/* zh.js — Chinese translation of question text, options and official explanations
   (LLM-translated for comprehension; the official German original / English translation
   remain authoritative). Plus theme/chapter names. */
window.__ZH = {"1.1.01-001":{"q":"防御性驾驶你应如何理解？","o":["不强求自己的权利","体谅他人的失误","在每个路口都预先停车"],"c":"防御性驾驶是指，一方面你在道路交通中不坚持主张自己的优先通行权，另一方面还要考虑到其他交通参与者可能犯的错误。因此，你并不必过度谨慎地驾驶——这本身反而可能带来危险并妨碍交通流。防御性驾驶意味着尽可能为来自自身或外部的危险做好准备，从而及时加以避免。例如，你可以在交通信号灯前足够早地制动，以避免追尾碰撞，就能做到这一点。总体而言，较慢行驶可以保护你不受那些在情急之下误判信号灯相位或左右不分的驾驶人的影响。"},"1.1.01-002":{"q":"追尾事故可能由哪些原因造成？","o":["突然的急刹车","注意力不集中","与前车距离过近"],"c":"有几种可能导致追尾碰撞的情形。如果某人过于突然且出乎意料地制动，就可能发生碰撞。跟车过近也是追尾碰撞的常见原因，尤其是当后车驾驶人分心、不专注时。足够大的安全距离有助于避免此类风险。"},"1.1.01-003":{"q":"下列哪项是“预见性驾驶”的良好范例？","o":["对道路交通状况可能发生的变化尽早作出反应","尽可能早地识别其他交通参与者的意图","尽量把对交通的观察限制在正前方的车辆上"],"c":"有预见性地驾驶对于道路安全至关重要。你应当始终留意正前方的车辆，以便必要时能立即做出反应。对周围的所有交通参与者也应如此。"},"1.1.01-004":{"q":"你将要驾驶一辆不熟悉的机动车。为何起初必须特别小心？","o":["因为对操纵装置的位置和功能不熟悉","因为对其制动特性不熟悉","因为对其操控灵活性不熟悉"],"c":"每位驾驶人都习惯了自己机动车的驾驶行为与特性。由于各自的车辆重心、尺寸和重量不同，每辆车的操控特性也各不相同。即便是同一车型，其离合器、过弯表现和制动距离也可能存在差异。驾驶人必须仔细熟悉这些特性以及各仪表的操作。"},"1.1.01-101":{"q":"你在城镇内道路行驶，前方车辆挂的是外地号牌。可能发生什么？","o":["该车可能突然刹车","该车可能在转弯前过晚开启转向灯","该车可能突然停车问路"],"c":"如果你从车牌号判断出某个交通参与者是外地人，就必须预料到他们因不熟悉当地而做出意外的操作。例如，该驾驶人可能停在畅行车道向路人问路。也有可能外地驾驶人较晚才认出正确路线，从而在弯道、路口和出口前较晚制动或打转向灯。"},"1.1.01-102":{"q":"哪些情况会造成不必要的阻碍？","o":["在车流密集处熄火","车辆无正当理由行驶过慢","机动车因燃油耗尽而抛锚"],"c":"发动机熄火是可避免的交通阻碍之一。这尤其是初学者的错误，最坏情况下可能导致追尾碰撞。不过，通过在偏僻道路上适当练习便可轻松克服。此外，根据道路交通法规，每辆车都必须及时加油以防熄火。最后，作为机动车驾驶人，以恰当速度行驶也是你的义务之一，即绝无正当理由地行驶得如此缓慢，以致妨碍交通并引发事故。"},"1.1.01-103":{"q":"为什么不得无正当理由地特别缓慢行驶？","o":["因为这会阻碍交通流","因为这会增加追尾事故的危险","因为这会促使后方驾驶人危险超车"],"c":"道路交通法规禁止不必要的慢速行驶，因为它妨碍交通流并大大增加事故风险：它会诱使后方交通参与者在视线不良处冒险超车。此外，由此产生的速度差会使追尾碰撞的风险急剧上升。"},"1.1.01-104":{"q":"哪些情况会构成危险？","o":["磨损的轮胎","调得过高的前照灯","颜色惹眼的车辆"],"c":"安全风险还包括调整不当的前照灯。如果调得过低，会造成驾驶人视野不佳。调得过高的灯光则可能使对向来车受到强烈眩目，引发严重事故。轮胎花纹深度是重要的安全因素。磨损的轮胎在湿滑路面上制动距离长得多。法定规定的1.6毫米花纹深度从安全角度看并不足够。在这样的花纹深度下，发生水上滑行的风险已非常高。一旦发生水上滑行，车辆会失控打滑。"},"1.1.01-107":{"q":"驾驶中如何判断自己开始疲劳？","o":["眼皮发沉","频繁打哈欠","反应时间变快"],"c":"疲劳会导致反应时间延长以及驾驶时注意力下降。其征兆包括频繁打哈欠。你也可以通过越来越难以睁开眼睛来识别睡眠不足。"},"1.1.01-108":{"q":"忽视疲劳迹象会发生什么？","o":["微睡眠（瞬间入睡）","注意力不集中","驾驶失误"],"c":"你绝不应忽视疲劳的最初征兆，例如注意力下降，因为由此你可能被微睡眠所侵袭。这往往又会导致严重的、有时甚至危及生命的驾驶错误。"},"1.1.01-109":{"q":"驾驶中开始感到疲劳时应怎么做？","o":["立即休息","下车到新鲜空气中活动","听提神的音乐"],"c":"由于疲劳在行车过程中可能导致危险情况，长途出行应规划充足的休息。在这一恢复阶段，建议到新鲜空气中散步，以让血液循环重新活跃起来。"},"1.1.01-110":{"q":"疲劳如何影响驾驶？","o":["降低警觉性","限制感知能力","延迟反应"],"c":"疲劳驾驶会增加事故风险，原因如下：注意力和专注力明显下降；感知受限，反应明显延迟。"},"1.1.01-111":{"q":"危险情况可能如何产生？","o":["因静止停放的车辆","因未保持适宜车速","因白天开启车灯"],"c":"道路交通中的一大危险原因是行驶过快。对初学者尤其如此，他们容易因此失去对车辆的控制。其他交通参与者往往没有预料到如此高的速度。但行驶过慢同样可能构成危险，因为此时冒险超车和追尾碰撞会更频繁。此外，停着的车辆也可能成为危险的障碍。为了让其他驾驶人更好地看见自己，白天也开启车灯会有所帮助。"},"1.1.01-112":{"q":"什么可能导致车辆驶离道路？","o":["分心","疏忽","疲劳"],"c":"驾驶人常因疏忽或注意力不集中而偏离道路。分心，例如打电话，也可能导致此类驾驶错误。第三种驶离道路的原因则是疲劳叠加微睡眠。"},"1.1.01-113":{"q":"严重事故的常见原因是什么？","o":["未注意其他交通","与前车距离过近","未相应调整车速"],"c":"严重后果往往由以下情形造成：因不必要的慢速行驶而引发的冒险超车和追尾碰撞，因疲劳和反应延迟，以及因儿童行为不可预测、鲁莽。"},"1.1.02-004":{"q":"接近儿童时应预料到什么？","o":["儿童突然鲁莽的行为","儿童快速而正确的反应","儿童规范的道路行为"],"c":"儿童总是会做出欠考虑的行为，因此在对其他交通参与者的信赖原则上享有豁免。所以，当儿童靠近你时，你必须减速，随时准备制动。"},"1.1.02-005":{"q":"在斑马线处必须预料到儿童有何行为？","o":["他们会不顾交通跑上斑马线","他们会在斑马线上无故转身往回跑","他们会因总能正确判断来车的速度和距离而在路缘等待"],"c":"儿童通常没有必要的训练来在道路交通中始终按规则行事。因此，完全可能他们不知道斑马线的含义，在车辆驶近时仍踏入道路，或在通过后又突然跑回来。"},"1.1.02-009-B":{"q":"你必须怎么做？","o":["立即大力刹车并保持随时制动","保持原速继续行驶，因为儿童肯定会停下来","保持原速行驶，以免阻碍后方交通"],"c":"如果一名儿童突然不顾交通横穿道路，你应立即减速并保持随时可制动的状态继续行驶。同时要留意是否还有其他儿童跟随。必须保持步行速度，以便必要时能完全停下。"},"1.1.02-022":{"q":"儿童在交通信号灯处等待时必须预料到什么？","o":["我行驶方向灯由绿变黄时他们就会开始跑","因为等得太久不耐烦，他们在红灯时也会开始跑","他们会互相推搡到车行道上"],"c":"由于缺乏生活经验以及教育不足，儿童并不总是按规则行事，例如在打闹中闯进车道。此外，你还必须预料到儿童会突然横穿道路，即使交通信号灯仍为红色，或者横向交通的灯刚刚切换。"},"1.1.02-023":{"q":"一群儿童在即将结束的自行车道上骑行。你必须预料到什么？","o":["他们会不注意地驶上车道","他们会过多地驶上车道","他们会下车并等待车道空出"],"c":"尤其是儿童，通常对交通规则并不太熟悉，容易做出不可预测的操作。因此，尤其在自行车道尽头，你应意识到这些年幼的交通参与者可能毫无预警地驶上道路。此外，儿童常常并排成组骑行，从而部分摆入你的车道。"},"1.1.02-024-B":{"q":"哪些说法正确？","o":["只要不阻碍乘客且确信无人受到危害，可以以步行速度从右侧通过","若无人受到阻碍或危害，可以高于步行速度从右侧通过","乘客上车前必须让行驶中的车辆先通过"],"c":"如果你不妨碍或危及上下车的乘客，可以以步行速度缓慢超越停靠的电车。需要注意的是，此时乘客拥有绝对优先权，无需让行驶中的车辆先行。必要时，作为机动车驾驶人你必须停下等待。"},"1.1.02-026-B":{"q":"在此情况下必须注意什么？","o":["在公交车仍在行驶时不得超车","在确信乘客不受危害的前提下，以步行速度通过停着的公交车","在公交车仍在行驶时超车"],"c":"如果公共汽车或校车开启了危险警示灯且仍在行驶，你不得超越它。如果该车已停靠在站台，你可以步行速度并保持适当距离驶过。这对于不危及上下车乘客是必要的。如果你在对向车道行驶，也必须减速或停车以确保乘客安全。"},"1.1.02-027":{"q":"使用助行器的老年人过马路时必须预料到什么？","o":["他们可能停在路上","他们可能转身返回","他们会缓慢地过马路"],"c":"当使用助行器的老年人横穿道路时，你有更高的注意义务。信赖原则被中止。你必须预料到这些人会突然停下或出乎意料地转身。老年人横穿道路所需的时间也相对较长。"},"1.1.02-028":{"q":"一位轮椅使用者沿车道行驶，尽管右侧有人行道。你该怎么做？","o":["跟随在轮椅后方，直到可以超越","超越时在侧面留出充足空间，因为轮椅可能摆出","鸣喇叭示意此人行为不当"],"c":"残疾人和老年人有时因身体限制而无法按适合交通的方式行事。因此，请特别小心，务必体谅。要预料到轮椅使用者会突然意外地转向，甚至更深入车道。在此类情况下，不允许鸣喇叭或以高速绕过该人。"},"1.1.02-029":{"q":"一位轮椅使用者过马路后无法上路缘进入人行道。你该怎么做？","o":["停车并开启危险警示灯","下车帮助这位轮椅使用者","鸣喇叭并从其旁边绕行"],"c":"你应当帮助这个人。为此，你可以停车并开启危险警示灯，以警示其他交通参与者可能的危险。在此情况下不允许鸣喇叭并绕过该人。这会使轮椅使用者受到惊吓和不安。"},"1.1.02-032":{"q":"谁有严重视力障碍？","o":["那位男子","那个孩子","那位女士"],"c":"对于具有以下标记的人，你必须预料到其有严重视力障碍：如果一个人佩戴有三颗黑点的黄色臂环和/或斜向前伸的白色盲杖。"},"1.1.02-036":{"q":"你该怎么做？","o":["停车","让那位男子过马路","与那位男子进行目光交流"],"c":"视力受损的行人常常佩戴臂环，并带有佩戴白色牵引挽具的导盲犬。无法与视力受损的交通参与者进行目光交流。因此，你有义务对此给予特别体谅。你必须停车，让行人安全地横穿道路。"},"1.1.02-037":{"q":"你必须注意什么？","o":["行人从公交车前方横穿马路","人们为了上公交车从左侧横穿到右侧","公交车会突然倒车"],"c":"在公共汽车或电车停靠的地方，你必须始终预料到人们会突然踏上道路。有些乘客为了赶上公共汽车而迅速横穿街道。乘客下车时，往往不注意交通就出乎意料地进入车道。由于倒车灯未亮，作为后方驾驶人你可以确定公共汽车会向前驶离车站。"},"1.1.02-038-M":{"q":"必须警惕哪些风险？","o":["他们会驶上车道","他们会继续在自行车道上行驶","他们会停下不动"],"c":"骑车人并不总是以适合交通的方式行事。这里，即使该儿童先前已向你左侧看过，也可能骑上车道。因此为避免危险情况，你应当减速并随时准备制动。"},"1.1.02-039-M":{"q":"你该如何行动？","o":["留意儿童","做好制动准备","保持原速继续行驶"],"c":"减速并密切注视这两名儿童。小心谨慎，随时准备制动。如果儿童的行为使然，就停车。"},"1.1.02-040-M":{"q":"必须注意什么？","o":["他们会向左转","他们会到路的另一侧","他们不会妨碍我通行"],"c":"骑车人始终有可能不按适合交通的方式行事。骑车人可能在不打手势示意的情况下左转或换到道路另一侧。如果有两名骑车人，可能第二个也会不打手势地跟随第一个。因此，即使骑车人继续直行，你也应随时准备制动。"},"1.1.02-041-M":{"q":"必须警惕哪些风险？","o":["儿童不会及时离开车道","部分儿童会再次转身","所有儿童都会在人行道上等待"],"c":"如果路上有一个球，可以推断会有一名儿童前来捡球。对你作为驾驶人而言这意味着：立即停车，以便儿童能安全地捡回球。对儿童，你必须预料到他们会违反交通规则行事，且无法正确评估危险。"},"1.1.02-042-M":{"q":"你该如何行动？","o":["减速至步行速度","保持随时制动","保持原速继续行驶"],"c":"这里的规则是：立即减速，随时准备制动，并缓慢驶过这一情况。可以推断，正在玩耍的儿童不会注意交通，也不会以适合交通的方式行事。"},"1.1.02-043-M":{"q":"你必须如何行动？","o":["立即减速至步行速度","保持随时制动","以原速驶过"],"c":"最有可能的是，会有一名儿童因追球而不顾交通跑进道路。立即将你的车减速至步行速度。特别警觉，随时准备制动！"},"1.1.02-046-M":{"q":"在此情况下，哪些车辆可以在确保乘客无危险的前提下仅以步行速度通过？","o":["与我同向行驶的车辆","对向来车"],"c":"当公共汽车在站台开启危险警示灯时，两个方向的所有车辆都必须以步行速度驶过该车。不得危及或妨碍上下车的乘客。"},"1.1.02-048-M":{"q":"现在你该怎么做？","o":["我减速至步行速度","我保持随时制动","我超越骑行者"],"c":"由于街道左右两侧都有儿童，你应制动至步行速度并保持随时可制动。"},"1.1.02-049":{"q":"在此情况下你该怎么做？","o":["我执行紧急制动","我鸣喇叭并继续行驶","我加速"],"c":"立即实施紧急制动，以避免与从左侧驶来的骑车人相撞。在此情况下继续行驶会很危险，即使你这一方向是绿灯。"},"1.1.02-050-M":{"q":"为什么在此必须缓慢行驶并随时准备制动？","o":["因为交通状况混乱不清","因为车行道上有一名儿童","因为白色厢式货车正在起步"],"c":"左侧厢式货车后面的儿童正朝车道跑去。你无法看出他是否会停下。因此，在这种不明确的交通情况下要特别专注和小心。缓慢行驶，随时准备制动。"},"1.1.02-051-M":{"q":"在此情况下正确的做法是什么？","o":["我停车让该人过马路","我从该人左侧驶过，并留出足够间距","我闪动前照灯示意该人我让行"],"c":"该男子佩戴黄色臂环，并带有导盲犬。他是盲人或视力受损者，无法看到交通状况。对盲人必须特别小心。因此，你必须让他从你车前横穿道路。"},"1.1.02-052":{"q":"为什么必须预料儿童在道路交通中行为难以预测？","o":["因为他们容易分心","因为他们往往无法完全把握交通状况","因为他们往往无法正确判断声音传来的方向"],"c":"儿童常常行为不可预测，因此其他交通参与者始终必须预料到意外。由于周围环境的外部刺激，幼儿不断从道路和交通上分心。他们的目光不断在周围游移，并停留在有趣的事件或物体上。对声音的感知也要在生命过程中逐渐发展，在儿童身上只有限地具备。因此，儿童通常无法将道路交通中的众多声音归到某个方向，他们更难仅凭听觉判断车辆从哪个方向驶来。\n除方向感知外，童年时期对距离、速度和制动距离的感知也尚未充分发育。因此，儿童往往只能不完整地观察交通状况。"},"1.1.02-107":{"q":"一名儿童牵着狗在人行道上走。这会造成危险情况吗？","o":["会，如果狗突然跑到车行道上并把儿童拖在后面","会，如果狗挣脱而儿童去追狗","不会，因为狗害怕交通"],"c":"这里可能出现危险情况。狗可能挣脱，儿童可能追着它跑。也可能出现狗跑上道路、儿童被一起拽着的情形。因此，你应当缓慢行驶，随时准备制动。"},"1.1.02-108-B":{"q":"在此情况下必须注意什么？","o":["只能以步行速度通过","只有在确信乘客不受危害时才可通过","在任何情况下都不得通过"],"c":"当公共交通车辆和校车停靠在站台且开启了危险警示灯时，适用以下规定：车辆只能以步行速度并保持足够距离驶过。这既适用于对向交通，也适用于与公交车同向行驶的车辆。作为车辆驾驶人，你必须排除对乘客的任何危险。"},"1.1.02-109-B":{"q":"在此情况下哪些说法正确？","o":["对向来车只要谨慎，可以通过这辆公交车","我只要谨慎，可以通过这辆公交车","由于我是对向来车，无需顾及这辆公交车"],"c":"两个方向驶来的车辆只能小心地驶过停靠在站台的公共汽车、校车和有轨电车。由于该公交车未开启危险警示灯，你不必将车速降至步行速度。在此情况下要特别专注！"},"1.1.02-110-B":{"q":"在此情况下哪些说法正确？","o":["可以在任一车道通过公交车，但车速不得超过步行速度","若乘客会因此受到危害，两个车道的车辆都必须停车","左侧车道的车辆可以不加特别注意地通过公交车"],"c":"如果一辆公交车停靠在站台且开启了危险警示灯，作为驾驶人你只能在同一车道上以步行速度驶过该车。保持足够距离。必要时你必须停车等待。其原因是必须始终确保公交车乘客的安全。这也适用于在同一车道上对向行驶的交通参与者。"},"1.1.02-112":{"q":"在居民区，一个球滚到你的车前。你必须如何反应？","o":["制动","继续行驶","避让以免撞到它"],"c":"如果在住宅区内一个球滚到你的车前，你必须预料到会有一名儿童突然跑进道路。因此你必须制动并随时准备停车，因为在这种情况下信赖原则不适用。"},"1.1.02-113":{"q":"你正接近在人行道上玩耍的儿童。你必须如何行动？","o":["减速并随时准备制动","为不阻碍后方交通而保持原样继续行驶","鸣喇叭并继续行驶"],"c":"在人行道上玩耍的儿童可能出乎意料地跑上车行道。因此信赖原则被中止。你必须减速，随时准备制动。"},"1.1.02-114":{"q":"在此情况下应预料到什么？","o":["狗会跑到车行道上，把儿童拖在后面","狗会挣脱，儿童会去追","狗会被儿童牢牢控制住"],"c":"在此情况下，你应当对以下危险做好准备：狗跑进车道并把儿童拖在后面，以及狗挣脱、儿童追着它跑。"},"1.1.02-115":{"q":"在此情况下，你必须缓慢行驶并随时准备制动吗？","o":["是，因为乘客可能从公交车前方横穿马路","是，因为并非下车的行人可能横穿马路","是，因为公交车会立即起步"],"c":"由于公交车停靠在站台并向右闪烁，你只能非常小心地驶过。此外，有一个人正站在公交车前方，因而就在你的近旁。你还必须预料到乘客会下车。其他人可能从道路另一侧走向公交车并想上车。因此，无论如何你都应当减速，以便必要时能立即制动。"},"1.1.02-116":{"q":"有轨电车刚刚在车站停稳。正确的做法是什么？","o":["不得使乘客受到危害","不得妨碍乘客","可以鸣喇叭警告乘客"],"c":"你可以小心地以步行速度驶过停靠的有轨电车——但前提是不危及或妨碍任何乘客。"},"1.1.02-117":{"q":"为什么在此必须稍停？","o":["因为有那名儿童","因为有那辆摩托车","因为有那辆越野车"],"c":"儿童会做什么并不明确。儿童有可能不顾交通地跑上道路。因此，你必须小心地通过此处：你应当非常缓慢地行驶，随时准备制动。"},"1.1.02-119":{"q":"你该怎么做？","o":["减速至步行速度","保持随时制动","保持原样继续行驶"],"c":"对道路交通中的儿童始终需要特别小心。在此情况下，你必须预料到这名幼儿会继续从厢式货车后面骑上道路。将车速降至步行速度，并始终保持警觉和随时可制动。如果你不确定儿童会如何行动，必要时就停车。仅仅鸣喇叭并继续行驶将是重大过失。"},"1.1.02-120-M":{"q":"你该怎么做？","o":["提前制动，向行人清楚地表明我让他们通过","继续行驶，即使行人短暂停步","绕开行人，以免阻碍后方交通"],"c":"行人在人行横道上始终拥有绝对优先权。因此，要及时且清晰可见地制动你的车辆。这样行人就能容易地看出你在履行让行义务，可以踏入车行道。即使行人仍站在路边，也绝对禁止径直驶过。"},"1.1.02-121-M":{"q":"你该怎么做？","o":["停车等待让行人过马路","继续行驶，因为行人到达我这一侧之前还有充足时间","继续行驶，因为行人只在路的左侧"],"c":"当行人在斑马线处等待横穿道路时，他们拥有优先权。这同样适用于他们位于道路左侧的情况。因此你应当及时制动。行人必须能够看出你在履行停车让行义务。即使行人先停下等待，你也必须以清晰可见的方式让他们先行。"},"1.1.02-122":{"q":"在此类车站应预料到哪些行为？","o":["行人会不注意地从电车车站岛走下","行人会跑过马路前往电车车站岛","行人会等到马路空出"],"c":"行人须在此类交通岛处等待。因此即使电车车门仍开着，你也允许驶过电车。但由于人们上下电车时常常疏忽大意，危险情况一再发生。例如，乘客不注意交通就径直横穿车行道去赶电车。"},"1.1.02-123-M":{"q":"你想右转。必须做好哪些准备？","o":["货车会停下","行人可能让货车先通过，然后在我前方横穿马路","货车转弯后，行人可能从马路对面过来"],"c":"如果你想右转，此处直行的交通参与者拥有优先权。他们可能是想横穿道路的行人或骑车人。如果一辆卡车在你前面右转，也有可能行人会让它先过。那样的话，卡车会挡住你望向道路另一侧、也就是从那里驶来的交通参与者的视线。"},"1.1.02-124-M":{"q":"必须做好哪些准备？","o":["有人横穿","视线受阻","车门突然打开"],"c":"在停放车辆很多的地方，你应当始终小心、体谅地驾驶。一方面，你的视线被停放的车辆遮挡。其次，你必须始终意识到车门可能被疏忽地打开。其他交通参与者也可能想从停放的车辆之间横穿车道。"},"1.1.02-125-M":{"q":"应预料到什么？","o":["成年人可能走上车道","儿童可能从车辆之间出现","可能需要大力制动"],"c":"右侧的“儿童”警告标志表明，此处需要格外注意和特别的谨慎。除儿童外，当然也可能有成年人突然从停放的车辆之间踏上这里的车行道，需要猛烈制动。"},"1.1.02-126":{"q":"为什么年长行人比年轻行人在道路交通中风险更高？","o":["他们往往视力和听力较差","他们往往反应较慢且行动不便","他们往往错误判断车辆速度"],"c":"年长的交通参与者视力较差、听力较差、反应更慢，并会误判车辆速度。要预料到这些人过晚地察觉危险，并过晚地反应或根本不反应。"},"1.1.02-127":{"q":"在交通量小的居民区必须注意什么？","o":["玩耍的儿童会跑到路上","骑行者会注意力不集中","所有成年人都会遵守交通法规"],"c":"在住宅区，车流稀少往往让儿童和成年人产生高度安全的感觉。这里有些交通参与者不加思索，常常导致不适合交通的行为。在此类区域，要始终预料到有玩耍的儿童、不专心的骑车人和突然进入道路的行人。要格外小心和专注地驾驶，因为尤其是儿童无法正确评估道路交通的危险。"},"1.1.02-128":{"q":"在行人横道处应预料到人们会有哪些行为？","o":["他们既不左看也不右看","他们会突然走上车道","有时他们走到一半又折返"],"c":"斑马线对行人具有保护功能。它赋予行人相对于其他交通参与者的优先权。有些行人不加思索地信赖这一保护，不注意交通便横穿车行道。在斑马线处要意识到，行人尤其是老年人或弱势者可能不左右观察就踏入车行道。也有可能当交通信号灯变红时，行人会半途折返。"},"1.1.02-129":{"q":"一位持白色盲杖的行人想在你前方过马路。你该怎么做？","o":["减速，必要时停车","发出警告信号","保持原速继续行驶"],"c":"白色盲杖向你表明，这位交通参与者是盲人或至少有严重视力障碍。盲杖也是该人获准在无人陪同情况下参与道路交通的标志。你必须始终对盲人和视力受损者给予更高的体谅。减速，必要时停车。不要鸣喇叭：你会使该人受到惊吓和不安。"},"1.1.02-130-M":{"q":"应预料到什么？","o":["行人会在我前方走上车道","儿童会突然从车辆之间出现","行人会等我驶过"],"c":"右侧的“儿童”警告标志提醒你格外小心。不过，在停放车辆很多的情况下，你必须始终设想会有人出乎意料地踏上人行道。当然，除儿童外，成年人也可能不按适合交通的方式行事，突然从车辆之间出现。"},"1.1.02-131":{"q":"应预料到什么？","o":["行人会突然走上车道","车门会被打开","车辆会开始移动"],"c":"在有多辆停放车辆和不同交通参与者的交通情况下，停放的车辆会妨碍你的视线。可以预料到行人会从汽车之间出现以横穿道路。也可能有人从车中下车，或车辆不注意当前交通状况就起步驶离。"},"1.1.02-132":{"q":"你对这一情况如何判断？","o":["那位女性行人可能不注意地走上车道","那位骑轻便摩托车的人可能突然改变方向","我可以保持原速继续行驶"],"c":"你只能以适当的安全距离、非常小心地驶过在路旁等待的行人。对于在道路右侧按规定推着轻便摩托车行走的骑车人也同样如此。必要时，你也可以换到左侧车道。"},"1.1.02-133":{"q":"路边一人佩戴有三个黑点的黄色臂章。该臂章表明什么？","o":["佩戴者有残疾","我有义务以特定方式对待此人","此人从事某种特定职业"],"c":"如果你在路旁看到一个人佩戴带有三颗黑点的黄色臂环，这对你而言意味着：信赖原则已被中止。你现在负有更高的注意义务。因为该臂环表明其存在严重视力障碍这一身体限制。视力受损者若佩戴此臂环和/或白色盲杖，则获准在无人陪同情况下在交通中活动。"},"1.1.02-134-M":{"q":"为什么在此必须减速？","o":["因为有那名儿童","因为有那辆摩托车","因为有那辆SUV"],"c":"如果一辆厢式货车停在房前，而一名儿童从房子里跑出，该儿童可能正好在厢式货车前方跑进道路。儿童很少注意交通。因此，你应当能够在紧急情况下立即制动。为此，你应当降低车速。"},"1.1.02-135":{"q":"行人横穿马路时应预料到什么？","o":["他们会注意力不集中","他们会突然停下","他们会走到一半又折返"],"c":"当行人横穿车行道时，并不能确定他会一直走到道路对面。也完全可能他会停下、转身或延迟继续行走。"},"1.1.02-136-M":{"q":"为什么现在必须缓慢行驶并随时准备制动？","o":["因为那名行人","因为公交车正在起步","因为那名骑行者"],"c":"你必须缓慢行驶并随时准备制动，因为乘客可能在公交车前方横穿道路。"},"1.1.02-137-M":{"q":"为什么在此必须制动？","o":["因为那名儿童","因为那名骑行者","因为那辆绿色车辆"],"c":"一名儿童在停放的车辆后面，很可能在下一刻横穿道路。"},"1.1.02-138-M":{"q":"现在正确的做法是什么？","o":["我减速","我做好紧急制动的准备","我保持原样继续行驶"],"c":"由于这只狗很可能会从左侧跑上街道，你必须减速并准备为应对危险而制动。"},"1.1.02-201-M":{"q":"为什么在此必须停车？","o":["因为一名行人想从左侧过马路","因为一名行人想从右侧过马路","因为一名骑行者想从左侧过马路"],"c":"你应当在此停车，因为公交车前方有2名行人想横穿道路。一个从右侧，一个从左侧。"},"1.1.02-202-M":{"q":"为什么现在必须制动？","o":["因为那名儿童","因为那辆绿色汽车","因为那名骑行者"],"c":"儿童随时可能跑上车行道。制动以避免事故。"},"1.1.03-001":{"q":"在哪里特别要预料到车行道上有污物因而有打滑危险？","o":["建筑工地附近","田间小路交汇处","市内交叉路口"],"c":"在土路交汇处和施工现场，车行道很可能被泥土、黏土和污物严重弄脏。从那里驶来的车辆会用轮胎花纹沟把污物带到路上。在潮湿条件下，这意味着打滑风险增大。"},"1.1.03-002":{"q":"为什么潮湿路面上的安全距离必须比干燥路面大得多？","o":["轮胎与路面之间的接触变差","车轮溅水会影响视线","制动距离更长"],"c":"在湿滑道路上，由于水膜的存在，轮胎与路面之间的附着力较差。因此制动距离明显变长。此外，前车溅起的水花会使能见度变差。雨天也是如此。"},"1.1.03-003":{"q":"在哪里特别要预料到路面结冰？","o":["桥上","穿越林区的路段","经常使用的路段"],"c":"在以下区域你必须预料到路面结冰增多：潮湿、背阴和有风、有利于路面结冰形成的地点。其中主要包括林间路段和桥梁。在树林中，寒冷比开阔田野持续更久。由于背阴，湿气在这里蒸发得更慢。在桥上，路面比地面储存的热量少。因此桥面更冷，结冰更快。周围水体的湿气以及因无遮挡的位置而增大的风也会促进结冰。"},"1.1.03-004":{"q":"寒冷季节在林荫大道上行驶有哪些特殊条件？","o":["湿树叶以及白霜、黑冰和积雪覆盖的路面尤其在拱形路面上特别危险","与其它路面相比，石板路面上白霜和黑冰出现得更频繁且更出乎意料","林荫大道在冬季特别安全，因为树冠保护路面免受积雪"],"c":"寒冷季节沿林荫道行驶的特殊性源于林荫道的基本特征：其特点是道路左右两侧有整齐平行排列的行道树。树木的枝叶在车行道上形成阴影。这使湿气保持更久，在寒冷天气中有利于结冰。如果树叶落在车行道上，也会显著增加车辆打滑的风险。"},"1.1.03-005":{"q":"路面上有油。现在你该怎么做？","o":["我通知消防队","我避免大力制动和急打方向","我向路左侧急转"],"c":"如果路面有油，避免猛打方向和猛烈制动；有打滑的风险。只要不危及其他交通参与者，你可以换到左侧车道。通知消防队，以便将油吸附处理。"},"1.1.03-006-M":{"q":"在此必须做好哪些准备？","o":["有车辆从右侧驶来","制动距离延长","车道变窄"],"c":"由于天气和相应的路面状况，你必须为延长的制动距离、为从右侧驶来的车辆（右先于左）以及为变窄的车道做好准备。"},"1.1.03-007-M":{"q":"你在暴雨后行驶。在此情况下应注意什么？","o":["我应与前车保持较大的安全距离","我难以察觉路面上的不平处","溅起的水可能影响我的视线"],"c":"下雨时，你的视野会变差。因此你应当加大与前车的安全距离，因为你的制动距离变长了。湿滑的路面会使前车卷起水雾。这意味着坑洼难以辨认。"},"1.1.03-102-B":{"q":"为什么在这段路上行驶要求驾驶人格外警觉？","o":["路面不平且附着力变化不定","对向可能有有轨电车驶来","在轨道上行驶有危险"],"c":"有轨电车可能沿轨道迎面驶来，此时车道对你而言变得窄得多。有轨电车轨道也很危险，尤其在潮湿时会变滑。此外，由于还有鹅卵石，路面不平整、抓地力不一。这会增大制动距离。"},"1.1.03-104":{"q":"路面有一小段结冰。在此应尽可能避免什么？","o":["加速","制动","转动方向盘"],"c":"在结冰的道路上，轮胎的抓地力不如平时。因此，你应当避免危险情况，即不要突然制动或加速。你还应避免突然的转向动作。这可能导致你的车辆打滑。只进行必要的制动和转向，并尽量避离结冰路面。"},"1.1.03-105":{"q":"驾驶中如何安全地检查路面是否结冰？","o":["以极低速度小心轻踩制动","向左向右猛打方向盘","迅速加速"],"c":"通过在低速下小心制动来测试路面状况。务必注意后方交通。避免猛打方向或急剧加速。这可能导致车辆侧滑失控。"},"1.1.03-108-B":{"q":"为什么在此必须特别谨慎驾驶？","o":["因为路面湿滑","因为弯道遮挡视线","因为违停的车辆使路面变窄"],"c":"积雪使路面湿滑。你前方有一个不易看清的弯道，那里停放着一辆车。你将不得不驶入对向车道绕过它。因此要格外小心驾驶，以便随时能够反应。此外，你的车辆需要合适的轮胎以获得良好的抓地力。"},"1.1.03-109":{"q":"在哪里必须做好遭遇突发浓雾的准备？","o":["河流附近","沼泽地区","湖泊附近"],"c":"低温下的湿度有利于雾的形成。因此，在湖泊、水道和河流周围以及沼泽地带更容易出现雾。"},"1.1.03-110":{"q":"浓雾使能见度急剧下降时你该怎么做？","o":["及时根据能见度调整车速","加大与前车的距离","紧跟前方车辆，以便以其尾灯作为方位参照"],"c":"根据能见度条件调整你的车速和驾驶方式。确保你能在可见距离内停下。必要时加大与前车的安全距离。例如，能见度为50米的雾意味着你最多只能以50公里/小时行驶。"},"1.1.03-112-M":{"q":"在此正确的做法是什么？","o":["我小心制动","我让右侧的行人过马路","我小心继续行驶，因为路面上看不到标线"],"c":"即使车道标线看不见，交通标志也表明此处有人行横道。小心制动，以防车辆打滑。"},"1.1.03-114-M":{"q":"为什么在此必须特别注意？","o":["因为道路走向不明确","因为路面不平","因为对向来车可能切弯"],"c":"你前方有一个长长的弯道，其尽头你看不到。可能有高速行驶的车辆从那里迎面驶来并切入你的车道。路面也不平整、表面不均。因此要预想着抓地力不足，并以相应的速度行驶。"},"1.1.03-115":{"q":"你想驶出高速公路；必须特别密切注意什么？","o":["那辆红色摩托车","那辆黄色货车","那辆白色厢式货车"],"c":"在视频中你看到一辆红色摩托车在减速车道上。之后它不再可见，因为它位于你右侧的盲区内。如果你此时也驶向减速车道，就会切到这名摩托车手——对他而言是危险情况。在变道前，请确保摩托车手已经驶过你身旁。"},"1.1.03-116":{"q":"为什么在此右转可能有危险？","o":["因为如果有行人横穿侧街，我可能无法及时停车","因为从侧街驶出的车辆可能开始打滑","因为如果我转弯过快，我的车可能开始打滑"],"c":"冬季天气使路面湿滑，并增大路口处的制动距离。你的车或对向来车可能失控打滑或滑走。因此要及时减速，不要猛制动。右侧道路仍满是积雪，因此更加湿滑。转弯时要留意行人。你转弯时他们始终拥有优先权。"},"1.1.03-117":{"q":"你在这条城镇外的道路上行驶。应做好哪些准备？","o":["行人使用该道路","道路狭窄","行人只在路外行走"],"c":"你会在右侧看到停车场的标志。要预料到行人从停放的车处走来或走向那里。由于大量积雪使人行道无法通行，避让的行人可能会使用车行道。天气造成湿滑状况并增大你的制动距离。缓慢行驶。"},"1.1.03-118":{"q":"必须注意什么？","o":["开启后雾灯","最高时速不超过50公里","最高时速不超过80公里"],"c":"这里的雾非常浓，你无法看到50米以外。视野如此受限时，若高速行驶便无法及时发现障碍物和危险情况。因此，你必须将车速降至最高50公里/小时，并非常小心地驾驶。开启你车辆的后雾灯。"},"1.1.03-119-M":{"q":"为什么必须与前车保持更大的安全距离？","o":["因为溅水否则会影响视线","因为制动距离比干燥路面长","因为路面不平处否则会被更晚察觉"],"c":"在湿滑道路上存在水上滑行的风险。制动距离比干燥路面更长。前车溅起的脏水雾会降低你的能见度。此外，你无法提前看到较大的水洼。为了能很好地应对危险情况，与前车保持更大的距离并调整车速。"},"1.1.03-120":{"q":"在此情况下正确的做法是什么？","o":["我减速","我避免急打方向","我在弯道内大力制动"],"c":"小心、缓慢地驾驶，避免猛打方向或猛制动，因为湿滑的积雪或冰随时可能出现。"},"1.1.03-121":{"q":"驾驶中突然下起大雨。你该怎么做？","o":["我减速","我避免强烈加速","我减小与前车的安全距离"],"c":"在暴雨中行驶时应格外小心。这包括调整车速、加大安全距离，以及避免猛烈加速，因为那会造成打滑风险。"},"1.1.04-001":{"q":"你从照明良好的道路转入无照明道路。必须注意什么？","o":["眼睛只能缓慢适应黑暗","障碍物比以前更难辨认","转入时眼睛已适应了黑暗"],"c":"瞳孔在明亮时收缩，在黑暗中放大。因此，刚从明亮道路转入黑暗道路后，你会更难看清那些在黑暗中本就难以看清的障碍物。视年龄不同，你的眼睛需要或多或少的时间来适应光照条件的变化。"},"1.1.04-103-B":{"q":"在此情况下被致眩时你必须怎么做？","o":["看向车道右边缘","必要时减速","加速以更快驶出光束"],"c":"如果你被远光灯或调整不当的前照灯眩目，不要看向光锥，而要看道路右边缘。为稳妥起见，减速，以便仍能及时为行人或骑车人制动。"},"1.1.04-107":{"q":"在此必须注意什么？","o":["你的车辆不会被及时看到","你只会在过晚时才发现对向来车","交通信号灯与彩色标志牌几乎难以区分"],"c":"众多的霓虹灯招牌会使人从交通、尤其是交通信号灯上分心。由于分心，其他交通参与者可能过晚地看到你，你也可能不能及时发现他们。这可能产生危险情况。其他交通参与者可能因为没认出或过晚才认出交通标志而行为不当。小心并以恰当速度驾驶。"},"1.1.04-108":{"q":"为什么沿这条道路行驶可能有危险？","o":["因为路上的行人容易被忽视","因为照明不良的车辆难以察觉","因为对向来车会到很晚才被发现"],"c":"如果你行驶在有照明但含有黑暗路段的车行道上，必须特别注意可能横穿道路的行人。上述黑暗路段中停放的车辆也常常不能及时被看到。因此要缓慢、小心地驾驶。而对向来车通常容易被发现。"},"1.1.04-109":{"q":"为什么驾驶人可能没注意到“让行”标志？","o":["因为连续照明使人以为在该路口享有先行权","因为道路布局造成这是干道的印象","因为停放的车辆部分遮挡了该交叉口"],"c":"即使更好的照明让你以为你相对于照明较差的交叉路口拥有优先权，你也必须遵守优先通行规定。这由路口的相应标志表明。这一点也不会因交叉区域停放的车辆而改变。所以三个答案都正确。"},"1.1.04-110":{"q":"驶入地下停车场时必须注意什么？","o":["我的眼睛需要适应照明条件的变化","行人常常走在车行道上","我的轮胎可能被狭窄的出入口损坏"],"c":"驶入地下停车场时，驾驶人受到从日光到内部中等照明的变化干扰。瞳孔对光照条件变化反应不够迅速，因此可能无法及时发现障碍物或行人。此外，出入口狭窄且容易让人迷惑。在地下停车场中要缓慢行驶、开近光灯，并始终随时准备制动。"},"1.1.04-111":{"q":"在这种能见度下你该怎么做？","o":["我减速","我靠向车道右边缘","我开启远光灯"],"c":"在能见度差的情况下，你必须首先减速。如果你被对向来车眩目，应当看向道路右侧，以免驶离道路。此时你不得开启远光灯。"},"1.1.05-001":{"q":"开快车常常在哪里导致事故？","o":["在交叉路口","在行人横道处","在弯道处"],"c":"超速是事故的主要原因之一。你开得越快，制动距离越长，对交通参与者做出反应的时间也越少。车速过高时，你可能被离心力甩出弯道。在湿滑路面上，高速行驶会失去附着力和对车辆的控制。"},"1.1.05-002":{"q":"开快车在哪里特别危险？","o":["在视线受阻的弯角","在道路变窄处","在平交道口"],"c":"在视线不良的弯道上，快速行驶尤其危险，因为突然出现的障碍物会被过晚发现。在道路变窄处高速也可能危险，因为不一定总有足够的制动距离。此外，不要低估在铁路平交道口因路面不平而打滑的风险。"},"1.1.05-003":{"q":"你如何通过急弯？","o":["在进入弯道前减速","只有当道路变直时才再次加速","只在到达弯道中点时才减速"],"c":"你应当在进入急弯前减速，并且只有在视野允许时、驶入直道后才重新加速。要注意，在弯道中猛制动可能导致车辆打滑。"},"1.1.05-103":{"q":"必须注意什么？","o":["行人可能横穿马路","我可以以步行速度驶过公交车","我不得驶过公交车"],"c":"你只能以步行速度并提高警惕驶过一辆开启危险警示灯、停靠在站台的公交车。乘客可能从公交车前方踏上道路，或匆忙赶车。他们常常不注意交通。"},"1.1.05-105":{"q":"在此情况下必须注意什么？","o":["我留意可能走上车道的人","我只能以步行速度通过公交车","我不得驶过公交车"],"c":"如果一辆公交车停靠在站台，你必须始终小心地接近。你必须停在公交车后方，只有在你确信不会危及任何人时，才允许以步行速度驶过。点亮的危险警示灯表明：该停靠点有危险。校车正是以此警示下车的儿童。他们可能突然从公交车前方出来横穿车道，或跑去赶车。"},"1.1.05-107-M":{"q":"在此必须注意什么？","o":["有车辆超速","交叉路口不会被注意到","儿童可能跑到路上"],"c":"你正在穿过一个住宅区。道路宽阔，诱使人快速行驶。但要小心：玩耍的儿童可能突然跳上道路。如果你开得太快，就无法及时反应和制动。你也可能忽略交叉路口或路口。在住宅区，常常适用“右先于左”：你必须让从右侧驶来的车辆先行。"},"1.1.06-002":{"q":"在交叉路口前不远处超载货车加拖车是不负责任的吗？","o":["是，因为货车加拖车会遮挡重要交通标志的视线","是，因为货车加拖车会遮挡交叉方向交通的视线","否，因为货车加拖车大多行驶缓慢"],"c":"在任何情况下你都不应在人行横道前开始超车操作。这会增大事故风险。这尤其适用于超越卡车。你可能看不到横向交通或交通标志。"},"1.1.06-005-M":{"q":"为什么现在不允许超车？","o":["因为那名骑行者可能向左转出","因为我看不到可能出现的对向交通","因为左侧路面状况非常差"],"c":"你不允许超车，因为骑车人可能转弯，同时对向来车不能被及时发现。"},"1.1.06-103":{"q":"哪些失误使超车即使在开阔笔直的道路上也很危险？","o":["高估了对向来车的距离","低估了自己的超车距离","高估了自己的超车距离"],"c":"即使在笔直开阔的道路上，超车操作也很危险。当对向来车驶近时尤其如此。对向来车的速度难以判断。超车操作的持续时间常常被低估。如果你用时过长，就可能对你自己和他人产生危险情况。在你开始超越另一辆车之前，要确保对向车道畅通且你能迅速完成超车。否则就等待。"},"1.1.06-104":{"q":"超车时何时会陷入危险？","o":["当被超车辆突然加速时","当被超车辆甩出超车时","当被超车辆大幅减速时"],"c":"如果你察觉后方车辆想要超越你，在任何情况下都不要提高自己的车速。这会延长超车操作并可能导致危险情况。在你开始超车之前，要确保后方车辆不打算超越你。否则他们就不得不猛烈制动。"},"1.1.06-105":{"q":"在哪些情况下必须放弃超车？","o":["当被超的交通参与者突然加速时","当来自意外对向交通有危险时","当被超的交通参与者大幅减速时"],"c":"突然出现的对向来车要求立即中止超车操作。如果被超车辆加速，也同样如此。这意味着你再也无法估算超车距离，若继续就会危及对向来车。如果被超车辆减速，则没有危险。"},"1.1.06-106":{"q":"何时禁止超车？","o":["当你无法明显快于被超交通参与者行驶时","当你看不清前方道路时","当交通状况不明确时"],"c":"如果你遇到不明确的交通情况，禁止超车。这尤其适用于：\n- 在弯道上\n- 在视线不良的路段上\n- 在优先通行关系不明确的路口之前及路口处\n- 当交通情况不明确时\n- 当你无法准确判断前车在做什么时。\n- 如果你的车辆不够快、超车会耗时过长时。\n超车前，要确保你不会危及其他交通参与者和对向来车。"},"1.1.06-111":{"q":"为什么即使在视野清晰、笔直的道路上超车也可能危险？","o":["对向交通比最初以为的更快","超车距离比最初以为的更长","对向交通比最初以为的更慢"],"c":"在笔直路段上，你可能能从远处看到对向来车，但往往低估其速度。如果超车操作耗时过长，就可能产生危险情况。如果有对向来车，最好等到道路畅通后再超车。"},"1.1.06-113":{"q":"在此情况下你该怎么做？","o":["我留在骑行者后方","我超越骑行者","我鸣喇叭，让骑行者让路"],"c":"你不得超越该骑车人：在任何情况下你都不得跨越中心实线，哪怕只是部分跨越。同样，你在此也不得鸣喇叭。"},"1.1.06-114":{"q":"你该怎么做？","o":["我中止超车","我迅速完成超车","我谨慎完成超车"],"c":"你正想开始超越该骑车人，这时蓝色汽车突然驶出停车位。显然它还没有注意到骑车人。骑车人此时可能不回头看就向左移动。立即中止超车操作，以免危及骑车人。"},"1.1.06-121-M":{"q":"在此情况下必须预料到什么？","o":["骑行者会从停放的车辆左侧驶过","对向来车","骑行者会下车让我通过"],"c":"你的车道被一辆停着的车辆挡住。你必须驶入对向车道绕过它。要特别注意对向来车。你前方的骑车人也会绕过这一障碍，并可能不打手势示意。"},"1.1.06-122":{"q":"如果你想超车，应预料到什么？","o":["骑行者不安全的骑行方式","停车距离延长","打滑的风险"],"c":"在积雪覆盖的道路上，制动和停车距离更长，打滑风险也增大。尤其是骑车人难以安全骑行。他们的摔倒风险显著增加。与骑车人保持更大的距离，也因为他的停车距离非常长。"},"1.1.06-123":{"q":"你想超车。应做好哪些准备？","o":["骑行者会突然停在我正前方","更前方的骑行者会向左甩出","对向来车会突然出现"],"c":"骑车人可能摇晃，因为单手骑行和货架上沉重的货物使他的自行车不稳。如果前面的骑车人转身，很可能会使他向左摆动，占据比平时更多的空间。你只能以至少两米的安全距离驶过这些骑车人。"},"1.1.06-124":{"q":"你想在狭窄道路上超越骑行者。道路宽度意味着骑行者和汽车之间最多只能有50厘米间距。你该怎么做？","o":["我放弃超车","我在超车前发出短促警告信号","我以中等速度超车"],"c":"为避免危险，作为机动车驾驶人，你在超越骑车人时必须始终保持至少1.50米的安全距离。如果无法以这样的距离驶过骑车人，在任何情况下你都不得超越他。"},"1.1.06-125":{"q":"你想超越骑行者。选择骑行者与汽车之间距离时应注意什么？","o":["骑行者的行为方式","我车辆的速度","骑行者与汽车之间1.0米总是足够的"],"c":"如果你想超越骑车人，在侧向距离方面必须注意以下内容：侧向距离至少为1.5米，如果骑车人的行为引人注意则要更大。其原因在于骑车人可能摇摆不定，也在于你的车辆在较高速度下可能产生的气流吸力效应。鸣喇叭以及以更小的侧向距离超车均被视为重大过失。"},"1.1.06-127-M":{"q":"正确的做法是什么？","o":["在弯道之后","在与货车并齐之前","在货车与弯道之间"],"c":"骑车人将超越卡车，并为此向外摆出。在弯道前超越他太危险，因为你可能还看不到对向来车。只有在弯道之后才超越该骑车人。一般规则是：只有当你看出整个超车过程中都不会危及或妨碍对向来车时，才允许超车。"},"1.1.06-128":{"q":"在哪些情况下禁止超车？","o":["无法在禁超路段开始前完成超车","无法在山顶前完成超车","无法保持必要的侧向间距"],"c":"此处禁止超车，因为在这些情况下你作为超车者会大大增加事故风险。"},"1.1.06-129-M":{"q":"你想超车。现在应做好哪些准备？","o":["我正前方的骑行者在车行道上停下","远处的骑行者向左转出","蓝色汽车超越我"],"c":"你正前方的骑车人想横穿到人行道上，为了越过路缘，该骑车人很可能会先停下。较远处的骑车人以手势表明他想进入左转车道。"},"1.1.06-130":{"q":"为什么在无遮挡的笔直道路上超车可能危险？","o":["高估对向来车的距离","低估对向来车的速度","低估自己的超车距离"],"c":"如果你误判对向来车的速度和距离，你的超车路程会比预期更长。这可能导致事故。"},"1.1.06-131-M":{"q":"现在正确的做法是什么？","o":["我减速","我向右驶上停车带","我保持当前车速"],"c":"超越你的车辆把超车路程估算得太短了。你应当减速，以便超车者能更早地重新并入，从而降低事故风险。"},"1.1.06-201-M":{"q":"为什么在此情况下不得超车？","o":["因为超车距离被遮挡","因为我只比骑行者稍快一点","因为有禁超标志"],"c":"由于骑车人和道路走向，超车路段看不清。如果你看不到超车路段，就不得超车。由于你无法比骑车人快很多，超车路程会变得长得多，因此也更危险。"},"1.1.06-202-M":{"q":"为什么现在不允许超车？","o":["因为那名骑行者可能向左转出","因为会阻碍对向交通","因为有禁超标志"],"c":"骑车人向左摆动并回头张望。他很可能要左转。减速，给骑车人足够的空间，并确保他不会感到有压力。这样你也能避免在突然制动以及因距离不足可能发生的追尾碰撞中危及骑车人。"},"1.1.07-001":{"q":"前方货车想右转驶入狭窄街道时，必须做好哪些准备？","o":["它会大幅减速","它会在转弯前向左甩出","它会尽量靠右"],"c":"与卡车保持较大距离，在任何情况下都不要从右侧超车，即使你作为两轮车驾驶人有机会这样做。这辆汽车列车必须先大幅减速才能转弯。出于空间考虑，卡车驾驶人可能不得不把牵引车远远地转向左侧，以免挂车或半挂车在转弯时压上路缘。"},"1.1.07-002":{"q":"在城镇内道路的交叉路口处必须特别记住什么？","o":["相交道路即使狭窄且建设较差，也可能享有先行权","建设较好的道路总是享有先行权","“右先于左”规则在所有交叉路口毫无例外地适用"],"c":"行驶在宽阔且修建良好的道路上，你并不自动拥有优先通行权。“右先于左”规则并非处处时时适用。相反，由标志或交通信号灯规定谁拥有优先权。因此，在每个路口和交叉处都要注意标志标明的优先通行规定或交通信号灯。"},"1.1.07-005-B":{"q":"必须做好哪些准备？","o":["有车辆从右侧出现","由于湿滑且覆有树叶的路面，制动距离更长","从右侧来的车辆尽管有先行权却会让行"],"c":"路上的湿树叶会显著增大你车辆的制动距离。相应地调整车速。还要记住，由于没有优先通行标志，“左让右”规则适用。你将必须让从右侧驶来的车辆先行，即使该驾驶人因天气而缓慢、犹豫地接近路口。"},"1.1.07-006-B":{"q":"为什么在此必须特别小心？","o":["因为制动时打滑的危险增加","因为可能有车辆从右侧驶来","因为从左侧来的汽车享有先行权"],"c":"路上的湿树叶导致制动距离更长并带来很高的打滑风险。因此，在到达路口前要减速并小心驾驶。可能有车辆从右侧驶来，你应当让它先行。由于该路口没有赋予你优先通行权的标志，此处的规则是“右先于左”。"},"1.1.07-008":{"q":"你想从一排停放的车辆中驶入行驶车流。你后方是一辆停放的货车加拖车。你如何评估这一情况？","o":["由于视线受限，你只有在来车非常近时才能看到它们","由于视线受限，从后方驶来的车辆很晚才能看到你的车","在此驶出是安全的，因为你受到后方货车加拖车的保护"],"c":"由于这辆卡车，你几乎看不到后方的交通。它也遮住了你车辆上对流动车流的视野。因此你必须特别小心，缓慢地在道路上试探前行。必要时你可能需要倒车以避开危险。"},"1.1.07-009":{"q":"你正接近一所学校。儿童正离开校园。必须预料到什么？","o":["他们不假思索地冲到路上","他们不注意地把自行车骑上车道","他们总是行为规范"],"c":"在学校附近，你必须始终准备好应对儿童突然横穿道路。儿童还无法很好地评估自己和他人，常常冲动且以不适合交通的方式反应。作为汽车驾驶人，你必须相应地调整驾驶方式，以排除对儿童的任何危险。除低速行驶外，你还必须特别专注并始终随时准备制动。"},"1.1.07-010":{"q":"危险警示灯提醒你注意什么？","o":["注意抛锚的车辆","注意正在上下儿童的校车","注意交通拥堵"],"c":"危险警示灯的使用有严格规定。你只能为保障抛锚的车辆安全，或为提示交通拥堵或校车，才可开启危险警示灯。开启危险警示灯的校车只能以步行速度超越。"},"1.1.07-011":{"q":"你前方一台大型联合收割机想右转。哪些说法正确？","o":["转弯时会向左大幅甩出","转弯前会大幅减速","由于后轮转向无法甩出"],"c":"由于转弯半径很窄，联合收割机需要向外摆出才能转弯。为此它会大幅减速。保持距离，也要缓慢行驶并准备制动。尤其对骑车人：绝不要从右侧超车！"},"1.1.07-013":{"q":"你跟在装载高货物的农用车辆及其拖车后方行驶。必须预料到什么？","o":["尤其在制动或转弯时，部分货物可能掉落","转向灯可能被遮挡，使人难以看出该车组何时想转出","由于载货，该车组的制动距离特别短"],"c":"如果你行驶在一辆载有重物的挂车的农用车后面，你必须预料到以下情况：转弯或制动时部分货物可能掉落到车行道上。转向灯可能被弄脏或被货物遮挡。车辆的制动距离因货物重量而增大。"},"1.1.07-014-M":{"q":"应预料到什么？","o":["行人横穿马路","有车辆驶过公交车","我将在该路口必须停车"],"c":"转弯时你必须预料到要在路口前停下。一方面，从右侧驶来的公交车被遮挡看不见。此外，其他车辆可能驶过它。而且行人也可能想横穿道路。你必须始终对他们给予特别体谅。"},"1.1.07-015-M":{"q":"在此情况下你该怎么做？","o":["减速","随时准备制动","保持原样继续行驶"],"c":"从出口驶出的车辆驾驶人无法看到横向交通。他必须有人引导才能汇入车流。他可能继续向前行驶，从而阻止你继续前行。你应当减速、随时准备制动，必要时甚至停车。"},"1.1.07-016":{"q":"为什么右转前必须等待？","o":["因为那名行人","因为那名骑行者","因为那辆厢式货车"],"c":"如果你想右转，你需要让所有与你相遇的车辆先行通过。这同样适用于与你同向行驶的自行车。同样，你必须让想在你前方横穿道路的行人先行。"},"1.1.07-017":{"q":"在此情况下应预料到什么？","o":["对方会驶出并越过道路中线","对方会制动且不越过道路中线","对方会不越过道路中线地超车"],"c":"由于对向来车被一辆自行车拖慢，你应当预料到该车会超越这辆自行车。如果发生这种情况，该车可能切入你的车道。如果驾驶人没有制动，你应当尽可能靠道路右侧行驶。同时也要准备制动，以便能对任何情况尽快做出反应。"},"1.1.07-019-M":{"q":"你想在路口右转。正确的做法是什么？","o":["我尽早变更车道","我不得妨碍自行车道上的骑行者","我只能以步行速度越过自行车道"],"c":"在你的车道与转弯车道之间有一条供骑车人使用的保护车道。它是车道的一部分，用虚线分隔。\n你只能为变道、避让或转弯而使用这条保护车道。如果你使用它，就不得妨碍骑车人，也不得在保护车道中停车。因此你应当尽早就变道。"},"1.1.07-020-M":{"q":"何时会在此产生危险情况？","o":["如果我保持原速继续行驶","如果骑行者变更到我的车道","如果骑行者在自行车道尽头停下"],"c":"你可以看到自行车道就在你前方结束。该骑车人本应停下来等待，直到她能安全地汇入流动的车流。然而，与其停下，不如预料到她会在你前方摆入车道。"},"1.1.07-021":{"q":"在此右转时必须注意什么？","o":["注意骑行者","注意对向交通","注意摩托车"],"c":"在你能够右转之前，你必须让位于你右侧自行车道上的骑车人先行通过。骑车人在与你同向行驶时拥有优先权。对向行驶的骑车人没有优先权。不过仍要留意他们，以避免危险。"},"1.1.07-022":{"q":"你该怎么做？","o":["我停车","我小心地从货车右侧驶过","我现在驶入中间车道"],"c":"由于你左侧盲区内有一辆车，而另一侧有一辆卡车想右转进入工地，你应当停车。不要行驶到中间车道。等卡车让出道路。然后你可以继续行驶。"},"1.1.07-023":{"q":"关于参与道路交通的电动自行车（e-bike）应注意什么？","o":["速度之快出人意料","看起来与传统自行车非常相似","由于发动机噪音容易识别"],"c":"电动自行车与普通自行车一样安静，因此常被很晚才察觉。然而它们往往能达到比无发动机自行车高得多的速度。许多交通参与者对此估计不足，因此危险情况可能出人意料地发生。总体而言，要预料到骑车人会提速并做出快速的操作。"},"1.1.07-025-M":{"q":"现在正确的做法是什么？","o":["我做好制动准备","我密切注视那名骑行者","我驶到道路左侧"],"c":"你应当随时准备制动并密切注视该骑车人，因为骑车人可能突然骑上道路。"},"1.1.07-101":{"q":"你想超越一辆后方伸出悬挂农具的农用拖拉机。必须记住什么？","o":["拖拉机转出时悬挂农具可能甩出","尾灯可能严重沾污或被遮挡，致使开启时方向信号难以看清或无法看清","农用拖拉机由于速度低总是可以安全超越"],"c":"当拖拉机想要转弯时，你始终应放弃超车操作。原因在于拖拉机转弯半径大，很可能会向外摆出，从而挡住道路。还要记住，这类车辆的转向灯并不总是可见的，而且由于农业用途可能被污物遮挡。"},"1.1.07-103-M":{"q":"在这道坡顶另一侧必须预料到什么？","o":["那里可能停着一辆车","我这一侧可能有对向来车","我这一侧可能有行驶缓慢的车辆"],"c":"由于坡顶的高度，无法看清坡后有什么。要预料到那里会遇到障碍物，例如抛锚或缓慢行驶的机动车。还要准备好应对占用你车道的对向卡车。为了能及时对此类危险做出反应，你应当相应减速。"},"1.1.07-105-B":{"q":"你该怎么做？","o":["制动并向右让","不做反应继续行驶，迫使货车退回右侧"],"c":"当一辆卡车在跨越实线超车时，你绝不要试图把卡车挤回它的车道。相反，要制动并尽量靠右行驶。"},"1.1.07-107-B":{"q":"在此情况下必须做好哪些准备？","o":["不平整且脏污的路面","车道上有工人和施工设备","警察指挥交通"],"c":"在施工区域你必须小心驾驶并减速。一方面，道路可能很脏。但也可能有工人在路上，或施工设备、施工车辆在路上妨碍交通。"},"1.1.07-109-B":{"q":"在此情况下必须做好哪些准备？","o":["制动距离会更长","公交车会立即起步","公交车驾驶人会让我通过"],"c":"由于天气和融雪泥浆，你必须预料到路面湿滑和制动距离更长。公交车对你拥有优先权，并通过打转向灯表明它想起步。小心减速，让它摆出。在任何情况下你都不得超越它。"},"1.1.07-111":{"q":"你在信号灯处等待并想右转。应记住什么？","o":["确认我右侧没有想直行的交通参与者","只需瞥一眼后视镜确认我后方没有骑行者","全神贯注于转弯，因为任何骑行者反正都得等待"],"c":"如果有其他交通参与者在你旁边，而你想直行，你必须让他们先行。所以也要注意自行车道和人行道上的行人。仅通过后视镜观察道路是不够的。此外，你还必须回头从肩上方向后看，以掌握周围情况，从而能察觉到那些藏于后视镜盲区中的交通参与者。"},"1.1.07-113":{"q":"你在穿越林区的新路上行驶。必须预料到什么？","o":["野生动物意外横穿车行道","因涉及野生动物的交通事故而造成的障碍","没有理由预期新路上会发生涉及野生动物的事故"],"c":"在森林地区新建道路时，这些道路常常穿过各种野生动物的自然栖息地。因此，它们的惯常路径可能横穿你的车行道。基于此，在森林道路上你必须预料到野生动物横穿以及因频繁发生野生动物事故而产生的障碍。"},"1.1.07-114":{"q":"几只鹿在你车前跑过马路。必须预料到什么？","o":["可能有掉队的鹿跟在鹿群后","鹿群可能返回并再次横穿马路","没有理由预期还会有动物"],"c":"如果在你车前有几只鹿逃窜穿过道路，你必须预料到以下情况：可能还有几只动物跟随。整群鹿也可能转向相反方向，再次换到车行道的另一侧。"},"1.1.07-117":{"q":"一天中何时必须预料到野生动物横穿增多？","o":["黄昏","黎明","正午"],"c":"在清晨和傍晚的昏暗中要预料到更多的鹿横穿。这一昼夜之间的过渡时段以漫射的光线条件为特征。"},"1.1.07-118":{"q":"在农村地区首先必须预料到哪些危险？","o":["脏污的路面","行驶缓慢的农用车辆","过宽的农用车辆"],"c":"在从事农业的地方，拖拉机和其他农用车辆以低速行驶和/或超宽行驶。车行道也常常被泥土或粪肥弄脏。"},"1.1.07-119":{"q":"一台农用拖拉机在黎明时开着前照灯向你驶来。必须预料到什么？","o":["拖拉机可能携带难以看清的大型作业设备","尽管开着前照灯，也并非总能辨别拖拉机的宽度","拖拉机后面可以挂2辆宽拖车"],"c":"在农用车辆上，灯光有时会损坏。它们也可能被污物或篷布遮盖。车辆的宽度不易判断。此外，这些车辆最多可带两辆挂车。"},"1.1.07-120":{"q":"进入隧道时必须遵守什么？","o":["即使在照明良好的隧道内，白天也要开近光灯行驶","摘下太阳镜","开启雾灯"],"c":"在驶入隧道前，你必须注意以下事项：隧道内有开灯义务。因此开启近光灯，以便看得更清并被更好地看见。如果你戴太阳镜，请摘下。在隧道内你不得开启雾灯。"},"1.1.07-121":{"q":"隧道内发生交通拥堵时你必须怎么做？","o":["开启危险警示灯","车流停止时，与前车保持约5米的安全距离","立即固定车辆并离开"],"c":"如果隧道内发生交通拥堵，停车并关闭发动机。通过保持约五米的安全距离，你可以降低中毒风险、保留避让余地，并让救援车辆通过。开启危险警示灯以警示后方驾驶人。只有在相应的扩音广播之后才离开你的车辆。"},"1.1.07-122":{"q":"驶过隧道时什么会影响你的注意力？","o":["对向来车灯光的反射","隧道的长度","良好的道路标线"],"c":"在通过隧道时，以下因素可能干扰你的注意力：缺乏视觉刺激和速度的单调，以及对向来车的灯光。此时，以道路右侧作为参照会有所帮助；避免直视对向来车的灯光。"},"1.1.07-123":{"q":"驶过隧道时特别必须遵守什么？","o":["你可能被很大的噪音分散注意力","注意诸如紧急出口和紧急电话等安全设施的标志","你可能被灯光效果分散注意力"],"c":"由于隧道墙壁的反射，隧道内的行驶噪音明显更大。你还能听到通风系统的噪音。这对你作为驾驶人产生烦躁作用。你的眼睛首先要适应不同的可见度条件。对向来车增强的光反射使情况更困难。紧急疏散标志也会使人分心。"},"1.1.07-125":{"q":"在隧道内必须遵守哪些基本行为准则？","o":["即使在照明良好的隧道内，白天也要开近光灯行驶","不得掉头","听从隧道工作人员的指示和信息"],"c":"在所有隧道内以下行为规则都是强制性的：整段路程内不允许掉头。无论照明情况如何，都必须始终开启近光灯。必须始终遵守隧道工作人员的指示。对人的保护优先于对车辆及其财产的保护。"},"1.1.07-132":{"q":"为什么在此必须停车？","o":["因为那辆厢式货车","因为那名行人","因为那名骑行者"],"c":"你想左转。一辆从对向车道驶来的厢式货车也想转入这条道路。该车拥有优先权。同样，你必须注意想横穿这条街的行人。"},"1.1.07-136":{"q":"现在你该怎么做？","o":["减速并随时准备制动","保持原样继续行驶","向左急转"],"c":"在你前方转弯的车辆亮起白色倒车灯，表明它很可能要倒车回到原来的车道。由于你无法判断该驾驶人是否注意到了你，你应当降低车速并随时准备制动。由于有对向来车，避免做避让操作。"},"1.1.07-137":{"q":"你想右转。你该怎么做？","o":["让骑行者通过该路口","扭头越过肩膀察看以确认无车","抢在骑行者之前转弯"],"c":"在你能够转弯之前，你必须通过后视镜检查道路是否畅通。也建议回头从肩上方向后看：这是察知位于后视镜盲区中危险情况的唯一途径。要记住，那些你横穿其路径的其他交通参与者——骑车人或行人——始终拥有优先权。"},"1.1.07-138":{"q":"应预料到什么？","o":["摩托车可能向左甩出","厢式货车旁的人可能进一步侵入道路","行人可能从厢式货车前方横穿马路"],"c":"其他交通参与者可能以所描述的各种不同情形对此情况做出反应。它们都同样危险。因此需要极其小心并缓慢行驶。"},"1.1.07-139":{"q":"摩托车前方有一辆汽车想在道路上倒车。应预料到什么？","o":["该汽车继续倒车","摩托车会突然制动","我的制动距离会比平时更长"],"c":"汽车驾驶人常常低估驶近的摩托车手的速度；这里这位驾驶人在驶出停车位时也是如此。摩托车手可选的动作——制动或避让——在积雪湿滑的路面上对他而言都很危险。他可能摔倒。还要考虑到这种天气下更长的制动距离。"},"1.1.07-140":{"q":"你沿主干道快速行驶，在前方不远处看到一只鹿靠近车行道。你该怎么做？","o":["减速","随时准备制动","执行紧急制动"],"c":"如果鹿还没有在路上，在任何情况下你都不应实施紧急制动。这会不必要地危及其他交通参与者，并迫使他们做出不可预测的反应。不过，你应当降低车速并保持随时可制动：动物可能毫无预警地跑上道路。"},"1.1.07-141":{"q":"如果你骑两轮车，为什么风险特别高？","o":["因为容易被忽视","因为我的速度可能被低估","因为一旦发生事故受伤风险更大"],"c":"尤其是在雾、黑暗等能见度受限的情况下，两轮车驾驶人较小的轮廓使他们很晚才被发现，或根本不被发现。此外，其小巧的外形使速度难以估算。一旦发生碰撞，两轮车通常比大多数其他机动车提供的保护更少。"},"1.1.07-142":{"q":"在多车道的繁忙道路上行驶，你已变入左转车道。现在你不想左转而想右转。你该怎么做？","o":["我左转","我开启危险警示灯倒车","我以大弯转向右转"],"c":"由于车流量大，变道或右转可能危及其他交通参与者。因此你必须左转并绕一小段路。要留意禁止你变道的车道标线。"},"1.1.07-143":{"q":"我的路线中有一段隧道。我应了解什么？","o":["我应了解如果无法继续行驶如何停放并离开车辆","我应了解隧道内逃生路线如何标示","我可以确信发生紧急情况时救援会及时到达"],"c":"如果你的路线中有隧道，你应当了解相应的交通标志以及抛锚或事故时的行为措施：在这种情况下，通知隧道监控中心并沿最近的逃生路线撤离。首先关闭你车辆的发动机，并把点火钥匙留在锁中，以供救援作业使用。"},"1.1.07-144":{"q":"驶过隧道时你发现车内有火情。你无法驶出隧道。你该怎么做？","o":["开启危险警示系统","关闭发动机","把钥匙留在点火开关中"],"c":"如果你车辆中的火灾使你无法驶出隧道：将车辆不上锁停放，关闭发动机，并把点火钥匙留在锁中。报警通知隧道监控中心。步行沿最近的逃生路线撤离。"},"1.1.07-145":{"q":"在隧道中行驶时因火情你被迫停车。现在你该怎么做？","o":["我在紧急呼叫点触发火警","我尽力灭火","我锁上车门"],"c":"如果由于火灾你不得不把车辆停在隧道内，你应当：关闭发动机，把钥匙留在点火开关中，并在紧急呼叫站迅速触发火警。尽快沿最近的逃生路线离开隧道。"},"1.1.07-146":{"q":"应预料到什么？","o":["对方会甩出得更多","对方会突然停下","对方会停在右侧车道上不动"],"c":"你看到卡车想在你前方转弯。该车遮挡了对交通的视线，因此你需要调整车速。卡车很可能会向外摆出以完成转弯。它可能突然停下，让行人或其他交通参与者通过。"},"1.1.07-147":{"q":"现在必须注意什么？","o":["注意前方道路上的车辆","注意那辆自行车","注意那辆摩托车"],"c":"你想右转，你前方的汽车驾驶人也想右转。你要转入的横向街道的行人信号灯显示绿色，行人拥有优先权。你前方的汽车有可能很快就停下，让行人通过。在右侧你还能看到一名骑车人。该骑车人可能从右侧驶过你的车辆，并从左侧绕过你正在转弯的车辆。要避免这一危险。"},"1.1.07-148":{"q":"为什么在此必须停车？","o":["因为那名骑行者","因为那辆绿色汽车","因为那名行人"],"c":"必须让该骑车人先行，因为她处于优先通行的道路上。等到该骑车人驶过这些车辆并通过为止。"},"1.1.07-149":{"q":"为什么在此必须停车？","o":["因为那辆红色汽车","因为那名骑行者","因为那名行人"],"c":"主干道上的交通拥堵。红色汽车绕过停放的车辆以左转。你必须等待并让这辆车通过，因为它拥有优先权。"},"1.1.07-150":{"q":"现在正确的做法是什么？","o":["我紧握方向盘并保持指向正前方","我向左急转","我向右急转"],"c":"当动物从右侧走上道路时，避让操作是一种自然的反射。然而，这可能比保持行驶方向带来更严重的后果。向右避让可能导致冲入路旁沟渠，向左避让可能导致与对向来车相撞。最安全的做法是继续直行。"},"1.1.07-151":{"q":"现在你该怎么做？","o":["我执行紧急制动","我鸣喇叭","我向左急转"],"c":"你看到动物正要跑上道路。鸣喇叭可能有助于使它停下。此外，你应当实施紧急制动，以减轻可能的碰撞。不要避让！避让更容易导致造成人身伤害的事故，甚于与动物相撞。"},"1.1.07-152-M":{"q":"交通信号灯变绿时必须留意什么？","o":["注意那名行人","注意那辆摩托车","注意对向交通"],"c":"当你在红灯前等待时，一名摩托车手从等待的车辆旁挤过。当信号灯转为绿色时，你应当注意这名摩托车手，在他做出冒险的超车操作之前让他先行。但你也应当让那名行人横穿道路，尽管已经绿灯，他仍在路上。"},"1.1.07-153-M":{"q":"在此情况下必须做好哪些准备？","o":["对向交通会出现","货车驾驶人会跳到车行道上","交通标志被货车遮挡"],"c":"卡车挡住了你的视线。因此你既看不到对向来车，也看不到卡车后面的交通标志。低速接近该车。注意对向来车（它们拥有优先权），并绕行时与打开的车门保持距离。卡车驾驶人可能突然下车并跳到路上。"},"1.1.07-154":{"q":"驶过隧道时你该怎么做？","o":["在有对向交通的隧道内，我靠向车道右边缘","我记住诸如紧急出口和紧急电话等安全设施","我以较小的跟车距离行驶，以便用前车尾灯作为引导"],"c":"在通过隧道行驶时，按以下方式操作：务必注意安全距离，并以道路右侧为参照，以避免对向来车的眩光。了解各安全设施，以便知道最近的紧急出口和紧急电话在哪里。"},"1.1.07-155-M":{"q":"现在必须注意什么？","o":["注意左侧的骑行者","注意右侧的骑行者","注意那辆绿色汽车"],"c":"你打算左转。两名骑车人与你同向行驶。你必须特别注意他们，因为他们也可能毫无预告地转入这条街。"},"1.1.07-156-M":{"q":"现在你该怎么做？","o":["我执行紧急制动","我保持方向盘正直并握紧","我向左转向"],"c":"由于那只狗（从右侧）似乎正走进街道，请实施紧急制动，并保持方向盘正直、稳定。"},"1.1.07-157-M":{"q":"在此情况下应为哪些情况做准备？","o":["公交车起步时会甩到我这一侧道路","人们会在公交车尾部横穿马路","那辆四轮摩托车突然开始移动"],"c":"请准备好应对公交车后面的人进入车道，以及公交车摆出并短暂驶入你的车道。"},"1.1.07-158":{"q":"必须预料到骑行者有何种行为？","o":["在双向通行道上逆向行驶","在自行车道的错误一侧行驶","天黑时不开车灯"],"c":"三个答案都正确。骑车人会双向使用单行道，他们可能在黑暗中不开灯，或者可能在自行车道的错误一侧骑行。"},"1.1.07-159-M":{"q":"在此必须做好哪些准备？","o":["有人在道路上行走","对向来车左转","有车辆转入该道路"],"c":"该交通标志表示一个供徒步者使用的停车区，这意味着人们可以横穿车行道，车辆也可以随时驶离或驶入该停车区。"},"1.1.07-160-M":{"q":"为什么现在必须停车？","o":["因为那名骑行者","因为交通状况混乱不清","因为那辆黄色货车"],"c":"由于你无法完整地看到交通状况且必须让骑车人先行，你必须停车并小心地试探驶入。"},"1.1.07-161-M":{"q":"你想继续直行。在此情况下正确的做法是什么？","o":["我让那辆红色车辆转弯","我让那辆电动滑板车穿过马路","我第一个通过该路口"],"c":"你首先来自一条优先通行道路。由于没有其他交通标志，适用右先于左。红色汽车在你的右侧行驶，因此拥有优先通行权。\n电动滑板车没有优先通行权，所以为避免事故，你无论如何都应当让它通过。"},"1.1.07-162-M":{"q":"我想重新驶入道路。对这一情况正确的判断是什么？","o":["驾驶人很晚才能看到我","我很晚才能看到车辆","驾驶人在我重新驶入时给我优先权"],"c":"由于停在你后方的车辆非常大，你只能很晚才看到从后方驶来的车辆，而你自己也只能很晚才被其他驾驶人注意到。"},"1.1.07-163":{"q":"为什么继续驶过这个事故现场有危险？","o":["因为可能发生二次事故","因为可能忽视行人","因为交通运行状况不明确"],"c":"交通情况不明确，必须预料到围观者突然制动以及行人横穿道路。"},"1.1.07-164-M":{"q":"在此右转时必须注意什么？","o":["注意那名骑行者","注意对向交通","注意那辆摩托车"],"c":"该骑车人拥有优先通行权。右转时，你必须始终注意是否有行人或骑车人正在驶近。他们可以在你前方横穿街道。使用后视镜，并回头从肩上方向后看，以便能看到盲区。"},"1.1.07-165-M":{"q":"现在正确的做法是什么？","o":["我执行紧急停车","我快速通过该路口","我轻踩制动"],"c":"这辆滑板车似乎没有看到你驶来，并径直抢先通行。为避免事故，你必须立即实施紧急制动。"},"1.1.07-166-M":{"q":"在此情况下必须预料到什么？","o":["骑行者会向左转出","对向来车","骑行者会下车让我通过"],"c":"由于障碍物在你这一侧，在这种情况下你必须等待。此外，骑车人将超越停放的车，因此会向左摆出。"},"1.1.07-167":{"q":"你正驶过隧道。这里有哪些特殊之处？","o":["我可能被很大的车辆噪音分散注意力","诸如紧急出口和紧急电话等安全装置都有标志","我可能被灯光效果分散注意力"],"c":"在隧道内，紧急出口和SOS紧急电话都有清晰的标志并点亮。紧急情况下，你应当使用这些设施。隧道内不同的照明、其他交通参与者的灯光以及响得多的噪音都可能轻易使你分心。"},"1.1.07-168-M":{"q":"现在正确的做法是什么？","o":["我制动","我向左甩出","我加速，因为我有先行权"],"c":"那辆仍停着的车辆想驶入道路，并且显然忽略了你。你应当减速以避免事故。"},"1.1.07-169-M":{"q":"现在应预料到什么？","o":["那辆黄色车辆的驾驶人打开驾驶侧车门","那辆蓝色货车向左转出","那名骑行者向左转出"],"c":"那辆[黄色]车辆将停下，因此你必须准备好应对驾驶人打开车门。该骑车人很可能会向左移动以超越黄色车辆。你还必须预料到卡车会起步驶离。"},"1.1.07-170":{"q":"你行驶在已报告发生交通拥堵的路段上。正确的做法是什么？","o":["我继续关注交通播报","我在弯道处和接近坡顶时特别小心行驶","我使用紧急制动辅助以在拥堵尾部前安全停车"],"c":"在弯道上和坡顶前你应格外专注，因为交通情况难以看清。你还应继续关注交通广播的路况报道。"},"1.1.07-171":{"q":"为什么现在必须停车？","o":["因为那名骑行者","因为那些行人","因为那辆货车"],"c":"“让行”标志与附加的自行车标志组合向你表明，你必须注意可能的骑车人并让他们先行。因此，你现在必须停车并让骑车人通过。"},"1.1.07-172-M":{"q":"在此情况下正确的做法是什么？","o":["我执行紧急制动","我继续行驶并随时准备制动","我加速"],"c":"如果一名骑车人突然从左侧驶来，你必须紧急停车。"},"1.1.07-173":{"q":"驾驶中一只鹿在你车前横穿马路。应注意什么？","o":["可能有其他动物跟随这只鹿","鹿可能停在道路中央","我可以开启远光灯把鹿吓跑"],"c":"鹿非常不可预测，也许它会跑回森林，也许它会停在街道中间。因此你应当减速并关注事态发展，因为其他动物也可能踏上道路。"},"1.1.07-174-M":{"q":"正确的做法是什么？","o":["我继续制动","我暂时留在我的车道内等待","我现在向左转向"],"c":"由于你前方的卡车正在倒车停放，你必须继续减速。只有当左侧车道空闲时你才可以变道。暂时留在你的车道中并继续制动。"},"1.1.07-175-M":{"q":"在此情况下应预料到什么？","o":["那辆黄色汽车会左转","我将必须让出我的优先通行权","那名行人会横穿马路"],"c":"你行驶在一条转向的优先通行道路上。任何离开优先通行道路的人都必须让继续沿优先通行道路行驶的车辆先行。\n黄色汽车打转向灯并左转。尽管它没有优先通行权，但以其高速它无法在不闯入你车道的情况下停下。因此你应当制动并放弃你的优先通行权，以避免碰撞。避免事故的义务优先于所有优先通行规则。"},"1.1.07-176-M":{"q":"现在正确的行为是什么？","o":["我制动","我向左甩出","我平稳地继续行驶"],"c":"在左侧后视镜中你可以看到，后方有一辆车正要超车。与此同时，你右前方骑自行车的人可能移动到道路上。还有一辆卡车在对向车道上朝你驶来。这三个因素共同导致车行道变窄，从而增大事故风险。\n在这种情况下你必须制动，以避免与超车的汽车和骑车人相撞。"},"1.1.07-201-M":{"q":"在此情况下正确的做法是什么？","o":["我非常猛烈地制动","我鸣喇叭并继续行驶","我向右转向"],"c":"从左侧驶来的骑车人似乎没有减速，因此要猛烈制动。"},"1.1.07-202-M":{"q":"为什么现在必须制动？","o":["因为那名骑行者","因为那辆红色车辆","因为公交车站"],"c":"由于该骑车人想进入你的车道，为这名骑车人而制动。"},"1.1.07-203-M":{"q":"现在必须注意什么？","o":["注意左侧的骑行者","注意右侧的骑行者","注意那辆蓝色汽车"],"c":"右侧的骑车人正在车行道上骑行。左侧还有一名骑车人，由于我们要转弯，必须先让他通过。"},"1.1.07-204-M":{"q":"在此情况下应预料到什么？","o":["那辆黄色汽车的驾驶人没有看到我","车行道上有散落的碎石","我前方的拖拉机将右转"],"c":"由于你行驶在一辆大型车辆后面，很容易被对向来车忽视。该警告标志提示路上有滚落的碎石。"},"1.1.07-205-M":{"q":"你在城镇外行驶。在此情况下正确的做法是什么？","o":["只有在确认道路安全后我才继续行驶","我无需确认道路安全，因为骑行者正在移动","我不再可以继续使用自行车道"],"c":"这不是一条受保护的自行车道。因此你可以继续使用这条自行车道。\n在驶入另一条道路时，你必须确保道路畅通。这里有一个“让行”标志。这意味着道路另一侧的骑车人拥有优先通行权，你必须等待。你应当自行确认道路畅通。\n对于横穿，你仍必须确保道路畅通。"},"1.1.07-206-M":{"q":"为什么现在应当做好制动准备？","o":["因为那辆棕色车辆的驾驶人可能下车","因为那名行人可能走上车道","因为公交车可能驶入我的车道"],"c":"那辆棕色车辆刚刚停下，下一刻很可能有人匆忙而不加小心地下车。因此，你必须随时准备制动。"},"1.1.07-207-M":{"q":"在此情况下正确的做法是什么？","o":["我执行紧急制动","我继续行驶并随时准备制动","我向右让出"],"c":"该骑车人显然没有注意交通状况、也没有制动就横穿道路。采用紧急制动以避免碰撞。"},"1.1.09-001":{"q":"一位驾驶人饮酒过量因此不得驾驶。为什么他不可能在短时间内恢复驾驶能力？","o":["通过睡半小时","通过喝两杯浓咖啡","通过散步半小时"],"c":"大量饮酒后，没有快速恢复驾驶能力的办法。睡觉或散步都不够。喝浓咖啡也不会改变血液中的酒精浓度。身体每小时只能分解约0.1‰的酒精。"},"1.1.09-003":{"q":"哪些物质会以类似酒精的方式损害驾驶能力？","o":["某些药物和麻醉品","一杯咖啡","一杯茶"],"c":"尤其是毒品会改变感知，并损害快速、恰当反应的能力。因此，任何形式的吸毒都会使你丧失驾驶能力。甚至某些药物也会损害你的驾驶能力。如果医生给你开了药，请注意说明书中的指示。"},"1.1.09-004":{"q":"什么会损害驾驶能力？","o":["疲劳","酒精和其他麻醉品","某些药物"],"c":"任何对感觉器官产生负面影响的东西都可能降低驾驶能力。除毒品外，这也包括药物，因此服用前应阅读说明书。血液酒精浓度达到0.3‰时，你就已经丧失驾驶能力。疲劳是最常见的事故原因之一。此时你的注意力和专注力会消失，这可能导致所谓的微睡眠。"},"1.1.09-006":{"q":"一般来说，1.0‰（100毫克/100毫升）的血液酒精浓度需要多长时间才能从血液中清除？","o":["10小时","5小时","1小时"],"c":"经验法则是：每小时分解0.1‰。10小时后，1.0‰完全分解。"},"1.1.09-007":{"q":"什么会增强酒精的致醉作用？","o":["安眠药、止痛药或镇静剂","空腹饮酒","一口喝下含酒精饮料"],"c":"药物的作用会增强酒精的效果。尤其是大量酒精与安眠药、止痛药或镇静剂结合时，可能危及生命。如果你空腹饮酒或在短时间内大量饮酒，酒精会立即进入血液：你会突然酩酊大醉。"},"1.1.09-008":{"q":"即使少量酒精也可能产生哪些影响？","o":["反应延迟","鲁莽驾驶","听力和视力受损"],"c":"即使少量酒精也会影响你的中枢神经系统并损害你的感知：你的听觉和视觉、你的反应和执行能力、你的平衡感。你冒险的意愿增强，你不再察觉危险。你自以为适合上路，即使事实并非如此。"},"1.1.09-009":{"q":"毒品会产生哪些影响？","o":["中毒","依赖、成瘾","身体和精神能力的长期提升"],"c":"毒品物质会影响中枢神经系统并扭曲感官知觉。尽管在毒品影响下你会感觉自己更高效，但你实际的表现会下降，并导致你丧失驾驶能力。与其他致醉物质相比，毒品更易成瘾。"},"1.1.09-010":{"q":"哪些毒品即使只吸食一次也可能使人暂时不宜驾驶？","o":["大麻脂、大麻","海洛因、可卡因、安非他命","麦角酸二乙酰胺（LSD）"],"c":"即使少量使用毒品也会导致暂时的驾驶能力丧失。与酒精不同，毒品没有限量值。在毒品影响下驾驶可能意味着吊销你的驾驶执照。"},"1.1.09-014":{"q":"毒品依赖者何时才重新适宜驾驶机动车？","o":["在能证明其已停止吸毒至少一年且不太可能复吸之后","如果其已一个月未吸毒","如果其已六个月未吸毒"],"c":"任何因在毒品影响下驾驶而被查获的人，都必须交出驾驶执照。如果他是吸毒成瘾者，该人必须整整一年不沾毒品，之后才能重新取得驾驶执照。这一点由评估机构（德文：Begutachterstelle für Fahreignung (BfF)）以报告的形式予以证明。"},"1.1.09-015":{"q":"大麻脂中的致醉物质如何被身体分解？","o":["不规律地历经不确定的时段","均匀地每小时0.1‰","均匀地每小时0.1克"],"c":"大麻等毒品在体内并非均匀分解——例如与酒精不同。因此，在这方面无法做出可靠的预测。"},"1.1.09-017":{"q":"在毒品影响下（例如大麻脂、海洛因、可卡因）驾驶机动车的人会有什么后果？","o":["吊销驾驶证或禁止驾驶","罚款和/或监禁","强制医学/心理学检查"],"c":"在大麻、可卡因或海洛因等毒品影响下驾驶车辆可能导致：吊销执照、罚款和/或监禁。如果危及他人，监禁可长达五年。为了重新取得你的驾驶执照，你必须接受医学-心理学评估（MPA）。"},"1.1.09-018":{"q":"吸食大麻脂可能产生哪些影响？","o":["伴有危险幻觉和反应能力下降的中毒","伴有精神错乱和抑郁的中毒","改善时间判断"],"c":"吸食大麻会导致失去时间和空间感的致醉状态。注意力降低，对周围环境的感知明显模糊。可能出现感官错觉和混乱状态，以及幻觉。"},"1.1.09-019":{"q":"吸食大麻脂可能产生哪些影响？","o":["危险意识减弱","加工信息时出错的可能性增加","错误判断速度和距离"],"c":"吸食大麻使吸食者处于丧失风险评估能力的致醉状态。时间感和方位感丧失，其结果可能是幻觉以及错误感知。距离和速度再也无法被正确估算。冒险的意愿以及错误判断的倾向迅速增强。"},"1.1.09-021":{"q":"谁在驾驶机动车时不得饮酒？","o":["所有21岁以下的驾驶人","所有处于试用期的驾驶人","所有驾驶人"],"c":"在试用期期间或年满21岁之前，对你在每次出行前以及驾驶机动车期间适用0.0‰的限值：绝对禁酒。"},"1.1.09-022":{"q":"处于试用期的驾驶人在驾驶机动车时允许受酒精影响吗？","o":["否，绝对不允许","允许，若未犯过任何与酒精相关的交通违法行为，血液酒精浓度最高为50毫克","允许，若未犯过任何与酒精相关的交通违法行为，血液酒精浓度最高为30毫克"],"c":"在试用期内，如果你想驾驶机动车，就不得饮用任何酒精。总体而言，在参与交通时你应当坚持0.0‰。"},"1.1.09-024":{"q":"为什么即使少量酒精也会损害驾驶能力？","o":["因为这会缩小视野","因为这会减弱空间视觉","因为这会缩短反应时间"],"c":"即使少量酒精也会对视力、反应能力和感知产生负面影响。贸然行动的意愿增强，而距离估算和注意力下降。"},"1.1.09-025":{"q":"吸食大麻制品会如何影响驾驶表现？","o":["对其他交通的意识下降","对驾驶的专注度下降","对眩光的敏感度下降"],"c":"吸食大麻制品对驾驶能力有害无益。无论吸食后个人反应和行为方式有何不同，对交通的专注能力通常会下降，而对眩光的敏感度则会上升。"},"1.1.09-026":{"q":"为什么即使只吸食一次毒品，在公共道路上驾驶也很危险？","o":["可能导致我不宜驾驶","可能导致持续数小时的中毒状态","可能造成知觉错误"],"c":"毒品通常会造成知觉障碍。即使一次性使用毒品也可能导致持续数小时的致醉状态。你作为吸食者将丧失驾驶能力。"},"1.1.09-027":{"q":"大麻及其分解产物在尿液中可检出多长时间？","o":["数周","至多数日","仅数小时"],"c":"大麻及其分解产物在吸食后10天到3个月的时间内可在你的尿液中被检出。确切时间取决于吸食频率和检测的精确度。"},"1.1.09-028":{"q":"为什么吸食冰毒后个人不宜驾驶？","o":["因为可能产生幻觉","因为可能高估自身能力","因为可能突然出现疲劳"],"c":"“冰毒”对驾驶能力产生负面影响，原因如下：该毒品会造成妄想。它助长对自身表现的过高估计以及突然的疲惫。即使少量吸食也会使你丧失驾驶能力。"},"1.1.09-029":{"q":"过量饮酒后如何能快速恢复驾驶能力？","o":["没有办法做到","通过喝两杯咖啡","通过做15分钟运动"],"c":"由于酒精在体内分解非常缓慢，短期内任何东西都无法恢复你的驾驶能力。"},"1.1.09-030":{"q":"什么会以类似酒精的方式影响驾驶能力？","o":["药物","毒品","软饮料"],"c":"酒精、毒品和药物对我们的反应时间、自控力和运动技能都有负面影响。"},"1.1.09-031":{"q":"吸食大麻制品会对驾驶人产生什么影响？","o":["它降低对其他交通的意识","它降低专注驾驶的能力","它降低对眩光的敏感度"],"c":"吸食大麻后，你的感知变得模糊，专注能力下降。"},"1.1.09-032":{"q":"吸毒会产生哪些影响？","o":["注意力受损","冒险意愿增强","错误判断速度"],"c":"毒品会导致致醉状态。这也会改变一个人的感知。这些致醉状态可能造成各种损害，例如专注力受损和速度判断错误。\n此外，冒险倾向可能增强，因为人们非常容易错误判断危急情况或自己的驾驶能力。"},"1.1.09-033":{"q":"在驾驶前或驾驶时吸食哪种物质会使你不宜驾驶？","o":["可卡因","酒精","大麻脂"],"c":"对于此处列出的所有毒品和物质，吸食都会导致丧失驾驶能力。\n驾驶时吸毒和饮酒会给道路交通带来重大风险，因为它们会严重限制注意力和专注力。此外，摄入酒精和毒品可能产生众多生理和心理影响，正如错误判断危急情况或过高估计自己的驾驶能力一样。"},"1.1.10-001":{"q":"环境温度高时，这会损害长途驾驶中的注意力并导致事故数量上升。下列哪种做法值得推荐，以便即使盛夏也能保持清醒并安全驾驶？","o":["我计划定时休息","我充分饮水","我尽量在中午前后完成行程"],"c":"气温高时，请确保饮用足够的水，并定期休息活动身体。"},"1.1.10-002":{"q":"出现哪些身体症状时应避免驾驶任何车辆？","o":["恶心","头晕","发烧"],"c":"如果你感到不适，应当休息或让其他人驾驶，以确保所有交通参与者的安全。\n头晕、恶心和发烧会影响你的注意力和驾驶能力，因此要等到感觉好转，以免危及自己和他人。"},"1.2.01-001":{"q":"参与道路交通需要时刻谨慎并对其他交通参与者体谅。这对你意味着什么？","o":["预料他人会有不当行为","有预见地驾驶","时刻坚持自己的优先通行权"],"c":"始终要预料到他人的错误以及自己的错误。任何时候都要坚持有预见性的驾驶方式，在任何情况下都不要坚持主张自己的优先通行权。这会违反交通法规的原则并危及其他交通参与者。"},"1.2.01-003":{"q":"你必须特别照顾哪些交通参与者？","o":["有明显残疾的人","儿童","出租车司机"],"c":"对以下交通参与者你必须特别小心：所有无法或不再能够应对道路交通要求的人。这意味着信赖原则被取消，对儿童、老年人/体弱者、残疾或醉酒的骑车人的应尽注意义务由你承担。"},"1.2.02-101-B":{"q":"何时可以使用右侧应急车道？","o":["用于停车和驻车","用于驾驶行驶缓慢的车辆","用于超车"],"c":"右侧边带可在以下情况下使用：1. 用于停车和停放，2. 用于轻便摩托车或农用拖拉机和机械等慢速车辆。为避免交通阻碍和拥堵，这些车辆应当使用右侧边带。边带必须铺设且具有足够的宽度。在任何情况下都禁止使用边带超车。"},"1.2.02-104-M":{"q":"你误驶入左车道，但想右转。正确的做法是什么？","o":["我继续直行或左转","我小心变入右车道","我直行并在交叉口右转"],"c":"当以实线作为道路边缘标线时，在任何情况下你都不得右转。相反，你必须留在你的车道中继续直行或左转。"},"1.2.02-106":{"q":"在主干道上行驶时，哪些车辆必须尽可能使用应急车道？","o":["行驶缓慢的农用拖拉机和机械","轻便摩托车","小排量摩托车"],"c":"拖拉机、轻便摩托车等慢速车辆必须使用硬路肩。其他时速超过45公里的车辆需留在道路上。"},"1.2.02-107":{"q":"在此情况下你该怎么做？","o":["驶入避让处，让对向来车通过","继续向前，因为对向来车必须倒车","向后倒车，因为对向来车享有先行权"],"c":"在两侧都停有车辆的街道上，活动余地有限。只有一条车道时，两个方向的车辆地位同等。不过，你应当驶入一个空隙，让对向来车通过。"},"1.2.02-108":{"q":"一辆马车正向你驶来。你该怎么做？","o":["避免发出噪音","尽量靠右行驶","开启驻车灯"],"c":"遇到马拉车时，尽量靠右行驶。不要鸣喇叭，也不要以高发动机转速行驶。动物可能对噪音敏感并受到惊吓。有可能它们会挣脱并跑到你这一侧的道路上。"},"1.2.02-109":{"q":"在此情况下哪些说法正确？","o":["适用“右先于左”的先行权规则","我享有先行权","一个交通安宁区结束"],"c":"在“带优先通行权的交叉路口或路口”交通标志处，你必须遵守“右先于左”的优先通行规则。这适用于最近的交叉路口。"},"1.2.02-110":{"q":"横穿干道时必须注意什么？","o":["干道的宽度","交叉方向交通的速度和距离","天气条件"],"c":"横穿优先通行道路时，你必须考虑：1. 优先通行道路的宽度，2. 对向来车的距离和速度，3. 天气条件。这些都是对横穿优先通行道路有重要影响的因素。天气影响路况和能见度。它连同道路宽度一起决定了你横穿优先通行道路所需的时间。通过估算对向来车的距离和速度，你可以评估你有多少可用时间。"},"1.2.02-111":{"q":"你想使用高速公路。为此，在行驶证第一部分或营运许可中必须登记多大的车型最高速度？","o":[],"c":"根据德国道路交通法规（Straßenverkehrsordnung - StVO），只有最高设计速度超过60公里/小时的车辆才可以使用高速公路。"},"1.2.02-201":{"q":"你在城镇内一条允许轻便摩托车行驶的自行车道上行驶。应预料到什么？","o":["停放车辆的车门会突然打开","转入另一条街道的车辆可能看不到我","行人会走在自行车道上"],"c":"如果你在城里的自行车道上骑行，你应当预料到各种情况。停放汽车的车门可能突然被打开，转弯的车辆可能忽视你，行人也会使用自行车道。"},"1.2.03-001":{"q":"哪些因素会延长你的制动距离？","o":["牵引未装制动器的拖车","潮湿或湿滑的路面","下坡行驶"],"c":"车辆的制动距离会延长：1. 在陡坡上，2. 在潮湿或湿滑的路面上，3. 如果车辆必须承载额外的载荷。制动距离延长的原因在于：在陡坡上，重力会产生加速力。在潮湿或湿滑的道路上，轮胎与路面之间的静摩擦减小。额外的载荷增大了需要停止的质量。"},"1.2.03-002":{"q":"制动距离取决于什么？","o":["轮胎","制动系统","路面"],"c":"你车辆的制动距离取决于轮胎、制动系统和路况。只有功能正常的制动系统才能有力而迅速地产生制动力，并且只有在有足够花纹深度时才能最佳地传递到路面。轮胎的静摩擦取决于路况。"},"1.2.03-101":{"q":"城镇内道路一般允许的最高速度是多少？","o":[],"c":"50公里/小时是城市内法定规定的最高限速。\n如果超过这一速度，你将无法及时处理信息以做出反应。"},"1.2.03-102":{"q":"你将行驶速度加倍。这对制动距离有何影响？","o":[],"c":"这也取决于你的车速：速度翻倍时，制动距离将变为四倍——从30公里/小时时的9米到60公里/小时时的36米。"},"1.2.03-103":{"q":"选择车速时必须考虑什么？","o":["能见度和天气条件","道路状况和交通状况","个人驾驶能力"],"c":"你只允许以法定最高速度驾驶车辆。实际允许的速度通常更低。它取决于能见度和天气条件、路况、当前交通状况以及你个人的驾驶技能。"},"1.2.03-104":{"q":"用哪条经验法则可以根据速度确定机动车一秒钟行驶的米数？","o":["速度（公里/小时）除以10再乘3","速度（公里/小时）除以10再乘5","速度（公里/小时）除以10再乘速度（公里/小时）除以10"],"c":"借助以下经验法则和速度，你可以计算车辆在一秒内行驶的距离（以米计）：将速度除以十，再乘以三。如果你以100公里/小时驾驶车辆，一秒内可行驶30米。"},"1.2.03-105":{"q":"用哪条经验法则可以根据速度确定正常制动时的制动距离（米）？","o":["速度（公里/小时）除以10再乘速度（公里/小时）除以10","速度（公里/小时）除以10再乘5","速度（公里/小时）除以10再乘3"],"c":"制动距离是指从开始制动到你的车辆停止所行驶的距离。在正常制动时可以用简单的经验法则计算：行驶速度除以十，再乘以行驶速度除以十。"},"1.2.03-106":{"q":"你以30公里/小时行驶。按经验法则，正常制动时制动距离为9米。相同条件下以60公里/小时行驶时制动距离是多少？","o":["36米","27米","18米"],"c":"如果你把速度翻倍到60公里/小时，制动距离将变为四倍。只需从30公里/小时的制动距离出发，相应地计算9米乘以4 = 36米。"},"1.2.03-107":{"q":"你在一条宽阔道路上行驶，对向交通可以畅通地从你旁边通过。在任何情况下你都必须能在多长距离内停车？","o":["我能看清的距离","我能看清的距离的一半","我能看清的距离的两倍"],"c":"你必须能够在可见距离内停下，以防动物或人等障碍物突然进入车行道。"},"1.2.04-101":{"q":"与前车应保持的距离取决于什么？","o":["能见度条件","速度","路面状况"],"c":"与前车的距离取决于车速以及能见度和路况。作为经验法则，你应当至少保持以米计的、车速一半的距离。在能见度或路况不佳时，应加大这一距离。"},"1.2.04-102":{"q":"正确的做法是什么？","o":["我制动","我加大与驶入我车道的前车的距离","我保持车速"],"c":"如果你前方的驾驶人突然插入并缩小了他与你车辆之间的安全距离，你必须制动，直到这一距离再次得到保证。"},"1.2.04-103":{"q":"正确的做法是什么？","o":["我减速","我保持车速","我加速"],"c":"如果你被一辆汽车超越，你不得加快速度。相反，你应当减速，让超车的汽车尽可能快地重新并入。"},"1.2.04-104":{"q":"在你与前车之间保持足够距离可获得什么好处？","o":["有助于有远见地驾驶","有助于降低事故风险","会限制视野"],"c":"你应当始终与前车保持足够大的安全距离。通过有预见性的驾驶，你保持了最佳视野并降低了事故风险。"},"1.2.05-003":{"q":"在城镇外行驶时，你想超越骑行者或行人。你必须保持的最小侧向间距是多少？","o":[],"c":"在城镇外，对行人、骑车人和个人代步工具必须保持的最小距离为2米。"},"1.2.05-004":{"q":"在城镇内行驶时，你想超越一名骑行者。你必须保持的最小侧向间距是多少？","o":[],"c":"超车时，你必须保持足够的侧向距离，以免危及其他交通参与者。在城镇内，对行人、骑车人和个人代步工具的最小距离为1.5米。"},"1.2.05-005":{"q":"在城镇内行驶时，你想超越一辆电动滑板车。你必须保持的最小侧向间距是多少？","o":[],"c":"超车时，你必须保持足够的侧向距离，以免危及其他交通参与者。在城镇内，对行人、骑车人和个人代步工具的最小距离为1.5米。"},"1.2.05-101":{"q":"在哪里禁止超车？","o":["在交通状况不明确时","在对向交通可能受到阻碍处","在所有单行道上"],"c":"在以下情况下禁止超车：1. 在交通情况不明确时；2. 在违反交通法规时。不过，在单行道中不存在一般性的禁止超车规定。在你开始超车之前，要通过后视镜和回头从肩上方向后看，确保你没有妨碍或危及其他交通参与者。"},"1.2.05-103":{"q":"驶出超车的正确程序是什么？","o":["对后方交通没有危险","对向交通不受危害","前车发出右转信号"],"c":"超车驶出时适用以下规则：你必须通过看后视镜和回头从肩上方向后看一眼来确认，你的超车操作既不会危及也不会妨碍后方交通。只有在确认之后，你才允许打转向灯并驶出。在超车过程中，你必须注意不妨碍对向来车。如果你前方的驾驶人向右打转向灯，你不应受诱惑去超车。"},"1.2.05-104":{"q":"结束超车时你必须怎么做？","o":["尽快向右驶回，且不使被超车辆感到不便","清楚且及时地示意你驶回","紧挨着被超车辆正前方驶回车道右侧"],"c":"作为超车驾驶人，你必须尽快向右并入。但是，只要你与刚被超越的驾驶人距离仍然过近，就不要回到车道中，因为你可能妨碍甚至危及他。在开始驶出以及重新并回车道的适当时间之前，要提前打转向灯。"},"1.2.05-105":{"q":"关于超车时车速的规章是什么？","o":["超车车辆的速度必须明显更高","不得超过允许的最高速度","被超者不得提高车速"],"c":"只有当你明显更快（至少快20公里/小时）时，你才可以超越前方的车辆。此外，超车时：不要超过最高限速。被超者在超车过程中不得提高其初始速度。"},"1.2.05-106":{"q":"当你被超车时你必须怎么做？","o":["尽可能靠右行驶","不提高车速","提高车速"],"c":"尽量靠右行驶，以免危及对向来车和超车的车辆。在整个超车过程中，你作为被超者不得提速，否则就无法安全超车。"},"1.2.05-107":{"q":"在车行道中央行驶的有轨电车（非单行道）应从哪一侧超越？","o":["从右侧","从左侧","仅当其他车辆堵住右侧车行道时才从左侧"],"c":"有轨电车通常必须从右侧超越。如果此处停有车辆，你必须行驶在电车后方。如果轨道过于靠右，有轨电车也可从左侧超越。"},"1.2.05-108":{"q":"何时可以从左侧超越有轨电车？","o":["在单行道上","当轨道太靠右时","当有轨电车右侧的车行道（非单行道）被其他车辆堵住时"],"c":"有轨电车等轨道车辆基本上只能从右侧超越。当轨道过于靠右，或轨道车辆在单行道中行驶时，你才可以破例从左侧超越。妨碍右侧通行的车辆不足以成为从左侧超越轨道车辆的理由。"},"1.2.05-109":{"q":"哪些车辆只能保持特别大的侧向间距来超越？","o":["自行车","摩托车","有轨电车"],"c":"超车时你必须始终与旁边的交通参与者保持足够的距离。对摩托车和自行车骑行者，这一距离必须特别大。单辙车辆更不稳定，可能摆动。对两轮车辆的侧向最小距离为1.5米。"},"1.2.05-110":{"q":"何时必须发出信号？","o":["在驶出超车或通过之前","在超车后驶回之前","在离开急转弯的干道直行时"],"c":"每当你想要变道或转弯时，都需要打转向灯。这同样适用于沿一条转向的优先通行道路行驶时，但当你直行离开优先通行道路时则不适用。即使已经打了转向灯：也务必确保你在驶出或并回车道时不会危及任何人。"},"1.2.05-115":{"q":"在哪里禁止超车？","o":["在行人横道处","在视野不良的路段","在专用公交车道"],"c":"超车时，你必须排除对其他交通参与者的危险情况。通常禁止在人行横道处以及难以观察的道路上超车。你可能过晚地看到对向来车。你可以在公交专用道上超越公交车。"},"1.2.05-116":{"q":"你在主干道上驾驶一辆行驶缓慢的车辆。如何方便较快的车辆超车？","o":["驶上应急车道","驶上停车区","驶入避车处"],"c":"为了让更快的车辆在乡间道路上超越你，你可以在合适的边带、避让处或休息区避让。也可以减速，甚至在合适的地点停车。"},"1.2.05-117":{"q":"超车时关于间距必须注意什么？","o":["保持足够的侧向间距，尤其是车辆与人之间","车辆与其他交通参与者之间保持足够的侧向间距","对多车道车辆保持比单车道车辆更大的侧向间距"],"c":"超车时，你必须确保与其他交通参与者有足够的侧向距离：对汽车、卡车、公交车、有轨电车至少1米。对行人和骑车人，最小距离为1.5米。当你并回车道时，不得切入刚被你超越的驾驶人的前方。（检查：他在后视镜中可见吗？）"},"1.2.05-119":{"q":"如何判断一辆马车想改变方向？","o":["驾车人伸出手臂","显示交通指挥牌","闪烁的转向灯"],"c":"当马拉车想要改变行驶方向时，可通过以下标志之一识别：马拉车打转向灯；车夫用手臂或信号盘示意。"},"1.2.05-120":{"q":"你想在农村道路上超越一辆马车。你该怎么做？","o":["尽量少的噪音","尽量大的侧向间距","高发动机转速"],"c":"以恰当的速度并尽可能保持距离驶过马匹。动物可能被突然而响亮的噪音，如汽车喇叭或高发动机转速所惊吓，并可能挣脱狂奔。因此，要避免噪音和过近的距离。"},"1.2.05-121":{"q":"你想在农村道路上超越一辆马车。你该怎么做？","o":["我保持尽可能大的侧向间距","我注意驾车人的手势信号","我以高发动机转速超车"],"c":"如果你想在乡间道路上超越马拉车，你必须做到以下几点：避免不必要的噪音，如鸣喇叭或以高发动机转速行驶，以免惊吓马匹。注意车夫的手势，因为他能判断其马匹的行为。保持安全距离。"},"1.2.05-122":{"q":"你在农村道路上驾驶一辆行驶缓慢的车辆。你后方形成了一列车队。你该怎么做？","o":["我让后方的车辆超车","如果这是后方车辆唯一能超车的方式，我在合适的地点停车","我开启危险警示灯并尽量靠右行驶"],"c":"慢速车辆后方排起长队会导致危险的超车操作。为了让堵在你后方的车辆更容易超车，请降低车速。如果车队仍然不消散，你可能需要在边带上停车。这不适用于高速公路！你不得使用危险警示灯。"},"1.2.05-123":{"q":"你想在农村道路上超越一辆马车。正确的做法是什么？","o":["我留意驾车人表示想转出的手势信号","驶回时我保持足够的距离","我保持尽可能小的侧向间距"],"c":"超越马车时，你必须注意车夫的手势信号，他可能给你单独的指示。超越马车时始终应保持安全距离，以免惊吓马匹。"},"1.2.05-124":{"q":"超越行人和骑行者时必须保持多大的侧向间距？","o":["在城镇内保持至少1.5米的最小侧向间距","在城镇外保持至少2.0米的最小侧向间距","在城镇内保持至少1.0米的最小侧向间距"],"c":"为保护骑车人和行人，你在城镇内必须保持至少1.5米的侧向距离，在城镇外至少2米。"},"1.2.05-125-M":{"q":"在此情况下超越骑行者时你必须注意什么？","o":["坡度使骑行者摇晃","我必须保持至少1.5米的侧向间距超车","我必须保持至少1.0米的侧向间距超车"],"c":"在城镇内超车时，你必须与骑车人保持至少1.5米的侧向距离。\n由于骑车人的往返摆动，建议保持更大的最小距离。"},"1.2.05-126-M":{"q":"在此情况下正确的做法是什么？","o":["我留在骑行者后方","我以足够的侧向间距超越骑行者","我必须让行人过马路"],"c":"行车道标线为实线。因此此处禁止超车。"},"1.2.06-001":{"q":"因施工而封闭一半车行道时，哪辆车必须等待？","o":["施工所在那一侧车行道上的车辆","未受阻那一侧车行道上的车辆","总是较小的车辆"],"c":"如果你想驶过街道上你这一侧停放的汽车或障碍，你必须让对向来车先行，无论车辆多大。"},"1.2.06-002-B":{"q":"谁必须等待？","o":["我必须等待","对向来车必须等待"],"c":"如果你想驶过道路左侧停放的汽车或障碍，你必须让与你相遇的车辆先行。"},"1.2.06-004":{"q":"为什么在此应特别缓慢行驶？","o":["因为货车使车道变窄","因为人们正走上道路","因为我正接近一个信号灯路口"],"c":"在你前方，一辆停着的卡车使道路变窄。对交通的视野受限。在卡车前方有行人横穿街道，你可能过晚才察觉，因为他们的视线也被遮挡。因此，要非常缓慢、小心地绕过这一障碍。"},"1.2.06-005":{"q":"正确的做法是什么？","o":["等待，因为否则骑行者与汽车之间没有足够空间","以中等速度继续行驶，因为骑行者与汽车之间空间很小","保持原样继续行驶，因为骑行者与汽车之间空间足够"],"c":"你想绕过停放在道路右侧的车辆。但这只有在迎面而来的骑车人已经驶过你之后才可能。否则你将无法保持必要的侧向距离，因此必须等待。"},"1.2.06-006":{"q":"现在你该怎么做？","o":["驶过，前提是明确没有对向交通","等待，以免妨碍可能出现的对向交通","驶过，因为任何可能出现的对向交通肯定早已在等待"],"c":"你的视线被厢式货车遮挡，无法判断是否有车辆朝你驶来。在继续行驶之前，确保没有对向来车驶近。你必须等待，因为施工现场在你这一侧车道。"},"1.2.06-101-M":{"q":"在此情况下正确的做法是什么？","o":["我等到对向交通参与者驶过我","我在对向交通参与者之前优先通过","对向交通参与者与我商定谁优先"],"c":"你要等到迎面而来的摩托车手驶过，因为障碍物在你这一半车道上。"},"1.2.07-001":{"q":"你想变更车道时必须记住什么？","o":["必须及时示意你要变更车道","必须注意后方跟随的交通","变更车道前必须总是大力制动"],"c":"在开始变道前，打开转向灯并确保你不会危及其他交通参与者。不要猛制动。如果你要换入的车道上有车辆，你必须等待车流中出现足够大的空档。"},"1.2.07-103":{"q":"在单向多车道的道路上，前方有一条车道将结束。你在即将结束的车道上行驶。你该怎么做？","o":["只有在道路开始变窄前不久才按照拉链式并线法驶入","在看到第一个道路将变窄的标志后立即驶入直行车道","总是第一个驶入直行车道"],"c":"如果道路上存在障碍，或一条多车道道路变窄，那么对所有同向行驶的车辆都适用拉链式交替通行。行驶到你车道的尽头。不要为图便利而提前变道。在此等待，直到相邻车道上有一辆车让你进入。"},"1.2.07-104":{"q":"在有对向交通的隧道内你该怎么做？","o":["不得驶越车道分界标线","不得掉头","超车时驶越车道分界标线"],"c":"在有对向交通的隧道中，你必须按以下方式行事：以道路右侧为参照，避免直视对向来车的灯光。你不得压过或跨越道路边缘标线。必要时加大安全距离，有预见性地驾驶，并注意超车限制。"},"1.2.07-105-M":{"q":"在此情况下正确的做法是什么？","o":["我在约200米后变入右侧车道","我可以超越右侧车道上行驶的车辆","我现在变入右侧车道"],"c":"你尽可能贴近障碍处行驶，并仅在约200米之后才换到右侧车道。你可以超越右侧车道上的所有车辆。"},"1.2.07-112":{"q":"在哪些情况下使用交替并线程序？","o":["当车道结束时","当车道因障碍物而不能持续通行时","在汇入车道汇合处"],"c":"如果道路变窄，或道路上存在障碍导致一条车道结束，则适用拉链式交替通行。它不适用于驶入匝道的加速车道。在这里你必须等待。"},"1.2.07-113":{"q":"在单向多车道的道路上有一条车道结束。在直行车道上行驶时你该怎么做？","o":["按照交替并线程序，让即将结束车道上的交通汇入","从即将结束车道上的车辆旁驶过","进行目光交流后根据情况决定"],"c":"你必须让因所在车道结束而无法继续行驶的驾驶人安全地换到相邻车道。结束车道上的车辆与延续车道上的车辆必须在车道变窄开始处之前交替并入车道，这是强制性的。这被称为拉链式交替通行。"},"1.2.07-115":{"q":"你想继续直行。你该怎么做？","o":["我在道路变窄前才变更车道","我现在变入右侧车道"],"c":"如果一条车道结束，车辆应只在收缩开始处之前并入车道。这应交替进行：延续车道上的每辆车让结束车道上的每一辆车进入车道。这被称为拉链式交替通行。实际上，车辆常因担心不被让行而自己过早并入车道，从而比必要的时间更早地使车道变窄。"},"1.2.07-116":{"q":"你想在路口右转。你该怎么做？","o":["我放弃右转，留在我的车道内","我明显向右转向，以便在右侧车道腾出空间","我等到所有车辆驶过，然后变入右侧车道"],"c":"您将不得不变换到右侧车道，而该车道被等候的车辆堵住。这样您会在等候时妨碍该车道上的其他道路使用者。因此，您最好不要在此处转弯。"},"1.2.09-006":{"q":"你想左转。何时必须查看后方交通？","o":["在驶入车道前以及紧接转弯前","只在转弯前一次"],"c":"如果您想左转，必须首先通过拨动转向指示灯操纵杆来表示这一意图，以便让后车明白。无论是并入车道之前，还是紧临转弯之前，您都应当通过查看后视镜和转头从肩上方观察，确认后车已经注意到您的意图。"},"1.2.09-009":{"q":"两辆车相向驶来。两车都想左转。按规则它们必须怎么做？","o":["它们从彼此前方转弯","它们以大弯彼此通过并从彼此后方转弯"],"c":"各自要从自己的行驶方向左转的对向车辆，必须相互在对方车头前转弯。这种交通情形称为切向转弯（交错左转）。这是规定的规则。在狭窄的交叉路口或有安全岛的交叉路口存在例外情形，此时允许以更大的弧度转弯。"},"1.2.09-010":{"q":"两辆车相向驶来。两车都想左转。在哪些情况下不允许从彼此前方左转？","o":["当你注意到想左转的来车希望从你的车后方转弯时","当车道标线禁止这样做时","当想左转的来车恰好在交叉路口中央前停下时"],"c":"原则上，您必须在迎面车辆之前左转（切向转弯）。但是，如果车道上的车道标线规定如此，则应从另一辆车后方以较大弧度转弯。如果另一辆车驾驶人的驾驶方式表明他想在您后方转弯，您同样必须放弃相互在对方车头前转弯的做法。"},"1.2.09-012-M":{"q":"正确的做法是什么？","o":["我必须让那辆黄色车辆通过","我可以在那辆黄色车辆之前转弯"],"c":"如果您想左转，必须让迎面车辆先行。迎面车辆享有优先通行权，骑自行车的人也不例外。"},"1.2.09-013-M":{"q":"至左转前你应保持哪条行驶路线？","o":["右侧","左侧"],"c":"左转的驾驶人应驶至车行道中间位置。车辆不得伸入对向交通的车道，从而妨碍交通流通行。在单行道上，允许靠左侧车道行驶。"},"1.2.09-016":{"q":"你想左转。何时必须注意后方跟随的交通？","o":["在选择合适车道之前","在转弯之前","在转弯之后"],"c":"左转时，您在转弯前和并线前都应当注意后续交通。"},"1.2.09-017":{"q":"两辆车在交叉口相向驶来。两车都想左转。在什么特殊情况下它们必须一前一后转弯？","o":["如果交通状况要求这样做","如果交叉口的布局要求这样做","如果车辆驶越同等级优先权的交叉口"],"c":"通常应相互在对方车头前转弯。如果交通情形或交叉路口的构造（例如车道标线）有此要求，则必须前后依次转弯。"},"1.2.09-018":{"q":"两辆车在交叉口相向驶来。两车都想左转。在通常情况下两名驾驶人必须怎么做？","o":["从彼此前方转弯","从彼此后方转弯","相互沟通以商定转弯方式"],"c":"如果两辆左转的车辆相向而行，它们相互在对方车头前转弯（切向转弯）。"},"1.2.09-019-M":{"q":"你想左转。应保持哪条行驶路线？","o":["右侧行驶路线","左侧行驶路线","两条行驶路线都可以"],"c":"使用右侧的行车线。左侧行车线是留给对向交通的。"},"1.2.09-020-M":{"q":"在此必须向哪一交通参与者让行？","o":["那名行人","那名骑行者","那辆公交车"],"c":"转弯时，您必须让对向交通和横向交通先行——在此情形下即骑自行车的人和行人。\n即使您的信号灯为绿灯，也必须等到行人穿过马路后才能通行。转弯车辆必须让行人先行。"},"1.2.09-021-M":{"q":"你想在这个出口驶出环岛。正确的做法是什么？","o":["我必须让行人过马路","我必须让骑行者过马路","我相对横穿马路的交通参与者享有先行权"],"c":"驶出环形交叉路口时，过街的行人和骑自行车的人享有优先权。\n因此您必须让骑自行车的人和行人穿过车行道。"},"1.2.09-022-M":{"q":"你想在此右转。哪些说法正确？","o":["我必须让两名行人都过马路","我只必须让对向的那名行人过马路","我相对两名行人都享有先行权"],"c":"您必须让这两名行人都穿过马路。他们没有改变行进方向，因此相对于您享有优先权。"},"1.2.09-101":{"q":"在多条车道转弯驶出处可能产生哪些特别危险的情况？","o":["行驶过快","转弯时变更车道","严格保持在自己的车道内"],"c":"应以适中的速度驶入多车道转弯。速度过快可能使您偏离自己的车道，进入并排行驶车辆的车道。在这种转弯情形中应避免变更车道。因为存在有车辆正好处在您盲区内的风险。"},"1.2.09-103-B":{"q":"三辆车都想左转。哪辆在正确的车道上？","o":["那辆黄色汽车","那辆货车","那辆绿色汽车"],"c":"只有黄色汽车正确地并入车道。它按照安全岛上路牌所示从右侧通过，以便随后驶入尽可能靠左的正确车道，为左转做准备。绿色汽车完全错在了轨道上。在此情形下，卡车只允许直行或右转。"},"1.2.09-104-B":{"q":"左转后你想立即右转。你应如何摆放车辆？","o":["红色汽车","绿色汽车","蓝色汽车"],"c":"如果您左转后想紧接着再右转，则当有两条左转车道时应驶入右侧的正确车道。否则应尽可能靠右行驶。唯有如此，您才能在左转之后右转而不妨碍其他道路使用者。"},"1.2.09-107-B":{"q":"谁在此必须示意改变方向？","o":["那辆摩托车","我自己","没有人"],"c":"谁改变行驶方向，谁就必须打转向灯示意。无论道路的等级高低都是如此。因此，沿着转弯的先行道路行驶的摩托车驾驶人必须打转向灯。您继续直行，不必打转向灯。"},"1.2.09-109":{"q":"你在环岛内。应记住什么？","o":["只有当由于你车辆的尺寸不可避免时，才可驶越中央岛","你不得在环岛内的车行道上停车","你必须示意驶出环岛"],"c":"在环形交叉路口内，只有在因交通原因（例如交通堵塞）不可避免时，才允许停车。驶出环形交叉路口时要打转向灯。只有当因车辆尺寸原因不可避免时，才允许驶过铺砌或沥青铺装的中心岛。对于在您右侧行驶并留在环形交叉路口内的骑自行车者，始终要让他们先行。"},"1.2.09-111":{"q":"在什么情况下转弯特别危险？","o":["在山顶前","在道路弯道前","在有雾条件下"],"c":"在能见度差（雾天）时转弯可能产生危险情形。在弯道中转弯以及在坡顶之前转弯同样如此。"},"1.2.09-112-M":{"q":"谁必须示意？","o":["我","那辆蓝色货车","那辆红色汽车"],"c":"改变行驶方向时始终必须按转向指示灯示意。如果您继续沿着转弯的先行道路行驶，也应当打转向灯示意。因此，蓝色卡车必须打转向灯。您作为左转者，也必须打转向灯。"},"1.2.09-113-M":{"q":"谁在此必须示意改变行驶方向？","o":["我","那辆红色汽车","那辆摩托车"],"c":"改变行驶方向时始终必须足够提前地打转向灯示意。三名驾驶人都打算转弯。因此，三辆车都必须打转向灯。"},"1.2.09-116-M":{"q":"谁在此必须示意改变行驶方向？","o":["我","对向的汽车"],"c":"改变行驶方向的意图必须提前通过打转向灯予以表明。您沿着转弯的先行道路行驶；这次行驶方向的改变需要打转向灯。"},"1.2.09-117":{"q":"何时必须示意改变方向？","o":["在驶入路口或地产场地之前","如果我想继续沿一条改变方向的干道行驶","如果我想继续直行，从而离开一条改变方向的干道"],"c":"如果您想驶入一条横向道路或一处场地，必须打转向灯。如果您沿着转弯的先行道路行驶，同样如此——在这种情况下，改变行驶方向也必须打转向灯示意。"},"1.2.09-119":{"q":"为什么现在必须停车？","o":["因为那名骑行者","因为绿色车辆","因为红色车辆"],"c":"转弯的驾驶人必须等待来自对向的车辆，骑自行车者也不例外。红色汽车必须等待，直到绿色汽车和骑自行车者通过。"},"1.2.09-120":{"q":"你想左转。你以什么顺序准备左转？","o":["观察后方交通，示意转弯方向，驶入车道","示意转弯方向，驶入车道，观察后方交通","驶入车道，示意转弯方向，观察后方交通"],"c":"如果您想左转，请按以下顺序准备转弯：1. 观察，2. 打转向灯，3. 并线。观察是指通过后视镜和转头从肩上方观察后车。然后拨动转向指示灯指向左侧。只有当您能排除对其他道路使用者的危险时，才允许向左并线以便转弯。"},"1.2.09-121":{"q":"正确的做法是什么？","o":["我必须在停车线处等待","我必须让骑行者通过","我可以在骑行者之前转弯"],"c":"在“停车！让行！”交通标志（俗称停车标志）前，您必须始终停车。通常设有停车线。车轮必须至少短暂地保持静止。横向交通享有优先通行权——然后是对向的骑自行车者。作为左转的驾驶人，您必须让他先行。"},"1.2.09-122":{"q":"你该如何行动？","o":["向两名骑行者让行","只向同向行驶的那名骑行者让行","鸣喇叭并在两名骑行者之前转弯"],"c":"转弯的驾驶人通常必须等待迎面车辆。其中包括骑自行车者。在您所在车道上或车道旁同向行驶的骑自行车者，同样必须让他们先行。"},"1.2.09-123":{"q":"你想左转。必须向谁让行？","o":["对向骑行者","对向来车","想横穿我驶入道路的行人"],"c":"左转时，对向交通始终享有优先通行权。骑自行车者也不例外；他们享有优先权。如果有行人穿过您想转弯驶入的街道，行人同样享有优先权。"},"1.2.09-124":{"q":"你想左转。在此可能出现哪些困难？","o":["对向来车造成的视线受限","与左转的对向交通产生误解","左转的交通可能危险地靠近"],"c":"左转时，相向接近的车辆必须相互在对方车头前转弯（切向转弯）。这可能造成对直行交通的视线不良。尤其是左转的卡车可能造成严重遮挡，此时以较大弧度转弯（前后依次转弯）更为安全。当一方想在后方转弯而另一方想在前方转弯时，驾驶人之间可能产生误解。"},"1.2.09-125":{"q":"为什么现在必须停车？","o":["因为那辆有轨电车","因为那名骑行者","因为那辆白色汽车"],"c":"您在先行道路上，因此可以优先于从右侧驶来的白色汽车通行。但是，作为想要转弯的驾驶人，您相对于直行交通（在此情形下即有轨电车）处于次要地位。您必须停车。"},"1.2.09-126":{"q":"在此情况下正确的做法是什么？","o":["在铁路道口前不得超越轻便摩托车","超越轻便摩托车，同时留出足够的侧向间距","一旦骑行者让开路，就在铁路道口前超越轻便摩托车"],"c":"在铁路道口之前，您不得超越轻便摩托车。一般而言，从标志151、156起直至铁轨的范围内，在铁路道口处不得超越任何车辆。"},"1.2.09-127":{"q":"为什么现在必须制动？","o":["因为那辆摩托车","因为那辆厢式货车","因为那名骑行者"],"c":"摩托车驾驶人从左侧高速驶来。他很可能因为迎面的车辆而没有看到您。尽管您享有优先通行权，也必须减速，否则将发生事故。"},"1.2.09-128-M":{"q":"为什么右转前必须等待？","o":["因为那名行人","因为那名骑行者","因为那辆黑色汽车"],"c":"如果您想转弯，必须让直行的道路使用者先行。在此情形下，您相对于行人和骑自行车者处于次要地位，必须让他们安全通过。"},"1.2.09-129":{"q":"在此必须注意什么？","o":["继续制动","让汽车先行","驶入环岛时示意"],"c":"由于蓝色汽车已经在环形交叉路口内，您必须减速。只有在驶出环形交叉路口时，您才必须打转向灯。"},"1.2.09-130-M":{"q":"你想左转。应保持哪条行驶路线？","o":["左侧那条","中间那条","右侧那条"],"c":"由于您身处单行道，不必担心对向来车。请及时打转向灯。然后向左并线，并保持在左侧车道上，直到到达转弯处。"},"1.2.09-131-M":{"q":"骑行者想继续直行。在此正确的做法是什么？","o":["我留在骑行者后方","我超越骑行者"],"c":"想要转弯的车辆，在转弯前必须让在道路上或道路旁同向行驶的自行车先行。无论其车轮是否为机动驱动都无关紧要。"},"1.2.09-132-M":{"q":"在此情况下转弯前为什么必须等待？","o":["因为那辆摩托车","因为那辆货车","因为那名行人"],"c":"由于有卡车和摩托车。在此您必须注意转弯规则。等待这些车辆完成其动作，然后再继续转弯。"},"1.2.09-133-M":{"q":"在此情况下谁必须示意？","o":["我","那辆蓝色汽车","那辆红色汽车"],"c":"您和蓝色汽车都在改变行驶方向，因此必须打转向灯示意方向的改变。"},"1.2.09-134-M":{"q":"现在正确的做法是什么？","o":["我制动","我暂时继续在右侧车道行驶","我立即变入左侧车道"],"c":"您后方的摩托车已经变换到左侧车道，并将在左侧超越您。为了及时并入左转车道，您必须减速。"},"1.2.09-135-M":{"q":"为什么现在不允许转弯？","o":["因为黄色汽车","因为红色车辆","因为绿色汽车"],"c":"在交叉路口，直行的驾驶人享有优先通行权。您必须等待转弯，直到黄色汽车驶过交叉路口。"},"1.2.09-136-M":{"q":"在此情况下必须预料到什么？","o":["那辆蓝色汽车会继续直行","那辆红色公交车会立即开始移动","那名行人会等待"],"c":"蓝色汽车驶过正在停靠的公交车，尽管它位于转弯车道上，仍可能想继续直行。由于您要左转，它享有优先通行权。"},"1.2.09-137-M":{"q":"为什么现在必须停车？","o":["因为那辆电动滑板车","因为那些行人","因为那辆有轨电车"],"c":"盲区内有一辆电动滑板车，因此您必须停车，以免对其造成危险。"},"1.2.09-138-M":{"q":"现在正确的做法是什么？","o":["我让骑行者通过","我扭头越过右肩察看","我抢在电动滑板车之前转弯"],"c":"直行交通始终享有优先权，无论骑自行车者是在道路上还是在自行车道上骑行。为确保没有其他骑自行车者驶近，您必须向右转头从肩上方观察。"},"1.2.09-201-M":{"q":"为什么现在必须停车？","o":["因为那辆有轨电车","因为那名骑行者","因为那辆黄色汽车"],"c":"由于您想左转，转弯前应当等待有轨电车。"},"1.2.09-202-M":{"q":"在此情况下右转前为什么必须等待？","o":["因为那名行人","因为那名骑行者","因为那辆蓝色汽车"],"c":"转弯时，您必须让纵向交通先行，因此必须等待行人和骑自行车者通过。"},"1.2.09-203-M":{"q":"为什么在此不能驶离道路？","o":["因为红色汽车","因为黄色货车","因为蓝色拖拉机"],"c":"红色汽车仍在超越您，并且行驶速度比您快得多。请等待红色汽车通过。"},"1.2.09-204-M":{"q":"在此情况下左转前为什么必须等待？","o":["因为那辆有轨电车","因为那辆红色汽车","因为那辆黄色车辆"],"c":"您正在改变行驶方向，因此必须让有轨电车先行。"},"1.2.09-205-M":{"q":"在此情况下左转前为什么必须等待？","o":["因为那辆摩托车","因为那辆红色汽车","因为那名骑行者"],"c":"一辆摩托车行驶在红色汽车后面；由于您改变行驶方向，必须让摩托车驾驶人先行。"},"1.2.09-206-M":{"q":"为什么现在必须等待？","o":["因为那名骑行者","因为那辆蓝色车辆","因为那辆黄色汽车"],"c":"蓝色汽车和骑自行车者都在直行，因此它们享有优先通行权，即使骑自行车者是在人行道上骑行。"},"1.2.10-005":{"q":"你想从一条有下沉路缘石的道路驶入另一条道路。一辆汽车从左侧驶来。这里适用什么？","o":["凡越过下沉路缘石驶入道路者必须等待","“右先于左”规则","下沉路缘石与让行义务无关"],"c":"当存在下沉式路缘（这在居民区中经常出现）时，“左让右”规则不适用。在此您必须等待，直到能够在不危及其他道路使用者的情况下驶入车道。这些道路使用者相对于您享有优先权。"},"1.2.10-006-M":{"q":"你想驶出加油站。哪些说法正确？","o":["我必须向横穿马路的行人让行","我可以双向行驶","我相对从左侧驶来的车辆享有先行权"],"c":"带白色箭头的蓝色交通标志表示“规定行驶方向”。在此您只能右转。此外请注意，如果您想从私人场地驶入街道，必须让行人和车辆等其他道路使用者先行。"},"1.2.10-101":{"q":"驶离车行道边缘时你必须怎么做？","o":["查看后方交通","开启转向灯","看一眼后视镜就足够了"],"c":"任何想从车道边缘驶入行驶车流的人，都必须通过打转向灯表明这一意图。通过查看后视镜以及转头从肩上方观察，即可并入车道——同时须考虑到您相对于行驶车流处于次要地位。"},"1.2.10-104":{"q":"你想驶出交通安宁区并开始在道路上行驶。你该怎么做？","o":["让人行道上的行人先走过","在转弯前示意行驶方向","遵守“右先于左”规则"],"c":"如果您从交通安宁区驶入另一条街道，则必须让行，并让其他道路使用者先行。“左让右”规则在此不适用！转弯前请打转向灯，并特别注意骑自行车者和行人。"},"1.2.10-105":{"q":"你想驶出交通安宁区并开始在道路上行驶。骑行者从左侧驶来。谁必须等待？","o":["我必须等待","骑行者必须等待","每个人都必须停下，然后相互商定谁先行"],"c":"从交通安宁区驶入街道时，“左让右”规则失效。您必须等待行人、骑自行车者和行驶车流中的参与者。"},"1.2.10-106":{"q":"你想驶出地产场地并右转进入一条道路。骑行者从左侧驶来。谁必须等待？","o":["我必须等待","骑行者必须等待","每个人都必须停下，然后相互商定谁先行"],"c":"原则上，您在场地出口处必须等待，并让所有其他道路使用者先行。这也适用于人行道上的行人和骑自行车者。在此要特别小心。"},"1.2.10-107":{"q":"你想驶出地产场地并越过人行道驶入一条道路。必须注意什么？","o":["人行道上的行人不得受到危害","必要时应由他人引导你","首先注意道路上流动的交通"],"c":"从场地经人行道驶上道路转弯时，您必须注意：您必须等待人行道上的行人、自行车道上的骑自行车者以及行驶车流中的参与者。您不得危及其他道路使用者。如有疑问，须由他人引导您驶入车流。"},"1.2.10-108":{"q":"你想驶出地产场地。正确的做法是什么？","o":["我必须等到行人走过出口","如果行人放弃其先行权，我可以继续行驶","我短促鸣喇叭，以便行人让我驶出"],"c":"如果您想从场地出口驶出，必须等待所有其他道路使用者。这既包括行人，也包括骑自行车者。如果有道路使用者放弃其优先权，您可以通行——前提是不危及任何人。"},"1.2.10-109":{"q":"你想驶出停车位并驶入移动的车流。你该怎么做？","o":["我不得危害移动的交通","起步前我必须示意","我必须注意我后方的交通"],"c":"当您从停车位驶出时，不得危及其他道路使用者。请打转向灯表明您想驶上道路。查看后视镜和侧视镜，并通过转头从肩上方观察，确认没有骑自行车者在您的盲区内。"},"1.2.11-003":{"q":"交通拥堵时不得驶入哪些区域？","o":["交叉路口","平交道口","车道入口"],"c":"在交通停滞时，下列区域必须保持畅通，例如为救援车辆留出：交叉路口、铁路道口和人行横道。对于居民区出口，该规则不适用。如果您注意到有人想从自己的场地驶上道路，您应当给该驾驶人驶入道路的机会。"},"1.2.11-004":{"q":"交通拥堵时不得驶入哪些区域？","o":["路口","行人横道","设有锯齿线的公交车站"],"c":"如果交通变慢，只有当您能迅速驶离交叉路口时，才允许驶入。否则必须等待。横向街道的路口、人行横道和铁路道口同样必须保持畅通。但这不适用于公交车站。"},"1.2.11-005-B":{"q":"你该怎么做？","o":["减速，必要时停车","继续行驶，驶上人行道","加速继续行驶，因为对向来车必须等待"],"c":"由于该交通标志，您在此必须等待。指向您的红色箭头表示让对向车辆先行。在任何情况下您都不得驶上人行道。人行道仅供行人使用。"},"1.2.11-006":{"q":"交通拥堵时，道路设施的哪些部分必须保持畅通？","o":["交通汇流处","行人横道","公交车站"],"c":"人行横道（“斑马线”）旨在让行人能够安全、无危险地穿过马路。因此，在任何情况下您都必须保持人行横道畅通。如果您在缓慢行驶的车流中驶入路口（或交叉口），可能会堵住对向的横向交通，或者使左转的对向交通不得不等待过长的时间。这样路口或交叉口会变得更加拥堵，交通受到不必要的更多阻碍。"},"1.2.11-007-M":{"q":"你想继续直行。在此情况下哪些说法正确？","o":["我让该车队通过","我在停车线处等待","我驶越该路口"],"c":"在道路交通中成队一起行进的一群行人、骑自行车者或机动车，称为封闭队列。封闭队列必须有明显标识，且不得被中断。\n因此您必须等待，直到所有车辆都从您身旁驶过，并且在停车线处等候期间一直等待。"},"1.2.11-103-M":{"q":"你想继续直行。正确的做法是什么？","o":["我留在我的车道内等待","如果车流中有足够空间，我向右让出","我超越旁边的车辆并变更车道"],"c":"前方汽车堵住了您所在的车道。尽管如此，您不应在交叉路口前从右侧超车，因为这会太危险。保持车距、减速，必要时停车。当空闲车道畅通且信号灯变为绿色时继续直行。只有当存在足够大的车流间隙时，您才能变换到右侧车道。"},"1.2.11-104":{"q":"你该怎么做？","o":["在左转前停车并保持中央分隔带畅通","平稳转弯，以免妨碍后方交通","在中央分隔带中、另一辆汽车停下的位置停车"],"c":"如果有轨电车轨道穿过左转车道，且当有轨电车驶近时您想左转，重要的是在轨道前方保持足够距离等待。当有轨电车通过后，您才可以左转。"},"1.2.11-105":{"q":"正确的做法是什么？","o":["减速","加速","向左急转"],"c":"如果一名向左移动的骑自行车者行驶在您前方，而此处道路变窄且有对向交通，则您不得超越他。因为在此无法保持1.5至2米的安全距离。"},"1.2.11-107":{"q":"正确的做法是什么？","o":["减速","加速","向左急转"],"c":"您这一侧道路变窄。因此骑自行车者会向左移动。由于有对向交通，您无法以所要求的1.5至2米安全距离超越他。因此您必须等待并跟在他后面。"},"1.2.11-108":{"q":"在哪些情况下即使交通信号灯为绿灯也不得驶入路口？","o":["如果由于交通回堵我将不得不在路口中央停车","如果警察要求我停车","如果路口显示“停车让行”标志"],"c":"在下列情况下，即使信号灯显示“绿灯”，您也不得驶入交叉口：一是交通缓慢行驶时，因为路口必须为救援车辆保持畅通。二是当警察指挥交通并发出与信号灯颜色含义不同的指令时。一般而言，绿灯表示您被允许通行，并优先于其他规定优先通行权的交通标志。警察的指令具有最高效力，优先于信号灯。"},"1.2.11-109":{"q":"在哪些情况下即使享有先行权也不得驶入路口？","o":["由于我方向交通回堵，我将不得不在路口内等待","我将妨碍一辆闪着蓝灯鸣着警笛的车辆","我想左转，并由于对向交通而不得不在路口内等待"],"c":"如果交通变慢，只有当您能迅速驶离且不堵塞交叉口时，才可凭绿灯或优先通行权驶入交叉口。这对于为警察、消防和救护等救援车辆保持路口畅通尤为重要。如果听到警笛声，您必须小心地驶向交叉口，且只有在不妨碍任何救援车辆时才可继续通行。左转时，您必须缓慢驶入交叉路口并在那里等待，直到能在没有对向来车的情况下自由通行。"},"1.2.11-110-M":{"q":"为什么在此必须减速并随时准备制动？","o":["因为那名骑行者","因为那辆绿色车辆","因为那名行人"],"c":"您不必因为行人而减速。他离狭窄处足够远。红色车辆处于停车状态，因此也不是减速的理由。但是，由于骑自行车者应减速。他可能不伸手示意就变换车道，从而造成危险情形。"},"1.2.11-111":{"q":"为什么必须继续制动？","o":["因为垃圾车","因为蓝色货车","因为骑行者"],"c":"一辆垃圾车迎向蓝色卡车驶来，迫使其停车。由于垃圾车转弯时可能会甩出并驶入您的车道，您需要等待该车辆正确并入。骑自行车者不是刹车的理由。"},"1.2.11-112":{"q":"你想直行。你该怎么做？","o":["在停车线处","在黄色和蓝色车辆之间","直接跟在黄色车辆后方"],"c":"在交通停滞时，即使有绿灯或优先通行权，您也不得堵塞任何交叉路口或横向路口。您可能需要在停车线处等待，且在前方车辆驶离足够远之前不得紧跟上前。"},"1.2.11-113-M":{"q":"何时可以开始行驶？","o":["一旦货车驾驶人用手势明确表示让出其先行权","如果我不危害或明显妨碍交叉方向交通","立即，因为货车驾驶人在催促我这样做"],"c":"卡车已通过闪灯示意放弃其优先通行权。因此，在卡车驾驶人明确以手势放弃其优先权，并且您不危及横向交通或不对其造成重大妨碍之后（方可通行）。"},"1.2.11-114-M":{"q":"何时可以转弯？","o":["只有当货车驾驶人用手势明确表示放弃其先行权时","只有当我不危害或明显妨碍交叉方向交通时","立即，因为货车驾驶人在催促我这样做"],"c":"由于您想左转，对向交通享有优先权。只有当卡车驾驶人明确以手势放弃其优先通行权时，您才能在适当顾及对向交通的情况下通行。此处闪灯并不足够。"},"1.2.11-201-M":{"q":"你想直行。如果红色货车在“绿灯”时立即驶出，你该怎么做？","o":["我等待并让货车起步","必要时我发出警告信号","我也立即驶出"],"c":"您应当在此等待，让卡车先行起步，必要时发出警示信号，因为它看起来要右转。（右转向灯）"},"1.2.11-202-M":{"q":"你想直行。在此情况下你应把自己摆在什么位置？","o":["在货车右后方","在货车左后方","直接在摩托车后方"],"c":"卡车偏转让右转，请等待其完成转弯。然后您可以直行。"},"1.2.12-001":{"q":"哪里禁止临时停车？","o":["在平交道口","在道路狭窄路段和视线受阻处","在行人横道正后方"],"c":"“停车”（Halten）是指车辆因与交通无关的原因停车少于3分钟，且驾驶人不离开车辆。如果驾驶人停车时间更长和/或离开其车辆，则称为“泊车”。然而，驾驶人并非随处都可以停车，以免危及其他道路使用者。\n例外情况为：\n- 禁止停车区\n- 穿越铁轨的过渡段，因为存在与列车碰撞的风险\n- 净宽小于3米的狭窄、难以看清的地点\n- 看不见的弯道\n- 坡顶\n- 人行横道及其前方区域（距离不少于5米），但不包括其后方区域。"},"1.2.12-002":{"q":"哪里禁止驻车？","o":["在车行道边缘，如果这会妨碍他人使用专用停车区域","在城镇外的干道上","在城镇内的干道上"],"c":"一旦您在没有与交通相关原因的情况下停车或离开车辆超过三分钟，这就称为泊车。泊车并非随处都允许。在设有停车限制或禁止泊车的区域，您不得泊车——也不得在妨碍或阻碍其他道路使用者之处泊车。停车限制同样适用于城镇外的先行道路。请使用边带或停车位。"},"1.2.12-103":{"q":"哪里禁止临时停车？","o":["在车行道上，如果右侧有足够宽的应急车道","在路面上标有方向箭头时，在车道分隔线之间","在出租车候客站"],"c":"您只能在不会危及其他道路使用者之处停车。例如，当存在由实线白线与车行道隔开的应急车道时，即为这种情况。\n您不得在以下位置停车\n- 用于驶入优先通行权（让行）的标线车道上\n- 如果设有应急车道，则不得在车行道上\n- 在公交车站或其他公共交通站点\n- 在出租车候客站，以免堵住出租车的进出通道\n- 在高速公路或高速公路上，应急车道亦不例外。\n注意两轮车！"},"1.2.12-104":{"q":"哪里禁止临时停车？","o":["在行人横道上及行人横道前5米以内","在行人横道正后方","在井盖和其他道路盖板上"],"c":"在人行横道上以及其前方五米范围内，您不得停车，因为您会妨碍其他驾驶人对行人的清晰视线。这样行人就可能被过晚发现。人行横道之后您可以停车。在井盖上停留是允许的，但不得泊车。"},"1.2.12-105":{"q":"哪里禁止驻车？","o":["在车行道边缘，如果这会妨碍他人使用专用停车区域","在下沉路缘石前","在行人横道正后方"],"c":"您不得在道路边缘泊车，从而堵住标线停车区域并因此妨碍其他道路使用者。在下沉式路缘前方也禁止泊车，例如这些路缘位于车道入口前方。下沉式路缘应当方便轮椅使用者横穿马路。安全且因此允许的泊车位置是人行横道之后。"},"1.2.12-106":{"q":"在哪里允许沿行驶方向在左侧驻车？","o":["在单行道上","在右侧有轨道处","在右侧禁止驻车处"],"c":"您只能沿行驶方向在道路右侧泊车。即使所有停车位都在左侧，也是如此。如有必要，您应视情况掉头。唯一的例外是单行道，因为其只用于一个行驶方向。如果右侧有轨道，则您也必须靠左侧泊车，但始终要遵守停车限制。"},"1.2.12-107":{"q":"谁属于驻车？","o":["凡停车超过3分钟者","凡离开其车辆者","凡在关闭的平交道口栏木前等待超过3分钟者"],"c":"如果汽车驾驶人有意使车辆停下并在那里停留超过三分钟，或者离开停着的车辆，则视为泊车。在大门前停车等待不算泊车，无论时间多长，因为这种停顿是由交通造成的。"},"1.2.12-108":{"q":"在行人横道前临时停车或驻车时必须留出多少最小距离？","o":[],"c":"在人行横道上及其前方5米范围内，禁止停车和泊车。这样，作为汽车驾驶人您可以清楚地看到人行横道，行人也能很好地观察交通情况。"},"1.2.12-109":{"q":"在交叉路口前、后多少米以内禁止驻车？","o":[],"c":"在可能危及他人的区域禁止泊车。\n交叉口或路口前后各需保持5米距离，以保证对交通有足够的视线。"},"1.2.12-110":{"q":"在城镇外，在圣安德鲁十字（铁路道口标志）前驻车时必须留出多少最小距离？","o":[],"c":"在设有圣安德鲁十字标志的铁路道口处，不得在50米距离内遮挡对道口的视线，以便为等候的车辆留有足够空间。"},"1.2.12-111":{"q":"你想在城镇内一个圣安德鲁十字前驻车。必须留出多少最小距离？","o":[],"c":"在设有圣安德鲁十字的铁路道口处，轨道车辆享有优先权。\n为避免遮挡对铁路线的视线，必须保持5米的安全距离。"},"1.2.12-112":{"q":"在公交或有轨电车站牌前、后多少米以内禁止驻车？","o":[],"c":"不得在停车标志前后15米范围内泊车，以便公共交通车辆可以无障碍地驶近、停靠和驶离。"},"1.2.12-113":{"q":"在不阻碍公交车的前提下，你在公交车站最多允许临时停车多长时间？","o":[],"c":"停车时间限制为最长3分钟。如果车辆停车超过3分钟，则视为泊车。因此只允许停车3分钟。"},"1.2.12-118":{"q":"哪些车辆允许在其他车辆旁的第二排临时停车？","o":["出租车，在交通状况允许时供乘客上下车","任何车辆，前提是开启危险警示灯"],"c":"即使开启危险警示灯，也只有出租车允许在第二排等候。出租车属于公共交通。如果您让老人或残障人士上下车，则例外情况可以被容忍。"},"1.2.12-120-M":{"q":"谁停错了？","o":["那辆深色汽车","那辆浅色汽车","两辆车都"],"c":"在应急车道上，右侧的车辆允许等候。但是，不允许在实线左侧等候。左侧的车辆属于违章停车。"},"1.2.12-121-M":{"q":"谁驻车错误？","o":["那辆白色汽车","那辆深色汽车","两辆车都不是"],"c":"锯齿状线条表示延长或缩短停车或泊车禁令。如果没有路面边线标线，则适用停车标志前后最长15米的泊车禁令。在此情形下，白色汽车停错了，因为它停在标线上。深色汽车则泊车正确。"},"1.2.12-122":{"q":"何时不得在右侧车道驻车？","o":["如果车道右侧有足够铺装的应急车道","如果车道内嵌有轨道","如果车道右侧有合适的停车车道"],"c":"一般而言，如果泊车可能危及其他道路使用者，则禁止泊车。视线受阻也属于此种情况。因此这三种情形下都不允许泊车。"},"1.2.12-123-M":{"q":"在此必须注意什么？","o":["不允许在车行道分界线左侧临时停车","行驶较慢的车辆必须尽可能使用应急车道","任何时候都禁止驶越车行道分界线"],"c":"绝不要在车道标线左侧等候。您会阻碍甚至危及后面的车辆。边带是为泊车、等候和慢速车辆设计的。作为慢速行驶的驾驶人，您必须使用这样足够宽且稳固的边带行驶。在此情形下，您可以越过作为正式车道边界的粗实线行驶。"},"1.2.12-124":{"q":"哪些车辆可以在车行道上停放在其他停放车辆旁边？","o":["所有出租车，当乘客上下车时","所有车辆，当装卸货物时","所有车辆，当开启危险警示灯时"],"c":"在例外情况下，只有当乘客上下车时，出租车才允许在第二排停车。"},"1.2.12-125":{"q":"哪里禁止临时停车？","o":["在汇入和驶出车道上","在标有方向箭头的车道上","在地产场地出入口前"],"c":"您不得在加速车道或减速车道上等候。在带有方向箭头的车道上，您也不得停车。这不适用于通往场地的车道入口。"},"1.2.12-126-M":{"q":"谁停错了？","o":["那辆红色汽车","那辆黄色汽车","两辆车都"],"c":"在人行横道上及其前方五米范围内，禁止等候。该规定的目的是在此交通情形下确保对驶近车辆和有意过街的行人有清晰的视线。"},"1.2.12-128-M":{"q":"在此你可以在哪里驻车？","o":["在左侧和右侧应急车道上","仅在左侧应急车道上","仅在右侧应急车道上"],"c":"在单行道上，您只允许沿一个方向行驶。如果左右两侧都有边带，则您可以左右两侧都泊车。"},"1.2.12-129":{"q":"一条自行车道在你车行道右侧并行。在交叉口前、后多少米以内禁止驻车？","o":[],"c":"此处，在交叉路口和路口前8米范围内禁止泊车。"},"1.2.12-130":{"q":"一条自行车道在你车行道右侧并行。在丁字路口前、后多少米以内禁止驻车？","o":[],"c":"此处，在交叉路口和路口前8米范围内禁止泊车。"},"1.2.12-131":{"q":"你在街道右边缘寻找驻车之处。你车道右侧没有自行车道。在路口前、后多少米以内不得驻车？","o":[],"c":"为了不限制视线，您不得在交叉路口前后5米范围内泊车。"},"1.2.12-132":{"q":"哪里禁止临时停车？","o":["在消防通道前","在任何单行道上","在禁停区"],"c":"当车辆因非交通原因停车少于3分钟且驾驶人不离开车辆时，称为停车。如果驾驶人停车时间更长和/或离开车辆，则称为泊车。您并非随处都可以停车，例如以免危及其他道路使用者。消防通道和禁停区等不在此列；此处对泊车和停车加以区分。这不适用于所有单行道。"},"1.2.12-133":{"q":"你在车行道右边缘寻找驻车之处。一条自行车道在车行道右侧并行。在路口或交叉口前多少米以内禁止驻车？","o":[],"c":"为避免妨碍视线，您不得在路口或交叉路口前后8米范围内泊车。"},"1.2.16-001":{"q":"看到危险警示灯闪烁时必须预料到什么？","o":["一辆正在下儿童的校车","一辆被牵引的汽车","一辆抛锚的货车"],"c":"驾驶人在察觉危险警示灯时必须特别谨慎。汽车驾驶人可能出于各种原因使用它。其中一个例子是常规公交车想让儿童上下车。此外，当车辆被拖曳时，被拖曳的汽车和牵引车都会打开危险警示灯。发生故障时也通过打开危险警示灯来示意，并尽快停在道路边缘。"},"1.2.16-002":{"q":"如果看到一辆开启危险警示灯的车辆，应当怎么做？","o":["我降低车速","我做好应对突发危险的准备","我照常继续行驶"],"c":"如果危险警示灯亮起，可能有多种原因和缘由。为安全起见，您应当减速，并格外注意地从该车辆旁驶过。"},"1.2.16-101":{"q":"在城镇外，允许出于哪些目的使用喇叭？","o":["作为警告信号","作为超车信号","作为呼唤信号"],"c":"您可以通过鸣笛或闪灯来表明超车意图。您也可以使用喇叭或闪灯来警示其他道路使用者并提醒他们注意危险。在没有具体危险情形的情况下把喇叭当作招呼信号使用，是不允许的。"},"1.2.16-102":{"q":"在城镇内，允许出于哪些目的使用喇叭？","o":["作为警告信号","作为超车信号","作为呼唤信号"],"c":"在城镇内道路，驾驶人只有在出现危险情形时才可以使用喇叭作为警告信号。由于会造成不必要的噪音扰民，在城镇内道路出于打招呼目的或表示想超车而使用喇叭是不允许的。只有在城镇外，您才可以使用喇叭或闪灯来表明超车过程。"},"1.2.16-103":{"q":"在隧道内发生抛锚时应当怎么做？","o":["开启危险警示灯","如有可能，将车辆停入紧急停车带","为保险起见让发动机继续运转"],"c":"在隧道内，后续交通的替代选择很少。因此，如果发生故障，尽可能停在标出的紧急停车湾内。打开汽车的危险警示灯，并关闭发动机，因为隧道内废气中毒风险很高。"},"1.2.16-104":{"q":"你在隧道内行驶，驶近堵车车流的末端。应当怎么做？","o":["开启危险警示灯","掉头并驶离隧道","在堵车末端关闭发动机并离开车辆"],"c":"如果您发现前方有交通堵塞，重要的是立即打开危险警示灯，提醒后面的驾驶人注意即将出现的情况。这样他们就能更好地应对该情形。在交通堵塞期间，汽车驾驶人应当关闭发动机，但不要离开车辆。隧道内不允许掉头。"},"1.2.17-001":{"q":"关于车辆的照明装置，必须注意什么？","o":["必须安装正确","必须保持清洁","必须处于正常可用状态"],"c":"汽车驾驶人必须正确安装车辆上的照明设备。除了功能完好之外，照明设备还必须清洁，以便其他驾驶人在恶劣天气或隧道内能看到您。"},"1.2.17-101":{"q":"哪些情况会导致即使是近光灯也令对向车辆眩目？","o":["前照灯调整过高","灯泡安装不正确","车辆超载"],"c":"前照灯调得过高、灯泡安装错误，或装载汽车的方式不当，都可能使对向交通以及前方行驶的汽车驾驶人产生眩目。后部偏重的装载会改变近光灯锥体的半径；它会上移并导致危险的眩目。您应当了解您的汽车上的前照灯光束高度调节装置。"},"1.2.17-102":{"q":"如何避免近光灯使对向车辆眩目？","o":["可根据车辆载重调节前照灯照射范围","各前照灯只能使用许可的灯泡","每次维修后都应检查前照灯的设置"],"c":"为了避免使对向交通眩目，您应当注意近光灯的调节情况，并在前照灯修理或新安装之后进行调节。如果需要更换灯泡，只应使用经批准的灯泡。"},"1.2.19-001":{"q":"在铁路道口，一名铁路员工挥动白-红-白三色旗。这意味着什么？","o":["必须在铁路道口前停车等待","可以谨慎地通过铁轨","该旗只对火车司机有意义"],"c":"如果一名铁路员工在铁路道口前挥动白-红-白旗，您必须在道口前保持安全距离等待。挥旗意味着铁路道口被封锁，直到列车通过且铁路员工停止封锁。"},"1.2.19-002":{"q":"在什么情况下必须在铁路道口等待？","o":["红色闪光信号亮起时","栏杆正在放下时","铁路员工挥动白-红-白三色旗时"],"c":"在下列情形下，所有道路使用者都必须在铁路道口前立即停车等待：当信号系统的红色闪光灯亮起时，当栏木开始下降时，当栏木关闭时，当工作人员挥动白-红-白旗时。您必须等到封锁再次解除。"},"1.2.19-003":{"q":"你驶近一个设有半幅栏杆和闪光信号的铁路道口。红色信号正在闪烁，但栏杆仍然开着。应当怎么做？","o":["在圣安德鲁十字标志前等待","只要半幅栏杆还开着就通过","如果看不到轨道车辆，就通过铁路道口"],"c":"当铁路交通前的栏木系统红色闪光灯亮起时，所有道路使用者都必须在斜十字标志前停车。即使半栏木仍然开启，也严禁继续行驶。栏木关闭速度很快，可能夹住车辆。轨道车辆以高速驶近，且制动距离长达数百米。因此它们无法对障碍物作出随机应变的反应。"},"1.2.19-004":{"q":"在铁路道口，一名铁路员工挥动红色灯。这意味着什么？","o":["必须在铁路道口前停车等待","可以谨慎地通过铁轨","红色灯对你没有意义"],"c":"如果一名铁路工作人员用红灯防护一处交通量小的铁路道口，所有汽车驾驶人和其他道路使用者都必须在道口前保持安全距离等待。挥动红灯意味着轨道不可通行，列车享有优先权。"},"1.2.19-005":{"q":"你驶近一个栏杆开着的铁路道口。应当怎么做？","o":["以适中车速驶近，并沿铁路线瞭望","如果因交通拥堵而不得不停在道口上等待，则应在道口前停车等待","保持原速通过，因为在这种情况下道路交通总是优先"],"c":"尽管如此，当您接近栏木开启的铁路道口时，仍必须减速并注意轨道。汽车驾驶人应当确认该道口可以在无危险的情况下通过，且没有轨道车辆驶近。当您看到可能出现交通堵塞时，必须保持距离，以免有汽车最终停在铁轨上。轨道交通始终享有优先权。"},"1.2.19-008":{"q":"在工业区入口处设有一个圣安德鲁十字标志，并带有附加标志“工业区，轨道车辆优先”。必须注意什么？","o":["只能以适中的车速驶近铁路道口","在所有铁路道口轨道车辆都优先","在没有圣安德鲁十字标志的铁路道口，机动车优先"],"c":"即使整个工业区内的铁路道口既没有栏木也没有斜十字标志，机动车驾驶人也必须让所有轨道车辆先行。始终要预料会有列车驶来，准确观察铁路线路，并且只以适中的速度接近铁轨。"},"1.2.19-009":{"q":"该铁路道口的栏杆已经有一段时间没有动作了。正确的做法是什么？","o":["我不通过该铁路道口","我向警方报告该故障","我格外小心地通过该铁路道口"],"c":"显然铁路栏木发生了故障。因此使用该铁路道口不安全。在任何情况下都不得穿越该铁路道口；如果有列车驶近，您的生命会面临严重危险，而且还存在您无法从栏木下通过而被困住的风险。\n请将该铁路道口的故障告知警方，以便问题得到修复。"},"1.2.19-101":{"q":"你沿着林间道路行驶，驶近一个没有圣安德鲁十字标志的铁路道口。应当怎么做？","o":["以适中车速通过，并确认是否有轨道车辆驶近","注意倾听，以防轨道车辆以鸣笛或敲钟示意其驶近","无需特别防范地通过，因为此处轨道车辆必须等待"],"c":"即使没有斜十字标志，汽车驾驶人在田间和森林道路上也必须始终让轨道车辆先行。以适中的速度接近铁路道口，并倾听是否有列车驶近。观察轨道，必要时停车，让轨道车辆通过。"},"1.2.19-102":{"q":"在铁路道口栏杆关闭时应当怎么做？","o":["在圣安德鲁十字标志前等待，且不阻挡路口","天黑时如有可能开启示宽灯","占用路面空间，直接在栏杆前等待"],"c":"在栏木关闭的铁路道口处，所有汽车驾驶人都必须在斜十字标志前等待。如果没有交通标志，则必须保持到铁轨的安全距离。等候时注意不要堵住交叉路口或横向路口。在黑暗中必须开启照明，示宽灯即可。"},"1.2.19-104":{"q":"列车通过后，何时才允许通过设有闪光信号但无栏杆的铁路道口？","o":["红色闪光信号熄灭时","列车通过后立即通过，即使红色闪光信号仍在闪烁","对向车流一启动就通过，即使红色闪光信号仍在闪烁"],"c":"只有在红色闪光灯熄灭之后，您才可以穿越铁路道口，因为可能还有另一列车驶来。不要被对向交通误导：如果对侧等待的汽车驾驶人在列车通过后就过早地起步行驶，您也不要跟着开。"},"1.2.19-105":{"q":"你驶近一个设有栏杆的铁路道口。如果因交通拥堵而可能不得不停在铁轨上，应当在何处等待？","o":["在圣安德鲁十字标志前","紧靠铁轨前","与栏杆齐平处"],"c":"如果由于交通缓慢而无法迅速通过铁路道口，那么请在斜十字标志前停车。禁止直接在铁轨前或栏木高度处等候，因为在这些位置您可能被列车的动压或列车本身撞到，或被栏木困住。"},"1.2.19-106-B":{"q":"在此应当怎么做？","o":["以适中车速驶近并等待","可以通过，因为车道只是对向方向被占用"],"c":"如果铁路工作人员用白-红-白旗防护一处交通量小的铁路道口，所有汽车驾驶人和其他道路使用者都必须在安全距离处等待。在任何情况下都不应在此穿越铁轨，因为挥旗表示该道口被封锁，列车享有优先权。"},"1.2.19-107":{"q":"城镇内一处铁路道口的栏杆已关闭。应当在何处等待？","o":["在圣安德鲁十字标志前","在最后一个标志柱前","在第一个标志柱前"],"c":"卡车和挂车车辆（允许总质量超过7.5吨的车辆）只要求在城镇外铁路道口前方的标记（80米）之后等待。在城镇内，它们必须在斜十字标志前等待。"},"1.2.19-109":{"q":"该交通标志表示什么？","o":["提示存在架空电线","轨道交通始终优先","当轨道车辆驶近时必须始终等待"],"c":"斜十字标志表示此处轨道交通享有优先权。作为汽车驾驶人，当有轨道车辆驶近时您需要等待。斜十字中的闪电符号表示有电气化架空线，这对超高特种运输很重要。"},"1.2.19-110":{"q":"在铁路道口之前、通往右侧道路的路口之前，设有一个不带铁路道口标志的灯光信号。红灯亮起。应当在何处等待？","o":["在停止线处","如果没有停止线，则在灯光信号前","注意观察其他交通后，我可以一直行驶到铁路道口"],"c":"遇到红灯时，汽车驾驶人无论如何都必须停车。为了不堵住从右侧道路驶来的交通，红灯设在距离实际铁路道口数米处的地方。请在停车线处等待，如果没有停车线则在灯号处等待。"},"1.2.19-111":{"q":"在此情况下必须怎么做？","o":["- 在铁路道口前停车","- 从旗手左侧驶过","- 从旗手右侧驶过"],"c":"铁路工作人员防护该铁路道口，因此您应当在圣安德鲁十字前停车。"},"1.2.19-112":{"q":"在铁路道口，若红色闪光信号呈指向右侧的箭头形状，谁必须停车？","o":["右转的交通","直行的交通","左转的交通"],"c":"在交叉路口或横向路口之后的铁路道口后方，可以见到一个带向右箭头形式的红色闪光灯的斜十字标志。向右的箭头表示右转的汽车驾驶人必须等待。"},"1.2.19-113":{"q":"该交通标志组合表示什么？","o":["- 我可以最高 10 公里/小时的车速驶近该处","- 我可以最高 10 公里/小时的车速通过该处","- 轨道车辆可以最高 10 公里/小时的车速在该处通过"],"c":"该交通标志组合向您表明这是一个铁路道口。汽车驾驶人只允许以10公里/小时的速度接近铁路道口，并以该速度通过。"},"1.2.19-114":{"q":"现在正确的做法是什么？","o":["我在铁路道口前等待","我谨慎地通过铁轨","我在铁轨处等待"],"c":"如果由于交通堵塞或交通停滞，存在您可能停在铁轨上的风险，请在斜十字标志前停车，等到能够安全且迅速地通过铁路道口时再通行。当停在铁轨上的汽车无法避开来临的列车时，就会发生致命事故。"},"1.2.19-115":{"q":"你驶近一处铁路道口。栏杆开始放下。应当怎么做？","o":["我在铁路道口前等待","如果看不到火车就继续行驶","我开启危险警示灯"],"c":"当驾驶人接近正在下降的栏木时，他/她必须在铁路道口前等待。即使还看不到轨道车辆，也是如此。不需要打开危险警示灯。"},"1.2.19-116":{"q":"在哪些地方必须预料到会遇到没有技术防护设施的铁路道口？","o":["在较少使用的道路上","在工业区和港区","在土路和林间道路上"],"c":"在工业和港口区域、田间和森林道路上，以及交通量小的道路上，您应当预料到会有无栏木或无信号灯（技术上无防护）的铁路道口。"},"1.2.19-117":{"q":"你想通过一个栏杆开着的铁路道口。哪项正确？","o":["我必须用适中的车速驶近铁路道口","我预判通过铁路道口时路面会有颠簸","我只允许以步行速度通过铁轨"],"c":"即使栏木开启，您也必须始终谨慎并以适中的速度接近铁路道口。这样您才有足够时间对可能出现的颠簸和危险情形作出反应。这里的适中速度并不是指步行速度，因为您也可以以高于步行的速度行驶。这样可以防止与驶近的列车或正在下降的栏木有关的可能危险情形。"},"1.2.19-118-M":{"q":"现在应当怎么做？","o":["- 在十字标志前停车","- 快速通过铁路道口","- 穿过已打开的栏杆"],"c":"当圣安德鲁十字上方的闪光灯亮起或栏木已下降时，不得穿越铁路道口。"},"1.2.20-001":{"q":"在有轨电车站，乘客正在从车道上上下有轨电车。如果你想从右侧驶过，应当怎么做？","o":["如果会危及或妨碍乘客，则等待","如果能在不危及、不妨碍乘客的情况下驶过，则以步行速度谨慎驶过","发出明确的警告信号并通过"],"c":"在一站下车并步行至人行道，或从人行道步行至有轨电车的电车乘客，相对于车辆交通享有绝对优先权。您作为汽车驾驶人必须等待。只有当可以排除对乘客的阻碍或威胁时，您才可以以步行速度小心地从有轨电车旁驶过。"},"1.2.20-003":{"q":"当一辆公共汽车开启危险警示灯停在公交车站时，应当怎么做？","o":["只能以步行速度驶过，必要时停车","以足够的距离驶过，以排除危及行人的可能","如果可能妨碍乘客，则等待"],"c":"一辆打开危险警示灯停靠在站点的公交车，只允许以步行速度从旁驶过。对向交通同样适用步行速度。驶过公交车时应保持能够排除对乘客的任何危险或阻碍的距离。必要时请等待。足够的距离能改善视线，以便看清向前走出的行人。"},"1.2.20-004":{"q":"必须允许哪些车辆从标记的车站驶离？","o":["公共汽车","校车","出租车"],"c":"您必须让想从标明的站点驶离的公共汽车和校车先行，只要它们表明驶离意图，例如打转向灯。出租车属于例外，因为出租车不受固定站点和时刻表约束。"},"1.2.20-005":{"q":"对向的一辆公共汽车开启危险警示灯，停在同一路面的公交车站。应当怎么做？","o":["减速至步行速度","只有当乘客想横穿车道时才以步行速度通过","以原速通过，因为该公共汽车停在车道另一侧"],"c":"即使公交车在对向交通一侧，只要它打开危险警示灯停靠，您也有义务以步行速度从旁边驶过。即使没有行人想过街，也是如此。同样，必须保持足够大的安全距离，以免危及上下车人员。汽车驾驶人必须保证所有行人安全过街，必要时等待他们。"},"1.2.20-101":{"q":"你驶近一辆在反方向、停在你所在路面公交车站并开启危险警示灯的公共汽车。必须预料到什么？","o":["乘客会横穿车道去乘坐该车","下车的乘客会突然横穿车道","乘客只会在该车危险警示灯关闭后才横穿车道"],"c":"应当预料到，过路人会漫不经心地、毫不注意交通地横穿马路，因为他们还想赶上公交车。对于从公交车下车并在公交车前方或后方走在道路上的人，同样应加以预料。"},"1.2.20-102":{"q":"现在正确的做法是什么？","o":["我暂时跟在公共汽车后面","我以适中的车速超越公共汽车","我变换车道，但不立即超越"],"c":"您必须减速，先跟在公交车后面。只要公交车打开危险警示灯行驶，您就不得超越它。您也不能变换车道，因为您左侧有一辆正在超越您的车辆。"},"1.2.20-103":{"q":"你想驶过一辆停在公交车站的市内公交车。必须注意什么？","o":["- 驶过时保持足够的侧向间距","- 谨慎驶过","- 注意对向来车"],"c":"允许从停靠在公交站点的公共汽车旁驶过。驶过时，您通常会进入对向交通的车道。因此要特别注意对向交通。尽管如此，尽可能贴近公交车行驶仍是错误的。因为这样您可能危及行人。不必以步行速度行驶，但要非常小心地驾驶。"},"1.2.20-104":{"q":"你驶近一辆停在公交车站的市内公交车。驶过时必须注意什么？","o":["必须有足够的侧向间距","我的车速","路面上的行人"],"c":"当公共汽车、有轨电车或指定的校车在站点等候时，您只有在小心且保持足够侧向距离的情况下才可以从旁驶过。如果公交车停在对向交通中，同样适用该规则。可能有人漫不经心地在道路上，您作为汽车驾驶人必须特别注意这一点。"},"1.2.20-105":{"q":"必须做好什么准备？","o":["对向车辆会驶入我这一侧车道","该公共汽车起步时会摆动到我的车道上","乘客会从公共汽车前方走上车道"],"c":"停在您对面的公共汽车将会起步行驶。这样它可能甩到您这一侧道路上。即使是在公交车后面的车辆，在试图超车时也可能驶到您这一侧道路上。作为汽车驾驶人请刹车、靠右行驶，必要时停车。"},"1.2.20-106":{"q":"所有车辆已在路口等待了几秒钟。在此情况下应当怎么做？","o":["我用明确的手势表示放弃我的优先通行权","我第一个驶到路口中央，并在那里停车","我第一个通过该路口"],"c":"在此适用“左让右”的交通规则，每位驾驶人都必须让右侧的车辆先行。为了使该情形得以化解，一名汽车驾驶人必须放弃其优先通行权。您应当通过清楚可辨的手势放弃您的优先通行权，以便所有车辆都能继续通行。"},"1.2.20-107-M":{"q":"在此情况下正确的做法是什么？","o":["我保持在有轨电车后面","我从有轨电车右侧驶过","我从左侧超越有轨电车"],"c":"作为汽车驾驶人，您有义务尊重公共交通及其乘客。在有轨电车停靠且公交站点有人需要过街才能上车的这种情形下，适用如下规定：停靠到有轨电车后方，等待所有乘客上下车。"},"1.2.20-108-M":{"q":"在此情况下正确的做法是什么？","o":["我保持车速","我以更高的警觉性行驶","我现在减速至步行速度"],"c":"乘客可能会走上道路，您应当提高注意力。但您可以保持您的速度。"},"1.2.20-109-M":{"q":"在此情况下你必须注意什么？","o":["行人可能横穿道路","我可以以步行速度驶过该公共汽车","我不得驶过该公共汽车"],"c":"如果公交车停在公交站点并打开警示灯，您只允许以步行速度从旁驶过。这是因为下车的乘客可能在公交站点横穿马路。也可能有人为了赶公交车而跑过马路。\n因此要留意行人，减速，必要时停车。"},"1.2.20-110-M":{"q":"在此情况下正确的做法是什么？","o":["我只允许以步行速度驶过该公共汽车","该[蓝色]轿车必须停车","我可以以原速继续行驶"],"c":"当公交车打开危险警示灯在交通中行驶时，其他车辆必须始终格外照顾。如果公交车打开危险警示灯驶近一个站点，则不得超越它。但是，如果公交车停靠在站点，您可以以步行速度从旁驶过。"},"1.2.20-111-M":{"q":"在此情况下需要考虑到什么？","o":["可能有人横穿道路","我只允许以步行速度驶过停着的公共汽车","我不得驶过停着的公共汽车"],"c":"停靠在站点的公交车，如果处于静止状态并打开危险警示灯，可以以步行速度超越。但是，驶过公交车时始终重要的是格外照顾，以便能及时对危险情形（例如有人突然走上道路）作出反应。"},"1.2.20-201-M":{"q":"在此情况下正确的做法是什么？","o":["我保持在有轨电车后面","我从有轨电车右侧驶过","我从左侧超越有轨电车"],"c":"您不得阻碍或危及乘客。因此请停靠到有轨电车后方，直到您能在不危及乘客的情况下继续行驶。"},"1.2.22-101":{"q":"货物向后超出车尾反光标识的最大距离为多少时，无需设置突出标志？","o":[],"c":"照明灯或制动信号灯标示着车辆的尾部。借此您可以估计正确的安全距离。如果前方车辆有一个突出的物体被作了视觉标记，则它凸出至少一米。您在评估必要的安全距离时应当考虑到这一点，并相应加大安全距离。"},"1.2.22-102":{"q":"货物向后超出车辆车尾反光标识 1 米以上时，在黑暗中必须如何标识？","o":["用红色灯和红色车尾反光标识","用橙色警告牌","通过开启后雾灯"],"c":"如果您运载的货物从车辆尾部凸出超过1米，则必须通过一个红色灯和一个红色反光镜作相应标记。这样货物的末端对后方交通即可见，并能保持相应较大的安全距离。橙色警告牌表示运载须作标记的危险货物。后雾灯不会改善可见性，且不得使用。"},"1.2.22-104":{"q":"仅超载 20% 可能产生什么后果？","o":["制动器可能过载","转向可能变差","车辆承载部件可能承受过大负荷"],"c":"整个车辆设计、行驶性能和汽车重心都由制造商针对某一最大允许载荷极限进行了匹配和测试。超过最大极限可能会对车辆的行驶性能产生负面影响。此外，您还可能面临永久性损坏的风险，例如汽车上承重部件发生变形和断裂。"},"1.2.22-106":{"q":"车辆上的橙色警告牌表示什么？","o":["- 危险货物","- 牲畜","- 易腐食品"],"c":"橙色警告牌表示装载危险货物的车辆，即所谓的危险品运输。其他汽车驾驶人应以此方式得到警示。在发生交通事故时，橙色警告牌可作为救援人员的线索。"},"1.2.22-107":{"q":"如果你想运输货物，必须注意什么？","o":["- 不得妨碍我驾驶","- 即使我制动也不得滑动","- 绝不得超出车辆前端"],"c":"货物必须仔细固定，以免掉落。汽车驾驶人不得因货物而受到妨碍，其视线也不得受到妨碍。必须遵守允许的尺寸和质量限制。在前部，只有在高于2.5米的高度时，货物才允许最多凸出50厘米。该规定降低了追尾碰撞时受伤的风险。"},"1.2.22-108":{"q":"自什么高度起，允许货物向前超出车辆前端最多 50 厘米？","o":["2.50 米","2.00 米","3.00 米"],"c":"如果您的车辆高度不超过2.5米，货物可以向前凸出50厘米。这种最多50厘米的货物凸出在挂车上也是允许的，且绝不得超过，以尽量减少追尾碰撞时受伤的风险。"},"1.2.22-109":{"q":"关于车辆上的货物，必须确保什么？","o":["我的车辆不得超过车轴额定载荷","我必须使用合适的装备防止货物移位","我的车辆最多可超出车辆额定总质量的 5%"],"c":"装载车辆时，您不得超过允许的轴荷。您必须按照公认的工程规则固定货物。"},"1.2.23-001":{"q":"谁对已注册车辆的行驶安全性负责？","o":["驾驶人","车主","机动车责任保险公司"],"c":"车辆的行驶性能状态由车辆所有人以及驾驶人共同负责。驾驶人必须在驾驶前检查车辆的操作可靠性和行驶安全性。所有人必须确保这确实得到执行。这也适用于TÜV（技术监督协会）检验。责任保险不承担此责任。"},"1.2.23-002":{"q":"当你在行驶中发现车辆已不再具备行驶安全性时，必须怎么做？","o":["尽快使车辆退出交通","只有在损坏修复后才能继续行驶","驶往下一家授权经销商"],"c":"如果车辆不具备行驶安全性，驾驶人必须尽快将其从交通中撤出。请注意，驶往最近的修理厂也是被禁止的。只有在损坏修复之后，您才可以继续驾驶。"},"1.2.23-003":{"q":"车辆的哪些缺陷会对道路交通造成危险？","o":["磨损的轮胎","有故障的车尾灯","制动效果不足"],"c":"磨损的轮胎会对抓地力产生负面影响，并可能导致汽车打滑。有缺陷的尾灯会使汽车对周围交通而言可见度降低。制动作用不足会导致制动距离延长，从而带来更高的交通事故风险，尤其是追尾碰撞。这三种缺陷都会威胁交通安全。"},"1.2.23-006":{"q":"你想在驾驶车辆时打电话。必须注意什么？","o":["通话可能使我分心","操作电话可能使我分心","使用免提装置通话不会使我分心"],"c":"在驾驶时打电话或操作电话会使驾驶人分心。即使您使用免提装置，也必须记住，您的部分感官会受到影响，无法完全专注于驾驶。"},"1.2.23-007":{"q":"你想在驾驶时打电话。必须注意什么？","o":["我必须配备免提装置","如果车辆停放在合适地点且发动机完全关闭，我可以不使用免提装置使用电话","如果车辆以步行速度行驶，我可以不使用免提装置使用电话"],"c":"在驾驶时，您只允许使用免提电话。如果您没有免提装置，则必须驶到合适的地点并完全关闭发动机。只有这样您才可以使用手机。在驾驶时无免提设备使用手机是严重违法行为，即所谓的A类违法行为，会受到严厉处罚。"},"1.2.23-008":{"q":"你想在公共道路上使用机动车。必须遵守什么？","o":["机动车必须具备行驶安全性","机动车必须投保责任险","我必须是车主"],"c":"只有当车辆具备行驶安全性并且该车辆已投保责任保险时，您才可以在公共道路上使用车辆。"},"1.2.26-005":{"q":"在斑马线前及斑马线上，适用什么规定？","o":["- 超车","- 停车","- 停放"],"c":"在人行横道前和其上严格禁止超车。也就是说，为了您作为汽车驾驶人始终对斑马线和潜在行人具有良好的视线。在人行横道前五米范围内及人行横道上禁止泊车和停车。一般而言，您必须小心地驶近斑马线。"},"1.2.26-007":{"q":"正确的做法是什么？","o":["我停车，因为一名男子想过人行横道","我缓慢继续行驶，因为没有任何迹象表明有行人想过人行横道","我停车，因为厢式货车后面的一个孩子将要走上车道"],"c":"在人行横道处，您必须让行人过马路。从右侧来的行人跑得很快，可能会跑进街道。请以适中速度行驶，必要时停车。"},"1.2.26-008-M":{"q":"在此情况下哪项正确？","o":["- 不超越[骑自行车者]","- 超越[骑自行车者]，因为看不到对向来车","- 只以适中的车速超越[骑自行车者]"],"c":"您身处人行横道处。在此情形下，您不得在人行横道前和人行横道上超越骑自行车者。"},"1.2.26-009-M":{"q":"遇到这样的交通岛时必须预料到什么？","o":["行人以为他们对道路交通享有优先通行权","骑自行车者不注意交通就横穿道路","行人始终尊重车辆的优先通行权"],"c":"骑自行车者和行人常常认为他们享有优先权。因此请小心驾驶。"},"1.2.26-010-M":{"q":"在此情况下正确的做法是什么？","o":["我密切注视[行人]","我降低车速，必要时做好停车准备","我以原速继续行驶"],"c":"行人在人行横道处始终享有优先权。因此您必须注意行人，并做好减速和停车的准备。"},"1.2.26-108":{"q":"交通信号灯为绿灯。你想右转。对于想过你要转入的那条道路的行人，你应如何应对？","o":["让行人先横穿道路","抢在行人前面快速转弯","鸣喇叭警告行人"],"c":"如果驾驶人想右转且信号灯显示“绿灯”，当行人过马路时，无论有多少行人，他都必须停车。如果横向交通的信号灯显示“红灯”，支路中的行人灯大多为“绿灯”。即使没有信号灯，也必须让行人优先，此时驾驶人必须停车等待。即使是在驾驶人右侧直行的骑自行车者或驶近右转驾驶人的骑自行车者，也享有优先权，必须让他们通过。"},"1.2.26-109":{"q":"对于想过你要转入的那条道路的行人，你应如何应对？","o":["让行人先横穿道路","抢在行人前面快速转弯","只有当行人走在标线过街处时才等待"],"c":"如果汽车驾驶人想驶入一条被行人横穿的街道，或者行人在该街道上想过马路，驾驶人都必须让行人先行并停车。因此，快速行驶是错误的。无论人行横道是否作了标记，都无关紧要。"},"1.2.26-110-M":{"q":"正确的做法是什么？","o":["等待，因为这两名行人优先","继续行驶，因为这两名行人必须向我让行","从对面来的行人前面通过，因为他必须等待"],"c":"汽车必须等到行人过完马路。如果您想驶入一条正被行人横穿的道路，行人相对于汽车享有优先权。您作为汽车驾驶人必须表现体谅，并且需要停车。"},"1.2.26-111":{"q":"在哪些情况下必须特别谨慎地驶近人行横道？","o":["如果有行人想横穿道路","如果对人行横道的视线受限","如果已有另一辆车在人行横道处等待"],"c":"一般而言，机动车驾驶人必须小心地驶近人行横道。当有人想过马路，或者人行横道的视线受到限制（例如被停在人行横道前方的一辆车挡住）时，尤其需要特别小心。在任何情况下您都不得超越这辆车。"},"1.2.26-112":{"q":"一处人行横道被雪覆盖；只有“人行横道”标志可见。一名行人想横穿道路。正确的做法是什么？","o":["谨慎制动","让行人先通过","谨慎继续行驶，因为看不到路面标线"],"c":"该标志明确表示此处有人行横道。作为汽车驾驶人，当道路被雪覆盖时，您的行为也必须与在可见的人行横道处一样。请特别小心地驶近斑马线，刹车，必要时停车。"},"1.2.26-113":{"q":"一名行人想通过人行横道横穿道路。应当怎么做？","o":["我做好停车准备","我不超车","我格外小心地超越等待的车辆"],"c":"以适中的速度驶近人行横道，并示意您愿意让行。如果与行人有目光接触，可通过手势予以强调。如果降低速度不足以让行人通过该路段，您就必须停车。在人行横道前和人行横道上，不得超越任何其他车辆。"},"1.2.26-114":{"q":"在此情况下应当怎么做？","o":["我让行人先横穿道路","我在人行横道这一侧等待，直到蓝色车辆完成转弯","我紧跟在蓝色车辆后面停下"],"c":"如果在人行横道处有行人明确想过马路，您必须以适中的速度驶近并等待。当交通停滞时，您不得在人行横道上停车。在这种情况下，您还必须保持横向路口和交叉路口畅通。"},"1.2.26-115":{"q":"为什么驶近人行横道时采取防御性驾驶方式尤为重要？","o":["为了使行人不过度惊慌","为了避免追尾碰撞","为了使后方车辆更容易超车"],"c":"防御性地驶近该区域并缓慢刹车，可以向行人表明您正在履行等待义务。这样行人就能安全地过马路。此外，通过及时停车，您还可以避免追尾碰撞。"},"1.2.26-116":{"q":"你在一条双车道单行道的左侧车道行驶。在你前方约 30 米处，一辆货车在人行横道前停靠在右侧车道。应当怎么做？","o":["我以适中的车速驶近","我发出警告信号并驶过货车","我迅速地继续行驶"],"c":"在任何情况下都不得在人行横道前和人行横道上超越车辆。卡车挡住了对人行横道的视线。它可能会让行人过马路。即使它停在另一条车道上，也不得超越它。请以适中的速度驶向人行横道，并做好停车准备。"},"1.2.26-117":{"q":"一名骑自行车者想不下车在人行横道处横穿道路。应当怎么做？","o":["我让骑自行车者先横穿道路","我鸣喇叭并继续行驶，不向骑自行车者让行","我在紧靠人行横道处才制动"],"c":"该骑自行车者的行为违反了道路交通规定。他必须在穿越人行横道前下车推行。但是，作为小心地以适中速度驶近人行横道的汽车驾驶人，您不会撞倒他。那样也会违反道路交通规定。必要时，您要为位于人行横道上的骑自行车者停车，并让他通过。"},"1.2.26-118":{"q":"你前方有一处人行横道，其后方你所在车道的交通已经排队停滞。应当怎么做？","o":["在人行横道前停车，以便让行人通过","如果看不到人，就在人行横道上等待","在人行横道上等待以缩短堵车"],"c":"当交通停滞时，您不得在人行横道上停车。此处适用与交叉路口和横向路口相同的规则，这些区域同样必须保持畅通。"},"1.2.26-119-M":{"q":"正确的做法是什么？","o":["我等待，因为这两名行人优先","我继续行驶，因为这两名行人必须等待","我抢在[对面来的行人]前面转弯，因为只有[此人]必须等待"],"c":"如果您想转弯并遇到想过马路的行人，您应当注意他们。您必须停车并等候，暂停转弯。"},"1.2.34-002":{"q":"你损坏了一辆停放的车辆。尽管你已等待了适当的时间，受损方仍未出现。必须怎么做？","o":["在被损坏的车辆上留下你的姓名和地址，并立即向警方报告事故","你可以不做进一步处理就离开事故现场","把你的姓名和地址告诉一名未涉事的证人即可"],"c":"在受损车辆上留下个人资料之后，您必须将此事通知附近的警察局。这也可以通过电话进行。不作为会被视为肇事逃逸，属于刑事犯罪，其代价可能超过驾驶执照。常被提及的在受损车辆处的合理等待时间是相对的，并非法律规定的时长。直接联系只会便于处理。"},"1.2.34-004":{"q":"现在正确的做法是什么？","o":["- 离开车辆时留下点火钥匙或应答器","- 通过紧急出口离开隧道","- 留在车内等待事故现场清理完毕"],"c":"如果隧道内发生了事故，并且至少有一辆汽车燃烧并产生烟雾，您必须停车并离开您的汽车。您可以通过应急出口离开隧道，并沿着应急照明灯走。如果没有这些，您必须沿着隧道墙壁摸索前行。由于消防队可能需要将您的汽车移走，点火钥匙或应答器应留在车内。"},"1.2.34-005":{"q":"在德国，可以用哪些紧急电话号码呼叫警察和急救部门？","o":["110","112","115"],"c":"在德国，警察的紧急号码是110，事故救护和消防队的是112。即使您的手机没有余额，这些号码也能拨通。"},"1.2.34-006":{"q":"你卷入一起事故。如被要求，必须向事故另一方出示什么证件？","o":["我的驾驶证","车辆登记证第一部分或行驶许可","责任保险合同"],"c":"在发生交通事故时，所有当事方都必须根据要求出示以下证件：驾驶证和车辆登记证第1部分（登记证书）或行驶执照。此外，您还必须尽其所知提供有关责任保险的信息。"},"1.2.34-007":{"q":"你最先到达有伤者的事故现场。你已保护事故现场并了解了大体情况。此外还必须做什么？","o":["- 对伤者实施急救","- 通知急救部门","- 记录事故"],"c":"在您照料伤者之前，必须先通知救护车服务，之后您才有义务对伤者实施急救。"},"1.2.34-008":{"q":"你在一个停车场卷入一起事故。车辆损坏轻微。所有相关方一致认为无需通知警方。现在对理赔处理有帮助的做法是什么？","o":["从多个角度拍摄事故现场","与相关方交换必要信息","在事故报告中描述事故原因"],"c":"您应当与事故另一方交换最重要的信息，以便能够取得联系。您还应当共同记录事故经过。用照片记录损坏情况。这样保险公司就能更好地评估和评定损失。"},"1.2.34-009":{"q":"你的车辆损坏了他人停放的车辆。尽管等待了适当的时间，受损车辆的车主仍未出现。现在正确的做法是什么？","o":["- 在事故现场留下我的姓名和地址","- 向警方报告事故","- 把我的姓名和地址告诉一名未涉事的证人"],"c":"StVO（道路交通条例）第34条第6款a项至第7款允许您在合理的等待时间之后离开事故现场，前提是您已在事故现场留下姓名和地址，并向警方报告了事故。"},"1.2.34-010":{"q":"你与一辆挂有下列橙色标志牌的车辆发生事故。你看到该车有液体泄漏。正确的做法是什么？","o":["在拨打紧急电话时提供该橙色标志牌的编号","我避免在液体泄漏到的区域内走动","我尝试堵住该车辆的泄漏处"],"c":"带有橙色警告牌的车辆正在运输危险货物。\n在涉及危险品运输的事故中，您在报警时必须说明橙色标牌上的数字。这样报警中心就知道车辆运输的是哪些物质，并能派出相应的专业救援力量。您应当避免接触泄漏的液体，并尽可能保持距离。"},"1.2.34-011":{"q":"在欧洲任何地方，可以用哪个紧急电话号码呼叫急救部门？","o":[],"c":"在欧洲任何地方，您都可以通过拨号112免费联系到报警中心。这会直接将您接通到救援服务、警察和消防队。"},"1.2.34-102":{"q":"你最先到达有伤者的事故现场。应按什么顺序处置？","o":["保护事故现场 - 实施急救 - 呼叫救援部门","实施急救 - 呼叫救援部门 - 保护事故现场","呼叫救援部门 - 保护事故现场 - 实施急救"],"c":"必要行动步骤的正确顺序是：1. 保护事故现场，使后续车辆不会驶入事故现场。2. 对伤者实施急救。3. 通知事故救护车。如果您不是独自出行并且车上有乘客，这三个步骤或其中的一部分可以同时进行。例如，您实施急救，同时一名乘客通知救护车。"},"1.2.34-103":{"q":"你最先到达有伤者的事故现场。通常应首先做什么？","o":["保护事故现场","驶往下一个电话亭并呼叫救援部门","检查伤情的严重程度"],"c":"如果您是第一个到达有伤者的事故现场的人，请保持冷静，并首先保护事故现场作为您的第一项行动。这样您可以主动防止进一步的事故并保护伤者。然后寻找伤者并实施急救。通知救护车。"},"1.2.34-106":{"q":"在高速公路上如何获得帮助？","o":["在高速公路服务区","使用紧急呼叫箱","拨打 112 或 110"],"c":"在高速公路上发生故障或事故时，您可以通过紧急电话以及112或110求助。如果您的车辆还能驶到最近的服务区，您也可以在那里拨打求助电话。"},"1.2.34-109":{"q":"你注意到隧道内发生事故。必须怎么做？","o":["开启危险警示灯","通过紧急呼叫电话通知急救部门","不要离开你的车辆"],"c":"在隧道内发生事故时，驾驶人有义务立即使用危险警示灯提醒后续交通。将车辆停在车行道右侧，如有可能停在应急停车湾内，然后小心下车查看事故现场并进行紧急呼叫。保护事故现场并实施急救。还要注意自身防护、应急出口和紧急电话。"},"1.2.34-110":{"q":"你卷入一起交通事故。必须履行什么义务？","o":["- 如果损坏轻微，迅速移到路旁","- 告知其他相关方我也卷入了该事故","- 经要求向有权获得此信息的人提供我的姓名和地址"],"c":"如果损失轻微，肇事者必须立即靠边停车，以避免交通拥堵和其他危险。他还有义务告知其他当事方他卷入了该事故。如果他不这样做，将被作为肇事逃逸予以追究。这会带来前科并被吊销驾驶证。他必须向有权人员说明自己的姓名和地址。这些只是事故肇事者的一部分义务。"},"1.2.34-111":{"q":"你在乡村道路上发生事故。如何保护事故现场？","o":["我立即开启危险警示灯","我在距事故现场约 100 米处、显眼的位置摆放三角警示牌","必要时，我通过手势等方式警告其他车辆"],"c":"打开危险警示灯是第一项措施，但不足以保护事故现场。故障三角牌在城镇外应设置在事故前方约100米处。如有必要，后续道路使用者需要通过手势予以警示，只要不危及任何人（包括自己）。"},"1.2.34-112":{"q":"在联邦高速公路上，如何找到通往下一个紧急电话的最短路径？","o":["- 轮廓标上的黑色箭头","- 护栏上的方向标记","- 应急车道上的地面标记"],"c":"您可以借助反光柱上的黑色箭头（方向三角）识别通往最近紧急电话柱的最短路线。它们在联邦高速公路上为您指路。"},"1.2.34-113":{"q":"如果卷入一起道路交通事故，你必须履行什么义务？","o":["- 停车并查明事故后果","- 保护事故现场","- 如有人受伤则提供救助"],"c":"事故发生后，汽车驾驶人和所有其他当事方都必须停车，并了解事故的后果。立即着手保护事故现场，以避免进一步的损害。然后对伤者实施急救。"},"1.2.34-114":{"q":"一名驾驶人轻微损坏了另一辆车，并违法离开现场。这可能带来什么后果？","o":["罚款或监禁","吊销驾驶证或驾驶禁令","责令接受医学/心理检查"],"c":"如果您离开道路上的事故现场，就构成了肇事逃逸。根据刑法，肇事逃逸可被处以罚款或最高三年的监禁。\n肇事逃逸可能导致弗伦斯堡（记分系统）记分、最长三个月的驾驶禁令以及吊销驾驶证。在严重违规的情况下，还始终可能被命令接受医学-心理学检查。"},"1.2.36-001":{"q":"一名警察在十字路口指挥交通，尽管交通信号灯正在工作。以什么为准？","o":["警察的信号","交通信号灯的信号","规定优先通行权的交通标志"],"c":"道路交通规定有明确的等级顺序，您必须遵守。因此，警察的效力高于其他一切。其次是信号灯，信号灯又高于交通标志。如果没有交通标志、信号灯或警察，则适用“左让右”规则。"},"1.2.36-002":{"q":"一名警察在设有规定优先通行权交通标志的十字路口指挥交通。以什么为准？","o":["警察的信号","规定优先通行权的交通标志","“右方优先于左方”规则"],"c":"警察的指令具有最高优先权。无论标志如何规定，您都必须服从。交通指挥的优先等级顺序如下：警察具有最高权威。信号灯优先于交通标志。交通标志优先于“左让右”的基本规则。"},"1.2.36-003":{"q":"警察的指令有多重要？","o":["必须服从","只有当其与所设交通标志一致时，才必须服从","它们免除你自己应尽的注意义务"],"c":"驾驶人必须始终遵循警察的标志和指令。其他安排和规则，例如信号灯或交通标志，则排在最后。但是，道路使用者不得忽略应有的注意。"},"1.2.36-004-B":{"q":"哪项正确？","o":["黄色轿车必须驶离十字路口","我必须做好起步准备","我现在可以转弯"],"c":"警察通过其身体姿势和特定的手臂动作发出交通指令。举起的手臂表示：在交叉路口等候的驾驶人不得继续行驶，先前被拦停的驾驶人应做好继续行驶的准备。为此，警察根据指令从身体两侧伸开手臂或将手臂放于身体上。如果警察以胸前朝向驾驶人站立，驾驶人必须停车。如果警察侧身站立而驾驶人看到其侧影，驾驶人就可以以适中速度继续行驶。"},"1.2.36-005-B":{"q":"哪项正确？","o":["在十字路口等待","不停车即转弯"],"c":"警察借助身体手势指挥交通。横向伸出的手臂对着发动机方向表示您必须在交叉路口停车。如果该警员以胸前朝向您站立，则您的行驶方向被拦停。用两只伸出的手臂或贴在身上的手臂，他可以放行该行驶方向。如果警察侧身朝向您而您能看到他的侧影，您就可以缓慢行驶。如果他的手臂向上举起，您必须停车；如果交通被拦停，您可能很快就能继续行驶。位于交叉路口内的车辆必须驶离。"},"1.2.36-006-B":{"q":"哪项正确？","o":["以较快的速度通过十字路口","在十字路口等待警察的进一步指令"],"c":"从侧面看到警察的汽车驾驶人可以穿过交叉路口。他/她可以不停车地驶过交叉路口，因为警察已为其放行了该行驶方向。警察不必伸开手臂。"},"1.2.36-007":{"q":"你从后视镜中看到，紧跟在你的车后面的一辆警车车顶以红色发光字体显示“STOP POLIZEI”（停车 警察）字样。这针对谁？","o":["仅针对你","针对所有后方车辆","针对道路上所有车辆"],"c":"由于该要求显示在正面，并且您正好在警车正后方，所以该要求是针对您的。您依法有义务遵循警察的指令。"},"1.2.36-008":{"q":"紧在你的车前面行驶的一辆警车亮起“BITTE FOLGEN”（请跟随）字样。这意味着什么？","o":["只有你必须跟随该警车","同方向行驶的所有轿车都必须跟随该警车","只有重型货物运输车必须跟随该警车"],"c":"警察可以拦停汽车驾驶人，以进行交通检查和检查其驾驶能力。停车要求可以通过您前方警车上的“请跟随”标志发出。根据法律，您必须遵守该指令。"},"1.2.36-011":{"q":"一辆警车超越你，并随即切入你正前方。车顶以红色发光显示“BITTE FOLGEN”（请跟随）字样。应当怎么做？","o":["- 跟随该警车","- 如果该警车停车则停车","- 停车后让发动机继续运转"],"c":"“请跟随”信号始终适用于紧跟在警车后面的驾驶人。因此，您必须遵循警察的指令，跟在警员后面行驶，并在警车停车时停在其后方。"},"1.2.36-012":{"q":"一辆警车超越你，并随即切入你正前方。车顶以红色发光显示“BITTE FOLGEN”（请跟随）字样。这针对谁？","o":["针对我","针对我所在车道的所有车辆","针对后方跟随的警车和救援车辆"],"c":"警车上的“请跟随”信号适用于紧跟在警察后面的车辆，在此情形下即您。警察可以为了交通检查而拦停您。请跟随警车行驶，并在其停车时停车。"},"1.2.36-013":{"q":"在你前方行驶的一辆车向你出示警察信号牌。这意味着什么？","o":["我必须跟随该车辆直到它停车","我不得超越该车辆","我必须按所示方向转弯"],"c":"基本上，直接行驶在警车后面的驾驶人必须遵循警察发出的信号。如果能够辨认，警察的示意盘也可能针对前方的驾驶人。您不得超越警车，并且必须跟随它。"},"1.2.36-014-M":{"q":"现在正确的做法是什么？","o":["我谨慎地通过该路口","我在路口外等待警察的进一步指令","我让[蓝色车辆]先行"],"c":"在优先通行权的等级中，警察位居第一。基本规则“右先于左”、交通标志和灯光信号在此刻都不起作用。尽管如此，仍要保持注意力，因为其他道路使用者仍可能作出不当行为。"},"1.2.36-015-M":{"q":"此处谁优先？","o":["[红色]轿车","摩托车","我"],"c":"交通由警察指挥，因此红色汽车被允许先行。"},"1.2.36-016-M":{"q":"在此情况下正确的做法是什么？","o":["- 在路口前等待","- 不停车，向右转弯","- 掉头"],"c":"如果交通警察指挥交通，则必须遵循其指令。在此情形下，交通警察站在您前方，面向您并伸开双臂。这意味着您必须在交叉路口等待，来自左右两侧的车辆享有优先通行权。"},"1.2.36-101-B":{"q":"此处适用什么？","o":["可以通过该十字路口","必须等待警察的进一步信号后，才能进入该十字路口","禁止转弯驶离"],"c":"交通警察的手势决定了交通中的行为。如果该警员纵向于您的行驶方向站立而您能看到他的侧影，您就可以继续行驶并右转。右转的驾驶人应迅速穿过交叉路口，只要没有行人和骑自行车者驶近他们。如果您想左转，则驶入交叉路口以确保交通流不受干扰，并等待警察的指令。"},"1.2.37-002-B":{"q":"哪种行为正确？","o":["绿色轿车必须等待","我可以在遵守交通标志的情况下转弯","只有当信号灯显示“绿灯”时我才可以转弯"],"c":"信号灯系统为直行的交通规定优先通行权。左侧的转弯车道没有自己的信号灯。因此左转时，您必须驶入交叉路口区域并等待，直到对向直行车流中出现可供您通过的间隙。在先前分出供右转驾驶人使用的车道上，适用的是交通标志而非信号灯。转弯时注意横向交通。"},"1.2.37-004-B":{"q":"交通信号灯处于黄色闪光状态。正确的做法是什么？","o":["以更高的警觉性驶近，必要时让行","等到信号灯变换"],"c":"黄色闪光灯表示信号灯发生故障。此时改为适用规定优先通行权的交通标志，您必须在此让行。如果没有交通标志，则适用“左让右”规则。"},"1.2.37-007":{"q":"在设有绿色箭头标志的交通信号灯处，允许做什么？","o":["先停车后从右侧车道右转，前提是不妨碍、不危及他人","不停车右转","只有当交通信号灯为绿灯时才可右转"],"c":"黑底绿色箭头的附加标志允许您在红灯处停车后右转。尽管有该附加标志，汽车驾驶人仍必须确保不危及横向交通。这包括行人和骑自行车者。只允许在右侧车道转弯，且只能在停车并确保能够安全转弯之后进行。"},"1.2.37-009":{"q":"在设有绿色箭头标志的交通信号灯处，车辆右转前应在何处停车？","o":["在停止线处","如果没有停止线，则在人行横道或路口前","无需停车"],"c":"汽车驾驶人必须在停车线处停车。如果没有停车线，则无论如何都必须在交叉路口或横向路口前停车。如果交通情形允许，在红灯时也可以右转。右转的驾驶人的行为应当与遇到停车标志时一样。必须考虑并让横向交通的优先通行权。"},"1.2.37-010-M":{"q":"在此情况下应当如何做？","o":["不停车径直通过人行横道","在视线线处停车","在停止线处停车"],"c":"信号灯优先于其他交通标志和车道标线。只要信号灯为绿灯，就不停车地穿过交叉路口。"},"1.2.37-011-M":{"q":"必须在何处等待？","o":["在停止线处","在能沿相交道路观察到的位置（视线线）","与交通信号灯齐平处"],"c":"运行中的信号灯优先于规定优先通行权的交通标志。此外，如果设有停车线，就在那里停车并等待，直到允许您继续行驶。"},"1.2.37-012-M":{"q":"在此情况下哪项正确？","o":["右转的交通可以通过","直行的交通可以通过","左转的交通可以通过"],"c":"如果信号灯变为红色，想直行或左转的汽车驾驶人必须停车等待。如果有一个发光的向右箭头形式的附加信号灯，则允许继续行驶并右转。然而，没有附加信号灯或箭头的信号灯对所有方向都有效。"},"1.2.37-013":{"q":"应当怎么做？","o":["继续行驶","减速"],"c":"信号灯就在您面前从绿色变换为黄色。您的速度为45公里/小时。因此，您太快了，无法减速并在信号灯前停车。而且您后面还有一辆卡车，在紧急制动操作时可能会撞到您。请迅速地继续行驶。"},"1.2.37-015":{"q":"在此情况下哪项正确？","o":["我可以不受阻碍地转弯","我必须让对向交通通过","我必须在路口中央等待"],"c":"基本上，左转时您作为汽车驾驶人必须让对向交通先行。由于在此情形下，对向街角的绿色箭头亮起，您可以假定对向交通的信号灯为红灯。因此，您可以转弯。"},"1.2.37-016":{"q":"你想在设有绿色箭头标志的交通信号灯处右转。正确的做法是什么？","o":["我在路口前停车","我必须确保不妨碍其他道路使用者","我可以右转进入任意车道"],"c":"由于有绿色箭头标志，即使信号灯为红色，您也可以在此信号灯处转弯。为此向右并线，并在信号灯前短暂停车。之后，确保您不阻碍或危及其他道路使用者。还请注意横向交通仍然享有优先权。"},"1.2.37-017":{"q":"应当怎么做？","o":["减速","继续行驶"],"c":"您看到您面前有一个信号灯从绿色变换为黄色。您以40公里/小时的速度行驶。由于您离信号灯仍足够远，您必须减速。"},"1.2.37-018":{"q":"现在正确的做法是什么？","o":["我让横向交通先行","我在停止线处等待下一次绿灯","我迅速通过路口，因为显示的是“黄灯”"],"c":"如果黄色信号灯闪烁，则信号灯系统停止运行。此时适用一般的优先通行权规则。您不在先行道路上；因此，可能的横向交通享有优先通行权。"},"1.2.37-019":{"q":"在什么情况下可以在红灯时通过路口？","o":["为谨慎地给设有蓝色闪光灯并鸣响警笛的救援车辆让出空间","如果路口有警察在指挥交通","任何情况下都不可以"],"c":"在下列情况下，您可以在交叉路口闯红灯：如果您想小心地让行一辆带蓝色闪光灯和警报声的救援车辆，或者如果有警察在交叉路口指挥交通。"},"1.2.37-020-M":{"q":"你现在想在设有绿色箭头标志的交通信号灯处右转。正确的做法是什么？","o":["我先在停止线处停车","我确保不妨碍其他道路使用者","我不停车，以步行速度转弯"],"c":"如果信号灯处有绿色箭头标志，只要您先在停车线处停车，就允许闯红灯。如果没有阻碍或危及其他道路使用者的风险，您可以转弯。"},"1.2.37-021":{"q":"在设有附加标志的交通信号灯控制路口，规则是什么？","o":["- 即使信号灯显示红灯，骑自行车者也允许右转","- 即使信号灯显示红灯，机动车也允许右转","- 骑自行车者必须右转"],"c":"在带有该附加标志的信号灯处，只有骑自行车者即使在红灯时也可以右转。"},"1.2.37-022-M":{"q":"你正对的交通信号灯已经“绿灯”一段时间了。现在正确的做法是什么？","o":["我继续行驶，并做好制动准备，因为信号灯可能变为“黄灯”","我密切注视信号灯","我加速，以确保还能在信号灯为“绿灯”时安全通过路口"],"c":"由于信号灯已经绿了一段时间，它极有可能随时变为黄色。请保持行驶，并做好刹车准备，因为如果它变为黄色，您就必须停车。您不得加速，因为最高允许速度为30公里/小时。"},"1.2.37-101":{"q":"你想左转，信号灯为“绿灯”。你左侧有一辆想直行的有轨电车。哪项正确？","o":["你必须等待","有轨电车必须等待","因为对此没有规则，你们必须自行协商"],"c":"尽管由于绿灯您被允许通行，但您必须让有轨电车先行，因为它继续直行。因此，您应当只驶入交叉路口的一半，并让对向车辆通过，然后才能左转。"},"1.2.37-102-B":{"q":"虽然你想左转，却误入了右侧车道。允许你如何行驶？","o":["直行","向右","在交通信号灯为“绿灯”时向左"],"c":"由于有实线，您在此不得变换车道。只遵循您所在车道上的箭头。从该车道左转将被禁止，并会危及或至少妨碍其他驾驶人。"},"1.2.37-104":{"q":"现在正确的行为是什么？","o":["- 现在出发","- 只有当货车起步时才出发","- 只有当我的信号灯为绿灯时才出发"],"c":"由于此情形是一个两相位信号灯，因此没有绿色信号。红灯熄灭后，您可以赶上卡车。如果卡车后面的空间不足以驶到右侧出口，您就必须在信号灯处等待，直到有足够的空间停车。"},"1.2.37-201-M":{"q":"现在正确的做法是什么？","o":["我让横向交通先行","我在停止线处等待下一次绿灯","我迅速通过路口，因为显示的是“黄灯”"],"c":"信号灯发生故障，因此适用规定优先通行权的交通标志。您必须让行。"},"1.2.38-001":{"q":"一辆亮着蓝色闪光灯并鸣响警笛的车辆驶近。应当怎么做？","o":["为该车辆让出道路","必要时谨慎地驶上人行道","无论如何都要紧急制动并停车"],"c":"蓝色闪光灯和警报声用于诸如汽车事故或房屋火灾等紧急情形。因此，您必须尽快为救援车辆让出通道。为此请缓慢减速，并驶向道路右侧边缘。如有必要，驶上人行道并停在那里。"},"1.2.38-002":{"q":"你听到警笛声。必须问自己哪些问题？","o":["救援车辆是从哪个方向来的？","我是否会阻碍救援车辆？","该车辆到底是否允许使用警笛？"],"c":"如果您听到警报声，首先应当确定救援车辆来自哪个方向。然后您必须考虑可以去哪里，既不阻碍救援车辆继续通行，也不危及自己。"},"1.2.38-003":{"q":"车辆上的黄色闪光灯可以警示什么？","o":["警示施工现场或事故现场的危险","警示异常宽的车辆","警示低速行驶的大型运输"],"c":"黄色闪光灯警告存在需要特别小心驾驶的危险。这些危险是施工或事故现场，或异常缓慢、宽大或很长的车辆。"},"1.2.38-101":{"q":"当车辆开启蓝色闪光灯但未鸣响警笛时，意味着什么？","o":["警示事故或其他危险","警示消防队正在执行任务","一辆救援车正在执勤，正前往其目的地"],"c":"蓝色闪光灯警示事故或诸如出警救火等情形。任何驾驶人都应当让带蓝色闪光灯的车辆通过，因为这可能表示紧急情况、车辆护送或车队。"},"1.2.38-102":{"q":"蓝色闪光灯（不鸣警笛）可以表示什么？","o":["该车辆正在执行任务。你应当让行","对封闭车队的提前警告","不鸣警笛时，蓝色闪光灯没有任何意义"],"c":"没有警报声的蓝色闪光灯表示事故或其他紧急情况——因此您在此也应当让出通道。蓝灯也用于蓝灯行驶期间。它也可以用于保护车队。"},"1.2.38-104":{"q":"一辆亮着蓝色闪光灯并鸣响警笛的救护车跟在你后面。应当怎么做？","o":["我立即让路，且不危及他人","我提示旁边的车辆驾驶人让路","信号灯变绿后我立即让路"],"c":"您有义务尽快为救护车让出空间。注意不要危及其他道路使用者。如有可能，如果您在右侧车道上就向右让行；在高速公路和多车道道路上必须形成一条应急通道。"},"1.3.01-001":{"q":"在没有规定优先通行权交通标志的哪些地点，适用“右方优先于左方”规则？","o":["在十字路口和交叉路口","在车道出入口","在交通安宁区末端"],"c":"在没有规范交通的交通标志的交叉路口和横向路口，适用“左让右”。如果车辆从场地或限制通行区驶出，所有其他道路使用者（包括人行道上的行人和儿童）都享有优先权。"},"1.3.01-002":{"q":"在没有规定优先通行权交通标志的哪些地点，适用“右方优先于左方”规则？","o":["在十字路口和交叉路口","在路缘石下沉的路口","在农用道路或林间道路与其他道路相交的路口"],"c":"在没有先行标志的交叉路口和横向路口，来自右侧的车辆享有优先权。根据其标志牌等级相同的道路同样如此。设有下沉式路缘的车道、车道入口以及田间和森林道路属于例外。如果您在其中一条这样的道路上，必须让其他道路使用者先行。"},"1.3.01-003":{"q":"你驶近一个一时无法看清优先通行权情况的十字路口。应当怎么做？","o":["等待、观察，必要时与他人协商","按照“右方优先于左方”规则通过","直行时总是直接通过"],"c":"有些情形在优先通行权方面不易理解。如果遇到这种情况，请等待并观察其他汽车驾驶人。如果情形仍然难以判断，你们可以通过清楚的手势相互沟通。简单地继续直行或按“左让右”规则行事，风险太大且容易引发事故。"},"1.3.01-007-M":{"q":"正确的做法是什么？","o":["我必须让骑自行车者通过","我必须让[骑摩托车者]通过","我可以抢在骑自行车者前面转弯"],"c":"有必要遵守左让右规则。在驶入交叉路口之前，让从右侧来的摩托车驾驶人先行。接下来，您作为左转的驾驶人，必须让对向的骑自行车者先行。对摩托车驾驶人而言，骑自行车者来自右侧，因此享有优先权。"},"1.3.01-013-M":{"q":"正确的做法是什么？","o":["我可以第一个通过该路口","我必须让[红色货车]转弯","我必须让[骑自行车者]转弯"],"c":"在没有交通标志的交叉路口和横向路口适用左让右。由于没有车辆来自右侧，您可以首先穿过交叉路口。之后卡车行驶，最后是骑自行车者。"},"1.3.01-016-M":{"q":"正确的做法是什么？","o":["我必须让[蓝色货车]通过","我必须让[拖拉机]转弯","[蓝色货车]必须让我通过"],"c":"交通标志“让行”在此规定优先通行权。这意味着您必须等待，让左右两侧的车辆都通过。"},"1.3.01-017-M":{"q":"正确的做法是什么？","o":["我必须让[摩托车]通过","我优先于[公共汽车]","我必须让[公共汽车]通过"],"c":"在此适用交通标志“在下一个交叉路口或横向路口享有优先通行权”。由于您想左转，您必须让对向车辆通过。然后您可以在从右侧驶来的车辆之前转弯。"},"1.3.01-018-M":{"q":"正确的做法是什么？","o":["我必须让[摩托车]通过","我优先于[公共汽车]","我必须让[公共汽车]通过"],"c":"交通标志“让行”中止了左让右规定。因此，从左侧驶来的摩托车享有优先权。您必须等待。然后，对向交通中左转的驾驶人必须先让您穿过交叉路口，才能转弯。"},"1.3.01-021-M":{"q":"正确的做法是什么？","o":["- 只有在[摩托车]之后才能转弯","- 在[黄色轿车]之前转弯","- 第一个转弯"],"c":"该交通标志表示“先行道路”。因此您可以在从左侧驶来的车辆之前转弯。但首先您必须让对向车辆转弯，因为您作为左转的驾驶人必须等待。"},"1.3.01-034-M":{"q":"此处正确的做法是什么？","o":["我让[黄色车辆]通过","我先于[黄色车辆]转弯","我先于[红色]轿车转弯"],"c":"优先通行权规则规定，您必须让黄色车辆通过。"},"1.3.01-035-M":{"q":"正确的做法是什么？","o":["我向[绿色轿车]让行","我在[绿色轿车]之前左转","我必须让[红色轿车]通过"],"c":"由于该交叉路口没有确定驾驶人优先顺序的标志，适用“左让右”的优先通行权规则。因此，您需要先让您右侧的汽车通过。之后，左侧的驾驶人必须让您先行。"},"1.3.01-038-M":{"q":"正确的做法是什么？","o":["我必须向摩托车让行","我必须向[蓝色轿车]让行","我可以在[蓝色轿车]之前驶出"],"c":"根据标志牌，摩托车驾驶人位于先行道路上，因此被允许先行。蓝色汽车的驾驶人和您都位于带“让行”标志的车道上。由于这并不能使情形明了，适用“左让右”。因此，您必须让另一辆车通过。"},"1.3.01-039-M":{"q":"此处谁优先？","o":["电动滑板车","[红色货车]","我"],"c":"该电动滑板车沿着先行道路行驶，因此享有优先通行权。"},"1.3.01-040-M":{"q":"此处正确的做法是什么？","o":["[绿色]轿车可以先于[红色]轿车通过","我可以先于[红色]轿车通过","我可以先于[绿色]轿车通过"],"c":"绿色和红色汽车位于一条转弯的主干道上。您位于次要道路上。绿色汽车留在主干道上，这意味着绿色汽车被允许先行，然后是红色汽车，最后才允许您行驶。"},"1.3.01-041-M":{"q":"此处正确的做法是什么？","o":["我可以先于[红色轿车]通过","[黄色轿车]可以先于[红色轿车]通过","我可以先于[黄色轿车]通过"],"c":"您和黄色汽车位于一条转弯的主干道上。红色汽车位于次要道路上。由于黄色汽车留在主干道上，它被允许先行。您可以第二个行驶，红色汽车最后行驶。"},"1.3.01-042-M":{"q":"正确的做法是什么？","o":["我必须让有轨电车通过","我必须让[摩托车]通过","有轨电车必须让我先转弯"],"c":"交叉路口处的标志表示您必须让行。由于您想左转，您必须让有轨电车以及对向的摩托车通过，最后才驶入交叉路口。"},"1.3.01-043-M":{"q":"此处正确的做法是什么？","o":["摩托车可以先于[黄色轿车]通过","我可以先于[黄色轿车]通过","我可以先于[摩托车]通过"],"c":"摩托车位于一条转弯的主干道上，被允许在黄色汽车和您之前转弯。\n根据十字路口的“右先于左”规则，您可以在黄色汽车之前行驶。"},"1.3.01-044-M":{"q":"此处正确的做法是什么？","o":["我可以第一个通过","我必须让[红色轿车]转弯","我必须让[骑自行车者]通过"],"c":"在该交叉路口适用右先于左。因此您可以先行。\n“右先于左”适用于优先通行权未由标志、信号灯或交通警察规定的交叉路口。"},"1.3.01-045-M":{"q":"此处正确的做法是什么？","o":["我必须让[黄色轿车]通过","我必须让[蓝色货车]通过","我可以在[黄色轿车]之前通过"],"c":"在该路口适用右先于左规则，这意味着您必须让黄色车辆通过。\n您还必须让卡车通过，因为您想左转，而卡车想在其车道上继续直行。"},"1.3.01-046-M":{"q":"正确的做法是什么？","o":["我可以通过","我必须让[蓝色轿车]通过"],"c":"您位于转弯的先行道路上并沿其走向行驶。因此，您必须先行，另一辆车必须等待。"},"1.3.01-047-M":{"q":"此处正确的做法是什么？","o":["- 让[蓝色轿车]通过","- 在停止线处停车","- 让[红色轿车]通过"],"c":"您正在接近一条即将转弯的先行道路。由于您从一条支路驶来，您必须让驶离先行道路的蓝色汽车通过。您还必须在停车标志处的停车线停车，然后才允许驶入该路口。"},"1.3.01-048-M":{"q":"正确的做法是什么？","o":["我让[蓝色轿车]转弯","我第一个通过","我让摩托车在我之前转弯"],"c":"在没有交通标志的交叉路口，适用“左让右”。如果一辆从右侧驶来的汽车想右转，则它被允许先行，而您必须等待。另一方面，如果一辆驶近您的车辆想左转，则您享有优先通行权，因为驾驶人想转弯时必须始终让对向交通先行。"},"1.3.01-049-M":{"q":"正确的做法是什么？","o":["我可以第一个通过","我必须向[红色轿车]让行","我必须向有轨电车让行"],"c":"该交通标志表示您位于先行道路上。而有轨电车和红色汽车的驾驶人则必须遵循“让行”标志并等待。您先行。"},"1.3.01-050-M":{"q":"正确的做法是什么？","o":["我可以通过","我必须让[蓝色轿车]享有优先通行权","我必须让[绿色轿车]享有优先通行权"],"c":"如果您在先行道路上行驶，则始终被允许先行。一辆与您相遇并想左转的汽车则必须等待。如果一名汽车驾驶人想从右侧驶入您所在的街道，他/她同样必须让您先行，因为您在先行道路上。"},"1.3.01-051-M":{"q":"正确的做法是什么？","o":["我让有轨电车通过","我让[拖拉机]转弯","我先行驶"],"c":"在先行道路上适用如下等级：原则上，位于先行道路上的车辆始终享有优先权。但是，驶离先行道路时，您必须让对向车辆先行。而想驶上先行道路的车辆，则必须让先行道路上的其他道路使用者先行。\n这意味着您必须让有轨电车先行，因为它行驶在先行道路上、不改变方向，而您想左转。"},"1.3.01-052":{"q":"正确的做法是什么？","o":["我必须让骑自行车者通过","我放弃我的优先通行权，以免堵塞路口","我可以抢在骑自行车者前面左转"],"c":"由于“左让右”规则，您相对于绿色汽车将享有优先权。但是，您必须让您将要横穿其车道的对向骑自行车者先行。为确保交通流通，因此建议先让绿色汽车的驾驶人驶入交叉路口。"},"1.3.01-053":{"q":"你想右转驶入一条干道。必须注意什么？","o":["从左侧和右侧驶来的车辆","你右侧或后方的骑自行车者和行人","仅注意从左侧驶来的车辆"],"c":"如果您右转驶入一条先行道路，您必须让所有道路使用者先行。这既适用于从右侧驶来的车辆，也适用于从左侧经过的车辆。此外，务必注意您右侧或后方的骑自行车者和行人。"},"1.3.01-055-M":{"q":"正确的做法是什么？","o":["- 在[蓝色货车]之后","- 在[黄色轿车]之后","- 在[黄色轿车]之前"],"c":"由于该交叉路口的优先通行权未由相应标志牌确定，适用“左让右”原则。因此，您必须让从右侧驶来的黄色汽车先行。蓝色卡车也享有优先于您的权利，因为您作为左转的驾驶人将横穿其车道。"},"1.3.01-056-M":{"q":"正确的做法是什么？","o":["- 在[这两辆车]之前","- 在[这两辆车]之后","- 在[蓝色轿车]之后"],"c":"在该交叉路口您享有优先通行权。这是由交通标志表示的。因此来自左右两侧的车辆必须等待，让您先行。"},"1.3.01-057-M":{"q":"正确的做法是什么？","o":["我必须让[红色轿车]通过","我可以在[蓝色货车]之前通过","我只可以在[蓝色货车]之后通过"],"c":"如果您想从一条先行道路左转，而另一辆汽车在您旁边行驶并留在先行道路上，则您必须让这位汽车驾驶人先行。而不在先行道路上的车辆，则必须等待。"},"1.3.01-058-M":{"q":"在此情况下哪项正确？","o":["我必须让[摩托车]享有优先通行权","[摩托车]必须等待","我必须发出左转信号"],"c":"您位于一条转弯的先行道路上，但您不想沿其向右行驶，而是想继续直行。从右侧有一辆摩托车沿着先行道路的走向行驶。您必须等待，并让该车辆先行。"},"1.3.01-059-M":{"q":"谁优先？","o":["我","[红色轿车]","[绿色拖拉机]"],"c":"您沿着一条转弯的先行道路行驶。因此，您相对于直行的汽车驾驶人享有优先权。拖拉机的驾驶人也必须等待，因为他/她驶离先行道路，对您而言适用左让右规则。"},"1.3.01-060-M":{"q":"正确的做法是什么？","o":["我必须打转向灯","[黄色]轿车必须等待","我必须等待"],"c":"如果没有竖立规范优先通行权的交通标志，这就是所谓的环形交通。在此适用右先于左的基本规则。由于您要驶入环形交通，您必须打转向灯。"},"1.3.01-101-M":{"q":"谁必须等待？","o":["[从土路驶出的那辆车]","我必须等待"],"c":"如果一辆车辆想从田间或森林道路驶入一条道路，则该汽车驾驶人必须等待。此处不适用“左让右”规则。"},"1.3.01-103-M":{"q":"正确的做法是什么？","o":["我必须等待","[摩托车]必须等待"],"c":"在交叉路口和横向路口，谁来自右侧谁就享有优先通行权。因为如果没有控制优先通行权的交通标志，就适用“左让右”。无论车辆的大小和类型如何。"},"1.3.01-112":{"q":"你想左转。谁必须等待？","o":["我必须等待","蓝色车辆必须等待"],"c":"在没有规范交通的交通标志的交叉路口和横向路口，适用“左让右”规则。而田间和森林道路则是次要通行路线。如果您想从田间或森林道路驶入一条道路，您必须等待。"},"1.3.01-113":{"q":"正确的做法是什么？","o":["我必须等待","骑自行车者必须等待"],"c":"如果您想驶入环形交叉路口，“让行”交通标志会要求您等待。在此绕圈行驶的驾驶人享有优先权。"},"1.3.01-114-M":{"q":"正确的做法是什么？","o":["我必须让骑自行车者转弯","我必须让[蓝色轿车]通过","[蓝色轿车]必须让我转弯"],"c":"在此适用“左让右”以及左转的规则。从右侧驶来的汽车可以先行。由于您想左转，对向的骑自行车者享有优先通行权。"},"1.3.01-115":{"q":"正确的做法是什么？","o":["我必须等待","骑自行车者必须等待","我必须在视线线处等待"],"c":"如果有道路使用者来自右侧，您必须注意“左让右”规则并等待。即使对方是骑自行车者，也是如此。"},"1.3.01-116":{"q":"正确的做法是什么？","o":["我必须让骑自行车者通过","我可以在骑自行车者前面转弯","蓝色货车可以先通过"],"c":"在该处，优先通行权未由交通标志规定。因此，在该交叉路口适用左让右。在此，直行的骑自行车者相对于想转弯的您享有优先权。从左侧驶来的卡车最后行驶。"},"1.3.01-117-M":{"q":"正确的做法是什么？","o":["- 向[骑自行车者]让行","- 向[公共汽车]让行","- 在停止线处停车"],"c":"一辆从左侧驶来的车辆已经在先行道路上。因此，它被允许先行。如果您左转，您必须让对向车辆先通过。由于该交通标志，您必须在停车线处停车（“让行”），或完全停车，甚至不得缓慢滑行（“停车标志”）。"},"1.3.01-118-M":{"q":"正确的做法是什么？","o":["我必须让[骑自行车者]通过","我可以在[摩托车]之前通过","[骑自行车者]必须让我通过"],"c":"由于此处的优先通行权未由交通标志规定，适用左让右。这意味着：您必须停车，让来自右侧的车辆通行。从左侧驶来的自行车必须让您通行。"},"1.3.01-119":{"q":"你想横穿一条干道。由于停放的车辆，两侧的视线严重受限。应当怎么做？","o":["我谨慎地缓慢驶入路口","我迅速穿过该路口","我鸣喇叭警告横向交通"],"c":"如果视线受限，您只应谨慎前行。缓慢驶入交叉路口，直到能看到先行道路。这样您才是有责任心地行动。"},"1.3.01-120-M":{"q":"正确的做法是什么？","o":["我必须让[蓝色车辆]通过","我可以在[绿色车辆]之前转弯","我必须让[绿色车辆]通过"],"c":"如果您位于先行道路上并想左转，您必须让对向汽车先通过。如果有一辆汽车在您旁边行驶，与您不同而留在先行道路上，那么这位汽车驾驶人享有优先权。但是，如果一辆来自另一条带“让行”交通标志的街道的车辆想驶入您的先行道路，他/她只能最后行驶。"},"1.3.01-121-M":{"q":"正确的做法是什么？","o":["我必须让有轨电车通过","我必须让拖拉机通过","我不得停在铁轨上等待"],"c":"您位于先行道路上。因此拖拉机必须等待，让您先左转。但是，您必须首先让在先行道路上继续直行的有轨电车通过，因为直行交通始终优先于想转弯的交通。"},"1.3.01-122-M":{"q":"正确的做法是什么？","o":["我必须等待","[绿色轿车]必须等待"],"c":"如果您处在交叉路口并看到“让行”交通标志，您必须等待，让汽车驾驶人从先行道路上通过。"},"1.3.01-123-M":{"q":"正确的做法是什么？","o":["我必须等待","[黄色轿车]必须等待"],"c":"您和另一名道路使用者位于一条转弯的先行道路上。另一辆车沿着先行道路的走向行驶，您想驶离。因此，您必须让另一名道路使用者先通过。"},"1.3.01-124-M":{"q":"正确的做法是什么？","o":["我必须等待","我可以在[摩托车]之前通过该路口"],"c":"您想横穿一条转弯的先行道路。在此您必须让先行道路上的所有车辆先行，并等到先行道路对您而言可以自由横穿。"},"1.3.01-125-M":{"q":"正确的做法是什么？","o":["我必须让[红色轿车]享有优先通行权","我优先于[蓝色轿车]通行","我必须让[蓝色轿车]享有优先通行权"],"c":"如果没有附加的规定优先通行权的交通标志或信号灯，则适用一般的“左让右”规则。必须让从右侧驶来的汽车先行。您相对于从左侧驶来的汽车享有优先权。"},"1.3.01-126-M":{"q":"正确的做法是什么？","o":["我先行驶","我必须让[黄色轿车]通过"],"c":"在“在下一个交叉路口或横向路口享有优先通行权”的交通标志处，您可以在下一个交叉路口先行。从左侧驶来的车辆必须等待。"},"1.3.01-127-M":{"q":"各方可按什么顺序继续行驶？","o":["[骑自行车者]、我、[黄色轿车]","[骑自行车者]、[黄色轿车]、我","我、[骑自行车者]、[黄色轿车]"],"c":"您位于一条转弯的先行道路上，并想直行驶离。骑自行车者沿着先行道路的走向行驶，因此相对于您享有优先权。从左侧驶来的汽车必须根据“左让右”规则让您先行。"},"1.3.01-128-M":{"q":"在此情况下谁可以先行驶？","o":["我","[红色]轿车","[蓝色]拖拉机"],"c":"“右先于左”的基本规则不适用于从田间或森林道路驶入另一条道路的车辆。"},"1.3.01-129-M":{"q":"此处正确的做法是什么？","o":["我等到[骑自行车者]完成转弯","我优先于[骑自行车者]","我鸣喇叭警告[骑自行车者]"],"c":"在交叉路口和路口处，谁来自右侧谁就享有优先通行权。"},"1.3.01-130-M":{"q":"在此情况下哪项正确？","o":["我必须等待","[蓝色轿车]必须等待","我必须与[蓝色轿车]的驾驶人协商一致"],"c":"从标志可以看出这不是一个环形交叉路口。因此适用右先于左。"},"1.4.40-001":{"q":"看到该交通标志时应当怎么做？","o":["降低车速","做好制动准备","只注意从右侧驶来的交通"],"c":"该交通标志提醒您前方有不易看清的交叉路口或横向路口。您应当减速并做好刹车准备，因为此处右侧的道路使用者享有优先权。您还应当密切关注左侧的交通，因为您必须预料到它不会履行其等待义务，并可能无视您的优先通行权。请调整您的速度，使您能看到从右侧驶来的交通，并在必要时毫无问题地刹车。"},"1.4.40-002":{"q":"看到该交通标志时应当注意什么？","o":["下坡路段的制动距离比平地更长","长时间使用后制动器效能可能下降","不挂挡时制动器效能会提高"],"c":"该交通标志警告您前方有最大10%的下坡。这意味着您必须注意与平路相比在此下坡处出现的更长制动距离。由于制动器在长时间制动时可能发热并可能失去功能，驾驶人必须换入较低挡位以利用发动机制动作用。在任何情况下您都不得摘挡滑行。"},"1.4.40-004":{"q":"看到该交通标志时应当怎么做？","o":["让对向交通先行","同一方向有两条车道时，采用拉链式（交替）汇入法","同一方向有两条车道且你在左侧车道行驶时，你绝对优先"],"c":"警告标志：它警告您行驶方向上的车道变窄。如果两条车道并成一条，则适用拉链式并线。这意味着：不存在绝对的优先权；变窄车道的驾驶人必须能够无缝并入车流。"},"1.4.40-005":{"q":"你看到该交通标志。必须预料到什么？","o":["对向来车","夜间被对向车辆眩目","对向交通享有优先"],"c":"如果您看到该交通标志，您作为驾驶人就必须预料到会有对向交通和前照灯眩目。它警告您那些通常不会预料到有对向交通的地方：在单行道上行驶时、在施工现场沿线或高速公路上个别车道的护栏处。对于黑色箭头，任何方向都不享有优先权。"},"1.4.40-006":{"q":"该交通标志要求你做什么？","o":["最高度的警觉","做好制动准备","降低车速"],"c":"该标志将指引您前方有学校、幼儿园或游乐场。在此您必须以相应的速度和更高的注意力驾驶。儿童可能不注意交通就突然跑到道路上。始终要做好刹车准备。"},"1.4.40-008":{"q":"该交通标志组合表示什么？","o":["与马匹相关的危险","骑马者优先于机动车","因马道而禁止直行通过"],"c":"感叹号表示前方有危险。带有骑手的标志表示必须预料到路上会有马匹和骑手。"},"1.4.40-009":{"q":"该交通标志组合表示什么？","o":["与马车相关的危险","马车优先于机动车","禁止马车通过"],"c":"感叹号表示一般性危险警告。危险的具体性质由附加标志说明：此处必须预料到路上有马拉车。"},"1.4.40-010":{"q":"看到该交通标志时必须预料到什么？","o":["一处不易被发现的人行横道","可能横穿道路的行人","只能从右侧横穿道路的行人"],"c":"这是警告您前方有行人过街设施的警告标志。该行人过街设施可能不易被发现。行人会利用过街设施横穿车道。请特别警觉。"},"1.4.40-011":{"q":"看到该交通标志时必须怎么做？","o":["- 以适中的车速驶近人行横道","- 特别专注","- 做好制动准备"],"c":"该警告标志表示附近有行人过街设施。必须注意行人并让他们横穿道路。应以适中速度驶近，在特定情况下停车，且绝不能在过街设施处超车。"},"1.4.40-012":{"q":"该交通标志向你提示什么危险？","o":["侧风","我的车辆可能被吹向一侧的风险","空中交通"],"c":"该交通标志警告有强侧风，车辆可能被横向吹偏。"},"1.4.40-013":{"q":"你在一条每个方向各一条车道的道路上行驶。哪个交通标志表示你必须始终向对向交通让行？","o":["","",""],"c":"标志“右侧单侧道路变窄”表示您所在的车道将明显变窄。此处必须让行对向来车。\n\n标志“让对向来车先行”用红色箭头表示必须让对向来车先行。"},"1.4.40-101":{"q":"你在城镇外行驶时经过该交通标志。预计危险距离有多远？","o":["在 150 米至 250 米之间","在 50 米至 150 米之间","在 250 米至 350 米之间"],"c":"该标志警告前方有危险。预计危险区域位于城镇外道路上 150 至 250 米处。请减速并提高注意力行驶。"},"1.4.40-103":{"q":"经过这些交通标志时必须做好什么准备？","o":["- 该道路可能被用于冬季运动","- 路面上有压实的雪或黑冰","- 只有人行道被用于冬季运动"],"c":"必须做好有滑雪者和雪橇使用者横穿道路的准备。该交通标志告知您此路段可进行冬季运动，且没有冬季清雪作业清除积雪。必须预料到因道路上积雪残留而增加的打滑危险。"},"1.4.40-105":{"q":"看到该交通标志时应当怎么做？","o":["降低车速","尽可能靠右侧行驶","在右弯之后立即强力加速"],"c":"该标志警告您前方有双弯道。首先预料向右转弯，然后向左转弯。您可能会驶入对向车道。请调整车速并尽量靠右行驶，以避免与对向来车相撞。"},"1.4.40-106":{"q":"经过这些交通标志后必须预料到什么？","o":["一段长 800 米的下坡","一段长 800 米的上坡","前方 800 米处开始的下坡"],"c":"经过该交通标志后，开始 10% 的上坡。附加标志说明危险区长度为 800 米。向右和向左的箭头表示上坡从标志处开始。若无箭头，则表示上坡从 800 米距离处开始。"},"1.4.40-107":{"q":"看到该交通标志时应当怎么做？","o":["必要时换入低挡","换入高挡以保持车速","制动，使车速在下坡时不会增加过多"],"c":"该交通标志告知有 12% 的陡坡。根据车辆性能，可能需要换入更低挡位，以免因行驶过慢造成交通阻塞和对他人的危险。上坡加速时若速度提不上去，就需要减挡。"},"1.4.40-108":{"q":"驶近该交通标志时应当怎么做？","o":["降低车速","提高车速","通过急打方向盘来避开不平整路段"],"c":"您前方的路面不平整，可能有斜向或纵向沟槽。该标志对此发出警告。在潮湿和寒冷天气下，您不只是在潮湿寒冷时才会侧滑。请避免急打方向。"},"1.4.40-109":{"q":"如果忽视该交通标志，可能产生哪些危险？","o":["车辆可能发生侧滑并危及对向交通","车辆可能发生断轴或板簧断裂","货物可能受损"],"c":"由于驾驶不当，在该路段有侧滑并危及其他车辆的风险。该路段不平整，可能有斜向和纵向沟槽。这意味着轮胎抓地力会更低。您需要降低车速，以便能够安全操控车辆。"},"1.4.40-112":{"q":"该交通标志警示你什么？","o":["路面脏污时有打滑的危险","路面潮湿时有打滑的危险","受酒精影响的驾驶人"],"c":"您前方的道路在潮湿或脏污时打滑风险增加。应减速，不要急刹车或急打方向。"},"1.4.40-114":{"q":"看到该交通标志时应当怎么做？","o":["降低车速","不超车","总是在道路变窄前停车"],"c":"这是一个警告标志，提醒驾驶员前方道路即将变窄。必须预料到对向来车，并采取如下行为：减速并放弃超车动作。只有当对向车辆已进入瓶颈路段时，才需在瓶颈前停车。此处不适用特定的先行权，而是适用拉链式合流，即驾驶员交替并入车道。"},"1.4.40-115":{"q":"看到这些交通标志时必须预料到什么？","o":["前方约 50 米处道路变窄","道路变窄路段长 50 米","前方 50 米处道路变宽"],"c":"预计前方 50 米处车道变窄。请缓慢行驶并随时准备制动，以便在接近危险区时能对交通拥堵作出反应。"},"1.4.40-116":{"q":"看到该交通标志时必须预料到什么？","o":["筑路车辆的通行","在路面上作业的人员","路面上的建筑材料"],"c":"有施工路段时，必须预料到施工车辆和施工人员会非常靠近正常行驶的车流。建筑材料和工具也可能在道路上。即使施工路段当时未施工，也要预料到路面被污染。存在打滑和侧滑的危险。"},"1.4.40-118":{"q":"看到该交通标志时必须预料到什么？","o":["交通拥堵","前方行驶的车辆可能突然制动","道路变宽为三条车道"],"c":"该交通标志警告该路段有拥堵。请根据危险情况调整车速和与前车的安全距离。前车可能突然刹车。也要留意前车前方的车流情况。您可以在车道内稍微错位行驶。"},"1.4.40-121":{"q":"该交通标志表示什么？","o":["交通信号灯","海关检查站","设有红色闪光信号的铁路道口"],"c":"请注意不易辨认的发光信号装置，如交通信号灯。在道路后续路段可能出现交叉路口或施工路段等危险点。"},"1.4.40-127":{"q":"这些交通标志表示什么？","o":["右转道路上的铁路道口","火车可能驶来的方向","绕开该铁路道口的改道"],"c":"如果您在此处向右行驶或转弯，请注意无人看守的铁路道口。如果您继续直行，该标志对您没有意义。"},"1.4.40-130":{"q":"该交通标志表示什么？","o":["前方约 160 米处有铁路道口","前方约 80 米处有铁路道口","前方约 240 米处有铁路道口"],"c":"警告前方有铁路道口的标志告知您铁路道口位于 160 米处。谨慎驶近危险区并随时准备制动，以防有列车横穿您的路线。"},"1.4.40-131":{"q":"该交通标志表示什么？","o":["前方约 80 米处有铁路道口","前方约 160 米处有铁路道口","前方约 240 米处有铁路道口"],"c":"该交通标志是距离标。该交通标志始终设置在道路两侧。它属于警告标志类。所示交通标志为单线距离标。单独一条红色斜杠表示铁路道口位于 80 米处。"},"1.4.40-132":{"q":"该交通标志组合表示什么？","o":["- 距离约 240 米","- 距离约 80 米","- 距离约 160 米"],"c":"您前方约 240 米处有铁路道口。前方铁路道口标提醒这一危险。每条斜线代表 80 米的距离。"},"1.4.40-133":{"q":"该交通标志组合表示什么？","o":["结冰路况","积雪路况","雪崩"],"c":"请注意该区域突然出现的雪或冰。个别路段可能意外湿滑。请根据当时天气条件调整车速。"},"1.4.40-134":{"q":"遇到该交通标志组合时必须预料到什么？","o":["被泥土覆盖的路面","路面上的家畜","野生动物横穿"],"c":"这一交通标志组合表示牛群驱赶，因为动物通过时会弄脏道路。横穿道路的野生动物另有其他交通标志。"},"1.4.40-135":{"q":"看到该交通标志组合时必须注意什么？","o":["距离 240 米处的铁路道口","禁止超越车辆","距离 120 米处的铁路道口"],"c":"这些交通标志警告您前方 240 米处有铁路道口。从带三条斜线的前方铁路道口标到危险区（含交叉路口）为止，禁止超越其他机动车。在该区域超车可能危及您和其他道路使用者。"},"1.4.40-136":{"q":"该交通标志组合预示着什么？","o":["距离约 100 米处开始的施工路段","距离约 100 米处结束的施工路段","长约 100 米的施工路段"],"c":"该交通标志警告您前方 100 米处有施工路段。请特别注意危险区，并在交通拥堵时随时准备制动。"},"1.4.40-137":{"q":"你在室外温度 +3 °C 时经过该交通标志组合。应当怎么做？","o":["我降低车速","我照常继续行驶，因为没有迹象表明有薄冰","我立即缩短与前车的距离"],"c":"这些交通标志的组合警告该路段突然结冰。这种情况常发生在桥梁上。冰雪会延长制动距离。因此应减速并加大与前车的距离。"},"1.4.40-138":{"q":"看到该危险标志时应当避免什么？","o":["猛烈加速","突然的转向操作","紧跟前车行驶"],"c":"这些交通标志的组合警告该路段有松散碎石。石头和碎石可能被扬起。因此避免强烈加速和猛打方向。与前车保持安全距离。"},"1.4.40-139":{"q":"该交通标志组合表示什么？","o":["活动桥","渡船","排水工程"],"c":"在这一组合中，交通标志警告您有活动桥。注意过往船只，为让船只通过，桥可以抬升或移动。"},"1.4.40-140":{"q":"看到该交通标志组合时必须注意什么？","o":["该道路通往水道岸边","在黑暗中或能见度差时，存在把水面与道路混淆的风险","必须为两栖车辆保持出入口畅通"],"c":"这些交通标志的组合告知汽车驾驶员道路通向岸边。在雾或黑暗等能见度差的条件下，水面可能被误认为车道。"},"1.4.40-141":{"q":"看到该交通标志组合时必须注意什么？","o":["避免停车和停放","路面上可能有石块","前方车辆可能突然制动"],"c":"这些交通标志的组合警告有落石或已落下的岩石，即可能有石头落到道路上或已经落在道路上。必须预料到前方行驶的车辆会为躲避落石而突然刹车。为了自身安全，不应在这些区域停车或泊车。"},"1.4.40-142":{"q":"该交通标志组合表示什么？","o":["铁路道口","铁路下穿通道","火车站"],"c":"该交通标志表示您即将通过铁路道口。不一定存在火车站或地下通道。"},"1.4.40-143":{"q":"遇到该交通标志时必须预料到什么？","o":["你正驶近一个急右弯","对向交通可能切弯","我前方的车辆可能急剧减速"],"c":"该交通标志警告有向右急弯。应意识到对向来车可能切弯并侵占您的车道。还必须预料到前方行驶的车辆会急刹车。"},"1.4.40-144":{"q":"遇到该交通标志时必须预料到什么？","o":["可能横穿车行道的骑自行车者","供骑自行车者使用的下穿通道","“禁止骑自行车者”区域"],"c":"该交通标志警告骑行者可能横穿道路并可能驶入您的车道，例如当自行车道结束并汇入道路时。"},"1.4.40-145":{"q":"遇到该交通标志组合时必须预料到什么？","o":["突然出现的飞机噪声","其他道路使用者走神","机场的入口或出口"],"c":"该交通标志告知有飞行器从道路上方飞过。突然的飞机噪音可能惊吓驾驶员。道路使用者可能因飞机而分心、走神。"},"1.4.40-146":{"q":"该交通标志组合表示什么？","o":["人行横道","供行人使用的下穿通道","供行人使用的天桥"],"c":"这些交通标志的组合表示行人过街设施。在行人过街设施处行人有优先权。汽车驾驶员必须让行人横穿道路。"},"1.4.40-147":{"q":"该交通标志表示什么？","o":["与马匹相关的危险","骑马者优先于机动车","因马道而禁止直行通过"],"c":"该标志（三角形）表示与马匹有关的危险区。"},"1.4.40-148":{"q":"该交通标志表示什么？","o":["结冰路况","压实的雪","雪崩"],"c":"该交通标志表示道路因积雪和结冰而湿滑。"},"1.4.40-149":{"q":"遇到该交通标志时必须预料到什么？","o":["被泥土覆盖的路面","路面上的家畜","野生动物横穿"],"c":"该标志表示道路非常脏，且必须注意路上放牧的动物。"},"1.4.40-150":{"q":"在该标志提示的危险点应当如何行动？","o":["- 避免急加速","- 避免突然操作","- 与前车保持尽可能大的距离"],"c":"由于该道路上有碎石和砂砾，您应尽量与前车保持较大距离，避免突然转向，并避免强烈加速。"},"1.4.40-151":{"q":"该交通标志表示什么？","o":["活动桥","渡船","排水工程"],"c":"该标志表示有活动桥。"},"1.4.40-152":{"q":"看到该道路交通标志时必须注意什么？","o":["该道路通往水道岸边","在天黑或能见度差时，水域很难与道路区分开","必须为两栖车辆保持出入口畅通"],"c":"标志的形状表示注意，标志上的图案表示要注意什么。该道路通向岸边。在黑暗或能见度差的情况下，水面很难与实际车道区分。"},"1.4.40-153":{"q":"看到该道路交通标志时必须注意什么？","o":["避免停车和停放","路面上可能有石块","前方车辆可能突然制动"],"c":"请注意可能躺在车道上的石头。避免停车和泊车。前方车辆可能因落石而突然减速。"},"1.4.40-154":{"q":"遇到该交通标志时必须预料到什么？","o":["突然出现的飞机噪声","其他道路使用者可能走神","突然制动的车辆"],"c":"该标志表示您应预料到来自其他道路使用者的干扰、突然的飞机噪音以及突然刹车的车辆。所有答案都正确。"},"1.4.40-155":{"q":"该交通标志表示什么？","o":["人行横道","供行人使用的下穿通道","供行人使用的天桥"],"c":"该盾形标志（注意）表示行人过街设施。"},"1.4.40-156":{"q":"你驾驶一辆手动变速器的机动车。看到该交通标志时必须考虑到什么？","o":["制动距离更长","长时间持续制动会降低制动效果","不挂挡时制动效果会更好"],"c":"为了在坡道上不超速，您可能需要全程轻踩制动。如果制动器发热，制动效果会随时间减弱。要注意这也会延长制动距离。为避免制动器不必要的负担，您可以选择更低挡位以增强发动机制动效果。"},"1.4.40-157":{"q":"你驾驶一辆手动变速器的机动车。看到该交通标志时正确的做法是什么？","o":["必要时我换入低挡","我总是换入高挡","我谨慎地驶下这段下坡"],"c":"为了在上坡时保持车速，您可能需要减挡，否则扭矩可能不足以在低速下继续驱动车辆。"},"1.4.41-001":{"q":"在什么情况下必须在该交通标志处等待？","o":["当铁路员工挥动白-红-白三色旗时","当无法通过铁路道口而不在其上停车时","当轨道车辆驶近时"],"c":"铁路道口前的斜十字表示轨道交通享有优先通行权。当有轨道车辆驶近时，您必须在标志前等待。如果铁路工作人员挥动白-红-白旗，也同样如此。如果您有因交通堵塞而在铁路道口停车的危险，也必须在斜十字前等待，直到能够快速通过铁路道口。"},"1.4.41-004":{"q":"看到该交通标志时应当怎么做？","o":["必须打右转向灯","只能向右行驶","不得右转"],"c":"标志“从此处起在标志前右转”只允许您向右行驶。即使只有这一种选择，改变行驶方向也必须打转向灯示意。"},"1.4.41-005":{"q":"看到该交通标志时应当怎么做？","o":["必须打左转向灯","只能向左行驶","不得向左行驶"],"c":"标志“从此处起在标志前左转”只允许继续向左行驶。尽管只有这一种选择，改变行驶方向也必须打转向灯示意。"},"1.4.41-006":{"q":"可以向哪些方向行驶？","o":["直行","向右","向左"],"c":"标志“必须直行或右转”禁止左转。只允许其他方向，即直行和右转。如果向右转，必须打转向灯示意。"},"1.4.41-007":{"q":"看到该交通标志时必须怎么做？","o":["必须从交通岛右侧通过","必须右转","在该标志前不得左转"],"c":"标志“从障碍物右侧通过”表示必须从右侧绕过障碍物。这些障碍包括交通岛、施工路段或公交车站。如果标志处之前有交叉路口或丁字路口，您既可以右转也可以左转。绕行障碍物时若向外侧摆动，必须打转向灯示意。"},"1.4.41-008":{"q":"你驶近一处如此标记的公交车站。如果看到那里有儿童，应当怎么做？","o":["降低车速并做好制动准备","只有当校车在此停靠时才需要降低车速","当公共汽车停靠在停车湾时不得降低车速"],"c":"该站是公交车站，校车在所示时间运营。驶近该站时，必须预料到儿童会突然跑到路上；在此情况下不适用信赖原则。如果校车停在停靠弯道内或在街上，作为汽车驾驶员您必须能够刹车；只允许以步行速度驶过。"},"1.4.41-010":{"q":"看到该交通标志时必须注意什么？","o":["在此步行街内不得驾驶机动车","在此步行街内可以以步行速度驾驶机动车","居民可以在该步行街内驾驶机动车"],"c":"标志“步行区”禁止机动车驶入该区域，甚至禁止以步行速度行驶。这也适用于居民。在商业区常有附加标志允许在特定时间驶入。此处没有此规定。"},"1.4.41-012":{"q":"哪些车辆不得在此行驶？","o":["电动自行车（机动脚踏车）","小型摩托车","轻便摩托车"],"c":"标志“禁止轻便摩托车通行”只适用于轻便摩托车。它不适用于轻便摩托车和轻型摩托车。轻便摩托车的低速度会妨碍该道路的交通流。"},"1.4.41-013":{"q":"看到该交通标志时必须注意什么？","o":["可能有车辆从该道路驶出","你不得驶入该道路","你可以驶入该道路"],"c":"标志“禁止驶入”毫无例外地禁止包括自行车在内的所有车辆驶入此街或道路。只有附加标志允许时自行车才可驶入。车辆从这条车道驶出。它总是出现在单行道的出口或高速公路出口的末端。"},"1.4.41-014":{"q":"看到该交通标志时必须注意什么？","o":["不得停车","可以为装卸货物而停车","可以为让乘客下车而停车"],"c":"标志“绝对禁止停车”禁止驾驶员停留或停车，除非是由于交通状况，如红灯或其他紧急交通情况。禁止人员上下车或装卸车辆。"},"1.4.41-015":{"q":"在该交通标志处允许做什么？","o":["为装卸货物、上下车而停车","最多停留 3 分钟","停放，前提是使用停车计时盘"],"c":"标志“禁止泊车。允许停留。”允许您停留最多三分钟。装卸或上下车的情况也可以更长时间。汽车驾驶员必须紧邻车辆。"},"1.4.41-016":{"q":"在设有这些交通标志的地方允许做什么？","o":["持有相应编号停车许可的重度残疾人士可以在此停放","任何人都可以为接送乘客而停车","凭停车缴费机（Parkscheinautomat）出具的停车票，任何人都可以在此不限时停放"],"c":"标志“禁止泊车。允许停留。”允许您停车以便让人上下车或装卸。此停车位预留给持有残疾人证和个性化停车证的汽车驾驶员。只有这些人有权在此处泊车，并可以让人拖走违规停放的车辆。"},"1.4.41-017":{"q":"对于该交通标志组合，哪项正确？","o":["- 注意从左右两侧驶来的骑自行车者","- 注意从左右两侧驶来的电动滑板车交通","- 只注意干道上从左右两侧驶来的机动车交通"],"c":"附加标志表示骑行交通可能从左右两侧驶来。因此，即使您只想右转，也要注意两个方向。电动滑板车越来越常见，它们在自行车道上行驶，所以也要注意滑板车骑行者。"},"1.4.41-018":{"q":"哪些车辆可以驶入设有该标志的自行车快速道？","o":["居民驾驶的所有车辆","所有最高设计车速低于 25 公里/小时的轻便摩托车","所有轿车，前提是以步行速度行驶"],"c":"除骑行者外，其他车辆不得使用自行车道，除非附加标志允许。该附加标志允许居民驶入自行车道。"},"1.4.41-019":{"q":"关于黄色路面标线，哪项正确？","o":["- 只临时施划（例如在施工现场）","- 取代白色路面标线的效力","- 只对施工现场交通有效"],"c":"黄色车道标线是临时设置的，例如因施工路段改变车道走向。黄色标线替代了白色标线。"},"1.4.41-020-M":{"q":"在此情况下哪项正确？","o":["- 不在受限区域内行驶","- 利用受限区域转弯","- 如果有交通拥堵则利用受限区域"],"c":"原则上不得驶入禁行区域。"},"1.4.41-021":{"q":"哪些车辆可以驶入设有该标志的区域？","o":["自行车","小型电动车辆","居民驾驶的车辆"],"c":"该交通标志表示自行车街区，并带有附加标志“Anleger frei（船只靠泊者除外）”。在自行车街区内适用“右先左”规则。骑行者、超小型电动车及其他被许可的车辆在自行车街区内最高时速 30 km/h。骑行者和超小型电动车在自行车街区内可以并排骑行。该附加标志也允许居民在自行车街区内骑行。"},"1.4.41-022":{"q":"在城镇内，当在设有该交通标志组合的道路上行驶时应注意什么？","o":["骑自行车者可能朝我的方向行驶","超越骑自行车者时，我必须保持至少 1.5 米的最小横向间距","骑自行车者必须使用车道左右两侧的人行道"],"c":"单行道标志也适用于骑行者，但通过这一交通标志组合，他们被允许双向骑行。但请注意，在城镇内道路上超越骑行者时，必须始终保持至少 1.5 米的侧向距离。"},"1.4.41-023":{"q":"该交通标志设在右侧路缘处。它表示什么？","o":["- 在其之前不得停车","- 在其之后不得停车","- 在其之前可以停放"],"c":"该交通标志表示在标志前方和后方区域是绝对禁止停车区。向左的箭头表示标志后方不得停车，向右的箭头表示标志前方不得停车。"},"1.4.41-024":{"q":"该交通标志设在右侧路缘处。它表示什么？","o":["- 绝对禁止停车区的起点","- 绝对禁止停车区的终点","- 有限禁止停车区的起点"],"c":"该交通标志表示从标志处开始绝对禁止停车。向左的箭头表示禁止停车从标志处开始。"},"1.4.41-025":{"q":"看到该交通标志时必须注意什么？","o":["- 不得停车","- 可以为快速装载我的车辆而停车","- 可以为让乘客下车而停车"],"c":"该交通标志表示该区域是绝对禁止停车区。那里不得停车。"},"1.4.41-026-M":{"q":"在此情况下正确的做法是什么？","o":["- 在对向[轿车]通过之后","- 在对向[轿车]通过之前","- 只以步行速度"],"c":"该标志表示在瓶颈路段必须让对向来车先行。对向来车已靠近瓶颈路段，因此您必须等待，只能在对向来车驶过后才能行驶。"},"1.4.41-027":{"q":"何时可以在此停车？","o":["周日","法定节假日","周六"],"c":"绝对禁止停车只在工作日适用。周日和公共假日允许在此停车。"},"1.4.41-028-M":{"q":"该路口适用什么？","o":["- 通过该路口","- 右转","- 左转"],"c":"带有中央白色自行车图案的蓝色交通标志表示自行车街道。该道路只允许自行车使用，除非其他交通标志另有明确规定。此外，三角形标志“让行”表示必须让交叉方向来车先行。\n在“让行”标志处您不必一定要停车，且由于左右两侧未见来车，可以谨慎通过交叉路口。"},"1.4.41-029":{"q":"该交通标志表示什么？","o":["- 不得行驶","- 以步行速度行驶","- 作为居民行驶"],"c":"原则上，交通标志“禁止各类车辆通行”表示不允许车辆在道路上行驶。但摩托车或自行车可以推行。"},"1.4.41-030":{"q":"你在一条设有标志的单行道上行驶。哪项正确？","o":["为左转我必须尽可能靠左","我也可以在道路左侧停放","我可以逆着交通方向停放"],"c":"单行道的行驶方向始终由交通标志上的白色箭头表示。如果您在自己的单行道上，可以沿行驶方向在道路右侧或左侧泊车。\n为了左转时不阻碍后方交通，您必须尽量靠左行驶。这样可以为想直行或右转的车辆留出足够空间。"},"1.4.41-031":{"q":"你在一条主路上行驶。哪个交通标志结束你的优先通行权？","o":["","",""],"c":"交通标志“优先道路结束”向您表示先行权规定已取消，优先道路在此结束。\n如果您此前一直在优先道路上行驶，标志“让行”就告诉您这条优先道路现在结束。您现在必须让其他道路使用者先行。"},"1.4.41-032":{"q":"下列哪条交通规则要求你在右转前停车？","o":["","",""],"c":"“停车标志”向您表示必须始终在停止线或可视线上停车。\n红灯旁的“绿色箭头”表示尽管红灯您也可以右转。但只有在您已在停止线或可视线上停车并确认未危及任何人之后才可以。"},"1.4.41-033":{"q":"哪个交通标志禁止你驶入所标示区域？","o":["","",""],"c":"您不得驶入带有该交通标志的街道，因为它表示步行区。该区域只允许行人使用。\n该交通标志意为“禁止驶入”。因此禁止驶入该标志所标识的区域。"},"1.4.41-102":{"q":"看到该交通标志时应当怎么做？","o":["必须让对向交通先行","不得转弯","你优先于对向交通"],"c":"道路太窄，无法容纳两条车道。该交通标志规定了先行权。对向来车获准先行。如果遇到车辆，您必须提前停车，让对向来车通过。"},"1.4.41-106":{"q":"允许向哪些方向继续行驶？","o":["向左","向右","直行"],"c":"标志“您只能左转或右转”只允许您向左或向右转弯。需要示意想要的行驶方向。不得直行。"},"1.4.41-109":{"q":"一辆校车在你前方约 80 米处的路面上停靠。这可能危险吗？","o":["是的，因为儿童经常横穿道路去赶校车","是的，因为儿童横穿车道时并不总是走最短路线","不，因为每个校车站都有学生过街护卫队指挥交通"],"c":"如果一辆校车在您前方约 80 米处的道路上停车，您必须预料到以下情况：儿童可能突然跑到路上或从路上跑向校车，例如走最短路线。即使有学校交通协管员维护交通，也存在这一危险。您必须随时准备刹车，只允许以步行速度驶过校车。"},"1.4.41-114":{"q":"谁可以在该道路上驾驶机动车？","o":["送货人员","购物者","来访者"],"c":"该街道是明确的步行道，并带有附加标志“仅送货车辆”。因此，该道路只允许送货员驾驶机动车使用。送货员必须能够证明其需在此街道送货。无论是否有行人经过该街道，他都必须以步行速度行驶。他必须照顾行人。"},"1.4.41-115":{"q":"哪些车辆可以使用如此标记的专用车道？","o":["公共汽车","载货汽车","轿车"],"c":"此处所示车道供公共汽车使用。只有公共汽车可以使用这条车道。所有其他驾驶员禁止使用这条车道。"},"1.4.41-116":{"q":"谁可以驶入如此设标的街道？","o":["居民","拜访居民的人","过境交通"],"c":"附加标志表示因私事或公务需在此街道办事的驾驶员可以驶入。居民和访客是指商店的顾客、诊所的患者以及居住在这条街道上的人及其访客。这条街道禁止穿行交通。"},"1.4.41-118":{"q":"哪些车辆不得使用如此设标的道路？","o":["载货汽车","轿车","摩托车"],"c":"汽车以及其他多车道机动车不得在带有该标志的道路上行驶。这些包括汽车、卡车和公共汽车。该禁令不适用于摩托车（含带边车的摩托车）和非机动车。"},"1.4.41-119":{"q":"哪些车辆不得使用如此设标的道路？","o":["自行车","摩托车","轿车"],"c":"这个带红边的圆形交通标志禁止骑行者通行。它通常出现在允许高速行驶、骑行者可能因速度低而陷入危险的道路上。摩托车和汽车等机动车可以在此通行。"},"1.4.41-120":{"q":"哪些车辆不得使用如此设标的道路？","o":["摩托车","轿车","载货汽车"],"c":"带红边的圆形交通标志表示对车辆的普遍禁行。如果圆圈内有符号，则更精确地规定了禁行所适用的车辆类型。此处禁止摩托车驾驶员使用该道路。"},"1.4.41-121":{"q":"这些交通标志表示什么？","o":["前方 100 米处禁止驶入","一条长 100 米的单行道","前方 100 米处有一处海关检查站"],"c":"标志“禁止驶入”禁止汽车驾驶员驾驶各类车辆驶入该道路。附加标志明确该禁令仅在 100 米范围内适用。它没有明确说明持续多长。始终要预料到车辆可能从这条道路驶出。"},"1.4.41-124":{"q":"该交通标志表示什么？","o":["- 允许的最高车速 30 公里/小时","- 规定的最低车速 30 公里/小时","- 建议车速 30 公里/小时"],"c":"该交通标志表示最高时速 30 km/h 区域的起点。它常设在居住区，且只在起点设置一次。在整个区域内不得以超过 30 km/h 的速度行驶。该限速由“30 km/h 区域结束”标志取消。"},"1.4.41-125":{"q":"一处交通安宁的商业区（verkehrsberuhigter Bereich）从此开始。必须怎么做？","o":["必须特别注意频繁的行人交通","必须注意允许的最长停放时间","必须遵守 20 公里/小时的最低车速"],"c":"在有商店的交通稳静区内，道路使用者常因橱窗中的陈列而分心。因此必须注意雨天和不专心的行人。您的最高时速为 20 km/h。这是禁止泊车但允许停留的区域，您有义务使用停车计时牌。为了向许多顾客提供停车位，最长停车时间为两小时。"},"1.4.41-126":{"q":"该交通标志表示什么？","o":["- 允许的最高车速 30 公里/小时","- 规定的最低车速 30 公里/小时","- 建议车速 30 公里/小时"],"c":"该交通标志表示一个允许速度被设为 30 km/h 的区域的结束，从而取消 30 km/h 的最高时速。"},"1.4.41-127":{"q":"此处允许以超过 60 公里/小时的车速行驶吗？","o":["是的，如果路面干燥","是的，如果路面潮湿"],"c":"由于附加标志，60 km/h 的最高允许速度仅在潮湿条件下适用。如果整个车道覆盖有一层薄水膜并因此算作潮湿，请相应地降低车速。如果路面干燥或只是微湿，作为汽车驾驶员您也可以以超过 60 km/h 的速度行驶。"},"1.4.41-128":{"q":"看到该交通标志时应当怎么做？","o":["在天气和交通状况允许时，必须至少以 60 公里/小时的车速行驶","如果你不能或不允许至少以 60 公里/小时行驶，则不得使用该道路","不得以超过 60 公里/小时的车速行驶"],"c":"该交通标志规定您在此必须至少以 60 km/h 的速度行驶。只有在交通安全需要时才允许更慢行驶。如果汽车驾驶员因车辆或载重或缺乏个人能力而不能或不被允许开那么快，则不得使用该道路。"},"1.4.41-129":{"q":"在设有该交通标志的地方，允许超越哪些车辆？","o":["无边斗摩托车","带边斗摩托车","轿车"],"c":"该超车限制禁止汽车驾驶员超越多车道车辆，如汽车、卡车或拖拉机以及带边车的摩托车。无挂边车的摩托车和自行车可以被超越，因为它们是单车道车辆。"},"1.4.41-130":{"q":"这些交通标志表示什么？","o":["3 公里内禁止超车","前方 3 公里处开始禁止超车区","3 公里内同一方向有两条车道的道路"],"c":"该交通标志表示对多车道机动车或带边车摩托车的超车限制。带公里数说明的黑色箭头表示超车限制适用 3 km。超车限制从该交通标志起生效。"},"1.4.41-131":{"q":"这些交通标志表示什么？","o":["前方 200 米处开始禁止超车区","200 米内禁止超车","前方 200 米处禁止超车区结束"],"c":"该交通标志禁止汽车驾驶员超越多车道车辆和带边车的摩托车。附加标志禁止在 200 米内超车。由于它不含黑色箭头，并不意味着您在接下来 200 米内都不得超车。"},"1.4.41-132":{"q":"该交通标志表示什么？","o":["限速结束","禁止以超过 60 公里/小时的车速行驶","限速开始"],"c":"该交通标志表示 60 km/h 限速的结束。汽车驾驶员可以再次按通常速度行驶。"},"1.4.41-133":{"q":"看到该标志时哪些禁令失效？","o":["禁止超车","限速","禁止停放"],"c":"该交通标志取消所有道路限制。例如，道路限制包括超车限制和限速。停车限制如泊车禁令不属于道路限制的范畴。"},"1.4.41-134":{"q":"这些交通标志表示什么？","o":["- 在车道和应急车道上","- 仅在应急车道上","- 仅对载货汽车"],"c":"该交通标志向汽车驾驶员表示禁止在道路上停车。附加标志扩展了停车限制，对所有车辆（不仅是卡车）也禁止在路侧带停车。"},"1.4.41-135":{"q":"在从此开始的区域内允许做什么？","o":["最多停车 3 分钟","为装卸货物以及上下车而停车","停放，前提是使用停车计时盘"],"c":"通过标志“禁止泊车。允许停留。”，在整个区域内存在有限制的停车禁令，而无需在特定街道设置停车标志。作为汽车驾驶员，您可以在整个区域内最多停留三分钟。装卸或上下车的情况也可以更长时间。"},"1.4.41-136":{"q":"此处什么结束？","o":["禁止等候区","禁止停车区","先前所有的区域禁令"],"c":"此处禁止泊车区结束。请注意该交通标志常只设在道路左侧，且不取消停车限制。"},"1.4.41-140-B":{"q":"何时必须打转向灯？","o":["驶出环岛时","驶入环岛时"],"c":"如果您驶入环岛，不需要打转向灯，因为进入环岛总是向右。相反，如果您驶出环岛，则需要打转向灯，以便于其他驾驶员驶入环岛。"},"1.4.41-141":{"q":"你驶近该交通标志组合。必须注意什么？","o":["环岛内的车辆优先","驶出环岛时必须打转向灯","驶入环岛时必须打转向灯"],"c":"在环岛内行驶的车辆享有优先通行权。进入环岛时无需打转向灯，因为环岛总是从右侧进入。因此，“进入环岛必须打转向灯”这一答案是错误的。只有在驶出环岛时才打转向灯。这是合理的，因为这便于车辆驶入环岛。"},"1.4.41-142":{"q":"该交通标志表示什么？","o":["禁止在环岛上停车","驶入环岛时必须打转向灯","只允许以步行速度行驶"],"c":"您必须让在环岛内行驶的车辆先行。环岛内始终存在绝对禁止停车的标志。只有在驶出环岛时才打转向灯。这有助于其他汽车驶入环岛。环岛内不要求普遍以步行速度行驶。"},"1.4.41-143":{"q":"该交通标志表示什么？","o":["必须向环岛内的车辆让行","驶出环岛时必须打转向灯","驶入环岛时必须打转向灯"],"c":"这些交通标志表示环岛内行驶的驾驶员享有先行权。它们还表示进入环岛时无需打转向灯，因为驾驶员只能从右侧进入环岛。一旦您驶出环岛，就需要打转向灯，以便于其他道路使用者驶入环岛。"},"1.4.41-144":{"q":"看到该交通标志组合时必须怎么做？","o":["驶出环岛时必须打右转向灯","驶入环岛时必须让行","必须靠左驶入"],"c":"驶入时，您必须让已经在环岛内的车辆先行。环岛只能从右侧进入。只有在驶出环岛时才打转向灯。这一规定便于驾驶员驶入环岛。当看到转向灯时，他们可以在尽到注意义务的前提下决定是否可以驶入环岛。"},"1.4.41-145":{"q":"该交通标志表示什么？","o":["强制自行车道","“禁止骑自行车者”区域","横穿车行道的骑自行车者"],"c":"该交通标志标识骑行者必须使用、而其他道路使用者禁止使用的自行车道。横穿道路的骑行者有自己的警告标志。"},"1.4.41-146":{"q":"该交通标志组合表示什么？","o":["- “停车，让行。”","- “让行。”","- “向对向交通让行”"],"c":"该交通标志预告在 100 米后您会遇到一条优先道路，在那里您会看到标志“让行”。在任何情况下，您都必须在那里于停止线或可视线上停车。"},"1.4.41-147":{"q":"该交通标志表示什么？","o":["人行道（步行道）","禁止自行车和轻便摩托车通行","交通安宁区的起点"],"c":"标志“人行道”标识仅允许行人及 10 岁以下儿童使用的路径。汽车驾驶员、骑行者及其他道路使用者不得在这些路径上通行。但附加标志可规定例外。"},"1.4.41-148":{"q":"允许哪些车辆使用该道路？","o":["被推行的自行车和摩托车","机动车","电动车辆"],"c":"标志“禁止各类车辆通行”包括所有车辆。此处只有摩托车和踏板车等机动自行车以及自行车可以推行。"},"1.4.41-149":{"q":"在允许的送货时段驾驶车辆时应当如何行动？","o":["我只可以以步行速度行驶","我必须密切注意行人","如果我附近没有行人，我可以以高于步行速度的车速行驶"],"c":"由于此处标志“人行道”与附加标志“仅送货车辆”组合，送货员可以在如此标识的道路上行驶。无论是否看到行人，您都必须以步行速度行驶。行人享有优先权，您应特别体谅他们。"},"1.4.41-150":{"q":"看到该交通标志时必须怎么做？","o":["我不得在此掉头","我身处一条死胡同，必须掉头","我不得在此左转"],"c":"该交通标志表示禁止掉头以驶向相反方向。但允许左转。该交通标志并非仅适用于死胡同。"},"1.4.41-151":{"q":"该交通标志表示什么？","o":["我不得以超过 60 公里/小时的车速行驶","以 60 公里/小时行驶完全没有问题","建议的最低车速为 60 公里/小时"],"c":"从这些交通标志起，无论天气条件如何，最高可以 60 km/h 行驶。在恶劣天气条件下，速度必须进一步降低。但该交通标志并未表示必须始终以 60 km/h 行驶才安全。不存在推荐最低速度的交通标志。"},"1.4.41-152":{"q":"该交通标志表示什么？","o":["我只可以直行","我优先于对向交通","我在一条单向道路上"],"c":"该交通标志意为“您必须直行”。您只能直行，不得转弯。单行道标志颜色相同，但为矩形。"},"1.4.41-153":{"q":"看到该交通标志时应当怎么做？","o":["我以适中的车速驶近并做好制动准备","我让横向通行的交通享有优先通行权","如果我右转，则不必等待"],"c":"交通标志“让行”表示您在一条次要道路上行驶，交叉方向来车享有先行权。请缓慢行驶并随时准备制动，以免错过有先行权的车辆。"},"1.4.41-154":{"q":"该交通标志表示什么？","o":["一条骑手必须使用的马道","一条其他道路使用者不得使用的马道","一条骑手不得使用的道路"],"c":"该交通标志向您表示一条骑乘道。骑手在此与马匹通行。其他道路使用者不得使用该路径。"},"1.4.41-155":{"q":"看到该交通标志时必须怎么做？","o":["- 停车并让行","- 只有当存在停止线时才停车","- 只有当有横向通行交通时才停车"],"c":"标志“停车！让交叉方向来车先行”要求您停车，从而使车辆完全停下。无论是否有停止线，也无论是否有交叉方向来车。"},"1.4.41-156":{"q":"在这种交通情况下必须怎么做？","o":["- 在视线线处停车并让行","- 不停车，因为没有停止线","- 只有当有横向通行交通时才停车"],"c":"在交通标志“停车！让交叉方向来车先行”处，您必须停车并让行。即使没有交叉方向来车，您也必须始终停车。由于没有停止线，请在可视线上停车。从可视线您可以看见您要驶入的街道。"},"1.4.41-157":{"q":"在这种交通情况下必须怎么做？","o":["- 在停止线处停车并让行","- 只在停车标志处停车","- 只有当有横向通行交通时才停车"],"c":"交通标志“停车！让交叉方向来车先行！”要求您停车并让行。由于有停止线，您必须在停止线上停车。如果没有停止线，必须在可视线上停车，且车轮必须完全停住。即使没有交叉方向来车，您也必须始终停车。"},"1.4.41-158":{"q":"你沿一条干道行驶。哪个交通标志结束你的优先通行权？","o":["1","2","3"],"c":"示例 1 意为“让行”，您必须让其他道路使用者先行。标志 2 授予您在下一个交叉路口的先行权。标志 3 仅警告有危险区。"},"1.4.41-159":{"q":"对于该交通标志必须注意什么？","o":["我必须发出左转信号","我只可以通过左转继续行驶","我不得打转向灯"],"c":"该交通标志规定行驶方向。此处只能左转。必须示意行驶方向的改变。"},"1.4.41-160":{"q":"该交通标志适用什么？","o":["我必须从障碍物左侧驶过","我必须左转","在该标志前我不得右转"],"c":"该交通标志规定您必须从哪一侧绕过障碍物。您可以在中央隔离带、停车岛或施工路段找到该指示标志。如果在交叉路口或丁字路口遇到该标志，您可以向相应方向转弯。"},"1.4.41-161":{"q":"在该交通标志前后各 15 米范围内适用什么？","o":["- 停车","- 不得妨碍乘客上下车","- 停放"],"c":"在该交通标志处可以看到这里有有轨电车或公共汽车站。在标志前后 15 米内，驾驶员不得泊车。除非妨碍公共交通或危及乘客，允许停留最多三分钟。"},"1.4.41-162":{"q":"该交通标志适用什么？","o":["我必须发出右转信号","我只可以通过右转继续行驶","我也可以通过左转继续行驶"],"c":"给定的行驶方向具有约束力。汽车驾驶员必须在交通标志前右转，并向其他道路使用者示意这一动作。"},"1.4.41-163":{"q":"该交通标志适用什么？","o":["我必须预料到出租车会起步和停靠","我可以停车","我可以停放"],"c":"该交通标志表示出租车停靠站。原则上对所有其他车辆存在停车限制。汽车驾驶员必须始终预料到该区域有驶离和到达的出租车及乘客。"},"1.4.41-164":{"q":"该交通标志组合表示什么？","o":["- 可供冬季运动爱好者使用","- 冬季不得由交通使用","- 只有装配防滑链时才可使用"],"c":"该标志意为“危险区”，附加标志意为“允许冬季运动”。这一组合表示冬季运动者可以使用该道路，道路使用者必须特别注意。"},"1.4.41-165":{"q":"在这种交通情况下必须注意什么？","o":["- 不跨越车道标线","- 为超车而跨越车道标线","- 如果对向交通允许，则跨越车道标线"],"c":"您不得越过位于车道中央的车道边界（实线）向左行驶。横向行驶在其上也被禁止。"},"1.4.41-166":{"q":"在这条干道上必须注意什么？","o":["禁止停放","你不得跨越车道标线","如果停放的车辆与车道标线之间至少留有 3 米的净空，则允许停放"],"c":"两条车道中间的单实线禁止跨越或横穿该线。它还禁止在城镇外道路上的优先道路上泊车。"},"1.4.41-167":{"q":"你想超车。正确的做法是什么？","o":["- 超车","- 不超车","- 只有在我超车时保持在右侧车道，才超车"],"c":"如果不会危及其他道路使用者，您可以超车。单侧车道边界线允许您从虚线所在的一侧跨越这两条线。"},"1.4.41-168":{"q":"作为居民，你想驶入设有该标志的自行车快速道。驶入时必须注意什么？","o":["车辆行驶速度不得超过 30 公里/小时","自行车可以并排行驶","不得妨碍自行车交通"],"c":"交通适用最高时速 30 km/h。不得危及或妨碍自行车交通。如有必要，机动车交通必须进一步减速。允许并排骑行。"},"1.4.41-169":{"q":"谁可以驶入设有该标志的街道？","o":["所有骑自行车者","所有拜访居民的人","所有轻便摩托车驾驶人"],"c":"除骑行者外，其他车辆不得使用自行车道，除非附加标志允许。该附加标志允许居民驶入自行车道。"},"1.4.41-170":{"q":"该交通标志是针对你所在车道设置的。必须注意什么？","o":["在道路和交通状况允许时，我必须至少以 60 公里/小时的车速行驶","只有当我的车辆能够且允许至少以 60 公里/小时的车速行驶时，我才可以使用该车道","我不得以超过 60 公里/小时的车速行驶"],"c":"该交通标志表示规定的最低速度。因此您必须至少以 60 km/h 行驶，前提是道路和交通状况允许。"},"1.4.41-171":{"q":"在设有该标志的区域内，车辆可以行驶的最高车速是多少？","o":[],"c":"骑行者、轻型电动车及其他被许可的车辆在自行车街区内行驶速度不得超过 30 km/h。"},"1.4.41-172":{"q":"根据该交通标志适用什么情况？","o":["- 适用于晚上 10 点至早上 6 点之间","- 适用于早上 6 点至晚上 10 点之间","- 不适用于电动车辆"],"c":"附加标志将限速限定在 22 时至 6 时之间。"},"1.4.41-173":{"q":"看到该交通标志时应当怎么做？","o":["- 打左转向灯","- 在交通标志前左转","- 在交通标志后左转"],"c":"该交通标志上的箭头始终表示行驶方向。如果是直箭头，您必须在标志前转弯。如果是弯曲箭头，您必须按标志转弯。\n必须打转向灯示意行驶方向的改变。"},"1.4.41-174":{"q":"哪个交通标志表示禁止掉头？","o":["","",""],"c":"所有交通标志都向您表示禁止掉头。\n该交通标志告诉您隧道从这里开始。隧道内严格禁止掉头。\n交通标志“禁止掉头”向您表示此处禁止掉头。\n该交通标志告诉您您在高速公路上。高速公路上严格禁止掉头。"},"1.4.41-175":{"q":"从哪个交通标志起，你不得超过 60 公里/小时的允许最高车速？","o":["","",""],"c":"带红边的交通标志通常表示禁令。在带有此类交通标志的道路上，您不得以超过 60 km/h 的最高允许速度行驶。"},"1.4.42-001":{"q":"该交通标志表示什么？","o":["- 只在下一个十字路口或交叉路口","- 在该道路上所有十字路口和交叉路口","- 直到城镇边界"],"c":"该交通标志授予您在特定地点先行权。因此，驾驶员的先行权是有限的，不具有普遍效力。"},"1.4.42-005":{"q":"该交通标志表示什么？","o":["高速公路的起点","高速公路的终点","仅供机动车使用的快速公路的起点"],"c":"该交通标志表示高速公路从这里开始。这也使适用于这一特殊类型道路的所有规则生效。"},"1.4.42-009-M":{"q":"在此情况下路面上的白色标线表示什么？","o":["- 提示因“右方优先于左方”规则而产生的让行义务","- 表示交通安宁区","- 是对路面状况不佳的警告"],"c":"在适用“右先左”规定的交叉路口和路口处，尤其是在不易看清的位置，也会使用等待线。常使用看起来由许多小横线构成的等待线。"},"1.4.42-010-M":{"q":"在此情况下，路面标线所确立的规则是什么？","o":["- 谨慎驶近该路口","- 向[红色车辆]让行","- 在路面标线前停车"],"c":"您必须谨慎驶近该交叉路口，因为适用右先左规则。\n在适用“右先左”规定的交叉路口和路口处，尤其是在不易看清的位置，也会使用等待线。常使用看起来由许多小横线构成的等待线。"},"1.4.42-011":{"q":"从哪个交通标志起只允许以步行速度行驶？","o":["","",""],"c":"在交通稳静区内，您只能以步行速度驾驶车辆，因为您必须随时预料到行人或玩耍的儿童。"},"1.4.42-012":{"q":"在下一个路口，遇到哪个交通标志时你通常享有优先通行权？","o":["","",""],"c":"交通标志“一次性先行权”向您表示您在下一个交叉路口或路口处享有先行权。但该标志对再下一个交叉路口没有效力。"},"1.4.42-101":{"q":"在下一个十字路口，哪个交通标志赋予优先通行权？","o":["交通标志 1","交通标志 2","交通标志 3"],"c":"只有第一个交通标志授予您在下一个交叉路口的先行权。第二个交通标志则表示优先道路的结束，而第三个交通标志规定瓶颈路段处的先行权。"},"1.4.42-102":{"q":"哪个交通标志赋予优先通行权？","o":["交通标志 2","交通标志 1","交通标志 3"],"c":"正确的表明先行权的交通标志是第二个。第一个表示驾驶员前方有危险弯道，第三个表示某条国道的编号。"},"1.4.42-104":{"q":"在城镇外的干道上允许做什么？","o":["在车道右边缘停车","在应急车道停放","在车道上停放"],"c":"在城镇外的优先道路上，您可以：1. 在道路右侧停留；2. 在应急车道上泊车。相反，禁止在道路上泊车。停放的车辆会妨碍和/或危及车流，因为这里的车辆行驶速度远快于城镇内。由于应急车道不被视为车道，您可以用它来泊车。如果应急车道上有避让空间，您也应利用它短暂停留。"},"1.4.42-106":{"q":"此处什么结束？","o":["干道","受管理的停车区","先前所有的区域禁令"],"c":"该交通标志预告先行规则的改变。它标志着先前优先路线的结束。您在交叉路口和丁字路口可发现的标志“让行”和“停车！让行！”具有类似含义。"},"1.4.42-107":{"q":"看到该交通标志时应当怎么做？","o":["只有当变窄处畅通无阻时才行使优先权","尽管享有优先权，也必须做好停车准备","你必须让对向交通先行"],"c":"该交通标志授予您比对向来车优先的权利。对向来车有义务在障碍物前等待。但如果对向来车已进入瓶颈路段，您仍必须准备停车。您必须让这些驾驶员驶出。如果瓶颈路段空闲，您可以凭先行权继续行驶。"},"1.4.42-109":{"q":"这些交通标志允许什么？","o":["持有相应编号停车许可的居民可以在此停放","所有居民都可以使用这些停车位中的任意一个","只要还有其他空余停车位，任何人都可以使用该停车位"],"c":"该交通标志表示一个停车位，仅允许持有相应编号停车证的居民使用。其他道路使用者不得在此泊车，必须改用其他停车场所。"},"1.4.42-110":{"q":"允许你在此停放吗？","o":["可以，作为持有官方停车许可的重度残疾人士","可以，作为持有官方停车许可的陪同盲人者","可以，短暂购物时"],"c":"有专门为行动不便者或盲人设置的停车位。官方停车许可证标识这些人或其陪同者的车辆。其他驾驶员甚至短暂停放在这些区域也是禁止的。"},"1.4.42-111":{"q":"在此停放时必须遵守什么？","o":["不得超过停车票上标明的停车时间","停车票必须放置在便于检查时轻易阅读的位置","停车票与停车计时盘效力相同"],"c":"在该停车区，只有在持有有效停车票时才允许泊车。将停车票清晰地贴在前窗或后窗后面。务必不要超过停车票上注明的停车时间。停车计时牌不能替代停车票：停车计时牌仅在停车计时器故障时才有效。"},"1.4.42-112":{"q":"哪些车辆可以在此停放？","o":["允许总质量不超过 2.8 吨的车辆","摩托车","允许总质量超过 3.5 吨的车辆"],"c":"该交通标志规定道路使用者的停车情况。该标志允许总重量不超过 2.8 吨的车辆部分在人行道、路侧带和绿化带上泊车。"},"1.4.42-116":{"q":"如果你想使用该道路，机动车的结构最高车速必须至少为多少？","o":["61 公里/小时","51 公里/小时","81 公里/小时"],"c":"在汽车专用道上，您的车辆必须至少能达到 60 km/h 的最高速度。汽车专用道的起点始终由交通标志标识。"},"1.4.42-119":{"q":"该交通标志表示什么？","o":["死胡同（尽头路）","下穿通道","禁止车辆通行的道路"],"c":"这是死胡同。在死胡同里您可以正常行驶，但道路到此结束，因此您可能难以掉头以便再次驶出这条街。"},"1.4.42-120":{"q":"该交通标志表示什么？","o":["急救站","十字路口","危险点"],"c":"该交通标志表示此处设有“红十字会”或“撒玛利亚会”等急救站。但它不表示任何危险区。"},"1.4.42-125":{"q":"看到该交通标志时必须注意什么？","o":["路灯不会整夜亮着","车辆可以整夜在此熄灯停放","车辆不得在此停放"],"c":"如果您在灯柱上看到该标志，则必须用驻车灯保护您的车辆。由于这些灯柱并非整夜点亮，把未点灯的车辆停在这里很不安全。"},"1.4.42-126":{"q":"该交通标志表示什么？","o":["一条联邦公路（Bundesstraße）","车辆行驶速度不得超过 35 公里/小时","车辆必须至少以 35 公里/小时行驶"],"c":"该交通标志指一条主干道。其中的数字代表相应联邦公路的编号，而不是例如限速。"},"1.4.42-128":{"q":"该交通标志表示什么？","o":["一段通常车流量不大的高速公路","必须驶离高速公路的地点","载有危险货物的车辆的强制改道路线"],"c":"改道箭头向作为汽车驾驶员的您指出，您正处于高速公路上易发生拥堵的路段，并指出一条替代路线。但您没有义务遵循它。"},"1.4.42-129":{"q":"白天，你驶入一处如此标示且有照明的隧道。应当怎么做？","o":["我开启近光灯","我不必开启车灯","我开启示宽灯"],"c":"作为汽车驾驶员，您必须打开近光灯。日间行车灯不够，因为隧道内的光照条件不能与日光相比。您有义务让您的车辆被看见。"},"1.4.42-130":{"q":"该交通标志表示什么？","o":["下一个紧急停车带内可能有车辆","发生抛锚时，应当在所标示的紧急停车带停车","你可以在此停车休息"],"c":"该交通标志向您表示应急停车带。如果您发生故障，可以而且应该在那里停留。那里可能已有车辆。应急停车带不得用于休息。"},"1.4.42-131":{"q":"看到该交通标志时必须怎么做？","o":["摘下你的太阳镜","开启近光灯","开启危险警示灯"],"c":"该交通标志位于隧道入口前。打开近光灯并摘下墨镜以获得不受限制的视野。"},"1.4.42-132":{"q":"你驶入一处如此标示且照明明亮的隧道。应当怎么做？","o":["开启近光灯行驶","不开灯行驶","开启日间行车灯行驶"],"c":"即使灯火通明的隧道也达不到日光条件，因此您需要打开近光灯驶入，以使车辆可被识别。此情况下日间行车灯完全不够。"},"1.4.42-133":{"q":"该交通标志组合表示什么？","o":["- 交通安宁区","- 步行区","- 儿童游乐场"],"c":"该交通标志指向交通稳静区的结束。现在重新适用更高的速度规定。作为汽车驾驶员，您在驶出时没有先行权，驶入时必须小心。"},"1.4.42-134":{"q":"该交通标志表示什么？","o":["干道","城镇外车行道上禁止停放","快速公路"],"c":"您在一条优先道路上行驶。在每个您享有先行权的交叉路口或丁字路口，该交通标志都会重复出现。在城镇外，禁止在优先道路上泊车。在这些道路上人们行驶相对较快，停放的车辆会成为妨碍或威胁。"},"1.4.42-135":{"q":"该交通标志表示什么？","o":["编号的改道路线","3 号有轨电车线路","编号的地下停车场"],"c":"该交通标志表示带编号的绕行路线。由于有多条绕行路线，它们被编号。因此您可以确切知道该往哪里行驶。"},"1.4.42-136":{"q":"看到该交通标志组合时必须注意什么？","o":["如果我沿干道行驶，我必须发出左转信号","如果我继续直行，我必须发出右转信号","规定交通必须向左行驶"],"c":"由于附加标志，优先道路转向。这是一条转弯的优先道路。如果您继续沿优先道路行驶，需要打转向灯示意。您必须照顾横穿街道的行人，必要时必须停车。答案“必须向左行驶”是错误的，因为该交通标志并未规定行驶方向。"},"1.4.42-137":{"q":"在设有此类自行车保护车道的道路上，正确的做法是什么？","o":["- 必要时在保护车道上行驶，前提是不危及骑自行车者","- 任何情况下都不得在保护车道上行驶","- 利用保护车道以便停放"],"c":"该方向标志表示骑行者的安全区域。作为车辆驾驶员，只有在排除对骑行者的风险时，您才可以驶上指定的自行车道。此处严格禁止泊车。"},"1.4.42-138":{"q":"看到该交通标志时必须怎么做？","o":["如果明显有行人想横穿道路，我必须用适中的车速驶近","我必须让行人先横穿道路","如果交通排队停滞，我不得停驻在人行横道上"],"c":"在行人过街设施处行人有优先权，因此车辆应始终以适中速度行驶并随时准备制动。在行人过街设施处严格限制超车，且在车流停滞时禁止在过街设施处停车。"},"1.4.42-139":{"q":"在此必须做好什么准备？","o":["行驶中的车流会停下","儿童会比平时更频繁地横穿道路","儿童会在看护下在道路上玩耍"],"c":"交通标志“交通协管员”，以前称学校交通协管员，表示交通协管员在管制交通。他们被允许让交通停下，以便让儿童横穿道路。您必须预料到车流会停下，以及儿童会比平常更频繁地在道路上行走。"},"1.4.42-140":{"q":"根据该交通标志适用什么？","o":["我必须以步行速度行驶","我不得妨碍行人","我只能停放在指定地点"],"c":"在交通稳静区内，您只允许以 4 至 7 km/h 的最高步行速度行驶，即一挡、不给油。街道可完全由行人使用。儿童被允许在街上玩耍。请特别专注并随时准备制动。不得妨碍或危及行人，您可能需要等待。由于此处允许在街上玩耍，您必须更加注意儿童。您只允许在标识的区域内泊车。"},"1.4.42-141":{"q":"该交通标志组合对你意味着什么？","o":["我在一条向左弯曲的干道上","我不允许右转或直行","如果我继续直行，我必须让从右侧驶来的车辆先行"],"c":"该交通标志表示优先道路的走向。附加标志表示向左转弯；如果您沿此方向行驶，您仍将在优先道路上。"},"1.4.42-142":{"q":"看到该交通标志时必须注意什么？","o":["儿童可以在整条道路上玩耍","机动车必须以步行速度行驶","行人有权使用道路的全部宽度"],"c":"对于这个问题，三个答案都正确。在“交通稳静区”内，行人可以使用街道的整个宽度，儿童可以在街上玩耍，您只能以步行速度行驶。"},"1.4.42-143":{"q":"该交通标志表示什么？","o":["海关检查点","收费道路","禁止过境交通"],"c":"当您看到该交通标志时，您正驶近一个海关办事处。这意味着您可能遇到交通拥堵，因此必须减速。您也可能被检查，所以请把所有证件准备好。遵循海关人员的指示。"},"1.4.42-144":{"q":"在此情况下哪项正确？","o":["- 城镇建成区结束","- 城镇建成区开始","- 改道路线结束"],"c":"村牌的下半部分表示封闭式村镇的结束。上半部分表示下一个城镇。您站在道路左侧。"},"1.4.42-145":{"q":"在像这样的一种交通情况下必须遵守什么？","o":["- 为绕过障碍物而跨越中心线","- 为超车而跨越中心线","- 如果会危及其他交通，则不跨越中心线"],"c":"导向线的作用是分隔车道。因此，只有在避开障碍物或超车时才可越过它们。且只有在不会危及任何道路使用者时才允许这样做。"},"1.4.42-146":{"q":"该交通标志表示什么？","o":["紧急停车和抛锚停车带","临时增设的车行道","供休息和换驾驶人的停车处"],"c":"如果您驾驶车辆，只有在发生紧急情况或故障时，才可以使用应急停车和故障停车带。"},"1.4.42-147-M":{"q":"你在一条设有自行车保护车道的道路上行驶。你可以如何使用该保护车道？","o":["- 必要时在保护车道上行驶","- 在保护车道上停放","- 在保护车道上停车"],"c":"如有必要，您可以使用自行车道，前提是不会危及或妨碍骑行者。"},"1.4.43-101":{"q":"车辆上的红-白警告牌可以表示什么？","o":["城镇内停放在车行道上的拖车","超宽的车辆","运输危险货物的车辆"],"c":"红白警告标志指向超宽车辆（例如异常宽的农用车辆）。停放在城镇内的拖车必须点灯或用反光警告标志标识。因此，警告标志并非指危险品卡车。"},"1.5.01-001":{"q":"为保护环境，必须注意什么？","o":["停车时避免让发动机无谓地运转","避免无谓地来回行驶","过于频繁地以高转速行驶"],"c":"为了环境保护，作为汽车驾驶员您必须注意以下事项：1. 避免不必要的行驶；2. 以中等转速平稳运转发动机；3. 在长时间怠速时关闭发动机——约一分钟后。一般而言，让发动机怠速运转会导致发动机更快磨损并浪费能源。因此您应在中等转速范围内预热发动机，并尽可能保持在该范围内。高转速会导致油耗增加，从而污染环境。"},"1.5.01-003":{"q":"为防止高油耗和过量污染物排放，必须定期保养什么？","o":["发动机空气滤清器","化油器或燃油喷射系统","点火系统"],"c":"车辆的油耗应尽可能低。作为汽车驾驶员，您因此应定期检查并保养车辆中所有对油耗重要的部件。这些例如是点火和喷射系统以及发动机空气滤清器和化油器。"},"1.5.01-004":{"q":"胎压明显低于建议值会导致什么？","o":["燃油消耗增加","轮胎磨损加剧","污染物排放减少"],"c":"轮胎气压过低也会导致油耗增加。保持轮胎滚动所需的功明显高于轮胎气压设置为正确值时。这会导致轮胎磨损加剧、油耗增加并危害环境。"},"1.5.01-005":{"q":"何时应关闭发动机以节省燃油并减少污染？","o":["当你必须在堵车中长时间等待时","当你必须在铁路道口或施工现场等待时","当你在“STOP”标志处停车时"],"c":"为了避免不必要的汽油消耗，在某些情况下应关闭发动机。这些情况例如是交通拥堵时或在铁路道口前。虽然起动时油耗会增加，但从停车一分钟起就能得到补偿。在停车标志处您不应关闭发动机。"},"1.5.01-006":{"q":"你的车辆漏油。一滴油可以污染多少饮用水？","o":["600 升","50 升","1 升"],"c":"您应极力避免漏油。因为仅仅一滴油就能污染多达 600 升水并使其不适合饮用。"},"1.5.01-007":{"q":"加油时必须注意什么？","o":["不要吸入燃油蒸气","当油箱已满且油枪已自动关闭时，不要继续加油","尽可能加到满溢"],"c":"吸入燃油蒸气对健康有害。因此，请确保正确使用加油枪，并在加油时注意任何缺陷。当油箱加满时，应关闭自动装置。这可以防止汽油或柴油溢出。此外，油箱内必须留有一些空气，以便燃油膨胀。"},"1.5.01-008":{"q":"车辆的发动机和排气系统被“改装增强”。可能产生什么后果？","o":["噪声污染增加","污染物排放增加","燃油消耗大幅降低"],"c":"改装过的发动机和消声器会造成更大的噪音污染。此外，车辆油耗更高。更有甚者，尾气排放增加并污染环境。在最坏的情况下，驾驶员可能面临吊销行驶证。"},"1.5.01-009":{"q":"如何减少轿车产生的噪声？","o":["以低发动机转速行驶","使用全地形轮胎","拆下空气滤清器"],"c":"在低速转速范围内，发动机运行比高转速区域更安静。深胎纹轮胎和不装空气滤清器行驶也会造成噪音污染。主要低速范围行驶的风格省油、环保且安静。但必须达到最低速度，否则发动机运转抖动、顿挫和喘振。发动机在无顿挫情况下仍能运转的转速越低，噪音越低。"},"1.5.01-010":{"q":"废油、润滑剂和汽车蓄电池可以在哪里得到妥善处置？","o":["送往回收中心","送往汽车修理厂","放进生活垃圾"],"c":"废油、润滑油和车辆蓄电池可以在回收中心或通过汽车修理厂妥善处置。这些物质绝不能与生活垃圾一起处置。它们属于特殊垃圾。"},"1.5.01-011":{"q":"匀速行驶时如何做到省油？","o":["使用定速巡航","以低发动机转速行驶","以高发动机转速行驶"],"c":"在恒速下，您可以通过以下措施节省燃油：1. 在低速转速范围内平稳行驶；2. 使用定速巡航。低速转速范围略高于发动机达到最佳性能所需的最低速度。如果您低于该速度行驶，发动机会顿挫；如果您高于该速度行驶，由于发动机性能，在高转速范围内油耗会增加。在低速转速范围内稳定行驶时，发动机运行平稳且油耗低。定速巡航可实现均匀的驾驶风格并减轻汽车驾驶员的负担。"},"1.5.01-012":{"q":"在哪个发动机转速范围内燃油消耗更低？","o":["低发动机转速时","高发动机转速时"],"c":"发动机在略高于最低速度的转速范围内油耗最低。这就是所谓的低速转速范围。在低速范围行驶时，转速应始终高于怠速。低于最低速度的发动机会运转抖动、顿挫、喘振或熄火。作为经验法则，发动机无顿挫运转的转速越低，能节省的燃油越多。"},"1.5.01-013":{"q":"由于铁路道口栏杆关闭，你不得不等待。此时如何帮助保护环境并节省燃油？","o":["关闭发动机","关闭自动启停功能","让发动机怠速运转"],"c":"在关闭的栏门前等待时，建议关闭发动机。一方面您节省燃油从而省钱，另一方面关闭的发动机环保。仅将挡位挂入空挡并不可取，因为即使在怠速下发动机也不会关闭并继续耗油。"},"1.5.01-014":{"q":"哪些措施有助于保护环境？","o":["- 低滚阻轮胎","- 低黏度发动机机油","- 空调系统"],"c":"关闭空调也能节省燃油。低滚动阻力轮胎为较低的滚动阻力而设计，可以节省燃油。低摩擦机油是具有改善的流动特性（即所谓粘度）的合成机油。它更快更好地润滑发动机并减少摩擦。这也会带来明显的燃油节省。只能使用发动机或车辆制造商认可的机油，以防止发动机损坏。"},"1.5.01-015":{"q":"为保护环境应当怎么做？","o":["- 排气冒大量烟时，我应安排对机动车进行检查","- 长时间等待时，我应关闭发动机","- 行驶时，我应使用较高的发动机转速范围"],"c":"您应避免高速行驶。如果车辆冒烟，请到修理厂检查和修理。"},"1.5.01-016":{"q":"定期保养车辆有助于实现什么？","o":["保持低燃油消耗","保持低排放水平","保障行驶安全性"],"c":"定期保养车辆有助于确保道路安全、低油耗和低排放。"},"1.5.01-017":{"q":"在哪些情况下应关闭发动机以节省燃油并减少环境污染？","o":["- 可预见我将要在堵车中等待较长时间","- 我必须在设有栏杆的铁路道口等待","- 我必须在“停车”标志处停车"],"c":"在有栏门的铁路道口前或遇到交通拥堵时，您应关闭发动机，因为您无法准确估计等待时间的长短。这样您既能减少对环境的影响，又能节省燃油。"},"1.5.01-102":{"q":"行驶时什么会造成不必要的噪声污染？","o":["不必要的急加速","有故障的排气装置","以低转速行驶"],"c":"如果您高速行驶或消声器有缺陷，噪音水平会增加。低速行驶也能降低油耗。有缺陷的消声器应在修理厂修理。"},"1.5.01-103":{"q":"为特别顾及环境和省油，应当如何换挡？","o":["尽可能早地换入高挡","尽可能晚地换入低挡","只有当达到转速上限时才换挡"],"c":"环保的换挡方式意味着尽早升挡、迟些减挡。不要将挡位开到高转速，因为这会导致最高油耗。您应从一挡起步，然后尽可能直接换到二挡。然而，在某些交通情况下，例如在高速公路加速车道上或超车时，有必要高转速行驶。在这种情况下您当然应该这样做。"},"1.5.01-104":{"q":"行驶时为避免污染并节省能源，什么很重要？","o":["定期检查燃油消耗","定期检查发动机调校","定期清洗发动机，每年至少四次"],"c":"低油耗意味着环保和节能的驾驶。这需要定期检查油耗值，以便优化发动机正时并及时发现错误。"},"1.5.01-106":{"q":"燃油如何被浪费、环境如何被污染？","o":["以急躁的方式行驶","在信号灯前等待时“摆弄油门”","下坡时使用高挡"],"c":"如果您匆忙驾驶，不断在制动和加速之间切换并“玩油门”，您的车辆会消耗过多不必要的燃油。尤其是在加速时需要大量能量。在高挡下下坡行驶时，车辆驾驶员不必要地加重了制动器的负担。但这不会导致油耗增加。"},"1.5.01-108":{"q":"什么表明由于发动机严重磨损或调校不当而导致汽油消耗过高？","o":["排气冒出大量黑烟","排气中的冷凝水"],"c":"黑烟表示油耗增加。它可能与发动机控制系统的故障有因果关系。您务必要去修理厂。相反，从排气管滴下的冷凝水，或寒冷天气下的白色水蒸气，都是正常的。"},"1.5.01-109":{"q":"哪种驾驶方式会导致高燃油消耗？","o":["起步迅猛和不必要的加速","把所有挡位都拉到高转速","高速行驶"],"c":"由于空气阻力增加，高速需要更大的功率。因此油耗增加。如果驾驶员快速行驶或不必要地加速，这种驾驶风格也会导致油耗增加。挡位在满转速下行驶时同样如此。"},"1.5.01-110":{"q":"如何做到顾及环境的驾驶？","o":["及时减速，并在下一个信号灯为红灯时利用车辆的惯性","避免不必要的加速和不必要的制动","当信号灯变绿时总是全力加速"],"c":"避免不断的加速和制动。加速会消耗不必要的燃油，例如在红灯前可以通过松开油门踏板来避免。最大加速会导致高污染物排放和高噪音以及环境污染。"},"1.5.01-112":{"q":"如何用更少的燃油行驶更多里程？","o":["以尽快达到尽可能高的挡位的方式加速","行驶时提前预判，以避免不必要的加速和制动","把所有挡位都拉到尽可能高的转速"],"c":"在低速转速范围内油耗最低。及时升挡可避免高转速、耗油的行驶。预见性驾驶可节省燃油，因为您可以提前松开油门踏板，让车辆凭借现有动能滑行。"},"1.5.01-114":{"q":"什么有助于节省燃油并减少污染？","o":["购买机动车时注意其燃油消耗","通过提前预判和相应驾驶，促成车流顺畅","尽可能使用公共交通、骑自行车或步行"],"c":"在购买汽车之前，驾驶员可以查看哪种车型油耗低。此外，经济驾驶也有助于节省。"},"1.5.01-115":{"q":"你可以做什么来帮助保护环境？","o":["- 短途行驶","- 全速行驶","- 在拥挤的城市中心行驶"],"c":"保护环境的最佳方式是少开车。所有并非绝对必要的行程都应避免。某些驾驶风格会额外耗油：短途行驶，尤其是发动机还冷时，走走停停的交通，例如拥挤的市中心，以及寻找停车位。更有甚者，在交通繁忙的地区，因车辆尾气排放形成烟雾的风险增加。全油门行驶不仅会造成噪音，而且您的油耗会不成比例地增加。然而，一旦您只比最高速度低 20%，您就能减少约 40% 的油耗。拼车也有益于环境。"},"1.5.01-116":{"q":"如何实现高效的燃油消耗和低污染物排放？","o":["保持正确的胎压","以低发动机转速保持平稳的驾驶方式","充分利用每个挡位的全部转速范围"],"c":"在起步前，您应确保轮胎气压设置正确。关于此主题的所有重要信息都可以在您车辆的操作说明书中找到。如果轮胎内部气压过高或过低，污染物排放都会增加。即使是不平稳的驾驶也会导致高油耗。因此，与其加速到转速上限才换挡，您应在低或中等转速范围内升挡。这意味着您消耗更少的燃油，同时减少汽车的尾气排放。"},"1.5.01-117":{"q":"其他道路使用者提醒你注意你的排气持续冒出浓烟。必须怎么做？","o":["尽快对车辆进行检查","尽早换入低挡","尽早换入高挡"],"c":"您应去修理厂检查损坏情况。因为强烈的烟雾表明发动机或燃油系统有缺陷。此外，逸出的气体对环境有害，烟雾会妨碍其他道路使用者的视线。"},"1.5.01-118":{"q":"为什么使用低黏度发动机机油有益？","o":["- 在发动机中产生更少的摩擦","- 降低燃油消耗","- 可作为生活垃圾处置"],"c":"低摩擦机油以更好的流动特性为特征。这些是通过其改善的粘度减少发动机摩擦并优化润滑的合成机油。这样可以节省燃油。使用低摩擦机油时，必须注意发动机或车辆制造商的认可。"},"1.5.01-119":{"q":"启动车辆后应当怎么做？","o":["- 尽快起步驶离","- 尽可能以低发动机转速行驶","- 如有可能，让停着的车辆发动机预热"],"c":"启动汽车后，您应直接在低速范围内驶出。原地预热发动机是禁止的并浪费燃油。在低速范围内可以温和地预热发动机。直接高转速行驶对发动机不利。一般而言，发动机在高转速下耗油更多。在过低转速下，发动机会顿挫和喘振。发动机的油耗在略高于最低速度时最低。"},"1.5.01-120":{"q":"如何节省燃油？","o":["- 拆下任何非必要的车顶箱等","- 以有预见性的方式行驶","- 全年使用冬季轮胎行驶"],"c":"您可以通过以下方式节省燃油：1. 平稳且预见性地驾驶，避免高转速；2. 拆除未使用的车顶装置，因为它们会因空气阻力而增加油耗；3. 在温暖季节将冬季轮胎换成夏季轮胎。平稳驾驶意味着避免不必要的加速和减速。例如，通过缓慢滑行接近红灯，如果到达交通信号灯时已经变绿，您可以利用剩余的动能继续行驶。只需给油，与从完全静止起步相比可节省燃油。"},"1.5.01-121":{"q":"如何最大限度减少轮胎磨损？","o":["我尽可能避免急加速","我定期检查轮胎气压","我全年使用冬季轮胎"],"c":"在非冬季天气使用冬季轮胎会导致轮胎磨损加剧。强烈加速伴随着磨损增加。必须遵守车辆制造商推荐的轮胎气压。气压过低会显著增加轮胎磨损。如果气压过低，轮胎每转一圈的变形都会比气压正确时更大。由此轮胎的帘布层相互摩擦。可能产生热量，从而不可修复地损坏轮胎。"},"1.5.01-122":{"q":"哪些车辆通常不受“环保区”机动车通行禁令的限制？","o":["农林拖拉机","执行任务的救护车","环保区内居民拥有的所有机动车"],"c":"“环保区”的交通禁令不适用于正在执行任务的救护车。农林业的拖拉机也不受影响。"},"1.5.01-123":{"q":"何时关闭内燃发动机是明智的？","o":["在铁路道口长时间等待时","装卸车辆时","在设有停车标志的交叉路口停车时"],"c":"在关闭的铁路道口前较长的等待时间以及装卸车辆，都可成为关闭内燃机的理由。这节省燃油并减少噪音。在停车标志处的等待时间通常很短，让交叉方向来车通过后通常很快就能继续行驶。因此，在这种情况下不关闭内燃机。"},"1.5.01-124":{"q":"您在高峰时段穿过城市车流。走走停停的驾驶会有什么影响？","o":["- 消耗更多燃油","- 产生更多废气","- 对他人造成更多滋扰"],"c":"走走停停的交通中油耗更大，因为驾驶员必须更频繁地制动和加速。这会导致更多尾气，并可能干扰其他道路使用者。"},"1.5.01-125":{"q":"环保且节能驾驶的前提是什么？","o":["定期检查轮胎气压","定期进行车辆保养","定期清洗发动机"],"c":"轮胎气压对油耗有很大影响，因为它影响滚动阻力。定期保养车辆有助于低油耗和低排放。"},"1.5.01-126":{"q":"您驾驶一辆手动挡机动车。在城镇内道路中，哪种驾驶方式会导致更高的油耗？","o":["猛加速","高转速行驶","高挡位行驶"],"c":"猛烈加速时，您比正常加速时消耗更多燃油。速度越高，消耗的燃油越多。"},"1.5.01-127":{"q":"您驾驶一辆手动挡机动车。如何降低车辆油耗？","o":["尽早换入下一个高挡位","采用预见性驾驶方式，避免频繁变速","高转速行驶"],"c":"发动机转速越高，消耗的燃油越多。如果您有预见性地行驶，可以避免不必要的加速和制动。"},"1.5.01-128":{"q":"如何降低机动车产生的噪音？","o":["以低转速行驶","使用滚动噪音低的轮胎","拆下空气滤清器滤芯"],"c":"发动机转速越高，发动机声音越大。轮胎在质量上存在差异。购买轮胎时，请注意滚动噪音。"},"1.5.01-129":{"q":"为保护环境，您应该怎么做？","o":["- 若排气管冒烟过多，应送检机动车","- 长时间等待时关闭发动机","- 避免不必要的来回行驶"],"c":"发动机在静止时也会燃烧燃油，如果您较长时间停车，应关闭发动机。如果出现异常迹象，如冒烟，您应检查您的车辆。"},"1.5.01-130":{"q":"您驾驶一辆手动挡机动车。行驶中，哪些情况会造成可避免的噪音污染？","o":["不必要地猛加速","消声器损坏","低挡位高速行驶"],"c":"发动机转速越高，发动机声音越大。改装的排气系统通常比标准排气系统更响。猛烈加速时您会比正常加速时消耗更多燃油。"},"1.5.01-131":{"q":"您在平坦车道上驾驶一辆手动挡机动车。为以特别环保且经济的方式行驶，应如何换挡？","o":["尽可能早地换入高挡位","尽可能晚地换回低挡位","在某挡位一直行驶到发动机高转速区间后再换入高挡位"],"c":"加速时，始终尽量保持发动机转速尽可能低。滑行时，尽可能迟些换挡，以利用发动机制动效果，并尽可能少用制动器。"},"1.5.01-132":{"q":"您驾驶一辆手动挡机动车。哪种行为会污染环境？","o":["不均匀的驾驶方式","在交通信号灯前等待时频繁踩加速踏板","高挡位下坡行驶"],"c":"恒速比不断减速和加速消耗更少燃油。在红灯处不必要的加速会不必要地燃烧燃油。"},"1.5.01-133":{"q":"您驾驶一辆手动挡机动车。如何实现高效的燃油消耗？","o":["保持正确的轮胎气压","采用低转速、均匀的驾驶方式","加速时尽可能晚地换入高挡位"],"c":"恒速时比不断减速和加速时消耗更少。轮胎气压对油耗有很大影响，因为它影响滚动阻力。"},"1.5.01-134":{"q":"启动车辆后应注意什么？","o":["- 尽快起步","- 以低转速行驶","- 如有可能，让停放的车辆发动机预热"],"c":"不必要的原地停留并让发动机空转不必要地污染环境。只有在您想驶出时才启动发动机。发动机转速越低，燃烧的燃油越少。"},"1.7.01-003":{"q":"什么会影响弯道上离心力的大小？","o":["弯道半径","车速","逆风"],"c":"离心力可能将您的车辆甩出弯道。速度加倍时，离心力增加到四倍。此外，弯道半径也影响这一力。弯道越急，离心力增加得越多。因此，在急弯中您必须提前制动。"},"1.7.01-006":{"q":"潮湿环境会削弱鼓式制动器的效能。您应该怎么做？","o":["我谨慎行驶以干燥制动器","我在停车状态下反复踩制动器","我补充制动液"],"c":"鼓式制动器可能变干。为此，作为汽车驾驶员您要谨慎制动。鼓式制动器发热，水可以蒸发。当然，您只在交通流允许时制动。必须不惜一切代价避免追尾。留意后方交通。"},"1.8.01-003":{"q":"带有两分的违章记录何时会从道路交通违法者中央登记册中删除？","o":["- 5年","- 3年","- 2年"],"c":"已被记分并记入驾驶适格登记册的已登记违法行为（记两点），五年后超过时效。严重违法行为一律记两点。"},"2.1.01-001":{"q":"什么会导致弯道上侧滑？","o":["减震器故障","胎压不足或胎压不均","载重过小"],"c":"有缺陷的减震器可能导致车辆在转弯时侧滑或甩出弯道。制造商规定的正确轮胎气压对于车辆在弯道中的稳定姿态很重要。它是针对车辆的整体设计而设定的。轮胎气压过低或差异过大都会降低行驶稳定性，并增加转弯时侧滑的风险。负荷过大会影响行驶稳定性。不存在装载过少的情况。"},"2.1.01-003":{"q":"什么会导致弯道上侧滑？","o":["急刹车","在湿滑车道上高速行驶","驶出弯道时轻微加速"],"c":"在弯道中，以下因素可能导致侧滑：1. 速度过高；2. 潮湿或结冰的道路；3. 强烈制动。在转弯时，大部分静摩擦力被用于使车辆保持在车道内的转向力。如果您制动过多，静摩擦力则大部分被用于传递制动力。结果转向力太低，无法抵消离心力；速度过高时同样如此。在潮湿道路上，路面与轮胎之间的水膜会降低抓地力并促使侧滑。"},"2.1.01-004":{"q":"什么会导致危险情况？","o":["切弯（占道抄近）","过晚改用近光灯","与前车距离过远"],"c":"切弯时，弯道中的车辆被引导向内侧，并且还使用对向车道以便更快前进。这对对向来车构成严重威胁，并可能导致严重事故。过晚减光也可能危及对向驾驶员，因为他们被晃眼并几乎盲目行驶。"},"2.1.01-005-B":{"q":"如果白色汽车没有停车，您会怎么做？","o":["减速，放弃您的优先权","鸣喇叭并试图从汽车前方通过"],"c":"即使您享有先行权：在其他参与者交通行为不良时也不要冒险。用喇叭声提醒其错误，但不要坚持您的权利，应放弃先行权。同时降低您的速度。"},"2.1.01-006":{"q":"什么会给摩托车骑行者带来特殊风险？","o":["打开面罩骑行","大雨中骑行","路面铺装的变化"],"c":"如果您打开面罩骑行，昆虫随时可能飞进来。这可能非常疼痛并使人分心。如果路面发生变化，由于抓地力不同，有摔倒的风险。在大雨中，摩托车比汽车更容易发生水滑。"},"2.1.01-007-M":{"q":"您现在应该怎么做？","o":["我减速，以便超车车辆能在我前方并入","我加速，以便超车车辆能在我后方并入","我保持车速，因为有足够的安全距离"],"c":"超车车辆可能无法按计划完成其超车动作。为避免事故，您应让超车车辆并入车道。"},"2.1.01-008-M":{"q":"为什么您应该让卡车变更车道？","o":["因为卡车驾驶员可能看不到我","因为我应对卡车表现出应有的体谅","因为此处适用拉链式交替合流规则"],"c":"如果您处于卡车的盲区，而卡车突然加速驶离，可能会发生危险情况，您将不得不减速。由于与前车之间有足够空间，您应考虑到卡车并让它能够变换车道。"},"2.1.01-009":{"q":"作为摩托车骑行者，为什么在特别蜿蜒的路段采用预见性驾驶方式尤为重要？","o":["因为随着道路延伸，转弯半径可能变小","因为否则我无法及时看到车道上的污物","因为这样我能及时对迎面来车的动作做好准备"],"c":"通过有预见性地骑行，您能及时识别对向交通的行为以及潜在危险情况，如道路上的污物或弯道半径的变化，并相应地调整您的骑行行为。"},"2.1.01-010":{"q":"作为摩托车骑行者，您很容易被其他车辆驾驶员忽视。如何降低这一风险？","o":["我避免在其他车辆侧面的盲区中停留过久","我尝试从其他车辆驾驶员的角度观察路况","转弯前，我尝试与附近的其他驾驶员建立眼神接触"],"c":"试着设身处地为相关驾驶员着想，以便更好地理解他们接下来可能做什么。这样，您或许能识别潜在危险并及时作出反应。\n如果您行驶在车辆的侧方盲区，驾驶员将无法看到您。如果可能，请以不让您不必要地长时间处于盲区的方式行驶。在转弯前，您还应尝试与相关驾驶员进行目光接触，以确保他们能看到您。"},"2.1.01-101":{"q":"什么会导致危险情况？","o":["单侧制动过猛的制动器","转向盘自由行程过大","收音机交通信息接收受干扰"],"c":"如果脚制动器单侧作用强烈，车辆在制动时可能向侧方甩出。汽车可能侧滑并翻车。因此，制动力不均衡极其危险。高速时过度转向也可能导致侧滑，因为您无法再正确保持车道。受干扰的交通广播不是技术上的危险缺陷。"},"2.1.01-102":{"q":"在车内听大声音乐——尤其是低音音量极大时——会有什么影响？","o":["盲人在车辆附近时会失去方向感","驾驶员的注意力会受到明显损害","这使盲人更容易辨认道路位置"],"c":"车内大声的音乐会带来两个负面影响：驾驶员被音乐分心，无法专注于道路。尤其是低音会造成盲人道路使用者的强烈不确定感。他们尤其在低频音乐下可能失去方向感。"},"2.1.01-103":{"q":"行驶中什么会造成危险？","o":["单侧反应过猛的行车制动器","转向系统自由行程过大","近光灯故障"],"c":"如果近光灯不工作，一方面您看不清，另一方面您被看到的效果也更差。如果行车制动器单侧作用过强，车辆可能偏转或制动距离更长。如果转向间隙过大，转向指令将不会被传递。"},"2.1.02-002":{"q":"您在一条狭窄道路上行驶。前方约20米处一名儿童突然跑上车道。在哪种情况下，即使紧急制动也无法避免碰撞？","o":["50 km/h","30 km/h","20 km/h"],"c":"对于这个问题，您必须先计算反应距离和危险制动距离。在 50 km/h 时，反应距离为 50/10 x 3 = 15。因此有 15 米的反应距离。危险制动距离由以下计算得出：[(50/10 x 50/10) / 2] = 12.5。50 km/h 是正确答案。"},"2.1.02-003":{"q":"您为什么必须刹车？","o":["因为有人正走上车道","因为乘客正下电车","因为卡车正切入我的车道"],"c":"您必须预料到停在静止卡车前的人会向左移动。制动是为了保护该人。"},"2.1.02-004":{"q":"现在正确的做法是什么？","o":["我停车","我像之前一样继续行驶","我加速"],"c":"右转时，您必须始终注意驶近的行人和骑行者。他们可能在您前方横穿道路。"},"2.1.02-005-M":{"q":"在这种情况情况下您必须预料到什么？","o":["儿童走到车道上","人们从靠车道一侧下车","前方有行人过街横道"],"c":"该道路标志提醒对儿童的格外警惕，他们可能在车辆之间横穿道路。\n此外，您必须预料到有人会从道路一侧下车。"},"2.1.02-006-M":{"q":"现在正确的做法是什么？","o":["我停车","我像之前一样继续行驶","我加速"],"c":"由于有人想要横穿交叉路口，您必须停车并让该人通过交通信号灯。"},"2.1.03-001":{"q":"当您在高速公路左侧车道高速行驶时，必须预料到什么？","o":["您前方的驾驶者可能突然驶出车道超车","即使轻微、突如其来的侧风也会影响行驶稳定性","如果您开启远光灯，前方行驶的车辆就不会驶出车道超车"],"c":"高速时，摩托车对侧向来风非常敏感。小而快的摩托车很难被看见，其他车辆因此可能看不到您。"},"2.1.03-002":{"q":"摩托车在高速时何时有发生横向偏移的危险？","o":["当您超越卡车时","在强侧风中高速驶过桥下时","当前轮盘式制动器两侧制动效果不同时"],"c":"突然的侧风增加摩托车侧偏的风险。突然的侧风可能出现在驶出桥下、驶出隧道时或在超越卡车时。"},"2.1.03-003":{"q":"长时间干燥天气后开始下雨时，您必须预料到什么？","o":["路面形成危险的油膜","头盔面罩或护目镜视线不良","更短的制动距离"],"c":"雨水清理道路上的部分污物。如果天气长期干燥，道路上会积聚大量污物。加上水后，会在路面上形成一层薄膜，使路面更滑并延长制动距离。您还必须预料到头盔或护目镜上的视线不良。"},"2.1.03-004":{"q":"您突然驶入一段有松散碎石的路面。您会怎么做？","o":["如有可能避免制动","如有可能保持行驶路线","使用手刹猛刹车"],"c":"即将推出……"},"2.1.03-005":{"q":"如果您紧靠标线中心线绕行左弯，可能会发生什么？","o":["由于车身倾斜，您身体的上部可能被迎面来车撞击","摩托车可能压到中心线并从您身下打滑","只要轮胎是新的就没有危险"],"c":"左转时，靠近中线很危险。由于向左倾斜，您可能被对向行驶的车辆撞到。中线等道路标线是湿滑的，如果您的摩托车压在其上，可能打滑导致摔倒。"},"2.1.03-007":{"q":"潮湿的鹅卵石路面有哪些危险？","o":["制动器抱死倾向增加","摔倒危险增加","加速时后轮打滑空转"],"c":"鹅卵石路面湿滑，因此会增加摔倒的风险，或使轮胎在加速时失去对路面的附着力而打滑，同时也使制动器容易抱死。"},"2.1.03-009":{"q":"下雨时您尤其应记住什么？","o":["透过护目镜或头盔面罩的视线会明显变差","路面湿滑时路面损坏不易察觉","其他车辆溅起的水花会进一步降低能见度"],"c":"雨水降低能见度。潮湿时路面更不易被看清。来自其他车辆的水花也可能降低能见度。您的面罩也会积聚水滴，进一步降低您的能见度。"},"2.1.03-011":{"q":"当您的车道上有电车轨道时，您应记住什么？","o":["应始终尽可能以最大的角度横穿电车轨道","电车轨道上摔倒的危险总是更大","应始终尽可能以最小的角度横穿电车轨道"],"c":"有轨电车轨道由金属制成，是湿滑的。因此摩托车在其上有更高的打滑和摔倒风险。横穿时您应尽量与其垂直，以避免打滑。"},"2.1.03-012":{"q":"什么会导致弯道上摔倒的危险？","o":["车道上的油污","车道标线","弯道外缘高于内缘"],"c":"在弯道转弯时，湿滑的表面如车道标线、道路上的油、污物、井盖、沙或树叶都可能导致摔倒。"},"2.1.03-013":{"q":"什么会导致弯道上摔倒的危险？","o":["车道上的井盖","车道上的树叶","车道上的沙土"],"c":"在弯道转弯或制动时，湿滑的表面如车道标线、道路上的油、污物、井盖、沙、灰尘、碎石、潮湿表面、鹅卵石或树叶都会增加摔倒的风险。"},"2.1.03-014":{"q":"何时您必须特别小心地使用制动器？","o":["在鹅卵石路面上行驶时","开始下雨时","在附着良好的混凝土车道上"],"c":"在湿滑表面上（潮湿路面、鹅卵石、土路）制动效果较差，需要谨慎施加。"},"2.1.03-015":{"q":"在潮湿路面上，什么会导致水滑（湿滑路面打滑）？","o":["高速","磨损的轮胎","车道上的沟槽"],"c":"水滑（Aquaplaning，也称 hydroplaning）发生在轮胎胎纹深度不足以排开积聚的水量时，或由于高速（从 60 km/h 起）需要排开的水量过大时。此外，路面上积水的车辙也有利于这一效应的形成。"},"2.1.03-017-B":{"q":"为什么在此超车可能有危险？","o":["超车道上仍有雪泥","雪泥可能被溅起并影响能见度","因为雪泥下方路面也可能结冰"],"c":"在雪泥中超车可能导致许多危险。雪下可能有一层冰，使超车变得危险。此外，您可能向其他车辆抛洒雪块，或自己开始来回摆动。"},"2.1.03-018":{"q":"如果您的车辆受到强侧风影响，您必须怎么做？","o":["迎风转向","减速","迅速加速"],"c":"如果您的车辆受到强侧风的影响，您不应加速，而应减速并反向打方向。您开得越快，就越难将车辆保持在道路上，因为侧风可能导致车辆侧滑。"},"2.1.03-020":{"q":"强侧风何时可能特别危险？","o":["超越卡车时","驶过桥梁时","驶过林间防火隔离带时"],"c":"风向变化在驾驶时很危险。突然的阵风可能抓住您的车辆并将其推向一侧。您必须用力反向打方向以将车辆保持在车道内。如果风向改变，您必须迅速反应并调整您的转向行为。强侧风尤其在桥梁上以及平坦、无建筑和无树木的地形上很危险。如果您超越一辆或多辆卡车，在进入卡车尾流和驶出卡车时，您必须预料到压力条件的变化。在林中通道或驶出树林区域时，强侧风也可能突然袭来。"},"2.1.03-021-B":{"q":"在此您必须预料到什么？","o":["您的车辆可能被强侧风吹向左侧","超车时，当您进入卡车的尾流区，车辆会被拉向右侧","您前方的车辆可能被吹向右侧"],"c":"如果您在来自右侧的强侧风中行驶在高速公路上，侧风不断将汽车推向左侧。您必须向右反向打方向以保持在车道内。如果您超越一辆卡车，要预料到一进入卡车尾流，侧风的压力就立即消失。如果您继续反向打方向，就有撞向卡车的风险。由于侧风来自右侧，前方的车辆可能被推向左侧。"},"2.1.03-022-B":{"q":"强侧风从右侧吹来。超车时您何时特别容易遭遇危险？","o":["当您进入卡车的尾流区时","当您驶出卡车的尾流区时","超车后变更车道时"],"c":"如果来自右侧的强侧风存在，作为汽车驾驶员，当您在超车动作中进入卡车尾流时尤其危险。这一危险源于来自右侧的强侧风将您的车辆推向左侧，于是您自动开始反向打方向。当您超越卡车时，您落入其尾流；侧风瞬间消失，您必须调整转向。一旦您驶出尾流，侧风的压力又重新开始；因此您必须再次反向打方向。"},"2.1.03-023":{"q":"为什么在大雨中您必须减速？","o":["因为制动距离增大","因为能见度降低","因为可能发生水滑（湿滑路面打滑）"],"c":"挡风玻璃或面罩上的水会折射光线并使视线变差，扬起的水也会妨碍视线。潮湿道路上由于抓地力较低，制动距离更长。轮胎的胎纹排出水。高速时，需要排出的水量过大，存在水滑的风险。在这种情况下，道路与轮胎之间没有接触。车辆将无法再控制。"},"2.1.03-024-B":{"q":"在此什么对交通安全不利？","o":["能见度差","轮胎在潮湿车道上的附着力降低","迎面来车的近光灯"],"c":"雨水和扬起的水形成水雾，可能显著影响交通安全。要预料到由于潮湿路面，轮胎的抓地力明显低于干燥道路，而且这会延长您的制动距离。对向来车的近光灯不影响交通安全，因为汽车驾驶员不会因此被晃眼。"},"2.1.03-025":{"q":"如果路面突然变差，会导致什么？","o":["打滑和侧滑的危险","轮胎噪音的变化","更长的反应距离"],"c":"随着路面状况变差，总是会导致附着力的变化和恶化。随着车轮失去静摩擦，车辆会更快地打滑和侧滑。轮胎噪音也取决于路面状况，并会变化，例如当道路从铺装路面变为鹅卵石路面时。"},"2.1.03-027":{"q":"沿林荫大道行驶时有哪些特殊条件？","o":["弯道往往非常狭窄且视线受阻","狭窄且常有横向坡度的车道在有迎面来车时需要特别谨慎","树木提供侧向保护"],"c":"道路通常非常狭窄。此外，为排出雨水它往往弯曲严重。因此，遇对向来车时应特别小心。由于树木，弯道不易看清。由于弯道中可能有对向来车，您必须特别谨慎驾驶。左转弯尤其危险。树木对驾驶员不提供任何保护，甚至不能挡风。"},"2.1.03-028":{"q":"正确的做法是什么？","o":["我刹车","我尽可能靠右侧行驶","我保持在车道中央"],"c":"在超越骑行者时，对向的卡车也部分驶上您的车道。请制动并尽量靠右行驶。"},"2.1.03-029":{"q":"您为什么现在应该刹车？","o":["- 绿色汽车","- 蓝色汽车","- 拖拉机"],"c":"雪对作为汽车驾驶员的您是一种特殊危险。您的车道被雪覆盖。此外，您的视线被雪堆遮挡。驶近的绿色汽车不遵守先行权。因此，您应提前制动，因为由于湿滑，制动距离延长了。绿色汽车可能也被雪堆妨碍。"},"2.1.03-030":{"q":"为什么您应做好在此必须停车的准备？","o":["因为卡车","因为摩托车骑行者"],"c":"街道看起来非常狭窄。要预料到当卡车驶近您时您必须停车。您应尽量靠右行驶并准备停车，以避免碰撞。"},"2.1.03-031-M":{"q":"在此您应做好准备应对什么？","o":["- 延长制动距离","- 对行驶稳定性产生不利影响","- 缩短制动距离"],"c":"道路上的污物会增加（而非减少）制动距离，并可能使道路更滑，从而影响车辆的稳定性。"},"2.1.03-032":{"q":"行驶中，您突然遇到一段有松散碎石的直路。正确的做法是什么？","o":["我谨慎减速","我尽可能保持直线行驶","我使用驻车制动器急刹车"],"c":"在路面有滚动碎石的笔直意外路段，出于安全原因您应谨慎减速，并尽可能保持您的行驶路线。"},"2.1.03-033":{"q":"现在正确的做法是什么？","o":["我减速","我避免突然的操作","我猛向右转向"],"c":"由于恶劣的天气条件，您应减速并避免急剧的转向动作（参见危险标志），否则您可能侧滑。"},"2.1.03-034":{"q":"水滑的影响可能是什么？","o":["车辆转向能力降低","车辆制动能力降低","轮胎静摩擦力增大"],"c":"发生水滑时，您的车辆与路面没有直接接触，因此转向指令和制动指令无法执行。"},"2.1.03-035":{"q":"强侧风正在吹。高速时您的摩托车何时有被横向吹偏的风险？","o":["- 超越卡车","- 驶出隧道","- 驶过桥梁"],"c":"在超越卡车、驶上桥梁和驶出隧道时，风况会发生变化。请做好应对侧风的准备。"},"2.1.03-036":{"q":"在这种情况下正确的做法是什么？","o":["我减速","我避免突然的转向动作","我急刹车"],"c":"该交通标志表示有侧滑和滑移的风险。为避免侧滑，您应减速，尤其是在下雨且树叶落到道路上时，如本例。猛烈制动、猛烈加速或急剧转向都可能导致轮胎失去抓地力，您可能侧滑或滑移。"},"2.1.03-037":{"q":"在此您应做好准备应对什么？","o":["延长的制动距离","我的车辆能见度差","增大的轮胎牵引力"],"c":"由于下雨，您应预料到其他车辆将无法看到您的车辆，并且由于抓地力降低，您的制动距离会更长。"},"2.1.03-038":{"q":"在此超车过程中您尤其会在哪里遭遇危险？","o":["当您驶入卡车的背风区时","当您驶出卡车的背风区时","超车后变更车道时"],"c":"如果来自右侧的强侧风存在，作为汽车驾驶员，当您在越野时于卡车尾流中超车时尤其危险。这一危险源于来自右侧的强侧风将您的车辆推向左侧，于是您自动反向打方向。当您超越卡车时，您滑入其尾流；侧风瞬间消失，您必须调整转向。一旦您驶出尾流，侧风的压力又重新开始；您必须再次反向打方向。"},"2.1.03-039-M":{"q":"如果您紧靠车道标线通过弯道，可能会发生什么？","o":["- 被迎面来车撞击","- 在试图避让迎面来车时失去对摩托车的控制","- 能清楚地看到弯道对面"],"c":"始终确保您和您的摩托车不越过中线。如果您在盲弯中切弯，您不必要地危及自己和对向交通。因为您可能被对向来车撞到，或在避让动作中失去对摩托车的控制。"},"2.1.03-040":{"q":"在驶过弯道时，什么会增加摩托车摔倒的风险？","o":["车道上的漏油","车道上的凸起","车道向弯道内侧倾斜"],"c":"道路上的油会因路面湿滑而显著降低轮胎的抓地力，从而增加转弯时摔倒的风险。\n路面不平整，如颠簸，会降低轮胎的抓地力，从而增加摔倒的风险。"},"2.1.03-041":{"q":"遇到潮湿的路面标线时，如何降低摔倒的风险？","o":["我尽可能避免行驶在路面标线上","横穿路面标线时我走尽可能短的距离","在遇到路面标线之前我尽可能急地刹车"],"c":"由于车道标线湿滑，尤其是在潮湿时，您应尽可能避免压过它们。如果无法绕开它们，您应走最短路线压过它们，以尽量降低摔倒的风险。\n由于潮湿，您在此应避免加速或制动，以尽量降低摔倒的风险。"},"2.1.03-042":{"q":"在潮湿的鹅卵石路面上行驶时，您应预料到什么？","o":["制动时车轮抱死的倾向很大","加速时后轮迅速打滑","转向时前轮牵引力增大"],"c":"不平整且潮湿的路面因而抓地力更小，会增加加速时后轮空转或打滑的风险。\n在潮湿的鹅卵石路面上制动时，抱死倾向会增加，这可能导致后轮更快地向侧方打滑。\n抱死倾向意味着制动时前轮负载增加，而后轮卸载。"},"2.1.03-043":{"q":"在环境温度较低时驾驶摩托车，您应考虑什么？","o":["头盔面罩容易起雾","手指冰冷时无法安全操作驻车制动手柄","寒冷能提高注意力"],"c":"如果外部空气温度与头盔内的空气温度不同，头盔会起雾。这会极大地影响能见度。\n此外，用冰冷的手指操作手刹杆更加困难。"},"2.1.03-044-M":{"q":"在这种情况下您必须预料到什么？","o":["我的车辆可能被推向左侧","驶入卡车旁边的避风区时，我的车辆可能被推向右侧","我前方的卡车可能被推向右侧"],"c":"您可以从风向袋看出正刮着来自右侧的强风。强风可能将您的车辆推向左侧。请做好向右打方向的准备。\n此外，当进入卡车尾流时，您必须预料到您的车辆会被推向右侧，因为卡车的大面积会挡住侧风。请做好向左打方向的准备，以避免与卡车相撞。"},"2.1.03-045-M":{"q":"大雨已在路面上形成大水坑。现在正确的做法是什么？","o":["- 缓慢通过以避免溅起水花","- 快速通过以保持摩托车的稳定性","- 抬起双脚以防弄湿"],"c":"在驶过大的水洼时，您很容易失去对摩托车的控制。缓慢骑行，不要抬脚，以保持摩托车稳定并避免溅起水花。"},"2.1.03-046":{"q":"长时间干燥期后开始下雨时，行驶中您应预料到什么？","o":["特别光滑的路面","透过头盔面罩的视线不良","更短的制动距离"],"c":"基本上，下雨时您必须始终预料到通过头盔面罩的能见度更差；如果长时间干燥，道路上会残留一层污物，下雨时会在路面上形成一层湿滑的薄膜，因此您必须预料到道路特别湿滑。"},"2.1.03-101":{"q":"水滑（湿滑路面打滑）尤其常发生在哪里？","o":["车道上的凹陷处","车道上有沟槽的地方","平交道口处"],"c":"如果速度过高和/或水量超过轮胎胎纹所能排出的量，就会发生水滑。一层水膜阻止轮胎与道路之间的接触。车辆不再可控。水滑的风险尤其存在于车辙和道路沉降处。铁路道口通常没有增加的水滑风险，因为水通常可以很好地流走。"},"2.1.03-102":{"q":"水滑（湿滑路面打滑）会导致什么？","o":["车辆无法再转向和制动","车辆可能驶离道路","转向变沉"],"c":"水滑（Aquaplaning 或 hydroplaning）可能导致既不能制动也不能转向。其结果是车辆不再能有意识地驾驶。它可能发生侧滑。这一效应是由一种在轮胎与道路之间滑动的水楔造成的。"},"2.1.03-103":{"q":"长时间干燥天气后开始下雨时，您必须预料到什么？","o":["路面形成危险的油膜","打开雨刮器后立即出现视线不良","更短的制动距离"],"c":"如果长期干旱后开始下雨，道路上会形成一层危险的润滑膜，只有在长时间下雨后才会被冲走。这层膜比单纯的雨水更危险。请非常谨慎地制动。这种润滑膜也会沉积在挡风玻璃上。打开雨刮器后，它首先会极大地恶化视线。由于抓地力变差，制动距离延长了。"},"2.1.03-104":{"q":"开始下雨了。为什么您必须立即增大安全距离？","o":["因为可能形成油膜从而增大制动距离","因为能见度可能变差，且雨刮器不会立即提供清晰的视野","因为制动器反应更快"],"c":"开始下雨时，您必须立即加大安全距离，原因如下：在湿气的影响下，道路上的污物、灰尘以及轮胎磨损或花粉的细微沉积物会变成一层危险的油膜。这会降低附着力，从而延长制动距离。这种润滑膜也会在挡风玻璃和制动鼓上形成。如果您使用雨刮器，它首先会恶化您的视线并使玻璃变模糊。在制动鼓上，这种润滑膜会导致制动器在潮湿条件下响应更慢。"},"2.1.03-105":{"q":"您在城镇外的一条联邦公路上行驶，正遇到浓雾。您是否允许持续骑压在白色虚线中间行驶于道路中央？","o":["不可以，因为这可能对迎面来车构成危险","可以，如果开启雾灯和后雾灯","可以，因为这能降低驶离道路的风险"],"c":"即使在大雾中也不允许沿中线行驶，尤其是因为由于能见度降低，驾驶员随时可能撞上对向来车。如果有雾，请减速并沿道路右侧行驶以获得安全的行驶。"},"2.1.03-106":{"q":"白天行驶时突然遇到浓雾，您必须怎么做？","o":["立即根据能见度调整车速","开启近光灯","只开启示宽灯"],"c":"作为汽车驾驶员，在有雾、降雪及其他能见度差的情况下，白天您必须打开近光灯。由于亮度不足，不允许使用驻车灯行驶。请根据能见度条件调整车速，并在能见度低于 50 米时使用后雾灯。"},"2.1.03-107":{"q":"如何获得透过前挡风玻璃的足够视野？","o":["有雾时不时开启雨刮器","有雪泥时，在其他车辆把雪泥溅到您前挡风玻璃上之前就开启雨刮器","前挡风玻璃起雾时，关闭通风器并保持车窗关闭"],"c":"在有雾时，将您的雨刮器调到间歇挡，以清除雾气中的细小水滴。在超车或被超车前打开雨刮器，以便立即清除雪泥或溅水造成的妨碍。通过正确的通风设置避免玻璃起雾：将通风设置为外部进风，而非循环空气。把车窗打开一条缝以让湿气逸出。短暂打开空调可以非常迅速地给空气除湿。"},"2.1.03-109":{"q":"您想在城镇外的狭窄林荫道上超车。您尤其必须注意什么？","o":["由于车道狭窄，有迎面来车时往往连骑自行车者都无法超越","对距离和迎面来车的误判往往导致严重事故","车身较高的车辆常为避开树枝而移动"],"c":"由于车道狭窄，即使骑行者在对向来车时也无法被超越。通常道路为排出雨水而弯曲严重，这意味着当越过中线时，车辆会向另一侧倾斜。这种载荷变化会降低行驶稳定性。由于树木，弯道可能不易看清。车身高的车辆常常需要行驶在中央以避免碰到树枝，可能伸入您的车道。"},"2.1.03-110":{"q":"在这种情况下您必须注意什么？","o":["应根据能见度调整车速","由于光影不断变化，判断距离变得更加困难","光影不断变化使及时察觉其他道路使用者变得更加困难"],"c":"光照条件突然而强烈地变化时，您必须减速，因为人眼否则无法对光线的变化做出足够快的反应。在黑暗区域很难察觉其他道路使用者或障碍物。"},"2.1.03-111":{"q":"在超越多辆卡车时，您面临这种情况。现在您应该怎么做？","o":["我中止超车操作","并入车道后，我再次建立足够的安全距离","我继续快速超车并并入红色卡车前方的车道"],"c":"由于天气能见度非常差，道路不能被充分看清。为了不危及任何人，您应尽快中止超车过程，并在回到车道时确保与前车保持安全距离。"},"2.1.03-112":{"q":"您作为多辆摩托车组成的车队的一员行驶。什么能降低事故风险？","o":["- 保持其位置","- 保持较小的安全距离","- 在同一车道内并排行驶"],"c":"与一群摩托车一起行驶时，所有人都应彼此保持距离前后排列，并留有足够距离以便制动和停车。"},"2.1.03-113":{"q":"在转向和制动操作时何时摔倒风险增加？","o":["潮湿的鹅卵石路面","潮湿的沥青路面","有松散碎石的车道"],"c":"在弯道转弯或制动时，湿滑的表面如车道标线、道路上的油、污物、井盖、沙、灰尘、碎石、潮湿表面、鹅卵石或树叶都会增加摔倒的风险。"},"2.1.03-114":{"q":"潮湿的路面标线会增加摔倒风险。如何降低这一摔倒危险？","o":["在标线的间隙处横穿","不在标线上加速或制动","以较大的角度横穿较长的标线"],"c":"潮湿的标线类似有轨电车轨道，是湿滑的。您应尽可能垂直地越过它们，并尽量不要在它们上面加速或制动。"},"2.1.03-115":{"q":"正确的做法是什么？","o":["我继续减速","我在障碍物前等待","我现在切换到左侧车道"],"c":"您行驶方向有两条车道。您行驶在两条车道的右侧。对向驶来一辆扫雪车。您从后视镜看到您左侧车道的一辆车想要超车。雪堆妨碍您在车道上行驶。在超车完成之前您不能向左转。因此，您必须进一步等待，在障碍物前等候，直到您可以向左避让。"},"2.1.03-116-M":{"q":"在此您应该怎么做？","o":["- 大幅减速","- 在我的车道内继续行驶","- 从左侧驶过损坏的路面"],"c":"如果在转弯前有车道损坏，您应大幅减速以避免损坏车辆。由于弯道不易看清，您不应从左侧驶过车道损坏处，而应继续在右侧您自己的车道上行驶。"},"2.1.03-117":{"q":"您在高速公路上行驶。在这种情况下正确的做法是什么？","o":["- 打开后雾灯","- 最高以50 km/h行驶","- 最高以80 km/h行驶"],"c":"由于高速公路上能见度严重受限，您可以打开后雾灯并以最高 50 km/h 行驶。"},"2.1.03-118":{"q":"电子稳定程序（ESP）显示灯已闪烁多次。在这种情况下正确的做法是什么？","o":["我减速，因为车速过高","我保持车速，因为ESP确保我能继续安全行驶","我去修理厂，因为ESP显示灯提示故障"],"c":"电子稳定程序（ESP）始终处于激活状态。如果 ESP 指示灯闪烁，它向您表示它正在主动干预车辆的行驶行为并使其稳定。因此应降低速度。\n如果 ESP 符号持续亮起，则它未激活或有故障，需要检查。"},"2.1.03-119":{"q":"行驶中您使用车辆的自动跟车巡航系统（ACC）。在这种天气条件下您必须预料到什么？","o":["ACC的功能可能受到不利影响","我必须亲自控制车速和车距","ACC会使车辆停止"],"c":"自适应巡航控制系统（ASC）会自行估测与前车的距离和车速。在恶劣天气下，例如因积雪和污物，这一功能可能受到限制。因此，您必须自行控制距离和车速。"},"2.1.03-120":{"q":"您沿一条狭窄的林荫道行驶。您必须注意什么？","o":["- 必须能在我可见距离的一半内停车","- 必要时为迎面来车停车","- 预料到树根造成的路缘不平"],"c":"道路狭窄，且因树根影响常常弯弯曲曲，这迫使您在转弯和会车时格外小心。请这样选择车速：使车辆能在可见距离的一半之内停住。示例：当能见度约为40米时，您应选择能在大约20米内停住的车速。从纯数学角度计算，车速30 km/h时的制动距离为18米。"},"2.1.03-121":{"q":"电子稳定性控制（ESC）显示灯已闪烁多次。在这种情况下正确的做法是什么？","o":["我减速，因为车速过高","我保持车速，因为ESC系统确保我能继续安全行驶","我去修理厂，因为ESC显示灯提示故障"],"c":"您必须降低车速。由于路面湿滑，且弯道中的车速对于道路状况而言明显过快，车轮会失去抓地力，车辆可能发生侧滑。"},"2.1.03-122":{"q":"在此您必须预料到什么？","o":["车道上的行人","与迎面来车的侧向间距减小","您可能被低垂的太阳炫目"],"c":"道路右侧和左侧的积雪可能使车道变窄。因此，您必须预料到与对向来车的间距会减小。\n此外，从交通标志可以看出，右侧有一个供散步者使用的停车区域。因此，您必须预料到行车道上会有行人。"},"2.1.03-123":{"q":"直线行驶时，您因水滑而失去对车辆的控制。现在正确的应对是什么？","o":["我轻轻松开加速踏板","我尽可能保持转向盘正直","我用力刹车"],"c":"发生水滑（打滑）时，您无法转向或改变车辆方向。也不应加速或制动。因此只需小心地松开油门踏板，并尽量保持车轮正直，直到车轮重新接触路面。"},"2.1.03-124":{"q":"为什么在这条积雪覆盖的车道上超车很危险？","o":["因为我的车辆可能侧滑","因为车道部分路段可能结冰","因为我的视线可能受到更不利的影响"],"c":"在隐蔽的结冰路面上，轮胎的附着力降低，可能发生打滑。您应通过缓慢、有预见性的驾驶避免急刹车，以免侧滑。\n此外，前方车辆也可能因清障/抛撒作业而被甩到左侧车道，您的视线也会变差。"},"2.1.04-001":{"q":"夜间在乡村公路上行驶时，您看到您这一侧有行人。如果您被迎面来车炫目，您会怎么做？","o":["减速，必要时停车","切换到远光灯并不减速继续行驶","加速以尽快驶出炫目区域"],"c":"如果对向来车使您目眩，务必降低车速，以便在可能出现的危险情况下随时停车。如果行车道上或附近有行人，在这种情况下您甚至可能需要停车。不允许加速。"},"2.1.04-002":{"q":"如果野生动物突然出现在您远光灯的照射范围内，您必须怎么做？","o":["立即改用近光灯","鸣喇叭并刹车","继续使用远光灯行驶"],"c":"握紧方向盘并制动。切换为近光灯，因为远光灯会使野生动物目眩，从而使其停留在路上。鸣喇叭将其吓走。避免在高速下试图闪避。这类操作往往以撞上路边的树或冲入对向车流告终。因此，当路上出现野生动物时，适用以下规则：减速、切换为近光灯并鸣喇叭把野生动物吓走。"},"2.1.04-005":{"q":"在这种情况下您必须注意什么？","o":["- 我必须特别谨慎地驾驶","- 我可能不易被其他道路使用者看到","- 我更容易判断距离"],"c":"由于树木众多，且光线明暗不断交替，您必须特别专注地驾驶，因为识别其他交通参与者会困难得多。"},"2.1.04-101":{"q":"黑暗中，一辆迎面来车没有改用近光灯。您怎么做才能仍在一定程度上看清路面？","o":["避免注视驶来车辆的车灯，将视线移向车道右缘","也开启远光灯","放下遮阳板"],"c":"如果对向来车的灯光使您目眩，尽量把目光投向道路右侧。这样可以减轻眩目效应，您仍能保持在车道内行驶。禁止通过开启远光灯的方式反向眩目对方。放下遮阳板不是合适的做法，因为这会严重影响您的视线。"},"2.1.04-102":{"q":"您在黑暗和雨中行驶于乡村公路，遇到开启近光灯的迎面来车。您必须记住什么？","o":["您可能被湿路面上的反射光炫目","您湿漉漉的前挡风玻璃可能导致您被炫目","您可以通过开启远光灯来避免可能的炫目"],"c":"在这种情况下您不得开启远光灯，因为这会强烈眩目对向交通。尤其在潮湿路面上，光线的反射会大大增强。其他干扰因素还包括挡风玻璃上的水滴和条纹，它们会使光线散射并使视线模糊。"},"2.1.04-103":{"q":"如果您开启远光灯行驶，可能出现哪些风险？","o":["迎面来车的道路使用者会被炫目","车道上的野生动物会被炫目并停留在光束中不动","我这一侧停放的车辆要到太晚才会被发现"],"c":"开启远光灯时，您可能眩目前方车辆和对向来车的驾驶员，这可能导致他们完全无法或过晚识别行人和骑车人。横穿道路的野生动物也可能被眩目，从而导致动物停留在光锥中。借助远光灯，您可以更好地识别抛锚的车辆。"},"2.1.04-104":{"q":"夜间在乡村公路上行驶，您看到您这一侧有行人。如果您被迎面来车炫目，您会怎么做？","o":["- 视线移向道路右侧","- 必要时停车","- 打开我的远光灯"],"c":"如果您作为汽车驾驶员在夜间发现路边有人，应当减速。与路边保持经常的目光接触最有利于避免事故。如果您同时被眩目，可以向右行驶并停车。"},"2.1.04-105":{"q":"您在一条车道狭窄的林荫道上行驶。您必须注意什么？","o":["我只能以能在我视野范围一半内停车的车速行驶","可能与迎面来车发生冲突","我必须预料到树根造成的车道边缘不平"],"c":"在狭窄的林荫道上，只有当有对向来车时您能在可见距离的一半之内停住，才允许以相应车速行驶。可能会与对向交通发生冲突。您可能必须减速、制动并向右行驶，或者倒车，直到道路变宽，足以让对向来车通过。林荫道的路边可能特别不平整，因为树根会把路面顶起。"},"2.1.04-106":{"q":"什么会增加事故风险？","o":["- 前方太阳低垂时","- 前挡风玻璃起雾时","- 侧窗结冰时"],"c":"如果挡风玻璃和侧窗起雾或结冰，事故风险会显著增加，因为您只能有限地看到交通状况。出发前请把所有车窗清理清楚。\n当您迎着低垂的太阳行驶时，也可能被眩目。这可能会使您更晚注意到其他交通参与者，从而增加事故风险。请格外专注、佩戴太阳镜或放下遮阳板。"},"2.1.05-001":{"q":"您已高速行驶了一段时间。这可能产生什么影响？","o":["您失去对速度的感觉","您的注意力下降","对弯道合适速度的感觉增强"],"c":"您会很快习惯高速行驶，并仿佛进入一种亢奋状态。尤其在高速公路出口处，这可能造成致命后果，因为您的注意力和反应速度会迅速下降。因此，请反复查看车速表！"},"2.1.05-002":{"q":"长时间高速行驶会导致什么？","o":["您失去对速度的感觉","您与前车距离过近","您的反应能力提高"],"c":"感官已经习惯了快速节奏，您开始低估某些情况。因此，驾驶员常常高速冲入高速公路出口匝道的急转弯。高速而单调的行驶会降低注意力，从而降低反应意愿。安全距离也常被忽视，驾驶员跟车过近。"},"2.1.05-004":{"q":"何时会有低估自身车速的危险？","o":["当道路宽阔且路缘没有树木、建筑物、栅栏等参照物时","当您已高速行驶了一段时间时","当路边景物（树木、房屋、栅栏）不断变化时"],"c":"当您长时间高速行驶（例如在高速公路上）之后，就会出现低估自身车速的危险。即使宽阔、通畅的道路，也会很快诱使您高速行驶。相反，不断变化的路边环境则会产生相反的效果。"},"2.1.05-005":{"q":"什么会导致您危险地低估自身车速？","o":["长时间高速行驶","在良好、宽阔的道路上行驶","巨大的发动机和轮胎噪音"],"c":"宽阔、通畅且路边环境没有变化的道路，可能导致对自身车速的危险低估。但较长时间的高速行驶，例如在高速公路上，也可能产生这种效应。相反，强烈的发动机和轮胎噪声会让驾驶员更清楚地感知车速。"},"2.1.05-006":{"q":"您正高速接近一个狭窄的左弯。为什么您必须在进入弯道之前就减速？","o":["- 否则您会被甩出弯道至右侧","- 如果您到弯道上才刹车，就会发生侧滑","- 否则您会被甩出弯道至左侧"],"c":"对您作为汽车驾驶员而言，车速提高时存在侧滑的危险。最坏的情况下，您可能被甩出弯道并失去对车辆的控制。车速提高时离心力过大。轮胎随后无法再传递制动力。因此您应当及早制动。"},"2.1.05-007-B":{"q":"您必须怎么做？","o":["缓慢行驶，因为儿童随时可能从停放的车辆之间跑出","缓慢行驶，因为其中一辆车的车门可能朝车道一侧打开","以允许的最高车速行驶，因为实际上没有明显的危险"],"c":"在这种情况下，您应当保持在限速之下。儿童或其他行人可能从停放的车辆之间跑上行车道。此外，您还应预料到停放车辆的车门可能突然向行车道一侧打开。"},"2.1.05-008":{"q":"您正高速接近一个急左弯。为什么有必要在真正到达弯道之前就减速？","o":["- 可能沿弯道向右侧滑出","- 可能开始侧滑","- 可能沿弯道向左侧滑出"],"c":"由于车速过高，离心力可能使您的车辆向右侧滑出弯道。因此，您应当在弯道之前降低车速。"},"2.1.05-009":{"q":"驾驶员在什么情况下会经常低估自身车速？","o":["在宽阔、铺装良好的道路上","长时间高速行驶之后","在路面不平的狭窄道路上"],"c":"持续高速行驶时，注意力会下降。您会习惯这种速度。此外，宽阔且周边环境变化少的道路会使您更不清楚自己实际开得多快。反应时间会变长。"},"2.1.05-010":{"q":"在高速公路上高速行驶时，您应预料到什么？","o":["其他道路使用者低估我的车速","侧风可能对我在路上的稳定性产生不利影响","我可能无法足够及时地对危险作出反应"],"c":"其他交通参与者可能低估您的车速，例如突然超车并入。如果出现危险情况，您在高速下可能无法及时制动。如果您看到危险迫近，请提前相应降低车速。\n此外，在高速下，即使轻微的侧风也可能使您的车辆向右或向左偏摆。"},"2.1.05-101":{"q":"在为沿车道狭窄的林荫道行驶选择车速时，什么尤为重要？","o":["同时估算与树木及迎面来车的侧向距离","当对向驶来宽大车辆时，可能有必要在可见距离的一半内停车","迅速变化的光线条件使估算侧向距离更容易"],"c":"在车道狭窄的林荫道上行驶时，选择车速必须考虑以下因素：由于路旁的成排树木，光照条件可能迅速变化。这使您难以估计与两侧和对向交通的距离。您必须选择能在可看清的路段一半之内停住的车速。这一点尤其重要，因为宽大或高大的车辆常常因空间需要而行驶在林荫道的中间。"},"2.1.05-102":{"q":"为什么您现在必须减速？","o":["因为动物","因为拖拉机","因为道路走向"],"c":"一只动物从右侧跑上道路。由于您后方没有车辆，您应当减速、制动并向右行驶。这是应对各种可能情形最安全的做法：拖拉机可能撞上动物并开始侧滑，拖拉机可能在闪避时驶入您的车道，您可能撞上动物并失去对车辆的控制。"},"2.1.05-103":{"q":"在哪里您必须预料到突然出现的危险情况？","o":["在森林地区","在山顶之后","在学校前方"],"c":"在以下情况下您必须警觉突然出现的危险情形：1. 能见度受到严重限制；2. 人员或动物可能意外出现在道路上。在能见度受限的情况下，您可能过晚发现行车道上的障碍物，例如抛锚的车辆。您相应作出反应的时间更少。在林区，黄昏时分您必须预料到野生动物突然横穿；在居民区，您必须预料到儿童在街上玩耍。在学校门前和校车停靠站处也需要谨慎。"},"2.1.05-104-M":{"q":"为什么您在此必须降低车速？","o":["因为正在超车的车辆","因为限速","因为车流量低"],"c":"在您前方超车的车辆存在危险的事故风险，因为可能发生碰撞。为防止卷入事故，同时也为给其他车辆留出闪避空间，您必须降低自身车速。"},"2.1.05-105-M":{"q":"在这种情况下您应预料到什么？","o":["我这一侧有缓慢行驶的车辆","快速行驶的迎面来车切弯","野生动物横穿道路"],"c":"在视线不清的右转弯处，您必须预料到各种情况。尤其在黄昏时分，野生动物可能在刚过弯道后横穿到另一侧。但也可能发生对向来车切弯而很晚才被发现，或者刚过弯道后就有一辆车以极低车速行驶。"},"2.1.05-106-M":{"q":"为什么您在此必须减速并尽可能靠右行驶？","o":["因为[红色汽车]","因为限速","因为[蓝色卡车]"],"c":"在这种情况下，由于对向来车是那辆黄色汽车，您必须降低车速并尽量靠右行驶。"},"2.1.06-002":{"q":"如果您作为车队最后一辆车，在迎面来车一过去就立即超车，为什么会危险？","o":["因为您必须预料到车队中的其他人会驶出车道超车","因为所需的超车距离可能不够","因为如果您可能需要挤回车队，可能导致事故"],"c":"如果形成了车队长龙，驾驶员原则上应当一辆接一辆地超车。车队中的最后一辆车超车路程最长，并且必须预料到会有其他车辆在它前方开始超车。"},"2.1.06-003-B":{"q":"如果您想超车，必须记住什么？","o":["厢式货车可能开始超越其前方的车辆","可能出现迎面来车","由于看不到迎面来车，您可以毫不犹豫地超车"],"c":"在超车操作中，您应当确保对向车道是空的。还要确保前方没有弯道或路口，并且您只超越一辆汽车。注意更多的交通参与者，尤其是卡车。"},"2.1.06-004-B":{"q":"在这条高速公路上，您是否允许从右侧超越黑色汽车？","o":["不可以，因为左侧车道没有排队的车辆","可以，如果您的车速不超过80 km/h","可以，因为有足够的空间超车"],"c":"在此示例中，黑色汽车不得从右侧被超越。在高速公路和快速路上，只有在例外情况下才允许从右侧超车。例如，当左侧已经形成车流排队时，就属于这种情况。"},"2.1.06-005-B":{"q":"两辆汽车都以约30 km/h行驶。您是否允许在弯道前超越这两辆车？","o":["- 您所需的超车距离会过大","- 浅色汽车可能驶出车道超车","- 您不允许跨越虚线"],"c":"您可以越过虚线行驶。但此处超车仍然过于危险，因为在转弯前可供超车的可掌控距离太短。此外，您还必须预料到那辆浅色汽车的驾驶员也会开始超车。"},"2.1.06-006-B":{"q":"超车车辆的驾驶员显然判断失误。您必须怎么做？","o":["立即刹车并向右避让","像之前一样继续行驶"],"c":"汽车驾驶员应当降低车速。否则可能发生事故。如果这还不够，您还可以退到右侧的草地上行驶。"},"2.1.06-007-M":{"q":"您想超车。现在正确的做法是什么？","o":["我放弃超车","我加速","我保持车速"],"c":"由于您后方的车辆已经开始了超车过程，您应当放弃超车。"},"2.1.06-008-M":{"q":"您想超车。您应该怎么做？","o":["- 只有在我对所需路段有清晰视野时","- 只有在没有迎面来车时","- 与[蓝色汽车]同时"],"c":"如果能在所需距离内看清前方，且没有对向来车（能见度受限），您可以在此处超车。"},"2.1.06-009":{"q":"为什么您在此不允许超车？","o":["因为可见路段不够","因为若有迎面来车，我将无法保持足够的侧向间距","因为我不允许跨越中心线"],"c":"一般而言，如果整个超车距离无法看清，或者无法满足与其他交通参与者的侧向间距，就不得超车。在本情况中这两个不利条件同时存在：可供判断的路段对于安全超车而言太短。在与对向交通会车时，无法满足与骑车人1.5米的最小间距。"},"2.1.06-010":{"q":"您正在被超越，迎面来车正危险地逼近。尽管如此，对方车辆仍继续超车。您应该怎么做？","o":["- 减速","- 保持车速","- 加速"],"c":"您必须减速并向右行驶，以便超车的驾驶员能及时回到车道内。在被超车时，任何情况下都不得加速。"},"2.1.06-011":{"q":"为什么您现在应该急刹车？","o":["因为汽车","因为卡车","因为拖拉机"],"c":"由于那辆蓝色轿车很可能会驶入您的车道，您必须立即减速并靠右行驶。"},"2.1.06-012-M":{"q":"正确的做法是什么？","o":["我超越[蓝色汽车]，然后驶入中间车道","我超越[红色厢式货车]，然后驶入中间车道","我轻踩刹车，促使后方车辆保持距离"],"c":"当后方有车逼迫您或使用闪烁远光灯时，您作为汽车驾驶员不必闪避到中间车道。您应当照常超越蓝色汽车和红色厢式货车。要安全地变入中间车道，必须先完成超车过程。只有这样才能变道。"},"2.1.06-013":{"q":"您想超车。现在正确的做法是什么？","o":["我中止超车并保持在卡车后方","我加速并迅速继续超车","我保持车速并继续超车"],"c":"您已经打转向灯并想超越卡车。您在后视镜中看到一辆红色汽车正以高速从左侧车道驶近。您必须立即中止超车过程，并留在卡车后方。如果您继续超车，就会迫使红色汽车紧急制动。它可能撞上您的车。"},"2.1.06-014":{"q":"正确的做法是什么？","o":["我迅速继续超车","我中止超车并并入右侧车道","我刹车，但继续超车"],"c":"在超越卡车时，您在后视镜中观察到一辆快速驶近的汽车。此时再完成超车过程已为时过晚。请加速并迅速但安全地完成超车过程。原则上，后方车辆没有优先权；即使在高速公路上也是如此。"},"2.1.06-015":{"q":"正确的做法是什么？","o":["我超越厢式货车，然后驶入中间车道","我立即驶入右侧的车道","我轻踩刹车，促使后方车辆保持距离"],"c":"一位驾驶员在左侧车道上危险地紧跟在您后面，并用闪烁远光灯示意超车意图。您仍应当超中间车道上的那辆运输车，然后回到它前方的车道内，以化解局势。"},"2.1.06-016-M":{"q":"您现在应该怎么做？","o":["我减速","我尽可能靠右侧行驶","我加速"],"c":"由于有一辆车从前方驶来，并且想超越您后方的一辆汽车（红色），您应当减速并尽量靠右行驶。"},"2.1.06-017-M":{"q":"为什么您在此必须减速？","o":["因为正在超车的汽车","因为最高允许车速为80 km/h","因为拖拉机"],"c":"那辆对向汽车不顾对向交通，在您前方约250米处超车。您必须降低车速并尽量靠右行驶。这样您就化解了局势，并给超车的汽车更多时间和空间来完成超车过程。那辆拖拉机正在驶离路口，不构成危险。"},"2.1.06-018-M":{"q":"您现在应该怎么做？","o":["我减速","我尽可能靠右侧行驶","我加速"],"c":"如果一辆汽车不顾对向交通地超越您，您应当减速并尽量向右行驶。这样就能给该车足够的空间，安全地完成超车过程。"},"2.1.06-019-M":{"q":"为什么您在这种情况下不允许超车？","o":["因为摩托车想超越我","因为我的超车距离过长","因为这里是禁止超车区"],"c":"您不得超车，因为您后方有一辆摩托车正高速驶近并要超越您。此外，在这种情况下超车所需的距离也太长。"},"2.1.06-020-M":{"q":"您现在应该怎么做？","o":["我减速","我尽可能靠右侧行驶","我停车"],"c":"考虑到正在超越您的那辆卡车有对向来车，您应当减速并尽量靠右行驶，以便让它完成对您的超越。"},"2.1.06-021-M":{"q":"您想超车。现在正确的做法是什么？","o":["我放弃超越卡车，因为我对所需路段没有清晰视野","我跟在摩托车后面，因为卡车用转向灯示意可以超车","我缩短与卡车的距离，以便更快超车"],"c":"您不应当超越卡车，因为您无法看清为此所需的距离。"},"2.1.06-022-M":{"q":"为什么您必须中止超车？","o":["因为拖拉机想左转","因为可能妨碍迎面来车","因为前方可见禁止超车区"],"c":"您应当放弃超车操作，因为那辆拖拉机想向左转弯，并且可能妨碍对向交通。"},"2.1.06-023-M":{"q":"现在正确的做法是什么？","o":["- 不要超车，因为拖拉机想向左驶出","- 谨慎超车，因为拖拉机要求我这么做","- 立即超车，因为超车距离足够大"],"c":"您不应当超车，因为那辆拖拉机将向左偏转（见转向指示灯）。"},"2.1.06-024-M":{"q":"您想超车。在此正确的做法是什么？","o":["我不超车，因为[黄色]车辆可能想超车","我不超车，因为可能出现迎面来车","我超车，因为看不到迎面来车"],"c":"此处正确的（有预见性的）行为是不超车，因为那辆黄色车辆可能超车，且可能出现对向来车（视线受限）。"},"2.1.06-025-M":{"q":"现在正确的做法是什么？","o":["我立即刹车","我尽可能靠右行驶","我像之前一样继续行驶"],"c":"由于有一辆车在您的车道内，您应当立即减速并尽量向右偏转，以避免碰撞。"},"2.1.06-026-M":{"q":"为什么您现在不允许超车？","o":["- 摩托车","- 道路布局","- [红色]汽车"],"c":"由于那辆摩托车（对向交通）、道路走向以及由此造成的能见度不良，您不得超越骑车人。"},"2.1.06-027-M":{"q":"为什么您现在在此不允许超车？","o":["- 摩托车","- [红色汽车]","- 有标志的禁止超车"],"c":"此时一名摩托车手正在超越拖拉机。请等到您能安全开始超车操作时再行动。"},"2.1.06-028-M":{"q":"为什么您在此不允许超车？","o":["- 对前方道路没有足够视野","- 若有迎面来车，无法与骑行者保持足够的超车间距","- 不允许跨越中心车道标线"],"c":"由于弯道和树木，您无法充分看清余下的道路。在城镇外，您必须与骑车人保持2米的最小侧向间距。如果突然出现对向来车，您在超车时无法保持这一间距。因此，您在此处不得超车。"},"2.1.06-029-M":{"q":"为什么您在此不允许超车？","o":["因为与骑行者的侧向间距过小","因为我可能危及迎面来车","因为我不允许跨越中心线"],"c":"道路太窄，无法同时满足与骑车人和对向交通的足够侧向间距。"},"2.1.06-030":{"q":"您想在一条林荫道上超车。您应特别注意什么？","o":["在这种情况下侧向间距常被误判","车身较高的车辆常为避开树枝而进行避让操作","此处涉及树木的事故特别频繁"],"c":"这条林荫道被树木环绕。因此，光线与阴影的交替常常导致对距离的错误估计。同样，也常常会出现树木倒伏，以及车身较高的车辆试图避开树枝的情况。"},"2.1.06-031-M":{"q":"为什么您在此必须中止超车？","o":["因为拖拉机将向左转弯","因为摩托车将超越我","因为我能看到禁止超车标志"],"c":"那辆拖拉机开始向左转弯。拖拉机横穿道路的左侧车道。如果您现在超车，就会与拖拉机相撞。"},"2.1.06-032":{"q":"您在一条每个方向各一条车道的道路上行驶。前方有一列车队正在行驶。为防止出现危险情况，为什么您应放弃超车？","o":["因为超车距离比超越单辆车时要大得多","因为我不应过早并入我的车道而拆散车队","因为我无法判断车队前方的道路交通状况"],"c":"在道路交通中结队前行的行人、骑车人或机动车群体，称为封闭车队（不可分割的整体队伍）。封闭车队必须有明确的标识，且不得被打断。\n由于封闭车队由多辆车组成，您实际上无法真正了解交通状况。超越封闭车队时，您应当避免过早地并回队列，否则超车路程会明显延长。"},"2.1.06-033-M":{"q":"为什么在这种情况下超车很危险？","o":["因为前方车辆可能驶出","因为我看不到超车所需路段的足够远处","因为没有足够的空间并入前方车辆之间"],"c":"您在一条有对向交通的蜿蜒道路上，跟在卡车后面，处于由多辆汽车组成的车队中。理想情况下，卡车后面的那辆车先超车，然后后面的车辆再跟上并开始超车。\n在左转弯处，您无法充分看清超车车道。您很可能不得不取消超车操作并插入两车之间。有可能前方车辆之间的距离太小，您插入时会危及自己和他人。"},"2.1.06-034-M":{"q":"为什么您在这种情况下不允许超车？","o":["因为摩托车可能超越我","因为我的车速不够","因为此处禁止超车"],"c":"在这种情况下您不得超车，因为那辆拖拉机行驶得太快，您以最高50 km/h的车速无法超越它。\n那辆摩托车也在高速驶近。由于前方是长直道且看不到对向来车，它很可能超越您。"},"2.1.06-035-M":{"q":"您前方的车辆以约30 km/h行驶。为什么您不允许在道路弯道前超车？","o":["因为我的超车距离过长","因为[红色]汽车可能驶出车道超车","因为我不允许跨越车道标线"],"c":"在弯道之前您不得超车，因为您的超车距离太长，无法在弯道前超越这两辆车。而且两辆车之间的距离不足以让您插入。此外，红色汽车拥有在您前方超车的权利；如果你们俩都开始超车操作，您和对向交通都会面临危险。由于弯道处看不清，您无法知道是否有对向来车。"},"2.1.06-103-M":{"q":"为什么您必须切换到右侧车道？","o":["- [红色]汽车","- [蓝色]汽车","- [黄色拖拉机]"],"c":"交通标志提示前方200米处道路变窄（一条车道结束）。\n通过这一变窄处，车道被引入对向车流，因此您必须格外警觉，切勿驶入对向车流。"},"2.1.06-104-M":{"q":"在此正确的做法是什么？","o":["我暂时不超越[骑行者]","我超越[骑行者]","我鸣喇叭促使[骑行者]前后单列骑行"],"c":"您暂时不应当超车，因为您与对方并排行驶，无法保持足够的侧向间距。"},"2.1.06-105":{"q":"现在正确的做法是什么？","o":["我减速到步行速度","我尽可能靠右侧行驶","我驶过行人"],"c":"在这种情况下，您必须减速到步行速度并尽量靠右行驶。您不应当从行人旁边驶过，因为危险太高。"},"2.1.06-106-M":{"q":"现在正确的做法是什么？","o":["我减速","我保持车速","我超越[骑行者]"],"c":"您必须降低车速，因为无法保持与骑车人的侧向间距。"},"2.1.06-107-M":{"q":"为什么您在这种情况下不应超越轻便摩托车骑行者？","o":["因为这可能导致轻便摩托车骑行者摔倒","因为我不允许比轻便摩托车骑行者快得多","因为我无法保持所需的侧向间距"],"c":"在施工路段，限速为30 km/h，且道路变窄。\n因此，您不得以安全超越轻便摩托车骑手所需的那种车速行驶。\n由于道路狭窄，您无法保持所需的侧向间距，而且路况不佳，如果您超车，可能导致轻便摩托车骑手摔倒。"},"2.1.06-201-M":{"q":"在此正确的做法是什么？","o":["我暂时不超越[骑行者]","我超越[骑行者]","我鸣喇叭催促[骑行者]靠右"],"c":"您在此处无法超越骑车人，因为您无法保持足够的侧向间距。"},"2.1.07-002-B":{"q":"在这个高速公路停车区您必须预料到什么？","o":["人们突然走上车道","刹车时打滑的危险","迎面来车"],"c":"该高速公路停车场的路面由鹅卵石铺成，不仅不平整，而且潮湿。请做好心理准备：由于附着力降低，您车辆的制动距离会延长。您不必预料会有对向来车。但粗心的行人随时可能意外踏上道路。"},"2.1.07-004-B":{"q":"如果您想直行，您会怎么做？","o":["刹车，以便前方驾驶员能变更车道","“由于交通信号灯为‘绿色’，从左侧车道超越另一辆车”","鸣喇叭提示前方驾驶员不得在如此靠近交叉路口处变更车道"],"c":"如果您降低车速并让前方车辆变道，您的行为就是正确的。左侧车道只能用于左转目的。由于在示例中您想直行，因此不得使用左侧车道。"},"2.1.07-006-B":{"q":"您正接近图中的这些车辆。您会怎么做？","o":["观察卡车和拖车是否停留在应急车道上","当卡车和拖车打左转向灯时，让其驶入车道","当卡车和拖车打左转向灯时，闪大灯并快步通过"],"c":"在城镇外，拖拉机、卡车和轻便摩托车等慢速车辆常常行驶在应急车道上，因此可以更容易地被超越。如果这类车辆想向左转弯，或者因其他原因必须回到主路上，您必须让该驾驶员变道。"},"2.1.07-007-M":{"q":"在这种情况下您应预料到什么？","o":["[黄色汽车]的驾驶员没有看到我","车道上散落着碎石","前方车辆将右转"],"c":"视频开头处的标志提示“注意滚动的碎石”，因此您必须意识到路上有滚动的碎石，而且黄色车辆可能没有注意到您，因为您前方的拖拉机挡住了黄色汽车的视线，也挡住了您的视线。"},"2.1.07-008-M":{"q":"[白色汽车]想左转。如果[该车]没有停车，正确的做法是什么？","o":["我减速","我放弃我的优先通行权","我鸣喇叭并像之前一样继续行驶"],"c":"白色汽车想向左转弯，由于您不知道它是否会停下（您拥有先行权），最好放弃您的先行权并降低车速。"},"2.1.07-009-M":{"q":"为什么您现在必须刹车？","o":["- [绿色车辆]","- 摩托车","- [黄色汽车]"],"c":"由于那辆绿色车辆，您应当制动，因为它看起来要驶上拖拉机后方的道路。"},"2.1.07-010-M":{"q":"在这个停车区您必须预料到什么？","o":["违章停放的卡车","从停车位驶出的车辆","车道上的人"],"c":"车辆可能驶出停车位，请留意驶出停车位的车辆。由于您在休息，行人可能在行车道上走动。卡车司机常常把车停在轿车停车位里。"},"2.1.07-011-M":{"q":"现在正确的做法是什么？","o":["我尽可能靠右行驶","我刹车","我向左改变方向"],"c":"那辆汽车很可能会超越骑车人。为了安全起见，请减速并尽量靠右行驶。"},"2.1.07-012-M":{"q":"为什么您在这种情况下应做好刹车准备？","o":["因为拖拉机","因为摩托车","因为限速"],"c":"拖拉机驾驶员随时可能驶入您的车道，因此请随时准备制动，及时化解局势。"},"2.1.07-013":{"q":"当多辆摩托车结队同行时必须注意什么？","o":["在直线路段行驶时应采用交错队形","车队的驾驶方式应以经验最少的骑行者为准","车队在每种交通情况下都必须保持在一起"],"c":"请交错行驶，以避免因突然制动而造成的追尾碰撞。结队骑行并不容易；如果一名驾驶员犯错，其他所有人都必须作出反应。"},"2.1.07-014-M":{"q":"在这种情况下您应预料到什么？","o":["[红色]车辆的驾驶员没有看到我","[绿色]卡车转弯","拖拉机驶上道路"],"c":"由于那辆正在转弯的卡车，厢式货车可能没有注意到您。请随时准备制动。"},"2.1.07-015-M":{"q":"为什么您在此应进一步减速？","o":["因为[红色]汽车可能驶入我的车道","因为其他人可能走上道路","因为[蓝色汽车]可能继续行驶"],"c":"左侧车道上的那辆汽车不太可能继续行驶，因为它似乎已经抛锚了。即使它继续行驶，也不会影响到您。不过，由于车道上有一名人员，此处需要格外谨慎。也可能有其他人从车里出来跑上道路。那辆停着的汽车可能被灌木丛遮挡，或者没有设置警告三角牌。因此，后方的那辆车可能过晚才认出前方车辆已经停下。所以您应当有预见性地驾驶，并预料到后方车辆会闪避到您的车道。"},"2.1.07-016-M":{"q":"现在正确的做法是什么？","o":["我减速","我在我的车道内尽可能靠右行驶","我在我的车道内尽可能靠左行驶"],"c":"那辆抛锚的车辆挡住了另一辆车的车道，并遮挡了您的视线。您应当降低车速，并在行驶中尽量靠右。"},"2.1.07-017":{"q":"为什么您在此应继续减速？","o":["因为红色车辆可能驶入我的车道","因为其他人可能走上道路","因为否则我的车辆可能驶离道路"],"c":"左侧车道上有一辆汽车抛锚了。车前站着一个人。其他乘客可能下车并进入车道。对向车道驶近的车辆可能闪避到您的车道，以超越那辆抛锚的车辆并绕过障碍物。如果您减速，局势的危险性就会降低。"},"2.1.07-018":{"q":"现在正确的做法是什么？","o":["我继续刹车","我驶入左侧车道","我像之前一样继续行驶"],"c":"由于自行车道上的那辆运输车，骑车人无法继续前行。他会闪避到道路上并进入您的车道。您无法切换到左侧车道，因为您左后方有一辆车。请减速以化解这一危险局势。"},"2.1.07-019-M":{"q":"现在正确的做法是什么？","o":["我减速","我尽可能靠右侧行驶","我打右转向灯"],"c":"那名摩托车手正高速向您驶来。尽管蓝色卡车已经很近，他仍可能超越您。请尽量靠右行驶，以增大与对向车道的距离，并降低车速，以便摩托车手能够安全且及时地完成超车操作。"},"2.1.07-020":{"q":"您现在应该怎么做？","o":["我继续尽可能靠右行驶","我刹车","我驶入左侧车道"],"c":"那辆黄色汽车作为逆行车辆在高速公路上朝您驶来。请尽量向右行驶并制动。为警告其他交通参与者，请开启危险警示灯。"},"2.1.07-021-M":{"q":"现在正确的做法是什么？","o":["我停在出租车后方","我驶入左侧车道","我反复鸣喇叭"],"c":"鉴于您左后方车道上有来车，您应当减速并停在出租车后方，等左侧车流通过后再超越出租车。"},"2.1.07-022-M":{"q":"在这种情况下正确的做法是什么？","o":["- 进一步减速","- 做好刹车准备","- 进行紧急制动"],"c":"路上的动物难以预料。您应当继续降低车速并仔细观察局势，随时准备在动物横穿道路时制动。\n如果后方车辆无法足够迅速地反应，紧急制动可能导致追尾碰撞。"},"2.1.07-023-M":{"q":"为什么您现在应该减速？","o":["因为动物","因为[红色汽车]","因为限速"],"c":"即使您遵守60 km/h的限速，也会有动物在您正前方跑上道路。为避免事故，您必须降低车速。对向来车不会影响您的驾驶方式。"},"2.1.07-024-M":{"q":"在这种情况下您必须注意什么？","o":["[黄色汽车]的驾驶员可能没有看到我","车道上的碎石意味着碰撞风险增加","我必须让[红色汽车]优先通行"],"c":"那辆黄色汽车的驾驶员想向左转弯。他可能会在拖拉机后面忽略您。请预料到这一点并随时准备制动。\n您还应注意不要行驶在碎石上，因为碎石会增加行车道上打滑的风险。"},"2.1.07-025-M":{"q":"现在正确的做法是什么？","o":["我急刹车","我让出我的优先通行权","我像之前一样继续行驶"],"c":"由于那辆蓝色汽车很可能在道路上行驶时不遵守先行权规则，您必须大幅减速并放弃您的先行权。"},"2.1.07-026-M":{"q":"现在正确的做法是什么？","o":["我进一步减速","我让拖拉机并入车道","我驶入左侧车道"],"c":"那辆拖拉机通过闪烁灯光示意想要回到车道内。因此您应当降低车速，让拖拉机并入车道。"},"2.1.07-027-M":{"q":"在这种情况下正确的做法是什么？","o":["必要时我必须停车","我须作为预防向右转向驶上田地","我比拖拉机有优先通行权"],"c":"在这条狭窄的乡村公路上，您和拖拉机可能难以顺利相互通过。请做好停车让拖拉机先过的准备。"},"2.1.07-028-M":{"q":"现在正确的做法是什么？","o":["我加大与前方[汽车]的距离","我更加谨慎地继续行驶","我以较大的侧向间距超越[前方汽车]"],"c":"那辆黄色汽车的驾驶方式不正常。它可能是分心驾驶或醉酒驾驶。\n前方汽车的突然制动和转向操作是危险的。请注意它接下来如何行驶，拉大距离并随时准备制动。"},"2.1.07-029":{"q":"沿狭窄的林荫道行驶时，您必须注意什么？","o":["- 我常常难以看清弯道内的路况","- 我必须特别防御性地驾驶","- 我能免受路面黑冰的影响"],"c":"林荫道上的能见度比开阔地更为受限，因此需要采取相应的驾驶方式。\n在弯道处，您对弯道后行车道的视线可能受到限制。因此，您可能很晚才能看到障碍物。"},"2.1.07-030-M":{"q":"现在正确的行为是什么？","o":["我停在出租车后方","我驶入左侧车道","我谨慎地从右侧驶过出租车"],"c":"在这种情况下，除了停在出租车后方，您别无选择。因为您不得从出租车右侧通过，那里是人行道。一般而言禁止在人行道上行驶。\n您也无法变入左侧车道，因为您旁边有一辆摩托车。如果您变道，就有碰撞风险。"},"2.1.07-031":{"q":"您参加有数辆摩托车的结队出游。正确的行为是什么？","o":["我在车队中保持自己的位置","我确保与前方的摩托车保持安全距离","我总是与前方的摩托车骑得一样快"],"c":"您在车队中的位置应在结队骑行前确定，且在骑行过程中不应改变，以避免不断变换位置。您应当始终注意与前一辆摩托车保持必要的安全距离。\n这样可以避免与其他摩托车或对向交通产生潜在的危险情况，并使您能够及时对危险或突然的车速变化作出反应。"},"2.1.07-101":{"q":"什么可能导致快速行驶的机动车在干燥的直路上突然横向偏摆？","o":["它突然受到一阵强侧风的吹袭","轮胎爆裂","突发的逆风"],"c":"在笔直、干燥的道路上，车辆在遇到强侧风或轮胎爆裂时可能向侧面摆动。在这种情况下，请立即松开油门踏板，反向修正方向并轻踩制动。"},"2.1.07-102":{"q":"什么使在车流中行驶更容易？","o":["透过前方行驶车辆的车窗观察车流","在自己的车道内以略微交错的位置行驶","行驶时保持危险警示灯开启"],"c":"略微错位行驶可以让您观察到前方的车辆。这样您就能看清前方或透过前车车窗看到前方的交通状况，从而更快地对突发事件作出反应。在车队中开启危险警示灯行驶一般是禁止的。"},"2.1.07-105":{"q":"与野生动物（例如鹿）发生事故后，您必须怎么做？","o":["停车，开启危险警示灯并保护事故现场","通知警察或最近的林业部门","不停车继续行驶"],"c":"发生野生动物事故后，您必须停车、开启危险警示灯并保护事故现场。您还必须将事故通知警方或最近的林业部门。由于存在狂犬病危险，任何情况下都不得用裸露的手触摸野生动物！"},"2.1.07-106":{"q":"您在高速公路上高速行驶时一个轮胎爆裂。您会怎么做？","o":["收油，必要时反向转向并谨慎刹车","如有可能停在应急车道上，开启危险警示灯并放置三角警示牌","立即全力刹车并移到应急车道上"],"c":"避免在高速公路上紧急制动，而应轻柔地转向和制动，以使车辆保持稳定。如果可能，请把车停在应急车道上。开启危险警示灯并设置警告三角牌，以警示后方车辆。"},"2.1.07-109":{"q":"您将车速从50 km/h提高到100 km/h。按照经验法则，制动距离如何变化？","o":["它从25米增至100米，是原来的四倍","它从15米增至30米，是原来的两倍","它从50米减至25米，是原来的一半"],"c":"根据经验法则，车速加倍时制动距离变为四倍。例如，车速40 km/h时为16米，80 km/h时为64米。"},"2.1.07-110":{"q":"驶出城镇内道路时，您和前方约15米处的车辆都将车速从50 km/h提高到100 km/h。您应该如何改变与前方车辆的安全距离？","o":["- 增至至少50米","- 保持不变","- 增至至少25米"],"c":"在城镇封闭区域外，与前车保持至少为其车速数值一半（以米计）的安全距离。例如车速100 km/h时，安全距离应至少为50米。"},"2.1.07-111":{"q":"为什么您在这种情况下必须做好刹车准备？","o":["因为另一辆车可能继续行驶","因为前方道路走向要求如此","因为可见限速标志"],"c":"您看到一辆车想从右侧驶上道路。由于它来自田野或林间小路，您拥有先行权。由于森林遮挡，该驾驶员的视线可能受限。他/她有可能在应当等待的情况下仍然继续驶出。因此，在您明确看出它停下之前，必须随时准备制动。"},"2.1.07-112":{"q":"为什么您现在应降低车速？","o":["因为我不易被其他道路使用者看到","因为前方道路走向要求如此","因为我必须让行"],"c":"原则上您拥有先行权，因为您在优先道路上。不过，为避免危险情况，您仍应当降低车速并随时准备制动，因为从右侧驶来的那辆汽车的驾驶员可能过晚认出您，或者完全没有注意到您。由于路旁的树木，他/她的视线明显受限。"},"2.1.07-113-M":{"q":"在这种情况下正确的做法是什么？","o":["我减速","我加速","我像之前一样继续行驶"],"c":"在这种情况下，您需要降低车速并让汽车驾驶员向左回到车道内。如果多车道道路上有一条车道结束，或者行驶在另一条车道上的驾驶员无法继续沿该车道通行，他们必须能够按照拉链式（交替并入）程序变道。"},"2.1.07-114-M":{"q":"在这种情况下您应预料到什么？","o":["- 摩托车骑行者将减速","- 拖拉机将驶上道路","- 拖拉机将等待"],"c":"尽管您在优先道路上，也必须始终预料到危险情况的发生。例如，在路口驶入您所在道路的那辆拖拉机驾驶员可能没有履行等待义务，迫使您前方的车辆制动。通过有预见性地驾驶，您可以帮助化解潜在的危险情况。"},"2.1.07-115":{"q":"在这种情况下正确的做法是什么？","o":["我保持车速并像之前一样继续行驶","我加速以创造足够大的安全距离","我短暂刹车，以便后方驾驶员降低车速"],"c":"这条道路的最高限速为80 km/h。您以80 km/h行驶。您后方的驾驶员逼迫您开得更快；他/她危险地靠近并低于规定的安全距离。请保持您的车速。如果您试图通过加速来增大安全余量，后方的驾驶员很可能也会加速。即使短暂制动，也会危及您和后方车辆。"},"2.1.07-116":{"q":"您应该怎么做？","o":["我立即急刹车","我不采取避让动作","我向左避让"],"c":"如果您突然必须尽可能立即制动，请留在您的车道内，必要时接受与障碍物相撞。不要向左转向，因为有对向交通。向右闪避同样不可行，因为您会偏离车道，可能撞上其中一棵树。"},"2.1.07-117-M":{"q":"右转时您必须注意什么？","o":["注意摩托车","注意从左侧驶来的车辆","注意[拖拉机]"],"c":"必须给予所有行驶在优先道路上的驾驶员优先权。那辆摩托车位于您想右转驶入的车道上。在您右转驶入优先道路之前，必须等待并让摩托车通过。"},"2.1.07-118-M":{"q":"您想保持在优先道路上。现在您必须预料到什么？","o":["[红色汽车]没有看到我","儿童将横穿道路","厢式货车继续在优先道路上行驶"],"c":"在这种情况下，那辆黑色汽车很可能没有看到骑着摩托车的您。道路前方更远处的孩子们很可能要横穿道路。那辆红色厢式货车不会继续行驶在优先道路上，而是如转向灯所示向右转弯。"},"2.1.07-119":{"q":"如果已无法避免与野生动物相撞，您应该怎么做？","o":["我尽可能用力刹车","我保持行驶方向","我总是采取避让动作"],"c":"如果与动物的碰撞已无法避免，就应保持行驶方向。然后用力制动并握紧方向盘。闪避操作可能伤及其他交通参与者，或使损害比有控制的碰撞更大。"},"2.1.07-120-M":{"q":"您机动车的定速巡航系统设定为130 km/h。现在正确的做法是什么？","o":["- 通过刹车恢复安全距离","- 超越摩托车","- 驶入右侧车道"],"c":"您必须通过制动来中断巡航控制系统。那名摩托车手变道进入了您的安全距离。您只有通过制动才能恢复安全距离。无法变入右侧车道，否则您会进入前后相继车辆的安全距离内。限速规定不得以超过130 km/h的车速行驶。"},"2.1.07-121-M":{"q":"在这种情况下您必须怎么做？","o":["我立即急刹车","我不避让","我向左转向"],"c":"在这种情况下，您应当立即用力制动，但不要转向闪避。"},"2.1.07-122":{"q":"您在一条深受摩托车骑行者喜爱的蜿蜒路段上行驶。您必须预料到什么？","o":["摩托车骑行者因过弯时车身大幅倾斜而侵入我的车道","摩托车骑行者切弯","摩托车骑行者冒险超越我"],"c":"在弯道较多的道路上，摩托车手由于倾斜幅度大，可能会切弯或在弯道处越过到您的行车道上。即使是与您同向行驶的摩托车手，也可能利用弯道，并倾向于进行冒险的超车操作。"},"2.1.07-123-M":{"q":"您现在应该怎么做？","o":["我减速","我暂时保持在[红色]车辆后方","我快速驶过[红色]车辆"],"c":"那辆红色车辆的驾驶员切弯。请制动并留在该车后方，直到您确信它在弯道后会保持在自身车道内。"},"2.1.07-124-M":{"q":"现在正确的行为是什么？","o":["我减速","我尽可能靠右行驶","我示意摩托车骑行者他可以超越我"],"c":"在视线不清的道路上，或者当狭窄街道上有对向来车时，您应当始终密切关注其他交通参与者并调整车速。这样可以事先减少危险情况。\n您还应当尽量靠右行驶，以避免与对向驶来的卡车相撞。由于树木遮挡，您看不清对向卡车有多靠中间行驶。如果后方的摩托车试图超车且尚未看到卡车，您也能为道路上创造更多空间。"},"2.1.07-202":{"q":"您应该怎么做？","o":["减速，做好刹车准备","驶入左侧车道","继续行驶，闪灯示意"],"c":"在您前方行驶的一辆汽车停车了。您必须降低车速，然后在摩托车超越您之后变道，以避开停放的汽车。"},"2.1.07-203":{"q":"关于使用后视镜，您应该知道什么？","o":["我无法看到盲区内的车辆和行人","后视镜必须针对具体驾驶员进行调整","车内后视镜在右侧没有盲区"],"c":"使用后视镜需要了解以下内容：1. 后视镜必须在开始行驶前调整到适合驾驶员的位置。2. 所有类型的后视镜都存在盲区。盲区指视线被遮挡的区域，其中行人、小型车辆或障碍物可能被忽略。通过最佳地调整外侧后视镜和车内后视镜，您可以把盲区保持在尽可能小的范围内。"},"2.1.07-204":{"q":"您正驶入一个右弯。一名摩托车骑行者高速迎面驶来。您应考虑哪些风险？","o":["- 会因车身大幅倾斜而侵入我的车道","- 会切弯并侵入我的车道","- 会及时刹车并避免侵入我的车道"],"c":"当您进入右转弯时，对向的摩托车手正在左转。他的上身朝您这边倾斜。请注意，此时摩托车手几乎和一辆汽车一样宽。如果骑手为了增大转弯半径、降低离心力而过于靠近中线行驶，他的上身就可能被您的车辆撞到。"},"2.1.07-205":{"q":"在一条狭窄道路上，您想在坡道上超越骑行者。您应该怎么做？","o":["- 保持较大的侧向距离","- 让迎面来车先通过再超车","- 小心地紧贴骑行者驶过"],"c":"骑车人在上坡路段更容易摇晃。因此，与骑车人所需的最小1.5米间距应当加大。必须在允许对向交通通过后才能超车。超车经过骑车人时不要紧贴他们行驶。"},"2.1.07-206":{"q":"您在一条乡村公路上行驶。您前方有一列约15辆缓慢行驶的车辆。您应该怎么做？","o":["我暂时保持在这列车队后方","我闪灯并鸣喇叭催促前方车辆超车","我尽快超越这列车队"],"c":"在这样的车流中，保持冷静并保持必要的安全距离很重要。所谓逐车穿插超车（队列穿插），并不会节省时间，反而会带来很高的事故风险。"},"2.1.07-207":{"q":"您停车让乘客从右侧下车。那里沿路有一条自行车道。您应该怎么做？","o":["我应确保没有骑行者正驶来","我应向下车的人指出自行车道","我应仅通过后视镜观察交通状况"],"c":"您作为汽车驾驶员负有特别的注意义务。因此，如果您在自行车道旁停车并带有同乘人员，应当在他/她下车前提醒其注意骑车人。"},"2.1.07-208":{"q":"您将车速从50 km/h提高到100 km/h。按照经验法则，反应距离如何变化？","o":["它从15米增至30米，是原来的两倍","它从25米增至100米，是原来的四倍","它从50米减至25米，是原来的一半"],"c":"如果汽车驾驶员把车速提高一倍，制动距离就会从15米增加到30米。"},"2.1.07-209":{"q":"什么可能导致较快行驶的车辆在干燥的直路上突然偏摆？","o":["阵风","轮胎爆裂","持续的逆风"],"c":"阵风和轮胎爆裂会使您的车辆偏离方向，并使您偏离行进方向。"},"2.1.07-210-M":{"q":"您应预料到什么？","o":["一个危险的左弯","位于弯道转角的障碍物","山顶前的横向车流"],"c":"该危险标志警示前方有急左转弯。坡顶遮挡了道路上向前的视线。弯道无法看清。您必须预料到有抛锚车辆或其他障碍物。由于道路的原因，坡顶前不可能有横向交通。"},"2.1.07-211-M":{"q":"现在正确的做法是什么？","o":["我保持在中间车道","我驶入左侧车道","我驶入右侧车道"],"c":"从后视镜中可以看到，您后方的左侧车道上有一辆车。因此请留在中间车道，让卡车变道超车。"},"2.1.08-005-B":{"q":"在此您必须预料到什么？","o":["前方车辆变更车道","地下通道后车流更密集","右侧车道终止"],"c":"该标志预告左侧车道结束。车流将从两条车道汇合为一条车道。可能出现停车排队。左侧车道上的车辆将变道。您必须按照拉链式交替并入原则，允许车道左侧的车辆变更到您的车道。"},"2.1.08-006-B":{"q":"在此您必须怎么做？","o":["再次检查您的车速，必要时刹车","只在弯道上刹车，以免妨碍后方跟行车辆"],"c":"如果汽车驾驶员在高速公路上长时间高速行驶，感官会习惯这种快速节奏。存在低估车速的危险。尤其当您想驶出时，请查看车速表确认车速。利用高速公路的减速车道来降低车速。在那里制动不会妨碍任何人。这样您就能以合理车速进入出口的急弯。"},"2.1.08-008-B":{"q":"这里正在形成交通堵塞。正确的做法是什么？","o":["如有可能开启危险警示灯，以警示后方跟行车辆","尽可能靠右行驶，以便在左侧留出通道","尽可能靠左行驶，以便在右侧留出通道"],"c":"如果您驶向交通拥堵，请开启危险警示灯以警示其他交通参与者。为可能驶来的救援车辆让出救援通道很重要。此时应尽量靠右行驶。"},"2.1.08-010":{"q":"在高速公路的坡道上您必须预料到什么？","o":["右侧车道上有缓慢行驶的卡车","其他道路使用者突然超车","车辆之间巨大的速度差"],"c":"在高速公路上坡行驶时，您应当预料到右侧车道有缓慢行驶的卡车、其他交通参与者的突然超车操作，以及车辆之间较大的速度差。这3个答案都是正确的。"},"2.1.08-011":{"q":"您必须怎么做？","o":["减速并保持在车道内","驶入左侧车道","保持车速并保持在车道内"],"c":"由于您目前正被左侧的一辆汽车超越，您必须保持车道并降低车速，直到您前方的那辆卡车完成超车操作并变入右侧车道。"},"2.1.08-013":{"q":"驶入高速公路时您必须注意什么？","o":["在合流车道上，我可以比直行交通开得更快","直行交通有优先权","右侧车道上的直行交通必须让驶入的车辆合流"],"c":"在高速公路上，连续车流始终拥有先行权，不必让行进入的车辆。在加速车道上，驾驶员可以比其他车辆行驶得更快。"},"2.1.08-014":{"q":"您以推荐车速在高速公路上行驶，并想在下一个出口驶出。您应该怎么做？","o":["我及时停止超车","我在出口车道上大幅减速","我仍在高速公路右侧车道时就大幅减速"],"c":"请及时完成超车并驶入右侧车道。在变入减速车道前，请观察四周并打转向灯。在减速车道上，请查看车速表确认车速，以便正确判断。只有到了减速车道，才应明显降低车速，以免妨碍连续车道上的后续交通。"},"2.1.08-015":{"q":"以约120 km/h行驶了较长路程后，您想驶出高速公路。此时您必须注意什么？","o":["我及时打转向灯，然后在出口车道上刹车，以免妨碍后方交通","我查看车速表，以确保不低估车速","我在出口车道上保持车速，以免妨碍后方交通"],"c":"如果您作为汽车驾驶员以约120 km/h的车速驶离高速公路，必须注意以下事项：1. 及时完成所有超车操作；2. 向右并入；3. 在查看车速表的同时降低车速；4. 打转向灯。为不妨碍连续道路上的交通，您应当只在变入减速车道时才降低车速。"},"2.1.08-016":{"q":"您现在应该怎么做？","o":["我降低车速","我打开危险警示灯","我在畅通的车道内继续行驶"],"c":"在高速公路上驶近拥堵末端时，您必须降低车速，并通过开启危险警示灯来警示后方交通参与者。应让出救援通道。"},"2.1.08-017":{"q":"对于这个弯道您应预料到什么？","o":["弯道转角处有障碍物","弯道会随着延伸变得更急","我的车道上会有迎面来车"],"c":"弯道的走向无法判断。您必须始终预料到有抛锚车辆或交通拥堵等障碍物。请做好在可见范围内停车的准备。弯道在行进中可能变窄。这样您只会在弯道中才发现车速过快。及时降低车速很重要。"},"2.1.08-018":{"q":"在这种情况下什么是正确的？","o":["我必须减速","卡车有优先通行权","卡车必须等待"],"c":"该弯道对汽车驾驶员而言难以判断。路线上可能有其他交通参与者甚至障碍物。因此，即使在转弯前减速并在心理上做好应对可能危险情况的准备也是明智的。因为即使对对向驾驶员来说，这也是一个困难的位置，需要谨慎。"},"2.1.08-019":{"q":"为什么您在此必须减速？","o":["因为卡车","因为限速","因为白色汽车"],"c":"右侧车道上带有闪烁箭头的可移动路障迫使卡车驾驶员变入您所在的左侧车道。因此您现在必须减速。您后方的那辆白色汽车不构成危险。"},"2.1.08-020":{"q":"为什么您现在必须减速？","o":["因为蓝色汽车","因为限速","因为红色厢式货车"],"c":"在这种情况下，那辆蓝色汽车很可能会变入右侧车道。因此您应当降低车速，并与它保持安全距离。"},"2.1.08-021":{"q":"您至少比绿色卡车快20 km/h。您应该怎么做？","o":["我在绿色卡车前方驶上高速公路","我刹车并在绿色卡车后方驶上高速公路","我在合流车道末端停车，并在蓝色卡车后方驶上高速公路"],"c":"您处于驶入高速公路的加速车道上。在加速车道上允许比连续车道上的车辆行驶得更快。因此，您可以在绿色卡车前方以更快的车速驶入高速公路。"},"2.1.08-022":{"q":"您正接近这些车辆。在这种情况下您应该怎么做？","o":["我保持在中间车道，但不超越白色汽车","我保持在中间车道并谨慎超越白色汽车","我驶入左侧车道并闪大灯，直到前方的人让出车道"],"c":"左侧车道上的那辆白色汽车不得从右侧被超越。到它左后方并用闪烁远光灯要它让道也是禁止的。您必须减速，并在中间车道上以与该车相同的速度行驶。请给它留出足够距离，以便它随时能够变入中间车道。"},"2.1.08-023":{"q":"您驾驶一辆卡车。现在正确的做法是什么？","o":["我加大与前车的距离","我保持车速","我超越我前方的卡车"],"c":"请加大与前车的距离，从而保持必要的安全距离。"},"2.1.08-024-M":{"q":"您现在应该怎么做？","o":["- 不要变更车道，因为[红色汽车]已经在横向移动","- 驶入中间车道，因为我的超车已完成","- 变更车道，以免妨碍[黄色汽车]"],"c":"您旁边有一辆红色汽车正变入中间车道。因此您不能变道，否则会危及其他交通参与者。"},"2.1.08-025":{"q":"您想驶入高速公路。您应遵循什么行驶路线？","o":[],"c":"驶入高速公路时，您应当继续沿着第三条行驶线行驶，即保持在自己的车道内，不要切到分界线上。"},"2.1.08-026-M":{"q":"现在您应做好什么准备？","o":["[黄色汽车]驶出高速公路","摩托车驶出高速公路","我前方的[蓝色客车]因交通堵塞而刹车"],"c":"在这种情况下看不到有交通拥堵。由于摩托车行驶在左侧，它不会离开高速公路。另一方面，您左侧行驶的那辆汽车向右闪灯。您可以预料到该驾驶员要驶离高速公路。"},"2.1.08-027-M":{"q":"您想驶出高速公路。在此什么造成了危险情况？","o":["摩托车","[黄色卡车]","[绿色车辆]"],"c":"您后方的摩托车（见右侧后视镜）给您造成了危险情况。驶离高速公路时请考虑到这一点。"},"2.1.08-028-M":{"q":"现在正确的做法是什么？","o":["我减速","我保持在左侧车道","我像之前一样继续行驶"],"c":"卡车前方的右侧车道上有一个物体。卡车会通过使用左侧车道来避开该物体。因此您应当留在左侧车道。如果您继续不变地行驶，可能会与卡车相撞。因此您应当降低车速。"},"2.1.08-029-M":{"q":"为什么您现在必须减速？","o":["因为卡车","因为限速","因为[蓝色]汽车"],"c":"卡车前方的右侧车道被堵住了。它必须变入左侧车道。为让它能够这样做，您应当降低车速。您后方的汽车不是您减速的理由。此处最高允许车速为120 km/h。请记住这一点。"},"2.1.08-030-M":{"q":"您想驶离高速公路。正确的做法是什么？","o":["我每隔很短的时间就查看车速表以检查车速","我现在减速","我只在到达转弯处时才减速"],"c":"一旦进入减速车道，您就应当制动。如果在进入减速车道之前制动，您就会不必要地妨碍高速公路上的交通。您应当更频繁地查看车速表，以确保不会过快进入弯道。在高速公路上存在一种危险：您会过于习惯高速，从而过快驶入出口。如果您到转弯处才减速，就无法及时降低车速。一般而言，您应当始终在弯道之前制动，而不是只在弯道中制动。"},"2.1.08-031":{"q":"在高速公路上行驶时，为什么您应保持130 km/h的推荐车速？","o":["- 能防止事故发生","- 能减轻可能事故的严重程度","- 实现均匀的车流"],"c":"车速越高，反应距离、制动距离等就越长。如果所有车辆都以相近车速行驶，交通流就会更加均匀。"},"2.1.08-032-M":{"q":"在此您必须预料到什么？","o":["[黄色卡车]的驾驶员没有及时发现堵车队伍的开端","摩托车在车列之间穿行","[蓝色汽车]在我前方驶入我的车道"],"c":"由于突然出现的交通拥堵，卡车驾驶员过晚看到拥堵末端。由于交通拥堵，摩托车会试图从车辆队列之间穿过。"},"2.1.08-033-M":{"q":"驶出出口匝道时您应预料到什么？","o":["一辆抛锚的车辆","车道上的人","掉落的货物"],"c":"警告三角牌提示出口车道附近有障碍物，例如人员、故障车辆或掉落的货物。因此，请以大幅降低的车速驶入出口。"},"2.1.08-102":{"q":"为什么您应避免在施工路段旁超车？","o":["节省的时间往往微不足道","右侧车道上的车辆可能越过黄色路面标线","事故风险显著增加"],"c":"在施工区域内超车，事故风险会显著增加，因为您想超越的车辆有碾过黄色车道标线的风险。车道大多更窄，而且路边的干扰因素可能导致注意力不集中。\n在施工区域内超车往往几乎节省不了时间，因为施工区域内大多数驾驶员都只按最高限速行驶。"},"2.1.08-103":{"q":"如何降低逆规定方向驶上高速公路的风险？","o":["我在高速公路匝道处特意寻找显示正确行驶方向的交通标志","当行车路线变化时，我密切关注标志","遇到施工路段时，我只遵循导航系统提供的信息"],"c":"为避免在高速公路上逆行驶入，您应当始终注意相关的交通标志。尤其当交通路线发生变化时，注意准确的标志非常重要。"},"2.1.09-201":{"q":"作为值勤的客车驾驶员，您必须记住什么？","o":["- 值勤和待命值勤期间不饮用任何含酒精饮料","- 不在酒精作用下开始驾驶","- 值勤期间饮用含酒精饮料，只要不超过0.3‰的血液酒精浓度标准"],"c":"即将推出……"},"2.1.09-202":{"q":"作为值勤的客车驾驶员，您必须记住什么？","o":["值勤或待命值勤期间不得服用任何损害驾驶能力的毒品或药物","当您因毒品或药物导致驾驶能力受损时，不得开始驾驶","您可以服用任何无需处方的药物，而不必担心驾驶能力受损"],"c":"即将推出……"},"2.1.10-001":{"q":"如果夜间在开阔路段行驶时您察觉到疲劳迹象（眼皮沉重、感觉发冷、突然惊悸等），您必须怎么做？","o":["中断行程，进行充分的休息","打开收音机并继续行驶"],"c":"只有及时进行足够长的休息，您才能避免疲劳迹象。不要靠打开收音机来保持清醒，因为这有可能使您进一步分心。如果您已经感觉到疲劳的最初症状，请尽快找一个可以较长时间休息的地方。"},"2.1.10-002":{"q":"长途旅行中如何预防疲劳？","o":["通过适时且充分的休息停车","在休息期间做体操","喝咖啡且不停车休息"],"c":"及时休息可以防止过度疲劳。休息期间做体操可以促进血液循环，对关节也有好处。咖啡只有短期的提神作用，之后可能很快走向反面。也就是说，您可能在毫无预兆的情况下睡着。"},"2.1.10-003":{"q":"使用驾驶辅助系统时的潜在风险是什么？","o":["- 对系统抱有不切实际的期望","- 对周围交通关注过少","- 忽视自身的个人责任"],"c":"汽车驾驶员可能对高级驾驶辅助系统抱有过高的期望。这可能导致汽车驾驶员忽视自身的责任，对交通关注过少。即使使用高级驾驶辅助系统，安全驾驶的责任仍由驾驶员承担。"},"2.1.10-004":{"q":"如果行驶中使用电子设备而分心，风险是什么？","o":["我可能偏离我的车道","我可能没有注意到道路交通标志","我的停车距离可能缩短"],"c":"驾驶时使用电子设备可能导致您错过交通标志并偏离车道（注意力分散）。"},"2.1.10-005":{"q":"什么常导致年轻驾驶员发生“迪厅事故”？","o":["- 过度疲劳","- 身体极度疲惫","- 不适合驾驶"],"c":"这三项都是正确的。所谓迪斯科事故是由过度疲劳、身体疲劳以及不适合驾驶的状态造成的。"},"2.1.10-006":{"q":"如果在夜间行驶中您感觉到疲劳迹象，正确的做法是什么？","o":["我中断行程，进行充分的休息","如有可能，我让副驾驶员来驾驶","我决定不休息，与疲倦作斗争"],"c":"一旦您感到疲倦，就应当立即休息。睡着（打瞌睡）的风险每过一秒都在增加。如果可能，在同行乘客持有驾照的情况下可以让其驾驶。"},"2.1.10-101":{"q":"什么会降低道路交通中的警觉性？","o":["强烈的情绪（例如喜悦、恼怒、急躁）","热烈的交谈","车载收音机中引人入胜的节目"],"c":"所有外部刺激，例如喜悦、愤怒、收音机里有趣的内容以及热烈的交谈，都可能对驾驶时的注意力产生负面影响，因为它们会分散注意力。"},"2.1.10-102":{"q":"在您驾驶时什么会让您严重分心？","o":["打电话","点烟","在后座上吵闹的孩子"],"c":"驾驶时打电话只允许通过免提系统进行。即使如此，它仍然会分散注意力。点燃香烟被视为强烈的分心行为，因为它会把视线从道路引向香烟。哭闹的孩子和乘客可能非常让人分心，必要时请休息一下。"},"2.1.10-103":{"q":"何时您应中断行程？","o":["- 想捡起车内掉落的物品","- 察觉到注意力正在下降","- 想启用定速巡航系统"],"c":"尤其在较长的行程中，注意力随时可能减退。如果您注意到自己的注意力明显减弱，务必要休息一下。\n如果您想捡起掉入车内的物品，也应当停车。寻找并捡起物品会使您严重分心。因此，您可能危及自己和他人。"},"2.1.11-003":{"q":"一名缓慢的驾驶员妨碍您快速前行。什么是正确的？","o":["您跟在他后面，直到有超车的机会","您闪大灯让他开得更快","您靠近他以缩短超车距离"],"c":"切勿开始冒险的超车操作，也不要用闪烁远光灯逼迫前车加速。保持必要的安全距离，等待适合安全超车的有利时机。"},"2.1.11-007":{"q":"怎样才是一名好驾驶员？","o":["他把他人当作伙伴，冷静沉着地驾驶，不炫耀自己的优越","他利用一切机会超车、甩开他人并炫耀自己的优越，即使他的驾驶方式带有风险","他开快车以展示自己的能力"],"c":"好的驾驶员遵守交通规则，其特点是在与其他交通参与者打交道时表现出合作的行为。他/她会避免冒险的驾驶方式和粗心的超车操作。好的驾驶员不必向他人证明自己的能力。"},"2.1.11-008":{"q":"在主干道上跟行很长时间后，您终于能够超越一辆行驶非常缓慢的汽车。您应该怎么做？","o":["- 我在足够的距离后并入，以免妨碍另一位驾驶员","- 我短暂刹车，以引起另一位驾驶员对其缓慢车速的注意","- 我特意开得很慢，以向另一位驾驶员强调其驾驶方式的后果"],"c":"在这种情况下您应当保持冷静，并在保持足够安全距离的情况下超车，而不危及他人。应当避免通过紧逼他人来施压。否则可能发生事故。"},"2.1.11-009-M":{"q":"前方车辆已有一段时间让您无法超车。正确的做法是什么？","o":["我等到能够超车时再超","我缩短车距","我持续鸣喇叭并闪大灯"],"c":"汽车驾驶员必须等到能够无危险地超车时再超车，并始终与前车保持必要的安全距离。请保持冷静，因为紧逼前车、长时间开启远光灯或鸣喇叭被视为强迫（胁迫）行为，会受到罚款处罚，甚至吊销驾照。"},"2.1.11-010":{"q":"就在您想出发前，您因某事而恼火，变得非常生气。您应该怎么做？","o":["等我重新冷静下来后，我才出发","我出发，以分散自己对怒气的注意","我尝试快速到达目的地，以便在那里冷静下来"],"c":"怒气冲冲地上车会对您的驾驶方式产生负面影响。如果您生气，驾驶方式也会变得具有攻击性且受到限制。因此，只有当您情绪宣泄平复后才上车。"},"2.1.11-011":{"q":"您刚刚通过紧急制动避免了一起交通事故。您的双手和膝盖在颤抖。您离目的地还很远。您应该怎么做？","o":["- 前往下一个停车点，以便让自己冷静下来","- 前往我的目的地，以便恢复镇静"],"c":"您应当先冷静下来。因为您的不安会对驾驶方式产生负面影响。找一个地方停车放松。之后您可以继续行程。"},"2.1.11-012":{"q":"在漫长的一天工作后驾驶汽车时，您应注意什么？","o":["我的注意力水平较低","我会更快感到疲倦","我犯的驾驶错误更少"],"c":"在漫长的一天工作之后，您通常无法保持完全的效率，并且更容易疲倦。因此驾驶时的失误可能增多，注意力也会下降。"},"2.1.11-013":{"q":"如何辨认一名好驾驶员？","o":["- 表现出冷静放松的驾驶方式","- 不对道路上的挑衅作出回应","- 总是告知其他交通参与者他们的驾驶错误"],"c":"好的驾驶员始终注意以合作的方式行事，并且也知道人会犯错。"},"2.1.11-014-M":{"q":"您前方的[红色]汽车已缓慢行驶了一段时间。在这种情况下正确的做法是什么？","o":["我保持车速","我超车，因为道路畅通","我缩短车距并鸣喇叭"],"c":"您保持自己的车速，以免紧逼前车，并保持必要的安全距离。在交通中紧逼前车、跟车过近或鸣喇叭都是禁止的。\n道路是畅通的，但您只能看到下一个弯道处。可见距离对于超车操作而言太短。"},"2.1.11-015":{"q":"什么常导致年轻人发生“迪厅事故”？","o":["对道路交通缺乏意识","冒险倾向高","防御性驾驶方式"],"c":"尤其年轻驾驶员驾驶经验较少，并且因逞强好胜而有更高的冒险意愿。他们对危险情况的判断较差，事故也更频繁地发生。\n防御性的驾驶方式可以预防事故。"},"2.1.11-016":{"q":"为什么在时间压力下驾驶可能危险？","o":["- 风险常被低估","- 驾驶员常常开得过快","- 常采用防御性驾驶方式"],"c":"当您时间紧迫时，您可能低估危险，因为您的冒险意愿会增加，人们往往开得太快。您仍应当防御性驾驶并遵守限速，以免危及自己和他人。"},"2.1.11-017":{"q":"您在城镇外的一条道路上，您前方的一辆汽车行驶得比允许且其能力所及的速度慢得多。正确的做法是什么？","o":["我使我的车速与该车一致","我在合适的地点超车","我闪大灯，直到该车开始开得更快"],"c":"即使您不喜欢，也必须把车速调整到与那辆汽车相同，而不要过于靠近它。只在合适的地方超车，而不要紧逼它超车。不要危及自己或他人。"},"2.1.11-018":{"q":"为什么频繁变更车道不可取？","o":["因为这可能增加驾驶错误的风险","因为由此节省的时间通常很少","因为这可能危及其他道路使用者"],"c":"每次变道都需要一定的动作：观察交通、打转向灯、自己变道。在这种情况下，可能忽略并危及他人。频繁变道往往节省不了多少时间，但变道越频繁，就越容易犯错。"},"2.1.11-019":{"q":"您通过紧急制动勉强避免了一起交通事故。您的双手和膝盖在颤抖。正确的做法是什么？","o":["我尽快找机会休息，以让自己冷静下来","稍后我思考本是否可以避免该情况","我继续行驶以让自己冷静下来"],"c":"在下一个合适的时机停车休息，直到您冷静下来。也许您可以下车走几步并深呼吸。\n之后您还应当在脑中重新回顾当时的情况，因为您可能会意识到哪里做得不够好。这样您就能在将来调整自己的驾驶行为。"},"2.1.11-020":{"q":"行驶中，您对另一名道路使用者的行为感到非常恼火。现在正确的做法是什么？","o":["我继续专注于道路交通","我继续以不让怒气对交通安全产生不利影响的方式行驶","必要时我休息一下以让自己冷静下来"],"c":"重要的是，即使您因其他驾驶员的行为而恼火，也不要被交通分散注意力，因为道路安全至上。专注于交通并冷静地继续驾驶；如果在驾驶时情绪激动，您可能忽略危险。必要时休息一下，等冷静后再继续驾驶。"},"2.1.11-111":{"q":"为什么环保驾驶总体上对交通安全有积极作用？","o":["因为驾驶员行驶时会提前思考，从而能及时发现并妥善避免可能的危险","因为环保驾驶避免高速，从而危险情况发生得更少","因为使用替代燃料只能缓慢行驶"],"c":"避免高速行驶并有预见性地驾驶。这不仅对环境有积极影响，也有助于提高道路安全。"},"2.1.11-112":{"q":"您所在的车队被一辆汽车不体谅地超越。由于迎面来车，该驾驶员想并入您前面汽车前方的车队。这位驾驶员很恼火并“堵住空隙”。您会怎么做？","o":["您让步，让这位挤插的驾驶员并入车队","您也“堵住空隙”，以教训这位挤插的驾驶员","什么也不做，因为与您无关"],"c":"在这种情况下，您应当通过有意退让来降低车速，并给其他交通参与者留出回到车道内的空间，以降低事故风险。请记住，每个人都可能判断失误。"},"2.1.11-113":{"q":"一辆打右转向灯的卡车在您前方行驶。一位不耐烦的汽车驾驶员正挤插您。您能怎么做？","o":["只有在我完全确定交通状况允许安全超车时，我才超车","我拉大与卡车的距离，以便利这位挤插的驾驶员超车","我超车，因为我以为卡车驾驶员想向我示意可以超车"],"c":"在这种情况下，最好收敛并保持安全距离。也许卡车驾驶员是想示意道路已畅通。但也可能是他/她打算停车或向右转弯。只有在没有危险时才超车。请加大与卡车的距离，以便后面那位急躁的驾驶员能够超车。"},"2.1.11-114":{"q":"在城镇外的道路上，一辆汽车以略低于允许速度的车速在您前方行驶。您对这辆缓慢行驶的汽车感到恼火。您应该怎么做？","o":["我使我的车速与前方车辆一致","我在合适的地点超车","我闪大灯，直到前方汽车开始开得更快"],"c":"您务必要等到安全的情况再超车。通过紧逼前车或闪烁远光灯来施压，则构成威胁甚至强迫（胁迫）。您应当避免这样做。"},"2.1.11-115":{"q":"在周末夜间休闲驾驶中，什么常导致交通事故？","o":["- 天黑后驾驶经验少","- 满载车辆驾驶经验少","- 对道路交通法规了解少"],"c":"夜间驾驶经验不足，以及缺乏对满员车辆中驾驶行为的了解，常常导致周末夜间休闲出行时发生事故。"},"2.1.11-116":{"q":"您处于时间压力下。您必须确保什么？","o":["- 超速","- 即使红灯也闯过信号灯","- 降低安全性"],"c":"即使您时间紧迫，也必须遵守交通规则。这也意味着您要遵守限速。毕竟，超速是事故的首要原因。"},"2.1.11-117":{"q":"当年轻人在周末夜间休闲驾驶时，常发生严重事故。这里哪些原因可能特别相关？","o":["不适当的车速","高冒险倾向","犹豫不决的驾驶方式"],"c":"不合理的车速和冒险意愿常常导致年轻人在夜间周末出行时发生严重事故。"},"2.1.11-118":{"q":"一辆汽车超越您后，未在您前方留出足够空间就并入车道。您应该怎么做？","o":["我保持冷静以避免冲突","我刹车，以确保重新建立安全距离","我闪大灯以引起对方对妨碍的注意"],"c":"那辆超车车辆的汽车驾驶员表现出不当行为，您不应被其干扰。保持冷静，不要鸣喇叭，也不要开启闪烁远光灯。稍微减速并恢复车辆之间所需的安全距离。"},"2.1.11-119":{"q":"对于18至24岁的驾驶员，驾驶车辆引发事故的风险明显更高。这里哪些原因常常相关？","o":["驾驶经验太少","高估自身能力","更高的冒险倾向"],"c":"年轻汽车驾驶员往往经验太少，无法正确判断道路交通风险。他们常常粗心而冒险地驾驶，高估自己的能力，并依赖所驾车辆的安全性。通过试探自己的车和自身驾驶技术，他们有时会陷入无法掌控的局面。"},"2.1.11-120":{"q":"当您遇到交通堵塞时，您从后视镜中看到一名摩托车骑行者“蛇行”穿过静止的车列。您应该怎么做？","o":["我让他驶过","我鸣喇叭并记下他的车牌号","我采取措施确保他也必须停车"],"c":"在任何情况下，您都不应仅仅因为其他交通参与者违反现行规则自己就违法行事。您作为汽车驾驶员在此情况下鸣喇叭、拦停那名摩托车手或让其通过都是禁止的。"},"2.1.11-121":{"q":"您在主干道上行驶，后方一辆汽车正“紧贴”您行驶。您应如何反应？","o":["我保持车速并靠右行驶，以便后方汽车能超车","我加速，直到后方汽车不再“紧贴”我","我减速，直到后方汽车不再“紧贴”我"],"c":"在高速公路上行驶并被后方汽车逼迫时，您应当保持冷静并以合适的速度控制车速。您应当避免慢速行驶，以免妨碍交通流。但也不应受诱惑开得更快。最好在下一个合适的时机让那位急躁的驾驶员通过。"},"2.1.11-122":{"q":"您在高速公路上超车。您后方一辆汽车高速驶来，闪着大灯和转向灯。您应该怎么做？","o":["我迅速继续超车","我尽快并入右侧车道","我缓慢减速"],"c":"您唯一能做的就是保持冷静！保持冷静，不要试图报复那位急躁的驾驶员。最好让他通过。如果您有足够的超车速度，仍可以完成超车过程。一旦出现下一个合适的时机，您应当变入右侧车道，让那位急躁的驾驶员通过。"},"2.1.11-123":{"q":"五个年轻朋友驾车前往一场休闲活动。气氛欢快。这可能带来哪些风险？","o":["- 被分散对道路上情况的注意力","- 被诱导以冒险的方式驾驶","- 被诱导缓慢行驶"],"c":"对汽车驾驶员而言，存在被情绪带动的危险。他/她可能被其他人分散注意力，忽略交通危险并犯下驾驶错误。建议在出发前为乘客制定行为规则。这样汽车驾驶员就不会被视为扫兴的人，也不会受到任何诱惑。"},"2.1.11-124":{"q":"在高速公路行驶时您超越了几辆车。一辆车从后方闪着转向灯和大灯驶来。您应该怎么做？","o":["我继续行驶，直到能再次并入右侧车道","我短暂打开危险警示灯，催促后方车辆保持距离","我短暂刹车，促使后方车辆保持距离"],"c":"后方车辆密集、具有攻击性地紧逼，会危及所有交通参与者。因此，您应当尝试在保持安全距离的前提下变入右侧车道。任何制动操作都只会使这一危险局面恶化。此情况下开启危险警示灯是禁止的。"},"2.1.11-125":{"q":"您想超车。为什么您不应超车？","o":["迎面来车","道路弯道","路面状况"],"c":"汽车驾驶员只有在能看到对向车道空着时才允许超车。在这种情况下看不到对向交通，因此您不得超车。"},"2.1.11-126":{"q":"您在开始行程前心情不好。驾驶时您应避免哪些后果？","o":["分心","攻击性","谨慎"],"c":"任何可能对您的安全驾驶产生负面影响的事物都应避免。除分心因素外，这也包括攻击性。如果您心情烦躁，不要随后立刻坐到方向盘后。"},"2.1.11-127":{"q":"有责任心的驾驶员具有什么特征？","o":["他预料到其他道路使用者的错误","他疲倦时避免驾驶","他与其他道路交通参与者争强好胜"],"c":"负责任的汽车驾驶员会预料到其他交通参与者犯错，不会在自己极度疲劳或无法控制自己情绪时坐到方向盘后。此外，他/她不会总是坚持自己的权利，也不会分心。"},"2.1.11-128":{"q":"哪些情绪会影响驾驶行为？","o":["快乐与兴奋","忧虑与悲伤","愤怒与暴怒"],"c":"愤怒、恐惧、悲伤等强烈情绪，以及喜悦和兴奋，通常都会影响驾驶行为。它们会使汽车驾驶员分心，并常常导致冒险、具有攻击性或过度谨慎的驾驶。只有当您冷静而平和时，才应参与交通。"},"2.1.11-129":{"q":"哪些迹象表明您应中断行程？","o":["频繁打哈欠","难以睁开眼睛","难以保持车道"],"c":"短暂的微睡眠常常导致毁灭性的事故。如果您频繁打哈欠、几乎睁不开眼，或者难以保持车道，就应当停止行程并休息。"},"2.1.11-130":{"q":"您的乘客想在旅途中与您讨论某事。您应该怎么做？","o":["- 我的驾驶","- 讨论"],"c":"您在驾驶时不应分心。如果您的乘客想与您讨论，您应当停止行程。"},"2.1.11-131":{"q":"旅途中您的乘客告诉您，您多次紧贴前车。您应该怎么做？","o":["我认真对待乘客的意见","我保持更大的距离","我无视乘客的意见"],"c":"您应当认真对待乘客的安全建议。保持更大的距离。在城镇内，与前车的距离应至少为三个车身长度，即约15米。在城镇外，您应当遵循“两秒经验法则”。"},"2.1.11-132":{"q":"在城镇内的红灯前，另一位驾驶员显然想挑衅您进行街头飙车。您应该怎么做？","o":["我完全无视这种行为","我接受挑战，但不超过50 km/h","我下车与那位驾驶员对峙"],"c":"不要被挑衅，保持冷静。由于道路飙车（竞速）是被严格禁止的，您不应当理会这种行为。"},"2.1.11-133":{"q":"什么常导致年轻人发生“迪厅事故”？","o":["天黑后驾驶经验不足","满载车辆驾驶经验少","乘客造成的分心"],"c":"尤其年轻驾驶员，在载满乘客的情况下夜间驾驶的经验较少。此外，由于乘客使人分心，事故风险也会增加。"},"2.1.11-201":{"q":"在城镇内的红灯前，另一位驾驶员显然想挑衅您进行街头飙车。您应该怎么做？","o":["我完全无视这种行为","我接受挑战，但不超过50 km/h","我下车与那位驾驶员对峙"],"c":"道路竞速（飙车）会增加您的事故风险并使他人处于危险之中。您应当无视这类行为。"},"2.2.02-001":{"q":"您在一条每个方向各一条车道的道路上行驶并想左转。您应如何定位？","o":["- 靠近车道中央","- 在车道右缘"],"c":"在这种情况下向左转弯时，请驶向道路中央（即您车道的左侧）。"},"2.2.02-002":{"q":"您是否允许在人行道上使用您的机动自行车？","o":["可以，如果是小心推行机动自行车","可以，如果机动自行车当作自行车使用","可以，当车道上交通过于密集时也可使用发动机"],"c":"是的，但只有您推着它走才行，您不得在人行道上骑行。"},"2.2.02-003":{"q":"在“红灯”信号灯前，几辆汽车正在右侧车道等待。您是否允许谨慎地从右侧驶过这些汽车？","o":["可以，前提是车道上有足够的空间","可以，前提是您使用人行道","不可以，您必须始终在最后一辆车后方等待"],"c":"在这种情况下您可以像自行车一样行事，如有足够空间，可以从右侧超过那辆汽车。"},"2.2.02-006":{"q":"您在城镇外的一条每个方向标有三条车道的道路上行驶。个别较慢的车辆在右侧车道中彼此间隔很远地行驶。您可以持续使用哪条车道？","o":["中间车道","左侧车道"],"c":"左侧车道只允许汽车驾驶员临时超越其他车辆时使用。不过，如果道路位于城镇外并设有标线，则允许持续在中间车道行驶。即使右侧车道上只有少量车辆，这一规定同样适用。"},"2.2.02-007":{"q":"如果您在右侧车道与卡车并排行驶，可能出现哪些风险？","o":["- 被卡车驾驶员忽视","- 被其他道路使用者忽视","- 忽视其他道路使用者"],"c":"卡车会同时削弱您的视线以及道路上其他人（包括卡车驾驶员）看到您的可能性。"},"2.2.02-008":{"q":"在下一个交叉路口，您适用什么？","o":["- 左转","- 右转","- 直行"],"c":"即将推出……"},"2.2.02-009-M":{"q":"您想右转。现在正确的做法是什么？","o":["我保持在[蓝色汽车]后方","我驶到停止线","我驶到视线线（可见范围处）"],"c":"摩托车应当像汽车一样行事，并在蓝色汽车后方等待。"},"2.2.02-010":{"q":"您可以使用哪些自行车道驾驶您的轻便摩托车？","o":["城镇外的自行车道","城镇内的自行车道，如果附加标志允许","城镇内的自行车道，如果道路上交通过于拥挤"],"c":"在城镇外，您可以骑轻便摩托车行驶在自行车道上；在城镇内，如果附加标志允许，也可以行驶在自行车道上。"},"2.2.02-101-M":{"q":"在这条单行道上正确的做法是什么？","o":["我等待直到施工使我能驶过","我掉头往回行驶","我倒车驶回"],"c":"只有当施工情况允许时您才能继续行驶。在单行道上，您只能朝一个方向行驶。您不得掉头或倒车。对可能发生的任何事故，您都要负责。"},"2.2.02-201":{"q":"对于哪些指定用于或实际用于公路货物运输的机动车或汽车列车，必须在联邦公路上缴纳使用费？","o":["总质量至少7.5吨的机动车","总质量至少7.5吨的汽车列车","总质量小于7.5吨的汽车列车"],"c":"对于最大允许总质量至少为7.5 t的机动车，以及最大允许总质量至少为7.5 t的车辆组合，必须缴纳使用费（通行费）。"},"2.2.02-202":{"q":"哪些机动车和汽车列车在高速公路和联邦公路上需缴纳通行费？","o":["- 用于公路货物运输业务","- 总质量至少7.5吨","- 至少有4个座位"],"c":"最大允许总质量至少为7.5 t的机动车和车辆组合所行驶的道路均为收费道路。这也适用于用于货运的车辆。"},"2.2.02-203":{"q":"您在冬季运输危险货物。如果因压实积雪导致路况恶化，您应该怎么做？","o":["- 确保不危及他人","- 必要时寻找下一个合适的地方停车","- 总是中途不停地将危险货物运至目的地"],"c":"在结冰的天气里，您必须特别小心，以免危及他人。如果您到达了一个再也无法保证不危及他人的地方，就应当找一个合适的地方停车。"},"2.2.02-302":{"q":"您以30 km/h在一条右侧有铺装硬路肩的主干道上驾驶农用拖拉机。正确的做法是什么？","o":["如有可能我必须行驶在硬路肩上","我只能将硬路肩用于停车","我只能短暂使用硬路肩以便车辆超车"],"c":"为了继续保障交通流，请尽可能让您的农用拖拉机开到路肩上。"},"2.2.02-303":{"q":"如果您在右侧车道与卡车并排行驶，可能出现哪些风险？","o":["- 不被看见","- 忽视其他道路使用者","- 被卡车灼热的废气烫伤"],"c":"卡车会同时削弱您的视线以及道路上其他人（包括卡车驾驶员）看到您的可能性。"},"2.2.03-001":{"q":"车道上形成了一个大水坑。您会怎么做？","o":["缓慢驶过，双脚踩在脚踏板上","不刹车，抬起双腿驶过水坑","沿人行道行驶"],"c":"您应当缓慢驶过较大的积水，因为存在水滑（打滑）的风险。"},"2.2.03-002":{"q":"机动自行车（非轻型机动自行车）的最高行驶速度是多少？","o":[],"c":"轻便摩托车的最高速度为25 km/h，轻型轻便摩托车为20 km/h。"},"2.2.03-005":{"q":"您在高速公路上有雾中行驶，能见度为50米。您最高可以以多快行驶？","o":["50 km/h","70 km/h","90 km/h"],"c":"如果雾中的能见度低于50米，驾驶员不得以超过50 km/h的车速行驶。下雪或大雨时同样适用。"},"2.2.03-006":{"q":"您以100 km/h行驶，反应时间为1秒，正常刹车。按照经验法则，停车距离是多少？","o":[],"c":"正常制动时的停车距离由反应距离（（车速:10）×3）与制动距离（（车速:10）×（车速:10））相加组成。停车距离 = 反应距离 + 制动距离。车速100 km/h时，停车距离为130米。"},"2.2.03-007":{"q":"您以100 km/h行驶并正常刹车。按照经验法则，制动距离是多少？","o":[],"c":"制动距离 = （车速/10）×（车速/10）\n也就是说，车速100 km/h时，制动距离为100米。"},"2.2.03-008":{"q":"您以100 km/h行驶，反应时间为1秒。按照经验法则，反应距离是多少？","o":[],"c":"反应距离 = （车速/10）×3\n也就是说，车速100 km/h时，制动距离为30米。"},"2.2.03-009":{"q":"您以50 km/h行驶，反应时间为1秒，正常刹车。按照经验法则，停车距离是多少？","o":[],"c":"正常制动时的停车距离由反应距离（（车速/10）×3）与制动距离（（车速/10）×（车速/10））相加组成。\n停车距离 = 反应距离 + 制动距离。\n也就是说，车速50 km/h时，停车距离为40米。"},"2.2.03-010":{"q":"您以50 km/h行驶并正常刹车。按照经验法则，制动距离是多少？","o":[],"c":"制动距离 = （车速/10）×（车速/10）\n也就是说，车速50 km/h时，制动距离为25米。"},"2.2.03-011":{"q":"您以50 km/h行驶，反应时间为1秒。按照经验法则，反应距离是多少？","o":[],"c":"反应距离 = （车速/10）×3\n也就是说，车速50 km/h时，制动距离为15米。"},"2.2.03-012":{"q":"您在一条非常狭窄的道路上行驶，前方可见50米。您的最大停车距离必须是多少？","o":[],"c":"在狭窄的街道上，您必须在可见距离的一半之内停车，在此情况下即25米。"},"2.2.03-015":{"q":"在干燥、平整的沥青车道上计算应急制动（避让制动）距离的经验法则是什么？","o":["（{速度 km/h}/{10} × {速度 km/h}/{10}）÷ 2","（{速度 km/h}/{10} × 5）÷ 2","（{速度 km/h}/{10} × 3）÷ 2"],"c":"确定停车距离的经验法则是：反应距离（车速除以10再乘以3）加上制动距离（车速除以10再乘以车速除以10）。车速50 km/h时，即50除以10乘以3等于15米反应距离，加上50除以10乘以50除以10等于25米制动距离。停车距离为40米。在紧急制动的情况下，该数值减半。在本示例中即为20米。"},"2.2.03-016":{"q":"您以40 km/h行驶。应急制动的制动距离约为8米。在其他条件相同的情况下，以50 km/h行驶时制动距离是多少？","o":["12.5 m","11.0 m","9.5 m"],"c":"您车辆的正常制动距离由此经验法则确定：车速除以10再乘以车速除以10。要计算紧急制动时的制动距离，所得到的数值再减半（除以2）。此处即为：50/10 × 50/10 = 25，再除以2 = 12.5米。"},"2.2.03-017":{"q":"在城镇外的道路上，您驾驶总质量4.0吨的卡车最高可以以多快行驶？","o":[],"c":"当您的4.0 t卡车符合上路行驶条件时，在城镇外的道路上，对您适用80 km/h的最高车速。"},"2.2.03-018":{"q":"在城镇外的道路上，您驾驶带拖车的汽车最高可以以多快行驶？","o":[],"c":"如果轿车拖挂一辆拖车，在城镇外最高可以80 km/h的车速行驶。"},"2.2.03-019":{"q":"在城镇外的道路上，您驾驶总质量3.0吨且带拖车的卡车最高可以以多快行驶？","o":[],"c":"如果最大质量为3.0吨的货车拖挂一辆拖车，在城镇外最高可以80 km/h的车速行驶。"},"2.2.03-020":{"q":"在主干道上，您驾驶带行李拖车的客车最高可以以多快行驶？","o":[],"c":"即将推出……"},"2.2.03-021":{"q":"在主干道上，您驾驶限速100 km/h的客车最高可以以多快行驶？","o":[],"c":"即将推出……"},"2.2.03-022":{"q":"在主干道上，您驾驶总质量7.5吨的卡车最高可以以多快行驶？","o":[],"c":"您的卡车，总质量超过7.5 t，在乡村道路上行驶时，最高只允许以60 km/h的车速行驶。"},"2.2.03-023":{"q":"您在良好能见度条件下行驶于一条质量良好的道路。您必须能在什么距离内停车？","o":["- 我能看见的路段","- 我能看见路段的一半","- 我能看见路段的两倍"],"c":"在路况良好的道路上，能见度良好时，您必须能够在可判断的范围内停车。夜间，近光灯的照射范围视为可判断的范围。"},"2.2.03-024":{"q":"您在黑暗中依靠近光灯行驶于一条修建良好的主干道。您必须能在什么距离内停车？","o":["- 近光灯","- 远光灯","- 示宽灯"],"c":"您必须能够在近光灯的照射范围内停车，因为示宽灯（停车灯）太弱，无法为您提供可见的照明。如果您需要远光灯的照射范围才能停车，就有发生碰撞的风险。"},"2.2.03-025":{"q":"您在高速公路上有雾条件下行驶。您的可视范围小于50米。您允许以多快行驶？","o":[],"c":"您只允许以能在自身视野范围内停住的车速行驶。以50 km/h的车速正常制动时，停车距离为40米。因此，您在此处不得以超过50 km/h的车速行驶。\n\n停车距离 = 反应距离 + 制动距离\n[（车速 km/h : 10）×3] + [（车速 km/h : 10）×（车速 km/h : 10）]"},"2.2.03-026-M":{"q":"转弯后您最高允许以多快行驶？","o":[],"c":"除另有标示外，市区内的最高车速为50 km/h。之前优先道路上的30 km/h在此处不再适用。"},"2.2.03-101":{"q":"装有防滑链的机动车最高允许以多快行驶？","o":[],"c":"使用防滑链时，最高车速为50 km/h。如果超过该车速，行驶稳定性会受损，道路也会被损坏。"},"2.2.03-104":{"q":"在城镇外每个方向标有一条车道的道路上，您驾驶汽车最高允许以多快行驶？","o":[],"c":"对于总质量不超过3.5吨且不带拖车的车辆，最高限速为100 km/h。"},"2.2.03-105":{"q":"在城镇外每个方向标有一条车道的道路上，您驾驶允许总质量3.0吨的卡车最高允许以多快行驶？","o":[],"c":"对于总质量不超过3.5吨且不带拖车的车辆，最高限速为100 km/h。"},"2.2.03-106":{"q":"允许总质量3.0吨且带拖车的卡车在高速公路上最高允许以多快行驶？","o":[],"c":"对于总质量不超过3.5吨且不带拖车的车辆，最高限速为80 km/h。"},"2.2.03-107":{"q":"使用冬季轮胎（M+S）行驶时，您尤其必须记住什么？","o":["不得超过这些轮胎的最高允许速度","您不得以超过80 km/h的速度行驶","适用装有防滑链汽车的最高允许速度"],"c":"汽车驾驶员在使用冬季轮胎行驶时必须遵守最高限速。该车速取决于冬季轮胎的类型，可能超过80 km/h。"},"2.2.03-108":{"q":"在主干道上，您驾驶总质量5.5吨的卡车并拖挂总质量2吨的拖车，最高可以以多快行驶？","o":[],"c":"您的卡车允许总质量为5.5 t，并带有2 t的拖车，在高速公路上您最高只允许以60 km/h的车速行驶。"},"2.2.03-109":{"q":"您驾驶一辆汽车列车。它由一辆最大允许质量不超过3.5吨的机动车和一辆无100 km/h许可的拖车组成。您在高速公路上的最高车速是多少？","o":[],"c":"对于总允许质量不超过3.5吨且带拖车的车辆组合，在城镇外的最高车速为80 km/h。"},"2.2.03-110":{"q":"您驾驶一辆汽车列车。它由一辆允许最大质量不超过3.5吨的机动车和一辆获准最高100 km/h的拖车组成。在联邦公路（非快速公路）上的最高限速是多少？","o":[],"c":"联邦道路上的最高允许车速为80 km/h。只有当您的拖车具备必要的许可时，您才允许在高速公路和指定的快速路上以100 km/h的车速行驶。"},"2.2.03-202":{"q":"在高速公路上，您驾驶允许总质量4.0吨的卡车最高允许以多快行驶？","o":[],"c":"您的卡车允许总质量为4.0 t，在高速公路上您不得以超过80 km/h的车速行驶。"},"2.2.03-205":{"q":"在城镇外（非高速公路或仅机动车专用快速路）以非定线运营方式驾驶客车，您最高允许以多快行驶？","o":[],"c":"即将推出……"},"2.2.03-206":{"q":"在高速公路上，您驾驶带行李拖车的“100 km/h客车”（Tempo-100-Bus）最高允许以多快行驶？","o":[],"c":"即将推出……"},"2.2.03-208":{"q":"在高速公路上，您驾驶“100 km/h客车”（Tempo-100-Bus）最高允许以多快行驶？","o":[],"c":"即将推出……"},"2.2.03-209":{"q":"在没有标线的仅机动车专用快速路上，您驾驶“100 km/h客车”（Tempo-100-Bus）最高允许以多快行驶？","o":[],"c":"即将推出……"},"2.2.03-210":{"q":"在城镇外，当座位不足以容纳所有乘客时，您驾驶客车最高允许以多快行驶？","o":[],"c":"即将推出……"},"2.2.03-301":{"q":"在高速公路上，您驾驶允许总质量40吨的卡车最高允许以多快行驶？","o":[],"c":"您的卡车为40 t，在高速公路上您必须以80 km/h的车速行驶。"},"2.2.03-303":{"q":"您在一主干道上使用近光灯行驶。您必须能在什么距离内停车？","o":["- 近光灯","- 远光灯","- 示宽灯"],"c":"您只允许以能在可判断的路段内停住的车速行驶。在这种情况下，这相当于您近光灯的照射范围。"},"2.2.03-304":{"q":"哪些车辆在高速公路上适用推荐车速？","o":["- 汽车","- 摩托车","- 总质量超过3.5吨的卡车"],"c":"在高速公路上，所有轿车以及最大总质量不超过3.5 t的车辆都必须遵守高速公路限速。即使交通状况良好，也不建议超过该限速。"},"2.2.03-305":{"q":"在哪些道路上适用130 km/h的推荐车速？","o":["高速公路","城镇外、每个方向有独立车道的机动车道","城镇外、每个方向至少标有两条车道的机动车道"],"c":"在高速公路以及城镇外车道在结构上分离的道路上，适用130 km/h的建议车速。不过，您仍必须保持足够距离，以便随时停车。"},"2.2.04-001":{"q":"您以80 km/h跟在机动车后方行驶。您必须遵守的最小安全距离是多少？","o":["“2秒距离”","“1秒距离”","15米的距离"],"c":"跟在另一辆车后面行驶时，您需要保持所谓的“两秒距离”，以便能及时停车。在车速80 km/h时，这约相当于40米。"},"2.2.04-002":{"q":"您在城镇车流中行驶于干燥车道，车流速度为50 km/h。您必须与前车保持的最小安全距离是多少？","o":["15米或约3个车长","10米或约2个车长","5米或约1个车长"],"c":"在市区以及城市交通中，根据判例，较短的距离比城镇外更合理。在专注驾驶且路况良好的情况下，一般“两秒距离”可以缩短为一秒。车速50 km/h时，这约为15米。也就是大约三个车身长度。"},"2.2.04-003":{"q":"在城镇外，通常应与前车保持的最小距离是多少？","o":["车速表读数（以米计）的一半","车速表读数（以米计）的五分之一"],"c":"在城镇外，与前车的距离必须至少为其车速数值的一半（以米计），也就是说车速100 km/h时距离应约为50米。就连所谓的“两秒距离”在法律上也是被认可的。"},"2.2.04-004":{"q":"以100 km/h行驶时，您应与前车保持的最小安全距离是多少？","o":[],"c":"为了能够及时制动，您应当保持以米计等于车速数值一半的安全距离。"},"2.2.04-005":{"q":"在城镇外行驶时，您与前方车辆之间应保持的最小安全距离是多少？","o":["车速表读数（以米计）的一半","车速表读数（以米计）的三分之一","车速表读数（以米计）的五分之一"],"c":"在城镇封闭区域外，StVO（道路交通条例）规定了2秒的安全距离。这又相当于“车速表数值一半”的经验法则。\n注意：这些规则只适用于干燥路面。在下雨、下雪和路面结冰的情况下，安全距离应至少加倍。"},"2.2.04-101":{"q":"您在城镇外一条每个方向仅标有一条车道的道路上驾驶汽车并拖挂房车拖车（汽车列车长度超过7米）。您必须记住什么？","o":["通常，与前车的距离必须大到足以让超车的汽车并入","为最佳利用交通空间，与前车的距离不得超过您汽车列车的长度","您不得以超过60 km/h的速度行驶"],"c":"长度超过7米的列车在城镇外必须与前车保持至少等于其车速数值一半（以米计）的距离。对于带拖车的轿车，城镇外适用80 km/h的最高车速。这将相当于40米的距离。这样，超车的车辆才能回到车道内。"},"2.2.04-102":{"q":"在城镇外每个方向仅一条车道的道路上，带拖车的汽车何时必须与前车保持足够距离，以便超车车辆能并入？","o":[],"c":"StVO 第4条第2款：“受特殊限速约束的机动车以及长度超过7米的车辆，必须与前方的其他车辆保持固定距离，以便其他超越车辆能够超车。……”"},"2.2.04-103":{"q":"您在高速公路上驾驶总质量超过3.5吨的卡车。您的车速超过50 km/h。为什么您必须与前车保持50米的最小距离？","o":["- 我正在降低追尾碰撞的风险","- 那样有更多的反应时间","- 将更快到达目的地"],"c":"如果前方的交通参与者强烈制动，您就有更多时间作出反应，从而降低碰撞风险。最小距离并非用于此目的。"},"2.2.04-104":{"q":"您在高速公路上以超过50 km/h的速度驾驶长途客车。为什么您必须与前车保持50米的最小距离？","o":["- 我正在降低追尾碰撞的风险","- 那样有更多的反应时间","- 将更快到达目的地"],"c":"即将推出……"},"2.2.04-105-M":{"q":"您驾驶一辆拖着房车的汽车。关于您与前车的距离，什么是正确的？","o":["- 是适当的，因为超车车辆能在我前方并入车道","- 与超车车辆的距离必须在它并入车道后重新建立","- 过大，因为它超过我汽车列车长度的许多倍"],"c":"作为规则，与前车的距离必须足够大，以便超车车辆能够超车。超车之后，与前车的距离应重新调整，因为该距离不应大于您车辆的长度。"},"2.2.04-106":{"q":"您驾驶一辆载重很大的汽车。为什么您应与前车保持更大的安全距离？","o":["- 制动距离可能延长","- 汽车的操控性可能改变","- 我的反应时间可能变长"],"c":"额外的重量会改变汽车的行驶特性。制动器承受更大的负荷。这可能降低制动力，从而延长制动距离。"},"2.2.04-107":{"q":"从汽车列车的什么长度起，您必须在城镇外与前车保持足够距离，以便超车车辆能并入？","o":[],"c":"如果车辆组合的长度超过7米，您在城镇外必须与前车保持更大的距离。这样超车车辆就有机会并入到您前方。"},"2.2.04-204":{"q":"您在城镇外一条每个方向仅一条车道的道路上驾驶客车。作为规则，您必须与前方行驶的车辆保持什么距离？","o":["距离必须足够让超车车辆并入","为最佳利用交通空间，距离不得超过10米"],"c":"即将推出……"},"2.2.04-205":{"q":"您在高速公路上以约80 km/h行驶。您必须与前方行驶的车辆保持什么距离？","o":[],"c":"即将推出……"},"2.2.04-207-M":{"q":"关于您与前车之间的距离，这里什么是正确的？","o":["- 与卡车（的距离）是合理的，因为[黄色]汽车可能在我前方并入车道","- 与[黄色]汽车的距离必须在它并入车道后重新建立","- 与卡车的距离过大，因为它超过我客车长度的许多倍"],"c":"该距离是合适的，因为超车的汽车可以并入到您前方。一旦超车的汽车并入到您前方，您就必须与它保持足够的距离。"},"2.2.04-302":{"q":"您在城镇外以60 km/h驾驶总质量7吨的车辆。何时您必须保持足够大的距离，使超车车辆能并入车道？","o":["如果我行驶方向只有一条车道","如果禁止超车","如果我行驶方向有多于一条车道"],"c":"如果您的行驶方向只有一条车道可用，您应当保持足够大的距离，以便超车车辆能够并入。"},"2.2.04-303":{"q":"您在高速公路上以80 km/h驾驶卡车（总质量12吨）。您必须确保什么？","o":["- 我与前车之间的距离至少为50米","- 我的车速不增加","- 我与前车之间的距离等于车速表读数（以米计）的一半"],"c":"您的卡车（允许总质量12 t）在高速公路上以80 km/h的车速行驶时，最小距离应为50米。也请确保您的车辆不会加速。"},"2.2.04-304":{"q":"城镇外的一条道路在行驶方向上只有一条车道。哪些卡车必须与其前方车辆保持足够大的距离，使超车车辆能并入车道？","o":[],"c":"允许总质量超过3.5 t的卡车应当与前车保持足够大的距离，以便超车车辆能够并入。"},"2.2.04-305":{"q":"您在高速公路上以60 km/h驾驶总质量4吨的卡车。您必须与前车保持什么距离？","o":[],"c":"当您在高速公路上超越一辆最大允许质量为4 t、正以60 km/h行驶的车辆时，您应当至少保持50米的距离。"},"2.2.04-306":{"q":"在城镇外时，哪些车辆必须与其前方车辆保持足够大的距离，使超车车辆能并入车道？","o":["总质量超过3.5吨的卡车","长度超过7米的汽车列车","总质量不超过3.5吨的卡车"],"c":"这里所说的是所谓的并入距离（Einscherabstand）。这适用于最大允许质量超过3.5 t的卡车以及长度超过7 m的车辆组合。对于总质量不超过3.5吨的机动车，在城镇外一般不需要这样做。"},"2.2.04-307":{"q":"您在城镇外一条每个方向仅一条车道的道路上驾驶汽车列车。您通常必须与前车保持什么距离？","o":["- 必须大到足以让超车车辆并入车道","- 不得超过10米，以便最佳利用交通空间","- 必须大到足以让至少两辆超车车辆并入车道"],"c":"您所应保持的距离必须足够大，以便超车车辆能够并入。"},"2.2.05-005":{"q":"您在城镇外的道路上以100 km/h行驶。您前方一辆卡车以70 km/h行驶。当您开始超车操作时，您与道路坡顶的最小距离是多少？","o":["800 m","200 m","400 m"],"c":"超车路程的经验法则根据车速、超车时间和车辆长度计算。公式为 s = v1 / (v1−v2) * (l1+l2+sv+sh)。V1/ (V1-V2)) 乘以 L。V1 =100 km/h，V2 = 70 km/h，L = 2 乘以 50 m 安全距离加上车辆长度。卡车12.5 m加轿车4.5 m = 17 m。L = 117 m。100 km/h 除以 30 km/h 乘以 117 m = 389.9 m，也就是约400 m的超车路程。在视线不清的路段，这必须加倍。您必须距离坡顶至少800米。"},"2.2.05-006":{"q":"雾使能见度限制在约50米。在这种情况下，对总质量超过7.5吨的车辆适用什么？","o":["在城镇外的道路上禁止超车","在所有道路上允许的最高车速为50 km/h","在高速公路上允许超车"],"c":"在能见度受限的情况下，您在所有道路上的最高车速都不得超过50 km/h。在城镇外，禁止您超车。请根据情况（雾）调整您的驾驶方式。"},"2.2.05-007":{"q":"您在城镇外的道路上行驶并想超越一辆汽车。超车操作最迟应在哪里完成？","o":["在实线（车道边界线）开始之前","在针对所有类型车辆的禁止超车标志之前","在车道标线开始之前"],"c":"您最迟必须在超车限制开始之前完成超车过程。超车限制由交通标志或实线标线表示。虽然您不得压越实线行驶，但为了超车，您可以压越虚线行驶。"},"2.2.05-010":{"q":"出于什么原因您现在必须切换到右侧车道？","o":["因为关于除非超车等情况下使用右侧车道的规则","因为红色汽车","因为拖拉机"],"c":"在您超越那辆绿色厢式货车之后，由于靠右行驶的义务，您必须再次向右并入。但即使是在您车道上与您会车的那辆红色汽车，也必须重新驶回到右侧车道。"},"2.2.05-011":{"q":"在这种情况下正确的做法是什么？","o":["我中止超车并驶入右侧车道","我加速并继续超车","我以不变的车速继续超车"],"c":"如果您打算超车，可以驶上对向交通的车道。要超车，您必须把车速提高到超过允许的130 km/h，而这在这种情况下是不允许的。您必须取消超车操作并驶入右侧车道。"},"2.2.05-012":{"q":"现在您必须做好什么准备？","o":["- 蓝色汽车开始超车","- 绿色卡车的超车操作需要更长时间完成","- 白色卡车加速"],"c":"您可能必须做好现在无法超车的准备，因为其他交通参与者已经处于超车操作之中。不要仓促行事，只为了在允许的路段内完成超车操作。实线标线表示超车限制，等同于“禁止超车”标志。"},"2.2.05-013":{"q":"在这种情况下您必须特别密切关注谁？","o":["- 骑行者","- 红色汽车","- 白色卡车"],"c":"在这种情况下，您作为汽车驾驶员必须注意从右侧向您驶近的骑车人。骑车人可能驶上卡车前方的道路，造成危险局面。"},"2.2.05-014-M":{"q":"为什么您在此必须减速？","o":["- 摩托车","- 拖拉机","- 运动型多用途车（SUV）"],"c":"正在超车的摩托车手对您构成危险。他在超车过程中会与您在您的车道上相遇。您应当减速并避免碰撞。其他驾驶员的行为是符合交通规则的。"},"2.2.05-015":{"q":"您驾驶总质量超过3.5吨的卡车。您现在应该怎么做？","o":["我放弃超车","我减速","我加速"],"c":"您应当保持正确的距离，不要超车，并降低车速。"},"2.2.05-016-M":{"q":"您想超车。您现在应该怎么做？","o":["我暂不超车，因为[蓝色汽车]可能超车","如果[蓝色汽车]超车，我紧跟其后","我在一次超车操作中超越所有车辆"],"c":"您必须等您前方行驶的驾驶员完成超车后再超车。实线标线和禁止超车标志都表示超车限制。而虚线（引导线）则表示不禁止超车。"},"2.2.05-017":{"q":"现在正确的做法是什么？","o":["- 不要超越有轨电车","- 从右侧超越有轨电车","- 从左侧超越有轨电车"],"c":"请以这样的方式规划您的超车操作：使其在实线开始之前完成。实线以及相应的交通标志表示您在此处不得超车。"},"2.2.05-018":{"q":"您想超越一辆带拖车的卡车。此时您必须注意什么？","o":["由于拖车，所需的超车距离显著增加","卡车拖车列车的外部车身可能遮挡前方的车辆","只有当您正好在卡车拖车列车后方时才能驶出车道超车"],"c":"如果您想超越一辆带拖车的卡车，您应当考虑到由于拖车而需要更长的超车距离（它更长），以及卡车的车辆轮廓可能遮挡前方的车辆。"},"2.2.05-019":{"q":"为什么您现在不允许超越前方行驶的客车？","o":["因为客车的危险警示灯已开启","因为摩托车","因为缺少路面标线"],"c":"那辆公交车已开启警示灯，并且仍在驶向公交车站。在这种情况下，不允许超越公交车。此外，您后方的那辆摩托车已经开始了超车。"},"2.2.05-020-M":{"q":"您想超越前方行驶的车辆。您要超车必须满足什么？","o":["- 大幅提高车速","- 使用转向灯示意我超车的意图","- 观察我后方和侧方的交通"],"c":"请及时向其他交通参与者表明您将驶入左侧或中间车道。每次超车都必须通过打转向灯来示意。在您观察了后方和侧方交通并确认左侧车道空闲之后，必须按下转向指示灯。然后您就可以变道，并以大幅提高的车速超越较慢的车辆。\n请务必注意不要超过允许的最高车速。"},"2.2.05-021-M":{"q":"现在正确的做法是什么？","o":["我保持在拖拉机后方","我预料拖拉机可能驶离道路","我遵从拖拉机驾驶员用转向灯发出的超车示意"],"c":"那辆拖拉机似乎想向右驶入土路。请留在拖拉机后方，等它驶离。超越它是危险的，因为其后部安装的农具可能偏转。"},"2.2.05-102-M":{"q":"您想超越[蓝色汽车]。正确的做法是什么？","o":["- 以明显更高的车速超车","- 在保持现有车速的情况下超车","- 不要超车，因为一辆摩托车正在盲区中行驶"],"c":"请等待那辆自行车离开盲区。请注意，正在超车的汽车驾驶员必须以比被超车驾驶员更高的车速行驶。如有必要请加速，并在超车限制（例如实线）生效之前完成您的超车过程。"},"2.2.05-103-M":{"q":"什么可能使这种情况变得危险？","o":["迎面来车","[红色汽车]","拖拉机"],"c":"从后方驶近的汽车驾驶员试图在转弯前超越您，尽管他/她看不清弯道。如果在这种情况下有对向交通驶来，可能导致对向交通和超车驾驶员作出危险的闪避操作。路旁的那辆拖拉机不构成危险。"},"2.2.05-104":{"q":"您在高速公路上驾驶总质量超过7.5吨的机动车。大雪使能见度降至50米以下。您必须怎么做？","o":["我不得使用最左侧车道","我不得以超过50 km/h的速度行驶","我必须在下一个出口驶离高速公路"],"c":"您的车辆最大允许总质量超过7.5 t，因此您不得在最左侧车道上行驶，因为该车道是供较快的汽车超车用的。您不得以超过50 km/h的车速驾驶您的车辆。即使下雪，您也可以继续在高速公路上行驶。"},"2.2.05-202":{"q":"您在城镇外行驶。大雨使能见度降至约50米。在这种情况下适用什么？","o":["对允许总质量超过7.5吨的机动车禁止超车","允许的最高车速为50 km/h","必须开启后雾灯"],"c":"在此处同样如此（因大雨能见度降低至 50 m 时），限速为 50 km/h。允许总质量超过 7.5 t 的机动车禁止超车。后雾灯不必开启。"},"2.2.05-401":{"q":"您驾驶一辆农业机械。您后方形成了一列汽车。什么是正确的？","o":["在合适的地方减速或停车等待，以便让后方跟行的汽车超车","开启危险警示灯以表示无法超车","农业机械无须让较快的车辆超车"],"c":"即将推出……"},"2.2.05-402-M":{"q":"您现在应该怎么做？","o":["我驶入右侧的公交车站并停在那里","我加速","我保持车速并继续行驶"],"c":"在这种情况下，您应驶入公交车站，让后面的车超越您。"},"2.2.06-001":{"q":"现在正确的做法是什么？","o":["我在瓶颈路段前停车等待，直到迎面汽车通过","我谨慎地在迎面汽车和工地护栏之间驶过瓶颈路段","我示意迎面汽车的驾驶员应更靠近车道边缘行驶"],"c":"瓶颈路段位于您所在的车道内。因此，您必须在瓶颈路段前停车，等待对向来车通过后再继续行驶。"},"2.2.06-101-M":{"q":"在此正确的做法是什么？","o":["我减速并等待","我在右侧已等待的车辆后方排队","我以降低的车速继续行驶"],"c":"与自行车的距离不够。请停车等待，直到骑车人通过瓶颈路段。只有这样才能确保您不会危及骑车人。"},"2.2.07-001":{"q":"您正接近“红灯”信号灯。所有车道中都有几辆汽车在等待。您会怎么做？","o":["在您的车道内在最后一辆车后方等待","从右侧驶过等待的汽车并前进到停止线","从左侧驶过等待的汽车并前进到停止线"],"c":"您应始终在本车道最后一辆车后面排队等候，不要试图从任一侧跨过其他车辆。"},"2.2.07-002":{"q":"哪些机动车在城镇内可以自由选择车道？","o":[],"c":"在德国适用靠右行驶的规定。在城镇内道路，总质量不超过 3.5 t 的车辆不受靠右行驶规定的约束，可以自由选择车道。"},"2.2.07-004":{"q":"现在正确的做法是什么？","o":["我驶入右侧车道","我保持在中央车道","我驶入左侧车道"],"c":"在德国，您必须靠右行驶。由于您前方没有比您行驶更慢的车辆，您必须驶入右侧车道。一旦出现较慢的车辆，您可以驶回中间车道或左侧车道超越它们。"},"2.2.07-005":{"q":"可能如何出现危险情况？","o":["- 黄色卡车","- 绿色卡车","- 前方的汽车"],"c":"黄色卡车快速的驾驶方式表明，它也会超越其前方的蓝色卡车。您的车速比这些卡车更快。您无法向左避让，因为左侧车道正有一辆车在您后面。如果黄色卡车向外并线，您必须紧急制动。"},"2.2.07-006":{"q":"您现在应该怎么做？","o":["我让蓝色汽车在我前方合流","我加速","我立即从左侧车道变更到中央车道"],"c":"由于加速车道右侧的汽车驾驶员正在加速，您应让其能够汇入车流。放弃您的优先通行权并降低自己的车速。您不能变更到左侧车道，因为那里有车辆驶来。"},"2.2.07-007":{"q":"您应该怎么做？","o":["我保持在中间车道并减速","我驶入右侧车道并减速","我驶入左侧车道并超越我前方的红色汽车"],"c":"请留在中间车道并减速。前方车辆很快也会减速，以便让左侧车道的车辆汇入车流，因为该车道即将结束。您无法向左变道，变更到右侧车道也同样过于危险。"},"2.2.07-008":{"q":"正确的做法是什么？","o":["我减速","我不改变车速继续行驶","我驶入右侧车道"],"c":"您行驶在中间车道，在这种情况下您必须留在该车道并降低车速。左侧车道的驾驶员行驶得更慢。您不得从右侧超越它。您不能变更到右侧车道，那里有车辆。"},"2.2.07-009":{"q":"在这种情况下您必须预料到什么？","o":["- 灰色汽车将驶入中间车道","- 黄色卡车将在我前方驶出车道超车","- 灰色汽车将保持在右侧车道"],"c":"由于该车辆从右侧非常快速地驶上高速公路，您必须预料到它会变更到中间车道。卡车保持其速度和距离这一事实也强化了这种判断。"},"2.2.07-010":{"q":"正确的做法是什么？","o":["我降低车速，保持在中间车道","我保持车速，保持在中间车道","我保持车速并驶入右侧车道"],"c":"一辆汽车在您前方行驶，同时从右侧有一辆车驶上高速公路的主车道。很明显，左侧车道行驶的汽车速度比您慢。由于只允许从左侧超车，您必须减速并降低车速。"},"2.2.07-011":{"q":"你在一条同向有多条标记车道的道路上行驶。何时应采用交替并线（拉链式）程序？","o":["当一条车道终止时","当某条车道因障碍物而不能持续通行时","当高速公路上的汇入车道结束时"],"c":"当某条车道无法继续使用时，应采用拉链式合流（交替通行）。高速公路除外。"},"2.2.07-012-M":{"q":"在此情形下，关于使用应急车道，哪项正确？","o":["必须像右侧车道一样使用","只能在车辆抛锚时使用","只能由卡车使用"],"c":"该交通标志指示，应急车道应像右侧车道一样使用。"},"2.2.07-013-M":{"q":"在此情形下，关于使用应急车道，哪项正确？","o":["只能在车辆抛锚时使用","只能由卡车使用","必须与右侧车道同样使用"],"c":"不得常规使用应急车道。只有在发生故障时才可以使用。"},"2.2.07-014-M":{"q":"现在正确的做法是什么？","o":["我降低车速","我让[蓝色]汽车驶到我前方","我加速"],"c":"如果在多车道道路上有一条车道即将结束，必须允许车辆变更到相邻车道。此时重要的是要有预见性地驾驶，以便能够及时对变道作出反应，并在必要时调整自己的车速。"},"2.2.07-201-M":{"q":"对于这条位于城镇内道路之外的道路，适用哪项规定？","o":["执行左转","超车","发生交通拥堵时"],"c":"该交通标志提示您很快需要选择行驶方向。同时，您也会对该路口有一个概念，尤其是转弯轨迹。因此，只有当您想要左转时，才可以使用外侧的左侧车道。"},"2.2.09-001":{"q":"哪些地方禁止掉头？","o":["高速公路","机动车专用快速路","农用或林用道路"],"c":"您不得在高速公路或机动车道上调头。在这两类道路上，也严格禁止倒车行驶。"},"2.2.09-002-M":{"q":"为什么你在左转前必须等待？","o":["摩托车","汽车","自行车"],"c":"作为左转的驾驶员，您通常必须让对向车流优先通过。骑自行车者也享有这一优先通行权。因此，在这种情况下，您必须让摩托车先通过再转弯。它会从右侧经过左转的驾驶员并继续直行。"},"2.2.09-003-M":{"q":"正确的做法是什么？","o":["在[红色]车辆超过我之后","现在，以让出车道","现在，以免后车因我减速而产生误解"],"c":"如果您想左转，而有辆车想从左侧超越您，您必须让它先通过。只有当该车完成超车动作后，您才可以转弯。"},"2.2.09-004-M":{"q":"你想左转。正确的做法是什么？","o":["我在农用道路处停车等待","我加速并迅速完成转弯","我继续行驶，因为此处不能驶离该道路"],"c":"由于您目前正被超越，此时不可能左转。您必须等到超车过程结束后才能左转。"},"2.2.09-005-M":{"q":"在此情形下，为什么你在左转前必须等待？","o":["摩托车","[红色汽车]","[自行车]"],"c":"在这种情况下，您需要等汽车后面的摩托车通过后再左转。"},"2.2.09-006-M":{"q":"在此情形下，正确的做法是什么？","o":["在[红色汽车]超过我之后","现在，以免妨碍我后面的卡车","现在，以免我的迟疑使后车产生不确定感"],"c":"在这种情况下，您应先等摩托车超越您之后再左转。"},"2.2.09-007-M":{"q":"为什么你现在不允许驶离该道路？","o":["[红色汽车]","公共汽车","对向来车"],"c":"红色汽车正在超车，并在您的左侧行驶。为避免碰撞，此时无论如何都不要转弯。请检查您的转向灯是否脏污而因此无法被看到。"},"2.2.09-008-M":{"q":"你想在下一个路口左转。现在正确的做法是什么？","o":["我停在静止车辆的后方等待","我打左转向灯","我小心地从静止车辆的左侧驶过"],"c":"如果您驶过等候的车辆，可能会妨碍对向来车，最糟的情况下会堵住整条道路。因此，请现在就开始打左转向灯，以向其他道路使用者示意您想驶入该路。同时，请留在等候的车辆后面，等到到达该路口时再转弯。"},"2.2.09-009-M":{"q":"你想左转。你应沿哪条行驶轨迹行驶？","o":["中间行驶轨迹","左侧行驶轨迹","右侧行驶轨迹"],"c":"左转时请沿中线行驶。这样您就可以尽可能靠左行驶，而不会驶入对向车道，同时您后面的摩托车可以从右侧经过您。"},"2.2.09-010-M":{"q":"你想左转。你应沿哪条行驶轨迹行驶？","o":["中间行驶轨迹","左侧行驶轨迹","右侧行驶轨迹"],"c":"左转时您应尽可能靠左行驶。但是，您行驶的是一条允许双向骑行的单行道。因此，您不允许靠最左侧骑行，因为可能有骑自行车者迎面而来。所以请沿中线行驶。"},"2.2.09-011-M":{"q":"你想左转。你应沿哪条行驶轨迹行驶？","o":["左侧行驶轨迹","中间行驶轨迹","右侧行驶轨迹"],"c":"如果您想在单行道内左转，应尽可能靠左行驶，因此请沿左侧车道行驶。"},"2.2.09-101":{"q":"倒车时正确的做法是什么？","o":["额外环顾四周，以确保道路区域安全","缓慢且专注地行驶","确保没有人处于我的盲区内"],"c":"倒车时，请向后观察，并通过环顾四周来确保交通区域的安全，专注且缓慢地驾驶，并且出于安全考虑，确保盲区内没有人员。"},"2.2.09-201":{"q":"你驾驶一辆允许总质量超过3.5 t的机动车。在城镇内道路右转时，必须以什么速度行驶？","o":["步行速度","最高20 km/h","最高30 km/h"],"c":"以步行速度行驶，以避免危险和事故。"},"2.2.09-202":{"q":"你的车辆装有倒车摄像头。你想从一条非常繁忙的道路倒车驶入前院。此时你必须注意什么？","o":["我应额外安排一名观察员协助引导我倒车","我还必须直接观察交通状况","我可以仅依靠倒车摄像头"],"c":""},"2.2.09-203":{"q":"在城镇内道路右转时，什么可以降低发生严重事故的风险？","o":["为车辆装备转向辅助系统","右转时以步行速度行驶","快速完成右转以免妨碍其他道路使用者"],"c":""},"2.2.09-204":{"q":"你想把车辆从一块场地倒车驶上道路。你必须做什么？","o":["必要时安排他人为我指挥","让行人优先通行","只使用倒车摄像头"],"c":"要从一处物业倒车驶入道路，仅使用倒车摄像头是不够的。必要时应有人在街上指挥，并牢记行人享有优先权。"},"2.2.09-205":{"q":"右转时，存在因盲区而忽视直行自行车的风险。你如何降低这一风险？","o":["我以短间隔观察后方和侧方的交通","我确保后视镜调节正确","我确保驾驶室内的物品不遮挡视线"],"c":"当公交车或卡车右转时，存在因盲区而忽视直行骑自行车者的风险。为了将风险降至最低，您应短间隔地观察下列和侧向交通，确保后视镜调整正确，并确保没有配件遮挡视线。这样您就能及时发现骑自行车者并避免事故。"},"2.2.09-402":{"q":"你在拖拉机上挂装了向车尾伸出很远的犁。右转时你必须记住什么？","o":["只有当犁摆过时不会对对向来车造成危险时才可转弯","如果犁设有警示板标示，转弯时就不会危及任何人"],"c":"即将推出……"},"2.2.09-403":{"q":"你在拖拉机上挂装了向车尾伸出很远的犁。右转时谁可能受到危险？","o":["跟在你后面、打算超车的车辆","你左侧车道内的车辆","停在右侧的车辆"],"c":"即将推出……"},"2.2.09-405":{"q":"你在拖拉机上挂接了向车尾伸出很远的翻草机。左转时谁可能因此受到危险？","o":["在我右侧并排行驶的车辆","道路右侧的行人","跟在我后方行驶的车辆"],"c":"即将推出……"},"2.2.09-406":{"q":"你驾驶一辆带两节拖车的农用拖拉机，想右转。你必须注意什么？","o":["我右侧是否并排有自行车","转弯时拖车不会危及道路一侧或人行道上的行人","转弯时若须向左大幅甩出，记得开启危险警示灯"],"c":"由于您的农用拖拉机带两辆拖车右转时所需的转弯空间会增大，请确保转弯时不会危及路缘或人行道上的人员，并注意是否有紧挨着您、被盲区遮挡的骑自行车者。"},"2.2.09-407":{"q":"你驾驶拖拉机结束田间作业返回，想驶入一条道路。为避免危险情况，你应注意什么？","o":["保持挡风玻璃清洁","避免在无法从足够距离看到优先通行车辆驾驶员的位置驶入","若视线受限，让他人指挥我驶上道路"],"c":"即将推出……"},"2.2.12-001":{"q":"哪些地方禁止临时停车？","o":["在高速公路和机动车专用快速路停车区之外","在急弯附近或急弯上","在公交车站"],"c":"一般而言，《道路交通法》规定，在停车对其他道路使用者构成危险或危及公共安全与秩序的地方，禁止在交通区域内停车。这尤其适用于在高速公路车道或机动车道上停车。在急弯和视线不良的弯道上同样如此。"},"2.2.12-003":{"q":"哪些地方禁止停放车辆？","o":["在狭窄道路上、正对车道出入口的位置","在出租车候客站","在人行横道的紧后方"],"c":"根据《道路交通法》，在停放车辆会妨碍其他道路使用者，或无法再保证公共秩序与安全的所有地点，一律禁止停车。例如，禁止在出租车候客站、狭窄车道、物业出入口前，以及在人行横道及其前 5 m 范围内停车。"},"2.2.12-005":{"q":"在这个停车位上谁有优先权？","o":["白色车辆，因为它先到达该停车位","谁都没有，两位驾驶员应协商","我，因为我是正向驶入停车的"],"c":"先到达停车位的车辆始终享有优先权。即使车辆只是为了倒车入位或进行其他有利于停入该车位的操作而驶过该停车位，也依然享有优先权。车辆在该停车位等候时，优先权同样保持。"},"2.2.12-006":{"q":"停放摩托车时你必须考虑什么？","o":["不得妨碍任何人","不得翻倒","必须停放在人行道上"],"c":"摩托车不得妨碍或危及任何人。请确保摩托车停放安全且节省空间。"},"2.2.12-007":{"q":"何时允许将两轮车停放在人行道上？","o":["当交通标志指示允许时","如果人行道宽度至少2.0 m","如果没有其他选择"],"c":"原则上，车道应用于停放车辆。摩托车可以在允许汽车停放的任何地方停放。一般而言，除交通标志允许外，不允许将摩托车停放在人行道上。"},"2.2.12-008":{"q":"停放两轮车时你应注意什么？","o":["我不应将两轮车停放在松软的地面上","只有在有相应标志指示时，我才可将两轮车停放在人行道上","停放两轮车时，我可免除展示停车计时盘的义务"],"c":"当您停放摩托车或踏板车时，适用与汽车驾驶员相同的规则和禁令。这意味着您不得简单地将摩托车或踏板车停放在人行道上。您必须像汽车车主一样将车停在道路上。只有将摩托车或踏板车停放在划定的停车位内，或相应的交通标志允许时，才允许停放在人行道上。此外，您还应始终注意停放摩托车的地面；如果地面太软或太不平整，您的摩托车可能很快倒下并造成其他危险。"},"2.2.12-101-B":{"q":"两辆车都想在此停放。哪辆车优先？","o":["红色汽车","白色汽车"],"c":"在这种情况下，红色汽车享有优先通行权。它先到达了停车位。即使车辆只是为了倒车入位或进行其他有利于停入该车位的操作而驶过该停车位，也依然享有优先权。"},"2.2.12-102":{"q":"机动车的允许总质量最高为多少时，才可停放在特别指定的人行道上？","o":[],"c":"允许总质量不超过 2.8 t 的车辆可以停放在特别标记的人行道上。"},"2.2.12-104":{"q":"如果车辆会遮挡交通信号灯，车辆在信号灯前方必须至少留出多少距离？","o":[],"c":"必须保持至少 10 m 的最小距离，以免遮挡对信号灯的视线。"},"2.2.12-105":{"q":"在城镇内道路，允许总质量超过2 t的拖车在周日、法定节假日以及22:00至6:00之间通常允许停放在哪些地方？","o":["工业区","纯居住区，在特别指定的停车位上","专供休养用途的特殊区域，在足够宽的道路上"],"c":"允许总质量超过 2 t 的拖车，可以停放在带有相应标记停车位的商业区和居住区。在封闭区域以及用于休闲目的的特殊区域内，从 22:00 到 6:00 以及周日和公众假日，禁止常规停车。"},"2.2.12-106":{"q":"停放无牵引车的拖车时，你必须记住什么？","o":["不得在公共道路上停放超过2周","可在特别指定的停车位上停放超过2周","可在合适的应急车道上无限期停放"],"c":"请注意，如果拖车未连接到牵引车，您不得将其停放在常规停车位上超过两周。顺便一提，应急车道也同样适用。相应标记的停车场不受此规定限制。"},"2.2.12-107-M":{"q":"你想在道路右侧边缘停车。在此情形下你应怎么做？","o":["即使我有优先权，我也放弃该停车位","我现在就停车，因为我有优先权"],"c":"您先发出了信号，因此对该停车位享有优先权。为避免冲突，您仍应让出该停车位。"},"2.2.12-108-M":{"q":"你想在道路右侧边缘停车。在此情形下谁有优先权？","o":["[蓝色]汽车有优先权","我有优先权","谁都没有优先权。我们必须协商"],"c":"在您前方停下的汽车先发出了信号，因此对该停车位享有优先权。如果您现在停车，可能会发生碰撞。"},"2.2.12-109-M":{"q":"你想在道路右侧倒车入库停车。在此情形下哪项正确？","o":["在驶入车位前，我密切观察对向来车","我预料到可能有车辆驶出停车位","我开启危险警示灯"],"c":"停车时，您始终必须注意对向来车和后方来车，因为您在打方向时可能会离开自己的车道，从而危及其他道路使用者。同时也要注意是否有其他车辆想要驶离其停车位，以避免事故。"},"2.2.12-201":{"q":"在城镇内道路，允许总质量超过7.5 t的机动车在周日、法定节假日以及22:00至6:00之间通常允许停放在哪些地方？","o":["疗养地和医院区域，在特别指定的停车位上","工业区","纯居住区，在足够宽的道路上"],"c":"在居住区，您在这些时段停车不会交到很多朋友。（指噪音）请停放在工业区或温泉疗养区、医院区域指定的停车位内。"},"2.2.12-202":{"q":"在城镇内道路，固定线路公共汽车在周日、法定节假日以及22:00至6:00之间通常允许停放在哪些地方？","o":["工业区","任何公交车站","纯居住区"],"c":"即将推出……"},"2.2.12-203":{"q":"在哪个标志前，如果你的车辆会遮挡它，你必须保持至少10 m的距离？","o":["斜十字标志（铁路道口圣安德鲁十字）","停车让行标志","禁止停车标志"],"c":"在诸如斜十字（圣安德鲁十字）、信号灯或“停车！让横向交通先行”标志等标志前，您至少必须保持 10 m 的距离。当您的车辆会遮挡这些标志时，尤其需要如此。例如，您可以在停车标志前停车。但在其后方，则禁止停车。"},"2.2.12-204":{"q":"你想在车行道右侧边缘停放车辆。你的车辆与实线车道边界线之间的法定最小距离是多少？","o":[],"c":"如果停车时保持距车道边界线至少 3 m 的最小距离，停放的车辆就不会构成障碍。"},"2.2.13-001":{"q":"哪些地方停放车辆时必须使用停车计时盘？","o":["在故障的停车收费表处","在交通标志规定的地方","在禁止停放区域"],"c":"凡交通标志有规定之处，汽车驾驶员必须使用停车计时牌。当停车收费表故障导致无法取得有效的停车票据时，也使用停车计时牌。对于有限的禁止停留规定，使用停车计时牌并不使您有权在此停车超过三分钟。"},"2.2.13-002":{"q":"停车收费表上的时间尚未用完。你该怎么做？","o":["不投币，直接使用收费表上剩余的时间","不使用收费表上剩余的时间","只有在使用停车计时盘时才使用收费表上剩余的时间"],"c":"如果停车收费表尚未到期，您可以使用剩余的停车时间，并在剩余时间内免费将车辆停放在该停车场。此时您不需要停车计时牌。"},"2.2.13-003":{"q":"你在10:40驶入一个使用停车计时盘可停放2小时的区域。你必须把停车计时盘拨到什么时间？","o":["11:00","12:40","13:00"],"c":"停车计时牌上的指针应调到停车时间之后的下一个半小时刻度。如果您在 10:40 到达，指针应指向 11:00。此时停车时长无关紧要。"},"2.2.13-004":{"q":"你想在一个设有停车票机的停车场停放车辆。你必须记住什么？","o":["将有效停车票放置在车内，使其从车外容易读取","不要超过停车票上标明的停车时间","使用停车计时盘时从不需要停车票"],"c":"汽车驾驶员必须将有效的停车票据放置在车内，使其从外部可见。避免超过票据上打印的停车时间（该票据也称为停车票）。只有在停车收费表故障时，用停车计时牌代替停车票据才有效。"},"2.2.13-101":{"q":"何时你可以停放在停车收费表处而不启动它？","o":["为了让人员上下车","为了装卸货物","为了快速购物"],"c":"田地作业后，必要时应清洁照明和信号装置。在进出处以及装卸货期间，无需监控停车时间。在缓慢驶近优先通行道路时，道路必须有足够的视野。"},"2.2.14-001":{"q":"你必须如何防止摩托车被他人擅自使用？","o":["拔下点火钥匙","锁住转向","挂入最高挡"],"c":"为防止他人使用您的摩托车，请拔下点火钥匙并锁住转向。"},"2.2.14-002":{"q":"你想用侧撑支起停放摩托车。你必须考虑什么？","o":["侧撑下方的地面必须坚实","必须将侧撑完全展开到终点位置","你只应在坡道向上的一侧停放摩托车"],"c":"为防止您的摩托车倒下，请确保地面坚实并能承受摩托车的重量，并且将侧支架完全扳起到止挡位置。"},"2.2.14-003":{"q":"你想用主撑支起停放摩托车。你必须考虑什么？","o":["主撑下方的地面必须坚实","你只可用主撑短时间停放摩托车"],"c":"为防止您的摩托车倒下，请确保地面坚实并能承受摩托车的重量。您可以这样短时间或长时间停放您的车。"},"2.2.14-004":{"q":"不应将摩托车（用主撑或侧撑）停放在哪些地方？","o":["松软地面上","停放地面为陡峭下坡处","坚实地面上"],"c":"为防止您的摩托车倒下，请确保地面坚实并能承受摩托车的重量。同时请确保地面不要向下倾斜太陡，否则会使主支架或侧支架不稳固并有倾倒的风险。"},"2.2.14-005":{"q":"停放摩托车时你必须采取哪些预防措施？","o":["停放在坚实的地面上","拔下点火钥匙","锁住车把"],"c":"您必须通过拔下点火钥匙并锁住车把/转向来确保他人无法使用您的摩托车。同时请确保地面坚实，以免摩托车倒下。"},"2.2.14-006":{"q":"你想停放摩托车。你必须考虑什么？","o":["停放地面必须坚实","如果挂入挡位，你可以把摩托车靠在路灯杆上","必须开启近光灯"],"c":"停车时，为防止您的摩托车倒下，请确保地面坚实并能承受摩托车的重量。"},"2.2.14-008":{"q":"你如何防止摩托车被未经许可使用？","o":["拔下点火钥匙","锁上转向锁","断开蓄电池"],"c":"转向锁在发生未经授权的进入时可防止转向。拔下点火钥匙后发动机无法启动。"},"2.2.14-009":{"q":"使用侧撑时你必须注意什么？","o":["停放处的坡度","地面的特性","起步前侧撑已完全收起"],"c":"如果侧支架未完全收起，转弯时可能导致摔倒。如果坡度太大，摩托车可能向前滑动，因为侧支架会自行折回。如果地面太软，摩托车可能会下沉直至倒下。"},"2.2.14-010":{"q":"使用侧撑时应注意什么？","o":["尽可能不要将摩托车停放在坡道上","侧撑应完全展开","侧撑开关可防止你在侧撑展开的情况下起步"],"c":"如果侧支架仍然撑开而您挂挡，侧支架开关会自动关闭发动机。侧支架开关是一种安全措施，可防止您在侧支架撑开的情况下骑走。侧支架是为停放摩托车而设计的。停车时尽量避免坡道。请始终确保您的摩托车稳固，并将侧支架完全撑开，以避免危险和损坏。"},"2.2.14-101":{"q":"你必须如何防止车辆被盗？","o":["拔下点火钥匙、锁上转向锁并关闭车窗","锁上车门和后备箱","接合差速锁"],"c":"为防盗，您必须先关闭所有车窗和车门。无论如何都必须拔下点火钥匙。将方向盘锁锁入到位，以额外保护汽车。"},"2.2.14-102":{"q":"离开汽车时你必须做什么？","o":["开门前注意后方来车","防止车辆溜车","防止车辆被擅自使用"],"c":"离开车辆前，您必须防止车辆失控滑行，例如在下坡路段。下车前您必须确保不会危及其他道路使用者。这同样适用于您的乘客。下车时粗心开门是造成事故的常见原因。车辆还必须防止未经授权使用。"},"2.2.14-104":{"q":"你的汽车停在车行道边缘。上车时你应怎么做？","o":["尽可能让乘客从人行道一侧上车","只有在交通状况允许时才打开靠车行道一侧的车门","右侧车门总是可以无危险地打开"],"c":"上下车时，您必须注意不要危及其他道路使用者。从右侧——即从人行道一侧——上车更安全，但并非毫无危险。在打开车门前，请确保交通状况允许。请确保此时人行道上没有行人或骑自行车者。"},"2.2.14-105":{"q":"儿童上下车时重要的是什么？","o":["尽可能让儿童从人行道一侧上下车","只有在有人看护时才让儿童从车行道一侧上下车","禁止儿童在公共道路上上下车"],"c":"作为汽车驾驶员，您应确保儿童直接在人行道上上下车。如果情况不允许，则只应在成人看护下从道路一侧上下车。儿童更不易被看到，且行为难以预料。"},"2.2.14-106":{"q":"下车前你应提醒乘客注意什么？","o":["他们应注意左侧来车","他们应注意右侧行走的行人","自行车须在自行车道上等候"],"c":"作为汽车驾驶员，当乘客下车时，您必须采取必要措施以避免事故或交通干扰。当乘客在自行车道上开门下车时，请向他们指出这一点。骑自行车者在自行车道上没有等待的义务。任何上下车的人都不得危及其他道路使用者。"},"2.2.14-107-M":{"q":"为什么你现在不能下车？","o":["因为[有自行车]","因为有摩托车","因为[有行人]"],"c":"任何上下车的人都必须以避免危及其他道路使用者的方式行动。在您的左侧后视镜中可以看到一辆正在驶近的骑自行车者，您必须让它先通过。"},"2.2.14-108-M":{"q":"你停在了停车带内，现在想下车。在此情形下你必须怎么做？","o":["开门前查看左侧外后视镜","开门前向左肩后方瞥视","仅通过略微打开的车门观察"],"c":"在您打开车门下车前，请通过左侧后视镜检查后方无人驶来。您还必须向左观察，确保您的盲区内没有其他车辆。"},"2.2.14-109":{"q":"离开汽车时，你如何防止其被擅自使用？","o":["我锁上车门","我关闭车窗","我启用儿童安全锁"],"c":"您必须确保没有未经授权的人员使用您的汽车。因此，请从启动装置中取下钥匙，并确保所有车窗和车门都已关闭。"},"2.2.14-110":{"q":"你想让一名儿童下车。此时你应注意什么？","o":["从人行道同一侧下车","不必横穿车行道","下车时被提醒可能存在的危险"],"c":"作为汽车驾驶员，您应确保儿童直接在人行道一侧上下车。如果情况不允许，则只应在有人看护并事先提醒可能危险的情况下，从车道一侧上下车。儿童更难以被看到，且行为难以预料，因此您应确保他们无需再横穿道路。"},"2.2.15-001":{"q":"当你的摩托车因发动机损坏而抛锚时，允许怎么做？","o":["把摩托车装上车辆运走","把摩托车推到最近的修理厂","让人拖曳摩托车"],"c":"您不能用牵引的方式拖走一辆损坏的摩托车，它会倒下并摔落。相反，您应推行或运输它。"},"2.2.15-002":{"q":"你在城镇内道路之外，因摩托车故障而停下。应如何将其运到修理厂？","o":["用合适的拖车","用合适的厢式货车","用合适的牵引绳拖曳"],"c":"驾驶一辆不再符合交通安全的车辆，对您和其他道路使用者而言都是重大且首先无法估量的危险。因此，您必须尽快将您的车辆驶出交通。您可以将您的摩托车放到合适的拖车或厢式货车上运走。根据《道路交通法》(StVO) 第 15a 条第 (4) 款，不得用牵引绳牵引摩托车。"},"2.2.15-103":{"q":"你想用你的汽车拖曳另一辆车。你必须知道什么？","o":["你至少须持有B类驾驶证","你至少须持有BE类驾驶证"],"c":"您需要了解这是手动挡、自动挡还是电动汽车。电动汽车不能被牵引，必须装载运输。装有自动变速器的车辆只能在“N”挡下被牵引几公里而不造成损坏。"},"2.2.15-104":{"q":"一辆带助力制动器的汽车因发动机损坏而抛锚。拖曳该车时哪项正确？","o":["即使加大对踏板的压力，被拖曳的汽车也只能产生很小的制动效果","尽可能使用牵引杆","脚制动的作用不会因发动机不运转而受影响"],"c":"如果可能的话，牵引装有制动助力器的车辆时应使用牵引杆。因为制动助力器只在发动机运转时工作。当发动机熄火时，即使用力踩脚制动，该车辆也只能获得微弱的制动效果。"},"2.2.15-105":{"q":"一辆带助力转向的汽车因发动机损坏而抛锚，必须被拖曳走。哪项正确？","o":["明显更重","被锁止","不受影响"],"c":"动力转向的功能取决于发动机，并且只在发动机运转时工作。如果发动机和动力转向的助力功能失效，转向会明显变得困难，您需要更大的力气。转向的功能受到损害。"},"2.2.15-106":{"q":"当汽车在车流速度很快的道路上抛锚时，必须把三角警告牌放置在多远处？","o":["大约100 m处","大约50 m处","大约10 m处"],"c":"如果您在快速通行的道路上车辆抛锚，必须在约 100 m 的距离处设置警示三角牌。打开危险警示灯，使其他道路使用者注意到故障情况。"},"2.2.15-107":{"q":"夜间，当车辆在某处抛锚并对其他交通构成危险时，你必须如何警示？","o":["立即开启危险警示灯","在足够远处放置三角警告牌","开启倒车灯"],"c":"如果车辆在多车道道路上无法及时被识别为障碍物的地点抛锚，作为汽车驾驶员，您必须立即打开危险警示灯。之后，应在足够远的距离、清晰可见的位置，在快速交通中约为车辆前方 100 m 处设置警示三角牌。您不需要打开倒车灯。"},"2.2.15-108":{"q":"何时必须开启危险警示灯？","o":["当你的车辆在某处抛锚、不易被识别为静止障碍物时","双排停车时","所有装卸作业时"],"c":"如果汽车在多车道道路上无法及时被识别为障碍物的地点抛锚，必须立即打开危险警示灯。一般而言禁止在第二排停车。仅仅打开危险警示灯并不会改变这一点。这是不允许的。在装卸货物时不得打开危险警示灯。"},"2.2.15-109":{"q":"拖曳时你必须记住什么？","o":["两车之间的距离不得超过5 m","牵引绳/牵引杆必须清晰标示","摩托车只能用刚性连接拖曳"],"c":"牵引时，牵引车与被牵引车之间的距离不得超过 5 m。所使用的工具如牵引杆或牵引绳须有清晰标识。摩托车不得被牵引，必须装载运输。"},"2.2.15-110":{"q":"你的汽车在高速公路上爆胎。你应怎么做？","o":["开启危险警示灯，并尽可能靠右停车","在约100 m处放置三角警告牌","继续行驶到下一个出口"],"c":"如果您的车辆在多车道道路上因爆胎而无法及时被识别为静止障碍物的地点抛锚，请立即打开危险警示灯。之后，应在足够远的距离、清晰可见的位置设置警示三角牌。在快速交通中，车辆与警示三角牌之间的距离应约为 100 m。"},"2.2.15-111":{"q":"你的汽车发生故障，无法继续行驶。拖曳过程中你必须注意什么？","o":["若发动机失效，操作制动踏板所需的力会显著增大","尽可能使用牵引杆","还应开启后雾灯以示意正在拖曳"],"c":"请记住，在发动机不工作的情况下，发动机制动的制动助力器也会失效。这意味着所需的制动力比发动机运转时要大得多。如果可能，牵引时请始终使用牵引杆。牵引杆可防止碰撞，并且可以传递制动力。"},"2.2.15-112":{"q":"你的汽车发生故障，无法继续行驶。拖曳过程中你必须注意什么？","o":["两车都必须开启危险警示灯","牵引绳应尽可能保持绷紧","只有在为缩短前往下一家修理厂的路程时才可使用高速公路"],"c":"牵引时，牵引车和被牵引车都必须打开危险警示灯。牵引绳应尽可能拉紧。如果故障不是发生在高速公路上，则在牵引期间不允许驶上高速公路。"},"2.2.15-113":{"q":"你在城镇内道路之外发生抛锚。你的机动车位于道路上、弯道之后。在此情形下正确的做法是什么？","o":["我必须开启危险警示灯","我必须至少在车辆后方放置一个醒目的警告标志","我应穿上反光背心"],"c":"为保障该区域的安全，汽车驾驶员必须打开危险警示灯，并在车辆后方设置标志以警告其他道路使用者。此外，您应穿着安全背心以提高可见度。"},"2.2.15-114":{"q":"你的汽车发动机故障，须用牵引绳拖走。你必须注意什么？","o":["带助力转向的故障车难以转向","拖曳电动汽车时，必须遵循制造商的说明","拖曳汽车至少需要BE类驾驶证"],"c":"牵引时请遵守制造商的规定。电子辅助系统会失效，因此请对转向迟缓有所准备。"},"2.2.15-115":{"q":"你在城镇内道路之外发生抛锚。你的汽车位于道路上、弯道之后。在此情形下哪项正确？","o":["我必须开启危险警示灯","我必须在车辆后方约100 m处放置至少一个醒目的警告标志","我应穿上反光背心"],"c":"在您离开车辆前，必须打开危险警示灯并穿上高能见度背心。这样，其他道路使用者就能识别您并对您作出反应。在城镇外，必须在距车辆 100 m 的距离处设置警示三角牌。"},"2.2.15-201":{"q":"你必须在高速公路的应急车道上更换轮胎。必须采取什么警示措施？","o":["我必须把三角警告牌放置在右侧车道边缘、距离100 m处且位置醒目","我必须在适当距离处设置警告灯","我应始终穿着反光背心"],"c":"由于您是在高速公路上，会以极高的车速行驶，更换轮胎时，应将警示三角牌放在约 100 m 距离处、道路右缘清晰可见的地方。进行所有操作时都要穿着警示背心，并在足够远的距离设置警示灯。"},"2.2.16-001":{"q":"在哪些地方允许闪大灯以示意打算超车？","o":["城镇内道路之外的白天","城镇内道路之外的夜间","城镇内道路的夜间"],"c":"在城镇外，作为汽车驾驶员，您可以使用大灯闪烁来示意您打算超车。白天和黑暗中均允许这样做。在城镇内则不得使用大灯闪烁。"},"2.2.16-101":{"q":"何时必须开启车辆的危险警示灯？","o":["当车辆在视线受阻处抛锚时","当车辆被拖曳时","当我把车辆短暂双排停放时"],"c":"如果您的汽车在视线盲区抛锚，您应使用危险警示灯警告其他道路使用者。当您的汽车被牵引时，您必须打开危险警示灯。"},"2.2.17-001":{"q":"你如何判断后雾灯是否开启？","o":["通过黄色指示灯","通过蓝色指示灯","通过红色指示灯"],"c":"看一眼仪表盘就足够了，汽车驾驶员可以从黄色警示灯立即识别出后雾灯正在工作。根据《道路交通法》，该警示灯必须位于直接视野内。"},"2.2.17-002":{"q":"你的摩托车装有前雾灯。有雾时关于灯光你必须记住什么？","o":["前雾灯可代替近光灯使用","前雾灯可与近光灯一起使用","你只可开示宽灯行驶"],"c":"在雾天，您对道路上的其他人而言不太容易被看到。为提高您的可见度，您可以代替或配合近光灯使用前照灯。"},"2.2.17-004":{"q":"天很黑，因灯丝烧断远光灯失效。你必须怎么做？","o":["立即切换到近光灯","尽快更换灯泡","开示宽灯缓慢驶往最近的修理厂"],"c":"您需要确保既能让道路上的其他人看到您，同时您自己也能看清道路。请尽快更换灯泡，同时立即打开近光灯。"},"2.2.17-005":{"q":"能见度显著降低。何时允许开启前雾灯？","o":["下雨时","下雪时","有雾时"],"c":"如果白天的能见度因雾、降雪或降雨而受到严重影响，那么作为汽车驾驶员，您必须打开近光灯。只有在能见度受到强烈影响的天气条件下，您才可以同时打开雾灯。"},"2.2.17-008":{"q":"你夜间在无照明道路上行驶。前方不远处有一辆机动车。你必须开启哪些灯？","o":["近光灯","远光灯","仅示宽灯"],"c":"汽车驾驶员必须打开自己车辆的近光灯，以免使前方车辆或对向车流致眩。使用远光灯则免谈，因为它会使其他驾驶员眩目。"},"2.2.17-010":{"q":"你汽车的后部照明装置被遮挡。必须怎么做？","o":["无论如何都必须加装","仅在天黑或夜间行驶时才须加装","仅在行程超过5 km时才须加装"],"c":"您必须始终在您的车辆上安装一个带有所有尾灯的灯光支架。请记住，作为汽车驾驶员，您对照明设备的有效性负责。在这种情况下不存在公里数限制。"},"2.2.17-011":{"q":"视机动车而定，你如何判断远光灯是否开启？","o":["操纵开关的位置","蓝色指示灯","绿色指示灯"],"c":"带有前照灯符号的蓝色指示灯表示远光灯已打开。此外，您可以通过触摸开关的位置来识别远光灯是否打开。绿色的警示灯并不代表远光灯，而是近光灯。"},"2.2.17-012":{"q":"作为基本原则，夜间行驶时机动车必须开启哪些灯？","o":["近光灯","仅示宽灯","远光灯"],"c":"在德国，黑暗中必须打开近光灯。打开近光灯时，您能看到更多，同时也更易被看到。"},"2.2.17-013":{"q":"你如何判断远光灯已开启？","o":["蓝色指示灯","绿色指示灯","红色指示灯"],"c":"蓝色控制灯表示远光灯已打开。"},"2.2.17-101":{"q":"何时允许在白天也使用前雾灯？","o":["有雾或下雪时","下雨时","挡风玻璃结冰时"],"c":"在因雾、雪或雨造成的严重天气相关能见度受限时，白天可以打开雾灯。这种强烈的天气相关能见度受限通常只出现在秋冬月份。一般而言，您不允许在挡风玻璃结冰的情况下驾驶。您需要在开始行程前清除它。"},"2.2.17-102":{"q":"何时允许开启后雾灯？","o":["当雾使能见度降至不足50 m时","当雾使能见度降至100 m时","当大雨使能见度降低时"],"c":"只有在浓雾中能见度低于 50 m 时，才可以使用您车辆的后雾灯。由于眩目风险很高，否则这些灯会对后方交通构成安全隐患。"},"2.2.17-103":{"q":"汽车停放在无照明车行道上时，在哪些地方使用示宽灯即可？","o":["城镇内道路","城镇内道路之外","高速公路的应急车道上"],"c":"在城镇内，汽车只能打开停车灯停放在无照明的道路上。因为在城镇内，人们以较低的车速行驶，因此停放的汽车可以及时被发现。在城镇外则不允许这样做。"},"2.2.17-104":{"q":"行驶时，你如何判断前照灯已开启远光？","o":["通过蓝色指示灯","通过红色指示灯","通过绿色指示灯"],"c":"通常在速度表区域有一个蓝色指示灯，用于显示远光灯的功能。如果这个蓝色灯亮起，那么您车辆的远光灯也已打开。"},"2.2.17-105":{"q":"手动大灯高度调节设置不当会产生哪些危险？","o":["可能使对向车辆眩目","能见度可能过低","前照灯可能失效"],"c":"前照灯光束高度调节装置用于根据车辆载重调整前照灯的照射方向。如果调节不当，它们要么调得太低——能见度太低——要么调得太高。如果调得太高，会使用对向车流眩目。因此，仅仅有前照灯本身是不够的。"},"2.2.17-107":{"q":"夜间你是否允许仅开示宽灯（驻车灯）行驶？","o":["不允许","允许，如果你在城镇内道路之外的车队中行驶","允许，如果在城镇内道路上路面照明充足"],"c":"仅凭示廓灯，作为汽车驾驶员在任何情况下都不允许行驶。示廓灯的同义名称是停车灯。顾名思义：停车灯专门用于静止的、可能是停放的汽车。"},"2.2.17-109":{"q":"何时必须在白天也使用近光灯？","o":["有雾或下雪时","下雨时","挡风玻璃起雾时"],"c":"如果因天气条件——雨、雾、降雪——能见度严重受限，即使在白天行驶，您也必须使用规定的照明设备，通常是近光灯。这是必要的，以便其他道路使用者能更好地看到您，并且帮助您更好地看清他人。"},"2.2.17-111":{"q":"在天黑或夜间，何时必须至少开启示宽灯？","o":["当车辆停放在城镇内道路之外的应急车道上时","在照明充足且连续的道路上行驶时"],"c":"在黄昏和黑暗中始终打开近光灯行驶。这样，您清晰可见，同时您自己也能看清。车辆不允许仅打开停车灯行驶，因为这些灯（也称为示宽灯）的亮度不足。"},"2.2.17-114":{"q":"何时必须开启近光灯？","o":["在黄昏（暮色）时","天黑时","驶经隧道时"],"c":"在能见度不佳时，您必须始终打开近光灯。在黄昏、黑暗中或因天气导致的能见度不佳（如雨、雾或雪）时，始终如此。即使您驶过隧道，也必须始终打开近光灯。"},"2.2.17-115":{"q":"前照灯高度调节装置设置错误可能导致什么后果？","o":["对向车辆可能因我的近光灯而眩目","我汽车前照灯的照射距离可能过短","前照灯灯泡的使用寿命可能缩短"],"c":"如果前照灯调得太高，会使用对向车流眩目。如果前照灯调得太低，几乎照不亮道路，您对前方的能见度不足。如果前照灯调节不当，灯光可能无法完全关闭。"},"2.2.17-116":{"q":"夜间，你车辆的远光灯辅助系统有何功能？","o":["当有对向来车时及时切换为近光","当环境条件合适时自动开启远光","清洁远光灯灯罩"],"c":"该辅助系统会自动打开和关闭远光灯，以免其他道路使用者眩目。只有当道路照明不足时，才会自动打开远光灯。"},"2.2.17-117":{"q":"在哪些情形下，远光灯辅助系统可能无法在遇到对向来车时及时切换为近光？","o":["驶过坡顶时","驶经道路弯道时","被对向车辆眩目时"],"c":"在越过坡顶和驶过弯道时，远光灯辅助摄像头可能无法及时识别对向车流。当您察觉时，请手动关闭远光灯，以免使用对向车流眩目并危及自身。"},"2.2.17-118":{"q":"你汽车的自动灯光系统已启用。在所示光照条件下行驶时，你应预料到什么？","o":["近光灯不会自动开启","后方的道路使用者会很晚才看到我","自动灯光系统会开启我的雾灯"],"c":"由于低垂的太阳和雾蒙蒙的空气，光线和能见度条件很差。然而，自动灯光系统无法识别不佳的光线条件。请手动打开近光灯，以便后方道路使用者能更好地看到您。"},"2.2.17-202":{"q":"在城镇内道路，哪些车辆在天黑或夜间停放在车行道上时必须始终以自身灯光或停车警示板标示？","o":["允许总质量超过3.5 t的卡车和房车","拖车","小汽车"],"c":"允许总质量超过 3.5 t 的卡车和休闲车辆以及拖车，在城镇内如果通过停车警示牌或其自身光源可被识别，则可以停放在道路上。汽车不需要这种光源。"},"2.2.17-301":{"q":"哪些车辆必须在其侧面装备黄色反光器？","o":["含挂装器具在内长度超过6 m的拖拉机","拖车和挂接的作业设备","所有多轮机动车"],"c":"为使长侧面更易被看到，对于带悬挂农具、长度超过 6 m 的拖拉机，您应安装一个黄色反光镜。对于固定安装这些农具的拖车也同样适用。"},"2.2.17-401":{"q":"你结束了田间作业，想驾驶拖拉机在公共道路上回家。天已黄昏。你必须怎么做？","o":["即使你仍能看清，也要开启灯光","检查灯光，必要时清洁","也开启作业灯，以便更容易被看到"],"c":"即将推出……"},"2.2.17-402":{"q":"你夜间开启远光灯行驶。何时必须切换为近光？","o":["有车辆对向驶来时","有车辆在前方近距离行驶时","前方有同向行走的行人时"],"c":"您不得用远光灯使对向车流眩目。因此，一旦您意识到有其他车辆驶向您，请立即关闭远光灯。如果行人朝您的同一方向行进，他们不会被您的远光灯眩目。"},"2.2.17-403":{"q":"你夜间开启远光灯行驶。何时必须切换为近光？","o":["如果我在照明持续且充足的道路上行驶时","如果我须在铁路道口停车等待并会使他人眩目时","如果我前方有同向行走的行人时"],"c":"在黑暗中用远光灯行驶时，当有对向车流驶近时，您需要关闭远光灯。在全程照明充足的道路上，您不允许打开远光灯行驶。等候车辆的前照灯不应使他人眩目。因此，您在铁路道口必须使用近光。如果行人同方向在前方行进，他们不会被远光灯眩目。"},"2.2.17-404":{"q":"当雾、雨或降雪使能见度变差时，为什么白天也必须开近光灯行驶？","o":["以便其他道路使用者更容易看到你","以便你能以更高的速度行驶","以便你能在更远处看到交通标志"],"c":"如果白天因雨、雾或雪等天气条件导致能见度不佳，作为驾驶员您必须打开近光灯。这里首要关注的是让其他道路使用者更好地看到您的车辆。交通标志并不会从更远的距离被更好地看到。"},"2.2.17-405":{"q":"何时要求你开近光灯或日间行车灯行驶？","o":["每次行程","仅在城镇内道路行驶时","仅在能见度差时"],"c":"为了您和他人的安全，您应通过始终打开近光灯或日间行车灯来保持可见。"},"2.2.17-406":{"q":"何时挂装设备必须具备额外的照明装置？","o":["遮挡车辆的照明装置","侧向超出车辆前、后示廓灯40 cm以上","超出车辆反光器1 m以上"],"c":"需要遮挡您车辆农具的照明设备时，须额外用灯光进行标示。对于超出反光镜 1 m 以上的悬挂农具同样适用。当农具横向超出车辆的示廓灯或尾灯 40 cm 以上时也是如此。"},"2.2.18-001":{"q":"你在高速公路上行驶，前方发生交通拥堵。哪项正确？","o":["小心驶近车尾，并保持规定的安全距离","在其他车辆之间继续行驶","在应急车道上继续行驶"],"c":"在交通拥堵时，摩托车必须像普通汽车一样行事。它不能在车辆之间穿行，也不能使用应急车道。"},"2.2.18-002":{"q":"高速公路上允许什么？","o":["车辆抛锚时在应急车道停车","在同一车道内与另一车辆并排行驶","通过农用道路驶离高速公路"],"c":"在高速公路/机动车道上，摩托车必须像普通汽车一样行事。发生故障时它可以停在应急车道上。它不能与另一辆车共用一条车道，也不能从农田道路驶离。"},"2.2.18-003":{"q":"高速公路上对汽车和摩托车适用的推荐速度是多少？","o":[],"c":"在高速公路和机动车道上，汽车和摩托车必须保持 130 km/h 的建议限速。此外，只有速度超过 60 km/h 的车辆才允许在高速公路上行驶。"},"2.2.18-006":{"q":"你在两条车道中靠左的那条行驶，正接近一辆刚开始超车的车辆。你该怎么做？","o":["与前车保持足够的距离","让前车完成超车","贴近前车、鸣喇叭并闪灯"],"c":"您通过保持安全距离让该车辆超车。由于该车辆从右侧变更，请准备好接受尽管它在加速、车速仍低于您。必要时请放慢车速。切勿紧贴前车、鸣喇叭或闪灯。"},"2.2.18-007":{"q":"你在车流稀少的高速公路上行驶。你最多可以在左侧车道停留多久？","o":["超车所需的时间内","你跟随一辆在左侧车道超车的车辆行驶期间","始终可以，只要没有其他车辆想超越你"],"c":"左侧车道一般只允许用于超车目的。如果前方车辆在超车，可以假定后方的汽车驾驶员也会超车。因此，这里允许使用左侧车道。在所有其他情况下，您必须靠右行驶。"},"2.2.18-009":{"q":"在机动车专用快速路上适用哪些规定？","o":["禁止掉头","仅可在交叉路口和路口驶入快速路","夜间可以超过近光灯照射距离的速度行驶"],"c":"在高速公路上，您只允许在交叉路口或丁字路口驶入。禁止在高速公路上调头。关于车速的规定与高速公路适用的规定不同。在机动车道上，您的车速不得超过近光灯照射范围所允许的速度。"},"2.2.18-010":{"q":"车辆文件上必须登载怎样的最高车速方可在高速公路上使用？","o":[],"c":"机动车道或高速公路是为高速交通而修建的。因此，只有能够达到 60 km/h 以上车速的车辆才允许在此行驶。如果您不完全确定自己的车辆能否达到那样的速度，车辆文件中会有注明。"},"2.2.18-011":{"q":"三车道高速公路上形成了交通拥堵。应急车辆通道必须在何处形成？","o":["左侧车道与中间车道之间","中间车道与右侧车道之间","应急车道上"],"c":"当高速公路或在城镇外、单向至少有两条车道的道路上交通停止时，车辆必须形成一条空车道，供警车和救援车辆通行。如果一条道路单向有三条车道，则中间被认为是位于左侧车道和中间车道之间。"},"2.2.18-012":{"q":"你在汇入车道行驶。你应怎么做？","o":["从直行道上较慢车辆的右侧驶过，并在它们前方汇入","适当加速，尽可能不停车，在遵守优先通行权的情况下汇入","始终驶到汇入车道尽头，在那里停车后再汇入"],"c":"在加速车道上，允许在右侧比在连续车道上行驶得更快。为了汇入，作为汽车驾驶员您必须充分加速，并遵守优先通行权和保持安全距离。"},"2.2.18-013":{"q":"现在你必须怎么做？","o":["尽可能靠右","尽可能靠左","在中间"],"c":"您驶近高速公路上一处交通拥堵的末端。打开危险警示灯。在车道中间形成一条通道，供警车和救援车辆通行：在单向三条车道的道路上，在左侧车道和中间车道之间形成通道。因此，您必须尽量靠右行驶。该规则适用于城镇外和高速公路。"},"2.2.18-014":{"q":"你应怎么做？","o":["我继续行驶","我在应急车道上排队","我在本车道上停车等待空隙"],"c":"您想驶离高速公路。您看到您打算驶出的出口处交通正在停滞。由于您不允许在应急车道上行驶，也不允许在车道上等待，因此如果您继续行驶并使用下一个出口来驶离高速公路，您的做法是正确的。"},"2.2.18-015-M":{"q":"当这条道路上形成交通拥堵时，你必须怎么做？","o":["尽可能靠左行驶","尽可能靠右行驶","继续在中间行驶"],"c":"在高速公路以及城镇外有多于一条车道的道路发生拥堵时，任何汽车驾驶员都必须协助在道路中间形成一条通道，供警车和救援车辆通行。不要在侧边上行驶，这是禁止的。"},"2.2.18-016-M":{"q":"现在正确的做法是什么？","o":["我鸣喇叭并闪灯警告该驾驶员","我尽可能驶向右侧","我通知警察"],"c":"您在高速公路出口处遇到一名逆行驾驶员。通过尽量靠右行驶，您可以最好地应对与逆行驾驶员的碰撞。现在必须警告其他道路使用者这一紧迫危险。因此，您必须通知警察。"},"2.2.18-017-M":{"q":"现在你应怎么做？","o":["我加速，汇入到[卡车]前方","我减速，汇入到[红色汽车]与[卡车]之间","我减速，汇入到[黄色车辆]之后"],"c":"您已经在高速公路右侧的加速车道上超过了卡车。如果您继续加速，就可以在车道结束前驶上主车道。您应该这样做。"},"2.2.18-018-M":{"q":"你想驶离高速公路。在此情形下正确的做法是什么？","o":["我驶入左侧车道","我注意对向来车","我继续在应急车道上行驶"],"c":"您打转向灯并在出口处驶离高速公路。到出口转弯处的路段用于减速。请快速驶离高速公路，然后降速。以适度降低的速度进入弯道。"},"2.2.18-019":{"q":"如果你在高速公路以及同向两条车道的快速路上遇到交通拥堵，你必须怎么做？","o":["在右侧车道内尽可能靠右行驶","在左侧车道内尽可能靠左行驶","在右侧车道内尽可能靠左行驶"],"c":"如果车辆在高速公路或在城镇外、单向至少有两条车道的道路上以步行速度停着或行驶，则适用以下规定：作为汽车驾驶员，您必须参与在最左侧车道和最右侧车道之间形成一条空车道，供警车和救援车辆通行。"},"2.2.18-020":{"q":"你正接近高速公路上的交通拥堵。正确的做法是什么？","o":["我小心地在拥堵中最后一辆车后方停下","我小心地穿过应急通道","我沿应急车道小心继续行驶"],"c":"通过打开危险警示灯警告后方交通，并小心地靠近。"},"2.2.18-021-M":{"q":"现在正确的做法是什么？","o":["我保持在中间车道","我驶入左侧车道","我驶入右侧车道"],"c":"您必须留在中间车道，因为左侧和右侧车道上有您会妨碍的车辆。在右侧车道，一辆摩托车正从匝道驶上高速公路。在左侧车道，是刚刚超越您的那辆汽车。"},"2.2.18-022":{"q":"你想在下一个出口驶离高速公路。在此情形下正确的做法是什么？","o":["我观察后方交通","我现在开启右转向灯","我现在开始平稳减速到60 km/h"],"c":"驶离高速公路时，您应至少在出口前 300 m 设置转向灯。在高速公路上行驶时，始终密切关注后方交通。尤其是在驶离高速公路时，请确保无人试图从右侧超越您。"},"2.2.18-023-M":{"q":"现在你应怎么做？","o":["我降低车速","我加速","我驶入中间车道"],"c":"降低车速，让蓝色汽车在保持安全距离的情况下汇入高速公路。"},"2.2.18-024-M":{"q":"现在你可以预料到什么？","o":["制动","保持在中间车道","加速"],"c":"您应预料到前方的卡车会减速，因为右侧车道上的另一辆卡车已经在减速并打开了危险警示灯。您还必须预料到该卡车会留在中间车道，因为它没有足够的空间驶入右侧车道。如果在高速公路上发现危险情况，可以打开危险警示灯，以及时警告所有后方车辆。危险情况通常包括事故、交通拥堵或缓慢行驶的交通。"},"2.2.18-101":{"q":"你的车辆在高速公路上抛锚。拖曳时你必须记住什么？","o":["你必须在下一个出口驶离高速公路","拖曳过程中，两车都必须开启危险警示灯","你可以沿高速公路继续行驶到最靠近合适修理厂的出口"],"c":"在高速公路上牵引时，牵引车和被牵引车都必须打开危险警示灯。只允许在高速公路上牵引到下一个出口。然后必须驶离高速公路。"},"2.2.18-102":{"q":"高速公路上适用哪些规定？","o":["禁止在车行道和应急车道上停车","禁止倒车","夜间，在任何情况下都不得以超过近光灯照射距离的速度行驶"],"c":"在高速公路上，您只允许向前行驶，且只能沿一个指定的方向行驶。在车道上以及侧边上，都严格禁止倒车、调头和停车。"},"2.2.18-103":{"q":"你在高速公路上行驶并错过了出口。正确的做法是什么？","o":["我继续行驶，并在后面的某个出口驶离高速公路","我在应急车道上倒车回去，因为出口就在我后方不到100 m处","我在应急车道上停车规划后续路线"],"c":"继续行驶到下一个出口并在那里驶离高速公路。现在您可以经高速公路的另一侧开回错过的那个出口。您不得停车或倒车。"},"2.2.18-104-M":{"q":"在不进行转向干预的情况下，变道辅助系统在此情形下如何帮助你？","o":["对可能与中间车道车辆发生的碰撞发出警告","独立完成变道","对我车辆的车速进行制动"],"c":"变道辅助系统将中间车道上的车辆识别为危险，并警告您不要变更到该车道。若要自行变道，则需要转向干预。变道辅助系统不会干预您的车速。"},"2.2.18-105":{"q":"使用高速公路时禁止什么？","o":["在应急车道停车","倒车","掉头"],"c":"根据 StVO（《道路交通法》）第 18 条关于高速公路和机动车道的规定：(7) 禁止调头和倒车。(8) 禁止停车，侧边上也不例外。"},"2.2.18-207":{"q":"哪些车辆在高速公路和某些联邦公路上须缴纳通行费？","o":["允许总质量至少7.5 t、专门用于公路货物运输的机动车","允许总质量至少7.5 t、专门用于公路货物运输的汽车列车","允许总质量至少7.5 t的公共汽车"],"c":"正确的是：允许总质量至少 7.5 t、专门用于运输货物的机动车。允许总质量至少 7.5 t 的汽车列车。"},"2.2.18-208":{"q":"如果未缴纳通行费，谁可能被追究责任？","o":["驾驶员","车辆持有人","运输代理人"],"c":"不仅驾驶员有责任，车主也有责任。发货人不承担责任。"},"2.2.18-209":{"q":"你的牵引车允许总质量为6.5 t；拖车允许总质量为5.5 t。如果该汽车列车在高速公路上使用，是否须缴纳通行费？","o":["是，如果该汽车列车专门用于公路货物运输","总是，因为该汽车列车超过7.5 t的组合总质量","否，因为牵引车的允许总质量未超过7.5 t"],"c":"如果您的拖拉机允许总质量为 6.5 t，您的拖车为 5.5 t，那么只有当您的汽车列车专门用于货运时，您才可以在高速公路上通行并为其缴纳通行费。这些是收费道路。"},"2.2.18-210":{"q":"你的卡车允许总质量为5.5 t；拖车允许总质量为2.0 t。如果该汽车列车在高速公路上用于公路货运，是否须缴纳通行费？","o":["是","否"],"c":"由于您的卡车（货运）总质量加上拖车共 7.5 t（汽车列车），在高速公路上须缴纳通行费。"},"2.2.18-211":{"q":"在高速公路上，专门用于或实际用于公路货物运输的机动车或汽车列车须缴纳通行费。自多大的允许总质量起适用？","o":[],"c":"从最大质量 7.5 t 起须缴纳通行费。"},"2.2.18-212":{"q":"你的卡车允许总质量为6.5 t，你想在高速公路上将其用于公路货运。关于在收费终端登记，哪项正确？","o":["不必登记","必须输入车轴数","必须输入污染物等级（排放等级）"],"c":"您用于货运、总质量 6.5 t 的卡车无需注册登记，因为总质量低于 7.5 t。"},"2.2.18-213":{"q":"你的卡车装有机载单元（OBU）。在驶入收费路段前，必须核对哪些信息，并在必要时进行调整？","o":["车轴数","排放等级","允许总质量"],"c":"在您驶上收费路段之前，您应（在 OBU 收费设备上）输入车轴数量，并在必要时进行调整。"},"2.2.18-214":{"q":"你想在高速公路上驾驶一辆须缴通行费的机动车。所需通行费登记可以如何完成？","o":["通过互联网","在收费终端","使用机载单元（OBU）"],"c":"这里有 3 个答案是正确的。可以通过收费站的终端在互联网上，也可以通过车载单元（OBU），即手动和数字化地缴纳。"},"2.2.18-215":{"q":"在高速公路上行驶时，为什么应开启交通信息？","o":["对逆向行驶的车辆发出警告","提供交通拥堵报告","是在高速公路上行驶的强制要求"],"c":"驾驶员没有收听交通新闻的义务，但交通新闻对于顺畅的行程不可或缺。交通新闻会通报交通拥堵、交通事故和施工地点。关于逆行驾驶员的警告已经避免了许多严重事故。"},"2.2.18-216":{"q":"谁负责公路通行费的执行？","o":["自动检查龙门架的运营方","联邦货运局","联邦中央税务局"],"c":"通行费检查由自动检查桥的运营方和联邦货运局执行。税收与通行费无关。"},"2.2.18-217":{"q":"你的卡车装有机载单元（OBU）。在驶入收费路段前，必须核对哪些信息，并在必要时进行调整？","o":["允许总质量","排放等级","车轴数"],"c":"通行费率以重量等级为基础，因此您必须（申报）允许总质量，并在必要时进行调整。"},"2.2.18-218":{"q":"在何种情况下，用于公路货运的机动车或汽车列车须缴纳通行费？","o":[],"c":""},"2.2.18-219":{"q":"商业公路货运中的通行费缴纳适用哪些规定？","o":["未缴纳通行费时，驾驶员可能被追究责任","未缴纳通行费时，车主可能被追究责任","空驶时无需缴纳通行费"],"c":"驾驶员和车辆所有人都有责任正确缴纳通行费。如果未缴纳通行费，两人都被视为通行费的债务人，因此可以被相应追责。"},"2.2.18-220":{"q":"在高速公路上用于商业货运的机动车或汽车列车须缴纳通行费。自多大的技术允许最大装载质量起适用？","o":[],"c":"技术允许总质量超过 3.5 t 的机动车或汽车列车必须缴纳通行费。"},"2.2.18-301":{"q":"你的卡车装有机载单元（OBU）。在驶入收费路段前，必须核对哪些信息，并在必要时进行调整？","o":["车轴数","允许总质量","排放等级"],"c":"通行费率以重量等级为基础，因此您必须（申报）允许总质量，并在必要时进行调整。对于总质量超过 18 t 的车辆和汽车列车，重量等级的申报必须再提高一级。此时驾驶员还必须注明车轴数量。"},"2.2.21-001":{"q":"后座乘客对摩托车驾驶有何影响？","o":["起步更困难，因为摩托车只有在较高速度下才趋于稳定","摩托车更易受侧风影响","摩托车的制动特性可能发生变化"],"c":"让一名乘客坐在您身后会增加重量，使起步和提速更加困难，也会增加您停车所需的制动距离。由于它增大了侧面面积，还会增加您对侧风的敏感度。"},"2.2.21-002":{"q":"你想用摩托车搭载一名乘客。起步前你应注意什么？","o":["你的乘客必须佩戴规定的头盔","就行车途中的行为方式达成一致","小心谨慎地让缺乏经验的乘客熟悉乘坐摩托车"],"c":"搭载没有经验的乘客时，请确保他戴头盔，就骑行期间的行为方式达成一致，并逐渐适应新环境。"},"2.2.21-003":{"q":"如果你想搭载后座乘客，必须记住什么？","o":["摩托车必须获准搭载2人","必须为后座乘客配备安全头盔","在城镇内道路行驶时，后座乘客无需佩戴安全头盔"],"c":"搭载另一名乘客时，请确保他戴头盔，并且该摩托车获准搭载他。"},"2.2.21-004":{"q":"出发前你必须向后座乘客说明什么？","o":["必须把脚放在脚踏上","必须佩戴安全头盔","在弯道上必须始终向弯道外侧倾斜"],"c":"请确保您的乘客戴头盔，将双脚放在脚踏上（否则会增加事故和受伤的风险）。转弯时，您的乘客不必向弯道外侧倾斜来保持平衡。"},"2.2.21-006":{"q":"你想用助力自行车搭载一名5岁儿童。允许使用哪些座位？","o":["带脚踏的专用儿童座椅","加装软垫的行李架","加装衬垫的油箱"],"c":"为了搭载儿童作为乘客，您需要一个带脚踏的特制儿童座椅。"},"2.2.21-007":{"q":"为什么后排乘客不系安全带是危险的？","o":["即使在低速下也可能造成伤害","可能对前排乘员造成伤害","可能把这些乘员甩出车外"],"c":"发生碰撞时，后排座位上的人可能会向前或向侧方被抛出。如果他们向前被抛出，前排座椅靠背不能提供足够的保护。因此，驾驶员和副驾驶也面临风险。即使在低速下，也可能发生伤害。"},"2.2.21-008":{"q":"如果你想用摩托车搭载乘客，应注意什么？","o":["乘客也应穿着摩托车防护服","应相应调整底盘","应调整轮胎气压"],"c":"增加摩托车载重时，请确保提高轮胎气压、调整底盘/悬挂。您的乘客也应佩戴头盔和防护装备。"},"2.2.21-009":{"q":"如果你想搭载后座乘客，你必须注意什么？","o":["摩托车必须获准搭载2人","后座乘客必须有能力随行乘坐","7岁以上的儿童后座乘客必须能够使用现有的脚踏和扶手"],"c":"乘客必须在身体和精神上有能力乘坐，并且摩托车必须配备得当。"},"2.2.21-010":{"q":"搭载后座乘客对摩托车操控有何影响？","o":["更难保持摩托车稳定","制动时的表现发生变化","其对侧风的敏感性降低"],"c":"后座乘客自身的动作会使摩托车失去稳定。载人骑行应事先练习。"},"2.2.21-011":{"q":"你想用摩托车搭载后座乘客和行李。你必须注意什么？","o":["不得超过允许总质量","行李件必须牢固固定","照明装置不得被遮挡"],"c":"您不得超过摩托车的允许总质量。该质量由空车质量和最大允许载重量组成。为防止行李四处飞散，必须将其牢固固定。照明设备必须始终可见，且不得被装载的行李遮挡。"},"2.2.21-012":{"q":"你想搭载后座乘客。出发前你必须确保什么？","o":["我的后座乘客佩戴合适的头盔","我已就行车途中的行为方式向后座乘客作出说明","使用摩托车为搭载后座乘客所作的技术调节设置"],"c":"原则上，搭载后座乘客时，摩托车上必须有乘客座椅、脚踏和一个抓握装置。骑行时，骑手和后座乘客都必须佩戴合适的安全头盔。为确保安全骑行，您必须在骑行前向后座乘客说明正确的行为方式。"},"2.2.21-013":{"q":"如果你想搭载后座乘客，应预料到什么？","o":["车辆过弯时的操控特性会有所不同","超车所需距离可能更长","制动距离会缩短"],"c":"请注意，乘客的额外重量会使您的摩托车更慢，并使重心后移。因此，您将无法再像没有乘客时那样灵活地过弯。您还应意识到，额外的重量会使您的超车距离明显变长。"},"2.2.21-014":{"q":"要获准用轻便摩托车搭载一名5岁儿童，你必须满足哪些条件？","o":["年满16岁","为轻便摩托车安装专用儿童座椅","确保儿童的双脚不会卷入车轮"],"c":"法律规定，如果您想在轻便摩托车上搭载 7 岁以下的儿童，您必须至少年满 16 岁。由于该儿童未满 7 岁，您必须能够在轻便摩托车上安装一个特制儿童座椅。儿童的身高和身体控制能力尚不足以安全、独立地抓稳轻便摩托车。您还必须确保儿童的双脚不会卷入车轮。为此有专门的防护装置，例如：脚踏。"},"2.2.21-102":{"q":"你驾驶一辆带拖车的卡车，想顺路搭载一个人。允许将该乘客载在何处？","o":["驾驶室内","卡车的车厢地板上","拖车的地板上"],"c":"出于安全原因，您只允许在卡车的驾驶室内搭载人员。在载货平台上载人是不允许的。只有在特殊情况下，某些人员才可以乘坐载货平台，例如，如果他们负责押运货物。"},"2.2.21-103":{"q":"驾驶汽车出发前你必须确保什么？","o":["乘客能够系上现有的安全带","你有足够的后方视野","后搁板上没有散放的物品（如急救包、公路地图册、相机）"],"c":"汽车驾驶员对乘客和货物的安全负责。他/她必须采取一切必要措施来防止或尽量减少损害。装载必须按规定进行，并且必须仔细固定。"},"2.2.21-104":{"q":"允许如何在汽车内运送幼儿？","o":["使用带有检验标记的认证儿童约束装置","由成人抱着","放在后排某个座位上的婴儿提篮内"],"c":"幼儿必须特别加以固定。这只能通过适合其年龄的约束装置来实现。该装置应安装在后台。发生碰撞时，婴儿有被安全气囊窒息的风险。婴儿座椅不够安全。"},"2.2.21-105":{"q":"允许如何在汽车内运送一名5岁儿童？","o":["使用带有检验标记的合适且经认证的儿童座椅","在后排座位上系标准三点式安全带","在后排座位上系好腰带"],"c":"如果您想用车搭载一名五岁儿童，您必须使用经过测试并适合该儿童身高的儿童座椅。这对所有 12 岁以下儿童都是强制性的。"},"2.2.21-106":{"q":"允许如何在汽车内运送一名身高140 cm的11岁儿童？","o":["使用带有检验标记的认证增高垫并系好三点式安全带","系好三点式安全带","在后排座位上系好腰带"],"c":"一名身高 140 cm 的十一岁儿童需要儿童座椅或加高座椅。该儿童须用安全带固定。12 岁以下或身高不足 150 cm 的儿童必须使用（儿童约束装置）。如果安全带勒在颈部，会有勒伤的风险。"},"2.2.21-107":{"q":"使用带有检验标记的认证儿童座椅时应注意什么？","o":["儿童座椅必须适合儿童的身高和体重","儿童座椅必须能够固定在其所适用的车辆座椅上","除检验标记外无需其他"],"c":"儿童座椅是针对不同年龄组制造的。它们针对指定的重量和身高组别进行了安全测试。使用时您应注意这一点。儿童座椅只允许用于其适配且获准使用的那些汽车座椅上。"},"2.2.21-108":{"q":"为什么不系安全带是危险的？","o":["因为在约20 km/h速度下发生碰撞时，你无法充分保护自己","因为发生事故时你可能被甩出车外","因为在城市交通中由于速度低而没有危险"],"c":"在事故中，人可能因撞击能量而容易被抛出车外，或因在车内碰撞而受伤。在 20 km/h 时，撞击能量就已高到可能造成伤害。"},"2.2.21-111":{"q":"不系安全带时，从多大的碰撞速度起必须预计会有严重或致命伤害？","o":["从30 km/h起","从50 km/h起","从80 km/h起"],"c":"不系安全带时，仅仅超过 20 km/h 的碰撞就可能造成严重伤害。这同样适用于常被错误地认为无害的追尾碰撞。因此您应始终系好安全带，即使是在短途行驶时。"},"2.2.21-112":{"q":"一辆汽车装有两个前排气囊。哪些座位必须系安全带？","o":["所有座位","前排座位不必","仅前排座位"],"c":"前排气囊在发生强烈撞击（例如追尾碰撞）时保护前排的汽车驾驶员和副驾驶。然而，它们不足以提供全面的保护。所有乘客每次行驶时都必须系好安全带。"},"2.2.21-113":{"q":"这个警告标志是什么意思？","o":["不得安装与车辆行驶方向相反的儿童座椅","只可安装面向车辆行驶方向的儿童座椅","必须按图示安装儿童座椅"],"c":"该提示警告不要错误地安装儿童座椅。如果儿童座椅反向安装（使儿童面向与行驶方向相反的方向），在发生碰撞和气囊作用时，儿童可能严重受伤。儿童座椅必须沿行驶方向安装。"},"2.2.21-114":{"q":"你想在儿童生日聚会后送几名幼儿回家。使用汽车时你必须遵守什么？","o":["必须使用规定的儿童约束装置固定儿童","在城镇内道路内无需使用儿童约束装置","用现有安全带固定儿童即可"],"c":"如果您想用车送几个小孩回家，您必须确保所有座位上的乘客都使用法律规定的约束装置加以固定。"},"2.2.21-115":{"q":"如果你要驾驶一辆带有前排乘客气囊的车辆，必须遵守什么？","o":["不得在前排乘客座位上安装朝后的儿童约束装置","可以在前排乘客座位上安装朝前的儿童约束装置","可以在前排乘客座位上安装朝后的儿童约束装置"],"c":"儿童座椅必须朝前。如果反向放置，则不得使用该儿童座椅，因为在发生事故时气囊会对儿童构成风险。"},"2.2.21-117":{"q":"关于头枕，重要的是什么？","o":["按照使用手册将其调节到头部高度","它们已由厂家最佳调节","对后排座位而言它们替代安全带"],"c":"头枕必须始终调整到适合乘员身高的位置。只有这样，它们才能最好地吸收撞击能量，并在发生碰撞时保护驾驶员和其他乘客。然而，头枕不能代替安全带。"},"2.2.21-118":{"q":"行驶中，气囊控制指示灯持续亮起。你必须怎么做？","o":["前往修理厂","立即停止使用该车辆","什么也不做，因为这只是给修理厂的提示"],"c":"如果气囊控制灯亮起，表示气囊系统存在故障。这种传感和电子系统的故障通常只能在汽车修理厂修复。此事应尽快进行。因此，作为汽车驾驶员，您不必立即将车辆停驶。"},"2.2.21-120":{"q":"是否允许在卡车装载平台上运送人员？","o":["可以，如果他们必须进行必要的工作","可以，如果他们必须随行看护货物","可以，为了固定货物"],"c":"禁止在机动车载货平台上或运输空间内载人。如果这些人必须在那里进行必要的工作，则适用例外。该禁令也不适用于在施工场地内运输施工人员。"},"2.2.21-121":{"q":"你如何防止儿童在车辆行驶中打开车门？","o":["后排车门上的儿童安全锁","中控锁系统"],"c":"通过中控锁和儿童安全锁，您可以按一个按钮同时锁上所有车门。这样您就可以防止儿童在行驶中打开车门并因此受伤。"},"2.2.21-122":{"q":"你想在汽车内运送一名儿童。何时必须为此使用儿童座椅？","o":["如果儿童不满12岁且身高不足150 cm","如果儿童超过12岁且身高超过150 cm","如果儿童超过12岁且身高不足150 cm"],"c":"如果儿童未满 12 岁且身高不足 150 cm，您需要一个儿童座椅。如果您没有携带，则面临罚款。"},"2.2.21-123":{"q":"你想让一名婴儿坐在乘客座位上行驶。使用婴儿提篮时你必须注意什么？","o":["婴儿提篮必须反向于行驶方向放置","如果安装了，必须关闭乘客气囊","必须将婴儿用安全带固定在婴儿提篮内"],"c":"婴儿提篮必须逆向放置，并且必须关闭副驾驶气囊以保护婴儿。婴儿的肌肉还不够强壮，无法承受这样的碰撞。"},"2.2.21-124":{"q":"使用安全带时应注意什么？","o":["安全带不应扭转","系好后应将安全带拉紧","损坏的安全带应更换"],"c":"安全带是车内乘员在发生事故时最重要的防护装置。因此，在系好安全带时，必须注意它没有扭曲或损坏。系好安全带后，您应再拉一次安全带，以确保安全带正确贴合。如果您发现安全带损坏，必须立即修复。"},"2.2.21-125":{"q":"什么会妨碍三点式安全带发挥作用？","o":["穿着厚重的冬衣","把安全带从双臂下方穿过","未将安全带完全卡入锁扣"],"c":"为确保安全带发挥最大的保护作用，它必须正确地卡入锁扣，并从肩部和髋部上方经过。将安全带置于双臂下方可能导致伤害。此外，穿厚冬装夹克会削弱安全带的功能，因为身体和安全带之间有大量空气。"},"2.2.21-126":{"q":"出发前你应检查什么？","o":["每位乘客都已系好安全带","我能确保自己能够正确观察其他道路交通","我随身携带了车辆登记证书第二部分"],"c":"每次出发前您应检查若干事项。您应确保所有后视镜都调整正确，以便确保充分的交通观察。您还应确保所有乘车人员都已系好安全带，因为安全带是发生事故时最重要的防护装置。最好情况下，您应将登记证书第二部分存放在安全的地方，而不要放在车内随身携带。而登记证书第一部分（也称为车辆行驶证）您必须始终将原件随车携带。车辆登记文件是车辆获准参与道路交通的官方证明。"},"2.2.21-127":{"q":"关于气囊的预期保护效果，应注意什么？","o":["只有当车辆乘员处于正确的坐姿时，气囊才能发挥全部作用","不得侵入气囊展开区域","在城市内行驶时气囊可替代安全带"],"c":"气囊发挥保护作用的前提是它能够正常展开。在气囊展开期间，重要的是没有任何物体或障碍物妨碍其展开。只有当乘客直立、背部靠着座椅靠背坐着时，才能保证气囊理想的保护效果。"},"2.2.21-128":{"q":"你想用车辆运送一个人，且该人在行驶过程中必须坐在轮椅中。你必须注意什么？","o":["该机动车必须设有轮椅空间","必须使用轮椅约束系统固定轮椅","必须使用轮椅使用者约束系统固定该人"],"c":"安全运输轮椅应考虑若干事项。为此须使用专门的乘客和轮椅固定系统。此外，应有一个专门的轮椅停放位，例如在车辆上安装锚固点以固定轮椅。StVO（《道路交通法》）第 21a 条 (1)：行驶时必须系好规定的安全带；这也适用于规定的轮椅固定系统和规定的轮椅使用者固定系统。"},"2.2.21-201":{"q":"你驾驶一辆公共交通工具。允许乘客在何处上下车？","o":["在指定的公交车站","在红灯处","在出租车候客站"],"c":"您只允许在规定的站点让乘客上下车，以便能够排除一切危险。"},"2.2.21-202":{"q":"作为公共交通工具的驾驶员，当接近公交车站时你应怎么做？","o":["我平稳减速","我只在车辆停稳后才打开车门","我及时开启转向灯"],"c":"当驶近公交站点时，重要的是打开转向灯并平稳地降低车速。在公交车完全停稳之前不要打开车门。"},"2.2.21-301":{"q":"你驾驶一辆用于偶尔运送乘客的客车，须运送乘客和行李。你必须遵守什么？","o":["包括驾驶员在内，只允许运送车辆登记证书第一部分中标明的座位数那么多的人","装载行李不得导致超出允许轴荷和允许总质量","在行李妥善装载的情况下，允许总质量最多可超出10 %"],"c":"即将推出……"},"2.2.21-401":{"q":"允许如何在用于农业用途的拖车上运送人员？","o":["坐着，如果他们坐在合适的座位上","站立，如果为了随行看护货物而需要","在空载拖车上站立"],"c":"即将推出……"},"2.2.22-001":{"q":"为摩托车装载时可能需要进行哪些安全调节？","o":["提高轮胎气压","调整减震/悬挂","增大油箱容积"],"c":"增加摩托车载重时，请确保提高轮胎气压并调整底盘/悬挂。"},"2.2.22-002":{"q":"携带行李行驶时你应特别注意什么？","o":["车辆制造商使用手册中给出的推荐最高车速","重心变化对行驶操控的影响","对侧风的敏感性增大"],"c":"给摩托车增加行李会影响其在道路上的行驶表现。额外的重量会改变摩托车的重心。它会增加侧风对摩托车的影响。请确保不超过制造商建议的载行李行驶最高车速。"},"2.2.22-003":{"q":"应将重行李放置在何处？","o":["油箱包内","左右均匀放置，并尽可能放在边箱底部","车把包内"],"c":"您应将重行李尽可能靠近摩托车的重心放置，以尽量减少对其行驶表现的影响。请确保将其放在油箱包中，或均匀分配并尽量放低地放在边箱中。"},"2.2.22-004":{"q":"不正确的装载如何影响行驶稳定性？","o":["尾部装载过重会使摩托车抖动和摆动","装载分布不均会在制动时对行驶稳定性产生负面影响","没有影响"],"c":"摩托车装载不当会使其更不稳定。它会在制动时变得不稳定，并可能使其振动或摆动。"},"2.2.22-005":{"q":"为带拖车的卡车（卡车列车）装载时你必须注意什么？","o":["卡车列车含载荷的总长度不得超过20.75 m","载荷的分布方式不得影响卡车列车的运行安全","重物应尽可能放置在高处"],"c":"汽车列车（带拖车的卡车）及其装载的总长度不得超过 20.75 m，并且装载必须分配得当，使汽车列车的运行可靠性不受影响，从而不会危及任何其他道路交通参与者。"},"2.2.22-006":{"q":"带拖车的卡车含载荷的最大允许长度是多少？","o":["20.75 m","18.00 m","24.25 m"],"c":"卡车的装载，包括拖车，最长不得超过 20.75 m。"},"2.2.22-007":{"q":"你在摩托车上额外挂载了一件行李。你应考虑什么？","o":["车辆制造商可能给出的最高车速建议","摩托车重心的变化","摩托车对侧风敏感性的变化"],"c":"由于行李的原因，您的摩托车有更大的受风面积，因此更容易受到侧风的影响。额外的重量还会改变摩托车的重心。因此您应确保行李均匀分配，并相应调整您的骑行方式。车辆制造商可能会就如何根据载重调整车速给出建议。您应遵循这些建议。您可以在用户手册中找到它们。"},"2.2.22-008":{"q":"装载不当的载荷如何影响摩托车的行驶稳定性？","o":["置于尾部的重载会使摩托车在高速时摇晃和摆动","仅置于一侧的载荷会对操控产生负面影响","油箱包内的轻行李使打滑更可能发生"],"c":"摩托车后部装载过重会使前轮胎和转向承受的载荷过小。这使得车辆更容易摇摆和震动。两侧装载不均会对稳定性和操控产生负面影响。制动或过弯时，摩托车会更倾向于向较重的一侧倾斜。油箱包中的轻行李不会影响摩托车的骑行稳定性。"},"2.2.22-009":{"q":"当摩托车满载时可能需要什么？","o":["调整轮胎气压","调整底盘","调整后视镜"],"c":"如果摩托车满载，载重会对轮胎施加更大压力。因此您应检查轮胎气压。载重可能会使底盘进一步下压，因此必须重新调整。如果载重超出摩托车的范围，您还应重新调整后视镜。"},"2.2.22-010":{"q":"骑车时背背包可能影响两轮车的操控。可能导致什么后果？","o":["更易受侧风影响","重心的偏移","操控灵活性的提升"],"c":"背背包会为您提供更大的受侧风作用的面积。背背包还会使您的重心上移。这意味着您无法那么迅速地转向。"},"2.2.22-101":{"q":"卡车上带有黑色“A”的白色车牌表示什么？","o":["正在运输废弃物","正在运输危险品","由新手驾驶"],"c":"一辆挂有带黑色“A”字样的白色标牌的卡车在运输垃圾。带有黑色“A”的白色标牌必须清晰可见，卡车前后都要有。"},"2.2.22-102":{"q":"如果你想在车顶携带行李，必须注意什么？","o":["行驶操控特性会受到不利影响","不得超过允许总质量","不得超过汽车制造商（车主手册）规定的最大车顶载荷"],"c":"车顶行李会使您车辆的重心上移。这对汽车的行驶特性有显著影响。尤其是在弯道中，行驶特性会变差。车辆容易受风影响。必须确保不超过允许的车顶载荷和总质量。"},"2.2.22-103":{"q":"在车顶运送行李时必须预计到什么？","o":["车辆过弯时侧倾更大","车辆对侧风更敏感","由于重心升高，车辆行驶操控性得以改善"],"c":"车顶行李会改变车辆的重心——使其升高。这增加了翻车的危险，并且空气阻力增大。因此，当有车轮或卡车超越您时，您的车辆对侧风和气压更敏感。在弯道中，由于重心更高，行驶稳定性也会变差。您的车辆会更明显地倾斜。"},"2.2.22-104":{"q":"在车顶运送自行车时你必须怎么做？","o":["牢固固定支架和自行车","避免高速行驶","定期检查固定装置"],"c":"车顶上的自行车需要特别注意：请考虑安全规定并仔细固定。在行驶休息期间定期检查固定情况。车顶载重会改变车辆的重心，使其升高。行驶性能尤其在弯道中会变差。请避免高速行驶。"},"2.2.22-105":{"q":"在后置支架系统上运送自行车时必须检查什么？","o":["根据制造商说明，该系统是否适用于本车","系统和自行车是否固定牢靠","照明装置或车牌是否被遮挡"],"c":"检查后部承载系统是否牢固固定。同样，也要检查自行车的固定情况。如果照明装置或车牌被遮挡，必须在车辆系统末端安装技术设备，以实现充分的照明和/或安装车牌号。偏后的装载会改变车辆的重心。请检查载重的分配。"},"2.2.22-108":{"q":"夜间或能见度差时，当载荷侧向超出车辆示宽灯40 cm以上，必须如何标示？","o":["前方用白灯","后方用红灯","开启危险警示灯"],"c":"在黑暗中或能见度不佳的情况下，横向超出车辆示廓灯 40 cm 以上的货物必须用额外的灯加以标示。这些灯应安装在侧面距边缘不超过 40 cm、距路面不超过 1.5 m 处。前部需要一盏白色灯，后部您需要安装一盏红色灯。作为汽车驾驶员，您在行驶时不得打开危险警示灯。"},"2.2.22-109":{"q":"标示向后伸出载荷的红灯距路面允许的最大高度是多少？","o":["1.50 m","2.00 m","2.50 m"],"c":"安装灯的最大高度为 1.5 m。这是为了确保标示位于其他道路使用者的视野内。如果红色灯距离路面更高，它可能会被忽视。"},"2.2.22-111":{"q":"载荷伸出于车辆前方不得超过多大高度？","o":[],"c":"标示后部突出货物的红色灯，最高可安装在 2.50 m 的高度。如果更高，其他道路使用者可能会忽视它。为防止危险，规定了 2.50 m 的最大高度。"},"2.2.22-112":{"q":"在什么条件下允许载荷伸出于车辆前方？","o":["如果载荷伸出不超过50 cm且高度在2.50 m以上","如果载荷用红灯标示"],"c":"如果货物固定在 2.50 m 以上的高度，它最多可以从车辆前部突出 50 cm。此规定旨在降低因追尾碰撞货物而造成的危险和伤害风险。一般而言，货物应始终仔细固定，使其既不能滑动也不能掉落。"},"2.2.22-113":{"q":"休息时你发现其中一条捆绑带已断裂。你该怎么做？","o":["在捆绑带更换后继续行程","当载荷已由其他足够的固定装置固定时继续行程","继续行程，因为滑动的载荷会被侧板挡住"],"c":"作为汽车驾驶员，您必须确保您的货物在整个行驶过程中都得到妥善固定。如果绑带损坏，只有当其他固定装置能够确保货物妥善固定时，您才可以继续行驶。如果情况并非如此，您不得继续行驶。"},"2.2.22-114":{"q":"关于正确固定载荷的要求是否适用于所有小型运输车？","o":["适用于所有小型运输车","仅适用于具有敞开装载空间的小型运输车","仅适用于未与装载空间之间设隔板的小型运输车"],"c":"对货物妥善固定的要求无一例外地适用于所有厢式货车。偏后的装载会将车辆重心后移。结果，前轮不再受到足够的载荷，抓地力变差。这会助长危险的摆动。"},"2.2.22-115":{"q":"你想驾驶一辆允许总质量5.0 t并挂有橙色警告牌的卡车。你必须满足哪些条件？","o":["有效的ADR证书","有效的载客驾驶证","证明你此前运输过危险品的有效证明"],"c":"您需要满足的要求：除所需的驾驶证外，您还需要有效的 ADR 证书。这使您能够运输危险货物（橙色警示标志）。"},"2.2.22-116":{"q":"为使载荷适合安全公路运输做好准备时，你必须遵守什么？","o":["载荷的分布","载荷的固定","载荷固定装置的牢固安装"],"c":"载重的分配、这批货物本身的固定以及货物固定装置的备份，您都应注意，以确保安全。所有三个答案都是正确的。"},"2.2.22-117":{"q":"为车辆装载时应注意什么？","o":["超出反光器1 m以上的载荷必须标示","高度超过2.50 m的载荷向前伸出不得超过50 cm","无需固定重载"],"c":"货物在 2.50 m 以上的高度最多可以向前突出到车辆上方 50 cm。如果货物超出车辆后部反光镜 1 m 以上，末端必须用视觉方式加以标示。货物需要仔细固定。偏后的装载在较快行驶时会导致危险的摆动。对于摩托车，请确保货物在两侧均匀分配。"},"2.2.22-118":{"q":"运送长钢管时你必须确保什么？","o":["用合适的方法固定","如果后悬超过1 m，须标示","使用无前壁的车辆运送"],"c":"钢管必须用适当的手段加以固定，并且在后部突出超过 1 m 时予以标示。如果您注意到这一点，您就是安全的。"},"2.2.22-119":{"q":"载荷分布不均会如何影响车辆和操控？","o":["可能超出允许轴荷","转向特性会受到影响","燃油消耗会降低"],"c":"载重分配不均可能导致超过允许的车轴载荷，并影响转向。燃油消耗并不关键。"},"2.2.22-120":{"q":"何时会对卡车载荷产生离心力？","o":["过弯时","制动时","直线行驶时"],"c":"离心力在转弯时影响您的卡车。直行制动或没有圆周运动，因此不是决定性的。"},"2.2.22-121":{"q":"未固定的载荷在过弯时可能导致什么？","o":["造成车身损坏","使车辆更可能翻车","影响操控"],"c":"转弯时未固定的载重可能导致车身损坏，助长车辆翻车，并导致驾驶性能变差。"},"2.2.22-122":{"q":"如果你想运送该载荷，必须注意什么？","o":["必须固定","不得产生可避免的噪声","可以有单根杆件向侧面伸出"],"c":"装载您的车辆时，作为汽车驾驶员您必须确保货物牢固固定。不易辨识的物体以及堆垛、条材或板材不得从车厢内侧向伸出。货物必须以一种不产生任何可避免噪音的方式存放。"},"2.2.22-123":{"q":"你想在满载汽车的车顶运送度假行李。你必须遵守什么？","o":["使用手册中车辆制造商的车顶载荷规定","我汽车的允许总质量","车辆登记证书第一部分中载明的车顶载荷规定"],"c":"请遵守车辆制造商规定的允许车顶载荷。这可以在操作说明中找到。在登记证书第一部分中并未注明车顶载荷。不得超过车辆的允许最大质量。分配不均的载重会在制动和转弯时使行驶稳定性变差。"},"2.2.22-124":{"q":"你想运送载荷。运送时你必须注意什么？","o":["载荷在行驶中不得妨碍我","不得对车辆的行驶安全产生负面影响","载荷在行程中不得移动或翻倒"],"c":"运输货物时，您必须确保行驶中不会因它而受到妨碍，车辆的行驶安全性不受损害，并且货物在行驶中不会滑动或翻倒。"},"2.2.22-125":{"q":"汽车内应使用哪些载荷固定设备？","o":["捆绑带","安全网","止轮块"],"c":"用于汽车的货物固定工具是绑紧带和安全网。车轮挡块不包括在内。"},"2.2.22-126":{"q":"你想在车顶运送载荷。这会如何影响你汽车的操控？","o":["制动距离会延长","加速能力会降低","对横风的敏感性会降低"],"c":"车顶载货时，您的驾驶行为会影响制动距离（会变长），并且加速能力（例如超车时）会降低。"},"2.2.22-127":{"q":"可以使用什么来固定汽车内运载的载荷？","o":["行李网","张紧带","防滑垫"],"c":"防滑垫防止货物滑动。绷紧带用于将货物绑紧固定。行李网防止货物四处飞散。"},"2.2.22-128":{"q":"将行李装入汽车行李厢时你应记住什么？","o":["将三角警告牌放在易于取用的地方","将重行李放在底部","固定行李以防滑动"],"c":"在发生事故或故障时，警示三角牌应始终随手可取，以便能尽快设置三角牌。货物应加以固定，以防止其在加速、制动或急转弯时滑动。重行李应堆放在底部，使其不会掉落。"},"2.2.22-129":{"q":"如果你的行程超过100 km，经标示的载荷最多可伸出于车辆后方多远？","o":[],"c":"对于最长 100 公里的距离，货物允许突出最多 3 m。对于超过 100 公里的距离，货物向后允许突出最多 1.50 m。"},"2.2.22-130":{"q":"在车顶运送载荷时你应预料到什么？","o":["过弯时侧倾更大","对侧风反应更敏感","燃油消耗增加"],"c":"车顶装载会显著增加油耗。原因不在于重量，而尤其是顶风对油耗影响最大。由于车顶的额外载重，侧风作用到更大的面积上。这增加了侧风敏感性。此外，车辆的重心上移。因此，车辆在弯道中容易向一侧倾斜。"},"2.2.22-131":{"q":"你正用厢式货车运送家具。休息时你发现一条捆绑带已损坏。在什么条件下你可以继续行驶？","o":["已更换捆绑带","使用其他合适的载荷固定装置","以最高50 km/h继续行驶"],"c":"作为驾驶员，您有义务确保妥善固定货物。只有当您将损坏的绑紧带更换为未损坏的绑紧带或其他合适的货物固定装置后，您才可以继续运输家具。根据 StVO（《道路交通法》），适用以下规定：“第 22 条 (1) 货物，包括货物固定装置和装载装置，必须堆放并固定得当，使其即使在制动或突然避让动作时，也不会滑动、翻倒、掉落、坠落或产生可避免的噪音。(…)"},"2.2.22-132":{"q":"在后置支架系统上运送电动助力自行车时，关于拖车钩你应注意什么？","o":["后置支架系统必须设计得当","拖车钩必须具有合适的垂直载荷能力","必须适当调整汽车的轮胎气压"],"c":"在购买用于拖车挂钩的电动自行车支架之前，应先澄清几个问题。例如，我的拖车挂钩的支撑载荷是否足够，以及所选的尾部承载系统是否适用于如此大的重量？如果这两个问题都能回答“是”，并且您选择了相应的尾部承载系统，那么您必须根据额外载重调整轮胎气压。"},"2.2.22-201":{"q":"哪块警告牌安装正确？","o":["右边那块","左边那块"],"c":"因为我们需要一个 A（代表 attention/注意），所以正确的警示牌已就位。"},"2.2.22-203":{"q":"你如何判断一辆卡车超载？","o":["通过称量装载后的车辆","通过内置的轴荷测量装置","通过对装载后的车辆进行制动测试"],"c":"要确定是否超载，您可以重新称量已装载的车辆，或使用车载车轴载荷测量装置。"},"2.2.22-204":{"q":"一辆用于可换装载容器（可换箱体）的卡车允许总质量为6,000 kg。可换箱体的空载质量为1,500 kg。允许在该可换箱体中装载多大质量？","o":["4,500 kg","6,000 kg","7,500 kg"],"c":"空车质量（1500 kg）加上装载（4500 kg）= 载重量（6000 kg）。4500 kg 是正确的。换句话说，载重量（6000 kg）减去可换集装箱的空车质量（1500 kg）等于装载量（4500 kg）。"},"2.2.22-208":{"q":"何谓形状配合（形锁）固定的载荷？","o":["将载荷直接紧靠前壁和侧壁放置","载荷抵住装载区边界和已固定的垫块","与装载货物形状相适应的包装"],"c":"在形式锁合（牢固支撑）式的货物固定中，指的是将货物抵靠装载限位、固定的间隔件，以及将货物直接支撑在正面和侧面车厢壁上。包装与此无关。"},"2.2.22-210":{"q":"何谓载荷的形状配合（形锁）固定？","o":["载荷直接紧靠前壁和侧壁放置","载荷各部分之间的空隙必须用合适的填充物填满","独立放置的载荷用合适的捆绑装置绑扎固定在装载面上"],"c":"正向货物固定是指用合适的填充物封闭货件之间的空余空间，以及货物直接抵靠前端壁和侧壁。"},"2.2.22-211":{"q":"谁对载荷得到充分固定负责？","o":["运输过程中涉及的所有各方","仅驾驶员","仅装载人员"],"c":"所有运输参与者都对充分的货物固定负责。"},"2.2.22-214":{"q":"就载荷而言，谁对车辆的运行负责？","o":["驾驶员","车主","登记机关"],"c":"驾驶员和车主都对车辆的运行负责。"},"2.2.22-216":{"q":"倾倒散装货物时你必须考虑什么？","o":["车辆必须停在足够坚实的地面上","必须解锁相关安全装置，以便完全倾翻自卸车厢","只有当自卸车厢处于倾翻终点位置时才应打开侧板"],"c":"卸料时，请确保车辆停在足够坚实的地面上，并且必须解除防护装置，以便自卸车厢能够完全倾翻。"},"2.2.22-217":{"q":"为什么必须遵守载荷分布图？","o":["以防止超出轴荷","以确保保持转向能力","以便于装卸"],"c":"为避免超过车轴载荷，有必要遵守载重分配计划。这样您还能确保转向能力。"},"2.2.22-218":{"q":"载荷分布图的用途是什么？","o":["帮助实现车辆符合行驶安全的装载","避免低于车辆的轴荷下限","确定车辆的卸货顺序"],"c":"载重分配计划显示车辆必须如何装载。如果分配不均，制动性能会发生很大变化。"},"2.2.22-219":{"q":"如果你的车辆未按载荷分布图装载，可能发生什么？","o":["轮胎可能损坏","转向能力可能受到影响","其制动性能可能受到不利影响"],"c":"载重分配计划显示车辆必须如何装载。如果载重分配不均，制动性能会发生相当大的变化。会出现轮胎损坏，转向能力也会受损。"},"2.2.22-220":{"q":"在载荷分布图中可以找到哪些具体信息？","o":["关于最大允许装载极限下载荷重心的信息","关于在装载平台上固定载荷的信息","关于装载平台上载荷最大高度的信息"],"c":"载重分配计划提供关于在最大允许载重下载重重心的信息。"},"2.2.22-221":{"q":"谁对车辆上载荷的固定负责？","o":["驾驶员","托运人","收货人"],"c":""},"2.2.22-222":{"q":"什么有助于摩擦配合（力锁）载荷固定？","o":["捆绑带","防滑垫","捆绑链"],"c":"在力锁合（摩擦）式货物固定中，运输的货物通过绑扎被压紧在装载面上。这种绑扎方式也称为压紧绑扎。货物通常自由地立在装载面上，仅通过施加的增大的力加以固定。在大多数情况下，装载面与货物之间的摩擦力被增大。货物借助绑紧带、绑紧链、防滑垫或遮盖网等货物固定装置，以及借助装载面上的固定点加以固定。这样可以防止货物滑动。"},"2.2.22-223":{"q":"选择载荷固定捆绑装置时应考虑什么？","o":["载荷的形状","载荷的重量","可用的绑扎点"],"c":"除其他因素外，货物的面（表面积）和形状对于选择合适且必要的绑扎装置具有决定性作用。同样重要的是车辆的要求，例如允许的载重量和固定点。"},"2.2.22-224":{"q":"你想通过绑扎来固定载荷。你应注意什么？","o":["定期检查捆绑装置的张紧度","只对形状稳定的载荷进行绑扎固定","选择尽可能小的绑扎角度"],"c":"压紧绑扎时，使用绑扎装置将货物压紧在装载面上，以增大摩擦力并防止滑动。重要的是检查绑扎装置的张力，因为只有张力足够时才能达到必要的接触力，从而获得所需的摩擦力。此外，这种方法只适用于尺寸稳定的货物；柔性货物可能在张力下变形，这意味着预张力丧失，货物固定不再有保障。"},"2.2.22-301":{"q":"出于行驶安全的考虑，哪种更好？","o":["卡车装载，拖车空载","拖车装载，卡车空载"],"c":"由于您可以在带拖车的卡车上将部分重量装载到前部，出于行驶安全的考虑，拖车空载时更好。"},"2.2.22-302":{"q":"当你想用拖车运送动物时，必须记住什么？","o":["动物运输的特别规定","不得超过拖车的允许总质量","只可在装有气压制动器的拖车上运送动物"],"c":"您必须确保不超过拖车的允许总质量，并且在对动物运输（车）运输动物时须遵守关于动物运输的特殊规定。"},"2.2.22-303":{"q":"何时挂接的作业设备必须用红白警告牌标示？","o":["当其带有对交通构成危险的部件时","当侧向超出拖拉机示宽灯或尾灯40 cm以上时","当向后超出拖拉机尾灯1 m以上时"],"c":"当货物在牵引车的尾灯后方突出超过 1 m 时，以及当其横向超出牵引车的示廓灯或尾灯 40 cm 以上时，须安装一块红白相间的警示牌，前提是它带有交通危险部件。三个都正确。"},"2.2.22-305":{"q":"驾驶装载车辆时你有哪些义务？","o":["我有责任确保载荷不影响车辆的行驶安全","我必须根据载荷的性质调整车速","对于有倾翻风险的载荷，我必须安排一人在装载区随行看护载荷以确保其固定"],"c":"如果您驾驶一辆载货车辆，您有责任确保车辆的行驶安全性不受载重影响，并且您必须根据载重情况调整车速。"},"2.2.23-001":{"q":"如果你不穿着贴身的衣物会怎样？","o":["高速时飘动的衣物会影响行驶安全","鼓起的衣物会缩小你在后视镜中的视野","鼓起的衣物会降低空气阻力"],"c":"不宽松也不贴身的衣服在高速时会被风吹得飘动，从而降低您的稳定性。它们还可能减少您的后向视野。然而，它们不会对空气阻力产生任何影响。"},"2.2.23-003":{"q":"出发前你必须做什么？","o":["检查摩托车的行驶安全和运行安全","检查头盔面罩和贴身的衣物","检查边箱和尾箱是否固定正确"],"c":"三个都正确。请确保所有东西都妥善固定在您的摩托车上。请确保您穿着合适的服装，检查您的头盔面罩。最后，确保道路和摩托车的安全。"},"2.2.23-006":{"q":"为什么摩托车驾驶人必须佩戴合适的防护头盔？","o":["以尽可能避免头部伤害","以便更容易收听广播","以在较高速度下降低空气阻力"],"c":"需要佩戴头盔来保护您的头部免受伤害和潜在死亡。"},"2.2.23-009":{"q":"哪些物品属于摩托车驾驶人的安全装备？","o":["合适的上衣","合适的裤子","运动鞋"],"c":"合适的上衣、裤子和靴子是安全装备的一部分，可以在发生事故和受伤时保护您。运动鞋不是防护装备。"},"2.2.23-010":{"q":"骑摩托车时为什么应穿合适的靴子？","o":["即使摩托车只是在静止时翻倒，也可能遭受相当严重的脚部伤害","因天气因素导致的过冷可能损害健康","因为空气阻力降低了"],"c":"靴子不会降低空气阻力。合适的靴子是一种防护装备，可以保护您免受伤害和受寒。"},"2.2.23-014":{"q":"哪种摩托车服装能提高视觉可辨识度？","o":["亮色服装","浅色服装","深色服装"],"c":"为提高您的可见度，请穿着明亮和浅色的颜色。深色不易被看到，尤其是在夜间。"},"2.2.23-016":{"q":"为什么应定期在静止状态下用力制动？","o":["机械传动和连接部件是否处于正常工作状态","液压制动系统是否无泄漏","制动器的减速度是否足够"],"c":"静止时，请使用您的制动器，以确保系统正常工作（包括制动传动、连接和制动器本身）。"},"2.2.23-018":{"q":"严重刮花的头盔面罩有什么影响？","o":["佩戴者比平时更容易炫目","自身视线受到妨碍","在白天没有负面影响"],"c":"严重刮伤的头盔面罩会削弱您的视力，并使光线显得更强烈，有眩目的风险。"},"2.2.23-019":{"q":"检查制动灯时哪项正确？","o":["依次操作手刹和脚刹","同时操作手刹和脚刹","仅操作手刹"],"c":"请确保手制动和脚制动的制动灯分别都能正常工作。"},"2.2.23-020":{"q":"允许将行李存放在摩托车的哪些位置？","o":["边箱内或行李架上","油箱包内","均匀分布在车把左右两侧"],"c":"您可以将行李存放在油箱包、边箱（左右均匀分配）、行李架、车把上。"},"2.2.23-021":{"q":"你必须如何保护自己免受严重头部伤害？","o":["官方认可的防护头盔","钢盔","经检测的防护工作帽"],"c":"需要佩戴官方认可的保护头盔来保护您的头部免受伤害。"},"2.2.23-026":{"q":"摩托车后视镜的安装和使用适用哪些规定？","o":["必须正确固定和调节","既不得破裂也不得模糊","右侧的一个后视镜可替代回头观察"],"c":"为了能够使用您的后视镜，您必须确保它们固定良好、调整正确且能正常工作（没有裂纹、不盲）。"},"2.2.23-027":{"q":"当你的车辆机动车责任保险已失效时，需要什么？","o":["不得再在道路交通中使用","必须送交技术检测中心"],"c":"您的车辆必须投保，没有保险您不得驾驶它。"},"2.2.23-031":{"q":"什么会妨碍你听到警告信号？","o":["收音机音量开得太大","使用耳机","排气噪声过大"],"c":"其他声音，例如大声的收音机或响亮的排气管，可能会妨碍汽车驾驶员察觉重要的警告信号。此外，使用耳机通常会限制听力。这往往导致驾驶员忽视警告信号。请确保您始终能听到警告信号。"},"2.2.23-033":{"q":"你出售了一辆仍未注销登记的车辆。买方已付款。你必须做什么？","o":["立即将买方的姓名和地址告知登记机关","凭收据将车辆行驶证（Fahrzeugschein）和车辆登记证书（Fahrzeugbrief）或使用许可（Betriebserlaubnis）交给买方","从官方号牌上取下检验标贴"],"c":"如果您已出售您的已登记车辆并收到款项，请按以下步骤操作：1. 您将所有车辆文件交给新车主，以换取收据确认。2. 您向登记机关报告车辆买方的姓名和地址。这样您就能保护自己免受新车主方面的交通违规可能引起的无理索赔。3. 检验标牌留在车上。"},"2.2.23-034":{"q":"关于官方号牌，重要的是什么？","o":["必须牢固安装在规定位置","必须始终清晰可读","后号牌在夜间必须被照亮"],"c":"对于车牌号，重要的是它们安装在规定的位置。此外，它们必须易于辨认，并在黑暗中照明。"},"2.2.23-035":{"q":"当你的车辆不再受机动车责任保险承保时，需要什么？","o":["不得再在道路交通中使用","必须在登记机关办理注销登记","必须送交登记机关"],"c":"没有有效的责任保险，汽车不具备行驶资格，因此不得参与公共交通。责任保险用于处理您可能对其他车辆造成的损害。因此，无论肇事方的经济状况如何，都能保障对受害方的赔偿。如果没有责任保险，车主必须在登记机关注销该汽车。不遵守此规定将招致处罚。"},"2.2.23-036":{"q":"允许对官方号牌作哪些更改？","o":["什么都不允许","为字符加贴保护膜","粘贴彩色贴纸"],"c":"车牌号是官方证件，不得以任何方式更改。因此，请勿在您的车牌上粘贴任何薄膜或贴纸。"},"2.2.23-038":{"q":"作为自行车骑行者，出发前你必须检查什么？","o":["轮胎状况","照明","急救用品"],"c":"在开始行程前，请确保您的灯光和轮胎状况良好且工作正常。"},"2.2.23-039":{"q":"“盲区”一词指什么？","o":["即使借助车辆后视镜也无法看到的车辆周围区域","因能见度限制而车辆无法进入的市中心区域","由于我车辆转弯半径大而无法驶过的车行道区域"],"c":"在盲区中您看不到其他道路使用者。车辆周围即使借助车辆后视镜也看不到的区域，都属于此类。另外两个答案是错误的。"},"2.2.23-040":{"q":"你驾驶汽车时手机来电。如果你没有免提装置，此时你必须注意什么？","o":["必须中断行驶才能使用电话","必须关闭发动机才能使用电话","行驶中手机使用不得超过15秒"],"c":"您必须让手机继续响铃。接听或手持电话对机动车驾驶员而言通常是被禁止的，可能导致高额罚款。如有必要，请在最近方便的地点停车。先关闭发动机。只有这时您才可以拿起手机。"},"2.2.23-042":{"q":"你的摩托车后座乘客未穿着醒目服装可能导致什么后果？","o":["后车更难识别","前方车辆更难识别","对向来车更难识别"],"c":"如果您的乘客不穿高能见度的衣服（显眼的衣服），会使您在后方驾驶员眼中更不易被看到。"},"2.2.23-043":{"q":"为什么摩托车即使开启了近光灯仍可能被忽视？","o":["因为它们比汽车窄","因为摩托车若强烈加速，会极为迅速地接近","因为车上人员有时穿着不显眼的服装"],"c":"摩托车容易被忽视，因为它们体积小，如果行驶速度快且穿着不易被看到的衣服，就更是如此。"},"2.2.23-044":{"q":"骑摩托车时不穿醒目的摩托车防护服可能有什么后果？","o":["我更难被看到","我发生事故的风险增高","我可以预料没有负面影响"],"c":"如果您不穿高能见度的衣服（显眼的衣服），其他驾驶员和道路上的人会更难看到您，因此您的事故风险更高。"},"2.2.23-045":{"q":"为什么行车途中强烈建议穿着摩托车防护服？","o":["发生摔倒时可减轻伤害","雨天可防止水滑","发生事故时摩托车可免受损坏"],"c":"防护性的摩托车服在发生事故时能保护您免受伤害。它不能减少水滑（滑水）现象，也不能保护摩托车。"},"2.2.23-046":{"q":"关于“盲区”一词，哪些说法正确？","o":["对自行车骑行者特别危险","即使借助后视镜也看不到","由于转弯半径原因无法驶过"],"c":"在盲区中您无法借助后视镜看到。这对骑行者尤其危险。这与能否在盲区行驶无关，是错误的。"},"2.2.23-047":{"q":"白天为使你在道路交通中尽可能早地被看到，允许使用哪些灯光？","o":["近光灯","日间行车灯","示宽灯"],"c":"白天为了保持可见，您可以使用近光灯和日间行车灯。"},"2.2.23-048":{"q":"你想驶出停车位驶上道路。你必须特别注意什么？","o":["注意在车辆周围玩耍的儿童","注意行驶中的交通","注意我的车辆大幅甩出"],"c":"您还应特别留意车辆附近的玩耍儿童。留意您的车辆可能向外摆动的部分以及车流情况。三个都正确。"},"2.2.23-049":{"q":"为什么不穿摩托车防护服骑行有风险？","o":["受伤风险增高","对天气因素的保护更少","发生损害事件时可获得的保险保障更少"],"c":"穿着防护性的摩托车服会降低发生事故时受伤的风险，并且还能保护您免受天气影响。如果发生事故，如果您没穿防护服，保险赔付将会减少。"},"2.2.23-050":{"q":"为什么应穿着高可视性颜色的摩托车防护服？","o":["因为这样别人能更好地看到我","因为这样降低事故风险","因为这样即使我的灯坏了我也能开回家"],"c":"穿着高能见度的颜色会使您更容易被看到，从而降低事故风险。"},"2.2.23-051":{"q":"作为摩托车驾驶人，白天你应怎么做才能让自己更容易被他人看到？","o":["穿着高可视性的摩托车防护服","开启近光灯或日间行车灯行驶","开启远光灯行驶"],"c":"为了在白天更易被看到并降低事故风险，您应穿着高能见度的防护服，并使用近光灯或日间行车灯。"},"2.2.23-052":{"q":"你想在城镇内道路右转。此处可能出现哪些风险？","o":["未看到直行的自行车骑行者","未看到行人","因转弯半径过大而危及对向来车"],"c":"3 个答案是正确的。既有直行时忽视骑自行车者的危险，也有危及行人和因转弯弧度过大而妨碍对向来车的危险。"},"2.2.23-053":{"q":"作为车主，你必须向相关登记机关报告哪些变更？","o":["我的住址","我的姓名","我的第三方责任保险"],"c":"如果您更改姓名或居住地，必须通知车辆登记机关。但是，您不必申报责任保险中的变更。"},"2.2.23-054":{"q":"你是一辆已登记许可车辆的新车主。你必须做什么？","o":["将所有权变更告知登记机关","向登记机关提交该车辆存在责任保险的证明","通常在所有权变更时安排一次车辆行驶安全检查"],"c":"更换车主时，您无需进行整车检验。您必须将车主变更一事告知机动车牌照管理局，并向其提供一份第三方责任险。"},"2.2.23-055":{"q":"你应定期检查头盔面罩。为什么刮花后应更换它？","o":["因为否则我在夜间会炫目","因为否则我的视线会受到限制","因为我的面部应始终可被辨认"],"c":"严重刮花的头盔面罩会削弱您的视野，并使光线被更强烈地感知，从而存在炫目风险。"},"2.2.23-056":{"q":"骑摩托车时若未穿着合适的摩托车防护服，你应预料到什么？","o":["发生摔车时我受伤的风险更大","我对天气因素影响的防护较差","我应预料到发生事故时我的保险赔付会减少"],"c":"穿着摩托车防护服可降低发生事故时的受伤风险，同时还能为您抵御天气影响。发生事故时，如果您未穿着防护服，保险赔付将会减少。"},"2.2.23-057":{"q":"你想使用安装在摩托车上的导航设备。你应注意什么？","o":["在摩托车静止时输入目的地","尽可能避免在行驶中操作该设备","使用集成在耳机中的语音输出功能"],"c":"为了能够完全专注于行车，您应在静止状态下使用安装在摩托车上的导航系统（输入目的地），行驶中尽可能不要操作该设备；如有配备，应使用通过耳机的语音播报功能。"},"2.2.23-058":{"q":"合适的摩托车防护服应包括哪些？","o":["贴身合体的摩托车夹克","护背","低帮鞋"],"c":"摩托车防护装备包括鞋子、手套、上衣、裤子和头盔。"},"2.2.23-059":{"q":"骑摩托车时为什么应穿合适的摩托车靴？","o":["如果摩托车在静止时翻倒，可能造成严重的脚部伤害","意外保险索赔可能被减少","车辆的操作可能因天气因素受到限制"],"c":"翻倒时脚部可能受伤。恶劣天气条件下车辆操控可能受到限制。发生事故时保险公司可能拒绝赔付。"},"2.2.23-060":{"q":"为什么应更换刮花的头盔面罩？","o":["限制视线","加剧眩光","会使面罩更容易起雾"],"c":"您会被其他光线强烈炫目，同时能见度也受到限制。"},"2.2.23-061":{"q":"你必须怎么做才能保护自己免受头部伤害？","o":["合适且贴合良好的摩托车头盔","保养良好的摩托车帽","经官方检测的工作安全帽"],"c":"摩托车头盔可保护您免受头部伤害；发生事故后，您必须更换头盔。"},"2.2.23-062":{"q":"如何确保摩托车上的后视镜正常工作？","o":["必须正确调节","不得损坏","不得侧向伸出超过车把"],"c":"两轮车上的后视镜必须按照骑行者进行正确调整——以便骑行者能够观察到所有重要的交通情况。损坏的后视镜不算处于正常工作状态。为了能更好地覆盖必要区域，摩托车上的后视镜可以侧向超出车把末端。"},"2.2.23-063":{"q":"行驶中什么会导致你听不到警告信号？","o":["听大声的音乐","通话中分散注意力","以低发动机转速行驶"],"c":"过大的噪音，例如听音量过大的音乐，会淹没警示信号，导致您对其反应过晚。\n因打电话造成的分心，也可能使您过晚或完全听不到警示信号。"},"2.2.23-064":{"q":"骑摩托车时佩戴全盔有什么好处？","o":["伤害","昆虫","淋湿"],"c":"全盔比其他头盔款式提供更多保护，因为全盔是完全封闭的。下巴与头盔连成一体，无法被向上顶起，因此您能得到良好的防伤害保护。完整的面部防护可让风、雨和昆虫远离您的眼睛。面罩保护您的眼睛免受风雨侵袭，您的视野也不会因天气而受到限制。"},"2.2.23-065":{"q":"起步前你应检查两轮车的什么？","o":["灯光是否正常工作","制动器是否正常工作","点火正时设置"],"c":"您每次出发前都应检查两轮车的车灯是否正常工作。出发前检查刹车是否正常工作同样必不可少。"},"2.2.23-066":{"q":"骑摩托车时，什么能使你更容易被其他道路使用者看到？","o":["穿着高可视性服装","夜间穿着带有反光细节的服装","开启远光灯行驶"],"c":"如果您穿着醒目的服装，例如颜色鲜艳的摩托车夹克或反光夹克，您对其他道路使用者来说会更显眼。"},"2.2.23-067":{"q":"摩托车靴必须满足哪项标准？","o":["具有防滑鞋底","覆盖脚踝以上","宽松合脚"],"c":"注意靴子的贴合度，靴子应合脚并高过脚踝，同时不限制您的活动自由。\n您还应确保靴子具有防滑鞋底，以便在脚踏上有良好的抓地力。"},"2.2.23-068":{"q":"摩托车手套必须满足哪项标准？","o":["贴身合手","提供良好的抓握力","由耐磨材料制成"],"c":"摩托车手套应贴合但不宜过紧。您的手指应能略微弯曲，而布料不会绷紧。\n手套应让您有良好的抓握力，以便您毫无问题地操作刹车杆和离合器杆。\n请选择由皮革或特殊纺织品等耐磨材料制成的摩托车手套，以便在摔倒或发生事故时更好地防止擦伤和烫伤。"},"2.2.23-069":{"q":"你骑一辆最高设计车速25 km/h的轻便摩托车。你需要如何保护自己免受头部伤害？","o":["必须用合适且贴合的摩托车头盔保护头部","必须用合适且贴合的自行车头盔保护头部","以步行速度行驶时不必保护头部"],"c":"由于轻便摩托车行驶速度可超过 20 km/h，您必须佩戴合适的摩托车头盔，以便在交通中以该速度充分保护您的头部。"},"2.2.23-070":{"q":"购买摩托车夹克和摩托车裤时你应注意什么？","o":["护具必须位于正确的位置","我注意安全标准标识","A级防护提供最高防护等级"],"c":"购买摩托车上衣和摩托车裤时，您应始终注意安全标准标识，以便获得充分的保护。\n您还应确保护具正好位于其预定位置，以便在摔倒时为您提供理想的保护。"},"2.2.23-101":{"q":"对于带帆布篷的车辆必须记住什么？","o":["帆布篷不得妨碍驾驶员通过外后视镜观察后方","带有高帆布篷上部结构的空载拖车对侧风特别敏感","车辆装有帆布篷时，载荷无需特别固定"],"c":"对于带篷布（帆布罩）的车辆，您必须注意不要影响后视野。尤其是在空载且篷布较高的拖车上，存在侧风风险。"},"2.2.23-103":{"q":"驾驶非本人车辆时你必须调节什么？","o":["座椅、头枕、安全带","内后视镜、外后视镜","单次日程计数器"],"c":"为了安全驾驶非本人的车辆，您必须按照自己的需求调整驾驶员专属设备，如座椅、安全带、头枕和后视镜。您可以重置里程表，但并非必须。"},"2.2.23-104":{"q":"你如何防止手动变速箱的汽车在下坡处溜车？","o":["拉紧驻车制动器","挂入一挡或倒挡","将换挡杆置于空挡位置"],"c":"您可以通过挂入低档位（例如一档或倒档）来防止手动挡汽车溜车。使用驻车制动器，并且不要将变速杆置于空档位置。"},"2.2.23-105":{"q":"你如何防止自动变速箱的汽车在下坡处溜车？","o":["拉紧驻车制动器","将选挡杆置于“P”位","将选挡杆置于“N”位"],"c":"您可以通过启用驻车制动器并另外将选档杆置于驻车档 P 来防止自动挡汽车溜车。您不得选择 N 档，因为这等同于手动挡汽车的空档。"},"2.2.23-106":{"q":"倒车时你必须怎么做？","o":["主要向后观察；同时注意前方和侧方的交通状况","特别专注且缓慢地行驶","绝不在未开启危险警示灯的情况下行驶"],"c":"作为汽车驾驶员，您只能非常缓慢且极其谨慎地倒车。倒车时，您主要应向后以及向其他各个方向观察。倒车时您无需开启危险警示灯。"},"2.2.23-107":{"q":"什么会妨碍你的视线？","o":["载荷","磨损的雨刮片（形成条纹）","有污渍的车窗"],"c":"如果车窗玻璃变脏、因雨刷磨损而产生条纹，或者货物遮挡视线，您的视野都可能受到影响。"},"2.2.23-113":{"q":"一辆带惯性制动器的单轴房车停在下坡处。你必须如何固定以防止其溜车？","o":["拉紧驻车制动器","在车轮前方放置止轮块","在同一车轮的前后各放置一个止轮块"],"c":"为了保护您的房车不溜车，您必须在车轮前放置车轮挡块，并另外用驻车制动器固定拖车。"},"2.2.23-114":{"q":"你想倒车。你必须确保什么？","o":["必要时我必须让他人指挥我","我必须注意向后伸出的载荷","我使用倒车摄像头就足够了"],"c":"为了不危及他人，您应留意必要时让人指挥来应对向后突出的装载物。仅靠倒车摄像头是不够的。"},"2.2.23-115":{"q":"你在拖拉机上挂接了设备。如果想在公共道路上行驶，你必须做什么？","o":["熟悉关于该设备运输位置的相关说明","有效遮盖危险部件","开启危险警示灯行驶"],"c":"您必须了解拖拉机所挂农机具在运输位置方面的相应要求，并有效地遮盖危险部件，以免危及他人。警示灯并不属于其中。"},"2.2.23-116":{"q":"你想把卡车从一块场地倒车驶上道路。你必须做什么？","o":["必要时必须让他人指挥我","必须注意人行道上接近的道路使用者","不必打转向灯"],"c":"倒车时，如有必要，您必须让人指挥，以排除对其他道路使用者的危险。人行道上的交通参与者也包括在内。"},"2.2.23-117":{"q":"你的车辆被雪覆盖。起步前你必须做什么？","o":["清除车窗上的冰和雪","清除后视镜上的冰和雪","清除车顶上的冰和雪"],"c":"开车前，您必须清除车辆上的冰，以免危及其他道路使用者。请检查所有车窗、后视镜以及车顶。"},"2.2.23-118":{"q":"你的车辆被雪覆盖。起步前你必须做什么？","o":["清除车窗和后视镜上的冰和雪","包括白天在内，清除照明装置上的冰和雪","让发动机预热"],"c":"作为汽车驾驶员，您必须在每次行车前确保排除对其他道路使用者的风险。因此，白天您也必须清除所有车窗、后视镜以及车顶的冰雪。不得利用发动机来给车辆预热。"},"2.2.23-119":{"q":"调节汽车头枕时应注意什么？","o":["头顶应与头枕上边缘齐平","后脑与头枕之间的间距应尽可能小","头枕上边缘应与上部颈椎相接"],"c":"正确调整头枕可以减轻车辆突然运动时对颈椎的作用力。因此，头枕是事故中保护车内乘员的直接防护装置。可电动或手动调节高度和倾斜度的头枕，应调整到头部的头顶高度与头枕上边缘相齐。为了使其保护功能充分发挥作用，您应将头枕倾斜，使您的后脑与头枕之间的距离不超过几厘米。"},"2.2.23-120":{"q":"即使有免提装置，何时也不应使用电话？","o":["当电话交谈令人紧张时","在复杂的交通状况下","如果这会分散我的注意力"],"c":"尽管有免提系统，您在艰难的通话中仍可能变得紧张和焦虑。您会更关注通话对象，而对路面的注意力则会减少。分心可能导致您遗漏交通中的情况，无法足够迅速地做出反应。在复杂的交通情况下，您也应避免使用手机。"},"2.2.23-121":{"q":"你想把安装在机动车上的智能手机用作导航设备。你应注意什么？","o":["在车辆静止时输入目的地","尽可能避免在行驶中操作该设备","使用该设备的语音输出功能"],"c":"为保护自己，您应在车辆静止时输入目的地，并尽可能在行驶中不要操作该设备。使用设备的语音播报功能。这样您就不会分心，可以专注于交通。"},"2.2.23-122":{"q":"行驶中你接到电话。你必须注意什么？","o":["为此不得手持电话","使用电话只需短暂瞥一眼","此处使用电话不得超过7秒"],"c":"如果使用手机会使您过于分心以致影响交通，则禁止使用。拿起手机并看显示屏时，这种情况必然会发生。"},"2.2.23-123":{"q":"你计划用机动车进行一次长途出行。出发前你应检查车辆的什么，以免危及自己和他人？","o":["轮胎","前照灯设置","雨刮器是否正常工作"],"c":"您应定期检查轮胎，因为磨损、损坏或气压调整不当以及胎纹深度不足都会构成重大的安全风险。\n胎纹最小深度为 1.6 mm。\n此外还应检查前照灯是否有缺陷以及其设置是否正确。例如，设置过高的前照灯会使对向来车炫目。\n每次行车都应确保清晰视野。这不仅包括确保挡风玻璃没有污物，还包括仍要有足够的玻璃水。"},"2.2.23-124":{"q":"汽车头枕的主要功能是什么？","o":["提高乘员的安全性","改善坐姿","在后排座位上替代安全带"],"c":"在急刹车或发生事故时，头枕可减轻对乘员颈椎的作用力。"},"2.2.23-125":{"q":"行驶中，你车辆挡风玻璃内侧开始起雾。你如何应对？","o":["开启空调系统","以最大风量将气流引向挡风玻璃","如果室外湿度高，打开车窗"],"c":"通过加大挡风玻璃处的空气循环，您可以防止挡风玻璃起雾。您也可以开启空调，空调会干燥空气，有助于去除挡风玻璃上的水汽。"},"2.2.23-126":{"q":"你的汽车被雪覆盖。出发前你需要做什么？","o":["清除车牌上的雪","清除车顶上的雪","清除照明设备上的雪"],"c":"开车前，您必须清除整辆车上的积雪，因为积雪可能在行驶中掉落并危及其他道路使用者。此外，积雪可能在您刹车时滑到挡风玻璃上，遮挡您的视线，使您完全无法采取行动。还要清除照明设备上的积雪，以便其他道路使用者能及时看到您，并使您在昏暗的照明条件下也拥有足够的视野。\n此外，请确保没有积雪覆盖您的车牌。如果车牌无法辨认，您将面临行政违法和罚款。"},"2.2.23-127":{"q":"起步前你必须把机动车的哪些部位完全清除干净冰雪？","o":["挡风玻璃","外后视镜","侧窗"],"c":"开车前，您必须清除整辆车上的积雪，因为积雪可能在行驶中掉落并危及其他道路使用者。此外，积雪可能在您刹车时滑到挡风玻璃上，遮挡您的视线，使您完全无法采取行动。"},"2.2.23-128":{"q":"你想在冬季天气条件下出行。你需要注意什么？","o":["脱落时会引发事故","脱落时会损坏其他车辆","脱落时会妨碍你自己的视线"],"c":"开车前，您必须清除整辆车上的积雪，因为积雪可能在您行驶时掉落，危及其他道路使用者，最坏情况下还会引发事故。此外，积雪可能在您刹车时滑到挡风玻璃上，遮挡您的视线，使您完全无法采取行动。"},"2.2.23-201":{"q":"你如何防止两轴卡车在陡坡上溜车？","o":["拉紧驻车制动器","在后轮下方放置一个止轮块","使用缓速器"],"c":"为防止在陡坡上溜车，您应拉紧驻车制动器，并在一个后轮处放置车轮挡块。两轴卡车的持久制动器在陡坡上不起作用。"},"2.2.23-202":{"q":"你如何防止两轴公共汽车在坡道上溜车？","o":["拉紧驻车制动器","在后轮下方放置一个止轮块","启用公交站制动器"],"c":"即将推出……"},"2.2.23-212":{"q":"你如何降低盲区造成的危险？","o":["以短间隔观察后方交通","只有在确信车辆旁没有道路使用者时才转弯","快速转弯"],"c":"通过观察后方交通，可以减小盲区。只有当您确定旁边没有其他道路使用者时再转弯，才能实现减小盲区。快速转弯是不正确的。"},"2.2.23-213":{"q":"当你从一块场地倒车驶入街道时，你如何确保车辆后方的交通区域安全？","o":["请人在车辆后方守护道路区域","开启危险警示灯","多次鸣喇叭"],"c":"您可以通过一名指挥人员来清空交通空间。鸣笛或开启危险警示灯并不属于其中。"},"2.2.23-214":{"q":"用松散散装货物装载车辆时你必须注意什么？","o":["如果可能在途中被吹散，须覆盖","装载方式须使其在途中不会从尾门掉落","在装载面上尽可能靠后放置"],"c":"装载松散散装物料时，如果散料可能在行驶中被吹落，就必须对其进行遮盖，并且装载方式要保证其在行驶中不会从侧面掉落。"},"2.2.23-215":{"q":"你想为车身除冰。适合此用途的设备是什么？","o":["除冰平台","除冰龙门架","带安全带和后部防护栏的除冰梯"],"c":"您可以使用所有第三种除冰方式、除冰平台，或带安全带和背部护圈的除冰梯。"},"2.2.23-216":{"q":"长时间停车后，你想继续行驶。你应怎么做？","o":["我应检查车下没有儿童","我须目视检查车辆状况","我须检查载荷是否固定"],"c":"3 个答案都正确。道路交通安全是首要任务。因此，请检查车下是否有儿童。请目视检查车辆状况，并通过固定货物进行检查。"},"2.2.23-217":{"q":"你在机动车上安装了前置的、向前伸出的挂装设备。你必须注意什么？","o":["在我的视线受影响的场合，安排合适的人为我指挥","行驶中考虑改变后的车辆尺寸","有效遮盖前置挂装设备的危险部件"],"c":"由于您前置的前挂机具很占空间，行驶时必须考虑车辆已改变的尺寸。在视野受限处可由合适的人员进行引导，并有效遮盖前挂机具的危险部件。三个答案都正确。"},"2.2.23-218":{"q":"你在服务区休息后想继续行程。重新出发前你应检查什么？","o":["我的脚坑内没有散放的物品","所有车门都已正确关闭","所有乘客都已就座"],"c":"休息结束后，您应确保脚部空间内没有松散物品。您还应提醒并检查所有乘客都已坐好在自己的座位上。还要检查所有车门是否已正确关闭。"},"2.2.23-219":{"q":"你如何清除车辆结构上的冰雪？","o":["使用除冰平台","使用带足够坠落防护的除冰梯","用合适的工具（如扫帚）从内侧顶推篷布结构"],"c":"给车辆除冰时，务必使用合适的辅助工具，如除冰平台或具有足够防坠落保护的除冰梯，以将坠落风险降至最低。\n用合适的工具从内部顶推篷布结构，可以在无需爬上顶部的情况下使冰和雪松动，这同样能降低事故风险。"},"2.2.23-301":{"q":"当你想挂接拖车时，就灯光而言必须记住什么？","o":["如果拖车侧向超出牵引车示宽灯40 cm以上，拖车必须有自己的示宽灯","牵引车与拖车必须具有相同的电压。插头与插座必须正确连接","如果拖车电压较低，牵引车与拖车的电压可以不同"],"c":"关于照明，在拖车挂接时，您应确保牵引车与拖车的电压相同，并且插头与插座必须正确连接。此外，如果拖车横向超出牵引车示廓灯 40 cm 以上，它必须配备自己的示廓灯（侧标志灯）。"},"2.2.23-302":{"q":"你拖车的篷布结冰。起步行驶时可能发生什么？","o":["制动时气管和电缆严重损坏","人员遭受危及生命的伤害","严重损坏其他车辆"],"c":"当拖车的篷布结冰时，制动过程中掉落的冰块可能会严重损坏车上的气路和电路管线，造成人员重伤，并使其他车辆严重受损。请清除篷布上的冰。"},"2.2.23-401":{"q":"一辆带惯性制动器和转盘转向的两轴拖车停在坡道上。必须如何固定以防溜车？","o":["拉紧驻车制动器","在后轮下方放置一个止轮块","在挂钩高度处支撑叉形牵引杆"],"c":"即将推出……"},"2.2.23-402":{"q":"你在牵引车上安装了双胎。你必须记住什么？","o":["如果轮胎侧向超出灯光40 cm以上，夜间必须在最外侧加装灯","如果因双胎使牵引车宽度超过2.75 m，必须用警告牌标示该超宽","牵引车宽度即使安装双胎也不得超过2.55 m"],"c":"即将推出……"},"2.2.23-403":{"q":"在哪些情形下我可以允许自行车骑行者被拖带？","o":["在任何情况下都不允许","如果我的行驶速度不超过步行速度","如果我在车流较少的道路上行驶"],"c":"拖拽骑行者对您和骑行者双方都危险，并且是不允许的。"},"2.2.23-404":{"q":"作为轻便摩托车驾驶人（非轻型轻便摩托车），你必须采取什么措施防止头部伤害？","o":["合适的防撞头盔","经认证的自行车头盔","经认证的建筑工地安全帽"],"c":"为保护头部免受伤害，需要佩戴合适的头盔。骑行头盔或建筑工地安全帽既不合法，也不足够。"},"2.2.23-406":{"q":"行驶中禁止谁在没有免提装置的情况下使用手机？","o":["小汽车","卡车","摩托车"],"c":"汽车驾驶员只有在使用免提设备的情况下，才可以在行驶中使用手机和车载电话。一旦您需要拿起或握着手机才能通话，在行驶中打电话就是被禁止的。"},"2.2.23-407":{"q":"你想在拖拉机上挂接设备。在哪些情况下你必须特别小心？","o":["侧向伸出于车辆侧面","向车辆后方伸出很远","向车辆前方伸出很远"],"c":"当机具从您的车辆向后伸出很远，或者向前伸出很远并向侧面突出时，您应特别谨慎。同样，三个答案都正确。"},"2.2.23-408":{"q":"骑摩托车时，你如何帮助其他道路使用者更好地、尽早地看到你？","o":["穿着醒目的服装","天黑后穿着反光服装","开启远光灯行驶"],"c":"夜间穿着高可视性服装（醒目服装）和反光服，会增加您对道路上其他人的可见度。穿着深色服装且没有反光服，会使您在道路上难以被看到。"},"2.2.23-409":{"q":"骑摩托车时哪些物品属于你的防护服？","o":["合适的防撞头盔","合适的手套","合适的油箱包"],"c":"夜间穿着高可视性服装（醒目服装）和反光服，会增加您对道路上其他人的可见度。穿着深色服装且没有反光服，会使您在道路上难以被看到。"},"2.2.23-410":{"q":"骑摩托车时哪些物品能提高安全性？","o":["护背","专用摩托车服装","尾箱"],"c":"专用摩托车服装（例如夜间高可视、反光的装备）和护背会提高您的安全性，并降低受伤风险。"},"2.2.23-411":{"q":"你为摩托车安装了油箱包和侧边箱。你必须确保什么？","o":["不得超过允许总质量","应根据更大的装载重量调整轮胎气压","必要时应根据更大的载荷调整后轮悬挂"],"c":"给摩托车装载行李包和边箱时，请确保不超过车辆总质量限值，并因额外重量而调整后轮悬挂以及轮胎气压。"},"2.2.23-412":{"q":"你想驾驶带挂接附属设备的农用拖拉机。起步前你必须注意什么？","o":["附属设备必须置于运输位置并加以固定","必须遵守最大允许轴荷","单轮制动的踏板必须解除连接"],"c":"将机具置于运输位置并加以固定，使其不构成危险。注意最大允许轴荷。"},"2.2.23-413":{"q":"你驾驶一辆带挂装器具的农用拖拉机。结束田间作业后，你想驶上公共道路。你必须首先检查什么？","o":["拖拉机与挂装器具之间的连接装置","挂装器具用于道路行驶的运输位置","照明系统的状况和正常工作"],"c":"用于道路行驶时，您必须检查机具的运输位置，以及拖拉机与机具之间的连接装置。此外，还要检查照明设备的状况和功能。"},"2.2.23-414":{"q":"你驾驶一辆带挂接设备的拖拉机。结束田间作业后，现在你想驶上公共道路。你应首先注意什么？","o":["单轮制动的脚踏板已锁止","挂接设备处于运输位置","已安装必要的警告板以标示车辆宽度"],"c":"在道路上驾驶带悬挂机具的拖拉机之前，请检查机具是否处于运输位置。此外，各个车轮制动器的踏板必须锁定，并且必须安装必要的警示标志以指示车辆宽度。"},"2.2.26-102":{"q":"你意外地在人行横道上停下。你该怎么做？","o":["稍微向前或向后移动，以尽快让出人行横道","移到人行道上一半以让出人行横道","即使后方车行道畅通，也绝不倒车"],"c":"为避免给行人带来危险，人行横道必须保持畅通。因此，您需要尽快清空人行横道。在交通状况允许的范围内向前或向后行驶。请注意其他道路使用者。不要在人行道上行驶。人行道专供行人使用。"},"2.2.29-001":{"q":"参加非法道路飙车可能导致什么？","o":["发生严重道路交通事故","对车辆驾驶员判处监禁","吊销车辆驾驶员的驾驶证"],"c":"参与非法道路赛车可能导致严重的交通事故，并可能导致驾驶员被判处监禁以及吊销驾驶证。"},"2.2.29-203":{"q":"一辆宽2.50 m的机动车装载了大件货物，其侧向超出侧灯和尾灯50 cm以上。运送该载荷时必须记住什么？","o":["超宽载荷必须在前方和后方标示","必须随身携带道路交通管理机关的特许证","如果使用黄色旋转警示灯，载荷即可照常运送"],"c":"如果您的货物横向超出前后示廓灯 50 cm，请务必对货物前后进行标记，并携带道路安全管理部门颁发的特别许可。"},"2.2.29-204":{"q":"一台宽3米的工程机械要在公共道路上运输。在什么条件下你可以执行该运输？","o":["载荷必须标示","主管机关已签发该运输的许可证","载荷无需标示"],"c":"在公共道路上使用您 3 米宽的工程机械时，您必须对货物进行标记，并且必须向主管机关申请并获得运输许可。"},"2.2.29-205":{"q":"某车辆超过了法定最大质量和尺寸限制。想在公共道路上驾驶该车辆时适用什么规定？","o":["需要一份补充许可证","可能被规定须配备护送车辆","车辆行驶路线可自由选择"],"c":"持有特别许可，您可以由一辆护送车陪同按规定行驶。这需要一份额外的许可。路线不能自由选择。"},"2.2.30-101":{"q":"周日和法定节假日禁行令在什么时段之间适用？","o":[],"c":"对总质量超过 7.5 t 的卡车以及所有无论总质量为多少但牵引拖车的卡车，周日和公共假日 0 点至 22 点禁止行驶。"},"2.2.30-102":{"q":"周日和法定节假日禁行令适用于哪些车辆？","o":["允许总质量超过7.5 t的卡车","所有带拖车的卡车","带拖车的牵引车"],"c":"超过 7.5 吨的卡车以及带拖车的卡车在周日和公共假日不得在公共道路上行驶。但拖车可以由拖拉机牵引。"},"2.2.30-103":{"q":"哪些从事商业或有偿货物运输的机动车禁止在周日和法定节假日行驶？","o":["允许总质量超过7.5 t的卡车","牵引拖车的卡车","牵引拖车的小汽车"],"c":"周日和公共假日的行驶禁令适用于 C 类驾照，即带拖车的卡车或最大允许总质量超过 7.5 吨的卡车。小汽车仍可行驶。"},"2.2.30-201":{"q":"德国夏季假期交通规定适用于哪些用于有偿或收费货物运输的车辆？","o":["允许总质量超过7.5 t的卡车","带拖车的卡车","拖拉机"],"c":"《假日出行条例》适用于最大允许总质量超过 7.5 t 的从事商业性或收费货物运输的卡车，以及带拖车的卡车。"},"2.2.30-202":{"q":"德国夏季假期交通规定中的禁行令何时适用？","o":[],"c":"在 7 月和 8 月的所有周六 7 点至 20 点，您需遵守《假日出行条例》规定的行驶禁令。此外还叠加周日的行驶禁令。"},"2.2.30-203":{"q":"你驾驶一辆允许总质量18 t的卡车。在周日和法定节假日，有偿货物运输的禁行令在什么时段适用？","o":[],"c":"对于收费货物运输或经营性出行，行驶禁令适用于最大允许总质量 18 t 的卡车，时间为 0 点至 22 点。"},"2.2.30-204":{"q":"你想以商业方式或收费方式运输货物。假期行驶规定适用于哪些车辆或汽车列车？","o":["允许总质量超过7.5 t","拖车","允许总质量不超过7.5 t"],"c":"假日规定适用于所有最大允许总质量超过 7.5 吨的卡车以及带拖车的卡车。"},"2.2.32-101":{"q":"你（例如从田地或建筑工地）驶入公共道路并严重弄脏道路。谁负责清除这一交通障碍？","o":["你，因为是你造成的","主管道路建设机关","居住在该路段沿线的人员"],"c":"如果您因驶离未铺装区域而严重污染道路，那么作为污染者，您必须对其进行清理。"},"2.2.32-102":{"q":"为避免因从车上掉落的设备或载荷危及他人，你必须怎么做？","o":["自己清除这些部件","守护危险点并立即通知道路管理部门或警察","继续行驶并通知最近的市政机关"],"c":"对于掉落在车行道上并危及其他道路使用者的任何物体，您必须立即清除。请对危险区域进行防护。如有必要，请联系警方或道路服务部门。"},"2.2.32-203":{"q":"你的车辆在车行道上留下了大量污物，对道路交通构成危险。你必须怎么做？","o":["立即清除污物","在清洁完成前妥善标示危险点","如果危险点易于识别则什么也不做"],"c":"如果您立即清除污染物，并对清除时产生的危险点进行充分标记，下列道路使用者将会感谢您。在危险点易于识别的情况下，什么都不做是错误的。"},"2.2.32-204":{"q":"驾驶车辆驶出建筑工地时你必须做什么？","o":["清洁轮胎和照明装置","清除夹在双胎之间的石块","确保载荷不会掉落"],"c":"驶离建筑工地时，您应确保没有货物掉落，并清洁轮胎和照明设备。还要清除双胎之间夹住的石块。三个答案都正确。"},"2.2.32-205":{"q":"当你驾驶车辆驶离建筑工地时应如何做？","o":["清洁照明设备","清除夹在双胎之间的石块","确保装载的散装货物已妥善覆盖"],"c":"驶离建筑工地时，清洁照明设备很重要，以确保您对其他道路使用者清晰可见，且不损害道路交通安全。清除夹在双胎之间的石块，可防止它们在行驶中被甩出，从而损坏其他车辆或引发事故。此外，装载的散装物料必须充分遮盖，以防止物料在行驶中掉落到道路上，从而对后续交通构成危险。这些措施旨在保护所有道路使用者，并有助于防止道路交通中的污染和危险。"},"2.2.32-401":{"q":"为避免弄脏车行道，你必须做什么？","o":["离开田地前清除轮胎上的松散泥土","离开田地前清洁作业设备","下雨时只使用带双胎的牵引车"],"c":"即将推出……"},"2.2.32-402":{"q":"驾驶农用车辆时你无法避免弄脏车行道。你必须怎么做？","o":["立即采取措施清洁被弄脏的区域","在污物清除前充分标示危险点","用三角警告牌守护危险点，直到雨水将污物冲走"],"c":"即将推出……"},"2.2.32-403":{"q":"你用农用车辆弄脏了公共道路。这危及或妨碍了交通。你必须怎么做？","o":["立即清除此类污物","在污物可被清除前充分标示被弄脏的区域","始终向公共秩序机关报告此类弄脏行为"],"c":"清理该区域并进行明显标记，以消除危险。"},"2.2.34-001-M":{"q":"在此情形下正确的做法是什么？","o":["我像之前一样继续行驶","我立即大力制动","我拍摄事故现场的照片"],"c":"可以看出事故现场已经得到了充分的防护。因此，您不应急刹车，因为在这种情况下这样做是不必要的。强烈的减速只会增加发生进一步事故（尤其是追尾碰撞）的风险，因为后方的驾驶员不会料到有刹车动作。行驶中拍摄事故是被禁止的。"},"2.2.34-002-M":{"q":"现在正确的做法是什么？","o":["我降低车速","我尽可能靠左继续行驶","我像之前一样继续行驶"],"c":"右侧车道上发生了事故，您正驶向尚未得到防护的事故现场。由于情况对您来说并不完全清楚，您必须降低车速。尽量向左行驶，与右侧车辆保持足够的距离。"},"2.2.34-003-M":{"q":"现在正确的做法是什么？","o":["我进一步降低车速","我尽可能靠左行驶","我跟之前一样继续行驶"],"c":"发生事故时，您应始终采取稳妥的做法：加大安全距离并降低车速，以防有人闯入车道。"},"2.2.34-101":{"q":"你的车辆撞上了野生动物。此时正确的做法是什么？","o":["我守护事故现场","我通知警察","我把动物装进我的车辆"],"c":"在马鹿事故后，您应开启危险警示灯、穿上高可视性背心并设置三角警示牌，以对事故现场进行防护。您应通知警方，描述您的事故并告知准确位置。"},"2.2.34-102":{"q":"为什么行程中应始终随身携带欧洲事故报告表？","o":["便于与讲外语的事故当事方一起记录事故","使当事方能够独立记录事故","在事故现场明确澄清责任问题"],"c":"应随身携带《欧洲事故报告单》，因为它便于与讲其他语言的事故当事人一起记录事故，并使事故能够独立地记录下来。"},"2.2.34-103":{"q":"发生严重事故时，eCall系统如何工作？","o":["机动车的位置","事故时间","机动车内人员受伤的严重程度"],"c":"在严重车祸中，例如安全气囊触发时，eCall 系统会自动发出一个 112 紧急呼叫。它会传送事故的时间以及准确位置。\n或者，车内乘员也可以手动触发 SOS 信号——例如乘客突发心脏病时。"},"2.2.34-104":{"q":"在什么情况下eCall系统设计为可手动触发？","o":["如果我目击了一起严重事故","如果一名乘客发生医疗紧急情况","如果我的车辆发生爆胎"],"c":"在出现紧急医疗问题时，例如发生严重事故时、车内人员突发心脏病时，或作为路过施救者时，也可以手动触发紧急呼叫系统。"},"2.2.34-201":{"q":"你驾驶卡车在高速公路上发生事故。你按什么顺序行动？","o":["立即停车、确保交通安全、查看事故后果并救助受伤人员","立即停车、寻找目击者、确保交通安全并救助受伤人员","停车、报警、开启危险警示灯并等待"],"c":"在高速公路上用您的卡车发生事故时，您应立即停车，对交通进行防护，并了解事故和可能的伤情以便提供帮助。"},"2.2.34-203":{"q":"你在高速公路上行驶时，乘客告诉你车内有烟。你必须怎么做？","o":["立即在应急车道停车，并在足够距离处守护车辆","引导乘客前往远离客车和高速公路的安全距离处","继续行驶到下一个加油站寻求帮助"],"c":"即将推出……"},"2.2.34-204":{"q":"你的客车在事故中翻车，你无法打开车门。你必须怎么做？","o":["告诉乘客通过紧急逃生窗和紧急门离开客车，并保持冷静","请未受伤的乘客帮助将受伤者和体弱者以及儿童安全地带出客车","首先等待救援"],"c":"即将推出……"},"2.2.34-205":{"q":"大雾中你在高速公路上卷入一起连环相撞事故。你的客车被其他车辆夹住。你必须怎么做？","o":["将受伤人员和乘客带到远离客车和高速公路的安全距离处并实施急救","将乘客疏散到安全处后，返回事故现场","首先在事故现场寻找目击者"],"c":"即将推出……"},"2.2.34-206":{"q":"你发生抛锚，必须停在高速公路右侧应急车道上。你必须怎么做？","o":["开启危险警示灯，并在车辆后方足够距离处放置警告标志（安全装置）","确保你的乘客停留在远离客车和高速公路的安全距离处","除非你能自行修理车辆，否则呼救"],"c":"即将推出……"},"2.2.34-207":{"q":"谁是事故当事方？","o":["其行为可能对事故有促成作用的人","造成事故的人","对所发生情况作证的人"],"c":"交通事故的当事人可以是其行为促成了该事故的人，也可以是造成事故的人。"},"2.2.34-208":{"q":"事故当事方是否必须将其车辆移到一旁？","o":["是，在轻微损坏的情况下","是，在任何情况下","否，绝不"],"c":"如果只是轻微损坏，事故当事人应将其车辆开到一旁。这样交通才能继续顺畅通行。"},"2.2.34-210":{"q":"你卷入一起交通事故。为确保乘客不受危险，他们必须离开客车。然而你的客车车门已无法打开。现在你必须怎么做？","o":["安抚乘客","要求乘客在紧急情况下使用紧急出口","要求乘客相互帮助"],"c":"如果您卷入了交通事故且车门无法打开，您应首先让乘客冷静下来。\n请乘客通过指定的紧急出口离开车辆，并请乘客之间互相帮助。"},"2.2.34-211":{"q":"你在高速公路上驾驶客车时卷入一起道路交通事故。乘客需要下车。正确的做法是什么？","o":["我向乘客说明情况","我必须就如何安全离开客车发出明确指示","我必须从行车记录仪中取出驾驶员卡"],"c":"您首先应安抚乘客并向他们说明情况。然后给乘客明确的指示，请他们通过指定的紧急出口离开车辆，并请他们互相帮助。"},"2.2.37-001-B":{"q":"这些信号表示什么？","o":["右侧的两条车道对交通开放","你不得使用左侧的两条车道","你只可使用左侧的两条车道超车"],"c":"这些常设的信号灯可以根据交通情况开放或关闭车道。它们总是直接关联其所在的车道。绿色标志表示您可以在这条车道上行驶，红色叉号表示封锁该车道，带箭头的黄色标志对您意味着：变换车道。"},"2.2.37-002":{"q":"你以约40 km/h的速度行驶。当你距路口10 m时信号灯由“绿”变“黄”。你该怎么做？","o":["通过","停车"],"c":"在 40 km/h 时，根据经验公式制动距离为 28 米。即使采取紧急制动，汽车驾驶员也几乎无法在交通信号灯前 10 米处停下。因此，为防止可能发生的追尾碰撞，您应继续行驶。"},"2.2.37-003":{"q":"你以约40 km/h的速度行驶。当你距路口40 m时信号灯由“绿”变“黄”。你该怎么做？","o":["停车","通过"],"c":"根据经验公式，在 40 km/h 的速度下，您的汽车会在 28 米后停下。唯一正确的反应是停车。"},"2.2.37-004":{"q":"你正接近一个已“绿灯”一段时间的交通信号灯。你该怎么做？","o":["密切注视信号灯","驶近，但做好停车准备","即使超过限速也加速"],"c":"由于交通信号灯已经绿了一段时间，它随时可能切换。以相同的速度继续行驶，仔细留意信号灯并做好停车准备。一旦您到达了决定点——即距离信号灯已无法正常停车的距离——就继续行驶，即使信号灯切换。"},"2.2.37-006":{"q":"信号灯刚刚变黄。如果你正在左转，正确的做法是什么？","o":["停车","转弯"],"c":"黄色交通信号灯表示您必须在路口前等待。由于在这种情况下您与停车线的距离足够远，您可以安全停车。"},"2.2.37-007":{"q":"关于长期亮起的标志，哪项正确？","o":["长期亮起的标志或封闭车道或对交通开放车道","在有长期亮起标志的车行道旁，车辆不得停车","长期亮起的标志仅适用于多轮机动车"],"c":"如果有交叉的红色斜杠，车道上的驾驶员既不得在其前方行驶，也不得在其前方停车。一个向下的绿色箭头表示：您可以在这条车道上行驶。一个闪烁的、斜向下的黄色箭头表示您必须沿箭头方向变换车道。"},"2.2.37-008":{"q":"这些长期亮起的标志表示什么？","o":["1号车道可继续行驶","2号车道必须变更到右侧车道","3号车道和4号车道必须停车"],"c":"车道上方的连续光信号会告知作为汽车驾驶员的您，这条车道是可通行的、被封锁的，还是您需要离开它。红色交叉杠表示：该车道不得使用。一个向下的绿色箭头表示：您可以在这条车道上行驶。一个闪烁的、斜向下的黄色箭头表示您必须沿箭头方向变换车道。"},"2.2.38-101":{"q":"一辆闪着蓝灯并鸣响警报器的车辆从后方接近你。现在正确的做法是什么？","o":["我尽可能驶向右侧","我降低车速","我立即停车"],"c":"必须为该车辆让出通道。因此，您必须降低车速并尽量靠道路一侧行驶，以便带有蓝色闪光灯的车辆可以不受阻碍地继续前进。"},"2.4.40-002":{"q":"当你在高速公路上看到这个交通标志时，你该怎么做？","o":["提高警觉，并作为预防措施加大与前车的距离","发生交通拥堵时，制动并开启危险警示灯","发生交通拥堵时，移到应急车道上继续行驶"],"c":"注意拥堵：看到这个交通标志时，您应降低车速并加大与前车的距离。通过观察前车前方的交通情况来更好地判断状况，必要时在车道内略微错位行驶。在驶向交通拥堵末端时，请开启危险警示灯。"},"2.4.40-003":{"q":"当你看到这个交通标志时，你必须怎么做？","o":["在弯道前降低车速","尽可能驶向右侧靠边行驶","在弯道前打左转向灯"],"c":"该交通标志预告一个危险的左转弯。降低车速以减小离心力。对向来车可能因离心力而驶入您的车道。此外，弯道后方可能有一辆车抛锚。尽量靠右行驶。您是在跟随道路行驶，并没有转弯。因此，您无需打转向灯。"},"2.4.40-004":{"q":"在这一危险路段内你该怎么做？","o":["减速慢行，注意野生动物","看到野生动物时切换近光灯并制动","如果会危及对向来车，则不要避让野生动物"],"c":"注意野生动物横穿：这个标志设置在已经发生过很多野生动物事故的路段。一看到这个标志，您就应降低车速并做好刹车准备。特别要注意路边。如果您看到动物，应刹车并变换近光灯。如果野生动物突然跳到您面前，您应进行紧急制动。避免转向躲避，因为这样您可能驶入对向车道。"},"2.4.40-005":{"q":"看到这个交通标志时你必须做好什么准备？","o":["侧风","反向修正转向","上方有飞机"],"c":"该交通标志表示一段有侧风的路段。这在桥梁和高架桥上尤其如此。如果有强烈的侧风，您必须降低车速。您需要做好握紧方向并反向修正以保持在车道内的准备。该交通标志与空中交通无关。"},"2.4.40-006":{"q":"看到这个交通标志时你必须做好什么准备？","o":["车辆响应特性的变化","需要反向修正转向","需要调整车速"],"c":"遇到这个交通标志时，您必须做好应对强侧风的准备。这个交通标志最常见于特别容易受风影响的路段——例如桥梁或高架桥上。在强侧风下，驾驶员必须反向修正方向以保持在车道内。您还需要根据风力情况调整车速。"},"2.4.40-007":{"q":"看到此交通标志时，你应预料到什么情况？","o":["前方车辆可能突然向左拐出","前方车辆可能突然制动","车道上横有倒伏的树枝"],"c":"由于树木的存在，高大的车辆可能突然刹车并转向躲避。高大的车辆经过时可能刮断树枝，这些树枝随后会落在车行道上。要特别提高警惕。"},"2.4.40-201":{"q":"看到此交通标志时，你必须预料到什么？","o":["树木可能伸入我所在的车行道","车道上可能横有树枝","车辆可能突然拐向"],"c":"全部 3 个答案都正确。道路上可能横躺着树木，路面上可能散落着树枝，汽车也可能突然让行。"},"2.4.41-001":{"q":"从该交通标志起，下列哪种说法正确？","o":["你可以推行你的轻便摩托车","你可以驾驶轻便摩托车缓慢行驶","在发动机熄火的情况下，你可以驾驶轻便摩托车通行"],"c":"这个标志表示任何车辆都不得通行，因此您不能骑行您的助力自行车，但仍可以推行它。"},"2.4.41-002":{"q":"该交通标志上的“12 t”指什么？","o":["车辆（含载重）的质量","车辆（不含载重）的质量","货物（不含车辆）的质量"],"c":"总质量（12 t）指的是包括装载物在内的车辆。"},"2.4.41-003":{"q":"你所驾车辆长 10 米，货物超出车辆后缘 60 厘米。出现该交通标志时，你应如何做？","o":["不得驶入设有该标志的街道，因为车辆与货物合计长度超过 10 米","如果货物有专门标记，可以驶入设有该标志的街道","可以驶入设有该标志的街道，因为货物无需计入长度"],"c":"您的卡车长度标注为 10.6 m（10 m + 60 cm 装载物后伸），以此为准。因此，您不得驶入这条道路，因为您的卡车总长 10.6 m。"},"2.4.41-004-M":{"q":"你正在这条高速公路上行驶。正确的做法是什么？","o":["我驶入右侧车道","仅在发生故障时我才使用左侧车道","我保持当前车道行驶"],"c":"在高速公路上原则上适用靠右行驶规则。因此，除非您想超车，否则您有义务在右侧车道行驶。您前方没有需要超越的车辆。\n左侧车道已封闭。您在任何情况下都不得使用它。即使您发生了故障也不可以。"},"2.4.41-005-M":{"q":"现在正确的做法是什么？","o":["我加速","我保持车速","只有在限速被交通标志解除后我才加速"],"c":"您可以加速，因为您已经驶过了带限速标志的施工路段，重新驶回了正确的车道，并且前方的道路畅通。"},"2.4.41-101":{"q":"看到该交通标志时，你必须注意什么？","o":["使用防滑链","最高允许车速 50 公里/小时","履带式车辆享有优先通行权"],"c":"该交通标志表示接下来的路段只能使用防滑链行驶。未安装防滑链行驶是被禁止的。使用防滑链时的最高速度为 50 km/h。注意异常声响。如果您听到异常声音或车辆行驶不稳定，应停车检查防滑链。这个标志与履带式车辆无关。"},"2.4.41-102":{"q":"哪个交通标志表示许可总质量？","o":[],"c":"作为汽车驾驶员，您应注意这个交通标志可以有两种读法。一方面，t 代表吨，因此指的是实际重量。但是，如果 t 另外用白色符号标出，则该交通标志也可能指的是最大允许总质量。"},"2.4.41-103":{"q":"哪个交通标志表示实际质量？","o":[],"c":"如果交通标志中有代表吨的符号 t，那么它指的是实际重量。实际重量由车辆空重加上当前装载物计算得出。车辆空重记录在车辆证件中。作为汽车驾驶员，您有义务了解您车辆的重量。"},"2.4.41-104":{"q":"哪些车辆禁止驶入设有此类标志的道路？","o":["实际轴荷超过 2 吨的车辆","许可轴荷超过 2 吨的车辆","许可总质量不超过 2 吨的车辆"],"c":"该交通标志禁止超过标志上标注重量的车辆在该路段行驶。重量标注指的是实际轴荷。不得超过该轴荷。交通标志中的红色圆形边框始终表示禁令。"},"2.4.41-105":{"q":"该交通标志表示什么？","o":["禁止宽度（含载重）超过 2 米的车辆通行","车行道宽 2 米","你必须与其他车辆保持至少 2 米的侧向间距"],"c":"交通标志“含装载物的宽度限制”表示后续路段上的道路狭窄和瓶颈。对于包括货物在内宽度超过标志所示数值的车辆，该车道不可通行。此处允许的宽度为 2 m。"},"2.4.41-106":{"q":"无视该交通标志时，哪些车辆可能引发严重事故？","o":["长 8 米、宽 2.5 米、高 4 米","长 10 米、宽 3.9 米、高 3 米","长 4 米、宽 2.5 米、高 2.5 米"],"c":"该交通标志针对卡车，预告限高的通道——位于隧道、桥梁建筑或有轨电车的高架接触网之前。限高由黑色三角形标示，此处为 3.8 m。如果高度超过 3.8 m 的车辆无视此标志，可能发生严重事故。卡车可能被架空接触网或地下通道卡住或卡死。长度和宽度在此无关。"},"2.4.41-107":{"q":"哪些车辆禁止在设有此类标志的道路上行驶？","o":["带房车拖车的轿车，列车总长 11 米","带拖车的牵引车，列车总长 12 米","长度（含载重）9 米的载货汽车"],"c":"交通标志中的红色圆形边框始终表示禁令。实际长度超过 10 m 的车辆不得在这条道路上行驶。即使是总长度超过 10 m 的带拖车车辆也不得在这条道路上继续行驶。这表示道路状况不适合较长的车辆通行。"},"2.4.41-108":{"q":"出现该交通标志时，你可以超哪些车辆？","o":["任何车辆都不可以","单轮迹车辆","多轮迹车辆"],"c":"您不得超车，无论是单车还是多车道车辆。"},"2.4.41-109":{"q":"该标志所示的禁止超车规定适用于哪些机动车？","o":["客车或公交车","单轮迹机动车","不带拖车的轿车"],"c":"该交通标志对最大允许总质量超过 3.5 t 的机动车规定了超车禁令。附加标志还（将超车禁令）扩展到公共汽车和带拖车的小汽车。"},"2.4.41-201":{"q":"哪些车辆禁止驶入设有此类标志的道路？","o":["许可总质量超过 3.5 吨的载货汽车","牵引车","带拖车的轿车"],"c":"当您驾驶最大质量超过 3.5 t 的拖拉机或卡车时，不得驶入标志所标的这条道路。带拖车的小汽车可以在此行驶。"},"2.4.41-202":{"q":"哪些车辆在此处必须保持 70 米的最小间距？","o":["许可总质量超过 3.5 吨的载货汽车","牵引车","轿车"],"c":"无论是拖拉机还是最大质量超过 3.5 t 的卡车，都适用这些特殊规定。小汽车不在其中。"},"2.4.41-203":{"q":"哪些车辆在此处不得超车？","o":["许可总质量超过 3.5 吨的载货汽车及带拖车的载货汽车","牵引车","轿车"],"c":"总质量超过 3.5 吨的卡车以及拖拉机在该标志处不得超车。"},"2.4.41-204":{"q":"该交通标志表示什么？","o":["禁止携带有强制标识危险货物的机动车通行","禁止实际轴荷超过 3.5 吨的车辆通行","禁止载货汽车及汽车列车通行"],"c":"该交通标志表示禁止（载有相应标志的）运载危险货物的车辆通行。其余车辆在该区域内均允许通行。"},"2.4.41-205":{"q":"你想驶入设有该标志的道路。“12 t”这一信息指什么？","o":["车辆的实际质量","车辆的许可总质量","车辆的空车质量"],"c":"该标志指的是车辆的实际质量，包括货物。请注意这一点。"},"2.4.41-206":{"q":"该道路交通标志上“12 t”这一信息指什么？","o":["车辆的实际质量","车辆的许可总质量","货物的实际质量"],"c":""},"2.4.41-207":{"q":"你驾驶许可总质量 30 吨的载货汽车列车。看到该道路交通标志后，何时你可以继续行驶？","o":["我必须将货物送往当地居民处","我正行驶在指定的绕行路线上","这样做我能够遵守行车与休息时间规定"],"c":"只有当您必须向居民送货，或者这是指定的绕行路线时，您才可以在这条道路上行驶。"},"2.4.41-208":{"q":"你驾驶由牵引车与拖车组成的汽车列车，想驶入设有该标志的道路。“5.5 t”这一信息指什么？","o":["汽车列车中每辆单车的实际质量","汽车列车的实际总质量","牵引车的许可总质量"],"c":"该交通标志指的是每一辆单独车辆（即车组）的实际质量，包括装载物。"},"2.4.41-209":{"q":"看到该交通标志时，在哪种情况下你必须与前车保持至少 70 米的最小间距？","o":["我驾驶许可总质量超过 3.5 吨的载货汽车，跟在另一辆许可总质量超过 3.5 吨的载货汽车后面","我驾驶牵引车，跟在许可总质量超过 3.5 吨的载货汽车后面","我驾驶许可总质量超过 3.5 吨的载货汽车，跟在带拖车的轿车后面"],"c":"作为最大允许总质量超过 3.5 吨的卡车驾驶员，或作为拖拉机驾驶员，如果我前方有一辆最大允许总质量超过 3.5 吨的卡车，我必须保持至少 70 米的距离。"},"2.4.41-401":{"q":"在设有该标志的道路上，哪些机动车禁止行驶？","o":["型式最高车速为 25 公里/小时的牵引车","最高允许车速为 25 公里/小时的带拖车机动车","型式最高车速超过 40 公里/小时的牵引车"],"c":"该交通标志表示禁止设计最高速度不超过 25 km/h 的拖拉机，以及最大允许速度不超过 25 km/h 的带拖车机动车通行。\n这不适用于设计最高速度超过 40 km/h 的拖拉机。"},"2.4.42-001":{"q":"该交通标志表示什么？","o":["高速公路终点","机动车专用快速路终点","高速公路临时封闭"],"c":"该交通标志位于高速公路的终点。"},"2.4.42-002":{"q":"该交通标志表示什么？","o":["机动车专用快速路终点","高速公路终点","禁止机动车通行"],"c":"该交通标志设置在快速公路（高速公路）的终点。它意味着：从这里开始建议速度限制不再适用。它并不表示禁止机动车通行。"},"2.4.42-004":{"q":"此类交通标志表示什么？","o":["高速公路的编号","到下一个加油站的距离","欧洲道路的编号"],"c":"蓝底白边白色数字表示您当前所在高速公路的编号。"},"2.4.42-005":{"q":"该交通标志中的数字“26”表示什么？","o":["高速公路第 26 号出口","A 26 高速公路","从该出口到杜塞尔多夫-本拉特的距离"],"c":"所有高速公路出口都编号，以便更好地辨认方向。作为汽车驾驶员，您可以通过数字 26 认出高速公路的出口匝道。在道路地图、道路图册以及常见的导航设备中也能再次找到这些编号。"},"2.4.42-006":{"q":"该交通标志表示什么？","o":["需要时供高速公路车流绕行","地铁站","联邦公路（Bundesstrasse）22 号"],"c":"该交通标志表示高速公路交通的绕行路线。例如在发生交通拥堵时会设置它。如果汽车驾驶员沿着该绕行路线行驶，就会重新回到高速公路。"},"2.4.42-007":{"q":"从该交通标志起适用什么规定？","o":["最高允许车速 50 公里/小时","许可总质量不超过 3.5 吨的机动车可自由选择标线车道","所有机动车均可自由选择标线车道"],"c":"该交通标志适用城镇内道路交通的规定。其中包括将最高速度限制为 50 km/h。自由选择车道仅适用于最大允许总质量不超过 3.5 t 的车辆。超过 3.5 t 的车辆须靠右行驶。"},"2.4.42-008-M":{"q":"看到该交通标志时适用什么规定？","o":["我可按行驶方向自由选择车道","我可在右侧车道比在左侧车道行驶的车辆开得更快","因为这是多车行道，我可以超过 50 公里/小时行驶"],"c":"在城镇内，您可以偏离靠右行驶的要求，即在多车道道路上您可以自由选择车道。在城镇内的双车道上，右车道上的车辆也可以比左车道上的车辆行驶得更快，但在城镇内您仍然不得行驶超过 50 km/h。"},"2.4.42-101":{"q":"从该交通标志起适用什么规定？","o":["不得鸣喇叭示意超车意图","停放的轿车可用驻车灯作安全标示","在黑暗中可以仅开驻车灯行驶"],"c":"汽车驾驶员从该交通标志可以认出，适用于封闭城镇内交通的规定开始生效。您不得通过鸣笛来预告超车动作，因为这仅在封闭城镇之外才被允许。一般而言，禁止只开驻车灯行驶。停放的车辆可以用驻车灯进行示意。"},"2.4.42-102":{"q":"许可总质量不超过 2.8 吨的车辆在此处允许如何停放？","o":["如图所示的轿车","如图所示的房车","小型轿车也可相对行驶方向斜向停放"],"c":"该交通标志向车辆驾驶员表明，最大允许总质量不超过 2.8 t 的车辆只能按照图示方式停放。不过，较小的汽车也同样必须遵守这些规定。"},"2.4.42-103":{"q":"该交通标志表示什么？","o":["加氢站","天然气加气站","液化石油气加气站"],"c":"蓝边方形交通标志表示附近有供氢动力车辆加注氢气的设施。这类汽车目前仍然相对昂贵，但被视为未来的车辆。"},"2.4.42-104":{"q":"该交通标志表示什么？","o":["天然气加气站","加氢站","液化石油气加气站"],"c":"该交通标志指示一个天然气加气站，驾驶员可以在那里为其天然气动力车辆加气。缩写 CNG 代表压缩天然气。"},"2.4.42-105":{"q":"该交通标志表示什么？","o":["液化石油气加气站","天然气加气站","加氢站"],"c":"方形交通标志上的字样 LPG 是液化石油气的缩写。该交通标志向汽车驾驶员表明此处有一个 LPG 加气站。"},"2.4.42-106":{"q":"该交通标志表示什么？","o":["电动汽车充电站","加油站因电气设备存在爆炸危险","手机充电设施"],"c":"您会在标志上看到一个带线缆的插头。它向您指示附近有一个供电动汽车（如电动汽车、电动自行车或电动滑板车）使用的充电站。您可以在那里为您动力驱动的车辆充电。"},"2.4.42-107":{"q":"该交通标志表示什么？","o":["与公共交通衔接的停车场（“Park + Ride”）","带洗车设施的加油站（“Care + Clean”）","带维修车间的租车中心（“Breakdown service + Repair”）"],"c":"蓝底上的交通标志 P + R 代表“Park and Ride”（停车换乘）。它标识一个与公共交通相连的停车场。该停车场可以是长期或临时的。"},"2.4.42-108":{"q":"你驾驶需缴费的载货汽车，正接近所示交通标志。你应如何做？","o":["我检查车载单元（OBU），确认车轴数量设置是否正确","只有在已为该路线缴纳通行费的情况下，我才能不使用车载单元（OBU）继续行驶","我在驶出收费路段时在收费站缴费"],"c":"只有该路段的使用费已缴纳，您才能继续行驶；在没有车载设备（OBU）的情况下，您应在此处检查车轴数量是否已正确设定。如果不正确，请正确申报。"},"2.4.42-109-M":{"q":"在这种情况下，哪种说法正确？","o":["在仔细观察道路交通情况、排除对骑车人的危险后，我可以在建议性自行车道上行驶","我仅可在驶过该载货汽车之前使用建议性自行车道","我不得在建议性自行车道上行驶"],"c":"连续行驶在防护带上是不允许的。防护带带有虚线标记，必要时汽车可以驶上去，尤其是在避让对向来车时。但只有在不会危及自行车交通的情况下您才能这样做。"},"2.4.42-110":{"q":"凭哪种证件你可以在此停车？","o":["我的欧盟重度残疾人停车证","我所运送的重度残疾人的欧盟停车证","我的居民停车许可"],"c":"如果您本人持有欧盟重度残疾人停车证，或者您正在运送一名持有欧盟重度残疾人停车证的人，您就可以在这块带此标志的停车场内停车。"},"2.4.43-002":{"q":"你在高速公路上需要帮助。路边标志牌上的箭头为你提供什么信息？","o":["箭头方向上最近的紧急呼叫电话","箭头方向上最近的停车场","箭头方向上的下一个出口"],"c":"高速公路边缘反射柱上的箭头指向最近的紧急呼叫柱。如果您需要帮助，请顺着箭头走，以尽快到达一个紧急呼叫柱。"},"2.5.01-001":{"q":"你可以怎样避免不必要的噪音？","o":["避免发动机高转速","不擅自改装进气与排气系统","拆除导流罩"],"c":"为避免不必要的噪音，请避免让发动机高转速运转，也不要改装进气/排气系统。拆除整流罩对噪音没有影响。"},"2.5.01-002":{"q":"你可以怎样避免噪音污染？","o":["起步时不要让车轮空转","避免通过扬声器制造“大功率音效”","在居住区内尽可能推行车辆"],"c":"为避免产生超出正常水平的噪音（即噪音污染），以上各项都要做到。"},"2.5.01-004":{"q":"你怎样节省燃油？","o":["尽早换入高挡","较晚换入低挡","经常以高转速行驶"],"c":"作为汽车驾驶员，当您以较低速度行驶时可以节省燃油。您应尽可能早地换入高档位，并尽可能晚地降档，以保持发动机转速较低。"},"2.5.01-005":{"q":"怎样可以避免噪音？","o":["尽可能避免强烈加速","需要较长时间等待或停车时关闭发动机","以高转速行驶"],"c":"噪音通常由汽车运转的发动机产生。高速行驶和强烈加速会加剧噪音。如果您在某个地方等待或长时间停放车辆，请关闭发动机。"},"2.5.01-006":{"q":"可避免的噪音是怎样产生的？","o":["使用有故障的排气装置行驶","停车时空踩油门","遇到危险时鸣喇叭"],"c":"可避免的噪音可能由于使用有缺陷的排气系统行驶，或由于停车时“轰油门”而产生。如果汽车驾驶员因危险情况而鸣笛，这不属于可避免的噪音，而是用于避免危险。"},"2.5.01-007":{"q":"为什么应避免急速起步？","o":["因为所造成的噪音会打扰他人","因为会加剧轮胎磨损","因为这会严重加重后制动器的负担"],"c":"轰油门起步（赛车式起步）会给其他道路使用者带来额外的噪音污染。作为汽车驾驶员，赛车式起步会因高度磨损和磨耗而损坏您的车辆和轮胎。环境也因此承受额外负担。另一方面，起步时后轮制动器的负荷并不会因此更低，也不会更高。"},"2.5.01-009":{"q":"冷启动后，你怎样既能减少对环境的污染又对发动机有益？","o":["以低转速起步，不要原地怠速热车","不要加速，让发动机在车辆静止时预热","在静止时多次加速，以便尽快达到有利的工作温度"],"c":"尽可能不要让您的车辆在静止状态下预热，因为这会损坏发动机和环境。如果以低发动机转速进行预热，您将有助于同时保护这两者。发动机只有在达到工作温度（绿色区域）后才具有完全的承受能力。"},"2.5.01-010":{"q":"哪些车辆允许驶入该环保区？","o":["贴有红色排放标识的轿车","摩托车","即使未贴排放标识，但满足绿色标识要求的轿车"],"c":"机动车驾驶员只有在车辆明显贴有有效标识、且该标识至少相当于相应等级标志（红、黄、绿）时，才可以将车辆驶入环保区。摩托车和享有特殊权利的车辆不受此规定约束。"},"2.5.01-011":{"q":"在夏季月份使用冬季轮胎行驶会导致什么？","o":["燃油消耗","轮胎磨损","行驶稳定性"],"c":"每位汽车驾驶员都应知道，冬季轮胎是为在寒冷和下雪的路面上使用而设计的。在夏季月份使用它们会降低行驶稳定性。更大的橡胶磨耗和轮胎磨损会导致油耗增加。"},"2.5.01-012":{"q":"哪些机动车可以驶入设有该标志的环保区？","o":["贴有绿色颗粒物排放标识的机动车","摩托车","即使未贴该标识，但满足绿色颗粒物排放标识要求的机动车"],"c":"附加标志显示哪些机动车凭哪种标识可以驶入。摩托车在任何情况下都可以驶入。"},"2.5.01-013":{"q":"你想洗车。为保护环境，应在哪里洗车？","o":["在洗车场","在停车场","在空旷道路上"],"c":"您应始终在洗车场清洗您的车辆。在那里，废水由经营者以环保的方式处理。相反，如果您在道路上或停车场清洗车辆，水会未经处理地渗入地下。"},"2.5.01-014":{"q":"什么会显著增加你车辆的燃油消耗？","o":["座椅加热","空调","导航设备"],"c":"打开车辆的座椅加热或空调会消耗大量能量，并显著增加您汽车的油耗。与这些设备相比，导航设备所需的功率相对较小。"},"2.5.01-015":{"q":"什么可以降低商用车的燃油消耗？","o":["为车辆安装导流罩","驾驶员有预见性的驾驶方式","使用专用轮胎"],"c":"三个答案都能带来（排放/油耗的）降低：车辆上使用导流板（百叶窗式导流装置）、驾驶员以预见性方式驾驶，甚至使用特殊轮胎。"},"2.5.01-016":{"q":"内燃机机动车高速行驶会产生哪些影响？","o":["燃油消耗增加","有害物质排放增加","噪音水平降低"],"c":"请注意，快速、高速行驶会导致高油耗和高排放。这也会产生更多噪音，且不会降低噪音水平。"},"2.5.01-017":{"q":"骑摩托车时，你可以怎样避免不必要的噪音？","o":["只使用许可的排气系统","高速起步","采用不平稳的驾驶方式"],"c":"不当的排气系统会导致更高的噪音污染。\n不均匀的驾驶，例如频繁刹车然后再次猛加速，会导致不必要的噪音。\n高速起步会导致不必要的噪音。"},"2.5.01-018":{"q":"为什么环保的驾驶方式也有利于道路交通安全？","o":["以有预见性的方式驾驶","避免高速行驶","使用替代燃料只能缓慢行驶"],"c":"替代燃料也可以用来快速行驶。不过，如果您避免高速行驶、以预见性方式驾驶，从而例如避免急刹车和再次起步，您就是在以环保的方式行驶。"},"2.5.01-102":{"q":"关于催化转化器，你必须了解什么？","o":["通过牵引启动轿车时，催化转化器可能被损坏或毁坏","多次启动失败后发动机终于启动时，催化转化器可能被损坏","发动机启动时，催化转化器内未燃烧的燃油不会造成任何损坏"],"c":"带催化转化器的车辆不应被拖曳。因为这样未燃烧的燃油可能流入催化转化器，导致其损坏或损毁。如果车辆的发动机在多次尝试启动后仍无法启动，也会产生同样的后果。"},"2.5.01-103":{"q":"轮胎磨损会给环境带来负担。什么可以延长轮胎寿命？","o":["避免高速行驶","遵守使用手册中规定的胎压","夏季使用冬季轮胎（M+S）"],"c":"当轮胎按预期用途使用时，其磨损最小。在夏季使用的冬季轮胎会因其材料特性（橡胶配方）磨损得更快。气压过低时轮胎也会磨损得更快。高速起步并使轮胎发出尖叫声，会因磨耗增加而使轮胎磨损。"},"2.5.01-104":{"q":"驾驶自动变速机动车时，你怎样节省燃油？","o":["尽可能不使用“强制降挡”功能","在城市交通中始终将选挡杆置于最低挡","尽可能以“P”挡行驶"],"c":"避免使用强制降档（kick-down）。这种高速加速档会增加油耗。不过在高速公路上超车或汇入车流时，它可能有帮助。挂 P 档（驻车档）时，自动挡车辆无法行驶。尽早换入高档位也能节省燃油。"},"2.5.01-105":{"q":"你怎样能将对环境的负担降到最低？","o":["组织拼车","避开交通高峰时段","避开经常发生交通拥堵的道路"],"c":"为了减轻环境负担，作为汽车驾驶员您应与他人拼车。环境尤其受到行驶车辆数量的负担。此外，您还应避免多辆车集中聚集，例如形成交通拥堵。"},"2.5.01-106":{"q":"什么会导致你轿车燃油消耗增加？","o":["车顶行李架或滑雪板架","运载不必要的物品","胎压过高"],"c":"例如，如果您安装车顶行李架或滑雪架，或者用不必要的物品装载车辆，就可能出现油耗增加。相反，轮胎气压对油耗没有影响，尽管（不当气压）总体上仍应避免。"},"2.5.01-107":{"q":"你怎样节省燃油？","o":["至少遵守使用手册中规定的胎压","拆下车顶行李架或滑雪板架","避免使用最高挡行驶"],"c":"额外的负载和车顶行李架或滑雪架等额外附件会增加油耗：不使用时请拆除它们。以低速行驶时您可以节省燃油：尽早换入高档位。关闭空调系统能节省燃油，按照制造商规定保持轮胎气压同样如此。因为轮胎气压过低会增加滚动阻力。"},"2.5.01-108":{"q":"出于环保原因，你应避免什么？","o":["让发动机在车辆静止时空转预热","不必要的出行","开窗播放高音量音乐"],"c":"启动发动机后，作为汽车驾驶员您应立即以低速的驾驶方式起步。发动机在静止状态下预热是不允许的。高速行驶、延长换档并延迟换档会浪费燃油。不必要的行驶会造成可避免的尾气排放。"},"2.5.01-109":{"q":"哪种行为体现了环保意识？","o":["在联合停车场（“P + R”）换乘公共交通","组织拼车","在交通拥堵时关闭发动机"],"c":"避免漫无目的地驾车。私人交通会污染环境。尽可能经常拼车。如有可能，使用公共交通。如果您堵在交通拥堵中，不要让发动机空转，请将其关闭。"},"2.5.01-111":{"q":"你怎样能降低噪音？","o":["在城镇内道路以 4 挡或 5 挡行驶","以高发动机转速行驶","高速行驶"],"c":"在高速区间行驶比低速的驾驶方式产生更多噪音。在城镇内您应尽可能以最高档位行驶，以使发动机产生尽可能小的噪音。避免发出尖啸声的高速起步。"},"2.5.01-112":{"q":"车内“大功率音效”会导致什么？","o":["听不到其他交通参与者的信号，尤其是警笛声","即使车窗关闭，也会对他人造成噪音污染","因驾驶员分心而导致驾驶失误"],"c":"车内的“动力音效”会造成过度刺激。这种过度刺激可能使驾驶员分心，从而可能漏听其他重要信号。请记住，其他道路使用者也会受到噪音的干扰。"},"2.5.01-113":{"q":"与以推荐车速 130 公里/小时行驶相比，中型轿车以 160 公里/小时行驶时，其燃油消耗（升/100 公里）通常增加多少百分比？","o":["最多 35%","最多 5%","最多 10%"],"c":"与以建议速度限制 130 km/h 行驶相比，以 160 km/h 的速度行驶时油耗通常会大幅增加。例如，一辆中级轿车的油耗可能上升多达 35%。"},"2.5.01-116":{"q":"何时你允许驶入环保区？","o":["当你的车辆贴有相应的排放标识时","当你的车辆享有特殊权利时","当你拥有低排放车辆时"],"c":"作为汽车驾驶员，只有当您的车辆明显贴有有效标识、且该标识至少相当于相应等级标志（红、黄、绿）时，您才可以驶入环保区。此规则仅豁免享有特殊权利的车辆，例如历史（经典）机动车。"},"2.5.01-117":{"q":"低排放车辆识别用排放标识必须贴在何处？","o":["前挡风玻璃内侧清晰可见处","前挡风玻璃外侧清晰可见处","后车窗内侧清晰可见处"],"c":"作为汽车驾驶员，您必须确保环保标识（颗粒物排放标识）贴在车辆挡风玻璃内侧，以便清楚地标识您的低排放车辆。"},"2.5.01-118":{"q":"如果你的轿车为汽油发动机但未贴排放标识，你是否允许驶入如下设标示的环保区？","o":["不可以，因为我的轿车没有排放标识","可以，因为我驾驶的是带氧传感器闭环控制的催化转化器轿车","可以，因为该禁令仅适用于柴油车辆"],"c":"如果没有明显贴出的环保标识，汽油发动机的机动车驾驶员不得驶入环保区。车辆上的标识必须有效，且至少相当于相应等级标志（红、黄、绿）。"},"2.5.01-119":{"q":"你可以把行李存放在何处，以免不必要地增加燃油消耗？","o":["在后备厢","在前排座椅后方","在车顶行李架上"],"c":"如有可能，您应只将行李存放在车辆后备箱中。使用车顶行李架装载行李会大幅增加空气阻力，往往导致油耗显著增加。"},"2.5.01-120":{"q":"轮胎磨损对环境有负面影响。你怎样减少这种影响？","o":["采用有预见性的驾驶方式","按照制造商规定定期检查胎压","夏季使用冬季轮胎"],"c":"为减少轮胎磨损，您可以以预见性方式驾驶，并通过按照制造商规定定期检查轮胎气压来显著减轻负荷。磨损更少＝负荷更少。"},"2.5.01-121":{"q":"什么有助于环保驾驶？","o":["参加节油驾驶方式的实践培训","使用电力驱动车辆","组织拼车"],"c":"如有可能，拼车以减少道路上车辆的数量。培训可以帮助您养成省油的驾驶方式。电动汽车不排放任何污染物，因此行驶时特别环保。"},"2.5.01-122":{"q":"如果你驾驶自动变速轿车，怎样节省燃油？","o":["起步时不要重踩油门","行驶时使用节能模式","下坡行驶时关闭发动机"],"c":"不必要的加速会导致高油耗。如有配备，请使用节能（eco）模式。车辆会调整其加速行为以降低油耗。"},"2.5.01-123":{"q":"在指定环保区内行驶的哪些轿车必须张贴颗粒物标识？","o":["汽油发动机","柴油发动机","电动机"],"c":"原则上，在指定的环保区内，所有小汽车都有义务展示细颗粒物（环保）标识。工程机械、救护车等除外。"},"2.5.01-124":{"q":"驾驶轿车时听极高音量音乐可能导致什么？","o":["驾驶员察觉不到其他交通参与者的信号","对其他道路使用者造成干扰","驾驶员的反应能力增强"],"c":"过大的音乐声会导致听不到其他道路使用者的警示信号等。过大的音乐声还可能烦扰、干扰并因此危及其他道路使用者。\n由于音乐声过大以及由此导致的注意力下降，驾驶员的反应能力会变差。"},"2.5.01-125":{"q":"空气阻力会影响车辆的燃油消耗。什么对空气阻力影响最大？","o":["行驶速度","乘员人数","轮胎花纹深度"],"c":"您行驶得越快，作用在您车辆上的空气阻力就越大。速度加倍会使空气阻力变为 4 倍。\n轮胎的胎纹深度对轮胎的滚动阻力有很大影响。\n乘客人数不会直接影响空气阻力。"},"2.5.01-126":{"q":"因铁路道口栏杆放下你必须等待。此时你可以怎样帮助保护环境？","o":["使用自动启停系统","将车辆挂入一挡","拉紧驻车制动"],"c":"通过使用自动启停系统，车辆在等待时可以被关闭，并能以很小的力气立即重新启动。这样可将污染物排放降至最低。拉紧手刹对车辆的污染物排放没有影响。"},"2.5.01-127":{"q":"什么可以增加电动汽车的续航里程？","o":["使用高能量回收（再生制动）级别","降低暖风温度","短促而猛烈的加速"],"c":"如果您只轻微刹车，电动机会进行制动，动能被回收。如果您刹车更用力，就会进行机械制动，动能将不会被回收。由于较高的能量回收（再生制动）等级，电动汽车表现得像内燃机汽车，因此您可能不得不更轻地刹车，即更少地机械制动。电动汽车中的暖风直接由电池供电，因此会消耗本也可用于行驶的能量。"},"2.5.01-128":{"q":"电动汽车的能量回收（再生制动）有何好处？","o":["增加续航里程","减轻行车制动系统的负担","可以从制动过程中回收能量"],"c":"能量回收（Recuperation）意为“回收”。正如电能被转化为动能一样，制动时将动能重新转化为电能，然后回充到电池中。这增加了电动汽车的续航里程。"},"2.5.01-129":{"q":"你的轿车配备自动启停系统。使用该车辆系统对环保有何好处？","o":["燃油消耗","噪音污染","轮胎磨损"],"c":"自动启停系统在您停车时自动关闭发动机，并在您踩下任一个踏板时立即重新启动它。\n通过在例如交通信号灯处关闭发动机，自动启停系统可以降低噪音污染，还可节省多达 15% 的燃油。"},"2.5.01-130":{"q":"你驾驶插电式混合动力轿车。你怎样优化燃油消耗？","o":["我定期用市电为电池充电","我通过驾驶方式使用电力驱动","我只用能量回收为电池充电"],"c":"通过预见性地驾驶——平缓加速并及时刹车——您可以降低车辆的油耗。这种驾驶方式常常会用到电动机。\n您还可以通过定期在电网上为插电式混合动力车的电池充电来降低油耗，或者通过纯电行驶将其降至最低。"},"2.5.01-202":{"q":"你怎样避免不必要的噪音？","o":["更换磨损的侧板铰链或紧固件","正确装载或使用链条","大幅提高空载车辆的胎压"],"c":"通过正确存放或使用张紧链，以及更换被打出（撞坏）的后栏板铰链或锁扣（它们会大声哐当作响），您可以避免不必要的噪音。"},"2.5.01-203":{"q":"什么会造成噪音污染？","o":["松动的链条","松动或磨损的侧板铰链","未固定的装载物"],"c":"3 个答案都正确。松动或磨损的后栏板铰链和未固定的装载物，以及松动的张紧链。"},"2.5.01-204":{"q":"在城镇内道路，尤其是空载车辆，你怎样避免噪音？","o":["调整车速，尤其在路面状况差时","以低挡高速行驶","频繁使用两脚离合换挡"],"c":"在城镇内，您可以通过适宜的速度，避免空载车辆在特别差的道路上产生噪音。"},"2.5.01-205":{"q":"哪些机动车允许使用设有该标志的道路？","o":["任何贴有相应排放标识的载货汽车","任何贴有相应排放标识的公交车","任何轿车"],"c":"这条道路通向一个环保区。所有带有相应排放标识的公共汽车以及所有带有相应标识的卡车都允许在此行驶。并非所有小汽车都有该标识，所以“所有小汽车”是错误的。"},"2.5.01-206":{"q":"你怎样避免产生噪音？","o":["尽可能在固定设施处为空压气罐充气","更换磨损的侧门闩","在较长等待时让发动机怠速运转"],"c":"如果您尽可能在固定设施上为空的压缩空气罐充气，并更换磨损的举升门锁扣，就可以避免此类噪音。"},"2.5.01-207":{"q":"规划行程时，你怎样使出行更环保？","o":["将多个目的地合并为一次行程","与其他用车人组织拼车","计划使用公共交通代替自己的车辆"],"c":"为了环境，机动车驾驶员应放弃所有并非绝对必要的出行。因此，请合理规划您的出行，并尽可能经常拼车，以避免不必要的行程。使用公共交通也是对积极环境保护的又一贡献。"},"2.5.01-208":{"q":"你怎样安全地驶下坡道？","o":["选择无需大量制动的挡位","挂空挡滑行","关闭点火开关"],"c":"在下坡时，通过降入低档位来使用发动机制动。这样可以减轻行车制动器的负担。在任何情况下都不要切换到空档！因为空档会使发动机制动失效，从而使行车制动器可能过热。此外，关闭点火开关时制动助力器无法工作。这会大大延长制动距离。"},"2.5.01-209":{"q":"哪些机动车无需细颗粒物标识即可驶入环保区？","o":["所有两轮和三轮机动车","所有农林用牵引车","所有带催化转化器的机动车"],"c":"所有两轮和三轮机动车以及农林业拖拉机无需环保标识即可驶入环保区。它们不受环保区限制的约束。作为汽车驾驶员，安装催化转化器并不能免除您获取环保标识的义务。"},"2.5.01-210":{"q":"哪些制造商参数可以让你了解你的机动车是否环保？","o":["关于燃油消耗","关于效率等级","关于排放等级"],"c":"排放等级提供有关污染物排放的信息。由标准或法律界定的排放等级对排放废气或干扰信号的产品进行划分。在汽车领域还适用以下内容：油耗越低，能效等级就越高，因而车辆就越环保。"},"2.5.01-211":{"q":"为什么冷发动机短途行驶对环境的危害特别大？","o":["消耗更多燃油","材料磨损程度更高","车辆电池会过度充电"],"c":"发动机冷机时的短途行驶通常比发动机处于工作温度时行驶消耗更多燃油。因此它们对环境特别有害。此外，发动机冷机时的短途行驶中摩擦力更大。这会导致更高的材料磨损。"},"2.5.01-212":{"q":"什么会造成可避免的噪音？","o":["以鸣喇叭打招呼","用力关车门","带着车顶行李架行驶"],"c":"车辆正常运行中产生的一切噪音干扰都被视为不可避免。作为汽车驾驶员，您应避免任何多余的噪音，例如以鸣笛打招呼或非常大声地关车门。车顶行李架不会给您带来任何可避免的噪音。"},"2.5.01-213":{"q":"商用车的滑行（eco-roll）模式如何有助于降低燃油消耗？","o":["最大限度利用车辆的动能","发动机制动效果增强","车辆的滑行阶段缩短"],"c":"正确答案是：在滑行（eco-roll）模式下车辆的动能得到最大利用。这与变速器的自动空档位置有关。滑行阶段不会缩短，发动机制动效果也不会增强。"},"2.6.01-001":{"q":"摩托车何时必须进行官方检验（Hauptuntersuchung）？","o":["每两年","每三年","每次重新登记时"],"c":"与小汽车类似，摩托车也应每两年进行一次检验。"},"2.6.01-003":{"q":"你怎样知道何时需要送车进行下一次车辆技术检验？","o":["查看后车牌上的检验标牌","查看行驶证第一部分中的登记记录","查看车辆使用手册中的记录"],"c":"您车辆下一次主检验（年检）的日期可以在登记证书第一部分中找到。此外，该日期在您车牌上打印的检验标牌上也清晰可见。"},"2.6.01-105":{"q":"你购买了一辆二手车，刚完成官方检验（Hauptuntersuchung）。下一次官方检验何时到期？","o":["两年后","一年后","三年后"],"c":"如果一辆二手车刚刚完成主检验，您必须在两年后进行下一次年检。只有新购置的汽车，下一次年检的期限为三年。"},"2.6.01-106":{"q":"你已将登记过的房车拖车在冬季停放在露营地六个月。就官方检验（Hauptuntersuchung）而言，适用什么规定？","o":["必须遵守检验印章上标明的日期","检验印章上标明的日期可延长在露营地停放的时间"],"c":"即使您将房车停放在露营地，您也必须遵守年检的期限。技术缺陷，例如锈蚀，可能随时出现，如果不加以修复就会成为安全隐患。"},"2.6.01-108":{"q":"你购买了一辆使用 3 年的轿车供个人使用，车辆技术检验证书是新的。距下一次必须进行技术检验还有多长时间？","o":[],"c":"乘用车的首次年检在三年后进行，此后每次年检每 2 年进行一次。"},"2.6.01-201":{"q":"许可总质量超过 3.5 吨的载货汽车必须每隔多少个月进行官方检验（Hauptuntersuchung）？","o":[],"c":"总质量超过 3.5 t 的卡车，您必须每 12 个月送去做一次主检验。"},"2.6.01-203":{"q":"公交车必须每隔多少个月进行官方检验（Hauptuntersuchung）？","o":[],"c":"即将推出……"},"2.6.01-205":{"q":"你被要求将许可总质量 18 吨的载货汽车送交车辆技术检验。你需要哪些车辆证件？","o":["行驶证第一部分（机动车登记证）","检验记录簿","行驶证第二部分（机动车所有权证）"],"c":"对于最大质量 18 t 的卡车，您应随身携带行车日志（行驶记录簿）和登记证书第一部分（也称为车辆登记文件）。"},"2.6.01-206":{"q":"你被要求将客车送交安全检查。你需要哪些车辆证件？","o":["行驶证第一部分（机动车登记证）","检验记录簿","行驶证第二部分（机动车所有权证）"],"c":"即将推出……"},"2.6.01-207":{"q":"你被要求将许可总质量 18 吨的拖车送交车辆技术检验。你需要哪些车辆证件？","o":["行驶证第一部分（机动车登记证）","检验记录簿","行驶证第二部分（机动车所有权证）"],"c":"对于送去进行年检的最大总质量 18 t 的拖车，需要出示登记证书第一部分（登记证书）以及行车日志。"},"2.6.01-208":{"q":"检验记录簿中登记哪些内容？","o":["车辆技术检验","安全检查","行驶记录仪检验"],"c":"在行车日志中会记录年检和安全检查的日期。\n行驶记录检查（Fahrteinschreibeüberprüfung）的日期并不属于其中。"},"2.6.01-209":{"q":"你怎样知道何时需要送车进行下一次安全检查？","o":["查看带检验标签的安全检查标牌","查看行驶证第一部分中的登记记录","查看车牌上的检验标签"],"c":"当您下次必须接受安全检查时，您会认出带有标记的 SP（安全检查）标志。另外两个答案是错误的。"},"2.6.01-210":{"q":"客车和公交车进行车辆技术检验的法定时间间隔是多久？","o":[],"c":"公共汽车和长途客车行驶里程多并运送人员，因此公共汽车和长途客车必须每 12 个月接受一次年检。"},"2.6.02-002":{"q":"哪些改装会导致使用许可（Betriebserlaubnis）失效？","o":["安装边车","安装不同尺寸的轮胎","安装后雾灯"],"c":"加装边车或安装不同尺寸的轮胎会改变您车辆的行驶特性，从而导致您的行驶许可被吊销。安装后雾灯不会改变您车辆的行驶特性，因此是允许的。"},"2.6.02-003":{"q":"哪些改装会导致使用许可（Betriebserlaubnis）失效？","o":["安装不同功率的发动机","安装导流罩","安装收音机"],"c":"您车辆的下一次技术检验（年检）可以在登记证书第一部分中查到，也可以在您后车牌上的检验标牌上查到。"},"2.6.02-005":{"q":"哪些改装会导致使用许可（Betriebserlaubnis）失效？","o":["改变传动比","改装发动机以提高功率","安装电启动器"],"c":"更改传动比或发动机功率会改变您车辆的行驶特性，从而导致您的行驶许可被吊销。"},"2.6.02-007":{"q":"你持有 A1 类驾驶许可。下列描述的哪些车辆你允许驾驶？","o":["排量 120 cm³；功率 11 kW；结构最高车速 80 公里/小时","排量 100 cm³；功率 12 kW；结构最高车速 90 公里/小时","排量 150 cm³；功率 10 kW；结构最高车速 80 公里/小时"],"c":"持有 A1 类驾驶证，您可以驾驶最高速度 80 km/h、排量 120 cm³、功率 11 kW 的车辆。"},"2.6.02-010":{"q":"当你的车辆机动车责任保险到期时，有哪些要求？","o":["不得再在道路交通中使用","必须在登记中心注销","必须在技术检验中心送交检验"],"c":"您的车辆必须投保，没有保险您不得驾驶它。"},"2.6.02-011":{"q":"何时你不允许在公共道路上驾驶轻便摩托车？","o":["当你没有机动车责任保险时","当轻便摩托车不具备行驶安全性能时","当未缴纳机动车税时"],"c":"助力自行车必须投保，以便在发生事故时赔偿第三方损失，并且车辆必须处于可安全行驶（适行）状态。"},"2.6.02-012":{"q":"驾驶轻便摩托车的最低年龄是多少？","o":[],"c":"您必须年满 15 岁才能驾驶助力自行车。"},"2.6.02-013":{"q":"驾驶一辆因经过改装而能行驶超过 25 公里/小时的轻便摩托车，会产生什么后果？","o":["因无证驾驶而受到处罚","因使用许可和保险保障已失效而被罚款并受处罚","只要骑该轻便摩托车时不超过 25 公里/小时，就不会有不良后果"],"c":"将您的助力自行车改装使其行驶速度超过 25 km/h，会使您的行驶许可和保险失效，并且您可能因无相应许可驾驶而被罚款。"},"2.6.02-014":{"q":"什么会导致轻便摩托车的使用许可失效？","o":["疏通消声器","改变传动比","安装第二个后视镜"],"c":"影响您摩托车行驶特性的改动，例如传动比、消声器，可能导致行驶许可被吊销。"},"2.6.02-015":{"q":"你必须随身携带哪些证件？","o":["使用许可（Betriebserlaubnis）","检验证书","保险证明"],"c":"驾驶时您必须始终随身携带保险证明、行驶许可、检验证书，以备警方检查。"},"2.6.02-016":{"q":"你想在公共道路上行驶。你必须为车辆投保哪种保险？","o":["机动车责任保险","车辆综合保险","法律费用保险"],"c":"法律要求您必须为驾驶您的车辆投保机动车责任险，该保险在发生事故时赔偿对第三方造成的损害。"},"2.6.02-017":{"q":"什么能证明你已为车辆投保机动车责任险？","o":["有效的保险号牌","保险证明","使用许可（Betriebserlaubnis）"],"c":"您可以出示保险证明，或者拥有一块有效的保险号牌。"},"2.6.02-018":{"q":"保险号牌的最长有效期为多久？","o":["1 年","2 年","车辆整个使用期"],"c":"保险号牌有效期最长为 1 年。"},"2.6.02-023":{"q":"你两轮车的保险标识已失效。如果你仍继续驾驶，会产生什么后果？","o":["我必须预期被处以罚款或监禁","发生的任何事故损失我将自行承担","我只能以步行速度行驶"],"c":"法律要求必须投保才能驾驶。没有保险，您将面临罚款或监禁的风险。如果您在没有保险的情况下发生事故，您必须自行承担对第三方的任何损害。"},"2.6.02-024":{"q":"如果你想驾驶排量大于 200 cm³ 的摩托车，必须随身携带哪些证件？","o":["我的驾驶证","行驶证第一部分（机动车登记证）","行驶证第二部分（机动车所有权证）"],"c":"要驾驶，您需要持有您的驾驶证以及登记证书第一部分，以证明您本人和该摩托车都具有驾驶资格。"},"2.6.02-025":{"q":"如果你想驾驶轻型摩托车，必须随身携带哪些证件？","o":["我的驾驶证","运行许可或行驶证第一部分（机动车登记证）","行驶证第二部分（机动车所有权证）"],"c":"要驾驶，您需要持有您的驾驶证以及登记证书第一部分，以证明您本人和该摩托车都具有驾驶资格。"},"2.6.02-026":{"q":"如果你想驾驶小排量摩托车，必须随身携带哪些证件？","o":["我的驾驶证","运行许可或符合性证书（COC 文件）","保险证书"],"c":"您必须持有全部三份文件：您的驾驶证、一份保险证明，以及一份行驶许可或符合性证书。"},"2.6.02-027":{"q":"如果你想驾驶强制登记车辆，必须随身携带哪些证件？","o":["我的驾驶证","行驶证第一部分（机动车登记证）","行驶证第二部分（机动车所有权证）"],"c":"作为汽车驾驶员，您必须始终随身携带您的驾驶证和车辆登记证书（登记证书第一部分）。车辆所有权证明（登记证书第二部分）应妥善保存在家中。它作为所有权证明，驾驶时无需携带。"},"2.6.02-028":{"q":"如果你想在国内从事不定期客运，必须随身携带下列哪些证件？","o":["批准文书","我的驾驶证","保险证书"],"c":"即将推出……"},"2.6.02-030":{"q":"对车辆的技术改装导致运行许可失效。如果你仍然在公共道路上使用该车辆，应预料到什么后果？","o":["行政机关罚款","记入道路交通违法者中央登记册","失去我的保险保障"],"c":"如果您在行驶许可已过期的情况下仍在公共道路上使用您的车辆，您将失去保险保障，因为该车辆已不再是当初投保的那辆车。由于在德国有投保义务，无保险驾驶属于违法行为。在警方检查时将被处以罚款，并且您必须预料到在驾驶适合性登记册中被记录在案。"},"2.6.02-031":{"q":"哪种农林用拖车无需拥有自己的登记号牌？","o":["后部装有“25”限速标志的拖车","用于运输农产品的拖车","可以超过 25 公里/小时行驶的拖车"],"c":"即将推出……"},"2.6.02-032":{"q":"你想运输危险货物，但超过允许的豁免限额。为运输该货物你必须满足哪些条件？","o":["持有相应准驾车型的驾驶证","随身携带 ADR 证书","至少年满 25 岁"],"c":"由于您超出了数量限制，您需要为您的驾驶证持有并携带所需的相应准驾车型，以及一份 ADR 证书（危险品运输资格证书）。"},"2.6.02-034":{"q":"此类标牌上的数字表示什么？","o":["提供所运输危险货物的信息","是车辆制造商给出的规格","表示最大载重量"],"c":"这些数字提供有关所运输危险货物的信息。33——我们的 1203，UN 编号——是危险编号（高度易燃液体）（闪点低于 23 ℃）（也称为物质编号）（汽油/燃油）。"},"2.6.02-035":{"q":"你想驾驶一辆许可总质量 8.0 吨、载有橙色警示牌的载货汽车。你必须满足下列哪些条件？","o":["随身携带 ADR 证书","持有 C 类驾驶证","至少 3 年无事故驾驶"],"c":"使用您总质量 8.0 t 的卡车时，您必须满足以下条件：您必须持有并携带驾驶证 C 类以及一份 ADR 证书（危险品运输资格证书）。无事故记录与此无关。"},"2.6.02-036":{"q":"因对车辆进行技术改装而进行了检验。你有义务做什么？","o":["将检验报告或确认书随车携带，必要时更正行驶证第一部分中的登记内容","将检验报告或确认书转交车辆制造商","将检验报告或确认书粘贴到行驶证第二部分的指定位置"],"c":"在对车辆进行技术改造后，通常会在鉴定时生成一份验收报告。但也可能在登记证书第一部分中进行登记。该报告必须由车辆驾驶员在每次行车时携带。应要求时，例如在设卡检查时，必须出示该报告。"},"2.6.02-037":{"q":"由于被禁止的技术改装，一辆轻便摩托车的结构最高车速超过 25 公里/小时。如果我在公共道路上骑这样的轻便摩托车，会有什么后果？","o":["我因无证驾驶构成刑事犯罪","我因未获准驾驶该轻便摩托车而构成行政违法","只要我不超过 25 公里/小时行驶，就没有后果"],"c":"一旦您在车辆上进行任何未经一般营运许可或批准的改动，营运许可即失效。由于驾驶速度超过 25 km/h 的轻便摩托车已属于 AM 类或更高级别，您就是在无有效驾驶证的情况下驾驶。"},"2.6.02-038":{"q":"对车辆改装后需要进行评估。该评估必须何时进行？","o":["改装后立即进行","在下一次检验时进行","在登记管理机关要求时进行"],"c":"改装后必须立即进行鉴定。"},"2.6.02-039":{"q":"对摩托车的哪种技术改装通常会使已颁发的运行许可失效？","o":["对主动齿轮与链轮传动比的任何改变","对发动机功率的任何改变","安装油箱包"],"c":"小齿轮与链轮的原始传动比属于所授予营运许可的一部分。所有影响您车辆驱动装置的改动都必须登记备案。这意味着如果您更改传动比，营运许可即失效。"},"2.6.02-040":{"q":"对两轮车的哪些技术改装可能导致车辆型式认证被撤销？","o":["安装定制车把","改变车轮/轮胎组合","安装相同的发动机"],"c":"如果对车辆进行会改变车辆类型、可能引发危险或使排放或噪音数值变差的改动，营运许可即失效。\n例如，如果您安装特殊车把，或使用未明确批准用于您两轮车的车轮/轮胎组合，您的两轮车营运许可可能失去效力。两轮车是经过批准的。"},"2.6.02-041":{"q":"为了在保险保障不中断的情况下继续行驶，你最迟必须在何时将新的保险证明贴示在你的两轮车上？","o":["3 月 1 日","1 月 1 日","6 月 1 日"],"c":"自 2023 年 3 月 1 日起，保险号牌将失效。为了能够不受过渡期限制继续骑行，请及时办理一块新的号牌。"},"2.6.02-042":{"q":"你摩托车上保险号牌的有效期已过。这对在公共道路上使用该车有何后果？","o":["不得再骑行该摩托车","可以在人行道上推行该摩托车","可以将该摩托车停放在停车场"],"c":"在没有有效保险号牌的情况下，禁止在公共道路上使用两轮车。法律规定了强制保险义务，以便覆盖可能发生的事故费用。\n您可以在没有有效保险号牌的情况下在人行道上推行您的两轮车，因为这不算作“驾驶”。"},"2.6.02-101":{"q":"你的机动车悬架被降低，必须取得专家鉴定。该鉴定必须何时取得？","o":["改装后立即","与下一次官方检验（Hauptuntersuchung）一并进行，最迟在改装后 1 年","在车辆登记管理机关要求时"],"c":"如果您降低车辆（改装悬挂），这项底盘改动必须经过官方鉴定认可。因此必须立即进行鉴定。您必须始终随身携带该报告或确认文件，必要时须将该技术改动的登记记入登记证书第一部分，即车辆登记证书中。"},"2.6.02-104":{"q":"你持有 B 类驾驶许可。你的轿车参数如下：- 空车质量 1900 kg - 许可总质量 2400 kg - 许可牵引载荷 1500 kg 你允许牵引哪种拖车？","o":["1000 kg","1200 kg","1500 kg"],"c":"无论上述信息如何，对于 B 类驾驶证，一辆汽车加一辆拖车的总质量不得超过 3,500 kg。当汽车满载时，所载拖车的重量不得超过 1,100 kg。例外情况：汽车的最大允许质量为 3,500 kg，且拖车重量低于 750 kg。"},"2.6.02-201":{"q":"你持有 C 类驾驶许可。你的载货汽车参数如下：- 空车质量 9000 kg - 许可总质量 18000 kg - 许可牵引载荷 22000 kg 你允许牵引哪种拖车？","o":["750 kg","18000 kg","22000 kg"],"c":"对于 C 类，不得超过拖车最大许可质量 750 kg。"},"2.6.02-202":{"q":"你持有 C1 类驾驶许可。你的载货汽车参数如下：- 空车质量 3500 kg - 许可总质量 6200 kg - 许可牵引载荷 9300 kg 你允许牵引哪种拖车？","o":["750 kg","3500 kg","6200 kg"],"c":"根据这些数据，您的拖车重量不得超过 750 kg。"},"2.6.02-203":{"q":"你持有 D 类驾驶许可。你的公交车参数如下：- 空车质量 13000 kg - 许可总质量 18000 kg - 许可牵引载荷 2000 kg 你允许牵引哪种拖车？","o":["750 kg","1000 kg","2000 kg"],"c":"即将推出……"},"2.6.02-204":{"q":"D 类或 D1 类驾驶证的最长签发期限是多久？","o":[],"c":"即将推出……"},"2.6.02-206":{"q":"什么会导致你的公交车驾驶员资格需要重新审核？","o":["你作为公交车驾驶员的知识与能力","你的身体或精神方面的适任资格","你雇主的可靠性"],"c":"即将推出……"},"2.6.02-207":{"q":"D 类或 D1 类驾驶许可何时失效？","o":["未及时续期时","超过 1 年未驾驶公交车时","你作为公交车驾驶员的雇佣关系终止时"],"c":"即将推出……"},"2.6.02-209":{"q":"公交车驾驶员何时不得驾驶？","o":["当他患有须报告的传染病时","当其家庭成员患有须报告的传染病时","当他身体严重不适时"],"c":"即将推出……"},"2.6.02-210":{"q":"你公交车的所有座椅都配备了规定的安全带。你正在从事不定期交通运营。哪种说法正确？","o":["你必须系安全带","你必须告知乘客他们必须系安全带","在城镇内道路不必系安全带"],"c":"即将推出……"},"2.6.02-215":{"q":"在欧盟成员国之间的跨境交通中，公交车必须随身携带哪份证件？","o":["客车和公交车商业跨境客运有效许可证的核证副本","经批准的时刻表","有效的地点说明"],"c":"即将推出……"},"2.6.02-225":{"q":"《公路货运法》规范什么？","o":["商业性货物运输","有偿货物运输","私人货物运输"],"c":"《公路货物运输法》规范收费货物运输和经营性货物运输。私人货物运输不在此列。"},"2.6.02-227":{"q":"你正在执行跨境搬家运输。必须随身携带哪份运输单据？","o":["CMR 运单","行驶证第二部分","保险证明"],"c":"在国际家具运输时，您必须携带 CMR 运单。CMR 是一项公约（国际公路货物运输合同公约）。"},"2.6.02-228":{"q":"你持有依据客运法颁发的批准证书。在不定期客运中，何时必须携带该证书？","o":["在德国境内","在欧盟内德国境外","在欧盟以外"],"c":"即将推出……"},"2.6.02-229":{"q":"你从事有偿的搬家清宅业务。为搬运家具你使用许可总质量 4.5 吨的机动车。运输该货物是否需要《公路货运法》规定的许可？","o":["需要，因为该机动车许可总质量超过 3.5 吨","不需要，因为该工作的实际目的是搬家清宅","不需要，因为小企业无需许可"],"c":"由于您的卡车最大许可质量为 3.5 t，对于总重 4.5 吨的家具运输，您需要一份《公路货物运输法》规定的许可。"},"2.6.02-230":{"q":"关于 C、C1、D 和 D1 类驾驶证，你应注意什么？","o":["驾驶证签发的最长期限为 5 年","最早可在到期前 6 个月申请换发驾驶证","驾驶证的有效期截止日在驾驶证文件上标明"],"c":"三个答案都正确。所提到的各类有效期都最长为 5 年。驾驶证的延期最早可在有效期（5 年）届满前 6 个月申请，并且有效期的截止日期标注在驾驶证上。"},"2.6.02-231":{"q":"你将要运输危险货物，但超过允许的豁免限额。为执行运输你必须随身携带什么证明？","o":["有效的 ADR 培训证书","相应车辆类别的有效驾驶证","上一次危险货物运输的有效记录"],"c":""},"2.6.02-232":{"q":"你在哪里可以找到有关驾驶证有效期的信息？","o":["在你的驾驶证上","在你的驾驶员卡上","在你的驾驶员资格卡上"],"c":""},"2.6.02-233":{"q":"延长驾驶证有效期需要哪些证明？","o":["我的适任能力","我的视力","我的急救培训"],"c":"要延长您驾驶证的有效期，您需要重新提供适合性证明和视力证明。急救培训无需重复进行。"},"2.6.02-234":{"q":"你驾驶载货汽车从事商业货运。在被要求时你必须能证明什么？","o":["运输单据","有效的职业驾驶员资格","有效的货物责任保险单"],"c":"作为商业货运中的卡车驾驶员，您必须随身携带以下文件：\n        1. 运输文件：根据《公路货运法》（GüKG）第 7 条第 1 款第 3 项，必须携带一份包含所运货物、发货人和收货人信息的运输单据。\n        2. 有效的职业驾驶员资格：根据《职业驾驶员资格法》（BKrFQG），您必须提供相应资格的证明，例如在驾驶证上登记关键代码“95”。\n        3. 有效的货物损坏责任保险：根据 GüKG 第 7a 条，需要提供货物损坏责任保险的证明，以覆盖对所运货物的责任。\n\n携带这些文件是法律要求，旨在确保公路运输有序且安全。"},"2.6.02-235":{"q":"依据《公路货运法》，何时需要货物运输许可？","o":["以商业方式从事运输","运输距离超过 100 公里","使用汽车列车进行运输"],"c":"您只有从事商业货运中的货物运输时才需要这份授权。"},"2.6.02-301":{"q":"从事不定期客运时，被要求时你必须向主管人员出示哪份证件供查验？","o":["行驶证第一部分","不定期客运批准文件","乘客事故保险证书"],"c":"即将推出……"},"2.6.02-302":{"q":"作为公交车驾驶员，你通过定期国际班线运送乘客。必须随身携带哪些证件？","o":["行驶证第一部分","目的地国所需的许可","行驶证第二部分"],"c":"即将推出……"},"2.6.02-403":{"q":"农用拖车要免于登记必须满足哪些要求？","o":["该拖车只能由牵引车或自走式作业机械牵引，且行驶速度不超过 25 公里/小时","该拖车只能用于农业或林业用途","该拖车必须每 12 个月进行官方检验（Hauptuntersuchung）"],"c":"即将推出……"},"2.6.02-406":{"q":"保险标识失效时，在公共道路上使用车辆会产生什么后果？","o":["不得再使用","如果驾驶员愿意自行承担所造成损害的赔偿，可以继续使用","如果你的行驶速度不超过骑车人，可以继续使用"],"c":"法律要求必须投保才能驾驶。没有保险您不得驾驶，并面临罚款或监禁的风险。如果您在没有保险的情况下发生事故，您必须自行承担对第三方的任何损害。"},"2.6.02-407":{"q":"如果你想在欧盟内驾驶跨境客运公交车，必须随身携带下列哪些证件？","o":["欧盟客运运单","个人行车日志","无需特定证件"],"c":"即将推出……"},"2.6.02-408":{"q":"载明驾驶员危险货物运输培训的 ADR 证书有效期为多久？","o":["5 年","3 年","无期限"],"c":"ADR 证书（危险品货物驾驶员培训）有效期为 5 年，之后必须重新换发。"},"2.6.02-409":{"q":"驾驶商业货运车辆时你有哪些义务？","o":["采取固定货物所需的一切必要措施","随身携带载明所运货物、装卸地点和委托方的随车单证","为货物编制随车单证"],"c":"在商业货运中，您的义务是采取一切必要措施固定货物，并携带一份随运单据，其中载明所运货物、装卸以及客户的信息。"},"2.6.02-410":{"q":"持有 T 类驾驶证的人在年满 18 岁之前可以驾驶哪些车辆（含拖车）？","o":["40 公里/小时","50 公里/小时","60 公里/小时"],"c":"即将推出……"},"2.6.02-411":{"q":"持有 T 类驾驶证的人在年满 18 岁之后可以驾驶哪些车辆（含拖车）？","o":["60 公里/小时","70 公里/小时","80 公里/小时"],"c":"即将推出……"},"2.6.02-412":{"q":"对车辆的哪些改装可能导致其行驶许可被取消？","o":["安装不同类型的方向盘","改装排气系统","安装替换发动机"],"c":"更换方向盘类型或改装排气系统会改变您车辆的行驶特性，从而导致您的行驶许可被吊销。用同类发动机更换发动机不会改变您车辆的行驶特性，因此是允许的。"},"2.6.02-413":{"q":"下列哪些法规规范危险货物的道路运输？","o":["德国《公路、铁路和内河危险货物运输条例》（“GGVSEB”）","《ADR》","德国民法典（“BGB”）"],"c":"这些规定规范运输事宜，包含在《危险货物条例》（GGVSEB）和 ADR（《关于危险货物国际道路运输的欧洲协定》）中。"},"2.6.02-414":{"q":"客车或公交车从事（国内）不定期客运的许可有效期为多久？","o":["最长 10 年","最长 5 年","最长 2 年"],"c":"即将推出……"},"2.6.02-416":{"q":"跨境公路货运可能需要哪些证明？","o":["ECMT 许可证","双边许可","欧共体执照"],"c":"3 个答案都正确。作为跨境货运的证明，适用欧洲交通运输部长会议（ECMT）许可证、双边授权以及欧共体许可证。"},"2.6.03-001":{"q":"倒车时如果汽车列车的后方视野受阻，正确的做法是什么？","o":["如果与指挥人员的视线中断，必须停车","只有在驶入优先通行道路时才需要指挥人员","在厂区内不需要指挥人员"],"c":"如果您驾驶车组倒车且后方视野受限，您必须确保不危及其他道路使用者。因此，您应接受他人指挥引导交通。这也适用于厂区场地。"},"2.6.03-002":{"q":"机动车从事其他（国内）不定期客运的许可有效期为多久？","o":["最长 5 年","最长 10 年","最长 2 年"],"c":"即将推出……"},"2.6.03-101":{"q":"B 类载货汽车最多允许牵引多少辆拖车？","o":[],"c":"机动车（B 类）后方只允许牵引一辆拖车。但用于客运的（公共汽车拖车）不允许牵引。"},"2.6.03-102":{"q":"你在有坑洼的道路上行驶，你的拖车开始跳动。你必须怎么做？","o":["降低车速以避免打滑","加速以保持汽车列车直线行驶","以相同车速继续行驶并避开坑洼"],"c":"您不应继续加速，因为这会令拖车产生摆动。而应轻踩刹车。降低车速可使拖车重新恢复可控。"},"2.6.03-105":{"q":"当你想在轿车后面使用带惯性制动器的拖车时，必须注意什么？","o":["拖车的实际总质量不得超过轿车允许的牵引载荷","安全分离索（断脱拉索）连接到牵引车上","该汽车列车的最高允许车速为 60 公里/小时，在高速公路上也是如此"],"c":"请确保断裂绳（安全绳）正确固定。它的作用是在脱开时使拖车制动器自动拉紧，从而使拖车停下。惯性制动器与最高允许速度无关。"},"2.6.03-106":{"q":"什么是牵引载荷？","o":["实际被牵引的载荷","拖车的许可总质量","拖车的有效载荷"],"c":"只有实际被牵引的载荷才称为拖车载荷，换言之，就是拖车的重量。制造商规定了用于牵引拖车的这一数值。"},"2.6.03-111":{"q":"你想牵引拖车。何时必须为你的机动车加装额外的后视镜？","o":["如果不加装额外后视镜就无法观察到所有相关道路交通情况时","当拖车的装载平台宽度超过 1.5 米且高度超过 1 米时","当你牵引房车或农林用拖车时"],"c":"作为汽车驾驶员，您有责任确保车辆有足够的视野。如果因拖车而使视野受影响，且规定的后视镜不再足够，您就需要安装附加后视镜。"},"2.6.03-112":{"q":"你想牵引一辆带制动器的拖车。你在哪里可以找到有关你轿车允许牵引质量的说明或规定？","o":["在我轿车的行驶证第一部分中","在我拖车的行驶证第一部分中","在保险证书中"],"c":"关于牵引车能够牵引多少重量的信息，可以在登记证书（第一部分）以及车辆用户手册中找到。"},"2.6.03-113":{"q":"你想把拖车挂接到你的轿车上。你在哪里可以找到有关你轿车最大允许垂直载荷（支撑载荷）的说明？","o":["使用手册","行驶证第一部分","行驶证第二部分"],"c":"关于允许的拖车载荷的信息，可以在牵引车（汽车）的登记证书第一部分及其操作说明中找到。"},"2.6.03-114":{"q":"你想牵引拖车。你必须注意什么？","o":["牵引车的可牵引质量","牵引装置的垂直载荷","拖车的载荷"],"c":"制造商规定最大支撑载荷、有效载荷和拖车载荷可以有多高。如果不遵守这些数值，可能会影响行驶特性，从而导致事故。"},"2.6.03-115":{"q":"你带着拖车在有坑洼的道路上行驶。你的汽车列车开始摇摆。现在你必须怎么做？","o":["降低车速以避免打滑","加速以保持汽车列车直线行驶","迅速反向转向以防止打滑"],"c":"通过降低车速，您可以防止侧滑（甩尾）。"},"2.6.03-116":{"q":"轿车后面最多可以牵引多少辆拖车？","o":[],"c":"根据 StVZO 第 32 条关于牵引拖车的规定：车辆后方只允许牵引一辆拖车，但不允许用于客运的（公共汽车拖车）。"},"2.6.03-117":{"q":"你想把许可总质量超过 750 kg 的拖车挂接到你的轿车上。在此情况下你必须确保什么？","o":["必须对球头牵引装置的手柄进行目视和机械检查","安全分离索正确安装","挂接后检查拖车照明系统功能是否正常"],"c":"为使拖车正确连接，离合器爪（连接头）必须完全包裹住球头。如果保险（锁止）卡入，就可以保证离合器爪不会自行脱开。请用手和眼睛检查这一点。此外，最大允许总质量超过 750 kg 的拖车还必须用一根断裂绳（安全绳）固定。行车前请检查是否合适。\n在您检查完所有连接之后，还必须在开始行驶前检查照明。"},"2.6.03-118":{"q":"你驾驶的轿车牵引一辆满载且装有惯性制动器的拖车。此时应特别注意什么？","o":["较长的下坡行驶会使拖车制动器过热","汽车列车在上坡停车状态下惯性制动系统不起作用","分离汽车列车前必须启用拖车的驻车制动"],"c":"为了让拖车在与牵引车分离时不会溜车，你应当拉紧拖车的驻车制动器。在较长距离的下坡行驶中，拖车制动器可能会过热。在这种情况下，你行驶途中可能需要停车休息。\n拖车制动器只有在拖车挂接在牵引车上时才会起作用。如果你上坡行驶，制动时可能并非如此，这取决于你制动的力度。"},"2.6.03-119":{"q":"轿车挂接房车拖车后行驶时，你应注意什么？","o":["超车距离延长","加速能力下降","左转或右转时所需的转弯半径减小"],"c":"超车时，你的超车路段会因所拖挂旅居拖车的长度而延长。由于受旅居拖车重量的影响，你的车辆加速更慢，超车路段也因此相应延长。"},"2.6.03-120":{"q":"你持有 B 类驾驶证。你允许牵引哪种拖车？","o":["不超过 750 kg 的拖车","超过 750 kg，但汽车列车的许可总质量不超过 3500 kg 的拖车","3500 kg 的拖车"],"c":"持有 B 类驾驶证的人员可以牵引最大允许质量为 750 kg 的拖车。只要汽车列车（车辆组合）的最大允许质量不超过 3,500 kg，你的拖车的最大允许质量也可以大于 750 kg。"},"2.6.03-121":{"q":"什么会影响被牵引拖车的行驶稳定性？","o":["位于拖车靠后位置的质心","拖车轮胎胎压不足","减震器漏油"],"c":"拖车的载荷应当这样分配：使重心尽可能靠近拖车的车轴。这样才能确保拖车具有最佳的行驶稳定性和操控性。\n载荷重心过于靠后，会严重影响拖车的行驶稳定性。这会导致拖车在突然转向或较高车速时更容易摆动，从而增加发生事故的风险。\n如果拖车的胎压过低，会影响拖车的行驶稳定性。一方面，胎压过低会导致抓地力变差，使拖车在转弯时更难控制。另一方面，胎压过低会加剧轮胎磨损，增加行驶中轮胎损坏的风险。\n已经出现渗漏的减震器也会对拖车的行驶稳定性产生负面影响。拖车上渗漏的减震器会丧失其减震性能，从而可能导致不稳定的行驶状态以及难以控制的危险情况。"},"2.6.03-301":{"q":"许可总质量 10 吨、带连续制动系统的载货汽车后面，拖车的最大允许质量为多少？","o":["15 t","10 t","20 t"],"c":"在最大允许质量为 10 吨、装有连续制动系统的货车后面，拖车的重量不得超过 15 吨。"},"2.6.03-302":{"q":"计算载货汽车（连续制动系统）后面最大允许牵引载荷时，哪两个质量（重量）必须按比例适用？","o":["载货汽车许可总质量与拖车实际质量之比","载货汽车实际质量与拖车许可总质量之比","载货汽车许可总质量与拖车许可总质量之比"],"c":"在这里你必须把货车的最大允许质量与拖车的实际质量相加进行计算。"},"2.6.03-303":{"q":"载货汽车（连续制动系统）后面的最大允许牵引载荷是多少？","o":["不超过载货汽车许可总质量的 1.5 倍","不超过载货汽车的许可总质量","不超过载货汽车的空车质量"],"c":"货车后面牵引的拖车不得超过货车最大质量的 1.5 倍。"},"2.6.03-304":{"q":"许可总质量 15 吨的载货汽车（连续制动系统）后面的最大允许牵引载荷是多少？","o":[],"c":"当你驾驶总质量为 15 吨的货车时，拖车载荷的质量不得超过 22.5 吨。"},"2.6.03-306":{"q":"带短连接系统的半挂牵引列车有哪些特点？","o":["这类车辆组合的转弯特性不同于传统铰接式载货汽车","连接装置承受更高的磨损","有效装载面积大于采用传统连接装置的铰接式载货汽车"],"c":"在这里你必须考虑所有的特殊性。此类汽车列车的转弯特性与传统的汽车列车不同。连接装置承受的磨损更大，且有效装载面积比采用传统连接方式的同类铰接式列车更大。"},"2.6.03-307":{"q":"你想挂接一辆多轴拖车。你必须确保什么？","o":["必须防止拖车溜车","任何人不得停留在机动车与拖车之间","制动管路必须在即将对接前连接"],"c":"如果你要挂接多轴拖车，你需要防止拖车溜车，并且机动车与拖车之间不得有人。"},"2.6.03-308":{"q":"你想牵引拖车。关于牵引车与拖车之间的电缆，你必须注意什么？","o":["电气连接装置不得损坏","牵引车与拖车的车载电压必须相互匹配","出行前必须检查汽车列车照明系统的功能是否正常"],"c":""},"2.6.03-401":{"q":"用结构最高车速为 32 公里/小时的牵引车，最多可以牵引多少辆带惯性制动器并标有“25”限速标志的拖车？","o":[],"c":"敬请期待……"},"2.6.03-402":{"q":"由一辆载货汽车和两辆带惯性制动器的拖车组成的汽车列车，最高允许以多少速度行驶？","o":[],"c":"敬请期待……"},"2.6.03-403":{"q":"你想用结构最高车速为 32 公里/小时的农用牵引车牵引两辆免于登记、带惯性制动器的拖车。你必须注意什么？","o":["每辆拖车都必须有“25”限速标志","每辆拖车都必须有官方登记号牌","该汽车列车的最高允许车速为 32 公里/小时"],"c":"敬请期待……"},"2.6.03-404":{"q":"用结构最高车速为 32 公里/小时的牵引车，最多可以牵引多少辆免于登记、带惯性制动器的拖车？","o":["两辆拖车，如果装有“25”限速标志","一辆拖车，如果不超速 32 公里/小时","两辆拖车，如果不超速 32 公里/小时"],"c":"敬请期待……"},"2.6.03-405":{"q":"当你打算以超过 25 公里/小时的速度驾驶载货汽车/拖车列车时，最多允许用牵引车牵引多少辆带惯性制动器的拖车？","o":[],"c":"敬请期待……"},"2.6.03-406":{"q":"一辆单轴拖车的实际总质量为 600 kg。最小的垂直载荷（支撑载荷）可能是多少？","o":["24 kg（= 4%）","60 kg（= 10%）","90 kg（= 15%）"],"c":"支撑载荷是指压在牵引车连接装置上的质量。为确定它，汽车驾驶员可以把一块木头或一根管子放在拖车的连接点下方，并在下面放一台体重秤，支撑载荷便会显示出来。对于总质量不超过 3.5 吨的拖车，牵引车所需承受的最小支撑载荷不得低于拖车总重的 4%。不过，25 kg 的最小载荷就已足够。在本例中，最小支撑载荷为 24 kg。装载拖车时，作为汽车驾驶员你必须注意，既不得低于最小载荷，也不得超过最大允许载荷。通过移动载荷，你可以影响支撑载荷。"},"2.6.03-408":{"q":"你驾驶结构最高车速为 40 公里/小时的农用牵引车。你想在该牵引车后面牵引一辆免型式认证的拖车。此时你必须注意什么？","o":["该汽车列车的最高允许车速为 25 公里/小时","拖车上必须显示“25”限速标志","拖车必须有自己的登记号牌"],"c":"为提高运输能力，可以在牵引车后面拖挂两辆拖车。最高允许速度不得超过 25 km/h，并且拖车必须标有“25”的限速标志。"},"2.6.03-409":{"q":"你驾驶结构最高车速为 40 公里/小时的农用牵引车。最多允许牵引多少辆最高允许车速为 25 公里/小时的拖车？","o":[],"c":"为提高运输能力，可以在牵引车后面拖挂两辆拖车。最高允许速度不得超过 25 km/h，并且拖车必须标有“25”的限速标志。"},"2.6.04-202":{"q":"驾驶许可总质量 16 吨的载货汽车，在两周内最多允许驾驶多少小时？","o":["90 小时","92 小时","96 小时"],"c":"最大质量为 16 吨的货车，在 2 周内只允许驾驶 90 小时。另外两个答案都是错误的。"},"2.6.04-203":{"q":"你驾驶许可总质量 16 吨的载货汽车。连续驾驶 4 个半小时后，继续行驶前所需的最短休息时间为多久？","o":["45 分钟","30 分钟","15 分钟"],"c":"总质量为 16 吨的货车在连续行驶 4 个半小时后，必须至少休息 45 分钟。这既是为了保护你自身，也是为了保护其他道路交通参与者。请注意避免过长的驾驶时段。"},"2.6.04-205":{"q":"驾驶许可总质量 16 吨的载货汽车，每天最多允许的驾驶时间为多久？","o":["9 小时，每周可有两次延长至 10 小时","9 小时，每周可有三次延长至 10 小时","每天 10 小时"],"c":"每周你不得驾驶超过 56 小时。因此，每周可以有两次 9 小时，以及此处 10 小时。"},"2.6.04-208":{"q":"独自驾驶时，最短每日休息时间（不作任何缩短）为多久？","o":["11 小时","10 小时","9 小时"],"c":"如果你是单独驾驶，必须保证 11 小时的休息且不得缩短。如果你过早地继续驾驶，你就没有充分恢复体力，可能会使自己和他人陷入危险。请不要忽视适当的中途休息（休息）。"},"2.6.04-211":{"q":"驾驶许可总质量 6 吨的载货汽车，在两周内最多允许驾驶多少小时？","o":["90 小时","92 小时","96 小时"],"c":"驾驶总质量为 6 吨的货车时，你在最多两周内不得驾驶超过 90 小时。"},"2.6.04-212":{"q":"你驾驶许可总质量 6 吨的载货汽车。连续驾驶 4 个半小时后，继续行驶前所需的最短休息时间为多久？","o":["45 分钟","30 分钟","15 分钟"],"c":"驾驶总质量为 6 吨的货车时，你在连续行驶 4 个半小时后，需要进行一次 45 分钟的休息。"},"2.6.04-216":{"q":"在欧盟内，公交车最多允许不休息连续驾驶多少小时？","o":["4 个半小时","5 小时","5 个半小时"],"c":"敬请期待……"},"2.6.04-217":{"q":"每天最多允许的驾驶时间为多久？","o":["9 小时，每周可有两次延长至 10 小时","每天 9 小时，每周可有三次延长至 10 小时","每天 10 小时"],"c":"敬请期待……"},"2.6.04-218":{"q":"在欧盟内，公交车在两周内最多允许驾驶多少小时？","o":[],"c":"敬请期待……"},"2.6.04-219":{"q":"你在欧盟内驾驶公交车从事不定期交通运营。连续驾驶 4 个半小时后，继续行驶前所需的最短休息时间为多久？","o":["45 分钟","30 分钟","15 分钟"],"c":"敬请期待……"},"2.6.04-220":{"q":"你从事不定期交通运营。独自驾驶时，最短每日休息时间（不作任何缩短）为多久？","o":["11 小时","10 小时","9 小时"],"c":"敬请期待……"},"2.6.04-223":{"q":"你驾驶许可总质量 6 吨的载货汽车。连续驾驶 4 个半小时后所需的最短休息时间为多久？","o":["休息 45 分钟","如果已休息过一个 15 分钟，则休息 30 分钟","如果已休息过三个各 10 分钟，则休息 15 分钟"],"c":"驾驶总质量为 6 吨的货车时，你在连续行驶 4 个半小时后，需要进行一次 45 分钟的休息。或者，如果你在此之前已经休息过 15 分钟，则休息 30 分钟即可。"},"2.6.04-224":{"q":"对于驾驶许可总质量 6 吨商业货运载货汽车的驾驶员，什么构成驾驶休息？","o":["间歇和休息时间","由其本人进行的换胎","协助装货或卸货"],"c":"作为驾驶最大允许质量为 6 吨货车从事商业货运的驾驶员，休息时间和休息期的规定适用于你。"},"2.6.04-225":{"q":"你驾驶用于不定期客运的公交车。连续驾驶 4 个半小时后，驾驶时间必须中断多久，你才能继续驾驶？","o":[],"c":""},"2.6.04-226":{"q":"你驾驶许可总质量 6 吨的载货汽车从事商业货运。你最迟必须在何时停止驾驶以进行休息？","o":[],"c":""},"2.6.04-227":{"q":"你驾驶许可总质量超过 3.5 吨的载货汽车从事商业运输。哪些时间被视为你的驾驶休息？","o":["规定的休息时间","作为乘客乘车的时间","装货和卸货的时间"],"c":"驾驶休息是驾驶员用于恢复体力的时间。在这段时间里，驾驶员不坐在车辆方向盘后面，也不从事任何驾驶活动。在此期间，装卸车辆等工作也是被禁止的。\n驾驶员坐在副驾驶座位上的时间同样算作驾驶休息。"},"2.6.04-228":{"q":"你驾驶车辆从事商业货运或客运。缩短的每周休息时间最迟必须在何时补足？","o":["其后第三周","其后第四周","其后第二周"],"c":"作为从事商业货运或客运的驾驶员，你必须在缩短每周休息时间之后、最迟第三周结束前，用等长的休息时间来补偿。这种补偿旨在弥补因缩短休息时间造成的恢复不足，并确保交通安全。"},"2.6.04-229":{"q":"你驾驶车辆从事商业货运或客运。不作任何缩短的常规每周休息时间最短为多久？","o":[],"c":"该规定要求驾驶员必须有一段至少 45 小时的常规休息期。它旨在提高道路安全性、保护驾驶员的健康并确保公平竞争。"},"2.6.04-230":{"q":"商业运输货物时，谁须遵守行车与休息时间规定？","o":[],"c":"行驶时间和休息时间的规定适用于驾驶超过 2.8 吨车辆的驾驶员；这些规定旨在保护驾驶员和整体道路安全。"},"2.6.04-302":{"q":"驾驶许可总质量 24 吨的载货汽车带拖车，在两周内最多允许驾驶多少小时？","o":["90 小时","92 小时","96 小时"],"c":"如果你驾驶最大质量为 24 吨的货车，在 2 周内最多允许驾驶 90 小时。"},"2.6.04-305":{"q":"驾驶许可总质量 24 吨的载货汽车带拖车，每天最多允许驾驶多少小时？","o":["9 小时，每周可有两次延长至 10 小时","9 小时，每周可有三次延长至 10 小时","每天 10 小时"],"c":"允许的每日行驶时间（最大允许总质量 24 吨）为 9 小时，每周可有两次为 10 小时。"},"2.6.04-307":{"q":"你驾驶许可总质量 24 吨的载货汽车带拖车。连续驾驶 4 个半小时后，继续行驶前所需的最短休息时间为多久？","o":["休息 45 分钟","如果已休息过一个 15 分钟，则休息 30 分钟","如果已休息过三个各 10 分钟，则休息 15 分钟"],"c":"在行驶 4 个半小时后，你需要休息 45 分钟；或者如果你在此之前已经休息过 15 分钟，则休息 30 分钟即可。请避免过多的短暂休息。"},"2.6.04-310":{"q":"如果你驾驶许可总质量 16 吨的载货汽车，连续驾驶多少小时后必须休息？","o":["4.5 小时后","5.0 小时后","5.5 小时后"],"c":"经验法则：总是取每日行驶时间的一半。由于每日行驶时间为 9 小时，所以此处答案是 4.5 小时。"},"2.6.04-311":{"q":"谁须遵守规定的商业货运行车与休息时间？","o":["许可总质量超过 2.8 吨的载货汽车或半挂牵引车（通常情况）","许可总质量不超过 2.8 吨的车辆","包括拖车在内、合计许可总质量不超过 2.8 吨的车辆"],"c":"对于从事商业货物运输的驾驶员，行驶时间和休息时间的规定原则上适用于货车以及总质量超过 2.8 吨的货车。"},"2.6.04-312":{"q":"如果你驾驶许可总质量 6 吨的载货汽车，连续驾驶多少小时后必须休息？","o":["4.5 小时后","5.0 小时后","5.5 小时后"],"c":"对于驾驶总质量 6 吨货车的你，需要在连续行驶 4.5 小时后中断行驶进行休息。"},"2.6.04-313":{"q":"如果你驾驶许可总质量 20 吨的铰接式载货汽车，连续驾驶多少小时后必须休息？","o":["4.5 小时后","5.0 小时后","5.5 小时后"],"c":"对于总质量 20 吨的鞍式牵引车（半挂车），你需要在行驶 4.5 小时后休息一次。"},"2.6.04-314":{"q":"如果你驾驶许可总质量 6 吨的载货汽车从事商业货物运输，每天的允许驾驶时间为多少小时？","o":["9 小时，每周另有两次可允许 10 小时","9 小时，每周另有三次可允许 10 小时","每天 10 小时"],"c":"对于最大允许质量为 6 吨、用于商业道路运输的货车，允许的每日行驶时间为 9 小时，每周可有两次为 10 小时。"},"2.6.04-315":{"q":"对于驾驶许可总质量 16 吨商业货运载货汽车的驾驶员，什么构成驾驶休息？","o":["间歇和休息时间","由其本人进行的换胎","协助装货或卸货"],"c":"休息和休息期被视为中途停留。换轮胎或帮忙装卸等属于中断，但不被视为休息或休息期。"},"2.6.04-316":{"q":"对于驾驶许可总质量 24 吨商业货运载货汽车的驾驶员，什么构成驾驶休息？","o":["间歇和休息时间","由其本人进行的换胎","协助装货或卸货"],"c":"在总质量 24 吨的商业货物运输中，你必须遵守休息和休息期的规定。在这些时间里你可以恢复体力。"},"2.6.04-317":{"q":"你驾驶许可总质量超过 3.5 吨的商业货运载货汽车。连续驾驶 4 个半小时后，再次出发前你必须至少休息多久？","o":["如果我此前未休息，则 45 分钟","如果我此前已休息过 15 分钟，则 30 分钟","如果我此前已休息过三个各 10 分钟，则 15 分钟"],"c":"行驶时间的中断就是你的恢复时间。45 分钟，或者如果提前休息过，则为 30 分钟（已先行休息 15 分钟）是正确的。"},"2.6.04-318":{"q":"你驾驶许可总质量 24 吨的半挂牵引车从事商业货运。如果你已不间断驾驶 4 个半小时，必须至少休息多久？","o":[],"c":"在连续行驶 4 个半小时后，你需要休息 45 分钟。"},"2.6.04-319":{"q":"你驾驶许可总质量 24 吨的汽车列车。最长驾驶多久后必须中断驾驶进行休息？","o":[],"c":""},"2.6.05-216":{"q":"驾驶员卡的作用是什么？","o":["证明驾驶时间与休息时间","通行费证明","驾驶证卡片的替代件"],"c":"使用驾驶员卡，行程中的所有活动都会被存储。它可作为行驶时间和休息时间的证明。"},"2.6.05-217":{"q":"警方可以在检查卡上访问哪些数据？","o":["记录的全部数据","有关货物的全部数据","联邦机动车管理局记录的关于驾驶员的全部数据"],"c":"警察使用控制卡可以访问所有已存储的数据。在你自己的驾驶员卡上，你可以查看自己的行驶时间和休息时间。"},"2.6.05-219":{"q":"驾驶员卡遗失后必须何时报告？","o":["立即","最迟 8 天后","最迟 14 天后"],"c":"驾驶员卡丢失必须立即报告，不能等到明天或后天。"},"2.6.05-220":{"q":"检查的警察何时可以扣留驾驶员卡？","o":["当出示的驾驶员卡属于他人时","当驾驶员明显超速行驶时","当驾驶时间被不当延长时"],"c":"如果检查人员发现出示的驾驶员卡与另一名驾驶员不符，你将失去该卡。另外两个答案都是错误的。"},"2.6.05-221":{"q":"申请驾驶员卡时必须提交什么？","o":["驾驶证卡片","照片","雇主确认书"],"c":"驾驶证需连同照片一并出示，这样才能正确核验你的驾驶资格和身份。不需要雇主的确认。"},"2.6.05-226":{"q":"行驶记录仪记录什么？","o":["驾驶时间","行驶速度","燃油消耗"],"c":"通过控制装置（行车记录仪），会记录行驶时间和行驶速度。这有其交通法规上的原因。"},"2.6.05-227":{"q":"出发前，装货时间如何用该行驶记录仪加以证明？","o":["将其输入行驶记录仪","记录在一张单独的纸上","及时告知雇主"],"c":"通过在行车记录仪（控制装置）上输入，你可以完整地证明所有活动。这样也能记录装卸时间。"},"2.6.05-228":{"q":"该行驶记录仪的插槽 2 有何用途？","o":["用于插入“第二驾驶员”的“驾驶员卡”","使警方能够读取行驶记录仪数据","存放备用卡"],"c":"如果有第二名驾驶员随车，必须使用行车记录仪的第二个插槽。这也被称为多人驾驶（multi-manning）。"},"2.6.06-101":{"q":"操作车辆时，关于车辆高度你必须注意什么？","o":["查明车辆的实际高度","查明超出车辆外部车身货物的实际高度","遵守适用于实际高度的限制"],"c":"在出发前，你应当了解车辆的实际高度，了解超出车辆轮廓的货物的实际高度，并注意与高度有关的禁行规定（地下通道／桥梁）。"},"2.6.06-102":{"q":"什么是允许有效载荷？","o":["最大允许载荷","许可总质量与空车质量之差","许可总质量"],"c":"允许的有效载荷——也就是你可以装载的重量——遗憾的是在车辆登记证书中找不到。但可以通过另外两项信息推算出来：空车质量和允许的总质量。"},"2.6.06-103":{"q":"不带突出货物时，轿车与拖车组成的汽车列车的最大允许长度是多少？","o":[],"c":"不装载货物时，你的车辆最长可达 18.00 m。"},"2.6.06-104":{"q":"关于车辆高度（含货物高度），车辆运营适用什么规定？","o":["在行驶证第一部分中查看车辆高度","测定高出车辆顶部货物的实际高度","遵守法定允许的最大高度 4.5 米"],"c":"你必须在登记证第一部分，即所谓的车辆登记证书中，了解你车辆的确切高度。这样你就能避免在高度受限的路段出现危险情况，以及违反允许总高度的规定。\n如果货物超出车辆轮廓，你需要确定车辆连同该货物时的实际高度。这样你就能确保不超过允许的总高度。"},"2.6.06-201":{"q":"由一辆机动车和一辆拖车组成的汽车列车（含货物）的最大允许长度是多少？","o":["20.75 m","18 m","20 m"],"c":"由一辆机动车和一辆拖车组成的汽车列车，包括货物在内，最长不得超过 20.75 m。"},"2.6.06-202":{"q":"限速器何时必须检验？","o":["每次改变轮胎有效周长尺寸后","每次更换燃油供给装置后","每次更换排气系统后"],"c":"限速装置（超速限制器）的检验，在每次改变燃油供给之后、每次改变有效车轮周长之后都是规定要求的。"},"2.6.06-203":{"q":"谁可以签发限速器检验证明？","o":["经官方认可的车辆制造商","经主管部门授权的修理厂","所有商用车修理厂"],"c":"限速装置的检验证书，只能由经主管部门授权从事此项工作的车间以及官方认可的车辆制造商出具。"},"2.6.06-204":{"q":"你仅持有 B 类和 D 类驾驶证，想在公交车后面牵引一辆拖车。拖车不得超过的最大允许质量是多少？","o":["750 kg","850 kg","1000 kg"],"c":"敬请期待……"},"2.6.06-205":{"q":"在满座的客车中，如果所有乘客都携带行李，你必须预料到什么？","o":["存在超过许可总质量的危险","存在超过许可总轴荷的危险","始终能保证不超过许可总质量"],"c":"敬请期待……"},"2.6.06-207":{"q":"驾驶公交车通过狭窄通道时你必须考虑什么？","o":["外后视镜超出车辆证件中标明的车辆宽度","路面不平时车身可能摆动","外后视镜已计入所标明的车辆宽度"],"c":"敬请期待……"},"2.6.06-208":{"q":"你仅持有 B 类和 D1 类驾驶证。你的公交车参数如下：- 空车质量 5000 kg - 许可总质量 7500 kg - 许可牵引载荷 2000 kg 你牵引的拖车的许可总质量是多少？","o":["750 kg","1500 kg","2000 kg"],"c":"敬请期待……"},"2.6.06-211":{"q":"驾驶载货汽车通过狭窄通道时你必须注意什么？","o":["外后视镜比车辆证件中标明的车辆宽度更宽","在不平路面上车身会摆动","外后视镜已计入所标明的车辆宽度"],"c":"你应当注意，在狭窄路段，外后视镜会超出车辆文件中标明的车辆宽度（可能与文件中的信息不同），而且车辆车身在路面不平时也会有所不同。"},"2.6.06-213":{"q":"在这种情况下，何时你允许留在左侧车道？","o":["包括货物在内，实际最大宽度为 2 米","根据行驶证第一部分（机动车登记证），宽度为 2 米"],"c":"该交通标志表示你的车辆（包括外后视镜和最大载荷）允许有多宽。请注意，你的车辆文件中的尺寸是否包含了外后视镜。"},"2.6.06-215":{"q":"哪些车辆证件包含有关你公交车尺寸的信息？","o":["行驶证第一部分（机动车登记证）","检验记录簿","行驶证第二部分（机动车所有权证）"],"c":"敬请期待……"},"2.6.06-216":{"q":"在这种情况下你必须注意什么？","o":["200 米后左侧车道宽度将变窄","包括外后视镜在内，我的车辆比车辆证件中规定的宽度更宽","左侧车道将在 200 米的距离内变窄"],"c":"上方的交通标志表示车行道将收窄至标志上所示的宽度。附加标志提示车道收窄大约在 200 米后开始。外后视镜要计入车辆文件中标明的宽度。路面不平时的车身倾斜也可能需要更大的宽度。你在这里行驶时要考虑这些因素。"},"2.6.06-301":{"q":"如果货物不向后突出，一辆载货汽车和一辆拖车组成的汽车列车的最大允许长度是多少？","o":["18.75 m","18.00 m","20.00 m"],"c":"由一辆货车和一辆拖车组成的汽车列车，在不超出货物的情况下，最长可为 18.75 m。"},"2.6.06-302":{"q":"铰接式机动车（两轴牵引车、三轴半挂车，非联合运输）的最大允许总质量是多少？","o":["40 t","38 t","44 t"],"c":"鞍式牵引车（铰接式车辆）的最大允许质量不得超过 40 吨。"},"2.6.06-303":{"q":"在采用 40 英尺 ISO 集装箱的联合运输中，铰接式机动车（三轴牵引车、三轴半挂车）的最大允许总质量是多少？","o":["44 t","40 t","38 t"],"c":"对于牵引车有 3 根车轴、挂车有 3 根车轴的鞍式牵引车（铰接式车辆），允许的总质量最多可为 44 吨。"},"2.6.06-304":{"q":"带拖车的载货汽车（两轴载货汽车、三轴拖车，非联合运输）的总质量不得超过多少？","o":["40 t","38 t","44 t"],"c":"汽车列车（两轴货车、三轴拖车，非联合运输）的总质量不得超过 40 吨。"},"2.6.06-305":{"q":"你怎样通过计算检查铰接式机动车（半挂车载荷=垂直载荷）是否超过汽车列车的许可总质量？","o":["牵引车的许可总质量加半挂车的许可总质量减垂直载荷","牵引车的许可总质量加半挂车的许可总质量","牵引车的许可总质量加半挂车的有效载荷"],"c":"你可以用数学方法计算：牵引车的最大质量加上拖车的最大允许质量，再减去挂车支撑载荷，得到预期结果。这样你就能检查是否超过了汽车列车的最大允许总质量。"},"2.6.06-306":{"q":"你组合一辆 5 轴的半挂式机动车（非联合运输）。已知以下车辆数据：许可总质量（牵引车）= 25 t；许可总质量（半挂车）= 34 t；半挂车载荷/垂直载荷（牵引车）= 16 t；半挂车载荷/垂直载荷（半挂车）= 16 t","o":["如果所载货物比有效载荷少至少 3 吨，则允许","即使半挂车满载 34 吨也允许","在任何情况下都不允许"],"c":"如果这一车辆组合至少放弃 3 吨的有效载荷，则允许其运营，因为总载荷为 43 吨。（34 吨 + 25 吨 - 16 吨 = 43 吨）"},"2.6.06-307":{"q":"由一辆载货汽车和两轴拖车组成的汽车列车（含货物）的最大允许长度是多少？","o":[],"c":"你由一辆货车和一辆两轴拖车组成的汽车列车，连同其货物在内，长度可以超过 20.75 米。"},"2.6.06-308":{"q":"你怎样确定由牵引车和刚性拉杆拖车组成的汽车列车的最大许可组合质量？","o":["当大于牵引车允许的垂直载荷时，拖车的许可总质量减去拖车的垂直载荷","当小于牵引车允许的垂直载荷时，拖车的许可总质量减去拖车的垂直载荷","当大于牵引车允许的垂直载荷时，拖车的载重量减去拖车的垂直载荷"],"c":"你可以用以下数据计算允许的总牵引质量：牵引车的最大允许质量加上拖车的最大允许质量，再减去拖车的牵引杆载荷（若该载荷大于牵引车允许的最大牵引杆载荷）。"},"2.6.06-401":{"q":"带有安装式作业机具的该牵引车的最大允许宽度是多少？","o":[],"c":"敬请期待……"},"2.6.06-402":{"q":"牵引车的最大允许尺寸 X 是多少？","o":["3.5 m","2.5 m","4.5 m"],"c":"敬请期待……"},"2.6.06-403":{"q":"农用牵引车的最大允许尺寸 X 是多少？","o":["12 m","8 m","10 m"],"c":"敬请期待……"},"2.6.06-404":{"q":"载货汽车与拖车（含货物）的最大允许长度是多少？","o":[],"c":"敬请期待……"},"2.6.06-405":{"q":"从多少宽度起，牵引车必须配备这些警示牌？","o":[],"c":"敬请期待……"},"2.6.06-406":{"q":"尺寸 X 的最大允许长度是多少？","o":[],"c":"敬请期待……"},"2.6.06-407":{"q":"《公路货运法》适用于许可总质量超过多少的商业货运车辆或汽车列车？","o":["超过 3.5 吨","2.8 吨及以上","3.0 吨及以上"],"c":"对于最大质量达到 3.5 吨、用于营业性货物运输的机动车或车辆组合，须遵守道路运输法。"},"2.6.06-408":{"q":"你某一准驾车型的驾驶证有效期已过。这会产生什么后果？","o":["该准驾车型的驾驶证已失效","禁止驾驶该准驾车型的机动车","该准驾车型的驾驶证仅可继续用于私人出行"],"c":"后果是：禁止驾驶这一类别的机动车，且该类别的驾驶证被吊销。它不得用于私人出行。"},"2.6.07-001":{"q":"使用导航系统和公路地图时你必须注意什么？","o":["内容可能在购买后不久就过时","即使是最新的内容也可能与现实不符","所有导航系统都能自动更新"],"c":"使用导航系统时，你应当意识到，即使是较新的内容也可能与现实有出入，而且内容可能在购买后不久就会过时。尽管有自动更新，也无法保证内容始终是最新的。"},"2.6.07-101":{"q":"在国外进行路线规划时你必须注意什么？","o":["适用于市内道路使用的规定（例如城市拥堵费）","在环保区行驶的标识要求","适用的限速规定"],"c":"在出行前，先了解国外适用哪些规定。"},"2.6.07-204":{"q":"规划路线时你必须考虑什么？","o":["因各联邦州假期交通可能造成的交通阻碍","因施工工地可能造成的交通阻碍","尽可能有趣的路线"],"c":"在规划路线时，请注意因道路施工可能造成的交通延误，以及各州因假期出行交通可能造成的交通延误。"},"2.6.07-206":{"q":"公路地图中的信息会与实际状况不一致吗？","o":["公路地图甚至在出版前就可能已过时","公路地图有效期为 4 年，之后必须更换","汽车俱乐部和石油公司出版的公路地图从不与实际状况不一致"],"c":"道路地图可能在出版后不久就被修订而过时。请注意尽量关注地图的日期（出版日期）。"},"2.6.07-207":{"q":"公路地图上的比例尺 1:300000 告诉你什么？","o":["地图上 1 厘米相当于实际 3 公里","地图上 1 厘米相当于实际 300 公里","地图上 1 厘米相当于实际 30 公里"],"c":"该比例尺表示，地图上 1 厘米相当于实际 3 公里。"},"2.6.07-209":{"q":"你沿高速公路行驶，想直接去翁特巴赫（Unterbach）。你在哪里驶离高速公路？","o":["在杜塞尔多夫/埃尔克拉特（Düsseldorf/Erkrath）高速公路出口","在杜塞尔多夫南（Düsseldorf-Süd）高速公路枢纽","在希尔登（Hilden）高速公路枢纽"],"c":"如果你想去翁特巴赫（Unterbach），应当从杜塞尔多夫／埃尔克拉特（Düsseldorf / Erkrath）的高速公路出口驶出。"},"2.6.07-210":{"q":"你想驾车从汉堡到罗马。初步总体规划应使用哪种地图比例尺？","o":["1:500000","1:50000","1:10000"],"c":"当你从汉堡前往罗马时，可以用 1:500,000 的比例尺进行初步的整体路线规划。"},"2.6.07-212":{"q":"公路地图上的图例提供什么信息？","o":["对地图上符号和标记的说明","用于快速确定距离的直尺","关于地图历史的历史概述"],"c":"道路地图的图例为你提供地图中所用符号和标记的说明，以及便于快速测定距离的距离标尺。"},"2.6.07-213":{"q":"高速公路编号具有以下含义：","o":["南北方向的高速公路为奇数编号","区域性高速公路为三位数编号","东西方向的高速公路为奇数编号"],"c":"高速公路的编号含义是：区域性的高速公路使用三位数字编号，南北走向的高速公路使用奇数编号。"},"2.6.07-214":{"q":"你想驾驶许可总质量超过 7.5 吨的载货汽车沿高速公路从汉诺威到慕尼黑。你可以按多少平均速度估计？","o":["70 公里/小时","80 公里/小时","40 公里/小时"],"c":"对于允许总质量超过 7.5 吨的货车，在从汉诺威到慕尼黑的高速公路上，你应当预计平均时速约为 70 km/h。"},"2.6.07-216":{"q":"你想长途运输活动物。规划路线时你必须考虑什么？","o":["对货物的检查与照料","加油与休息的停靠","动物运输保护规定"],"c":"如果你想长途运输活体动物，在规划路线时应当考虑《动物运输条例》、装载监控与装载维护，以及服务区和休息站。"},"2.6.07-217":{"q":"你想制定一份从法兰克福（奥得河畔）到基尔的路线计划。你必须在不同的中途站点交换货物。就道路和时间而言，规划路线需要哪些信息？","o":["起点、目的地、中途站点顺序、计划装货时间和行车中断","位置、目的地、中途站点、最高车速","位置、目的地、行驶速度"],"c":"在你从法兰克福（奥德河畔）到基尔、并途经多个中间站点的行程规划中，由于涉及货物装卸，应当提供以下信息：起点、终点、途经点的顺序、计划的装卸时段和休息。"},"2.6.07-218":{"q":"你使用比例尺为 1:200000 的公路地图规划行程。地图上 1 厘米相当于实际多少公里？","o":["2 km","10 km","20 km"],"c":"在使用 1:200,000 比例尺的道路地图规划时，地图上 1 厘米相当于实际 2 公里。"},"2.6.07-219":{"q":"在车内使用导航系统时你必须注意什么？","o":["所提供的信息仅供参考","导航设备不应妨碍驾驶员的视野","导航设备不应未固定地在车内随意放置"],"c":"使用导航系统时请注意：所给出的信息只是建议；导航设备不得妨碍你的视线；导航系统不得未加固定地随意放置在车内。"},"2.6.07-220":{"q":"驾驶时哪些活动可能造成极高风险的分心？","o":["在导航仪中输入地址","编写短信","即使通过免提装置使用电话"],"c":"这三种活动都会在行驶过程中分散汽车驾驶员对交通的注意力。汽车驾驶员可能因此无法及时发现危险情况。"},"2.6.07-221":{"q":"为什么在路线规划中必须考虑行车与休息时间？","o":["确保驾驶员能够遵守规定的休息时间","旨在避免驾驶方式受到影响","它缩短行驶距离"],"c":"在路线规划中考虑行驶时间和休息时间很重要，因为这能确保你遵守规定的休息时间，并避免因疲劳影响驾驶。"},"2.6.07-222":{"q":"规划路线时应考虑什么？","o":["行车与休息时间","特定联邦州的公共假日","跨境运输时对方国家的法律规定"],"c":"在规划路线时，你应当考虑行驶时间和休息时间、各联邦州的节假日，以及在跨境交通中还应当考虑另一国家的规定。"},"2.6.07-223":{"q":"使用电子导航设备时必须遵守什么？","o":["应定期更新存储卡","应在车辆静止时输入目的地","应始终遵循导航设备上的指示"],"c":"请注意定期检查是否进行了地图更新，并且应当在车辆静止时输入目的地。"},"2.6.07-224":{"q":"规划路线时你应考虑什么？","o":["行车与休息时间","各联邦州的公共假日","跨境出行时其他国家的规定"],"c":"规划路线时，你应当考虑全部 3 个答案：行驶时间和休息时间、各联邦州的公共节假日，以及跨境交通中另一国家的规定。"},"2.6.07-225":{"q":"规划路线时你应考虑什么？","o":["行车与休息时间","跨境出行时其他国家的规定","各联邦州公共假日禁止行驶的规定"],"c":"规划路线时，你应当考虑行驶时间和休息时间，以及在跨境交通中另一国家的规定。"},"2.6.07-226":{"q":"就路线规划而言应遵守什么？","o":["德国夏季假期交通条例中的规定","关于行车与休息时间的规定","道路施工可能造成的交通阻碍"],"c":"规划路线时，你应当注意因道路施工可能造成的交通阻碍、假期出行规定以及行驶时间和休息时间。所有答案都是正确的。"},"2.6.07-227":{"q":"你在运输杂货。就路线规划而言应注意什么？","o":["装货和卸货点的顺序","装货和卸货所需的时间","结合德国《工作时间法》适用行车与休息时间规定"],"c":"在运输零担货物时，你应当考虑全部 3 个答案：装卸点的顺序、装卸所需的时间（节省时间），以及结合《工作时间法》适用行驶时间和休息时间的规定。（休息并恢复体力）"},"2.6.07-228":{"q":"使用导航系统时你应注意什么？","o":["必须考虑所建议路线上的车辆尺寸","安装的移动导航系统不得妨碍前视野","出发时计算的到达时间已考虑强制的行车与休息时间"],"c":""},"2.6.07-229":{"q":"冬季在其他欧洲国家行驶时你必须注意什么？","o":["轮胎的最小花纹深度","为车辆安装冬季轮胎的义务","随车携带防滑链的义务"],"c":""},"2.7.01-008":{"q":"你的摩托车满载。你怎样驶下较长的山口道路？","o":["换入低挡以利用发动机制动效果","不要在弯道之间行驶过快，以免制动器过热","仅使用前轮制动"],"c":"长时间下坡行驶时，你的制动器有过热的风险。为避免这种情况，尽量利用低挡位下发动机的制动作用，并减少弯道之间的加速／减速。"},"2.7.01-009":{"q":"何时存在摩托车前轮离地的危险？","o":["在低挡下快速加速时","起步时突然松开离合器时","用力拉手刹时"],"c":"快速而突然的加速可能导致前轮离地。在低挡位加速或起步时突然松开离合器，都可能发生这种情况。"},"2.7.01-014":{"q":"你换了摩托车。你第一次驾驶带导流罩的摩托车。有什么不同？","o":["由于风压减小，有开得更快的倾向","对侧风的敏感性增强","摔倒的危险降低"],"c":"导流罩（整流罩）不会降低摔倒的危险。不过，它会增大对侧风的敏感度，但会减弱迎面风，从而产生想要开得更快的倾向。"},"2.7.01-018":{"q":"携带侧挂箱包或包袋时你必须特别注意什么？","o":["避免重量分布不均","不超过摩托车制造商推荐的最高车速","满载时仅使用后制动"],"c":"在摩托车上加装行李会影响其在道路上的行驶表现。请确保不超过制造商建议的载货行驶最高速度，并将重量（左右）均匀分配，以保持摩托车稳定。"},"2.7.01-019":{"q":"如果高速行驶时挂入过低挡位并迅速松开离合器，会发生什么？","o":["后轮抱死并可能侧滑","摔倒往往不可避免","前轮离地"],"c":"如果你挂入过低的挡位并松开离合器，摩托车会猛地减速，可能导致你摔倒或向侧方打滑。"},"2.7.01-020":{"q":"出发前你必须检查摩托车的哪些方面？","o":["后视镜的调整","制动液液位、操纵杆行程","凸轮轴的设置"],"c":"在开始行驶前，请确认后视镜安装正确、调节到位并能正常工作（未损坏、无盲区），并确认制动器工作正常。"},"2.7.01-022":{"q":"何时必须提高胎压？","o":["搭载乘客时","在高速公路上长时间高速行驶时","携带重行李行驶时"],"c":"如果载重更大（额外乘客、沉重行李），或者长途行驶尤其是高速行驶时，需要提高胎压。"},"2.7.01-023":{"q":"搭载乘客时你必须注意什么？","o":["弯道上的行驶特性会改变，尤其是进入和驶出弯道时","在相同条件下，超车需要更长的距离","在相同条件下，制动距离缩短"],"c":"乘客会增加摩托车的重量。这会使加速变慢，超车因此更费时。它会增大转弯时的离心力，并延长制动距离。"},"2.7.01-024":{"q":"为做好制动准备你必须做什么？","o":["将手放在手刹杆上","将脚放在制动踏板上方","换入高挡"],"c":"把手放在手刹（制动杆）上、脚放在制动踏板上，可以缩短你制动时的反应时间。"},"2.7.01-025":{"q":"为什么摩托车制动时后轮比前轮更容易抱死？","o":["后轮上的载荷减小","后轮仍在被驱动","后轮上的载荷增大"],"c":"制动时，更多重量会压在前轮上，后轮承受的重量较少，这可能导致后轮抱死。"},"2.7.01-026":{"q":"在下坡路段转弯时，哪种说法正确？","o":["在弯道前充分制动，使弯道内无需额外制动","开始入弯时要确保即使大幅倾斜也不会进入对向车流区域","当看不到对向来车时，沿理想线路行驶并使用整个车行道宽度"],"c":"下坡时，你需要比在平坦路段的弯道上更多地制动。因此你应当在进入弯道前充分制动，同时还应与对向车道的分界线保持距离，以防需要将摩托车倾斜得更多。"},"2.7.01-027":{"q":"你以较快速度通过一个比你最初设想的更急的弯道。你该怎么做？","o":["收油，进一步增大倾斜","不要猛力制动","立即猛烈转向"],"c":"在这种情况下，猛打方向会很危险，可能导致摔倒。你应当逐渐减速，并更多地倾斜车身以完成更大的转向。如果你在转弯时急刹，转矩力会使车身从向一侧倾斜变为更竖直的姿势，从而增大转弯半径。"},"2.7.01-028":{"q":"把摩托车支起到支架（中央支架）上时，你必须特别注意什么？","o":["地面必须坚硬平坦","不应向下陡斜","不得向上倾斜"],"c":"为避免摩托车倾倒或摔倒，你必须确保地面坚实、平整，且下坡坡度不太陡。"},"2.7.01-029":{"q":"为什么“必须根据视野调整驾驶”这一规则在弯道中尤为重要？","o":["因为弯道可能比预想的更急","因为路面危险污染可能被过晚发现","因为否则你会失去过多动量"],"c":"在弯道中，由于道路的弯曲，视线受限。你应当降低车速，因为可能会出现预料之外的危险因素，如路面污物、障碍物或更急的弯道。"},"2.7.01-030":{"q":"你怎样抵消离心力？","o":["通过倾斜车身","通过降低车速","通过快速加速"],"c":"离心力可以通过降低车速来减小，也可以通过更多倾斜车身来抵消。加速则相反，会增大离心力。"},"2.7.01-031":{"q":"如果摩托车快速加速，可能发生什么？","o":["如果左转，摩托车可能偏离车行道并危及人行道上的行人","如果右转，摩托车可能冲入对向车流","如果直线行驶，行驶稳定性无论如何都会提高"],"c":"转弯时加速会增大离心力，从而增大转弯半径。这可能导致你被带向对向车流或人行道。直线行驶时快速加速会降低稳定性。"},"2.7.01-032":{"q":"在负载行驶前必须调整什么？","o":["弹簧预紧力","胎压","链条张力"],"c":"重载行驶时，请务必提高胎压，并调整悬挂弹簧的预紧力。"},"2.7.01-033":{"q":"出发前哪些检查尤为重要？","o":["后轮胎花纹","载荷均匀（前后、左右）","面罩的状况"],"c":"这三项在开始行驶前都值得检查。请确保头盔面罩状况良好，没有破损或划痕。如果你载货，请确保重量均匀分配，以免影响重心和稳定性。同时还要确保后轮状况良好。"},"2.7.01-034":{"q":"在哪些情况下只应非常谨慎地制动？","o":["在有松散碎石或沙子的车行道上","在有轨电车轨道、下水道井盖和车道标线上","首次使用新轮胎行驶时"],"c":"在湿滑路面上，如湿滑道路、电车轨道、井盖、车道标线，以及土路、有沙石的道路上，以及使用新轮胎行驶时，你都应当小心制动。"},"2.7.01-035":{"q":"摩托车的常规制动方法是怎样的？","o":["同时使用前后制动","仅使用后制动","仅使用前制动"],"c":"你应当同时使用两个制动器，这样制动距离会比只使用其中一个制动器更短。"},"2.7.01-036":{"q":"为什么摩托车的两个制动器必须始终处于完好状态？","o":["为了达到尽可能短的制动距离","为了在一个制动器失效时仍能制动","为了在下坡上安全停放摩托车"],"c":"两个制动器都必须能正常工作：万一其中一个突然失效，另一个可以接替。此外，与只使用一个制动器相比，同时使用两个制动器可以缩短制动距离。"},"2.7.01-037":{"q":"车轮抱死的倾向有区别吗？","o":["有，通常后轮先抱死","有，通常前轮先抱死","没有，通常两个车轮同时抱死"],"c":"制动时，更多重量会压在前轮上，后轮承受的重量较少。因此，后轮往往最先抱死。"},"2.7.01-038":{"q":"制动效果有区别吗？","o":["有，通常前轮制动器的制动效果更强","有，通常后轮制动器的制动效果更强","没有，通常两个制动器的制动效果相同"],"c":"制动时，更多重量会压在前轮上，后轮承受的重量较少，因此前制动器能提供更大的制动力。"},"2.7.01-039":{"q":"你意外驶入一段有松散碎石的道路。你该怎么做？","o":["谨慎降低车速","避免猛力制动和倾斜","仅使用前制动"],"c":"敬请期待……"},"2.7.01-040":{"q":"你的车辆在潮湿天气中长时间露天停放。首次制动时你必须预料到什么？","o":["车轮有危险的抱死倾向","制动效果降低","发动机制动效果降低"],"c":"潮湿时，制动器的效果变差，车轮更容易抱死。不过，这对低挡位下发动机的制动没有影响。"},"2.7.01-041":{"q":"轻便摩托车在弯道上打滑的原因可能是什么？","o":["剧烈制动","潮湿或结冰的路面","沙子或松散碎石"],"c":"由于湿滑路面，如湿路、冰面、沙地、泥土、树叶、鹅卵石路面、井盖等，打滑风险会增加。急刹车也可能导致打滑。"},"2.7.01-042":{"q":"制动距离何时增加？","o":["下坡行驶时","携带重行李时","有逆风时"],"c":"车辆越重，制动距离越长。下坡以及湿滑路面也会延长制动距离。"},"2.7.01-043":{"q":"在潮湿路面行驶时，你必须注意盘式制动的哪些特殊特性？","o":["通常，盘式制动的效果比在干燥路面上来得更晚","通常，盘式制动的效果比在干燥路面上来得更早"],"c":"作为汽车驾驶员，你必须考虑到：路面潮湿时，盘式制动器发挥作用通常比在干燥路面上要晚得多。"},"2.7.01-044":{"q":"高速行驶时，什么会增加冲出弯道的危险？","o":["制动","加速","分离离合器"],"c":"减速或加速会使转向所需的力气变小。因此，高速时“冲出弯道”的危险会增加。分离以获得更大的转向力。"},"2.7.01-045":{"q":"检查胎压时你必须考虑什么？","o":["车辆载荷/乘员人数","轮胎温度","车轮材质（钢/铝）"],"c":"检查胎压时，你还必须考虑温度和车辆载荷。这些因素会影响胎压。相比之下，轮辋的材质则无关紧要。"},"2.7.01-046":{"q":"你先后以 30 公里/小时和 60 公里/小时通过同一弯道。离心力如何变化？","o":["增至四倍","增至两倍","保持不变"],"c":"当速度加倍时，离心力会增大到四倍；也就是说，当你以 60 km/h（速度是原来的两倍）通过该弯道时，离心力为四倍。"},"2.7.01-047":{"q":"转弯行驶时，什么会增加离心力对车辆的作用？","o":["更高的车速","更小的弯道半径","更高的胎压"],"c":"速度会直接影响离心力的大小。当车速加倍时，你的制动距离变为四倍。弯道半径越小，离心力越大。胎压对离心力没有影响。"},"2.7.01-048":{"q":"你驾驶右侧带边车的摩托车。在弯道上必须采用哪种驾驶技术？","o":["右弯道适度加油","左弯道收油并轻踩制动","所有弯道都分离离合器"],"c":"带边车（挎斗）行驶会增加重量，因此转弯时你需要更慢。"},"2.7.01-049":{"q":"为降低在弯道上倾覆的风险，带边车摩托车的乘客应坐在何处？","o":["坐在边车中","坐在摩托车上","乘员的位置没有影响"],"c":"为保持带边车摩托车的稳定，重心两侧的重量应当均匀分配。因此第二名乘客应当坐在边车里。"},"2.7.01-050":{"q":"驾驶摩托车带边车（边车在右）时，如果右弯道边车离地，你可以怎么做？","o":["收油、制动，将身体重心向右移动","减小转向角，在所在车道内画出更宽的弧线","增大转向角，加速"],"c":"向右转弯时，转矩力会把边车向上抬。为减小这种转矩，你可以减速、把身体重心向右移，并转得更大（半径更大）。"},"2.7.01-051":{"q":"右侧带边车的摩托车在右弯道行驶过快时可能发生什么？","o":["边车离地，整个组合倾覆","摩托车离地，整个组合向右倾覆"],"c":"向右转弯时，转矩力会把边车向上抬。高速时边车可能被抬起、失去与地面的接触并翻倒。"},"2.7.01-052":{"q":"你此前只驾驶过单辆摩托车。现在你换驾带边车的组合（边车在右、无制动）。驾驶有何不同？","o":["加速时，组合向右跑偏","转弯时必须转向而不是倾斜车身","制动时，组合向右跑偏"],"c":"由于边车装在你的右侧，你不能向右倾斜车身，而需要转向。加速时边车倾向于被拉向右侧。制动时边车会被拉向左侧。"},"2.7.01-053":{"q":"你此前只驾驶过单辆摩托车。现在你换驾带边车的组合（边车在右、无制动）。有什么不同？","o":["制动时，组合向左跑偏","在右弯道边车可能离地","白天不得开启近光灯行驶"],"c":"由于边车装在你的右侧，你不能向右倾斜车身，而需要转向。向右转弯时，转矩力会把边车向上抬。高速时边车可能被抬起、失去与地面的接触并翻倒。加速时边车倾向于被拉向右侧，制动时边车会被拉向左侧。"},"2.7.01-054":{"q":"关于公交车车门的应急操作，你应了解什么？","o":["应能使车上的任何人在发生事故和故障后打开车门","如果误用，可能导致公交车行驶中车门被打开","只能由驾驶员解除"],"c":"敬请期待……"},"2.7.01-055":{"q":"骑摩托车起步时如果非常迅速地加速，可能发生什么？","o":["乘客可能跌落","前轮可能离地","我可能失去对摩托车的控制"],"c":"快速而突然的加速可能导致前轮离地、乘客摔落以及失去对摩托车的控制，因为前轮与路面之间接触减少或没有接触，转向能力随之减弱或丧失。"},"2.7.01-056":{"q":"你驾驶公交线路车，想从公交车站起步。你必须注意什么？","o":["所有车门均正确关闭","公交车前方没有人员","不妨碍正常行驶的车流"],"c":"敬请期待……"},"2.7.01-058":{"q":"你驾驶带拖车的轿车在潮湿天气下行驶于狭窄的乡村道路，正接近一个视野清晰但很急的左弯。你应怎么做？","o":["我在弯道前降低车速","我保持在车道中央，待重新回到直道后再加速","我只在到达弯道顶点后才制动"],"c":"在转弯前降低车速。要考虑天气状况。请记住，离心力的增长是速度增长的两倍。你只应在弯道顶点处再加速。"},"2.7.01-060":{"q":"用中央支架支起摩托车时，你必须注意什么？","o":["即使仅略微倾斜也可能翻倒","在陡坡上可能难以支起","最好从坐姿将其支起"],"c":"把摩托车架到中撑上需要更大的力气，在陡坡上可能很困难。而且车身向一侧倾斜时也容易翻倒。"},"2.7.01-061":{"q":"如果你的摩托车开始摇摆，你该怎么做？","o":["收油、分离离合器并谨慎制动","降挡并尽可能快地加速","通过迅速反向转向来抵消摇摆"],"c":"如果摩托车开始摆动（抖动），应减速，分离离合器并制动。不要加速，因为那可能加剧摆动并导致事故。也不要试图去抵消它，因为这样做很危险，同样可能导致事故。"},"2.7.01-062":{"q":"你驾驶装有防抱死制动系统（ABS）的摩托车。你怎样执行紧急制动操作？","o":["使用手制动和脚制动实现尽可能好的减速","不要按压脚制动杆，因为 ABS 仅在前轮起作用","间歇操作手制动杆和脚制动杆（点刹）"],"c":"同时使用脚刹和手刹会获得最短的制动距离。ABS 通过在强力制动时防止车轮抱死，改善制动距离。"},"2.7.01-063":{"q":"驾驶员辅助系统可以怎样提供帮助？","o":["有助于提高道路交通安全","有助于辅助驾驶员","用以弥补不适合驾驶的状况"],"c":"驾驶辅助系统能协助汽车驾驶员并提高交通安全，前提是在行驶前已设置好导航设备。不过，驾驶辅助系统无法弥补驾驶能力不足（不适合驾驶）的问题。"},"2.7.01-064":{"q":"如果在弯道中你必须急刹车，你必须注意什么？","o":["我的摩托车会立起（直立）","我必须更用力转向以保持过弯线路","我的过弯线路变小"],"c":"如果你不得不在弯道中急刹，要知道摩托车会因此竖立起来（惯性力）。你必须更用力地转向以保持弯道行驶轨迹。"},"2.7.01-065":{"q":"驾驶四轮全地形车时你必须注意什么？","o":["必须佩戴合适的防撞头盔","四轮全地形车在通过急弯时容易翻车","操控特性与轿车相似"],"c":"转弯时要降低车速，因为四轮摩托车（沙滩车）重心高，容易翻倒。"},"2.7.01-066":{"q":"驾驶四轮全地形车时应遵守什么？","o":["应穿着摩托车防护服","四轮全地形车上必须携带警告三角牌","所需的转向力可能明显大于轿车"],"c":"四轮摩托车没有转向助力，因此转向可能比驾驶汽车更费力。"},"2.7.01-067":{"q":"你驾驶手动变速摩托车。为做好制动准备你必须做什么？","o":["我把手放在手制动杆上","我把脚放在制动踏板上方","我换入高挡"],"c":"把脚和手预先放在制动杆上，以便更快地启动制动过程。"},"2.7.01-068":{"q":"你想使用固定在摩托车侧面的行李箱或边箱。你必须特别注意什么？","o":["应避免重量分布不均","较重的行李应尽可能放置在靠近底部的位置","不得超过摩托车的许可总质量"],"c":"请确保重量均匀分配，以稳定行驶表现。把沉重行李尽量放在低处，使重心尽可能低。"},"2.7.01-069":{"q":"你的摩托车装有牵引力控制系统（TCS）。该系统的作用是什么？","o":["防止起步时后轮空转","在紧急制动操作中稳定摩托车","防止制动时前轮抱死"],"c":"“打滑”是指驱动轮因你加速过猛而失去抓地力时，其转速突然升高。这会触发防滑控制装置，通过制动防止车轮空转。"},"2.7.01-070":{"q":"你正通过一个弯道，随着弯道延伸转弯半径变得更小。你原本预计转弯半径会更大。现在你必须怎样反应？","o":["我增大倾斜角度","我降低车速","我按下紧急熄火开关"],"c":"如果你估计的转弯半径偏大，应当降低车速；通过降低车速，你可以用更小的转弯半径行驶。\n你也可以在弯道中增大倾斜角度，从而能够通过更急的弯道。"},"2.7.01-071":{"q":"当你在通过道路弯道时不得不意外急刹车，你应考虑什么？","o":["我的摩托车有直线行驶的倾向","我应轻柔地反向转向","我的摩托车的行驶线路保持不变"],"c":"当你在弯道中制动时，摩托车会因惯性力而竖立起来。你必须通过有感觉的反向修正转向来抵消这一点。否则你会继续直行，无法转过弯道。"},"2.7.01-072":{"q":"在路面状况差的弯道中，什么会增加打滑风险？","o":["底盘受损","胎压不正确","货物装载不当"],"c":"理想情况下，所有车轮都应以相同的力压在路面上，以确保最佳的抓地力和操控性。如果并非如此，在路面状况不佳时会增加打滑的风险。\n例如，悬挂系统的任务就是让所有轮胎以相同的力保持与路面的接触。如果悬挂系统损坏，它就无法再做到这一点。如果胎压不正确，或者车辆装载不当、装载不均，打滑的风险也会增加。\n这是因为轮胎无法对路面施加相同的力，你会更快丧失抓地力。"},"2.7.01-073":{"q":"你正沿一条坡度陡峭的蜿蜒道路行驶。你的摩托车满载。正确的做法是什么？","o":["我使用低挡行驶，以利用发动机制动","我避免在弯道之间加速到高速","我只使用前轮制动"],"c":"避免在弯道之间加速，因为加速会给制动器带来更大的负担。因此，下坡行驶时不要加速。\n均匀使用前制动器和后制动器，并尽量利用发动机的制动作用来减轻制动器的负担。发动机转速越高，制动作用越大。"},"2.7.01-074":{"q":"何时存在摩托车前轮失去车行道接触的风险？","o":["在低挡下加速","搭载后座乘客时加速","使用前轮制动"],"c":"加速时，重量会向后转移。在低挡位下猛烈加速会使重心移到后轴之后，前轮随之抬起。\n乘客在加速时也会使重量向后转移。这种重量转移会减轻前轮的负担，可能导致前轮抬起。"},"2.7.01-075":{"q":"如果高速行驶时换入低挡，可能发生什么？","o":["后轮可能抱死","摔倒在地的风险很高","前轮可能离地"],"c":"接合离合器时发动机转速突然迅速升高，会产生制动作用。发动机的制动力可能导致你的后轮抱死或打滑，从而失去对路面的抓地力。你可能会失去对摩托车的控制并发生事故。"},"2.7.01-076":{"q":"如果你的摩托车开始摇摆，你应怎样应对？","o":["立即松开油门并减速","在继续行程时避免高速行驶","立即反向转向"],"c":"通过立即降低车速，你可以减小摆动并提高行驶稳定性。摆动发生在高速时。因此继续行驶时请避免开得过快。"},"2.7.01-077":{"q":"摩托车上紧急熄火开关的作用是什么？","o":["关闭发动机","关闭灯光","触发 eCall 系统"],"c":"紧急熄火开关会关闭发动机。你可以用它来在危险情况下迅速关闭发动机，而不必转动钥匙。"},"2.7.01-078":{"q":"关于前轮制动器和后轮制动器的效果，尤其是在较高车速下，适用什么？","o":["前制动的效果更强","后轮制动的效果更强","前轮制动和后轮制动的效果相同"],"c":"制动时，重量会向前转移，给前轮带来更大的负担。因此，前轮制动器通常设计为具有更强的制动效果，以便更容易应对更大的载荷。"},"2.7.01-079":{"q":"什么会导致摩托车高速时发生摇摆？","o":["车轮不平衡","在路面不平处","后部载有重行李"],"c":"在路面不平的道路上高速行驶，或者车轮未做动平衡时，摩托车更容易出现“摆动”，因为路面的凹凸会改变车辆的位置。\n如果摩托车后部载重很大，前轮承受的重量就会减少。高速时摩托车可能会摆动，使你更难控制摩托车。"},"2.7.01-102":{"q":"牵引房车拖车时会发生什么变化？","o":["超车距离显著增加","方向盘的急动作会增加打滑危险","制动距离显著缩短"],"c":"如果你拖挂房车（旅居挂车）行驶，不仅会增加打滑的风险，超车距离和制动距离也会变长。这是由于需要牵引的额外载荷以及拖车的牵引作用。"},"2.7.01-103":{"q":"轿车牵引两轴拖车时会发生什么变化？","o":["转弯和过弯时需要更多的空间","加速能力下降","行驶稳定性提高"],"c":"汽车加拖车的组合在通过弯道和转弯时需要更大的空间。同样，质量也会改变加速能力，加速能力会明显下降。"},"2.7.01-104":{"q":"你驾驶带拖车的轿车在有对向车流的道路上行驶，想左转。再次起步时你必须特别注意什么？","o":["考虑你的轿车与拖车组合的长度","考虑降低的加速能力","通过闪灯警示对向来车"],"c":"带拖车时，你的加速能力更低、质量发生变化、总长度更大。在你重新起步时，必须考虑到这一点。在这种情况下，不得用闪灯（大灯闪烁）来警示对向车流。"},"2.7.01-105":{"q":"你驾驶轿车牵引一辆无制动器的拖车，正接近一段长而陡的下坡。哪种说法正确？","o":["降低车速，必要时及时换入低挡，随时准备制动","考虑拖车的推撞作用","通过频繁分离离合器来减轻轿车制动器的负担"],"c":"要及时减速。尽量使用低挡位。由此启动的发动机制动会辅助脚刹的制动作用。你绝不能把车辆挂入空挡滑行，因为那会使车辆更快。"},"2.7.01-107":{"q":"出发前对带房车拖车的轿车必须检查什么？","o":["拖车的灯光是否正常","通过后视镜的视野是否足够","房车拖车内的乘客是否系好安全带"],"c":"房车（旅居挂车）会遮挡后方视线。因此，你在出发前必须检查后视镜是否能提供足够的后方视野。你还需要确保照明装置工作正常。"},"2.7.01-108":{"q":"你驾驶轿车牵引一辆满载且无制动器的拖车。哪种说法正确？","o":["制动距离增加","反应距离增加","停车距离缩短"],"c":"请注意，一辆满载但没有自身制动器的拖车，会因相应的拖车载荷而延长制动距离，从而延长停车距离。在这种情况下，反应距离不变。"},"2.7.01-109":{"q":"你想在轿车后面牵引一辆单轴房车拖车。你必须检查什么？","o":["轿车的许可牵引载荷或许可拖挂质量是否被超过","因拖车的宽度是否必须加装额外后视镜","该拖车是否获准运送乘客"],"c":"房车会遮挡后方视线。作为汽车驾驶员，你必须检查通过现有后视镜获得的后方视野是否足够。你可能需要在车上加装额外的后视镜。牵引车与拖车必须始终相互匹配。"},"2.7.01-110":{"q":"你想驾驶自动挡轿车（液力变矩器）起步。你必须了解什么？","o":["挂挡时，通常必须用行车制动器将车保持住","只有在发动机停止时才能移动选挡杆","必须大幅提高发动机转速，以免发动机熄火"],"c":"如果你在自动挡车辆中挂入挡位后松开制动（给出“起步”），车辆会试图自行起步。这只能通过操作行车制动器来阻止。选挡杆在发动机静止和运转时都可以并且允许操作。"},"2.7.01-111":{"q":"关于胎压你必须注意什么？","o":["定期检查气压，包括备胎气压","车辆重载时把气压提高到车辆手册中规定的水平","较长行程前降低气压"],"c":"定期检查轮胎气压，可以避免轮胎损坏，还能节省燃油。如果你使车辆承受更大的负荷，就需要调整胎压。"},"2.7.01-112":{"q":"你的轮胎发生故障，必须安装应急备胎。继续行驶时禁止什么？","o":["以超过 80 公里/小时的车速行驶","使用应急备胎行驶超过必要的时间","搭载乘客"],"c":"应急车轮（备用轮）的结构与普通车轮不同，且只允许以最高 80 km/h 的速度行驶。它们的行驶性能较差。你应当只在必要的情况下才使用它们行驶。允许搭载其他人员。"},"2.7.01-113":{"q":"行驶时你注意到轿车持续向左跑偏。原因可能是什么？","o":["左前轮胎气压过低","前轴车轮定位不正确（前束、车轮外倾）","左后轮胎严重磨损"],"c":"如果你的车辆向左跑偏，以至于需要反向修正转向，那么可能是左轮胎气压过低，或者车轮定位（车轮设定）不同所致。严重磨损的轮胎通常不会造成这种影响。"},"2.7.01-114":{"q":"如果前轮驱动轿车在弯道上加速过度，容易发生什么？","o":["车头容易向外甩出","车辆容易转向过度","车尾容易向外甩出"],"c":"作为汽车驾驶员，你必须始终预料到：如果在转弯时加速过猛，前轮驱动的车辆会甩头（前部甩出）。你的车辆更可能转向不足，而不是转向过度。"},"2.7.01-115":{"q":"如果后轮驱动轿车在弯道上加速过度，容易发生什么？","o":["车尾容易向外甩出","车头容易向外甩出","车辆容易转向不足"],"c":"你应当始终预料到：如果在转弯时加速过猛，后轮驱动的车辆会甩尾（后部甩出）。它更可能转向过度，而不是转向不足。"},"2.7.01-118":{"q":"驱动防滑系统（ASR）有哪些优点？","o":["起步时车轮不空转","在湿滑路面上起步时侧滑危险降低","制动时车轮不抱死"],"c":"汽车的牵引力控制系统（TCS）可防止车轮空转，尤其是在较快加速时。这样就能在很大程度上防止在湿滑路面上起步时车辆向侧方滑移。"},"2.7.01-120":{"q":"你想挂接带球头牵引装置的拖车。哪种说法正确？","o":["牵引装置的卡爪必须牢固地卡住球头，锁止装置必须啮合","必须连接电气线路","支撑轮必须调至行驶时也能转动的状态"],"c":"在带有球式挂接器的拖车上，挂接爪必须牢固地包住球形接头。保险装置必须卡合到位。请确保电气连接工作正常。支撑轮在行驶时不得运转，必须锁定在升高的位置。"},"2.7.01-121":{"q":"挂接带惯性制动器的单轴拖车后你必须做什么？","o":["检查制动器是否正常","将（如有）支撑轮升至最高位置","将安全分离索（断脱拉索）连接到机动车的牵引装置上"],"c":"防脱钢索必须挂在牵引车的连接装置上。对于惯性制动（冲压式制动）装置，当与牵引车的连接断开时，拖车会自动制动。必须检查制动器功能。支撑轮在行驶时不得运转，因此应当将其置于升高位置。"},"2.7.01-122":{"q":"装载单轴拖车时你必须注意什么？","o":["轴荷","牵引装置上的载荷","总质量"],"c":"装载单轴拖车时，你必须确保遵守总质量的规定，并且你的载荷不超过允许的轴载荷和支撑载荷。"},"2.7.01-123":{"q":"你想把单轴拖车（惯性制动器，许可总质量 1000 kg）停放在坡道上。你必须做什么？","o":["拉紧驻车制动","在车轮下放置止轮块","挂上倒挡锁"],"c":"你必须始终防止拖车可能发生的溜车。为此，你必须使用驻车制动器，并在车轮前方放置轮挡。通常这类拖车没有倒车锁止装置。"},"2.7.01-124":{"q":"长时间停放的带惯性制动器拖车可能出现哪些危险缺陷？","o":["制动器可能因生锈而失效","电缆连接可能损坏","因日晒胎压可能大幅升高"],"c":"如果你把拖车长时间停放在某处，天气可能造成损坏：电气连接可能受损，制动器可能生锈。阳光照射不会使胎压升高太多，因而不会产生危险的缺陷。"},"2.7.01-125":{"q":"装载拖车时你必须注意什么？","o":["必须牢固装载","除有专门标记外，不得超出后反射器 1 米以上","不得超出牵引车前端 1 米以上"],"c":"请始终注意正确固定你的货物。为了不危及自己和他人，你必须始终拥有清晰的视野并对车辆有完全的掌控。货物必须在后部做出标记，且在前方不得超出 50 cm。"},"2.7.01-126":{"q":"为什么在驶下长坡时不应同时踩下离合器并关闭发动机？","o":["带助力转向的车辆转向会立即变得异常沉重","带制动助力系统的车辆即使大力踩踏板也无法达到全制动效果","电池会过度充电"],"c":"发动机熄火时，发动机制动（制动助力器）无法工作。此时连转向助力也不会起作用。为了迅速有效地应对危险情况，这两者你可能都需要。"},"2.7.01-127":{"q":"为什么在长而陡的下坡上不应踩下离合器？","o":["因为发动机制动将失去作用","因为这会不必要地加剧制动器磨损","因为在这种情况下制动助力装置将不再起作用"],"c":"如果你踩下离合器，发动机制动就不起作用，你就不得不更多地使用行车制动器。其结果是可能发生过热和加剧制动器磨损。"},"2.7.01-128":{"q":"挂接全挂车时哪种说法正确？","o":["应站在驾驶员的视野范围内并引导他","提示驾驶员看不到的障碍物和道路使用者","握住牵引杆直到其锁入牵引装置"],"c":"在挂接多轴拖车时，你应当确保有一名合适的人待在你的视野范围内，观察并指导你，并且这个人能够提醒你注意你看不到的障碍物和道路交通参与者。"},"2.7.01-129":{"q":"你驾驶满载的汽车列车。执行紧急制动时应注意什么？","o":["必须施加更大的制动力","后轮制动器可能作用更强","必须施加更小的制动力"],"c":"如果载重更大，你应当施加更大的制动力。由于额外的重量，后轮制动器也会制动力更大。"},"2.7.01-130":{"q":"你在潮湿车行道上过弯时突然必须制动。装有防抱死制动系统（ABS）的车辆有哪些特殊之处？","o":["转向能力保持的时间更长","车辆始终保持稳定","车辆不可能滑出弯道"],"c":"在湿滑路面上，防抱死系统可防止车轮抱死并缩短制动距离。此外，车辆在制动时仍能更好地转向。在碎石或雪地上，制动距离肯定会更长得多。"},"2.7.01-131":{"q":"汽车列车（轿车牵引房车）在转弯时的转弯特性会有什么影响？","o":["可能向外甩出","可能内切（切入弯道内侧）","通常沿轿车的轨迹行驶"],"c":"尽管谨慎驾驶，拖车仍可能内切弯道甚至还可能甩出。因此汽车驾驶员必须谨慎行事，以排除对他人的危害。"},"2.7.01-132":{"q":"你的摩托车发生钟摆式摆动。原因可能是什么？","o":["载荷","车轮不平衡","以低转速行驶"],"c":"如果你的整辆摩托车前后摆动，这可能是由重载或车轮失衡引起的。"},"2.7.01-133":{"q":"什么会限制车道偏离警告系统的功能？","o":["脏污的路面","没有道路标线","没有护栏"],"c":"如果系统无法正确识别车道信号，车道偏离预警系统的功能可能会受到限制。这是因为这种由计算机控制的系统是基于不同的光学系统工作的。护栏不会发出信号。车道偏离预警系统的另一个名称是：车道保持辅助（带转向辅助的主动式车道偏离预警系统）。"},"2.7.01-134":{"q":"驾驶纯电动汽车出行前，你应获取哪些信息？","o":["我可以在哪些地点为车辆充电","发生事故后我必须做什么","影响续航里程的因素"],"c":"汽车驾驶员在出发前应当了解电动汽车的续航里程。这与传统车辆的续航里程差别很大，需要更频繁地停车为电池充电。你还应当考虑到，电动汽车内的技术更多。虽然总的来说电动汽车与传统汽车一样安全，但其车身内通常敷设有为超高电压设计的电缆。"},"2.7.01-135":{"q":"你正规划驾驶纯电动汽车进行较长行程。你应注意什么？","o":["电动汽车充电桩的可获得性","电池充电时间","外部环境温度对续航里程的影响"],"c":"如果你计划驾驶纯电动汽车进行较长距离的行程，你应当考虑到，与传统车辆相比，你的车续航里程要低得多。此外，电池的容量还受外部温度的影响。"},"2.7.01-136":{"q":"为纯电动汽车充电时你应注意什么？","o":["充电时间取决于电源","只应使用制造商认可的充电电缆充电","每个加油站都可充电"],"c":"为纯电动汽车充电时，你必须意识到它们无法在每个加油站充电。请只使用制造商认可的充电电缆。根据电源接口的不同，充电时间也会有所不同。"},"2.7.01-137":{"q":"纯电动汽车与内燃机车辆有何不同？","o":["发动机噪音更低","没有直接的尾气排放","空气阻力更低"],"c":"纯电动汽车几乎没有噪音。这类车辆也没有直接的尾气排放。空气阻力取决于车身的体积，而与驱动方式无关。"},"2.7.01-138":{"q":"你驾驶纯电动汽车在居住区行驶。由于发动机噪音较低，你应注意什么？","o":["行人不会注意到我，或比平时更晚注意到我","前方骑行的骑车人会不回头地左转","后方车辆会紧跟在我后面"],"c":"驾驶纯电动汽车时，你在路上几乎没有噪音，其他道路交通参与者几乎听不到你的声音。尤其是骑自行车的人，如果他们听不到发动机噪音就会有危险。他们常常不看后面就转向。"},"2.7.01-139":{"q":"你驾驶装有防抱死制动系统（ABS）的机动车。你怎样实现尽可能短的制动距离？","o":["迅速且以最大力度","先轻柔，然后逐渐加大力度","快速间歇地多次并以最大力度"],"c":"如果你驾驶装有自动防抱死制动系统的汽车，那么果断制动并以最大的踏板力制动，可以获得最短的制动距离。ABS 在制动过程中可防止车轮抱死。"},"2.7.01-140":{"q":"带纠正性转向控制的车道辅助系统可以在行驶中帮助你。你应注意什么？","o":["当道路标线清晰时可使车辆保持在车道内","当道路标线较差时不起作用","弥补驾驶能力不足（如疲劳）"],"c":"良好（清晰）的车道标线是车道偏离预警系统完美工作的前提。请记住，技术性的驾驶辅助装置无法弥补驾驶能力不足。作为汽车驾驶员，你必须始终能够干预驾驶过程。"},"2.7.01-141":{"q":"你高速驶入弯道。如果不得不急刹车，可能发生什么？","o":["可能失去与路面的附着力","可能滑出弯道","借助稳定性控制系统始终保持行驶稳定性"],"c":"如果你高速驶入急弯，在急刹时会失去抓地力并滑出弯道。（离心力）"},"2.7.01-142":{"q":"什么可能导致你的机动车在过弯时打滑？","o":["严重转向过度","车速过快","在弯道出口轻柔加速"],"c":"如果你急转方向，车辆可能在弯道上开始打滑。车速过快时也可能发生这种情况。转弯时要调整好车速。"},"2.7.01-143":{"q":"车道保持辅助系统以声音、触觉或光学信号向你发出警告。其原因可能是什么？","o":["我的车辆正在靠近路侧的道路标线","我的车辆正在缩短与前车的安全距离","另一辆车正以不足的侧向间距超越我"],"c":"如果你偏离驶出车道，车道偏离预警系统会通过识别到你正在接近车道标线而发现这一点。不得超出允许的总质量。"},"2.7.01-144":{"q":"在哪些情况下，带转向干预的车道保持辅助系统能为您提供帮助？","o":["在高速公路上","在乡村道路上","在道路标线不清的狭窄施工路段"],"c":"在高速公路和乡村道路上，车道偏离预警系统的转向干预会很有帮助，因为那里的标线清晰可见。\n由于施工路段标线较差、车道狭窄，车道偏离预警系统的转向干预无法进行，因为很可能无法被正确识别。"},"2.7.01-145":{"q":"带转向干预的车道保持辅助系统能在哪项驾驶任务中帮助驾驶员？","o":["直线行驶时","转弯时","超车时"],"c":"如果车道标线良好，带转向干预的车道保持辅助可以在直线行驶时帮助你使车辆保持在车道内。\n转弯时你会跨越车道和标线；车道偏离预警系统在这里无法介入来为你提供支持。超车时，你通过打转向灯向车道偏离预警系统表明你是有意跨越车道标线的。因此，它在超车过程中不会介入。"},"2.7.01-146":{"q":"哪些因素会对车道保持辅助系统的功能产生不利影响？","o":["天气条件","道路标线的状况","施工路段内的附加道路标线"],"c":"如果车道标线状况较差，车道保持辅助就无法识别应当保持的车道在哪里。由于施工区域有额外的车道标线，哪条才是应当保持的车道并不明确。\n天气状况可能影响车道偏离预警系统的传感器。此外，水或雪也会使标线变形。"},"2.7.01-147":{"q":"带转向干预的车道保持辅助系统在什么条件下能最佳地工作？","o":["在道路标线清晰的地方","在路面有积雪斑块的地方","在有附加施工标线的地方"],"c":"车道保持辅助在车道标线清晰时效果最好。\n施工路段中较差的或额外的标线会使车道偏离预警系统无法介入，因为很可能无法被正确识别。\n天气状况可能影响车道偏离预警系统的传感器。此外，雪也会使标线变形。"},"2.7.01-148":{"q":"哪个驾驶员辅助系统具有很高的道路安全潜力？","o":["制动辅助系统","自动紧急制动系统","定速巡航系统"],"c":"自动紧急制动辅助系统会持续探测车辆前方的交通情况。如果即将发生危险，紧急制动辅助系统可以执行紧急制动操作。\n制动过晚或制动力过小往往是交通事故的成因。制动辅助系统通常比人反应更快，因而能提供更高的安全性。"},"2.7.01-149":{"q":"驾驶员辅助系统如何帮助您？","o":["就危险向我发出警告","帮助我完成驾驶任务","在危急的道路交通情况下自动干预"],"c":"在危急的交通情况下，驾驶辅助系统能够迅速反应，并通过转向或制动等方式自动介入。\n如果即将发生危险，它们可以通过灯光、声音和触觉信号向你发出警告。驾驶辅助系统还可以在驾驶任务中帮助你，例如保持在车道内。"},"2.7.01-150":{"q":"驾驶前轮驱动汽车通过弯道时，如果加速过猛，可能导致什么？","o":["车头可能甩出","转向能力可能降低","车尾可能甩出"],"c":"如果你在弯道中给前轮驱动的汽车油门过大，它可能在前轴处甩出。前轮失去对路面的抓地力，你的车辆就无法再转向，而是继续直行并甩出。"},"2.7.01-151":{"q":"主动式变道辅助系统在什么条件下可以执行一次变道？","o":["已探测到标线清晰、有多条车道的车道","在相关安全区域内未探测到任何车辆","已探测到对向车流中有足够大的空隙"],"c":"主动式变道辅助系统只有在相关安全区域内探测不到任何车辆时，才会执行变道。要进行主动变道，辅助系统必须首先识别到带有多个车道的标明车道。"},"2.7.01-152":{"q":"您的机动车配备主动式车道保持辅助系统。该系统的状态显示可指示哪些信息？","o":["已激活","已关闭","存在故障"],"c":"系统必须能够显示其处于开启、关闭或故障状态，因为这对驾驶员很重要。"},"2.7.01-153":{"q":"您的机动车配备车道保持辅助系统。该系统在什么情况下能帮助您？","o":["我无意中偏离车道时","超过最高允许车速时","车辆过快驶过路面车辙时"],"c":"车道保持辅助帮助你保持在车道内。如果你无意中驶离车道，它会向你发出警告。"},"2.7.01-154":{"q":"您的机动车已激活车道保持辅助系统。行驶中它发出警告信号。原因可能是什么？","o":["变道时我忘记打开转向灯","我无意中偏离了车道","我未保持与前车的最小距离"],"c":"如果你无意中驶离车道，车道保持辅助会向你发出警告。如果你在变道时忘记打转向灯，车道保持辅助会把它识别为无意中驶离车道并向你发出警告。"},"2.7.01-155":{"q":"行驶中您正在使用机动车的车道保持辅助系统。当您偏离车道时系统没有反应。原因可能是什么？","o":["道路照明不足","强降水","缺少车道标线"],"c":"由于缺少车道标线、道路照明不足以及强降水，车道偏离预警系统的传感器会受到影响，这意味着无法可靠地识别车道。"},"2.7.01-156":{"q":"您的机动车配备无转向干预的变道辅助系统。行驶中左侧外后视镜上的警告灯闪烁。该警告灯指示什么？","o":["被监控区域内有其他车辆","您现在不可以向左变道","您现在可以无风险地向左变道"],"c":"如果监测区域内有车辆，外后视镜上的警示灯会亮起来提示这一点。"},"2.7.01-157":{"q":"行驶中您正在使用机动车的主动式车道保持辅助系统。当该系统干预时，您如何手动将其覆盖？","o":["通过反向转向","通过打开转向灯","通过加速"],"c":"反向修正转向和开启转向灯可以覆盖（取消）车道保持辅助的介入。"},"2.7.01-158":{"q":"在什么情况下使用主动式变道辅助系统是有意义的？","o":["高速公路","类似高速公路的道路","无标线的道路"],"c":"在高速公路或类似高速公路的道路上，车道标线清晰可见，车道通常也是直的。主动式变道辅助正是在这里发挥作用。"},"2.7.01-159":{"q":"您想要超车，并已通过主动式变道辅助系统启动变道。以下哪项正确？","o":["系统独立完成变道","我必须监控变道过程","系统始终独立保持所有安全距离"],"c":"主动式变道辅助系统在启动后可以自动变道。不过，你必须始终对此进行监控，因为例如安全距离并不总能自动保持。"},"2.7.01-160":{"q":"哪些驾驶员辅助系统必须由您手动激活才能在特定情况下为您提供帮助？","o":["主动式泊车辅助系统","自适应巡航控制系统（ACC）","紧急制动辅助系统"],"c":"主动泊车辅助系统和自适应巡航控制系统不算作与安全相关的辅助系统。因此，你可以手动启动它们。"},"2.7.01-161":{"q":"您想用图中所显示的厢式货车（最大3.5吨）运输家具。与驾驶轿车相比，您必须注意什么？","o":["转弯时更容易侧翻","需特别注意限高","易受侧风影响"],"c":"厢式货车比普通轿车高得多、长得多也宽得多。因此，你应当始终注意通行高度的标示。你还应当注意在弯道中调整车速，因为厢式货车更容易翻车。此外，侧风作用的面积更大，被吹出车道的风险会明显增加。"},"2.7.01-162":{"q":"主动式泊车辅助系统在泊车时如何帮助您？","o":["探测足够大的停车位","在泊车过程中探测所有障碍物","检查在特定地点是否允许停车"],"c":"主动泊车辅助系统必须由你手动启动。启动该辅助系统后，系统会帮助你寻找合适的停车位。"},"2.7.01-163":{"q":"为什么转弯辅助系统可能并不总能探测到有骑行者存在？","o":["传感器上有污物","停放的车辆遮挡了骑行者","传感器损坏"],"c":"转向辅助系统可能因各种情况而工作不正确。因此，如果你与骑自行车的人之间存在障碍物，系统就可能无法识别到骑车人或行人。例如，这些障碍物可能是停放的车辆或路边的树木。同样，传感器被污染或损坏也很容易成为功能不正确的原因。"},"2.7.01-164":{"q":"使用主动式泊车辅助系统时您必须注意什么？","o":["存在危险时必须将其覆盖","意味着我不再需要关注其他道路交通","在泊车过程中可靠地探测所有障碍物"],"c":"启动主动泊车辅助系统后，系统会帮助你寻找并停入合适的停车位。尽管如此，你仍然必须观察交通情况，并在出现危险时手动介入。"},"2.7.01-165":{"q":"您驾驶一辆电动汽车。何时能量回收会削弱制动作用？","o":["电池充满电时","低于电池工作温度时","在节能模式下"],"c":"通过能量回收，电动汽车的电机在制动时像发电机一样工作。因此，制动会产生电能并自动为汽车电池充电。所以，如果电动汽车的电池已经充满，车辆就无法再回收能量，通过能量回收获得的制动效果可能就不起作用了。此时车辆只能依靠传统制动器。如果电池过冷，能量回收也可能减弱或被关闭。这会降低通过能量回收获得的制动效果。"},"2.7.01-166":{"q":"您的车辆配备坡道起步辅助系统。该辅助系统有什么好处？","o":["防止我的车辆无意中后溜","接管松开制动器的操作","同时驱动所有车轮"],"c":"坡道起步辅助可以在你松开制动器时，让你更容易在坡道上起步，从而防止无意中向后溜车。"},"2.7.01-167":{"q":"使用驾驶员辅助系统对车辆进行纵向和横向控制时，以下哪项适用？","o":["我需要了解驾驶员辅助系统的系统局限","出现故障时我必须立即覆盖驾驶员辅助系统","疲劳时我可以让驾驶员辅助系统负责纵向和横向控制"],"c":"在使用驾驶辅助系统之前，你应当了解该系统的局限性。这样你就能确切知道在哪些危险情况和故障下需要格外注意。\n如果你察觉驾驶辅助系统发生故障，应当尽快通过主动操控来接管。通过有针对性的主动操控，可以手动应对驾驶辅助系统在纵向和横向引导中的任何错误。主动操控通常可以通过轻踩油门和制动，或者小心地反向修正转向来触发。"},"2.7.01-202":{"q":"驾驶部分装载的罐式货车时您必须做好什么准备？","o":["过弯时有极大的侧翻危险","有极大的侧滑危险","下坡行驶时转向沉重"],"c":"当你驾驶部分装载（腔室内有部分液体）的罐式车辆时，你必须做好心理准备：在弯道中打滑的风险增加，翻车的危险也会增加。"},"2.7.01-204":{"q":"在长距离下坡路段，您如何避免行车制动器过度磨损？","o":["及时减挡","使用缓速器","使用驻车制动器"],"c":"及时换回低挡，可以避免行车制动器过热。使用减速器（缓速器）也很有帮助。不过，使用驻车制动器是不正确的。"},"2.7.01-205":{"q":"您驾驶满载客车下坡，且低估了坡度。尽管已开启缓速器，车速仍明显上升。您必须怎么做？","o":["使用行车制动器以便能够减挡","松开缓速器，仅用行车制动器调速"],"c":"敬请期待……"},"2.7.01-206":{"q":"乘客上下车时您必须记住什么？","o":["只有在客车停稳后方可启用自动门的开门装置","您必须监视所有直接操作的车门","对于自动门，即使开门指示灯仍亮着，您也可以起步"],"c":"敬请期待……"},"2.7.01-207":{"q":"当您的客车车门独立操作时，您必须记住什么？","o":["您必须定期确认防夹保护功能正常","对于无防夹保护的车门，您必须确保没有乘客被车门夹住","对于有防夹保护的车门，即使开门指示灯仍亮着，您也可以起步"],"c":"敬请期待……"},"2.7.01-208":{"q":"在常规交通中您必须注意什么？","o":["目的地和路线标牌必须显示正确的信息","公交车线路号必须显示在客车尾部","黑暗中，目的地和路线标牌只允许在停车时点亮"],"c":"敬请期待……"},"2.7.01-209":{"q":"在哪些行程中不允许运送站立乘车的乘客？","o":["在非常规交通中","前往度假地的旅游交通中","在常规交通中"],"c":"敬请期待……"},"2.7.01-211":{"q":"冬季您必须做好哪些保障？","o":["踏板必须无积雪和结冰","地板必须保持防滑","乘客区的侧窗不得起雾"],"c":"敬请期待……"},"2.7.01-212":{"q":"关于客车车门您必须注意什么？","o":["行驶时车门区域必须保持畅通","只有所有车门完全关闭时您才可以起步","夏季如乘客有此愿望，您可以在行驶中打开车门"],"c":"敬请期待……"},"2.7.01-216":{"q":"在常规交通中驾驶时，您允许用扬声器系统做什么？","o":["播放收音机的交通信息","发布运营信息","为乘客提供娱乐"],"c":"敬请期待……"},"2.7.01-217":{"q":"在常规交通中，如乘客要求，您必须向他们出示什么？","o":["运价和运输条件","时刻表","带路名索引的城市地图"],"c":"敬请期待……"},"2.7.01-218":{"q":"作为客车驾驶员，何时必须进行干预？","o":["不当使用安全装置（如紧急开门器）时","向车外抛掷物品时","在常规公交车上吸烟时"],"c":"敬请期待……"},"2.7.01-219":{"q":"作为客车驾驶员，何时必须进行干预？","o":["制造噪音骚扰他人时","未经允许打开车门时","饮用清凉饮料时"],"c":"敬请期待……"},"2.7.01-220":{"q":"您可以拒绝运送哪些人？","o":["会危及运营安全与秩序的人","会危及其他乘客安全的人","携带犬只的人"],"c":"敬请期待……"},"2.7.01-221":{"q":"您不允许在客车上携带什么？","o":["危险和散发恶臭的材料","可能对乘客造成伤害的物品","装在笼子里的小动物"],"c":"敬请期待……"},"2.7.01-222":{"q":"在客车上运输行李时您必须注意什么？","o":["行李必须安全装载","通道和车门必须保持畅通","行李只允许在专门标记的行李舱内运输"],"c":"敬请期待……"},"2.7.01-223":{"q":"在客车上运输动物时您必须注意什么？","o":["它们不得被放置在座位上运输","动物不得妨碍乘客","犬只只有在佩戴嘴套时才可运输"],"c":"敬请期待……"},"2.7.01-225":{"q":"驾驶校车在公交站台时必须做好什么准备？","o":["可能在车门关闭时试图上车","可能仍挤进已满载的客车"],"c":"敬请期待……"},"2.7.01-226":{"q":"校车何时必须标有橙色校车标志？","o":["运送学童时","运送学童之前和之后"],"c":"敬请期待……"},"2.7.01-227":{"q":"作为校车驾驶员，在离开站台前您必须做什么？","o":["确保所有车门已正确关闭","确保车头前方没有儿童","关闭危险警示灯"],"c":"敬请期待……"},"2.7.01-228":{"q":"作为校车驾驶员，行驶中何时必须进行干预？","o":["进入划定的隔离区域时","站在座位上时","调换座位时"],"c":"敬请期待……"},"2.7.01-229":{"q":"作为常规公交或校车驾驶员，接近站台时您必须记住什么？","o":["接近某些站台时打开危险警示灯","接近时及时减速，避免急刹车","离开所有站台时打开危险警示灯"],"c":"敬请期待……"},"2.7.01-231":{"q":"作为常规公交驾驶员，您想驶离站台。以下哪项正确？","o":["仅在起步前才打开转向灯","不要强行汇入车流","汇入车流时打开危险警示灯"],"c":"敬请期待……"},"2.7.01-232":{"q":"当您想使用客车的坡道或升降机时，必须注意什么？","o":["坡道只有在客车停稳时才能移入或移出","升降机只有在客车停稳时才能操作","坡道和升降机也可以在客车起步时移入"],"c":"敬请期待……"},"2.7.01-236":{"q":"您驾驶客车执行非常规交通任务。乘客要求您休息。您必须记住什么？","o":["选择一个乘客下车时不会受到危险的地点停车","只允许在有公共厕所的地点休息"],"c":"敬请期待……"},"2.7.01-238":{"q":"一辆带气压制动器的机动车数天未使用。您最早可在何时起步（车辆满载）？","o":["压力警告装置的信号停止后","弹簧储能制动器自动松开后","显示3巴储备压力时"],"c":"如果你的车辆停放了数天，你应当确认压力警示装置不再显示信号。压缩空气系统很可能在停放期间泄漏了气压。"},"2.7.01-242":{"q":"更换车轮后您必须做什么？","o":["按制造商说明拧紧车轮螺母","行驶一小段距离后再次拧紧车轮螺母","通知修理厂已更换车轮"],"c":"车轮螺母应当始终按照制造商的说明拧紧。不要拧得过紧。行驶一小段距离后再复紧车轮螺母也是正确的做法。无需通知车间。"},"2.7.01-247":{"q":"一辆满载车辆的提升桥轮胎损坏。您可以怎么做？","o":["按该车辆的使用说明书更换轮胎","呼叫卡车救援服务","升起提升桥并继续行驶"],"c":"如果提升轴（举升桥）上的轮胎发生爆胎，你需要让该车辆停驶，并按照手册呼叫货车救援服务来更换车轮。把提升轴抬起并继续行驶是不正确的。"},"2.7.01-250":{"q":"哪些货物运输不受《货运法》约束？","o":["货车（含其拖车的允许总质量不超过3.5吨）的商业货物运输","允许总质量不超过7.5吨的货车的商业货物运输","散装货物的商业运输"],"c":"《道路货物运输法》规定，营业性货物运输车辆（包括拖车在内）的总允许质量不得超过 3.5 吨。"},"2.7.01-251":{"q":"在商业货物运输中，哪些车辆需要许可证？","o":["含拖车允许总质量为8吨的车辆","不含拖车允许总质量为4吨的车辆","含拖车允许总质量为3吨的车辆"],"c":"在商业货运中，如果你要驾驶最大允许质量为 8 吨（包括拖车在内）的车辆，以及驾驶最大允许质量为 4 吨（不带拖车）的车辆，都必须出示许可证（许可证书）。"},"2.7.01-253":{"q":"您的客车配备外部动力驱动的坡道或外部动力驱动的升降机。您必须定期检查什么？","o":["安全装置（如反向装置）","坡道的指示灯和声音信号","坡道或升降机在客车行驶时是否工作"],"c":"敬请期待……"},"2.7.01-254":{"q":"在最高时速100公里的客车上，哪些位置不允许使用翻新轮胎？","o":["前轴","所有车轴","后轴"],"c":"敬请期待……"},"2.7.01-255":{"q":"安装车轮时您必须注意什么？","o":["按规定扭矩拧紧车轮螺母","车轮螺母的交替拧紧","仅行驶500公里后才检查车轮螺母"],"c":"请注意按规定扭矩拧紧车轮螺母，并且要交叉（对角）拧紧车轮螺母。行驶的距离长短并不起决定作用。"},"2.7.01-256":{"q":"在冬季条件下操作您的机动车时您必须注意什么？","o":["我的车辆必须装配冬季轮胎","使用前所有上下车踏板必须无积雪和结冰","车辆必须加注足量的风挡玻璃防冻液"],"c":"为确保安全，你必须使用冬季轮胎行驶、配备足够的防冻液，并清除踏板上的冰雪。"},"2.7.01-257":{"q":"您驾驶一辆手动挡机动车。在长距离下坡行驶时如何保护行车制动器？","o":["我提前及时减挡","我使用持续制动器","我使用驻车制动器"],"c":"降挡以增强发动机的制动作用。"},"2.7.01-258":{"q":"为什么您的转弯辅助系统会发出警告？","o":["我车辆右侧有骑行者","我越过了车道分界线","我转弯时车速过快"],"c":"转向辅助系统在货车右转时会检查货车右侧区域是否有骑行者（骑车人）和行人，并警告驾驶员。"},"2.7.01-259":{"q":"您的机动车配备转弯辅助系统。该系统在转弯操作中有什么功能？","o":["就副驾驶侧较弱势的道路使用者向驾驶员发出警告","就副驾驶侧的障碍物向驾驶员发出警告","可以完成整个转弯操作"],"c":"转向辅助系统在货车右转时会检查货车右侧区域是否有骑行者（骑车人）和行人，并警告驾驶员。"},"2.7.01-260":{"q":"如果您驾驶一辆重载卡车通过急弯，可以预期什么？","o":["车速过快时卡车可能侧翻","未充分固定的货物可能滑动","卡车过弯时操控更好"],"c":"装载很重的货车在通过急弯时可能翻车，或者未充分固定的货物可能因离心力而滑动，离心力与车辆和货物的质量成正比。这些力可能使车辆失稳并导致翻车，尤其是在重心较高时。未充分固定的货物可能因这些力而滑动，进一步影响车辆平衡，增加事故风险。因此，正确的货物固定对于确保车辆稳定、提高道路安全至关重要。"},"2.7.01-301":{"q":"当拖车与牵引车之间的电气连接中断或电缆未连接时，拖车上的哪些装置不工作？","o":["自动防抱死装置（ABS）","所有照明装置","防滑装置（ASR）"],"c":"如果拖车的电缆因为与牵引车的电气连接断开而无法工作，那么 ABS 就不工作，照明装置也不会亮。"},"2.7.01-305":{"q":"随车携带的备胎您应定期检查什么？","o":["是否牢固固定","轮胎气压","胎面标识"],"c":"携带备胎时，你应当注意其固定是否牢固，并检查气压。胎纹规格的说法不正确。"},"2.7.01-306":{"q":"您驾驶一辆载货卡车行驶在有坡度的道路上。尽管已开启持续制动器，车速仍明显上升。正确的做法是什么？","o":["继续使用行车制动器制动，以便能够减挡","松开持续制动器，仅用行车制动器保持车速","继续使用行车制动器制动，以便能够加挡"],"c":"在下坡时，你应当设法增强货车的发动机制动作用：通过行车制动器制动，以便能够降挡。"},"2.7.01-307":{"q":"配备传统防抱死制动系统（ABS）的摩托车在弯道中制动时应注意什么？","o":["即使在倾斜状态下也应进行可控制动","自回正力矩取决于制动力","倾斜状态下可传递的制动力增大"],"c":"即使你的摩托车装有 ABS，你仍然应当采用受控的制动方式，因为 ABS 主要是为直线行驶时的强力制动而设计的。在弯道中，你制动越猛，感受到的转矩力越大，这会使摩托车从倾斜姿态趋于竖直。"},"2.7.01-308":{"q":"什么有助于改善摩托车车把的摆动？","o":["以更高的速度行驶","单侧加载重量","以更低的速度行驶"],"c":"车速越高，以及重量分配不均（例如右侧或左侧重量更大）时，摆动会加剧。"},"2.7.01-309":{"q":"什么会导致摩托车开始摆动？","o":["错误安装的整流罩","侧箱负载不平衡","燃油质量差"],"c":"摆动可能是由重量不均（右侧或左侧重量更大）或安装不当的导流罩（整流罩）引起的，后者会使某一侧受到的阻力更大。"},"2.7.01-310":{"q":"汽车列车（牵引拖车的机动车）转弯时，其转弯特性会产生什么效果？","o":["可能向外甩出","可能内切弯道","通常沿牵引车的轨迹行驶"],"c":"车辆组合的转弯特性会使它在转弯时甩出，你也可能内切弯道。"},"2.7.02-001":{"q":"您发现车把轴承有间隙。您必须怎么做？","o":["消除该间隙","保留间隙，因为这样更容易转动车把"],"c":"车把松动并存在间隙是危险的，会使你的摩托车更难控制；为确保安全，请确保车把没有任何间隙。"},"2.7.02-002":{"q":"转动车把时，您发现车把轴承在某处有卡滞。您必须怎么做？","o":["消除卡滞","增大车把轴承的间隙以改善循迹性"],"c":"车把轴承出现卡滞会使你的摩托车更难控制；为确保安全，请确保车把没有任何卡滞。"},"2.7.02-003":{"q":"车把轴承的间隙会导致什么？","o":["可能对行驶性能产生不利影响","行驶性能得到改善","循迹性得到改善"],"c":"车把松动并存在间隙是危险的，会使你的摩托车更难控制；为确保安全，请确保车把没有任何间隙。"},"2.7.02-004":{"q":"转向减震器损坏会对行驶性能产生什么影响？","o":["损坏的转向减震器会导致方向盘抖动","行驶安全性可能变差","行驶安全性只在低速时变差"],"c":"损坏的转向减震器会导致车把振动／抖动，并降低摩托车的稳定性和行驶安全性。"},"2.7.02-005":{"q":"什么会严重损害行驶性能？","o":["车把轴承偏斜","转向减震器损坏","车把轴承有间隙"],"c":"这三点都会使摩托车的转向变差，使其更难控制、更难安全驾驶。"},"2.7.02-006":{"q":"您发现您的摩托车循迹性差。原因可能是什么？","o":["车轮轴承间隙过大","后叉偏斜"],"c":"车轮轴承存在间隙以及后叉变形，都会导致摩托车无法保持行驶方向，使其更难操控、更不安全。"},"2.7.02-007":{"q":"您的摩托车不再保持循迹。什么可能损坏了？","o":["前叉弯曲","车架弯曲","后轮制动器损坏"],"c":"弯曲变形的叉或车架会使摩托车不正（不对中），从而导致难以保持行驶方向。"},"2.7.02-008":{"q":"当您松开油门但不分离离合器时，您的摩托车不再保持循迹。原因可能是什么？","o":["前叉轴承间隙过大","后轮轴承间隙过大","怠速过高"],"c":"后轮轴承和叉轴承存在间隙，都会导致摩托车无法保持行驶方向，使其更难操控、更不安全。"},"2.7.02-010":{"q":"您发现摩托车液压前轮制动器的操纵杆行程明显变长。您必须怎么做？","o":["修理前轮制动器","在下次保养前只使用后轮制动器","立即补充制动液"],"c":"这是前轮制动器损坏的迹象，需要修理或更换。"},"2.7.02-012":{"q":"您摩托车的后视镜支架松动。您怎么做？","o":["固定后视镜支架","拆下后视镜"],"c":"你绝不应拆掉后视镜，必须把它们安装好，因为随时都需要它们来观察后方的交通情况。"},"2.7.02-015":{"q":"在轮胎上您可以检查什么？","o":["胎面磨损是否均匀","胎面","轮胎的使用年限"],"c":"驾驶员可以在轮胎上检查是否达到规定的胎纹深度，以及胎纹磨损是否均匀。此外，还可以从所谓的 DOT 编号读出轮胎的年龄（生产日期）。"},"2.7.02-016":{"q":"什么时候需要更换制动片？","o":["当它们被油污染时","当它们达到磨损极限时","当它们被弄湿时"],"c":"如果制动片被机油严重污染，汽车驾驶员必须更换车辆上的制动片。达到磨损极限时，也必须并且必须进行更换。"},"2.7.02-017":{"q":"起步后不久您测试制动器。为什么？","o":["检查制动器的有效性","快速排出制动系统中的空气"],"c":"为了你自己的安全，在行程开始后应当立即通过制动试验检查行车制动器的有效性。与排放（放气）制动系统不同，你可以自己轻松踩下制动器来完成这一检查。"},"2.7.02-019":{"q":"为什么必须按照车辆制造商的说明更换制动液？","o":["确保制动系统即使在更高负荷下仍能正常工作","确保制动液中的含水率达到不可接受的水平以下","确保制动系统不泄漏"],"c":"制动液还会从空气中吸收水分，因此制动液中的含水量会随时间增加。水分过多会使制动液中产生气泡。如果气泡进入制动管路，制动作用可能完全失效。"},"2.7.02-020":{"q":"在哪些情况下必须测试制动器？","o":["当您驾驶另一辆车时","当车辆较长时间未使用时","每次更换发动机机油时"],"c":"如果车辆长时间未移动，或者你从他人手中接管一辆车，制动试验总是必不可少的。如果车辆进行了换机油，这对制动系统没有影响。"},"2.7.02-021":{"q":"您必须定期检查您车辆轮胎的哪些方面？","o":["气压是否正确","胎面是否足够","是否有外部损伤"],"c":"你应当定期检查车辆轮胎的气压和胎纹深度。此外，还应当定期检查车辆轮胎是否有外部损伤。"},"2.7.02-022":{"q":"如果轮胎气压过高或过低，会导致什么？","o":["行驶性能可能变差","轮胎磨损可能加剧","反应距离可能变长"],"c":"如果轮胎内部气压过高或过低，行驶表现都会变差。此外，轮胎磨损也会增加。如果胎压过低，轮胎会因变形（挠曲）而发热，同时“过软”的轮胎在接触地面处被过度压缩和回弹。其后果是油耗增加、滚动阻力增大，此外行驶稳定性也会下降。如果胎压过高，轮胎可能爆裂。定期检查胎压并考虑制造商建议的数据很重要。胎压对反应距离没有影响。"},"2.7.02-023":{"q":"您用力使轮胎撞到坚硬的障碍物。您必须怎么做？","o":["立即检查轮胎和轮辋","重新拧紧车轮螺栓"],"c":"在继续行驶前，必须彻底检查轮胎和轮辋。轮胎侧壁的损伤尤其危险。变形的轮辋可能导致轮胎从轮辋上滑脱。开裂的铝合金轮毂也可能造成严重后果。车轮螺栓不会承受异常大的负荷，因此无需拧紧。"},"2.7.02-024":{"q":"当您以远低于标准的轮胎气压行驶时会发生什么？","o":["轮胎过度发热","行驶稳定性下降","轮胎磨损减少"],"c":"如果你以明显过低的胎压行驶，轮胎可能过热。气压过低会降低行驶稳定性，车辆会在路面上“漂浮”。胎面中部凹陷导致轮胎接地面积减小，会加剧轮胎磨损。胎压过低还会增加油耗。"},"2.7.02-025":{"q":"尾灯不工作的原因可能是什么？","o":["灯泡损坏","保险丝熔断","起动机损坏"],"c":"如果尾灯失灵，你应当首先检查灯泡。即使是损坏的保险丝也可能导致故障。不过起动机无关紧要，因为它与照明系统没有关系。"},"2.7.02-026":{"q":"您的转向灯控制灯闪烁得比平时快得多。原因可能是什么？","o":["灯泡损坏","转向灯开关损坏"],"c":"如果转向信号的某个灯泡损坏，指示灯（警示灯）的闪烁间隔会明显缩短。闪光灯开关的故障不可能是闪烁变快的原因。"},"2.7.02-027":{"q":"为什么必须立即修理损坏的排气系统？","o":["因为噪音污染","因为排气系统的部件可能掉落到路面上","因为发动机会过热"],"c":"你必须立即修理生锈的排气系统，否则排气管的部分部件可能掉落到路面上。这会危及其他道路交通参与者。此外，生锈的排气部件还会产生不必要的噪音。生锈的排气系统对发动机的温度没有影响。"},"2.7.02-028":{"q":"排气噪音突然比平时更大。您怎么做？","o":["检查排气系统","什么都不做，因为没有人受到危险","更换发动机空气滤清器"],"c":"排气系统很可能已损坏或生锈。生锈的排气系统在部件脱落时可能危及其他道路使用者。必须检查并修理排气系统。空气滤清器不可能是排气声音过大的原因。"},"2.7.02-029":{"q":"如果喇叭不工作，原因可能是什么？","o":["保险丝熔断","喇叭的操作装置损坏","起动机损坏"],"c":"如果车辆的喇叭不响，原因可能是保险丝损坏或开关损坏。起动机故障不会影响喇叭的功能。"},"2.7.02-030":{"q":"制动时您注意到车辆向右跑偏。您应该怎么做？","o":["我去修理厂","只要我能通过反向转向补偿，就不需要修复这个问题","我给制动片涂油"],"c":"制动系统有故障会带来重大风险，可能导致事故。汽车驾驶员必须到专业维修厂排除该故障。"},"2.7.02-031":{"q":"什么会导致制动气缸行程过大？","o":["自动间隙调整器损坏","传动系统上磨损的支座","储气罐压力过高"],"c":"制动缸行程过大的一个原因是传动装置的轴承磨损以及自动间隙调整器失效。储气罐压力过高不会造成制动缸行程过大。"},"2.7.02-032":{"q":"您车辆所有轮胎主胎面允许的最小花纹深度是多少？","o":[],"c":"摩托车和乘用车的轮胎花纹深度必须至少达到 1,6 mm。"},"2.7.02-033":{"q":"您车辆的制动灯不工作。原因可能是什么？","o":["相关保险丝损坏","灯泡损坏","制动液液位过低"],"c":"功能正常的制动灯对参与交通十分重要。如果汽车驾驶员发现车辆有故障，必须立即更换相应的部件。可能的原因包括灯泡损坏和保险丝烧断。"},"2.7.02-034":{"q":"如果启动发动机后机油压力警告灯没有熄灭，您必须怎么做？","o":["我立即关闭发动机","我检查发动机机油油位","我继续行驶到下次更换机油"],"c":"为避免损坏发动机，应立即关闭发动机并检查机油油位。"},"2.7.02-035":{"q":"何时必须立即检查您摩托车的制动系统？","o":["储液罐中的制动液液位明显下降时","拉动制动杆时感觉不到压力点时","行驶中制动控制灯亮起时"],"c":"制动指示灯会警告制动系统存在故障；如果在行驶中亮起，应立即送检车辆。如果制动器单侧制动，车辆就无法保持在车道内。应检查制动系统。"},"2.7.02-036":{"q":"您如何正确进行目视检查以确保制动灯正常工作？","o":["依次操作手刹和脚刹","同时操作手刹和脚刹","操作手刹或脚刹其中之一"],"c":"为确保手制动和脚制动的制动灯都能正常工作，应逐一操作并检查。如果同时操作两个制动器，就无法确定两个制动器都能点亮制动灯。"},"2.7.02-037":{"q":"您的一个车轮重重地撞到路缘石。您应该注意什么？","o":["应在修理厂检查车辆","车辆的操控性可能受到不利影响","轮胎可能有慢漏气"],"c":"如果撞上了坚硬的障碍物，应立即使轮胎和轮辋接受检查，以排除可能的损坏，确保安全行驶。如果轮子在碰撞中受损，可能对车辆的操控产生不利影响。如果轮胎只是轻微受损或没有明显损坏，仍可能逐渐漏气。"},"2.7.02-038":{"q":"您车辆的尾灯不工作。原因可能是什么？","o":["相关保险丝故障","灯泡损坏","远光灯开关故障"],"c":"保险丝烧断或灯泡损坏可能是尾灯失效的原因。"},"2.7.02-039":{"q":"您如何判断盘式制动系统的制动片已磨损？","o":["通过制动片上的磨损标记","通过制动液储液罐中极低的液位","通过手刹杆异常大的松动量"],"c":"制动片上的磨损标记用于检查制动片的磨损状态，并提醒您需要更换制动片。同样，制动液罐中液位过低也可能表明制动片磨损严重。因为制动片磨损时，大量制动液会流入制动缸。"},"2.7.02-040":{"q":"您车辆的制动灯不工作。正确的做法是什么？","o":["我安排修理厂修理车辆","我尝试自行确定原因并修复故障","我安排更换制动液"],"c":"如果灯泡损坏导致车辆的制动灯不亮，应立即修理。如果只是灯泡损坏，您可以自行更换或到维修厂更换。"},"2.7.02-041":{"q":"排气噪音突然变得异常大。正确的做法是什么？","o":["我立即检查排气系统是否有固定故障","我确保任何可能的损坏都得到及时修复","在下一次车辆检测前，我允许超过排气噪音限值"],"c":"应立即检查排气装置，例如当其不再固定牢固时，可能对排气装置造成损坏，从而使噪音变大。因此，在继续骑行之前，务必修复所有缺陷。"},"2.7.02-042":{"q":"您发现摩托车转向头轴承有相当大的间隙。正确的做法是什么？","o":["安排妥善修理转向头轴承","妥善拧紧前轮的快拆轴","妥善将车把拧紧到夹具上"],"c":"转向头轴承出现明显间隙表明轴承已损坏。在继续骑行之前，请由专业人员修理。"},"2.7.02-043":{"q":"您如何发现摩托车转向头轴承的故障？","o":["出现咔嗒声","运动迟滞","该处存在一定间隙"],"c":"转向头轴承应运转顺畅，没有卡点或间隙。例如，如果车把难以转动，可能是转向头轴承的问题。车把发卡会降低摩托车的可控性，因此必须立即由专业人员修理。"},"2.7.02-044":{"q":"您如何发现转向灯损坏？","o":["转向灯控制灯闪烁得比平时快","通过起步前进行功能测试","转向灯控制灯持续亮红色"],"c":"出发前，应操作转向灯拨杆并检查其是否闪烁，以确认转向灯功能正常。如果行驶时转向灯闪烁得比平时快，可能是某个转向灯有故障。应立即排除故障。"},"2.7.02-045":{"q":"您看到液压前轮制动器操纵杆的自由行程明显增大。您必须怎么做？","o":["立即检查前轮制动器的部件","在下次检查前只使用后轮制动器","调整制动杆的行程"],"c":"如果液压前制动器制动杆的自由行程变大，制动器很可能有故障。应立即检查并修理前制动器的部件。"},"2.7.02-046":{"q":"您摩托车的循迹特性变差。原因可能是什么？","o":["链条张紧器调整不均匀","摇臂轴承已磨损","发动机怠速设置过高"],"c":"后摇臂是后轮的活动悬挂装置。如果后摇臂的轴承磨损，行驶轨迹特性会变差。应更换轴承。如果摩托车的链条张紧器调整不均匀，后轮可能不再与前轮精确对齐，行驶轨迹特性可能变差。"},"2.7.02-047":{"q":"在什么道路情况下，磨损因而打滑的离合器会对道路安全产生不利影响？","o":["在主干道上超车时","在高速公路上汇入车流时","执行紧急制动操作时"],"c":"离合器磨损并打滑的表现是：它不再接合，您无法再正常换挡。当您需要快速加速时，例如在乡间道路上超车或驶入高速公路时，这尤其成问题。应由维修厂修理离合器。"},"2.7.02-048":{"q":"您在长途旅行中停车加油。此时应对您的摩托车进行哪些检查？","o":["我的轮胎","我的车灯","我的行李固定情况"],"c":"在开始较长距离的骑行之前，应检查灯光和轮胎。出发前以及每次停车时，还应检查行李是否固定牢固。"},"2.7.02-049":{"q":"您的液冷车辆上的显示器显示发动机温度过高。您现在应该怎么做？","o":["我尽快在合适的地点停车","我以高转速缓慢继续行驶以改善发动机冷却","我继续以低挡行驶直到下一个计划休息点"],"c":"应尽快在合适的地点停车并关闭发动机，以防止因过热而损坏发动机。"},"2.7.02-050":{"q":"您的液冷车辆上的显示器显示冷却液温度过高。原因可能是什么？","o":["散热器被污物污染","散热器风扇停止工作","散热器系统有穿孔"],"c":"冷却液温度过高的原因可能是沉积物和污垢，因为它们会降低散热效果。冷却液可能通过泄漏处或损坏的密封件流失。冷却液越少，升温越快。应检查车辆是否有可见的泄漏处，必要时予以修理。如果散热器风扇有故障，温度会迅速升高。应检查散热器风扇是否堵塞，必要时由专业人员更换。"},"2.7.02-051":{"q":"什么会对您摩托车的行驶稳定性产生不利影响？","o":["转向头轴承松动","减震器磨损","排气系统穿孔"],"c":"转向头轴承磨损会导致转向出现间隙。尤其是在转弯时，摩托车的行驶稳定性可能变差。如果减震器磨损，就无法再补偿路面的颠簸。轮胎在路面上的抓地力可能降低，摩托车的行驶稳定性也会变差。"},"2.7.02-052":{"q":"您的摩托车是液冷的。您必须确保做什么？","o":["定期检查冷却液液位","定期清洁散热器的外表面","每次加油时补充冷却液"],"c":"应定期检查冷却液液位，必要时补充，以防止发动机过热。堵塞和污垢会损害散热器的功能。保持外表面清洁即可避免这种情况。"},"2.7.02-103":{"q":"方向盘比平时更难转动。原因可能是什么？","o":["转向器损坏","助力转向不工作","轮胎气压过高"],"c":"如果转向发卡，转向机构故障可能是原因。此外，助力转向失效也会导致方向盘比平时更难转动。胎压过低也会产生类似效果，但胎压过高不会。"},"2.7.02-107":{"q":"您汽车的制动器强烈向一侧偏。制动时可能产生什么影响？","o":["您的汽车可能向一侧偏驶","制动距离更长","防抱死制动系统（ABS）失效"],"c":"如果汽车制动器产生强烈的单侧制动效果，会对车辆的行驶性能产生明显的不利影响。车辆可能侧向窜入相邻车道或开始打滑。制动距离变长。防抱死系统仍然有效。"},"2.7.02-109":{"q":"当您踩下制动踏板时，它触及地板。只有在多次踩下后踏板行程才变短。您必须怎么做？","o":["立即停车","修理制动器","补充制动液就足够了"],"c":"如果制动踏板能被踩到车辆地板，且反复踩踏后踏板行程变短，说明制动系统中有空气。这意味着必须立即保养并修理制动器。不能继续行驶。此外，补充制动液也无法解决问题。"},"2.7.02-112":{"q":"制动灯不工作。您怎么做？","o":["立即修理","更换制动液"],"c":"必须立即排除制动灯的故障，以免危及道路上任何人并避免事故。灯泡损坏或保险丝烧断可能是制动灯失效的原因。"},"2.7.02-113":{"q":"行驶中您如何判断一个转向灯不工作？","o":["转向灯信号灯会闪烁得比平时快","行驶中您无法发现损坏的转向灯"],"c":"转向灯有故障时会很明显，因为仪表显示屏中的转向指示灯闪烁得比平时快得多。作为驾驶员，您可以在行驶中迅速识别该故障。"},"2.7.02-114":{"q":"您在黑暗中开启近光灯行驶。对向来车向您闪大灯。这可能意味着什么？","o":["您车辆的前照灯设置不正确，正在造成眩目","灯光照射范围调节未适应您的车辆载荷","其他驾驶员在告诉您打开远光灯"],"c":"如果迎面驶来的驾驶员交替切换远光和近光，这是一个典型信号，表明您的前灯使对向交通感到炫目。原因可能是前照灯调整不当，或大灯照射范围调节与载荷状态不符。不要将对方交替切换远近光误解为邀请您开启汽车的远光灯。"},"2.7.02-115":{"q":"您左侧外后视镜的镜片破碎。您怎么做？","o":["更换镜片","不更换镜片，因为您仍能部分看到后方"],"c":"每辆车都必须配备左侧外后视镜。如果镜片破裂，即使所有其他后视镜工作正常，也必须立即更换后视镜。只有这样才能继续行驶。"},"2.7.02-117":{"q":"风挡玻璃清洗器不工作。原因可能是什么？","o":["储液罐中没有水","保险丝损坏","喷嘴堵塞"],"c":"如果风窗玻璃清洗器不工作，原因可能是喷嘴堵塞或保险丝损坏。不过，也可能是储液罐中已没有水，因此风窗玻璃清洗器不工作。"},"2.7.02-118":{"q":"从风挡玻璃清洗器喷嘴喷出的水太少。原因可能是什么？","o":["喷嘴部分堵塞","清洗泵损坏","储液罐中水太多"],"c":"如果车辆的风窗玻璃清洗喷嘴出水太少，它们可能部分堵塞。风窗玻璃清洗器失效的原因也可能是水泵故障。出水太多不视为故障原因。"},"2.7.02-119":{"q":"风挡玻璃雨刮器刮不干净？原因可能是什么？","o":["风挡玻璃雨刮片磨损","风挡玻璃上有油膜","风挡玻璃加热损坏"],"c":"如果雨刮器刮不干净，原因可能是风窗玻璃上有油膜。即使是磨损的风窗玻璃雨刮片也会影响雨刮器的功能。而车窗加热器故障对其没有影响。"},"2.7.02-120":{"q":"您汽车上的风挡玻璃雨刮器不工作。原因可能是什么？","o":["保险丝熔断","风挡玻璃雨刮电机损坏","风挡玻璃清洗器中的水太多"],"c":"如果汽车的风窗玻璃雨刮器不工作，原因可能是风窗玻璃清洗系统中的电机故障。保险丝烧断也可能是原因。相比之下，水太多不会导致任何故障。"},"2.7.02-121":{"q":"安全带锁扣无法闭合。您怎么做？","o":["修理锁扣","什么都不做，因为该座位配备安全气囊","以低速行驶"],"c":"如果安全带锁扣不能正常闭合，必须首先进行修理或更换。安全带不能正常工作时，即使低速行驶也不允许，因为完好的安全带有强制性要求。"},"2.7.02-122":{"q":"安全带不能自动卷回。原因可能是什么？","o":["安全带扭曲","自动卷收器损坏","座椅调节损坏"],"c":"有时在解开安全带时，织带会扭转并卡在导向装置中。如果发生这种情况，织带就无法再卷回。此外，装置可能存在缺陷，此时必须修理或更换。"},"2.7.02-123":{"q":"您汽车的方向盘在行驶中抖动。原因可能是什么？","o":["车轮不平衡","减震器损坏","车轮悬架弹簧损坏"],"c":"如果行驶时方向盘抖动，原因可能是减震器损坏。减震器用于抑制轮胎的垂直运动。悬挂系统损坏也可能是原因。不平衡的车轮也会造成同样的抖动现象。"},"2.7.02-124":{"q":"前轴轮胎一侧比另一侧磨损更多的原因可能是什么？","o":["前束调整不正常","转向轴弯曲"],"c":"基本上，前轮胎磨损程度不同有两个原因：要么车轮定位不正确，要么车轴导向件弯曲。应立即校正车轮定位或修理车轴导向件。"},"2.7.02-125":{"q":"什么会导致轮胎过度磨损？","o":["车轮悬架弹簧损坏","轮胎气压不正确","安装前扰流板"],"c":"轮胎气压不当和悬挂系统损坏是轮胎过度磨损最常见的原因。轮胎气压指的是气压过低。这会加剧磨损。加装前扰流板不会导致轮胎损坏。"},"2.7.02-126":{"q":"行驶中您的车辆向右跑偏。原因可能是什么？","o":["转向轴弯曲","车轮定位不正常","转向减震器松动"],"c":"如果车辆在行驶中向右跑偏，可能是车轮定位的问题。但车轴导向件弯曲也可能是原因。相比之下，转向减震器通常不会影响车辆的行驶方向稳定性。"},"2.7.02-127":{"q":"如果您在静止时操作方向盘，对车辆有什么影响？","o":["轮胎胎面可能损坏","前轴机构承受很大应力","转向变得更轻松"],"c":"车辆静止时试图转向所需的力远大于车辆滚动时。这种增大的力会传递到包括横拉杆在内的整个转向系统，使其承受比行驶中转向更大的负荷。"},"2.7.02-128":{"q":"何时应安排检查您汽车的制动系统？","o":["行驶中制动控制灯亮起时","我制动时汽车不能保持直线时","我对汽车执行了紧急制动操作时"],"c":"制动控制灯会警告制动系统存在故障；如果在行驶中亮起，应立即送检车辆。如果制动器单侧制动，车辆就无法保持在车道内。应检查制动系统。"},"2.7.02-129":{"q":"行驶中您注意到制动时汽车强烈向左偏。正确的做法是什么？","o":["立即在修理厂检查我的汽车","只以低速继续行驶","从那时起只使用手刹"],"c":"如果车辆出现异常表现，应始终立即前往维修厂。这样可以预防可能发生的事故。由于制动器显然存在问题，应避免需要大力制动或全力制动的情况。用手制动器制动可能导致汽车偏离车道。行驶中绝不能这样做。"},"2.7.02-130":{"q":"您的车辆比平时更难转向。正确的做法是什么？","o":["我立即安排修理厂检查我的车辆","目前我在继续行驶时留意这种转向特性","我降低前轴的轮胎气压"],"c":"如果车辆出现异常表现，应始终立即前往维修厂。继续行驶将带来过大的风险。您会将自己和其他道路使用者置于危险之中。"},"2.7.02-131":{"q":"您注意到车辆前轴的轮胎磨损不均匀。应检查什么？","o":["底盘设置","轮胎气压","减震器"],"c":"轮胎磨损不均匀有多种原因。应检查轮胎气压。减震器损坏或悬挂系统设置不正确也会导致不均匀磨损。两者都应在专业维修厂检查。"},"2.7.02-132":{"q":"行驶中您的车辆向右跑偏。正确的做法是什么？","o":["我检查轮胎气压，必要时将车辆送到修理厂","我在继续行驶时只是留意这种转向特性","我尝试通过猛烈制动来改善操控性"],"c":"如果车辆在行驶中向右跑偏，这可能表明轮胎气压不正确。应检查气压，必要时前往维修厂。大力制动不会改善操控性，只会导致更危险的行驶，并可能危及您和其他道路使用者。如果车辆出现异常表现，应始终立即前往维修厂。继续行驶将带来过大的风险。"},"2.7.02-133":{"q":"何时必须安排修理厂检查您的汽车？","o":["底盘","转向系统","漆面"],"c":"如果发现悬挂系统或转向系统有任何缺陷，应立即前往维修厂。这些缺陷对您和他人都可能非常危险，并对行驶性能尤其是汽车的安全性产生不利影响。"},"2.7.02-134":{"q":"转向灯闪烁得比平时快得多。该现象的原因可能是什么？","o":["一个灯泡损坏","保险丝故障","危险警示灯已打开"],"c":"作为灯泡损坏的提示，指示灯会以两倍速度闪烁。在车内仪表板上也能看到这种更快的闪烁。这意味着您在行驶中也能看出某个转向灯已失效。"},"2.7.02-135":{"q":"何时应安排修理厂检查您的汽车？","o":["制动时持续有噪音时","发动机启动后安全气囊指示灯不熄灭时","直线行驶时您必须持续反向转向时"],"c":"如果启动发动机后不久安全气囊指示灯仍不熄灭，应将汽车送维修厂检查。这可能表明安全气囊或安全带系统等存在问题。制动时持续发出噪音可能表明制动系统损坏。通常情况下，汽车不握方向盘也会直行。如果您必须不断反向修正才能保持在车道内，应送维修厂检查。"},"2.7.02-136":{"q":"加速时您注意到方向盘颤抖。此时应怎么做？","o":["检查前轮是否损坏","检查前轮的固定","检查方向盘的固定"],"c":"如果在加速时方向盘出现抖动，应仔细检查前轮。应先检查前轮是否有损坏，然后检查前轮是否仍安装牢固。"},"2.7.02-137":{"q":"副驾驶座安全带损坏。您必须怎么做？","o":["我必须安排更换该安全带","我不得再使用该座位","我必须调整安全带高度调节器"],"c":"损坏的安全带必须由专业人员更换。只要安全带存在缺陷，就不得再使用该座位，因为该座位上的乘员处境非常危险。"},"2.7.02-138":{"q":"您在黑暗中行驶于城镇内道路。对向来车向您闪大灯作为警告。在此情况下这可能意味着什么？","o":["我的车辆对对向来车造成眩目","我忘记打开近光灯","我应该打开远光灯"],"c":"如果对面有车辆闪灯，这可能是因为您开启了远光灯而使对方炫目。不过，这也可能是对您的提醒，例如您忘记开启近光灯。"},"2.7.02-139":{"q":"您汽车电子稳定程序（ESC）的指示灯持续亮着。这可能指示什么？","o":["已被关闭","已损坏","已打开"],"c":"汽车上 ESP 警告灯持续亮起表明车辆的行驶动态控制系统存在问题——在许多汽车上，关闭驾驶辅助系统也会导致 ESP 指示灯持续亮起。如果 ESP 警告灯持续亮起而您并未将其停用或关闭，应尽快前往维修厂检查行驶动态控制系统的功能。"},"2.7.02-140":{"q":"您汽车副驾驶座的安全带故障。正确的做法是什么？","o":["我修理安全带","我不让任何人在副驾驶座乘车","我调整安全带高度调节器"],"c":"安全带存在缺陷的座位不得再使用。为此，损坏的安全带必须由专业人员更换或修理，以确保相关乘员的安全。"},"2.7.02-202":{"q":"什么会导致气压制动系统的充气时间比正常长？","o":["储气罐或接头漏气","空气压缩机性能不足","储气罐中水太多"],"c":"如果气压制动系统的充气时间比正常情况长，应检查储气罐或连接处是否泄漏，或提高空气压缩机的功率，因为其功率过低。"},"2.7.02-203":{"q":"行驶中制动系统的警告装置启动。这意味着什么？","o":["储备压力不再足够","制动系统可能有故障","一个制动气缸泄漏"],"c":"如果行驶中压力警告装置响应，说明制动系统可能有故障，应进行修理。储气罐压力已不足，应检查是否存在压力损失。"},"2.7.02-204":{"q":"在带多回路安全阀的制动系统中，什么会导致空气压缩机持续输出压缩空气？","o":["空气压缩机的活塞磨损已达到不再达到切断压力的程度","连接到多回路安全阀的一个压缩空气回路泄漏","多回路安全阀未关闭"],"c":"如果空气压缩机持续输送压缩空气，原因是与多回路保护阀相连的某个气动回路发生泄漏，并且空气压缩机活塞磨损已严重到无法实现停机。"},"2.7.02-205":{"q":"哪些故障可能是空气压缩机性能不足的原因？","o":["风扇皮带打滑或空气滤清器脏污","空气压缩机损坏","储气罐中有水"],"c":"导致空气压缩机功率不足的原因可能是空气压缩机故障、皮带打滑或空气滤清器脏污。储气罐中的水分不是决定性因素。"},"2.7.02-208":{"q":"配备气助液压制动系统的车辆压缩空气系统失效。车辆仍可通过行车制动系统制动吗？","o":["即使用力踩下，也只能产生很小的制动效果，空载时也是如此","整个行车制动系统失效","可以，因为柴油发动机的真空泵替代了气压助力"],"c":"如果配备气压助力液压制动系统的车辆压缩空气助力失效，即使车辆空载，即便用很大的脚踏力也只能产生微弱的制动效果。"},"2.7.02-209":{"q":"驾驶带气压制动系统的机动车时，前轴一个车轮制动气缸的管路断裂。您如何发现这一损坏？","o":["在不制动行驶时您无法发现这一损坏","制动时，通过警告装置或前制动回路的双压力表","通过减弱的制动作用"],"c":"您可以通过制动效果减弱察觉到损坏。在制动时，可通过前制动回路的双压力表或通过警告装置判断。您可以在行驶中制动时察觉该损坏。三个答案都正确。"},"2.7.02-210":{"q":"驾驶带气压制动系统的机动车时，前轴制动回路储气罐上的一条管路断裂。您如何发现这一损坏？","o":["通过前轴制动回路的双压力表或通过警告装置","通过减弱的制动作用","弹簧储能制动器被激活"],"c":"您可以通过制动效果减弱以及前桥制动回路的双压力表或警告装置察觉该损坏。制动效果减弱这一说法不正确。"},"2.7.02-211":{"q":"严重漏气的空气弹簧气囊对行驶安全性可能产生什么影响？","o":["车辆向一侧倾斜","由于自动载荷感应制动力调节器（ALB）的控制压力不正确，制动作用受损","前制动回路的制动管路失去气压"],"c":"严重泄漏的空气弹簧气囊会因 ALB（自动载荷相关制动力控制）控制压力错误而影响制动效能。您的车辆会向一侧倾斜。请立即修理。"},"2.7.02-212":{"q":"当钢板弹簧总成的多片弹簧断裂时，对行驶安全性有什么影响？","o":["车辆的方向稳定性受损","车辆制动时跑偏","自动载荷感应制动力调节器（ALB）设置不正确"],"c":"三个答案都正确。钢板弹簧断裂时，车辆的行驶方向稳定性会受到损害。车辆在制动时甩尾，且 ALB（自动载荷相关制动力控制）的调整会失准。"},"2.7.02-213":{"q":"您机动车一个车轮制动气缸的制动管路严重泄漏。您如何发现这个问题？","o":["通过逸出的压缩空气产生的噪音","通过压力警告指示器","通过行驶中感受到的减弱的制动作用"],"c":"如果制动管路在某个车轮制动缸处泄漏，您可以同时通过压缩空气逸出的声音和压力警告指示灯察觉。行驶中制动效能低下也是明显的迹象，应进行修理。"},"2.7.02-214":{"q":"重要车轴悬架部件损坏对道路安全可能产生什么影响？","o":["操控性可能受到不利影响","车辆可能遭受额外损坏","轮胎可能出现斑点状磨损"],"c":"如果车轴悬挂系统的重要部件损坏，会影响行驶性能；如果不立即修理，可能产生进一步损坏。轮胎可能出现不均匀磨损（啃胎）。"},"2.7.02-215":{"q":"空气压缩机输出低的可能原因是什么？","o":["进气滤清器过度脏污","空气压缩机损坏","储气罐中有水"],"c":"空气压缩机输送率过低的原因之一可能是进气滤清器脏污，另一个原因可能是空气压缩机故障。"},"2.7.02-216":{"q":"如果行驶中发动机温度警告灯亮起，您应该怎么做？","o":["您应尽快在合适的地点停车，并遵循制造商的指导","以较高转速缓慢继续行驶以改善冷却","以低挡继续行驶到下一个计划休息点"],"c":"请查阅操作手册了解现在该怎么做。"},"2.7.02-302":{"q":"在双管路制动系统中，通往拖车的紧急管路破裂会产生什么效果？","o":["导致拖车制动","将拖车气源与破裂的紧急管路隔断","激活卡车的自动制动"],"c":"双管路制动系统的挂车制动阀在供气管路中断（压力下降）时切断对挂车的供气，并触发挂车制动。它在牵引时不会触发自动制动。"},"2.7.02-303":{"q":"松开驻车制动器后，您如何判断拖车制动阀是否工作（储气罐已充气）？","o":["当紧急管路（红色软管接头）断开时，拖车的制动气缸活塞进入制动位置","当紧急管路和行车管路连接好时，踩下制动踏板时拖车的制动气缸活塞进入制动位置","当行车管路（黄色软管接头）断开时，在不踩下制动踏板的情况下拖车的制动气缸活塞进入制动位置"],"c":"要判断挂车制动阀是否正常工作，可这样检查：断开供气管路（红色接头）时，挂车制动缸的活塞进入制动位置；当供气管路和制动管路连接好后，操作制动踏板时，挂车制动缸的活塞进入制动位置。"},"2.7.02-304":{"q":"如果双回路压缩空气制动系统的一个行车制动回路在车辆行驶中泄漏，会发生什么？","o":["空气将从泄漏的回路逸出，制动作用可能显著减弱","四通保护阀保护完好回路，使其压力不低于安全压力","四通保护阀向泄漏回路补充空气以补偿压力损失"],"c":"如果双回路气压制动的一个行车制动回路（回路 2）泄漏，泄漏回路的供气被切断，制动效果会明显减弱。四回路保护阀可保护完好的回路，防止压力降至安全压力以下。"},"2.7.02-305":{"q":"通往牵引车的电气连接中断。因此拖车上的哪个装置无法工作？","o":["防抱死制动系统（ABS）","电子制动系统（EBS）","牵引力控制系统（TCS）"],"c":"当电子连接中断时，ABV（自动防抱死系统）和 EBS 不再工作。"},"2.7.02-306":{"q":"如果与牵引车的电气连接缺失或中断，拖车上的哪个装置将不工作？","o":["电子制动系统（EBS）","照明系统","牵引力控制系统（TCS）"],"c":"当与挂车的电子连接断开时，电子制动系统（EBS）和照明都不工作。行驶前应检查连接。"},"2.7.03-001":{"q":"您的摩托车配有一个连接到后轮的链条传动。您应定期检查链条的什么？","o":["松弛量","其润滑情况","磨损程度"],"c":"您可以自行检查链条的几个方面，以尽量减少磨损并延长链条的使用寿命。检查松弛度，确保链条既不过松也不过紧，并检查链条是否有拉长或弯曲的链节。还应定期检查链条的润滑情况，必要时重新润滑，以尽量减少磨损并延长链条的使用寿命。"},"2.7.03-002":{"q":"您的摩托车配有一个连接到后轮的链条传动。张紧链条时您必须注意什么？","o":["松弛量必须符合制造商的规格","必须确保后轮的方向稳定性","张紧时链条必须无油脂"],"c":"对摩托车进行的所有作业都应遵循制造商的说明，或由专业人员完成。张紧链条时，要确保后轮保持正确对齐。这可确保更好的方向稳定性并避免不必要的轮胎磨损。链条的松弛度很重要，必须符合制造商的规格。"},"2.7.03-003":{"q":"您的摩托车配备连接到后轮的皮带传动。您应定期检查什么？","o":["皮带的张紧度","皮带是否损坏","皮带的润滑"],"c":"对于皮带传动的摩托车，必须定期检查皮带是否损坏，并且必须检查皮带的张紧度。裂纹、磨损和损坏的齿会对摩托车造成严重损坏。同样，摩托车皮带张紧度过低会导致性能下降和材料磨损加剧。"},"2.7.03-101":{"q":"发动机中冷却液过少可能导致什么结果？","o":["导致发动机损坏","导致发动机过热","导致油耗增加"],"c":"冷却液过少会导致发动机损坏，因此您应始终进行检查。另一个后果是发动机过热。请确保冷却液充足。"},"2.7.03-102":{"q":"您在堵车中，以步行速度行驶。何时对您手动挡车辆的离合器磨损最小？","o":["尽可能在不踩离合器的情况下以低挡行驶","反复起步和停车","以打滑的离合器缓慢行驶"],"c":"应完全踩下离合器，以避免离合器不必要的磨损。选择一个挡位，使您在不使用离合器和油门的情况下也能滑行。"},"2.7.03-201":{"q":"为什么柴油发动机也被称为自燃式发动机？","o":["因为喷射的燃油与压缩空气接触点燃时开始工作冲程","因为工作冲程由压力敏感的燃油启动","因为工作冲程由点火火花启动"],"c":"因为柴油发动机不需要火花塞，其工作循环是通过在压缩空气中点燃喷入的燃油而开始的。"},"2.7.03-203":{"q":"柴油发动机中凸轮轴的功能是什么？","o":["控制发动机中的气门","限制发动机转速","控制发动机温度"],"c":"柴油发动机中凸轮轴的作用是控制发动机中的气门。根据凸轮的形状或高度，气门保持开启或关闭。"},"2.7.03-205":{"q":"发动机冷却系统中冷却液节温器的功能是什么？","o":["调节发动机的工作温度","显示发动机的工作温度","显示散热器中的冷却液液位"],"c":"正如其名称所示，冷却液节温器用于调节发动机的工作温度。另外两个答案不正确。"},"2.7.03-206":{"q":"什么会导致发动机冷却系统在冬季损坏？","o":["防冻不足","冷却液未每年至少更换两次时","不会造成任何损坏，因为封闭系统无需任何维护"],"c":"防冻液不足可能导致发动机损坏。请确保始终加注防冻液。"},"2.7.03-207":{"q":"哪种机油覆盖的温度范围最大？","o":["SAE 10 W 40","SAE 30","SAE 10 W 30"],"c":"SAE 10 W 40 中较小的数字（10）（轻质油）表示机油适用的最低温度范围，而 W 旁边的数字（40）表示高温下较高的黏度。"},"2.7.03-208":{"q":"您的柴油发动机在冬季无法启动。原因可能是什么？","o":["油箱中仍有夏季柴油","火花塞不产生点火火花","点火线受潮"],"c":"如果油箱中仍装有夏季柴油，发动机在冬季可能无法启动，因为夏季柴油在低温下会絮凝并堵塞燃油滤清器。"},"2.7.03-209":{"q":"您在堵车中以步行速度驾驶您的车辆。在哪些情况下离合器磨损最小？","o":["尽可能在不使用离合器的情况下以低挡行驶","不断地起步和停车","以打滑的离合器缓慢行驶"],"c":"如果尽可能在不使用离合器的情况下以低挡行驶，则在堵车、以步行速度行驶时，磨损最低。"},"2.7.03-211":{"q":"差速锁的功能是什么？","o":["改善缓慢越野行驶和在湿滑路面上的牵引力","将驱动力矩均匀分配到驱动轮上","改善转弯时的操控性"],"c":"差速锁将驱动扭矩均匀分配到驱动轮，从而防止外侧与内侧车轮之间速度差的补偿。在缓慢的越野行驶和湿滑路面上，它能显著改善牵引力。"},"2.7.03-212":{"q":"何时激活差速锁有帮助？","o":["陷入困境且个别驱动轮空转时","在湿滑路面上缓慢直线行驶时","在干燥路面上进行机动操作时"],"c":"在湿滑路面上缓慢直线行驶时，以及在陷车、单个驱动轮打滑旋转时，应使用差速锁。这会有帮助。"},"2.7.03-213":{"q":"何时可以激活差速锁从而可能不损坏机动车？","o":["静止时","以步行速度行驶时","转弯时转向不足时"],"c":"如果您的车辆处于这种状态，并且以步行速度行驶，则预计不会产生破坏性影响。"},"2.7.03-214":{"q":"什么会增加手动挡机动车的离合器磨损？","o":["以高挡起步","以高发动机转速进行机动操作","以低挡起步"],"c":"对于手动变速器，在起步时使用高挡位（例如 2 挡）并以较高的发动机转速进行操控的机动车中，离合器磨损会增加。"},"2.7.03-215":{"q":"您如何保护手动挡机动车的离合器部件？","o":["等待起步时，我挂入空挡并将脚从离合器踏板上移开","我使用低发动机转速进行机动操作","我在起步时挂入高挡"],"c":"为保护手动变速器机动车的离合器部件，在等待时应将车辆置于空挡，松开离合器踏板，并以较低的发动机转速操控。"},"2.7.03-216":{"q":"差速锁（机械锁止差速器）的功能是什么？","o":["改善低速越野行驶和在湿滑路面上的牵引力","将扭矩均匀分配到驱动轮上","改善转弯时的操控性"],"c":"差速锁在缓慢越野行驶和湿滑路面上能改善牵引力，因为驱动扭矩被均匀分配到驱动轮。"},"2.7.04-001":{"q":"加注发动机机油时我应确保什么？","o":["我使用的机油符合车辆制造商的规格","我不超过最高液位","我在发动机运转时加注发动机机油"],"c":"只能使用符合制造商规格的机油。只允许加注正确的机油。注意不要超过允许的最大加注液位，否则可能损坏发动机。绝不要在发动机运转时加注机油。"},"2.7.04-002":{"q":"发动机机油在内燃机中的功能是什么？","o":["磨损保护","冷却","清洁"],"c":"机油对内燃机有多种作用。它用于防磨损、冷却和清洁。请确保机油油位充足。"},"2.7.04-003":{"q":"您如何检查发动机机油油位？","o":["通过观察窗","通过机油尺","通过瞬时油耗显示"],"c":"有一个观察窗可供读取油位。否则，可以通过机油尺读取。"},"2.7.04-101":{"q":"您如何检查发动机机油油位？","o":["通过驾驶员信息系统","通过机油尺","通过瞬时油耗显示"],"c":"视车辆而定，机油油位可以用不同方式检查。现代车辆可以在信息娱乐系统中显示油位。"},"2.7.04-201":{"q":"为什么在冬季开始前必须检查冷却液是否有足够的防冻能力？","o":["使冷却液不结冰","使冷却系统不被霜冻损坏","使车辆的行车许可不失效"],"c":"为避免冷却液冻结（凝固），您应充分检查防冻剂。这样即使遇到霜冻也能避免冷却系统损坏。车辆的行车许可不会因此失效。"},"2.7.04-203":{"q":"冷却液系统中防冻剂的功能是什么？","o":["防冻剂防止腐蚀","防冻剂保护冷却系统免于结冰","防冻剂在夏季引起腐蚀"],"c":"防冻剂可防止腐蚀（生锈）并保护冷却系统免于冻结。在夏季月份则不存在这种情况。"},"2.7.04-205":{"q":"为什么柴油和汽油发动机需要发动机机油？","o":["使活塞和轴承不卡死","减少内部摩擦","润滑水泵"],"c":"柴油发动机和汽油发动机都需要机油，因为它用于减少内部摩擦，从而使活塞和轴承不至于卡死。润滑水泵与此无关。"},"2.7.04-206":{"q":"柴油发动机用润滑油的要求是什么？","o":["它们必须减少磨损","它们必须耐热","它们在寒冷时期必须具有流动性"],"c":"柴油发动机的润滑油用于耐热性、低温下的流动性以及减少磨损。"},"2.7.05-001":{"q":"轮胎上标明的生产日期“1217”是什么意思？","o":["2017年第12个日历周生产","2017年第12个月（12月）生产","2017年1月2日生产"],"c":"轮胎上标注的生产日期由生产周数和生产年份组成。因此 “1217” 表示：2017 年第 12 周。"},"2.7.05-002":{"q":"您应该何时检查轮胎气压？","o":["定期在轮胎冷却时检查","更换轮胎后直接检查","每次行程后直接检查"],"c":"应定期在轮胎冷态时检查轮胎气压，并在每次更换轮胎后立即检查。不需要每次行驶后都检查。"},"2.7.05-003":{"q":"您轻便摩托车轮胎允许的最小花纹深度是多少？","o":[],"c":"您的轻便摩托车的花纹深度必须达到 1 mm。"},"2.7.05-004":{"q":"摩托车轮胎气压过高或过低可能有什么后果？","o":["摩托车的操控性会变差","轮胎磨损加剧","反应距离延长"],"c":"由于摩擦增大，轮胎磨损加剧。轮胎变形，从而使行驶性能变差。"},"2.7.05-005":{"q":"您在公共道路上行驶时轮胎气压明显过低。其后果是什么？","o":["车辆的操控性会显著变差","车辆转弯时的稳定性会危险地降低","轮胎磨损程度会大大减少"],"c":"轮胎气压过低会导致行驶时轮胎与沥青路面接触的面积更大。此外，轮胎不再保持圆形，无法再平稳滚动。如果轮胎气压明显过低，弯道中的行驶稳定性会危险地下降，转向性能也会变差。"},"2.7.05-006":{"q":"定期检查车辆轮胎时您必须检查什么？","o":["气压","花纹深度","是否有外部损伤"],"c":"应定期检查轮胎。重要的是要检查轮胎的外观状态，确保轮胎没有外部损坏，并且不低于法律要求的最低花纹深度 1.6 mm。尤其是在较长行程之前或载荷较高时，应事先检查轮胎气压。"},"2.7.05-007":{"q":"轮胎对路面的附着力取决于什么？","o":["取决于轮胎温度","取决于道路状况","取决于天气条件"],"c":"轮胎在路面上的附着（抓地）能力在很大程度上取决于道路状况和天气条件。轮胎在干燥路面上附着能力最好。然而，潮湿、积雪、结冰、颠簸或污垢会严重影响轮胎的附着能力。轮胎温度对附着能力也起重要作用，因为它影响橡胶混合物的特性。夏季轮胎在低温下可能变硬，降低其附着能力，而冬季轮胎在高温下可能磨损得更快。"},"2.7.05-008":{"q":"什么会导致轮胎气压逐渐下降？","o":["在高速公路上行驶时缺少气门嘴帽","轮胎中有异物","频繁快速加速"],"c":"轮胎因钉子或类似异物造成的损坏可能导致轮胎充气压力流失。在高速公路上高速行驶时，轮胎升温，轮胎气压升高。如果缺少气门帽，空气可能缓慢逸出。"},"2.7.05-009":{"q":"您驾驶一辆发动机排量大于125 cm³的摩托车。您摩托车所有轮胎法定规定的最小花纹深度是多少？","o":[],"c":"法律规定的轮胎最低花纹深度为 1.6 mm。"},"2.7.05-101":{"q":"用汽车千斤顶更换轮胎时应注意什么？","o":["汽车千斤顶只允许在车辆制造商指定的支撑点使用","地面必须始终稳固且防滑","汽车千斤顶必须始终放置在车身长度的中点"],"c":"为安装千斤顶，车辆驾驶员必须使用制造商提供的支撑点。为此，具有防滑性能的安全地面是绝对必要的。"},"2.7.05-102":{"q":"您必须拆除损坏的轮胎。您应按什么顺序进行？","o":["固定车辆防止溜车，放置千斤顶，松开车轮螺母，顶起车辆，拆下车轮螺母","固定车辆防止溜车，放置千斤顶，顶起车辆，松开车轮螺母，拆下车轮螺母","放置千斤顶，固定车辆防止溜车，松开车轮螺母，顶起车辆，拆下车轮螺母"],"c":"固定车辆，防止其意外溜车。安装千斤顶。在车辆仍接触地面时松开车轮螺母。借助千斤顶举升。拧下车轮螺母。"},"2.7.05-103":{"q":"轮胎上的红色符号表示什么？","o":["适用于冬季天气条件","在雪地条件下也有助于行驶性能","只允许与防滑链组合使用"],"c":"该符号表示此轮胎适合冬季天气条件，即使在雪地中也能保持良好的行驶特性。不需要安装防滑链。"},"2.7.05-104":{"q":"使用冬季轮胎行驶时您必须特别注意什么？","o":["不超过这些轮胎的允许最高车速","不超过80 km/h","只在我使用防滑链时一样快地行驶"],"c":"使用冬季轮胎时，必须确保不超过轮胎允许的最高速度。您可以通过速度等级（速度指数）查看。"},"2.7.05-105":{"q":"您的汽车配备冬季轮胎。您仪表盘上的速度标签“最高190 km/h”是什么意思？","o":["不得超过","仅适用于冬季道路条件","不适用于干燥道路条件"],"c":"使用冬季轮胎时，不得超过 190 km/h 的最高速度。"},"2.7.05-106":{"q":"给汽车安装冬季轮胎时您应记住什么？","o":["轮胎气压应按照制造商的指导进行检查","您应遵守这些轮胎的允许最高行驶速度","气压应比夏季轮胎的制造商指导值低0.5巴"],"c":"安装冬季轮胎后，应按照制造商的规格检查轮胎气压，并考虑轮胎允许的最高速度。不得超过该速度。"},"2.7.05-107":{"q":"该指示灯亮起。原因可能是什么？","o":["一个轮胎的气压过低","最近进行了车轮更换","一个车轮螺母松动"],"c":"轮胎气压指示灯通常表示轮胎气压过低，因此请检查轮胎气压。不过，如果您最近更换了轮胎，轮胎气压传感器也可能出现很多问题。先检查轮胎外观上是否能发现异常。如果轮胎外观正常而指示灯仍亮着，请咨询维修厂。"},"2.7.05-108":{"q":"您汽车所有轮胎主花纹范围内法定规定的最小花纹深度是多少？","o":[],"c":"法律规定的轮胎最低花纹深度为 1.6 mm。主要的花纹特征是中央胎面区域的沟槽。"},"2.7.05-203":{"q":"不正确的轮胎气压有什么影响？","o":["损害行驶稳定性","加剧轮胎磨损","延长反应时间"],"c":"轮胎气压不正确会增加轮胎劣化的可能性。请注意保持正确的气压。行驶稳定性会受损，危及您和其他道路使用者的安全。"},"2.7.05-205":{"q":"轮胎气压过低时有什么影响？","o":["轮胎过热","行驶稳定性降低","油耗增加"],"c":"因为支撑轮胎的空气在轮胎气压过低时，可以说更容易过热。此外，油耗会显著增加，行驶稳定性会降低。"},"2.7.05-210":{"q":"您应该何时检查轮胎气压？","o":["至少每周一次，在轮胎冷却时","每次更换轮胎后立即","每次行程后立即"],"c":"应在每次更换后立即测量轮胎气压，并至少每周在冷态轮胎上测量一次。每次行驶后测量是不正确的。"},"2.7.05-211":{"q":"“TWI”（胎面磨损指示器）这一标识是什么意思？","o":["指示轮胎磨损","指示翻新轮胎胎面","指示无内胎轮胎"],"c":"轮胎磨损指示器（磨损指示器或 Tread Wear Indicator，TWI）用于显示轮胎是否磨损，因此答案是：标示轮胎磨损的正确位置。"},"2.7.05-212":{"q":"您如何识别轮胎已被翻新？","o":["通过轮胎侧面的“RETREAD”标识","无法识别","通过轮胎胎面"],"c":"翻新轮胎可通过胎侧上的 RETREAD 标识来识别。它也被称为 Recap 或 remold。"},"2.7.05-213":{"q":"检查备胎固定时您必须注意什么？","o":["检查备胎是否牢固固定","检查备胎的双重固定","检查举升装置的功能"],"c":"检查备胎固定装置时，必须注意以下三点：检查备胎是否牢固安装、检查举升装置的功能，以及检查备胎的双重固定。"},"2.7.05-214":{"q":"何时应检查轮胎上的标识与允许的轮胎类型相符？","o":["每次接管车辆时","每次更换轮胎后","每次将车辆送到修理厂时"],"c":"每次更换车轮以及每次接收车辆时，都必须检查轮胎上的标识是否合规。送厂维修时则不需要。"},"2.7.05-215":{"q":"开始行程前，关于轮胎我必须检查什么？","o":["是否有可见损伤","是否失压","确保它们具有至少1 mm的花纹"],"c":"出发前必须检查轮胎的可见损坏和压力损失。"},"2.7.05-216":{"q":"您在哪里可以找到有关您车辆轮胎气压的信息？","o":["在操作手册中","在车辆登记证第一部分（机动车登记证）中","在运输单据中"],"c":"关于您车辆的轮胎气压信息，请查阅制造商的操作手册。气压可能因载荷不同而有所变化。"},"2.7.05-217":{"q":"更换轮胎后未重新拧紧车轮螺母可能有什么后果？","o":["车轮可能损坏","车轮可能从车辆上脱落","轮胎可能从轮毂上脱落"],"c":"如果更换车轮后未拧紧车轮紧固件，或因疏忽而未拧紧，车轮可能在行驶中因振动而从车辆上脱落。这可能导致严重事故。车轮不会从轮辋上脱落。"},"2.7.05-218":{"q":"您必须更换双轴机动车右前轮。您使用车轮挡块防止车辆意外溜车。这样做时您必须注意什么？","o":["机动车位于尽可能稳固的地面上","后轴上的一个车轮","前轴上未损坏的车轮"],"c":"应在一个后轴车轮处垫上挡块，并且车辆应尽可能停在坚实的地面上。"},"2.7.05-219":{"q":"您必须在平地上更换三轴机动车的右前轮。这样做时您应注意什么？","o":["一个后轴车轮上放置两个车轮挡块","前轴上未损坏的车轮上放置两个车轮挡块","后轴上两个车轮各放置一个车轮挡块"],"c":"应在后轴的一个车轮处垫上两个挡块，并且车辆应尽可能停在坚实的地面上。"},"2.7.05-220":{"q":"在以下轮胎标识中“L”指的是什么：315/80 R 22.5 156/150 L？","o":["轮胎的允许最高速度","轮胎的承载能力","轮胎的气压容差"],"c":"此处的 L 表示轮胎的最高速度。另外两个答案错误。"},"2.7.05-221":{"q":"在以下轮胎标识中“156/150”指的是什么：315/80 R 22.5 156/150 L？","o":["单胎和双胎的负荷指数","高宽比","按气压计的滚动周长"],"c":"标记 156/150 表示单胎和双胎的负载指数。它与气压或与高宽比有关。"},"2.7.05-222":{"q":"胎压监测系统（TPMS）向您指示双胎中的一个轮胎失压。您应该怎么做？","o":["我在最近合适的地点停车并进行目视检查","我在下次车辆检测时修理损坏","我可以忽略该警告，因为另一个双胎承受着重量"],"c":"当双胎中的气压下降时，应在最近合适的地点停车，进行目视检查，必要时更换轮胎。"},"2.7.05-223":{"q":"轮胎上的红色符号表示什么？","o":["适用于冬季天气条件","在雪地条件下也有助于行驶性能","只允许与防滑链组合使用"],"c":"此轮胎上的符号表示它适合冬季天气条件，即使在雪地中也能保持良好的行驶特性。不需要安装防滑链。"},"2.7.05-224":{"q":"对存放在您车辆中的备胎您应检查什么？","o":["确保备胎安全固定到位","备胎的双重保障","备胎的气压"],"c":"所有答案都正确。您必须检查备胎是否牢固固定、是否具有双重固定，以及备胎的气压是否保持正常。"},"2.7.05-225":{"q":"根据轮胎标识，您应何时检查轮胎的行驶安全性？","o":["每次接手第三方车辆时","每次更换轮胎时","每次将车辆送到车间时"],"c":"每次更换车轮以及每次接收他人车辆时，您都要根据轮胎标识检查其合规性。"},"2.7.05-226":{"q":"开始行程前，关于轮胎您必须检查什么？","o":["是否有任何损坏","是否有任何失压","主胎面具有至少1 mm的最小花纹深度"],"c":"通过目视检查，您可以检查轮胎，查看是否有损坏并进行修复，以及是否有压力损失（轮胎瘪了），然后更换/修补轮胎。"},"2.7.05-227":{"q":"您驾驶一辆长途客车或公交车。在冬季条件下您必须注意什么？","o":["其驱动轴","其前转向轴","其所有车轮"],"c":""},"2.7.05-228":{"q":"您驾驶一辆最大允许质量超过3.5吨用于运输货物的机动车。在冬季条件下您必须注意什么？","o":["其驱动轴","其前转向轴","其所有车轮"],"c":""},"2.7.05-229":{"q":"如果您的汽车有一个携带在车身外部的备胎，您应定期检查什么？","o":["双重保障","轮胎气压","滚动阻力"],"c":"如果您在车身外部携带备胎，定期检查双重锁止装置和轮胎气压非常重要。双重锁止装置确保备胎在行驶中牢固固定、不会松脱，从而避免道路上出现危险情况。应检查轮胎气压，因为气压不足的备胎在发生故障时无法使用，也就无法发挥其作为备用轮胎的作用。由于备胎经常闲置不用，它可能随时间推移而失去气压；定期检查可确保必要时能立即使用。"},"2.7.06-001":{"q":"拥有带防抱死系统（ALS）的摩托车有什么好处？","o":["在紧急制动操作中摔倒的风险降低","驾驶更快不会增加发生事故的风险","制动需要更少的力气"],"c":"紧急制动时，车轮容易抱死，您可能摔倒。自适应巡航控制系统通过调节制动压力来对抗车轮抱死，从而降低摔倒风险。"},"2.7.06-002":{"q":"您驾驶一辆配备防抱死制动系统（ABS）的摩托车。如果在弯道中必须制动，您应考虑到什么？","o":["尽管处于倾斜状态，我也应有控制地制动","激活的ABS能更长时间保持操控性","倾斜状态下制动力会自动增大"],"c":"自动防抱死制动器有助于稳定制动过程，防止车轮抱死。由于自动防抱死制动器能防止车轮抱死，您在制动的同时也能转向。不过，在倾斜（压弯）时应以可控的方式制动，因为大力制动可能导致摩托车侧滑。"},"2.7.06-003":{"q":"您的摩托车配备针对弯道优化的防抱死制动系统（ABS）。该辅助系统的目的是什么？","o":["在弯道中危急制动操作时增强操控性","减小弯道中制动时摩托车的回正力矩","增大弯道中制动时摩托车的回正力矩"],"c":"自动防抱死制动器在制动时防止车轮抱死。这使您在转弯时能够同时制动和转向。与标准防抱死制动器相比，倾角优化的防抱死制动器通过减小回正力矩来提高转向能力，尤其是在弯道中的关键制动操作时。"},"2.7.06-101":{"q":"自动防抱死装置（ABS）有什么效果？","o":["车辆在潮湿路面上也能以最佳方式制动","制动时在很大程度上保持转向控制","防止水滑现象"],"c":"防抱死系统确保即使在汽车驾驶员进行紧急制动时车轮也不会抱死。汽车至少仍具有有限的转向能力，即使在湿滑路面上制动距离也不会改变。在滑水（水滑）情况下，路面与轮胎之间的水膜主要由高速行驶形成。防抱死系统不能防止车辆漂浮。"},"2.7.06-103":{"q":"自动防抱死装置（ABS）有什么优点？","o":["制动时车轮不抱死","即使猛烈制动也保持转向控制","可以显著更快地过弯"],"c":"防抱死系统的优点是，在潮湿或脏污路面上制动时能防止车轮抱死。为此，制动压力以很短的时间间隔进行调节。ABS 不影响正常的行驶特性。"},"2.7.06-104":{"q":"自动防抱死装置（ABS）有什么优点？","o":["可以同时猛烈制动和避开障碍物","起步时防止车轮空转","弯道制动时降低侧翻危险"],"c":"防抱死制动系统在潮湿或脏污道路上大力制动时特别有用。它通过以很短的时间间隔控制制动压力来防止车轮可能的抱死。这可防止车辆冲出车道。防抱死系统对弯道行驶没有影响。起步时车轮打滑可由牵引力控制系统（TCS）防止，而不是防抱死系统。"},"2.7.06-105":{"q":"带惯性制动器的拖车的制动作用何时开始？","o":["当拖车向卡车（牵引车）靠拢时","当卡车的制动踏板被踩下时","在卡车的制动作用开始之前，以使卡车和拖车保持伸展"],"c":"当挂车挂在牵引车上时，配备惯性制动器的挂车会产生制动效果。顾名思义，只有当挂车顶到牵引车时，挂车制动器才会解除。"},"2.7.06-107":{"q":"在湿滑路面上，汽车列车何时特别容易折叠或侧滑？","o":["当驾驶员猛打方向时","在弯道行驶时对行车制动器施加最大压力时","缓慢加速时"],"c":"在汽车列车中，当转向动作生猛以及在弯道中用行车制动器以最大减速度制动时，危险特别大。"},"2.7.06-108":{"q":"在湿滑路面上，配备压缩空气制动器的半挂牵引列车何时特别容易折叠或侧滑？","o":["在弯道行驶时完全开启缓速器时","在弯道行驶时卡车比拖车制动更猛烈时","当载荷主要作用在驱动轴上时"],"c":"如果货车在转弯时比挂车制动得更强，则在湿滑路面上发生折弯（折叠）或甩尾的风险特别大。当在转弯时完全操作缓速器（retarder）时，可能产生不同的制动力效果。"},"2.7.06-109":{"q":"您牵引一辆带惯性制动器的拖车。您必须注意什么？","o":["可以倒车","可以前进","挂接拖车"],"c":"即将推出……"},"2.7.06-110":{"q":"如果定速巡航系统（限速器）关闭过晚，可能发生什么？","o":["跟车过近","过弯速度过高","超过允许最高车速"],"c":"速度调节器持续保持设定的速度。因此，当驶入有限速的路段时，您可能超过最高速度。您可能以过快的速度驶入弯道。调节器无法修正距离。如果关闭装置太晚，您可能与前车距离过近。"},"2.7.06-111":{"q":"定速巡航系统（限速器）能协助您做什么？","o":["保持恒定速度","保持节能的驾驶风格","保持与前车的最小距离"],"c":"定速巡航使您的汽车保持恒定速度，但不控制与前车的距离。当您松开油门踏板、只专注于道路时，同时也节省了燃油。"},"2.7.06-112":{"q":"使用自适应巡航控制系统时我应注意什么？","o":["即使长时间使用该系统，我也必须始终保持专注","该系统可能受大雨或降雪影响","踩油门或制动踏板总能覆盖该系统"],"c":"自适应速度控制系统评估您前方车辆的位置和速度。由此，它调整您车辆的速度和距离，包括相应的自适应发动机控制和制动干预（相位同步控制）。尽管如此，作为汽车驾驶员，您不应分心。您可以随时干预该系统。因为系统功能可能受天气条件影响。"},"2.7.06-113":{"q":"机动车上的自适应巡航控制系统执行什么功能？","o":["自动将车辆加速到先前设定的速度","当前车行驶较慢时自动制动","自动保持规定的安全距离"],"c":"自适应巡航控制系统（也称为自适应巡航控制）通过传感器确定您前方车辆的位置和速度，并调整本车的速度和距离。这是通过发动机控制和制动干预进行自适应调节的（相位同步控制）。该系统无法识别并设定规定的安全距离。"},"2.7.06-114":{"q":"机动车驾驶员使用定速巡航系统有什么好处？","o":["在平坦车道上保持恒定的预设速度","使驾驶员更容易操作车辆","使速度适应交通密度"],"c":"定速巡航在平坦道路上保持稳定的车速，并减轻您驾驶车辆的负担。交通密度无法根据速度进行调节。"},"2.7.06-115":{"q":"在什么情况下使用自适应巡航控制系统（ACC）有帮助？","o":["高速公路","快速路","蜿蜒道路"],"c":"自适应巡航控制监测与前车的距离并相应调整您的速度。在高速公路和快速路上行驶时，建议使用自适应巡航控制系统。"},"2.7.06-116":{"q":"您如何手动覆盖已激活的定速巡航系统？","o":["通过制动","通过加速","通过转向"],"c":"主动巡航控制系统可通过制动或加速来覆盖（接管）。这意味着车辆比巡航控制中设定的速度更慢或更快。"},"2.7.06-117":{"q":"机动车中自适应巡航控制系统（ACC）的目的是什么？","o":["自动将车辆加速直到达到先前设定的速度","如果识别到前方有以更低速度行驶的车辆，自动降低车辆速度","始终保持与前车的规定安全距离"],"c":"主动巡航控制系统像普通定速巡航一样，将车辆调整到您设定的速度。当检测到前方车辆时，它还会制动。如果无法检测到前方车辆，例如在夜间、大雨、雾天等情况下，它不会减速。"},"2.7.06-118-M":{"q":"行驶中您使用自适应巡航控制（ACC）。速度设为100 km/h。在进入道路弯道前您必须做好什么准备？","o":["ACC可能会使我的车辆加速","我必须使我的速度适应情况","ACC会提示我降低速度"],"c":"自适应巡航控制系统自动保持您设定的速度，同时与前车保持正确距离。您已将 AGR 的速度设定为 100 km/h。由于前方车辆现在已不在视野内，AGR 将加速。请设定较低的速度以安全通过弯道。"},"2.7.06-119":{"q":"您车辆的紧急制动辅助系统有什么功能？","o":["就追尾碰撞的紧迫危险发出警告","在不可避免的碰撞中降低受伤风险","如果我意外越过车道边界，会降低我的车速"],"c":"紧急制动辅助是机动车的一种安全系统，可在危急情况下警告您即将发生碰撞。如果检测到碰撞，它还会通过增大制动压力来辅助紧急制动，从而降低碰撞速度。"},"2.7.06-202":{"q":"当缓速器开启且应用行车制动器时会发生什么？","o":["驱动轴的车轮制动更有力","缓速器自动关闭","前轮不制动"],"c":"在接通持续制动器的情况下操作行车制动器时，会发生以下情况：驱动轴的车轮可以被更强地制动。"},"2.7.06-203":{"q":"驾驶机动车时速度控制（定速巡航）有什么优点？","o":["由于更均匀的驾驶风格而节省燃油","加速轻松","精确遵守速度限制"],"c":"定速巡航的优点包括减轻加速时的负担、通过更平稳的驾驶方式节省燃油，以及精确遵守速度限制。"},"2.7.06-206":{"q":"何时应使用速度控制（定速巡航）？","o":["当交通条件允许您以恒定速度行驶时","仅在上坡或下坡时","仅在高速时"],"c":"如果交通状况允许恒定速度，应使用定速巡航。"},"2.7.06-208":{"q":"带自动载荷感应制动力调节器（ALB）的制动系统是什么意思？","o":["制动力根据车轴上的载荷自动调节","在湿滑路面上完全制动时，自动防止车轮抱死","起步时防止车轮空转"],"c":"ALB（自动载荷相关制动力控制）指的是根据车轴上的载荷自动控制制动力。这在不同载荷下非常有用。"},"2.7.06-209":{"q":"配备自动载荷感应制动力调节器（ALB）的空载车辆，每次强烈制动时后轮都抱死。原因可能是什么？","o":["ALB有故障或调整错误","后轴上的多片弹簧断裂","制动器强烈热衰退"],"c":"原因可能是 ALB 故障或设置不正确，或后桥多片钢板弹簧断裂。"},"2.7.06-210":{"q":"自动载荷感应制动力调节器（ALB）和自动防抱死装置（ABS）的作用有何不同？","o":["防抱死装置（ABS）无论重量和路面状况如何都防止车轮抱死","自动载荷感应制动力调节器（ALB）自动使制动力适应车轴载荷","自动载荷感应制动力调节器（ALB）自动使制动力适应路面状况"],"c":"ABS 在制动时自动防止车轮抱死。对于 ALB，制动力会根据车轴载荷自动调整。根据道路状况自动调整制动力与此无关。"},"2.7.06-211":{"q":"哪些制动器不产生显著磨损？","o":["排气制动器","缓速器（电涡流制动器、液力制动器）","气压制动系统"],"c":"缓速器（电涡流制动器）工作时无明显磨损。"},"2.7.06-213":{"q":"弹簧储能制动气缸中是什么产生制动作用？","o":["弹簧力","进入的压缩空气","驾驶员施加的力"],"c":"弹簧储能制动器通过弹簧力起作用。此时，弹簧被排气（泄压）。"},"2.7.06-214":{"q":"弹簧储能制动系统如何工作？","o":["当启动手刹阀时，弹簧储能制动气缸被排空。弹簧力因此激活制动器","当启动手刹阀时，压缩空气流入弹簧储能制动气缸。压缩空气因此激活制动器","当在静止时踩下制动踏板时，压缩空气流入弹簧储能制动气缸。压缩空气因此激活制动器"],"c":"操作手制动阀时，弹簧储能制动缸被排气，从而通过弹簧的弹力实现制动。出于安全考虑，弹簧储能制动器在无气压时也会制动。"},"2.7.06-215":{"q":"一辆因发动机故障抛锚的卡车已应用弹簧储能制动器。气源已耗尽。这有什么影响？","o":["弹簧储能制动器不响应手刹阀的启动","为使车辆能够被拖走，必须通过紧急释放装置松开弹簧储能制动器","在车辆被拖走前必须拆除弹簧载荷"],"c":"如果您希望车辆被拖曳，必须用辅助装置解除弹簧储能制动器。另一个原因是排空的气压导致弹簧储能制动器在按下手制动阀时不响应。为进行拖曳，不得更换弹簧储能制动器。"},"2.7.06-216":{"q":"弹簧储能制动气缸存在哪些类型的紧急释放装置？","o":["气动式","机械式","自动式"],"c":"弹簧储能制动缸既有机械式辅助装置，也有气动式辅助装置。"},"2.7.06-217":{"q":"您驾驶一辆配备站台制动器的客车。您何时允许使用站台制动器？","o":["在站台停车时","代替驻车制动器，在停放客车时","在陡峭下坡时制动"],"c":"即将推出……"},"2.7.06-220":{"q":"对于带空气干燥器的气压制动系统，您必须记住什么？","o":["定期检查储气罐的排水阀，以查看空气干燥器是否正常工作","定期保养空气干燥器","定期检查空气干燥器中的防冻液液位"],"c":"在配备空气干燥器的气压制动系统中，应确保其定期保养。应定期检查储气罐的排水阀，确保空气干燥器正常工作。如果不行，请更换它。它们不是永久耐用的。"},"2.7.06-222":{"q":"当您完全踩下制动踏板时，机动车储气罐中多大的压力下降（切断压力约7-8巴超压）不会引起担忧？","o":["0.7巴","1.2巴","1.5巴"],"c":"如果您将制动踏板完全踩下（约为 7 至 8 bar 压力），0.7 bar 的压力下降是无害的。"},"2.7.06-223":{"q":"气压制动系统中多回路安全阀的功能是什么？","o":["将泄漏的回路与其他回路隔断","确保向完好回路供给压缩空气","保护压缩空气系统的所有回路免受过压"],"c":"气压制动系统中的四回路保护阀可确保对完好回路的供气，此外还负责将发生泄漏的回路与其他回路隔断。"},"2.7.06-224":{"q":"空气压缩机需要哪些定期检查和保养措施？","o":["检查输送管路连接","清洁进气滤清器并检查风扇皮带","检查转速控制器"],"c":"空气压缩机定期检查与保养的内容之一：清洁进气滤清器、检查 V 形皮带，以及检查压力管路的连接。检查速度调节器没有帮助。"},"2.7.06-226":{"q":"当您完全踩下制动踏板时（切断压力约7-8巴），车辆储气罐中超过0.7巴的压力下降为什么是有问题的？","o":["因为当您再次制动时系统中的空气供给下降过快","因为完全制动时车轮会抱死","因为制动系统中会产生真空"],"c":"如果在将制动踏板完全踩下（约 7 - 8 bar 压力）时，储气罐中的压力下降高于 0.7 bar，则存在问题，因为继续制动时系统中的供气会迅速下降。"},"2.7.06-227":{"q":"带自动载荷感应制动力调节器（ALB）的车辆后轮的制动力失效。原因可能是什么？","o":["ALB设置不正确","驾驶员施加了过大力量","制动系统中的供气压力过高"],"c":"这是由于 ALB 设置错误造成的。请检查，以便制动功能恢复正常并能安全地继续在后轮上起作用。"},"2.7.06-228":{"q":"您的机动车配备电子制动系统（EBS）。EBS失效时会发生什么？","o":["系统错误将通过指示灯指示","车辆在气动冗余压力的辅助下制动","车辆现在只能使用驻车制动器制动"],"c":"如果 EBS（电子制动系统）失效，车辆通过气动冗余压力进行制动。当系统中出现故障时，会通过警告灯向您提示。"},"2.7.06-229":{"q":"您的机动车配备电子制动系统（EBS）。EBS执行什么功能？","o":["在各车轮制动器之间最佳协调制动力","自动监控制动系统","在车道上出现障碍物时自动制动"],"c":"EBS 使各车轮制动器之间的制动力实现最佳调节。制动系统的自动监测由 EBS 完成。"},"2.7.06-230":{"q":"如果在持续制动器开启时启动行车制动器，会发生什么？","o":["对驱动轴的车轮施加更强的制动力","持续制动器将自动关闭","驱动轴的车轮将抱死"],"c":"在持续制动器接通时操作行车制动器会产生以下效果：驱动桥的车轮被更强地制动，从而使您更快地停下来。"},"2.7.06-231":{"q":"您完全踩下机动车的制动踏板。如果储气罐已满，制动系统中最大的安全压力下降是多少？","o":["0.7巴","1.2巴","1.5巴"],"c":"当储气罐完全充满时，最大 0.7 bar 的压力下降是无害的。"},"2.7.06-232":{"q":"如果您完全踩下制动踏板一次（切断压力约10至13巴），机动车压缩空气系统中超过0.7巴的压力下降为什么是有问题的？","o":["因为对于额外的制动操作空气供给下降过快","因为机动车的制动作用会变差","因为制动系统中会产生真空"],"c":"如果您车辆压缩空气系统中的压力下降超过 0.7 bar，供继续制动用的空气会下降过快，车辆的制动效果会变差。"},"2.7.06-233":{"q":"自动载荷感应制动系统（ALB）的目的是什么？","o":["根据实际车辆质量进行调节","根据路面状况进行调节","根据车速进行调节"],"c":"使用 ALB 时，制动力功能会根据实际车辆质量进行调整。"},"2.7.06-234":{"q":"机动车的哪个制动系统几乎没有磨损？","o":["发动机制动器","缓速器","压缩空气制动系统"],"c":"发动机制动器和缓速器（电动持续制动器）工作时不产生明显磨损。"},"2.7.06-235":{"q":"您的机动车配备电子制动系统（EBS）。EBS有什么效果？","o":["制动距离缩短","制动稳定性提高","制动片的磨损特性得到优化"],"c":"所有答案都正确。使用 EBS 可缩短制动距离、改善制动稳定性并优化制动片的磨损特性。"},"2.7.06-236":{"q":"您驾驶一辆配备手动变速箱的满载机动车。在陡峭下坡时，尽管已开启持续制动器，车速仍不断上升。您应该怎么做？","o":["我使用行车制动器制动并挂入低挡","我使用行车制动器制动并挂入高挡","我关闭持续制动器，仅使用行车制动器"],"c":"如果在陡坡上速度增加，应使用行车制动器制动并换入较低的挡位，以便借助发动机制动器的额外帮助进行制动。"},"2.7.06-237":{"q":"您的机动车配备紧急制动辅助系统。以下哪项正确？","o":["必须始终激活","仅在交通繁忙时激活","在高速公路上绝不激活"],"c":"如果配备了它，就应将其激活。它在紧急制动时能提供很大帮助。"},"2.7.06-238":{"q":"您的机动车配备紧急制动辅助系统。以下哪项正确？","o":["必须始终激活","仅在危险情况下激活","仅在出现疲劳时激活"],"c":"如果配备了它，就应将其激活。它在紧急制动时能提供很大帮助。"},"2.7.06-239":{"q":"为什么您应使用机动车的持续制动器（缓速器）？","o":["无磨损运行","可以减轻行车制动装置","可以将车辆制动到停止"],"c":"持续制动器是一种能够长时间、无磨损地制动而不降低其制动力的装置。"},"2.7.06-240":{"q":"在高速公路上使用自适应巡航控制（ACC）有什么好处？","o":["降低追尾碰撞的可能性","驾驶员在保持所选距离方面得到帮助","意味着不能低于安全距离"],"c":"驾驶员辅助系统确保与前车保持正确的安全距离。"},"2.7.06-241":{"q":"您驾驶一辆手动挡机动车。为使定速巡航系统有助于节能驾驶风格，合乎逻辑的做法是什么？","o":["选择合适的挡位","在走走停停的交通状况下使用定速巡航","在长上坡时提前加速"],"c":"速度必须尽可能低。"},"2.7.06-242":{"q":"什么会导致车辆的紧急制动辅助系统自动停用？","o":["由于雪导致雷达传感器的功能受阻","因为碰撞损坏导致传感器的位置偏移","因为自适应巡航控制（ACC）已打开"],"c":""},"2.7.06-243":{"q":"您的车辆配备紧急制动辅助系统。以下哪项正确？","o":["必须在车速超过30 km/h时打开","可以在高速公路上高速时关闭","只应在危险情况下打开"],"c":"作为货车驾驶员，在车速超过 30 km/h 时，您有义务保持紧急制动辅助系统处于激活状态，因为该系统有助于防止追尾事故，从而提高道路安全。"},"2.7.06-303":{"q":"当卡车的弹簧储能制动系统被激活时，卡车拖车组合会发生什么？","o":["卡车以机械方式制动","拖车通常通过其行车制动系统以气动方式制动","拖车以机械方式制动"],"c":"如果您在货车中拉紧牵引车的弹簧储能制动器，通常挂车会通过其行车制动系统（黄色）以压缩空气制动，而牵引车则通过机械方式制动。"},"2.7.06-306":{"q":"在哪些情况下您必须激活释放阀？","o":["当储气罐已满、制动管路未连接且拖车必须移动时","起步前，以便拖车的储气罐能够充气","起步前，以便拖车的驻车制动器能够松开"],"c":"当需要在储气罐充满、制动管路已脱开的情况下移动挂车时，您必须按下释放阀。"},"2.7.06-307":{"q":"当卡车（双回路制动系统）与拖车之间的制动管路（软管）在制动时断裂，会产生什么效果？","o":["四回路安全阀保持卡车制动系统的安全压力","紧急管路自动排气，拖车被制动","拖车的制动系统失效"],"c":"当牵引车（双回路制动系统）与挂车之间的制动管路（软管）在制动时发生断裂，会发生以下情况：供气管路自动排气，挂车被制动，且四回路保护阀维持牵引车行车制动系统的保障压力。"},"2.7.06-308":{"q":"一辆配备带预充气缸的气液双回路制动系统和气动拖车控制阀的卡车，其右前轮制动管路断裂。这对卡车和拖车有什么影响？","o":["拖车的行车制动系统保持完全有效","只能通过行车制动系统制动卡车的后轮","拖车立即自动被制动"],"c":"效果如下：对于挂车，行车制动器完全有效；对于牵引车，只能用行车制动器制动后轮。"},"2.7.06-309":{"q":"如果拖车气压制动系统的制动气缸活塞在制动时伸出到极限位置，会产生什么危险？","o":["完全制动失效","过度制动","制动力调节器不再反应"],"c":"当制动缸的活塞被顶出（脱落）时，存在的危险是：气压制动的挂车会一直制动到停止，制动作用可能完全失效。"},"2.7.06-310":{"q":"如果卡车和拖车在长下坡时持续使用行车制动器制动，可能发生什么？","o":["车轮制动器发热到制动作用危险地降低的程度","制动系统的空气供给没有得到补充","缓速器的作用减弱"],"c":"经过长时间下坡后，车轮制动器会发热到制动效果危险地减弱的程度。"},"2.7.06-311":{"q":"您驾驶满载的卡车和拖车下坡，且低估了坡度。尽管已开启缓速器，车速仍明显上升。您必须怎么做？","o":["使用行车制动器以便能够减挡","松开缓速器，仅用行车制动器调速"],"c":"如果您驾驶满载货车低估了一段长坡，应使用行车制动器减速，以便能够换入低挡。"},"2.7.06-313":{"q":"您将带压缩空气制动系统的拖车短时间停放。您如何解除拖车的行车制动器？","o":["通过激活释放阀","通过给制动管路排气","通过松开驻车制动器"],"c":"通过按下释放阀，您可以解除挂车的行车制动器。现在您可以离开您那带有气压制动器的挂车。"},"2.7.06-314":{"q":"半挂车的牵引车只配备防抱死制动系统（ABS）。在潮湿车道上执行紧急制动操作时，这可能产生什么效果？","o":["延长制动距离","导致拖车折叠","在制动时保持卡车和拖车的稳定性"],"c":"在紧急制动且挂车车轮抱死时，挂车可能甩尾并延长制动距离，因为 ABV（自动防抱死系统）仅由您的牵引车进行调节。"},"2.7.06-315":{"q":"电子制动系统（EBS）与拖车之间的连接中断。这在制动时对拖车可能有什么影响？","o":["防抱死制动系统（ABS）可能被停用","拖车在气动冗余压力的辅助下制动","制动灯不再工作"],"c":"当 EBS（电子制动系统）的连接中断时，ABV（自动防抱死系统）可能被关闭，挂车则通过气动冗余压力进行制动。"},"2.7.06-316":{"q":"牵引车和拖车都配备电子制动系统（EBS）。当储气罐已满时，您如何检查与拖车的电子连接？","o":["断开黄色和红色接头，打开点火开关，松开驻车制动器，应用行车制动器","连接黄色和红色接头，断开EBS连接，应用行车制动器，松开驻车制动器","断开黄色和红色接头，建立EBS连接，松开行车制动器，应用驻车制动器"],"c":"要测试储气罐已充满时与挂车的电子连接，您应：断开黄色和红色接头，接通点火（电源），松开驻车制动器，并操作行车制动器。"},"2.7.06-317":{"q":"如果在制动时牵引车与拖车之间带黄色接头的制动管路软管断裂，会产生什么效果？","o":["四通保护阀将确保牵引车行车制动系统的安全压力","供给管路将自动排气，拖车被制动","拖车的行车制动系统将失效"],"c":"如果牵引车与挂车之间的制动软管（带黄色接头）脱落，四回路保护阀会保障牵引车行车制动系统的备用压力，供气分配管路自动排气，挂车被制动。"},"2.7.06-318":{"q":"制动时您拖车气动制动气缸的一个活塞伸出到最大。这可能带来什么危险？","o":["拖车的制动作用降低","拖车过度制动","制动力调节器的功能受到不利影响"],"c":"对您而言危险在于：挂车的制动效果会降低。不会出现过度制动，功能也不受影响。"},"2.7.06-319":{"q":"您驾驶一辆配备压缩空气制动系统的牵引车。通往右前轮的制动管路断裂。在牵引拖车时这有什么影响？","o":["拖车的行车制动器保持完全可用","牵引车的制动力受到限制","拖车将立即自动被制动"],"c":"如果右前轮上的制动管路断裂，您仍可以用功能完好的行车制动器制动您的挂车，但牵引车的制动力会降低，这会影响整体安全性。"},"2.7.06-320":{"q":"您驾驶一辆共用压缩空气制动系统的卡车和拖车。此处手刹阀控制设置的功能是什么？","o":["牵引车通过弹簧储能制动器制动","拖车的行车制动器被松开","拖车的行车制动器被激活"],"c":"手制动阀的控制位置（在您配备持续气压制动系统的货车上的）功能意味着：牵引车通过弹簧储能制动器制动，同时挂车的行车制动器被解除。"},"2.7.06-321":{"q":"当牵引车中的驻车制动器被应用（不在测试位置）时，对卡车拖车组合有什么效果？","o":["牵引车将以机械方式制动","此时，拖车通常仅通过行车制动系统以压缩空气制动","拖车将以机械方式制动"],"c":""},"2.7.06-402":{"q":"您想驾驶一辆带两辆配备压缩空气制动器拖车的农用拖拉机。对于每辆拖车上的手动制动力调节器，您必须确保做什么？","o":["将调节器设置调整到拖车上的载荷","将调节器设置调整到拖拉机的实际总重量","将调节器设置调整到拖拉机的额定总重量"],"c":"即将推出……"},"2.7.06-403":{"q":"为确保定速巡航有助于节能，需要什么？","o":["正确的挡位选择","为长上坡提前加速","充分利用最大车辆总重量额定值"],"c":"选择正确的挡位有助于在使用定速巡航时实现更省油的驾驶方式。"},"2.7.06-404":{"q":"自动载荷感应制动系统执行什么功能？","o":["根据车辆的实际总重量进行调节","根据路面状况进行调节","根据车速进行调节"],"c":"载荷传感阀的作用是使制动力根据车辆实际总质量进行调整。"},"2.7.06-405":{"q":"您想驾驶一辆带配备惯性制动拖车的车辆。开始行程前您必须检查什么？","o":["连接装置已锁止","照明系统正常工作","断开拉索已连接"],"c":"请注意，惯性制动器是一种机械装置，其锁止装置必须在起步行驶前检查。此外，还要检查整个照明系统的功能以及断开式制动拉索是否正确连接。"},"2.7.06-406":{"q":"您必须定期检查空气压缩机的什么？","o":["压力管路连接","三角皮带","调速器"],"c":"在空气压缩机上，应定期检查压力管路的连接和 V 形皮带。"},"2.7.07-201":{"q":"对鞍式牵引座必须定期进行哪些控制和服务工作？","o":["润滑鞍式牵引座","检查与车架的固定","鞍式牵引座始终免维护"],"c":"在进行检查和保养工作时，必须对鞍式牵引座（第五轮）加注润滑脂，并检查其固定在车架上的情况。鞍式牵引座应始终进行保养。"},"2.7.07-202":{"q":"全新时为38.0 mm直径的自动拖车联接器上，联接销的最大允许磨损是多少？","o":["直到直径36.5 mm","直到直径35.0 mm"],"c":"牵引销磨损后其直径不得低于 36.5 mm，而在新状态下其直径为 38 mm。"},"2.7.07-204":{"q":"拖车联接器牵引杆的纵向间隙可能有什么影响？","o":["可能对横梁造成损坏","拖车可能脱开","后轴轮胎可能过载"],"c":"牵引杆（拉杆）存在轴向间隙可能损坏横梁，挂车可能被拉断。轮胎超载则无关紧要。"},"2.7.07-206":{"q":"拖车联接器的牵引杆允许有纵向间隙吗？","o":["不，不允许有纵向间隙","是的，最多1.5 mm","纵向间隙取决于牵引杆的直径"],"c":"答案是否定的。牵引杆不得有轴向间隙。"},"2.7.07-208":{"q":"联接带球形联接器的拖车时您必须考虑什么？","o":["联接器的卡爪必须可靠闭合","任何支撑轮都必须在行驶前抬起并固定","联接时支撑轮不得接触地面"],"c":"连接挂车时，必须确保现有的支撑轮在出发前被升起并固定。连接爪必须牢固闭合。连接过程中会接触地面。"},"2.7.07-209":{"q":"将多轴拖车联接到自动拖车联接器后必须检查什么？","o":["联接销必须完全啮合","控制销的位置","拖车牵引叉的倾斜角度"],"c":"将多轴挂车连接到自动挂车牵引装置时，应检查牵引销是否完全啮合，并检查控制销的位置。不需要检查挂车牵引杆的倾斜角度。"},"2.7.07-302":{"q":"连接半挂车后您必须做什么？","o":["检查鞍式牵引座的固定和锁止系统","连接并检查所有软管和电缆","松开半挂车的倒车锁"],"c":"挂接半挂车后，应建立并检查鞍式牵引座的锁止和保险系统，并检查它是否自动闭合所有软管和电缆连接。"},"2.7.07-303":{"q":"联接销允许的最大垂直间隙是多少？","o":["4 mm","2 mm","6 mm"],"c":"牵引销的间隙最大为 4 mm。如果间隙过大，会产生顿挫。如果过小，闭合牵引装置时锁销无法再啮合。"},"2.7.07-304":{"q":"您接手一辆之前未使用过的半挂车。连接半挂车之前您必须记住什么？","o":["检查联接销是否磨损或损坏","驾驶室与半挂车之间必须有足够的空间","半挂车和牵引车的轮胎必须尺寸相同"],"c":"在接收新半挂车时（并非所有都相同），请注意在驾驶室与半挂车之间留出足够的空间，并注意牵引销的磨损或损坏。"},"2.7.07-305":{"q":"拆卸半挂车之前您必须做什么？","o":["锁住半挂车的车轮并伸出支撑腿","断开牵引车与半挂车之间的所有软管和电缆接头","松开联接锁并打开鞍式牵引座的挂接装置"],"c":"三个答案都正确。断开牵引车与半挂车之间的所有软管和电缆连接，解锁牵引装置的锁止并打开鞍式牵引座的锁，最后固定半挂车的车轮并伸出支撑装置。"},"2.7.07-306":{"q":"联接多轴拖车的正确程序是什么？","o":["将卡车倒车到停放的拖车处","将拖车推向卡车","同时将两辆车相互移动靠拢"],"c":"在牵引车与多轴挂车连接的过程中，牵引车会倒退靠近挂车。也请注意可能处于两者之间的人员。"},"2.7.07-308":{"q":"应通过什么方式使多轴拖车的牵引杆与接近的牵引车联接器保持在同一高度？","o":["通过高度调节装置","通过副驾驶","通过足够的支撑"],"c":"多轴挂车通过高度调节装置保持在靠近的牵引车的连接高度上。"},"2.7.07-309":{"q":"联接多轴拖车之前您必须检查什么？","o":["拖车是否已固定防止溜车（驻车制动器、车轮挡块）","牵引叉是否调整正确","拖车的气压制动储气罐是否已满"],"c":"连接多轴挂车时，您需要确认牵引杆调整正确，以及挂车是否已防止溜车（驻车制动器、车轮挡块）。"},"2.7.07-310":{"q":"您已联接一辆之前未使用过的多轴拖车。您如何确定牵引叉和转环已危险磨损？","o":["在拖车制动器接合的情况下短暂前进并多次停车","在断开推进装置的情况下行驶时多次猛烈制动","以低速呈波浪线行驶"],"c":"在挂车处于制动状态时，用牵引车进行几次短距离的前进移动，可用于查明牵引杆和回转装置是否存在危险的磨损状态。"},"2.7.07-312":{"q":"对于自动拖车联接器，您如何看出联接销已正确啮合？","o":["通过联接器控制销的位置或驾驶室内的控制灯","通过联接器释放杆的位置","通过短暂前进并停车"],"c":"要检查牵引销是否正确啮合，您可以向上查看，或查看驾驶室中牵引装置控制销的指示灯。"},"2.7.07-314":{"q":"牵引环允许的最大磨损是多少？","o":["1.5 mm","1.0 mm","2.0 mm"],"c":"牵引环的磨损最大不得超过 1.5 mm。"},"2.7.07-315":{"q":"牵引叉在轴承衬套中沿牵引方向允许的最大间隙是多少？","o":["无可察觉的间隙","最多1.5 mm","最多3 mm"],"c":"牵引杆在轴承衬套中（拉伸方向）不得有任何明显的间隙。这会对衬套造成冲击。"},"2.7.07-317":{"q":"如果牵引联接器的牵引杆有纵向间隙，可能有什么后果？","o":["在牵引联接器所连接的横梁中可能形成裂纹","牵引联接器可能撕裂断开","后轴减震器过载"],"c":"拉杆轴向间隙的后果如下：固定挂车牵引装置的横梁出现裂纹，以及挂车牵引装置被拉脱。"},"2.7.07-319":{"q":"拆卸拖车时您必须如何断开空气管路？","o":["先断开紧急管路（红色软管接头）","如果软管接头是组合的，则同时断开两条管路","先断开行车管路（黄色软管接头）"],"c":"在摘挂（脱开挂车）时，您分离压缩空气管路的方法是：首先按下供气管路（红色接头），而在组合式接头中则同时分离两条管路。"},"2.7.07-320":{"q":"联接拖车时您必须记住什么？","o":["先连接行车管路（黄色软管接头）","如果软管接头是组合的，则同时连接两条管路","先连接紧急管路（红色软管接头）"],"c":"连接带有组合式接头的挂车时，同时连接两条管路；在没有组合式接头的情况下，先连接制动管路（黄色接头）。"},"2.7.07-321":{"q":"联接拖车时您必须记住什么？","o":["您不得连接颜色不同的联接器部件","当拖车联接好后，松开驻车制动器并移除车轮挡块","先连接紧急管路"],"c":"连接挂车时，请在连接后松开驻车制动器，并移除不同颜色的挡块；不同颜色的连接部件不得相连。"},"2.7.07-322":{"q":"将拖车联接到自动拖车联接器后您必须记住什么？","o":["联接销必须完全啮合","控制销的位置","联接销啮合后，您必须无法将联接卡爪向侧面移动"],"c":"对于（自动）自主工作的挂车牵引装置，应注意控制销的位置，并且牵引销必须完全啮合。"},"2.7.07-323":{"q":"联接半挂车之前必须满足哪些要求？","o":["鞍式牵引座必须解锁并打开","鞍式牵引座和联接器必须大致处于同一高度","所有管路和电缆连接必须建立"],"c":"在连接半挂车时，鞍式牵引座（牵引车）必须解锁并打开，并且鞍式牵引座与牵引销（半挂车）必须大致处于同一水平高度。"},"2.7.07-324":{"q":"您拖车挂接装置的联接销全新时直径为38 mm。关于磨损您应注意什么？","o":["在整个联接表面范围内直径不得低于36.5 mm","下部销导向不得有任何过度自由间隙","联接销在联接表面上可低于单侧直径36.5 mm"],"c":"如果您发现牵引销有磨损（例如 2 mm），必须更换牵引销，因为在整个连接面的圆周上直径不得小于 36.5 mm。下方的固定导槽中也不得有过大的间隙。"},"2.7.07-325":{"q":"拖车的牵引装置出现相当大的纵向间隙。这可能有什么影响？","o":["可能对牵引车的横梁造成损坏","拖车可能剪切脱开","后轴轮胎可能过载"],"c":"如果您发现挂车牵引杆存在明显的轴向间隙，这会影响牵引车后面的横梁（造成损坏），并且挂车可能被拉脱。"},"2.7.07-326":{"q":"挂接装置的牵引杆允许有多少纵向间隙？","o":["不允许有纵向间隙","最多1.5 mm的纵向间隙","允许的纵向间隙取决于牵引杆的直径"],"c":"您挂车的牵引杆存在轴向间隙是不允许的，必须立即排除。"},"2.7.07-327":{"q":"全挂车的牵引杆应与接近的牵引车的联接高度保持水平。如何确保这一点？","o":["通过拖车的高度调节系统","通过指挥操作的人员","通过牵引车的高度调节系统"],"c":"要将牵引杆式挂车的牵引杆调整到连接高度，应使用挂车的高度调节装置。"},"2.7.07-328":{"q":"您如何检查全挂车牵引杆或转盘的磨损状态？","o":["在拖车使用驻车制动器固定的情况下，用牵引车短暂起步","通过断开推进装置，并在行驶时多次猛烈制动","在拖车使用行车制动器固定的情况下，用牵引车短暂起步"],"c":"在挂车用驻车制动器固定住的情况下，您可以通过短距离起步，用牵引车检查挂车的牵引杆或回转支承环是否存在磨损。"},"2.7.07-329":{"q":"挂接装置牵引环眼的直径允许的磨损是多少？","o":["1.5 mm","1.0 mm","2.0 mm"],"c":"牵引杆环的磨损在直径上最大不得超过 1.5 mm。"},"2.7.07-330":{"q":"牵引杆牵引环直径上测量的最大允许磨损是多少？","o":["1.5 mm","1.0 mm","2.0 mm"],"c":"直径不得超过 1.5 mm。"},"2.7.07-401":{"q":"您的拖拉机配备带手动锁止的K 80联接系统。联接拖车时您必须确保什么？","o":["联接拖车后锁止联接系统上的固定器","在相关拖车上调整拖车联接器的高度","每次使用前润滑联接系统"],"c":"连接后，必须锁紧连接系统上的压紧装置，并将挂车牵引装置的高度调整到相应挂车。系统（K 80）不需要在每次使用前润滑。"},"2.7.08-001":{"q":"为什么必须按照车辆制造商的说明定期更换制动液？","o":["确保制动系统即使在高负荷下也保持功能","确保制动液中的含水率不超过允许水平","防止损坏制动系统的部件"],"c":"您应按照制造商的规格定期更换制动液，因为这样可以使制动系统即使在高负荷下也能正常工作，使制动液中的含水量不至于高到不可接受，并避免制动系统的部件受损。"},"2.7.08-201":{"q":"如果您不定期更换空气滤清器，对发动机有什么影响？","o":["废气中有害物质的百分比可能增加","油耗可能增加","发动机功率可能下降"],"c":"不进行定期空气滤清器更换会增加废气中的污染物比例。发动机功率可能下降，油耗可能增加。"},"2.7.08-202":{"q":"为什么您应定期检查轮胎的花纹？","o":["因为一侧磨损的轮胎可能表明前束或外倾角调整不正确","因为不均匀磨损的轮胎可能表明减震器或悬架元件损坏","因为不均匀磨损的轮胎可能对行驶性能产生不利影响"],"c":"三个答案都正确。定期检查是必要的，因为磨损不均匀的轮胎会对您的驾驶产生不利影响；因为磨损不均匀的轮胎可能表明减震器或悬挂装置损坏；还因为单侧磨损的轮胎可能表明前束或外倾角设置错误。"},"2.7.08-203":{"q":"为什么您应在寒冷天气期开始前检查您的车辆？","o":["因为发动机的冷却水系统可能结冰","因为蓄电池可能失效","因为风挡玻璃清洗系统可能结冰"],"c":"因为风窗玻璃清洗系统可能冻结，因为蓄电池可能失效。此外，在寒冷天气中发动机的冷却水系统可能冻结。三个答案都正确。"},"2.7.08-204":{"q":"您可以对蓄电池进行哪些预防性维护？","o":["检查电缆连接和蓄电池支架是否牢固到位","清洁并给极柱涂脂","更换蓄电池电解液"],"c":"检查电缆连接和蓄电池支架是否紧固、清洁，并给极柱涂脂是正确的做法。由于酸不会老化，因此不得更换。"},"2.7.08-206":{"q":"为什么定期检查发动机冷却液很重要？","o":["冷却液不足会导致发动机损坏","冷却液不足会导致发动机过热","冷却液不足不重要，因为它总是由膨胀罐自动补充"],"c":"定期检查冷却液很重要，因为缺少冷却液会导致发动机故障，发动机可能过热。请不时检查。"},"2.7.08-207":{"q":"为什么应对您车辆进行计划中的保养？","o":["确保及时识别对安全相关的车辆部件的磨损极限","确保对安全相关的车辆部件进行功能检查","确保对环境相关的车辆部件进行功能检查"],"c":"应执行规定的检查，因为这样可以检验与环境相关的车辆部件的功能，确保所有车辆部件都经过功能检验，并及时发现与安全相关的车辆部件达到磨损极限。"},"2.7.08-208":{"q":"为什么您应在起步前始终对车辆进行检查？","o":["因为这降低了行程中抛锚的风险","因为这允许及时识别车辆部件的磨损","因为这可确保车辆适航"],"c":"对您的车辆进行出车检查，您应基于上述所有原因。因为这关系到车辆的安全性；因为行驶中发生故障的风险会降低；也因为能够及早发现车辆部件的磨损。"},"2.7.08-209":{"q":"机动车和拖车上的润滑点如何润滑？","o":["对于中央润滑系统，从储液罐润滑","对于手动润滑，使用黄油枪在相关润滑点润滑","通过定期检查发动机机油油位"],"c":"手动润滑时，通过对相应的润滑点用力按压来进行润滑。在中央润滑系统中，从储油器进行润滑也是可行且正确的。"},"2.7.08-212":{"q":"润滑车辆时应注意什么？","o":["施加润滑剂前必须清洁润滑嘴","应可见明显的油脂层","旧油脂和新油脂不得相互混合"],"c":"您应注意要能识别出明显的润滑脂挤出，并在加注润滑脂前清洁润滑嘴。"},"2.7.08-301":{"q":"拖车需要哪些维护？","o":["润滑鞍式牵引座","润滑牵引叉","润滑制动片"],"c":"您必须对挂车上所有运动部件（牵引杆和回转支承环）进行保养。"},"2.7.09-202":{"q":"车辆含载荷的最大允许宽度是多少（不包括农林业产品车辆和冷藏车）？","o":[],"c":"您的车辆（农林业用车辆和冷藏车除外）包括货物在内的宽度最多应为 2.55 m。"},"2.7.09-203":{"q":"车辆含载荷的最大允许高度是多少（不包括农林业产品车辆）？","o":[],"c":"您的车辆包括货物在内的高度（农林业用车辆除外）最多必须为 4 m。"},"2.7.09-204":{"q":"超出车辆后部的载荷必须标记。白天允许哪些方式？","o":["一面至少30 x 30 cm、由横杆撑开的鲜红色旗帜","一块至少30 x 30 cm、横向于您行驶方向悬挂的鲜红色标牌","一块橙色警告牌"],"c":"白天，对于向后突出的货物，允许使用以下标识：一块至少 30 x 30 cm、亮红色、横向于行驶方向悬挂的摆动标牌，以及一面亮红色、至少 30 x 30 cm、用横杆撑开的旗子。仅使用橙色警告标志是不够的。"},"2.7.09-208":{"q":"将装载起重机投入运行前必须采取哪些预防措施？","o":["借助支腿固定车辆防止倾斜","旋转范围内不得有任何电线","检查侧面是否绝对需要支撑"],"c":"在使用装载起重机之前，您必须确保在其回转范围内没有电力线路，并且必须使用侧向支撑以防止车辆倾翻。"},"2.7.09-209":{"q":"在道路边缘进行装卸须满足哪些条件？","o":["您不得损害交通安全","您不得无视任何“禁止停车”标志","装卸期间，您允许轻微危及交通"],"c":"如果您想在路边进行装卸作业，请注意停车限制，并注意不危及交通安全。"},"2.7.09-210":{"q":"车辆含载荷的允许高度是多少（不包括农林业产品车辆）？","o":["4.0 m","4.5 m","4.2 m"],"c":"允许的货物高度（农林业用车辆除外）为 4 m。"},"2.7.09-211":{"q":"如果您的车辆抛锚且载有必须保温运输的货物（如沥青运输），您必须采取什么措施？","o":["确保车辆对其他道路使用者安全","组织救援","确保货物保持在必要的温度"],"c":"在运输的热货物出现故障时，您应组织援助，确保货物所需的温度，并保障车辆安全。"},"2.7.09-216":{"q":"运输冷藏货物时您必须遵守哪些规则？","o":["持续监控是否遵守规定温度","如果制冷失效，采取适当措施保存货物","无特殊规则"],"c":"在冷藏货物运输中，请务必持续满足规定的温度；如果冷却系统失效，应采取适当措施来保存货物。"},"2.7.09-220":{"q":"运输某些货物时必须遵守特殊规定。这适用于哪些货物？","o":["危险货物","废弃物","活体动物"],"c":"无论对于废弃物，还是对于活动物和危险品，都必须遵守特别规定。所有答案都正确。"},"2.7.09-221":{"q":"当载荷横向超出车辆侧灯0.4 m以上时，您如何标记？","o":["通过前部白色侧灯和后部红色侧灯","通过前部红色侧反射器和后部红色侧反射器","横向距离达1 m以内不需要标记"],"c":"对于侧面超过 0.4 m、高于车辆示廓灯的超出常规的货物，您在侧面朝前的部分应使用白色灯，侧面朝后的部分应使用红色灯。"},"2.7.09-222":{"q":"关于您车辆上的载荷，您必须确保什么？","o":["遵守车辆总重量额定值","遵守车轴总重量额定值","载荷的高度、宽度、位置和固定"],"c":"装载车辆时，请注意遵守最大质量、遵守允许的轴荷，以及货物的高度、宽度、位置并固定货物。"},"2.7.09-224":{"q":"这个标志是什么意思？","o":["废弃物运输","执勤中的救护车","军车"],"c":"该标牌表示废弃物运输。"},"2.7.09-225":{"q":"您在哪里可以找到有关车辆上货物运输和固定的指导方针？","o":["在《道路交通法》（StVO）中","在公认的货物固定技术标准中","在车辆登记证第二部分中"],"c":"您可以在道路交通法规和公认的货物固定技术标准中找到相关准则。车辆登记证第二部分是不正确的。"},"2.7.09-226":{"q":"您运输包含不同尺寸和重量运输单元的“拼箱”货物。您应如何固定该载荷？","o":["通过使用隔板将装载区分成更小的段","通过使用运输单元的互锁布置","通过确保运输单元之间保持最小间距"],"c":"如果您运输大小和重量不同的运输单元，请注意用分隔元件将装载面划分成较小的区域，并通过运输单元的形状配合摆放来固定货物。"},"2.7.09-227":{"q":"您运输原木。行车路线意味着您必须经过质量差的道路。您必须做什么？","o":["定期检查货物是否固定","使我的速度适应车道和载荷","确保原木之间的摩擦力降至尽可能低的水平"],"c":"在路况较差的道路上运输原木时，您应定期检查，并根据道路状况调整行驶速度，以确保货物固定。"},"2.7.09-228":{"q":"如果预计运输该货物会产生风险，您在接收货物时必须确保什么？","o":["如果我无法避免风险，则拒绝接收该货物","使我的行驶速度适应货物状况","有条件地接收该货物"],"c":"接收货物时如发现货物损坏，您应注意：如果无法避免危险，必须拒收该货物。"},"2.7.09-229":{"q":"何时您需要覆盖装载在车辆上的散装物料？","o":["可能掉落时","可能被风吹走时","超出侧板40 cm以上时"],"c":"对于散装货物，您必须在出发前覆盖车辆，并注意遮盖物不会被风吹落。"},"2.7.09-230":{"q":"什么构成载荷固定的一部分？","o":["安全地存放和固定载荷","覆盖散装物料","为载荷安排保险"],"c":"货物固定的一部分内容：安全堆放和固定，以及对散装货物的覆盖。为货物投保是没有必要的。"},"2.7.09-231":{"q":"车辆上的这个标志表示什么类型的运输？","o":["废弃物运输","危险材料运输","军方运输"],"c":""},"2.7.10-001":{"q":"机动自行车上哪些部件必须始终处于可用状态？","o":["常亮近光灯","尾灯","后反射器"],"c":"三者都必须在道路上可见，并确保您的安全。"},"2.7.10-003":{"q":"一辆客车有32个乘客座位。车上必须有多少个急救箱？","o":["2个急救箱","1个急救箱","3个急救箱"],"c":"即将推出……"},"2.7.10-101":{"q":"一辆汽车配备冬季轮胎（M+S）。仪表盘上贴有一张写有“Mit M+S 160”的贴纸。这是什么意思？","o":["您不得以超过160 km/h的速度行驶","路面干燥时该贴纸不适用","因降雨路面潮湿时该贴纸不适用"],"c":"使用这些轮胎行驶时，不得超过贴纸上标明的速度，这些轮胎未获批用于更高的速度。如果您以更快的速度行驶，轮胎可能过热并损坏。"},"2.7.10-102":{"q":"安装冬季轮胎（M+S）时您必须记住什么？","o":["气压应比夏季轮胎略高（约0.2巴）","在干燥路面上的行驶特性可能不同","气压应比夏季轮胎低"],"c":"在没有积雪且路面干燥时，冬季轮胎的最佳气压可能有所不同。建议将气压比夏季轮胎提高约 0.2 bar。"},"2.7.10-103":{"q":"您驾驶一辆常规公交。允许的座位和站立位数量在哪里标明？","o":["在车辆登记证第一部分（机动车登记证）中","在客车内部清晰可见的地方","在铭牌上"],"c":"即将推出……"},"2.7.10-203":{"q":"在不利的道路和天气条件下，客车上必须携带哪些设备？","o":["防滑链、铲子和锄头","拖绳或牵引杆","便携式绞盘"],"c":"即将推出……"},"2.7.10-204":{"q":"您的客车允许总质量为4吨。您必须携带什么？","o":["强光手电筒","三角警告牌和警告灯","50升桶装备用燃油"],"c":"即将推出……"},"2.7.10-206":{"q":"客车上携带的灭火器必须满足哪些要求？","o":["具有A、B、C类火灾的许可","至少6 kg填充材料（灭火剂）","4 kg填充材料（灭火剂）"],"c":"即将推出……"},"2.7.10-207":{"q":"灭火器必须按什么间隔检查可用性？","o":["每12个月","每18个月","每24个月"],"c":"即将推出……"},"2.7.10-210":{"q":"客车上必须清晰标明什么？","o":["急救箱的位置","常规交通中重残人士的座位","车载工具的位置"],"c":"即将推出……"},"2.7.10-211":{"q":"起步前您必须检查紧急出口的什么？","o":["它们是否具有开启所需的装置","它们是否被行李或其他物品遮盖","它们是否按规定照明"],"c":"即将推出……"},"2.7.10-212":{"q":"一辆客车有15个乘客座位。最少需要多少个标准急救箱？","o":["1个急救箱","最多16个乘客座位数量以内不需要急救箱"],"c":"即将推出……"},"2.7.10-213":{"q":"客车（单层）上必须携带的可用灭火器最少数量是多少？","o":["共1个灭火器","从12个乘客座位起，2个灭火器"],"c":"即将推出……"},"2.7.10-214":{"q":"双层客车上所需灭火器的位置在哪里？","o":["驾驶员座位附近","上层乘客甲板再放置一个","楼下后楼梯前再放置一个"],"c":"即将推出……"},"2.7.10-215":{"q":"您在哪里可以找到车辆上携带的灭火器检查周期的详细信息？","o":["在灭火器的检查标签上","在灭火器的维护日志上","在车辆登记证第一部分的粘性印章上"],"c":"即将推出……"},"2.7.10-216":{"q":"您驾驶一辆双层客车。灭火器应位于何处？","o":["紧邻驾驶员座位","在上层","在行李舱内"],"c":"根据《道路交通许可条例》（StVZO）第 35g 条，双层巴士必须至少携带两个可用的灭火器，每个的充装质量为 6 kg。一个灭火器应放置在紧邻驾驶员座椅的位置，以便驾驶员在紧急情况下能迅速取用。第二个灭火器必须位于上层乘客层，以便在发生火灾时能在那里迅速采取行动。这种布置确保驾驶员和巴士两层上的乘客在发生火灾时都能迅速行动，从而提高所有乘员的安全。"},"2.8.01-001":{"q":"正常的试用期是多长？","o":["2年","1年","3年"],"c":"通常情况下，实习期为 2 年。但也存在可将其延长至最多 4 年的情况。"},"2.8.01-009":{"q":"您目前处于试用期，迄今为止尚未引起当局注意。如果您未遵守交通标志“停车。让行。”并因此危及其他道路使用者，可能有什么后果？","o":["被命令参加新驾驶员高级研讨班","记入道路交通违法者中央登记册","被命令重新参加驾驶执照理论考试"],"c":"不遵守交通标志“停车。让行”属于严重违规，即 A 类违规，会被记入驾驶人适格登记册。如果在实习期内发生一次 A 类违规或两次轻微违规（B 类违规），作为新驾驶员您必须参加再培训研讨班。您不必重新参加考试。"},"2.8.01-010":{"q":"在试用期参加高级研讨班应达到什么目的？","o":["对在公共道路上驾驶采取更体贴和风险意识更强的态度","提高风险意识","减少道路交通违法者中央登记册中的扣分"],"c":"在再培训研讨班上，您将学习如何分析自己的日常驾驶行为，并提高对实习期内危险情况的意识。参加研讨班不能扣减记分。这可以通过驾驶能力研讨班来完成。"},"2.8.01-011":{"q":"一名驾驶员在试用期内多次违规，当局已命令其参加高级研讨班。该新驾驶员未遵守该命令。他现在可能面临什么？","o":["吊销驾驶执照","缴纳罚款通知","在道路交通违法者中央登记册中增加扣分"],"c":"如果新驾驶员未按要求参加再培训研讨班，他将面临立即吊销驾驶执照的后果。不会额外处以罚款。此外，也不会在驾驶人适格登记册中记分。"},"2.8.01-012":{"q":"如果驾驶执照申请人在无照驾驶时被发现，他应预期什么？","o":["驾驶执照管理机构可能撤销申请审查指令","可能被命令进行测试以确定您驾驶机动车的适格性","没有后果，只要您在驾驶学校注册"],"c":"想要取得驾驶执照的人不仅必须具备必要的身体和心智条件。此外，他不得多次违反交通法规或刑事法律。否则将表明申请人不适合驾驶机动车。无证驾驶同样如此。如果一名想取得驾驶执照的人无证驾驶，主管部门可能不允许其参加考试。"},"2.8.01-013":{"q":"一名学习驾驶员在试用期内多次违规。当局已命令该驾驶员参加补充驾驶课程。该学习驾驶员未遵守此命令。他们可以预期发生什么？","o":["吊销其驾驶执照","将试用期再延长3年","被命令参加驾驶员适格性培训"],"c":"新驾驶员的实习期为 2 年。在此期间，适用罚款目录中非常严厉的处罚。如果您在实习期内发生一次 A 类违规或两次 B 类违规，将被责令参加进修研讨班（ASF）。如果您不遵守该官方命令，您的驾驶执照将被吊销。"},"2.8.01-014":{"q":"一名驾驶执照申请人在没有驾驶教练的情况下在公共道路上练习实际驾驶技能。如果警察对其进行检查，他应预期什么？","o":["刑事起诉","对其驾驶机动车适格性的审查","没有后果，只要车内有驾驶执照持有人陪同"],"c":"作为驾驶执照申请人，您不得在没有教练的情况下在公共道路上驾驶。无证驾驶属于刑事犯罪，可处以罚款或监禁。警方可以下令检查您的驾驶能力。作为驾驶执照申请人，您有可能永远无法获得驾驶执照。"},"2.8.01-201":{"q":"您用卡车运输商业货物。您必须在5年内参加的35小时进修课程的目的是什么？","o":["提高健康意识","更新我对道路货运法规的知识","获得额外的驾驶执照类别"],"c":"在从事商业货物运输时，35 小时培训课程的目的是增强健康意识并更新货运法规方面的知识。"},"2.8.01-202":{"q":"作为职业驾驶员工作需要您完成基础资格并定期参加培训计划。您在哪里可以找到有关您职业驾驶员基础资格有效期的信息？","o":["在我的驾驶执照上","在驾驶员卡上","在联邦机动车运输管理局的网站上"],"c":"您可以在驾驶执照背面找到有关期限的信息。"},"2.8.01-203":{"q":"您是一名商业客车驾驶员。您必须在5年内参加的35小时进修课程的目的是什么？","o":["提高健康意识","更新我对客运法规的知识","获得额外的驾驶执照类别"],"c":"如果您用客车从事商业载客运输，在 35 小时培训课程中，您将学习如何增强健康意识并更新客运法规方面的知识。必须强制参加。"},"2.8.01-204":{"q":"什么会导致对您作为客车驾驶员适格性的审查？","o":["我的身体能力","我的心智能力","我雇主的可靠性"],"c":""},"2.8.01-205":{"q":"何时当局可以命令客车驾驶员接受适格性评估？","o":["如果驾驶员严重违反道路交通法规","如果驾驶员犯有严重道路交通违法行为","如果有迹象表明该客车驾驶员有很高的攻击性倾向"],"c":""},"2.8.01-206":{"q":"在首次获得C类驾驶执照后，您想商业运输货物。您如何满足要求？","o":["加速基础资格","职业驾驶员培训计划","35小时高级培训课程"],"c":""},"2.8.01-207":{"q":"在首次获得D类驾驶执照后，您想商业运送乘客。您如何满足要求？","o":["加速基础资格","职业驾驶员培训计划","35小时高级培训课程"],"c":""},"2.8.01-208":{"q":"为受雇为职业驾驶员，您需要基础资格以及定期培训。相关证明如何记录？","o":["在驾驶员资格卡上","在联邦机动车运输管理局的职业驾驶员资格登记册（KBA）中","在我的驾驶执照颁发机构的网页上"],"c":"在公共道路上从事货物或旅客运输的职业驾驶员需要初始资格，之后还需定期进修培训。这些培训的有效性记录在驾驶员资格证明上。"},"2.8.01-209":{"q":"驾驶员资格卡上记录了哪些内容？","o":["基础资格","培训","颁发的驾驶执照"],"c":"在公共道路上从事货物或旅客运输的职业驾驶员需要初始资格，之后还需定期进修培训。这些培训的有效性记录在驾驶员资格证明上。"}};
